INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Ի սկզբանէ Աստուած ստեղծեց երկինքն ու երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Երկիրն անձեւ ու անկազմ էր, խաւար էր տիրում անհունի վրայ, եւ Աստծու հոգին շրջում էր ջրերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Եւ Աստուած ասաց. «Թող լոյս լինի»: Եւ լոյս եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Աստուած տեսաւ, որ լոյսը լաւ է, եւ Աստուած լոյսը բաժանեց խաւարից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Աստուած լոյսը կոչեց ցերեկ, իսկ խաւարը կոչեց գիշեր: Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր առաջին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Աստուած ասաց. «Թող տարածութիւն առաջանայ ջրերի միջեւ, եւ ջրերը թող բաժանուեն ջրերից»: Եւ եղաւ այդպէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Աստուած ստեղծեց տարածութիւնը, որով Աստուած տարածութեան ներքեւում եղած ջրերը անջրպետեց տարածութեան վրայ եղած ջրերից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Աստուած տարածութիւնը կոչեց երկինք: Աստուած տեսաւ, որ լաւ է: Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր երկրորդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Աստուած ասաց. «Թող երկնքի տակ գտնուող ջրերը հաւաքուեն մի տեղ, եւ երեւայ ցամաքը»: Եւ եղաւ այդպէս. երկնքի տակի ջրերը հաւաքուեցին մի տեղ, ու երեւաց ցամաքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Աստուած ցամաքը կոչեց երկիր, իսկ հաւաքուած ջրերը կոչեց ծով: Աստուած տեսաւ, որ լաւ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Աստուած ասաց. «Թող երկիրը իր տեսակի ու իր նմանութեան սերմը պարունակող դալար բոյս եւ իր տեսակի ու իր նմանութեան սերմը պարունակող, իր տեսակի միրգ տուող պտղաբեր ծառ աճեցնի երկրի վրայ»: Եւ եղաւ այդպէս.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'հողը ամբողջ երկրի վրայ ցանելու սերմը իր մէջ պարունակող դալար բոյս եւ իր տեսակի սերմը իր մէջ պարունակող, միրգ տուող ծառ աճեցրեց: Աստուած տեսաւ, որ լաւ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր երրորդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Աստուած ասաց. «Թող լուսատուներ լինեն երկնքի տարածութեան մէջ, որպէսզի լուսաւորեն երկիրը եւ իրարից բաժանեն ցերեկն ու գիշերը: Դրանք թող լինեն, որպէսզի ցոյց տան տարուայ եղանակները, տօնական օրերն ու տարիները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'թող լինեն, ծագեն երկնքի տարածութեան մէջ՝ երկիրը լուսաւորելու համար»: Եւ եղաւ այդպէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Աստուած ստեղծեց երկու մեծ լուսատուներ. մեծ լուսատուն՝ ցերեկն իշխելու, իսկ փոքր լուսատուն՝ գիշերն իշխելու համար, ինչպէս նաեւ աստղեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Աստուած դրանք դրեց երկնքի տարածութեան մէջ՝ երկիրը լուսաւորելու համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'ինչպէս նաեւ ցերեկուայ ու գիշերուայ վրայ իշխելու եւ լոյսն ու խաւարը իրարից բաժանելու համար: Աստուած տեսաւ, որ լաւ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր չորրորդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Աստուած ասաց. «Թող ջրերն արտադրեն կենդանութեան շունչ ունեցող զեռուններ, եւ երկրի վրայ ու երկնքի տարածութեան մէջ թող թեւաւոր թռչուններ լինեն»: Եւ եղաւ այդպէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Աստուած ստեղծեց խոշոր կէտեր, կենդանութեան շունչ ունեցող ամէն տեսակ զեռուններ, որ արտադրեցին ջրերն ըստ տեսակների, եւ ամէն տեսակ թեւաւոր թռչուններ՝ ըստ տեսակների: Աստուած տեսաւ, որ լաւ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Աստուած օրհնեց դրանց ու ասաց. «Աճեցէ՛ք, բազմացէ՛ք եւ լցրէ՛ք ծովերի ջրերը, իսկ թռչունները թող բազմանան երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր հինգերորդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Աստուած ասաց. «Թող երկիրն արտադրի չորքոտանի կենդանիներ իրենց տեսակներով, սողուններ եւ գազաններ իրենց տեսակներով»: Եւ եղաւ այդպէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Աստուած ստեղծեց երկրի գազաններն իրենց տեսակներով, անասուններն իրենց տեսակներով եւ երկրի բոլոր սողուններն իրենց տեսակներով: Աստուած տեսաւ, որ դրանք լաւ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Աստուած ասաց. «Մարդ ստեղծենք մեր կերպարանքով ու նմանութեամբ, նա թող իշխի ծովի ձկների, երկնքի թռչունների, ողջ երկրի անասունների եւ երկրի վրայ սողացող բոլոր սողունների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Եւ Աստուած մարդուն ստեղծեց իր պատկերով, Աստծու պատկերով ստեղծեց նրան, արու եւ էգ ստեղծեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Աստուած օրհնեց նրանց ու ասաց. «Աճեցէ՛ք, բազմացէ՛ք, լցրէ՛ք երկիրը, տիրեցէ՛ք դրան, իշխեցէ՛ք ծովի ձկների, երկնքի թռչունների, ողջ երկրի բոլոր անասունների ու երկրի վրայ սողացող բոլոր սողունների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Աստուած ասաց. «Ահա ձեզ տուեցի ողջ երկրի վրայ տարածուած սերմանելի բոլոր բոյսերի սերմերը եւ իրենց մէջ պտուղ սերմանելու սերմ պարունակող բոլոր ծառերը: Դրանք թող ձեզ համար սնունդ լինեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'իսկ բոլոր կանաչ խոտերը երկրի բոլոր գազանների, երկնքի բոլոր թռչունների եւ երկրի վրայ սողացող բոլոր սողունների՝ բոլոր կենդանիների համար թող լինեն կեր»: Եւ եղաւ այդպէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Աստուած տեսաւ, որ այն ամէնը, ինչ ստեղծել էր, շատ լաւ է: Եւ եղաւ երեկոյ, եւ եղաւ առաւօտ՝ օր վեցերորդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Այսպիսով Աստուած ստեղծեց երկինքն ու երկիրը եւ կարգաւորեց դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Աստուած վեցերորդ օրն աւարտեց արարչագործութիւնը եւ իր կատարած բոլոր գործերից յետոյ՝ եօթներորդ օրը, հանգստացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Աստուած օրհնեց եօթներորդ օրը եւ սրբագործեց այն, որովհետեւ այդ օրը Աստուած հանգստացաւ իր այն բոլոր գործերից, որ սկսել էր անել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Այս է երկնքի ու երկրի արարչութեան պատմութիւնը: Այն օրը, երբ Աստուած ստեղծեց երկինքն ու երկիրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'երկրի վրայ դեռ ոչ մի տունկ չէր բուսել, դեռ ոչ մի դաշտային բոյս չէր աճել, որովհետեւ Տէր Աստուած անձրեւ չէր տեղացրել երկրի վրայ, եւ մարդ չկար, որ մշակէր հողը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'բայց աղբիւր էր բխում երկրից եւ ոռոգում ողջ երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Տէր Աստուած մարդուն ստեղծեց երկրի հողից, նրա դէմքին կենդանութեան շունչ փչեց, եւ մարդն եղաւ կենդանի էակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Աստուած դրախտ տնկեց Եդեմում՝ արեւելեան կողմը, եւ այնտեղ դրեց իր ստեղծած մարդուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Տէր Աստուած երկրից բուսցրեց նաեւ ամէն տեսակի գեղեցկատեսիլ ու համեղ մրգեր տուող ծառեր, իսկ կենաց ծառը՝ բարու եւ չարի գիտութեան ծառը, տնկեց դրախտի մէջտեղում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Գետ էր բխում Եդեմից, որպէսզի ոռոգէր դրախտը, եւ այնտեղից բաժանւում էր չորս ճիւղերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Մէկի անունը Փիսոն էր: Նա է, որ պատում է ամբողջ Եւիլատ երկիրը, այնտեղ, ուր ոսկի կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Այդ երկրի ոսկին ազնիւ է: Այնտեղ կայ նաեւ սուտակ եւ դահանակ ակնաքարը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Երկրորդ գետի անունը Գեհոն է: Նա պատում է Եթովպացւոց երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Երրորդ գետը Տիգրիսն է: Սա հոսում է դէպի Ասորեստան: Չորրորդ գետը Եփրատն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Տէր Աստուած իր ստեղծած մարդուն տեղաւորեց բերկրութեան դրախտում, որպէսզի սա մշակի ու պահպանի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Տէր Աստուած պատուիրեց Ադամին ու ասաց. «Դրախտում ամէն ծառի պտուղներից կարող ես ուտել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'բայց բարու եւ չարի գիտութեան ծառից մի՛ կերէք, որովհետեւ այն օրը, երբ ուտէք դրանից, մահկանացու կը դառնաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Տէր Աստուած ասաց. «Լաւ չէ, որ մարդը միայնակ լինի: Նրա նմանութեամբ մի օգնական ստեղծենք նրա համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Տէր Աստուած ստեղծեց նաեւ դաշտային բոլոր գազաններին, երկնքի բոլոր թռչուններին եւ բերեց Ադամի մօտ, որ տեսնի, թէ Ադամը ինչ անուն կը տայ դրանց: Եւ Ադամն ինչ անուն որ տար ամէն մի կենդանուն, այն էլ կը լինէր դրա անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Ադամը բոլոր անասուններին, երկնքի բոլոր թռչուններին եւ դաշտային բոլոր գազաններին տուեց անուններ, բայց Ադամը չգտաւ իր նմանութիւնն ունեցող մի օգնական:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Տէր Աստուած թմրութիւն բերեց Ադամի վրայ, եւ սա քնեց: Աստուած հանեց նրա կողոսկրերից մէկը եւ այդ տեղը մաշկով ծածկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Տէր Աստուած Ադամից վերցրած կողոսկրից կին արարեց եւ նրան բերեց Ադամի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Ադամն ասաց. «Այժմ սա ոսկոր է իմ ոսկորներից եւ մարմին՝ իմ մարմնից: Թող սա կոչուի կին, որովհետեւ իր ամուսնուց ստեղծուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Այդ իսկ պատճառով տղամարդը թողնելով իր հօրն ու մօրը՝ պէտք է միանայ իր կնոջը, եւ երկուսը պէտք է լինեն մի մարմին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Եւ երկուսն էլ՝ Ադամն ու իր կինը, մերկ էին ու չէին ամաչում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Օձը երկրի վրայ Աստծու ստեղծած բոլոր գազաններից աւելի խորամանկ էր: Օձն ասաց կնոջը. «Ինչո՞ւ Աստուած ասաց, թէ դրախտում գտնուող բոլոր ծառերի պտուղներից չէք կարող ուտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Կինն ասաց օձին. «Դրախտի ծառերի պտուղներից կարող ենք ուտել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Սակայն դրախտի մէջտեղի ծառի պտղի համար Աստուած ասաց. «Դրանից չուտէք եւ չմօտենաք, որպէսզի չմեռնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Օձն ասաց կնոջը. «Չէք մահանայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'որովհետեւ Աստուած գիտէր, որ այն օրը, երբ դրանից ուտէք, կը բացուեն ձեր աչքերը, եւ դուք կը լինէք աստուածների նման՝ կ՚իմանաք բարին ու չարը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Կինը տեսաւ, որ ծառի պտուղը լաւ է ուտելու համար, ակնահաճոյ է եւ գրաւիչ՝ ըմբռնելու համար: Նա առաւ նրա պտղից, կերաւ եւ տուեց իր մօտ կանգնած ամուսնուն, եւ նրանք կերան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Երկուսի աչքերն էլ բացուեցին, եւ նրանք հասկացան, որ մերկ են: Նրանք թզենու տերեւներն իրար կարեցին եւ իրենց համար գոգնոց շինեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Երեկոյեան նրանք լսեցին Տէր Աստծու՝ դրախտում շրջագայելու ոտնաձայնը, եւ Ադամն ու իր կինը Տէր Աստծուց թաքնուեցին դրախտի ծառերի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Տէր Աստուած կանչեց Ադամին ու ասաց նրան. «Ո՞ւր ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Ադամը պատասխանեց. «Լսեցի քո ձայնն այստեղ՝ դրախտում, ամաչեցի, որովհետեւ մերկ էի, եւ թաքնուեցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Աստուած ասաց նրան. «Ո՞վ յայտնեց քեզ, թէ մերկ ես: Արդեօք կերա՞ր այն ծառի պտղից, որից պատուիրել էի, որ չուտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Ադամն ասաց. «Այս կինը, որ տուեցիր ինձ, նա՛ տուեց ինձ ծառի պտղից, եւ ես կերայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Տէր Աստուած ասաց կնոջը. «Այդ ի՞նչ ես արել»: Կինն ասաց. «Օձը խաբեց ինձ, եւ ես կերայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Տէր Աստուած ասաց օձին. «Քանի որ այդ բանն արեցիր, անիծեալ լինես երկրի բոլոր անասունների ու գազանների մէջ: Քո լանջի ու որովայնի վրայ սողաս, ողջ կեանքումդ հող ուտես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Թշնամութիւն պիտի դնեմ քո եւ այդ կնոջ միջեւ, քո սերնդի ու նրա սերնդի միջեւ: Նա պիտի ջախջախի քո գլուխը, իսկ դու պիտի խայթես նրա գարշապարը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Իսկ կնոջն ասաց. «Պիտի անչափ բազմացնեմ քո ցաւերն ու քո հառաչանքները: Ցաւերով երեխաներ պիտի ծնես, քո ամուսնուն պիտի ենթարկուես, եւ նա պիտի իշխի քեզ վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Աստուած Ադամին ասաց. «Քանի որ անսացիր քո կնոջ ձայնին եւ կերար այն ծառի պտղից, որի՛ց միայն քեզ պատուիրեցի չուտել, բայց կերար դրանից, թող անիծեալ լինի երկիրը քո արածի պատճառով: Տանջանքով հայթայթես քո սնունդը քո կեանքի բոլոր օրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Փուշ ու տատասկ թող աճեցնի քեզ համար երկիրը, եւ դու դաշտային բոյսերով սնուես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Քո երեսի քրտինքով ուտես հացդ մինչեւ հող դառնալդ, որից ստեղծուեցիր, որովհետեւ հող էիր եւ հող էլ կը դառնաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Եւ Ադամն իր կնոջ անունը դրեց Կեանք, որովհետեւ նա է բոլոր մարդկանց նախամայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Տէր Աստուած Ադամի ու նրա կնոջ համար կաշուից զգեստներ պատրաստեց եւ հագցրեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Տէր Աստուած ասաց. «Ահա Ադամը դարձաւ մեզ նման մէկը, նա գիտի բարին եւ չարը: Արդ, գուցէ նա ձեռքը մեկնի, քաղի կենաց ծառից, ուտի եւ անմահ դառնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Եւ Տէր Աստուած արտաքսեց նրան բերկրութեան դրախտից, որպէսզի նա մշակի այն հողը, որից ստեղծուել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Աստուած դուրս հանեց Ադամին, բնակեցրեց բերկրութեան դրախտի դիմաց եւ հրամայեց քերովբէներին ու բոցեղէն սրին շուրջանակի հսկել դէպի կենաց ծառը տանող ճանապարհները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Ադամը պառկեց իր կին Եւայի հետ, սա յղիացաւ, ծնեց Կայէնին ու ասաց. «Մարդ ծնեցի Աստծու զօրութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Դրանից յետոյ նա ծնեց նրա եղբայր Աբէլին: Աբէլը դարձաւ ոչխարների հովիւ, իսկ Կայէնը հող էր մշակում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Որոշ ժամանակ անց Կայէնը երկրի բարիքներից ընծայ բերեց Աստծուն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'իսկ Աբէլը բերեց իր ոչխարների առաջնեկներից ու գէրերից: Աստուած բարի աչքով նայեց Աբէլին ու նրա ընծաներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'իսկ Կայէնի ու նրա ընծաների վրայ ուշադրութիւն չդարձրեց: Կայէնը շատ տրտմեց, նրա դէմքը մռայլուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Տէր Աստուած Կայէնին ասաց. «Ինչո՞ւ տրտմեցիր, ինչո՞ւ մռայլուեց դէմքդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Չէ՞ որ եթէ արդար ես զոհաբերում, բայց արդար չես բաժանում, մեղանչած ես լինում: Հանգի՛ստ եղիր, դու կարող ես մեղքից ազատուել, դու ի վիճակի ես այն յաղթահարելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Կայէնն ասաց իր եղբայր Աբէլին. «Արի գնանք դաշտ»: Երբ նրանք դաշտ հասան, Կայէնը յարձակուեց իր եղբայր Աբէլի վրայ եւ սպանեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Տէր Աստուած հարցրեց Կայէնին. «Ո՞ւր է քո եղբայր Աբէլը»: Սա պատասխանեց. «Չգիտեմ, մի՞թէ ես իմ եղբօր պահակն եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Աստուած ասաց. «Այդ ի՞նչ արեցիր, քո եղբօր արեան կանչը երկրից բողոքում է ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Արդ, անիծեալ լինես երկրի վրայ, որը բացեց իր բերանը եղբօրդ՝ քո ձեռքով թափած արիւնն ընդունելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Դու պիտի մշակես հողը, բայց նա պիտի չկարողանայ քեզ տալ իր արդիւնքը: Ահ ու դողի եւ երերման մէջ պիտի լինես երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Կայէնն ասաց Աստծուն. «Գործած մեղքս մեծ է թողութեան արժանի լինելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Եթէ այսօր ինձ հանես երկրից, ես կը թաքնուեմ քեզնից, ահ ու դողի եւ երերման մէջ կը լինեմ երկրի վրայ, եւ ով հանդիպի, կը սպանի ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Տէր Աստուած ասաց նրան. «Այդպէս չէ: Նա, ով կը սպանի Կայէնին, եօթնապատիկ վրէժի կ՚արժանանայ»: Եւ Տէր Աստուած նշան դրեց Կայէնի վրայ, որպէսզի ոչ ոք, ով հանդիպի նրան, չսպանի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Կայէնը հեռացաւ Աստծու մօտից եւ բնակուեց Նայիդ երկրում՝ Եդեմի դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Կայէնը պառկեց իր կնոջ հետ, սա յղիացաւ ու ծնեց Ենոքին: Կայէնը քաղաք կառուցեց եւ քաղաքը կոչեց իր որդու՝ Ենոքի անուամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Ենոքը Գայերիդադ անուամբ որդի ունեցաւ: Գայերիդադը ծնեց Մայիէլին, Մայիէլը ծնեց Մաթուսաղային, Մաթուսաղան ծնեց Ղամէքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Ղամէքն առաւ երկու կին. մէկի անունը Ադդա էր, իսկ երկրորդի անունը՝ Սէլլա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ադդան ծնեց Յոբէլին: Սա խաշնարածների վրաններում բնակուողների նախահայրն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Նրա եղբօր անունը Յոբաղ է: Նա է յօրինել երգն ու քնարը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Սէլլան ծնեց Թոբէլին, որը պղնձի ու երկաթի հմուտ դարբին էր: Թոբէլի քոյրը Նոյեման էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Ղամէքն ասաց իր կանանց՝ Ադդային ու Սէլլային. «Լսեցէ՛ք իմ խօսքը, Ղամէքի կանայք, ակա՛նջ դրէք իմ ասածին: Ես մի երիտասարդ մարդ սպանեցի, որովհետեւ նա ինձ վիրաւորել եւ հարուածել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Եթէ սպանութեան համար Կայէնից եօթն անգամ վրէժ է պահանջւում, ապա Ղամէքից՝ եօթանասունեօթն անգամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Ադամը պառկեց իր կին Եւայի հետ, սա յղիացաւ, ծնեց որդի, նրա անունը դրեց Սէթ եւ ասաց. «Կայէնի սպանած Աբէլի փոխարէն Աստուած ինձ ուրիշ զաւակ պարգեւեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Սէթն ունեցաւ որդի եւ նրա անունը դրեց Ենոս: Նա յուսալով կանչում էր Տէր Աստծու անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Սա մարդկանց ազգաբանութեան այն օրերի պատմութիւնն է, երբ Աստուած ստեղծեց Ադամին: Ըստ Աստծու պատկերի ստեղծեց նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'արու եւ էգ ստեղծեց նրանց, օրհնեց եւ ադամ, այսինքն՝ մարդ անուանեց նրանց այն օրը, երբ ստեղծեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Ադամը երկու հարիւր երեսուն տարեկանին իր նման ու իր կերպարանքով որդի ծնեց եւ անունը դրեց Սէթ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Սէթին ծնելուց յետոյ Ադամն ապրեց եւս եօթը հարիւր տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Ադամը մեռաւ՝ ապրելով ինը հարիւր երեսուն տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Սէթը երկու հարիւր հինգ տարեկանին ծնեց Ենոսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Ենոսին ծնելուց յետոյ Սէթն ապրեց եւս եօթը հարիւր եօթը տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Սէթը մեռաւ՝ ապրելով ինը հարիւր տասներկու տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Ենոսը հարիւր իննսուն տարեկանին ծնեց Կայնանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Կայնանին ծնելուց յետոյ Ենոսն ապրեց եւս եօթը հարիւր տասնհինգ տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Ենոսը մեռաւ՝ ապրելով ինը հարիւր հինգ տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Կայնանը հարիւր եօթանասուն տարեկանին ծնեց Մաղաղայէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Մաղաղայէլին ծնելուց յետոյ Կայնանն ապրեց եւս եօթը հարիւր քառասուն տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Կայնանը մեռաւ՝ ապրելով ինը հարիւր տասը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Մաղաղայէլը հարիւր վաթսունհինգ տարեկանին ծնեց Յարէդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Յարէդին ծնելուց յետոյ Մաղաղայէլն ապրեց եւս եօթը հարիւր երեսուն տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Մաղաղայէլը մեռաւ՝ ապրելով ութ հարիւր իննսունհինգ տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Յարէդը հարիւր վաթսուներկու տարեկանին ծնեց Ենոքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Ենոքին ծնելուց յետոյ Յարէդն ապրեց եւս ութ հարիւր տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Յարէդը մեռաւ՝ ապրելով ինը հարիւր վաթսուներկու տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Ենոքը հարիւր վաթսունհինգ տարեկանին ծնեց Մաթուսաղային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Ենոքը Մաթուսաղային ծնելուց յետոյ սիրելի եղաւ Աստծուն երկու հարիւր տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Ենոքը ապրեց երեք հարիւր վաթսունհինգ տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Ենոքը սիրելի եղաւ Աստծուն: Նա անյայտացաւ, որովհետեւ Աստուած նրան տարաւ իր մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Մաթուսաղան հարիւր ութսունեօթը տարեկանին ծնեց Ղամէքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Ղամէքին ծնելուց յետոյ Մաթուսաղան ապրեց եւս ութ հարիւր երկու տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Մաթուսաղան մեռաւ՝ ապրելով ինը հարիւր վաթսունինը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Ղամէքը հարիւր ութսունութ տարեկանին ծնեց որդի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Նա նրա անունը դրեց Նոյ: Ղամէքն ասաց. «Սա մեզ կը հանգստացնի մեր գործերից, մեր ձեռքերի ցաւերից եւ այն երկրից, որ անիծեց Տէր Աստուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Նոյին ծնելուց յետոյ Ղամէքն ապրեց եւս հինգ հարիւր վաթսունհինգ տարի եւ ծնեց ուստրեր ու դուստրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Ղամէքը մեռաւ՝ ապրելով եօթը հարիւր յիսուներեք տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Նոյը հինգ հարիւր տարեկանին ծնեց երեք որդի. Սէմին, Քամին եւ Յաբէթին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Երբ սկսեցին մարդիկ բազմանալ երկրի վրայ եւ դուստրեր ունեցան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Աստծու որդիները, տեսնելով որ մարդկանց դուստրերը գեղեցիկ են, կին առան նրանց, ում ընտրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Տէր Աստուած ասաց. «Իմ ոգին յաւիտեան թող չմնայ այդ մարդկանց մէջ, որովհետեւ նրանք մարմնաւոր են: Նրանց կեանքի սահմանը թող լինի հարիւր քսան տարի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Այդ օրերին հսկաներ էին ապրում երկրի վրայ: Երբ Աստծու որդիները մարդկանց դուստրերի հետ պառկեցին, իրենց համար որդիներ ծնեցին: Նրանք այն հսկաներն էին, որոնք հնուց ի վեր անուանի մարդիկ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Երբ Տէր Աստուած տեսաւ, որ մարդկանց չարագործութիւնները բազմանում են երկրի վրայ, եւ ամէն ոք իր մտքում ամէն օր խնամքով չարագործութիւններ է նիւթում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'զղջաց Աստուած, որ մարդ է ստեղծել երկրի վրայ, եւ տրտմեց իր հոգու խորքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Տէր Աստուած ասաց. «Երկրի երեսից վերացնելու եմ իմ ստեղծած ամէն մի էակ՝ մարդուց մինչեւ անասուն եւ սողուններից մինչեւ երկնքի թռչունները, որովհետեւ զղջացել եմ, որ ստեղծել եմ նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Նոյը, սակայն, արժանացել էր Տէր Աստծու սիրուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Այս է Նոյի պատմութիւնը: Նոյը կատարեալ եւ արդար մարդ էր իր ազգի մէջ: Նոյը սիրելի եղաւ Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Նոյը ծնեց երեք որդի. Սէմին, Քամին, Յաբէթին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Ապականուեց երկիրն Աստծու առաջ, աշխարհը լցուեց անարդարութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Տէր Աստուած տեսաւ, որ երկիրն ապականուած է, որովհետեւ երկրի վրայ ամէն էակ ապականել էր իր ճանապարհը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Տէր Աստուած ասաց Նոյին. «Բոլոր մարդկանց վերջը հասել է, որովհետեւ երկիրը լցուել է նրանց անիրաւութիւններով: Ես կ՚ոչնչացնեմ նրանց ու երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Արդ, դու քեզ համար քառակուսի փայտից տապան կը շինես: Տապանը բաժանմունքներով կը պատրաստես եւ ներսից ու դրսից կուպրով կը ծեփես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Տապանն այսպէս կը շինես. թող երեք հարիւր կանգուն լինի տապանի երկարութիւնը, յիսուն կանգուն՝ լայնութիւնը, եւ երեսուն կանգուն՝ բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Տապանն աստիճանաբար նեղացնելով կը շինես, այնպէս, որ նրա ծածկը մի կանգուն լինի: Տապանի դուռը կողքից կ՚անես. ներքնայարկ, միջնայարկ ու վերնայարկ թող ունենայ տապանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Իսկ ես, ահա, ջրով կը հեղեղեմ երկիրը՝ ոչնչացնելու համար երկնքի տակ գտնուող ամէն մի շնչաւոր էակ. եւ այն ամէնը, ինչ կայ երկրի վրայ, կ՚ոչնչանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Ես իմ ուխտը կը հաստատեմ քեզ հետ, եւ տապան կը մտնես դու, քեզ հետ նաեւ՝ քո որդիները, քո կինը եւ քո որդիների կանայք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Բոլոր կենդանիներից, բոլոր գազաններից ու բոլոր էակներից երկու-երկու կը մտցնես տապան, որ նրանք կերակրուեն քեզ հետ: Թող դրանք արու եւ էգ լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Ամէն տեսակ թռչուններից, ամէն տեսակ կենդանիներից, երկրի ամէն տեսակ սողուններից՝ բոլորից երկու-երկու, արու եւ էգ, թող մտնեն քեզ հետ, որ կերակրուեն քեզ հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Եւ դու կը վերցնես բոլոր այն ուտելիքներից, որոնցով պիտի սնուէք: Դրանք կը կուտակես քեզ մօտ, որպէսզի քեզ ու նրանց համար կերակուր լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Եւ Նոյն արեց այն ամէնը, ինչ պատուիրեց նրան Տէր Աստուած: Նա այդպէս էլ արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Տէր Աստուած ասաց Նոյին. «Դու եւ քո ողջ ընտանիքը մտէ՛ք տապան, որովհետեւ մարդկային ցեղի մէջ միայն քե՛զ գտայ արդար իմ հանդէպ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Անպիղծ բոլոր կենդանիներից եօթը-եօթը՝ արու եւ էգ, կը մտցնես քեզ հետ, իսկ պիղծ բոլոր կենդանիներից երկու-երկու՝ արու եւ էգ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'նաեւ երկնքի անպիղծ թռչուններից եօթը-եօթը՝ արու եւ էգ, իսկ պիղծ թռչուններից երկու-երկու՝ արու եւ էգ, որ սերունդ պահպանուի ողջ երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Եօթը օր յետոյ ես քառասուն օր ու քառասուն գիշեր անձրեւ պիտի թափեմ երկրի վրայ եւ երկրի երեսից պիտի ջնջեմ իմ ստեղծած ամէն մի էակ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Նոյն արեց այն ամէնը, ինչ պատուիրեց Տէր Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Նոյը վեց հարիւր տարեկան էր, երբ ջրհեղեղ եղաւ երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Ջրհեղեղի պատճառով Նոյի հետ տապան մտան նրա որդիները, նրա կինն ու նրա որդիների կանայք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Անպիղծ թռչուններից ու պիղծ թռչուններից, երկրի վրայ սողացող բոլոր սողուններից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'երկու-երկու՝ արու եւ էգ, Նոյի հետ մտան տապան, ինչպէս պատուիրել էր նրան Տէր Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Եօթը օր յետոյ երկրի վրայ ջրհեղեղ եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Նոյի կեանքի վեցհարիւրերորդ տարում, երկրորդ ամսի քսանեօթին ժայթքեցին ստորգետնեայ բազում աղբիւրներ, բացուեցին երկնքի ջրվէժները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Երկրի վրայ անձրեւ թափուեց քառասուն օր ու քառասուն գիշեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Այդ օրը Նոյի հետ տապան մտան Սէմը, Քամը, Յաբէթը՝ Նոյի որդիները, Նոյի կինը եւ նրա որդիների երեք կանայք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Նրանք եւ ամէն տեսակ գազան, ամէն տեսակ անասուն, երկրի վրայ սողացող ամէն տեսակ սողուն եւ ամէն տեսակ թռչուն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'մտան տապան՝ Նոյի մօտ, երկու-երկու բոլոր այն էակներից, որոնց մէջ կենդանութեան շունչ կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Տապան մտնող էակները արու եւ էգ էին, ինչպէս պատուիրել էր Աստուած Նոյին: Տէր Աստուած նրա ետեւից փակեց տապանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Երկրի վրայ քառասուն օր ու քառասուն գիշեր ջրհեղեղ եղաւ: Յորդացաւ ջուրն ու բարձրացրեց տապանը, եւ տապանը կտրուեց գետնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Ջուրն աւելի ու աւելի վարարեց, ողողեց երկիրը, եւ տապանը լողաց ջրերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Ջուրն այնքան սաստկացաւ երկրի վրայ, որ ծածկեց երկնքի տակ գտնուող բոլոր բարձրաբերձ լեռները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Տասնհինգ կանգուն աւելի վեր բարձրացաւ ջուրը եւ ծածկեց բոլոր լեռները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Մեռան երկրի վրայ շարժուող բոլոր կենդանի էակները՝ թռչունները, անասուններն ու գազանները, երկրի վրայ սողացող բոլոր սողուններն ու բոլոր մարդիկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Ցամաքի վրայ եղած ամէն բան, որ կենդանի շունչ ունէր իր ռունգերի մէջ, ոչնչացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Աստուած բնաջնջեց երկրի երեսին գտնուող ամէն մի էակ՝ մարդուց մինչեւ անասուն, սողուններից մինչեւ երկնքի թռչունները: Նրանք վերացան երկրի երեսից: Կենդանի մնաց միայն Նոյը, նաեւ նրանք, որ նրա հետ տապանում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Ջուրը հարիւր յիսուն օր ողողեց երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Աստուած յիշեց Նոյին, նրա հետ տապանում գտնուող բոլոր գազաններին, բոլոր անասուններին ու բոլոր թռչուններին: Աստուած հողմ բարձրացրեց երկրի վրայ, եւ անձրեւը դադարեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Փակուեցին ստորգետնեայ աղբիւրներն ու երկնքի սահանքները, դադարեց նաեւ երկնքից թափուող անձրեւը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Ջուրը գնալով իջնում, քաշւում էր երկրի վրայից, եւ հարիւր յիսուն օր անց այն նուազեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Եօթներորդ ամսի քսանեօթին տապանը նստեց Արարատ լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Ջուրը մինչեւ տասներորդ ամիսը քաշւում էր, նուազում: Տասնմէկերորդ ամսի առաջին օրը երեւացին լեռների գագաթները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Քառասուն օր յետոյ Նոյը բացեց իր կառուցած տապանի պատուհանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Նա արձակեց մի ագռաւ, որը գնաց, բայց չվերադարձաւ, մինչեւ որ ջուրը ցամաքէր երկրի վրայից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Յետոյ նա արձակեց մի աղաւնի՝ տեսնելու, թէ ջրերը քաշուե՞լ են երկրի երեսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Աղաւնին իր ոտքը դնելու տեղ չգտնելով՝ վերադարձաւ նրա մօտ՝ տապան, որովհետեւ ջուրը դեռ ծածկել էր ողջ երկիրը: Նոյը երկարեց ձեռքը, բռնեց նրան եւ բերեց իր մօտ՝ տապան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Նա սպասեց եւս եօթը օր ու տապանից դարձեալ արձակեց աղաւնուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Աղաւնին նրա մօտ վերադարձաւ երեկոյեան: Նրա կտուցին ձիթենու մի շիւղ կար: Նոյը դրանից հասկացաւ, որ ջրերը քաշուել են երկրի վրայից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Նոյն սպասեց եւս եօթը օր ու նորից արձակեց աղաւնուն, որն այլեւս նրա մօտ չվերադարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Նոյի կեանքի վեցհարիւրմէկերորդ տարում, առաջին ամսի առաջին օրը ջրերը քաշուեցին երկրի վրայից: Նոյը բացեց իր կառուցած տապանի ծածկը եւ տեսաւ, որ ջուրը քաշուել է երկրի երեսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Երկրորդ ամսի քսանեօթներորդ օրը երկիրը ցամաքեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Տէր Աստուած Նոյին ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '«Դո՛ւրս եկէք այդ տապանից դու, քո կինը, քո որդիները եւ քո որդիների կանայք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'նաեւ քեզ հետ եղող բոլոր գազանները, բոլոր էակները՝ թռչուններից մինչեւ անասունները: Դո՛ւրս հանիր քեզ հետ նաեւ երկրի վրայ սողացող բոլոր սողուններին, նրանք թող սողան երկրի վրայ: Աճեցէ՛ք եւ բազմացէ՛ք երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Դուրս ելան Նոյը, նրա հետ նաեւ իր կինը, իր որդիներն ու իր որդիների կանայք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Երկրի բոլոր գազանները, բոլոր սողուններն ու բոլոր թռչունները՝ իրենց տեսակներով, դուրս ելան տապանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Նոյը զոհասեղան շինեց Աստծու համար: Նա առաւ բոլոր տեսակի անպիղծ անասուններից, բոլոր տեսակի անպիղծ թռչուններից եւ ողջակիզեց զոհասեղանի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Եւ Տէր Աստուած հոտոտեց անուշ բոյրը: Տէր Աստուած իր մտքում ասաց. «Մարդկանց չար արարքների համար ես երկիրն այլեւս չեմ անիծի, որովհետեւ մարդկանց միտքը մանկուց չարի ծառայութեան մէջ է: Ես այլեւս ոչ մի կենդանի էակի չեմ պատուհասի, ինչպէս արեցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Այսուհետեւ, քանի դեռ կայ երկիրը, թող չդադարեն սերմն ու հունձը, ցուրտն ու տօթը, ամառն ու գարունը, ցերեկն ու գիշերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Աստուած օրհնելով Նոյին ու նրա որդիներին՝ ասաց նրանց. «Աճեցէ՛ք, բազմացէ՛ք, լցրէ՛ք երկիրն ու տիրեցէ՛ք դրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Ձեր ահն ու երկիւղը թող լինի երկրի բոլոր գազանների, երկնքի բոլոր թռչունների, երկրի բոլոր զեռունների եւ ծովի բոլոր ձկների վրայ, որ ենթարկել եմ ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Ամէն մի կենդանի զեռուն թող կերակուր լինի ձեզ, ինչպէս խոտն ու բանջարն եմ տուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Կենսատու արիւն պարունակող միս չուտէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'քանզի ես էլ ձեր կենսատու արիւնը կը պահանջեմ, բոլոր գազանների, ինչպէս նաեւ մարդու միջոցով կը պահանջեմ այն: Մարդու միջոցով պիտի պահանջեմ իր եղբօր հոգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Ով թափի մարդու արիւնը, նրա արեան փոխարէն թող թափուի իր արիւնը, որովհետեւ Աստծու պատկերով եմ ստեղծել ես մարդուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Իսկ դուք աճեցէ՛ք, բազմացէ՛ք, լցրէ՛ք երկիրը եւ բազմացէ՛ք դրա վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Տէր Աստուած, դիմելով Նոյին ու նրա որդիներին, որոնք նրա հետ էին, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '«Ահա ես ուխտ եմ դնում ձեզ հետ, ձեզնից յետոյ եկող ձեր սերունդների հետ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'ձեզ հետ եղող բոլոր կենդանի էակների հետ՝ թռչունների, անասունների, երկրի բոլոր գազանների, այդ տապանից դուրս եկած բոլորի եւ երկրի բոլոր կենդանիների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ես ուխտ եմ դնում ձեզ հետ. այլեւս ոչ մի էակ չի մեռնի ջրհեղեղից, ողջ երկիրը ոչնչացնող ջրհեղեղ չի լինի այլեւս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Տէր Աստուած ասաց Նոյին. «Իմ ու ձեր միջեւ, ձեզ հետ եղող ամէն կենդանի էակի միջեւ գալիք բոլոր սերունդների համար իմ հաստատած ուխտի նշանն այս է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'իմ ծիածանը կը կապեմ ամպերի մէջ: Եւ դա թող լինի իմ ու ողջ երկրի միջեւ յաւիտենական ուխտի նշանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Երբ երկրի վրայ ամպեր կուտակեմ, իմ ծիածանը թող երեւայ ամպերի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Այնժամ ես կը յիշեմ իմ ուխտը, որ հաստատել եմ իմ ու ձեր միջեւ եւ շնչաւոր բոլոր էակերի միջեւ: Այլեւս ջրհեղեղ չի լինի, որպէսզի բոլոր էակները չոչնչանան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Թող իմ ծիածանը լինի ամպերի մէջ, որպէսզի ես տեսնեմ այն եւ յիշեմ իմ ու երկրի վրայ գտնուող բոլոր շնչաւոր էակների միջեւ իմ հաստատած յաւիտենական ուխտը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Տէր Աստուած ասաց Նոյին. «Այս է նշանն այն ուխտի, որ հաստատեցի իմ ու ձեր միջեւ եւ երկրի վրայ գտնուող բոլոր էակների միջեւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Նոյի՝ տապանից դուրս եկած որդիներն էին Սէմը, Քամը եւ Յաբէթը: Քամը Քանանի հայրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Այս երեքն էին Նոյի որդիները, եւ ժողովուրդները սրանցից սերուելով տարածուեցին ողջ երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Նոյը՝ հողագործ այդ մարդը, առաջինն էր, որ հող մշակեց եւ այգի տնկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Նա խմեց դրա գինուց, հարբեց ու մերկացաւ իր տան մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Քամը՝ Քանանի հայրը, տեսաւ իր հօր մերկութիւնն ու դուրս գնալով՝ այդ մասին պատմեց իր երկու եղբայրներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Սէմն ու Յաբէթը, երկուսն էլ, հագուստներ առան իրենց ուսերին եւ, յետ-յետ գնալով, ծածկեցին իրենց հօր մերկութիւնը: Նրանք մէջքով էին կանգնած, այնպէս որ իրենց հօր մերկութիւնը չտեսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Նոյը սթափուելով գինովութիւնից՝ իմացաւ, թէ ինչ է արել իր նկատմամբ իր կրտսեր որդին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'եւ ասաց. «Անիծեալ լինի ստրուկ Քանանը եւ իր եղբայրների ծառան թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Նա աւելացրեց. «Օրհնեալ լինի Տէր Աստուած՝ Սէմի Աստուածը, իսկ Քանանը թող լինի նրա ծառան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Աստուած թող բարգաւաճեցնի Յաբէթին, նա թող բնակուի Սէմի տանը, իսկ Քանանը թող լինի նրա ծառան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Ջրհեղեղից յետոյ Նոյը ապրեց երեք հարիւր յիսուն տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Նոյը ինը հարիւր յիսուն տարի ապրելուց յետոյ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Սրանք են Նոյի որդիների՝ Սէմի, Քամի, Յաբէթի սերունդները. ջրհեղեղից յետոյ որդիներ ծնուեցին նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Յաբէթի որդիներն են Գամերը, Մագոգը, Մադան, Յաւանը, Ելիսան, Թոբէլը, Մոսոքը եւ Թիրասը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Գամերի որդիներն են Ասքանազը, Րիփաթը եւ Թորգոման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Յաւանի որդիներն են Ելիսան ու Թարսիսը, կիտացիներն ու ռոդացիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Սրանցից է, որ բաժանուեցին եւ ծովեզերքում բնակութիւն հաստատեցին ժողովուրդները՝ իւրաքանչիւրն ըստ իր երկրում ունեցած լեզուների եւ տոհմերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Քամի որդիներն են Քուշն ու Մեստրեմը, Փուդն ու Քանանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Քուշի որդիներն են Սաբան, Եւիլան, Սաբաթան, Ռեգման եւ Սաբակաթան: Ռեգմայի որդիներն են Սաբան եւ Յուդադանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Քուշը ծնեց Նեբրոթին: Նա առաջին հսկան էր երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Նա քաջ որսորդ էր Աստծու առաջ: Դրա համար էլ ասոյթ դարձաւ. «Նեբրոթի պէս քաջ է Տէր Աստծու առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Նրա թագաւորութիւնն սկիզբ առաւ Բաբելոնում եւ ընդգրկում էր Որէքը, Աքադն ու Քաղանէն, որոնք գտնւում էին Սենաար երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Նեբրոթն ելաւ այդ երկրից ու գնաց Ասուր, կառուցեց Նինուէն, Ռոբոթ քաղաքը, Քաղանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'ինչպէս նաեւ Նինուէի ու Քաղանի միջեւ գտնուող Դասեմանը: Սա մեծ քաղաք էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Մեստրեմը սերեց լուդիիմացիներին, սենիիմացիներին, սաղբիիմացիներին, հեփթաղիիմացիներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'պատրոսոնիիմացիներին եւ քասղոնիիմացիներին, որոնցից սկիզբ առան փղշտացիներն ու կափթոորիմացիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Քանանը ծնունդ տուեց Սիդոնին՝ իր անդրանիկ որդուն, քետացիներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'յեբուսացիներին, ամորհացիներին, գերգեսացիներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'խեւացիներին, արուակացիներին, ամինացիներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'արադիոնացիներին, սամարացիներին եւ ամաթացիներին: Դրանից յետոյ սփռուեցին քանանացիների ցեղերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Քանանացիների սահմանները ձգուեցին Սիդոնից մինչեւ Գերարա, որ Գազայի մօտ էր, մինչեւ Սոդոմ եւ Գոմոր, Ադամայից ու Սեբոյիմից մինչեւ Լասա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ահա սրանք են Քամի որդիներն ըստ իրենց ցեղերի, ըստ իրենց լեզուների, իրենց երկրների ու իրենց տոհմերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Յաբէթի երէց եղբայրը՝ Սէմը, որ Եբերի բոլոր որդիների նախահայրն էր, նոյնպէս ծնեց որդիներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Սեմի որդիներն են Ելամը, Ասուրը, Արփաքսադը, Լուդն ու Արամը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Արամի որդիներն են Հուսը, Եմուղը, Գադերն ու Մոսոքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Արփաքսադը ծնեց Կայնանին, Կայնանը ծնեց Սաղային, իսկ Սաղան ծնեց Եբերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Եբերը ծնեց երկու որդի. մէկի անունը Փաղէկ էր, որովհետեւ նրա օրօք ցրուեցին մարդիկ, իսկ եղբօր անունը Յեկտան էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Յեկտանը ծնեց Էլմոդադին, Սալէքին, Ասարմոդին, Յարաքին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Յոդորամին, Եզէլին, Դեկլային,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Գեբաղին, Աբիմէէլին, Սաբէիին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ուփիրին, Եւիլային ու Յոբաբին: Սրանք բոլորը Յեկտանի որդիներն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Նրանք բնակութիւն հաստատեցին Մասէից մինչեւ Սոփերա, որ գտնւում էր արեւելեան լերան կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ահա սրանք են Սէմի որդիներն ըստ իրենց ցեղերի, ըստ իրենց լեզուների, իրենց երկրի ու տոհմերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Այս է Նոյի որդիների ցեղերի ծննդաբանութիւնն ըստ իրենց տոհմերի: Ջրհեղեղից յետոյ աշխարհով մէկ սփռուած ժողովուրդները սրանցից են առաջացել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Այն ժամանակ ողջ երկիրը մէկ լեզուով, մէկ բարբառով էր խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Արեւելքից տեղաշարժուելու ժամանակ նրանք Սենաար երկրում մի դաշտ գտան եւ բնակուեցին այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Նրանք միմեանց դիմելով՝ ասացին. «Եկէք աղիւս շինենք ու այն թրծենք կրակով»: Աղիւսը նրանց համար ծառայեց իբրեւ քար, իսկ կուպրը՝ իբրեւ շաղախ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Նրանք ասացին. «Եկէք մեզ համար քաղաք կառուցենք եւ աշտարակ, որի գագաթը հասնի մինչեւ երկինք: Համբաւ ձեռք բերենք ողջ աշխարհով մէկ սփռուելուց առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Տէրն իջաւ, որպէսզի տեսնի այն քաղաքն ու աշտարակը, որ կառուցում էին մարդկանց որդիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Տէրն ասաց. «Սրանք մէկ ժողովուրդ են, ունեն մէկ լեզու եւ սկսել են այդ գործն անել: Արդ, ոչինչ չի խանգարում նրանց, որ կառուցեն այն, ինչ կամենում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Արի իջնենք եւ խառնենք նրանց լեզուն այնպէս, որ ոչ մէկը չհասկանայ իր ընկերոջ ասածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Տէր Աստուած այնտեղից նրանց սփռեց աշխարհով մէկ, եւ նրանք դադարեցին քաղաքն ու աշտարակը կառուցելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Դրա համար այն կոչուեց Խառնակութիւն (Բաբելոն), որովհետեւ Տէր Աստուած այնտեղ խառնեց ամբողջ երկրի բնակիչների լեզուները եւ այնտեղից նրանց սփռեց ողջ աշխարհով մէկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Սէմի սերունդները սրանք են. Սէմը հարիւրամեայ հասակում, ջրհեղեղից երկու տարի յետոյ ծնեց Արփաքսադին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Սէմն Արփաքսադին ծնելուց յետոյ ապրեց եւս հինգ հարիւր տարի: Նա ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Արփաքսադը հարիւր երեսունհինգ տարեկան հասակում ծնեց Կայնանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Արփաքսադը Կայնանին ծնելուց յետոյ ապրեց եւս չորս հարիւր տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ: Կայնանը հարիւր երեսուն տարեկան հասակում ծնեց Սաղային: Կայնանը Սաղային ծնելուց յետոյ ապրեց եւս երեք հարիւր երեսուն տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Սաղան հարիւր երեսուն տարեկան հասակում ծնեց Եբերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Սաղան Եբերին ծնելուց յետոյ ապրեց եւս երեք հարիւր երեսուն տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Եբերը հարիւր երեսունչորս տարեկան հասակում ծնեց Փաղէկին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Եբերը Փաղէկին ծնելուց յետոյ ապրեց եւս երկու հարիւր եօթանասուն տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Փաղէկը հարիւր երեսունչորս տարեկան հասակում ծնեց Ռագաւին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Փաղէկը Ռագաւին ծնելուց յետոյ ապրեց եւս երկու հարիւր ինը տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Ռագաւը հարիւր երեսուներկու տարեկան հասակում ծնեց Սերուքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Ռագաւը Սերուքին ծնելուց յետոյ ապրեց եւս երկու հարիւր եօթը տարի, ծնեց ուստրեր ու դուստրեր եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Սերուքը հարիւր երեսուն տարեկան հասակում ծնեց Նաքորին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Սերուքը Նաքորին ծնելուց յետոյ ապրեց եւս երկու հարիւր տարի, ծնեց տղաներ ու աղջիկներ եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Նաքորը եօթանասունինը տարեկան հասակում ծնեց Թարային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Նաքորը Թարային ծնելուց յետոյ ապրեց եւս հարիւր քսաներկու տարի, ծնեց տղաներ ու աղջիկներ եւ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Թարան եօթանասուն տարեկան հասակում ծնեց Աբրամին, Նաքորին եւ Առանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Թարայի սերունդը այս է. Թարան ծնեց Աբրամին, Նաքորին ու Առանին, իսկ Առանը ծնեց Ղովտին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Առանը մեռաւ իր հայր Թարայի կենդանութեան օրօք, իր ծննդավայրում՝ Քաղդէացւոց երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Աբրամն ու Նաքորը ամուսնացան: Աբրամի կնոջ անունը Սարա էր, իսկ Նաքորի կնոջ անունը՝ Մեղքա: Սա Առանի՝ Մեղքայի եւ Յէսքայի հօր դուստրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Սարան ամուլ էր՝ երեխայ չէր ունենում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Թարան իր որդի Աբրամին, իր որդի Նաքորին, իր որդի Առանի որդի Ղովտին ու իր հարսին՝ իր որդի Աբրամի կնոջը, Քաղդէացւոց երկրից առաւ տարաւ Քանանացւոց երկիրը: Նրանք հասան Խառան ու բնակուեցին այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Խառանում Թարան դարձաւ երկու հարիւր հինգ տարեկան. Թարան Խառանում էլ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Աստուած ասաց Աբրամին. «Հեռացի՛ր քո երկրից, քո ցեղից ու քո հօր տնից եւ գնա՛ այն երկիրը, որ ցոյց կը տամ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Քեզ մեծ ցեղի նախահայր պիտի դարձնեմ, պիտի օրհնեմ քեզ, պիտի փառաւորեմ քո անունը, եւ դու օրհնեալ պիտի լինես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Պիտի օրհնեմ քեզ օրհնողներին, իսկ քեզ անիծողներին պիտի անիծեմ: Քեզնով պիտի օրհնուեն աշխարհի բոլոր ժողովուրդները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Եւ Աբրամը գնաց, ինչպէս ասել էր նրան Աստուած: Նրա հետ գնաց նաեւ Ղովտը: Աբրամը եօթանասունհինգ տարեկան էր, երբ հեռացաւ Խառանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Աբրամն առաւ իր կին Սարային, իր եղբօրորդի Ղովտին, Խառանում ձեռք բերած ողջ ունեցուածքն ու ստրուկներին: Նրանք ճանապարհ ընկան, որ գնան Քանանացւոց երկիրը: Նրանք եկան Քանանի երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Աբրամը կտրեց անցաւ երկիրն իր երկարութեամբ մինչեւ Սիւքէմ վայրը՝ Բարձր կաղնին: Այդ ժամանակ, սակայն, քանանացիներն էին բնակւում այդ երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Տէրը երեւաց Աբրամին եւ ասաց նրան. «Քո յետնորդներին եմ տալու այս երկիրը»: Աբրամն իրեն երեւացած Տիրոջ համար զոհասեղան շինեց այդտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Այդտեղից նա գնաց Բեթէլի արեւելեան կողմում գտնուող լեռը: Այնտեղ՝ Բեթէլում, խփեց իր վրանը, ծովի դիմաց, իսկ արեւելքում Անգէն էր: Այնտեղ Տիրոջ համար զոհասեղան շինեց ու կանչեց Աստծու անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Աբրամը հեռացաւ, գնաց ու բնակուեց անապատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Երբ սով եղաւ երկրում, Աբրամն իջաւ Եգիպտոս, որ այնտեղ ապրի պանդխտութեան մէջ, քանի որ սովը սաստկացել էր երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Երբ Աբրամը մօտեցաւ Եգիպտոսին, իր կին Սարային ասաց. «Գիտեմ, որ դու գեղեցիկ կին ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Արդ, եթէ պատահի, որ եգիպտացիները տեսնեն քեզ եւ ասեն՝ սա նրա կինն է, ու սպանեն ինձ, իսկ քեզ ողջ թողնեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'կ՚ասես, թէ՝ նրա քոյրն եմ, որպէսզի քո շնորհիւ ես չտուժեմ եւ քո շնորհիւ կենդանի մնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Երբ Աբրամը մտաւ Եգիպտոս, եգիպտացիները տեսան, որ նրա կինը շատ գեղեցիկ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Տեսան նրան նաեւ փարաւոնի իշխանները, գովեցին նրան փարաւոնի առաջ ու նրան տարան փարաւոնի պալատը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Սարայի համար նրանք լաւ վերաբերմունք ցոյց տուեցին Աբրամին: Եւ նա ոչխարների, կովերի, էշերի, ծառաների եւ աղախինների, ջորիների եւ ուղտերի տէր դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Աբրամի կին Սարայի պատճառով Աստուած փարաւոնին ու նրա ընտանիքի անդամներին պատժեց մեծամեծ ու դաժան պատուհասներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Փարաւոնը կանչեց Աբրամին ու ասաց նրան. «Այս ի՞նչ փորձանք բերեցիր իմ գլխին, ինչո՞ւ չյայտնեցիր, թէ նա քո կինն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Ինչո՞ւ ասացիր, թէ «Իմ քոյրն է», ես էլ նրան կնութեան առայ: Արդ, ահա քո կինը քո առաջ է, ա՛ռ նրան ու հեռացի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Փարաւոնն իր մարդկանց պատուիրեց, որ Աբրամին, իր ունեցուածքով, նրա կնոջը, ինչպէս նաեւ Ղովտին ճանապարհ դնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Եգիպտոսից Աբրամն ելաւ գնաց անապատ, ինքը՝ իր ամբողջ ունեցուածքով, իր կինը եւ Ղովտն էլ նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Աբրամը շատ հարուստ էր անասուններով, արծաթով եւ ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Նա իր հասած տեղից՝ անապատից, գնաց Բեթէլ, որտեղ նախապէս նրա վրանն էր խփած, Բեթէլի եւ Անգէի միջեւ գտնուող վայրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'ուր սկզբնապէս նա զոհասեղան էր կառուցել: Այդտեղ Աբրամը կանչեց Տէր Աստծու անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Աբրամի հետ գնացող Ղովտը նոյնպէս ունէր արջառներ, ոչխարներ, անասուններ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'բայց երկիրը նրանց չէր բաւականացնում միասին ապրելու համար, քանի որ նրանք մեծ ունեցուածքի տէր էին, ուստի հնարաւոր չէր համատեղ ապրել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Կռիւ եղաւ Աբրամի հօտերի հովիւների ու Ղովտի հօտերի հովիւների միջեւ: Քանանացիներն ու փերեզացիներն այդ ժամանակ բնակւում էին այդ երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Աբրամն ասաց Ղովտին. «Թող կռիւ չլինի իմ ու քո եւ իմ հովիւների ու քո հովիւների միջեւ, որովհետեւ մենք եղբայրներ ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Մի՞թէ ողջ երկիրն առաջդ չի փռուած. հեռացի՛ր ինձնից: Եթէ դու ձախ գնաս, ես աջ կը գնամ, իսկ եթէ դու աջ գնաս, ես ձախ կը գնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Ղովտն աչքերը բարձրացրեց ու տեսաւ, որ Յորդանանի բոլոր շրջաններն էլ ոռոգելի են: Քանի դեռ Աստուած չէր կործանել Սոդոմն ու Գոմորը, մինչեւ Զոորայի սահմանը Աստծու դրախտի նման էր, Եգիպտացւոց երկրի նման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Ղովտն ընտրեց Յորդանանի ողջ շրջանը եւ գնաց դէպի արեւելք: Այսպիսով եղբայրները բաժանուեցին միմեանցից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Աբրամը պանդխտեց Քանանացւոց երկրում, իսկ Ղովտը հաստատուեց այդ կողմերում գտնուող մի քաղաքում՝ ապրեց Սոդոմում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Սոդոմացիները չար մարդիկ էին եւ Աստծու հանդէպ բազում մեղքեր էին գործում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Ղովտի հեռանալուց յետոյ Աստուած Աբրամին ասաց. «Կանգնածդ տեղից քո աչքերով նայի՛ր դէպի հիւսիս ու հարաւ, դէպի արեւելք ու ծով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Որքան աչքդ կտրում է, այդ ողջ երկիրը յաւիտեան քեզ եմ տալու եւ քո սերունդներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Քո յետնորդներին պիտի բազմացնեմ երկրի աւազի չափ. եթէ որեւէ մէկը ի վիճակի լինի հաշուելու երկրի աւազը, ապա քո յետնորդներն էլ թիւ կ՚ունենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Իսկ արդ, արի շրջի՛ր այդ երկիրն իր երկարութեամբ ու լայնութեամբ, որովհետեւ այն քեզ եմ տալու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Աբրամը ճանապարհ ընկաւ, եկաւ բնակուեց Քեբրոնում գտնուող Մամբրէի կաղնու մօտ եւ այնտեղ Տէր Աստծու համար զոհասեղան շինեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Սենաարի արքայ Ամարփաղի թագաւորութեան ժամանակ Սելլասարի արքայ Արիոքը, Ելամի արքայ Քոդողագոմորը եւ ազգերի արքայ Թարգաղը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'պատերազմեցին սոդոմացիների արքայ Բաղակի, գոմորացիների արքայ Բարսայի, ադամաացիների արքայ Սենայի, սեբոյիմացիների արքայ Սիմոբորի, ինչպէս նաեւ Բաղակի՝ նոյն ինքը Սեգոր թագաւորի դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Սրանք բոլորը հաւաքուեցին Աղի ձորում, որ Աղի ծովն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Նրանք տասներկու տարի ենթարկուել էին Քոդողագոմորին եւ տասներեքերորդ տարում ապստամբեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Տասնչորսերորդ տարում եկան Քոդողագոմորն ու նրա հետ եղած թագաւորները եւ կոտորեցին Աստարոթ Կառնայիմում գտնուող հսկաներին ու նրանց հետ եղած հզօր ցեղերին, ինչպէս նաեւ սոմացիներին՝ նրանց Շաւէ քաղաքում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'կոտորեցին նաեւ Սէիրի լեռներում բնակուող քոռացիներին եւ հասան մինչեւ անապատում գտնուող Բեւեկնի ձորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Նրանք վերադարձան Դատաստանի աղբիւրը, այսինքն՝ Կադէս, եւ կոտորեցին Ամաղէկի բոլոր իշխաններին ու Ասասանթամարում բնակուող ամորհացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Սոդոմացիների արքան, գոմորացիների արքան, ադամաացիների արքան, սեբոյիմացիների արքան ու Բաղակի՝ այսինքն Սեգորի արքան ելան եւ Աղի ձորում ճակատամարտ տուեցին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Ելամի արքայ Քոդողագոմորի, ազգերի արքայ Թարգաղի, Սենաարի արքայ Ամարփաղի, Սելլասարի արքայ Արիոքի դէմ. չորս թագաւոր՝ հնգի դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Աղի ձորում հորեր կային՝ կուպրի հորեր: Սոդոմացիների արքան ու գոմորացիների արքան փախուստի դիմելիս ընկան դրանց մէջ, իսկ մնացածները փախան լերան կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Նրանք բռնագրաւեցին սոդոմացիների ու գոմորացիների ողջ աւարն ու բոլոր պաշարները եւ գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Նրանք գերեցին նաեւ Սոդոմում բնակուող Ղովտին՝ Աբրամի եղբօրորդուն, բռնագրաւեցին նրա ունեցուածքը եւ գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Ճողոպրածներից մէկն եկաւ ու այդ մասին պատմեց միւս կողմում գտնուող Աբրամին: Նա բնակւում էր Աբրամի դաշնակիցներ Եսքողի եղբօր եւ Օնանի եղբօր՝ ամորհացի Մամբրէի կաղնու մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Երբ Աբրամն իմացաւ, թէ գերեվարուել է իր եղբօրորդի Ղովտը, հաւաքեց իր երեք հարիւր տասնութ ընդոծիններին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'ինքն ու իր ծառաները գիշերով հարուածեցին նրանց, քշեցին մինչեւ Քոբաղ, որ Դամասկոսի ձախ կողմում է գտնւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Աբրամը ետ առաւ սոդոմացիների ամբողջ աւարը, ազատեց իր եղբօրորդի Ղովտին, նրա ամբողջ ունեցուածքը, ինչպէս նաեւ կանանց ու ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Երբ նա վերադառնում էր Քոդողագոմորին եւ նրա հետ եղած թագաւորներին կոտորելուց, Շաւէի ձորում, այսինքն՝ Թագաւորների դաշտում նրան ընդառաջ գնաց սոդոմացիների արքան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Շաղէմի արքայ Մելքիսեդեկը հաց ու գինի հիւրասիրեց նրան, որովհետեւ ինքը բարձրեալ Աստծու քահանան էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Նա օրհնեց Աբրամին՝ ասելով. «Օրհնեալ է Աբրամը բարձրեալ Աստծու կողմից, որ ստեղծեց երկինքն ու երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Օրհնեալ է բարձրեալն Աստուած, որ քո թշնամիներին մատնեց քո ձեռքը»: Աբրամը նրան տասանորդ տուեց ամէն ինչից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Սոդոմացիների արքան, սակայն, ասաց Աբրամին. «Դու ինձ տուր այդ մարդկանց, իսկ աւարը թող մնայ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Աբրամն ասաց սոդոմացիների արքային. «Երդւում եմ երկինքն ու երկիրը ստեղծած բարձրեալ Աստուծով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'որ քեզ պատկանող ոչ մի բանից՝ թելից մինչեւ կօշիկի կապն անգամ ես չեմ վերցնի, որպէսզի չասես, թէ՝ «ես հարստացրի Աբրամին»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'բացի ծառաների կերածից: Իսկ ինձ հետ եկած մարդիկ՝ Օնանը, Եսքողն ու Մամբրէն, իրենք թող ստանան իրենց բաժինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Այս դէպքերից յետոյ Աբրամը երազում լսեց Տիրոջ խօսքը, որն ասում էր. «Մի՛ վախեցիր, Աբրա՛մ, ես քեզ հովանաւոր պիտի լինեմ, եւ քո վարձը չափազանց շատ պիտի լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Աբրամն ասաց. «Տէ՛ր ամենակալ, ի՞նչ ես անելու ինձ, չէ՞ որ ես անորդի եմ կորչում, եւ ինձ ժառանգելու է Եղիազար Դամասկացին՝ իմ ընդոծին Մասեկի որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Աբրամն աւելացրեց. «Քանի որ ինձ զաւակ չտուեցիր, ուստի իմ ընդոծինն է ինձ ժառանգելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Նրան իսկոյն հասաւ Աստծու ձայնը, որն ասում էր. «Նա չէ, որ ժառանգելու է քեզ, այլ քեզնից ծնուածն է ժառանգելու քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Աստուած դուրս հանեց նրան ու ասաց. «Նայի՛ր երկնքին ու հաշուի՛ր աստղերը, եթէ կարող ես հաշուել դրանք»: Նա աւելացրեց. «Այդքան է լինելու քո սերունդը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Աբրամը հաւատաց Աստծուն, եւ այդ հաւատը իր համար արդարութիւն համարուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Աստուած ասաց նրան. «Ե՛ս եմ քո Տէր Աստուածը, որ քեզ դուրս հանեցի Քաղդէացւոց երկրից, որպէսզի այս երկիրը քեզ տամ որպէս ժառանգութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Աբրամն ասաց. «Տէ՛ր ամենակալ, ինչի՞ց գիտենամ, որ ժառանգելու եմ այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Աստուած ասաց նրան. «Դու ինձ համար ա՛ռ երեք տարեկան երինջ, երեք տարեկան նոխազ, երեք տարեկան խոյ, տատրակ եւ աղաւնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Աբրամն առաւ այդ ամէնը, կտրեց մէջտեղից ու կտորները դրեց իրար դիմաց, իսկ թռչունները չկտրատեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Գիշակեր թռչուններ էին իջնում դրանց կտրտուած մարմինների վրայ, բայց Աբրամը հսկում էր կտրտուած մարմինները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Արեւի մայր մտնելու ժամանակ Աբրամը թմբիրի մէջ ընկաւ, սարսափելի վախ համակեց նրա սիրտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Տէրն ասաց Աբրամին. «Լա՛ւ իմացիր, որ քո յետնորդները պանդուխտ են լինելու օտար երկրում: Նրանց պիտի ստրկացնեն, պիտի չարչարեն, պիտի տանջեն չորս հարիւր տարի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'բայց ես դատաստան պիտի տեսնեմ այն ազգի հետ, որը պիտի ստրկացնի նրանց: Դրանից յետոյ նրանք այստեղ պիտի վերադառնան բազում հարստութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Դու խաղաղ հոգով պիտի գնաս քո նախնիների գիրկը՝ խոր ծերութեան հասնելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Չորրորդ սերունդը պիտի վերադառնայ այստեղ, որովհետեւ ամորհացիների մեղքերը դեռ իրենց լրումին չեն հասել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Երբ արեւը մայր մտնելու մօտ էր, կրակ բոցավառուեց, երեւաց ծխացող մի հնոց, եւ կրակի լեզուները անցան անասունների կտրտուած մարմինների միջով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Այդ օրը Տէրն ուխտ դրեց Աբրամի հետ եւ ասաց. «Քո յետնորդներին եմ տալու այդ երկիրը՝ եգիպտացիների գետից մինչեւ Եփրատ մեծ գետը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'նրանց պիտի ենթարկուեն կինեցիները, կենեզացիները, կեդմոնացիները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'քետացիները, փերեզացիները, ռափիմացիները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'ամորհացիները, քանանացիները եւ յեբուսացիները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Աբրամի կին Սարան նրան երեխայ չէր պարգեւում: Սարան ունէր մի եգիպտացի աղախին, որի անունն Ագար էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Սարան Քանանացւոց երկրում ասաց Աբրամին. «Քանի որ Տէրն ինձ զրկել է երեխայ ունենալուց, պառկի՛ր իմ աղախնի հետ, որպէսզի նրա միջոցով որդի ունենամ»: Եւ Աբրամն անսաց Սարայի ասածին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Սարան՝ Աբրամի կինը, եգիպտացի աղախին Ագարին կնութեան տուեց իր ամուսնուն՝ Աբրամին, Քանանացիների երկրում տասը տարի նրա ապրելուց յետոյ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Աբրամը պառկեց Ագարի հետ, եւ սա յղիացաւ: Երբ Ագարը տեսաւ, որ ինքը յղի է, տիրուհին ընկաւ նրա աչքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Այն ժամանակ Սարան ասաց Աբրամին. «Անիրաւ ես դու իմ նկատմամբ. ե՛ս իմ աղախնուն յանձնեցի քո գիրկը. իսկ նա տեսնելով, որ ինքը յղիացել է, արհամարհում է ինձ: Աստուած թող իմ ու քո դատաստանը տեսնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Աբրամն ասաց Սարային. «Քո աղախինն ահա քո ձեռքում է, վարուի՛ր նրա հետ այնպէս, ինչպէս հաճոյ է քեզ»: Սարան չարչարեց նրան, եւ աղախինը փախաւ նրա մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Տիրոջ հրեշտակը նրան գտաւ անապատում, ջրի աղբիւրի մօտ, այն աղբիւրի, որ Սուր տանող ճանապարհի վրայ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Տիրոջ հրեշտակը նրան ասաց. «Ագա՛ր, Սարայի աղախին, որտեղի՞ց ես գալիս, կամ ո՞ւր ես գնում»: Նա պատասխանեց. «Իմ տիրուհի Սարայի մօտից եմ փախչում ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Տիրոջ հրեշտակը նրան ասաց. «Վերադարձի՛ր քո տիրուհու մօտ եւ հնազա՛նդ եղիր նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Տիրոջ հրեշտակն աւելացրեց. «Ես անչափ բազմացնելու եմ քո սերունդը, այնքան, որ հաշուել հնարաւոր չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Տիրոջ հրեշտակը ասաց նաեւ. «Դու արդէն յղի ես, որդի պիտի ունենաս եւ նրա անունը Իսմայէլ պիտի դնես, որովհետեւ Տէրը իմացաւ քո տառապանքները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Նա վայրագ մարդ է լինելու: Նա ձեռք է բարձրացնելու բոլորի դէմ, եւ բոլորը ձեռք են բարձրացնելու նրա դէմ: Նա բնակուելու է իր բոլոր եղբայրների դիմաց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Ագարն իր հետ խօսող Տիրոջը դիմելով՝ ասաց. «Դու այն Աստուածն ես, որ ինձ զօրավիգ եղաւ. - քանզի ասաց, - ես իմ առաջ տեսայ նրան, ով երեւացել է ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Այդ իսկ պատճառով ջրհորը կոչուեց Ջրհոր, այսինքն՝ «որի դիմաց տեսայ Աստծուն»: Այն գտնւում է Կադէսի ու Բարադի միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Ագարը Աբրամի համար ծնեց մի որդի, եւ Աբրամը Ագարի՝ իր համար ծնած որդու անունը դրեց Իսմայէլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Աբրամը ութսունվեց տարեկան էր, երբ Ագարը նրա համար ծնեց Իսմայէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Երբ Աբրամը իննսունինը տարեկան եղաւ, Տէր Աստուած երեւաց Աբրամին ու ասաց նրան. «Ես եմ քո Աստուածը, հնազա՛նդ եղիր ինձ, եղի՛ր անարատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ուխտ եմ դնելու իմ եւ քո միջեւ. ես անչափ բազմացնելու եմ քո սերունդը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Աբրամը երկրպագեց, իսկ Աստուած, դիմելով նրան, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '«Այս է իմ՝ քեզ հետ դրած ուխտը. բազում ազգերի նախահայր պիտի դառնաս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Սրանից յետոյ քո անունը Աբրամ պիտի չլինի, այլ Աբրահամ պիտի լինի քո անունը, որովհետեւ բազում ազգերի նախահայր եմ դարձնելու քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Քո սերունդը շատ եմ աճեցնելու, քեզնից բազում ազգեր պիտի սերեմ, թագաւորներ պիտի ծնուեն քեզնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Իմ ուխտը պիտի հաստատեմ իմ եւ քո միջեւ, քեզնից յետոյ գալիք քո սերունդների ու նրանց ցեղերի միջեւ որպէս յաւիտենական ուխտ, որով ես եմ լինելու քո եւ քեզնից յետոյ գալիք սերունդների Աստուածը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Քեզ ու քո սերունդներին իբրեւ յաւիտենական սեփականութիւն տալու եմ այս երկիրը, ուր դու բնակւում ես պանդխտութեան մէջ, Քանանացիների ամբողջ երկիրը: Ես լինելու եմ նրանց Աստուածը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'իսկ դու եւ քեզնից յետոյ գալիք քո զաւակները, սերնդից սերունդ, պէտք է պահէք իմ ուխտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Այս է իմ ուխտը, որ պիտի պահես իմ եւ քո միջեւ ու քեզնից յետոյ գալիք քո զաւակների միջեւ, սերնդից սերունդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ձեր բոլոր արու զաւակները պիտի թլփատուեն, պիտի թլփատէք ձեր անդամների թլիփները, եւ դա թող լինի իմ եւ ձեր միջեւ ուխտի նշանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Ձեր մանուկները՝ ձեր ցեղերի բոլոր արուները, ընդոծինն ու արծաթով գնուած ստրուկները, ամէն մի օտարածին, որ քո սերնդից չէ, ութօրեայ հասակում պէտք է թլփատուեն: Պէտք է անպայման թլփատուեն քո տան ընդոծինն ու արծաթով գնուած քո ստրուկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Ձեր թլփատութեան մասին իմ ուխտը թող յաւիտենական ուխտ լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Ութերորդ օրը թլիփը չթլփատուած արուն թող վերանայ իր ցեղի միջից, որովհետեւ խախտած կը լինի իմ ուխտը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Աստուած ասաց Աբրահամին. «Քո կին Սարայի անունն այլեւս Սարա թող չլինի, այլ Սառա թող լինի նրա անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ես կ՚օրհնեմ նրան եւ նրա միջոցով քեզ զաւակ կը պարգեւեմ, ես կ՚օրհնեմ նրան, նա ազգերի նախամայր կը դառնայ, նրանից ցեղերի թագաւորներ կը ծնուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Աբրահամը երկրպագեց, ծիծաղեց ու ինքն իրեն ասաց. «Կարո՞ղ է հարիւր տարեկան մարդը որդի ունենալ, իննսունամեայ Սառան կարո՞ղ է ծնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Աբրահամն ասաց Աստծուն. «Այս Իսմայէլը թող ապրի քո առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Աստուած պատասխանեց Աբրահամին. «Այո՛. ահա քո կին Սառան քեզ համար որդի է բերելու, եւ իմ ուխտը, որպէս յաւիտենական ուխտ, հաստատելու եմ նրա հետ ու նրանից յետոյ գալիք սերունդների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Ինչ վերաբերում է Իսմայէլին, ապա ընդառաջում եմ քեզ: Նրան կ՚օրհնեմ, նրան կ՚աճեցնեմ եւ անչափ կը բազմացնեմ նրա սերունդները: Նա տասներկու ազգ է սերելու, եւ նրան մեծ ազգի նախահայր եմ դարձնելու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'բայց իմ ուխտը ես հաստատելու եմ Իսահակի հետ, որին կը ծնի Սառան քեզ համար միւս տարի այս ժամանակ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Աստուած վերջացրեց իր խօսքը Աբրահամի հետ եւ հեռացաւ նրա մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Աբրահամը իր որդի Իսմայէլի, իր բոլոր ընդոծինների, արծաթով գնուած իր բոլոր ստրուկների եւ Աբրահամի տանն եղած բոլոր արու մարդկանց թլիփը նոյն օրն իսկ թլփատեց, ինչպէս ասել էր նրան Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Աբրահամը իննսունինը տարեկան էր, երբ թլփատեց իր թլիփը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'իսկ իր որդի Իսմայէլը տասներեք տարեկան էր, երբ թլփատուեց նրա թլիփը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Այդ օրը թլփատուեցին Աբրահամն ու իր որդի Իսմայէլը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Նա թլփատեց իր տան բոլոր տղամարդկանց՝ ընդոծիններ լինեն նրանք թէ արծաթով գնուած օտարածին ստրուկներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Աստուած Աբրահամին երեւաց Մամբրէի կաղնու մօտ, երբ սա կէսօրին դեռ նստած էր իր վրանի դռան մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Աբրահամը բարձրացրեց աչքերը եւ իր դիմաց տեսաւ երեք տղամարդկանց: Տեսնելով նրանց՝ նա իր վրանի դռան մօտից ընդառաջ գնաց, գլուխը խոնարհեց մինչեւ գետին ու ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, '«Տէ՛ր, եթէ շնորհ գտայ քո առաջ, քո ծառային անտես մի՛ արա,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'թող մի քիչ ջուր բերեն, լուան ձեր ոտքերը, ապա հովացէ՛ք ծառի տակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Հաց բերեմ, կերէ՛ք եւ ապա գնացէ՛ք ձեր ճանապարհով, որովհետեւ ձեր ծառայի մօտ գալու համար շեղեցիք ձեր ճանապարհը»: Նրանք պատասխանեցին. «Արա՛ այնպէս, ինչպէս ասացիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Աբրահամն շտապեց դէպի վրանը՝ Սառայի մօտ, եւ ասաց նրան. «Շտապի՛ր, երեք գրիւ ընտիր ալիւր հունցի՛ր ու նկանակ պատրաստի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Աբրահամը գնաց դէպի նախիր, վերցրեց մի մատղաշ, լաւ հորթ, տուեց ծառային ու շտապեցրեց, որ կերակուր պատրաստի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Նա վերցրեց կարագ, կաթ ու հորթի մսից պատրաստուած կերակուրը եւ դրեց նրանց առաջ: Նրանք կերան, իսկ ինքը կանգնած մնաց նրանց առաջ, ծառի տակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Նրանք հարցրին. «Ու՞ր է քո կին Սառան»: Նա պատասխանեց. «Վրանում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Նրանցից մէկն ասաց. «Ես եկող տարի նոյն այս օրերին կը գամ քեզ մօտ եւ քո կին Սառան որդի կ՚ունենայ»: Սառան ականջ էր դնում վրանի դռանը՝ նրա ետեւում կանգնած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Աբրահամն ու Սառան ծերացել էին, նրանց տարիքն առաջացել էր, եւ Սառան կորցրել էր ծննդաբերելու յատկութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Ծիծաղեց Սառան իր մտքում եւ ասաց. «Այն, ինչ մինչեւ այժմ չկարողացայ անել, հիմա՞ պիտի կարողանամ: Իսկ իմ ամուսինն էլ ծերացել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Տէրն ասաց Աբրահամին. «Այդ ինչո՞ւ է ծիծաղում Սառան իր մտքում եւ ասում, թէ՝ «Իրօ՞ք կը ծնեմ, չէ՞ որ ես պառաւել եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Մի՞թէ Աստծու համար անկարելի բան կայ: Եկող տարի այս ժամանակ՝ այս օրերին ես կը վերադառնամ քեզ մօտ, եւ Սառան որդի կ՚ունենայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Ժխտեց Սառան՝ ասելով. «Ես չծիծաղեցի»: Նա վախեցել էր: Տէրը ասաց. «Ո՛չ, այդպէս չէ, ծիծաղեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Նրանք այդտեղից վեր կենալով ճանապարհ ընկան դէպի Սոդոմացւոց ու Գոմորացւոց երկիրը, իսկ Աբրահամը գնաց նրանց ճանապարհելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Տէրն ասաց. «Մի՞թէ ես իմ ծառայ Աբրահամից գաղտնի պիտի պահեմ այն, ինչ անելու եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Աբրահամը, հաստատապէս, մեծ եւ բազմանդամ ազգի նախահայր է լինելու, եւ նրա միջոցով պիտի օրհնուեն երկրի բոլոր ազգերը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'որովհետեւ ես գիտէի, որ նա իր որդիներին ու իր յետնորդներին կը պատուիրի, որ նրանք Տիրոջ ճանապարհով ընթանան՝ պահպանելով արդարութիւնն ու իրաւունքը: Տէր Աստուած կը կատարի այն ամէնը, ինչ խոստացել է Աբրահամին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Այնուհետեւ Տէրն ասաց. «Սոդոմացիների ու գոմորացիների աղաղակը ահագնացել, հասել է ինձ. նրանց մեղքերը խիստ շատացել են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Արդ, իջնեմ տեսնեմ, թէ ինձ. հասած նրանց աղաղակը համապատասխանո՞ւմ է նրանց կատարածին, թէ՞ ոչ: Այդ եմ ուզում գիտենալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Այնտեղից շրջուելով՝ այդ մարդիկ եկան Սոդոմ: Աբրահամը կանգնած էր Տիրոջ դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Աբրահամը մօտեցաւ Տիրոջն ու ասաց. «Մի՞թէ դու արդարին ամբարշտի հետ կ՚ոչնչացնես, եւ արդարը նոյն բանին կ՚ենթարկուի, ինչ որ ամբարիշտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Եթէ քաղաքում յիսուն արդար լինի, կ՚ոչնչացնե՞ս նրանց, չե՞ս խնայի ամբողջ քաղաքը յանուն այնտեղ գտնուող յիսուն արդարների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Քա՛ւ լիցի, չանես այդ բանը՝ արդարին սպանես ամբարշտի հետ, եւ արդարը ենթարկուի նոյն բանին, ինչ որ ամբարիշտը: Ո՛չ, դու, որ դատում ես ամբողջ աշխարհը, այդպիսի դատաստան չես անի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Տէրն ասաց. «Եթէ Սոդոմում՝ այդ քաղաքում գտնուի յիսուն արդար, յանուն նրանց ես կը խնայեմ ամբողջ քաղաքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Պատասխան տուեց Աբրահամն ու ասաց. «Հիմա համարձակւում եմ խօսել Տիրոջ հետ, թէեւ ես հող եմ ու մոխիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Իսկ եթէ յիսուն արդարները պակասեն հինգ հոգով, այդ հնգի պատճառով դարձեա՞լ կը կործանես ողջ քաղաքը»: Տէրն ասաց. «Չեմ կործանի, եթէ այնտեղ գտնուի քառասունհինգ արդար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Աբրահամը շարունակեց խօսել նրա հետ ու ասաց. «Իսկ եթէ այնտեղ գտնուի քառասո՞ւն»: Նա ասաց. «Չեմ կործանի յանուն այդ քառասունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Աբրահամն ասաց. «Տէ՛ր, ինձ որեւէ բան կը պատահի՞, եթէ շարունակեմ խօսել. իսկ եթէ այնտեղ գտնուի երեսո՞ւն»: Տէրը պատասխանեց. «Չեմ կործանի, եթէ այնտեղ գտնուի երեսուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Աբրահամն ասաց. «Քանի սկսել եմ խօսել Տիրոջ հետ, ասեմ. իսկ եթէ այնտեղ գտնուի քսա՞ն»: Տէրը պատասխանեց. «Չեմ կործանի յանուն այդ քսանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Աբրահամն ասաց. «Տէ՛ր, ինձ որեւէ բան կը պատահի՞, եթէ դարձեալ խօսեմ. իսկ եթէ այնտեղ գտնուի տա՞սը»: Տէրը պատասխանեց. «Չեմ կործանի յանուն տասի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Եւ Տէրը, վերջացնելով Աբրահամի հետ խօսակցութիւնը, գնաց, իսկ Աբրահամը վերադարձաւ իր բնակատեղին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Երկու հրեշտակները երեկոյեան եկան Սոդոմ: Ղովտը նստած էր Սոդոմի դարպասի մօտ: Երբ Ղովտը տեսաւ նրանց, ընդառաջ գնաց, գլուխը խոնարհեց մինչեւ գետին ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, '«Համեցէ՛ք, տիա՛րք, եկէք մտէ՛ք ձեր ծառայի տունը եւ գիշերեցէ՛ք այստեղ: Ես կը լուամ ձեր ոտքերը, եւ դուք վաղ առաւօտեան կը շարունակէք ձեր ճանապարհը»: Նրանք ասացին. «Ո՛չ, մենք այստեղ՝ քաղաքի հրապարակում կը գիշերենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ղովտը նրանց շատ ստիպեց, եւ նրանք դարձան նրա կողմը ու մտան նրա տունը: Ղովտը ընթրիք պատրաստեց, բաղարջ հաց եփեց նրանց համար, եւ նրանք կերան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Երբ դեռ նրանք քուն չէին մտել, սոդոմացիների քաղաքի տղամարդիկ՝ երիտասարդից մինչեւ ծերը, ամբողջ ժողովուրդը միասին պաշարեցին տունը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Ղովտին դուրս կանչեցին ու հարցրին նրան. «Ո՞ւր են այն տղամարդիկ, որ գիշերը քեզ մօտ եկան: Նրանց բե՛ր մեզ մօտ, որ կենակցենք նրանց հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Ղովտը դռնից դուրս՝ նրանց մօտ եկաւ եւ դուռը փակեց իր ետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Նա նրանց ասաց. «Քա՛ւ լիցի, եղբայրնե՛ր, մի՛ գործէք այդ չարիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Ես երկու դուստր ունեմ, որոնց տղամարդ չի մօտեցել: Բերեմ նրանց ձեզ մօտ, եւ նրանց հետ արէք այն, ինչ հաճոյ է ձեզ, միայն թէ այդ մարդկանց նկատմամբ որեւէ մեղք մի՛ գործէք, որովհետեւ նրանք մտել են իմ յարկի տակ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Նրանք ասացին. «Հեռո՛ւ կաց: Դու մեր երկիրը մտար իբրեւ պանդուխտ բնակուելու. միթէ դատաստա՞ն էլ ես ուզում տեսնել: Հիմա քեզ աւելի շատ կը չարչարենք, քան նրանց»: Նրանք շատ էին բռնանում այդ մարդու՝ Ղովտի վրայ, եւ քիչ էր մնացել, որ ջարդէին դուռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Ներսի մարդիկ, իրենց ձեռքերը մեկնելով, Ղովտին իրենց մօտ՝ տուն քաշեցին եւ տան դռները փակեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'դռան մօտ գտնուող մարդկանց՝ փոքրից մինչեւ մեծը կուրացրին, եւ սրանք յոգնեցին դուռը փնտռելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Այդ մարդիկ Ղովտին հարցրին. «Այս քաղաքում դու փեսայ, որդիներ, դուստրեր կամ ուրիշ որեւէ մէկն ունե՞ս: Հանի՛ր նրանց այս վայրից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'որովհետեւ մենք կործանելու ենք այս քաղաքը, քանի որ սրանց աղաղակը հասել է Տիրոջը, եւ Տէրը մեզ ուղարկել է, որ կործանենք այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Ղովտը գնաց իր փեսացուների մօտ, որոնք առնելու էին իր դուստրերին, եւ ասաց նրանց. «Հեռացէ՛ք այստեղից, որովհետեւ Տէրը կործանելու է այս քաղաքը»: Փեսացուներին թուաց, թէ նա կատակ է անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Երբ լոյսը բացուեց, հրեշտակներն սկսեցին շտապեցնել Ղովտին՝ ասելով. «Ա՛ռ քո կնոջը, երկու դուստրերիդ եւ հեռացի՛ր այստեղից, որ դու էլ չկորչես այս քաղաքի անօրէնութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Նրանք իրար անցան. եւ քանի որ Տէրը խնայել էր Ղովտին, հրեշտակները բռնեցին նրա, նրա կնոջ ու երկու դուստրերի ձեռքերից եւ քաղաքից դուրս հանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Երբ նրանց դուրս հանեցին, հրեշտակներն ասացին. «Փրկի՛ր անձդ, ետ չնայես, կանգ չառնես այս երկրի որեւէ շրջանում: Փախի՛ր լեռը, որ միւսների հետ չտուժես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Ղովտն ասաց նրանց. «Աղաչում եմ, Տէ՛ր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'թէեւ իմ անձին փրկութիւն պարգեւելով դու ողորմեցիր քո ծառային եւ նրա հանդէպ ցուցաբերեցիր քո մեծ արդարութիւնը, բայց ես չեմ կարող փախչել լեռը, որովհետեւ գուցէ ինձ էլ հասնի փորձանքը, եւ ես մեռնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Ահա մօտակայքում գտնուող այս քաղաքում կարելի է ապաստանել, այն փոքր է, կարելի է այնտեղ փրկուել: Չէ՞ որ այն փոքր է: Քո շնորհիւ ես կը փրկուեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Տէրն ասաց նրան. «Ահա ես շնորհ եմ անում քեզ ու քո այդ ասածին անսալով՝ չեմ կործանի այն քաղաքը, որի մասին ասացիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Արդ, շտապ փախի՛ր այնտեղ, որովհետեւ ոչինչ անել չեմ կարող. մինչեւ որ դու այնտեղ հասնես»: Դրա համար էլ նա այդ քաղաքի անունը կոչեց Սեգոր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Արեւ ծագեց երկրի վրայ, եւ Ղովտը մտաւ Սեգոր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Տէրը երկնքից ծծումբ ու կրակ թափեց Սոդոմի ու Գոմորի վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'կործանեց այդ քաղաքներն ու դրանց ամբողջ շրջակայքը, ոչնչացրեց քաղաքների բոլոր բնակիչներին ու երկրի ամբողջ բուսականութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Ղովտի կինը ետ նայեց ու դարձաւ աղէ արձան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Աբրահամը վաղ առաւօտեան գնաց այնտեղ, ուր ինքը կանգնել էր Տիրոջ առաջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'նայեց սոդոմացիների ու գոմորացիների կողմը, ամբողջ շրջակայքը եւ տեսաւ, թէ ինչպէս երկրի բոցը բարձրանում է հնոցի ծխի պէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Երբ Տէրը կործանեց այդ բոլոր քաղաքներն իրենց շրջակայ բնակավայրերով, յիշեց Աբրահամին եւ քաղաքից հանեց ու կորստից փրկեց Ղովտին, երբ կործանում էր այն քաղաքները, ուր Ղովտն էր բնակուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Ղովտը ելաւ Սեգորից եւ լեռը բարձրացաւ, որովհետեւ վախենում էր մնալ Սեգորում: Նրա հետ էին նաեւ իր երկու դուստրերը: Ինքն ու իր երկու դուստրերը միասին բնակուեցին այդ լերան մի քարայրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Աւագ դուստրն ասաց կրտսերին. «Մեր հայրը ծերացել է, եւ երկրում չկայ մէկը, որ մեզ հետ պառկի, ինչպէս ողջ աշխարհի կարգն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Արի գինի խմեցնենք մեր հօրը, պառկենք նրա հետ ու մեր հօրից զաւակ ունենանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Նրանք իրենց հօրը գինի խմեցրին այդ գիշեր: Աւագ դուստրն այդ գիշեր պառկեց իր հօր հետ, իսկ Ղովտը չիմացաւ նրա պառկելն ու վեր կենալը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Առաւօտեան աւագն ասաց կրտսերին. «Ես երէկ պառկեցի իմ հօր հետ: Նրան այս գիշեր էլ գինի խմեցնենք, եւ դու մտի՛ր, պառկի՛ր նրա հետ, որ զաւակ ունենանք մեր հօրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Այդ գիշեր էլ գինի խմեցրին իրենց հօրը, եւ կրտսերը պառկեց իր հօր հետ: Ղովտը չիմացաւ նրա պառկելն ու վեր կենալը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Ղովտի երկու դուստրերն էլ յղիացան իրենց հօրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Աւագը ծնեց որդի եւ նրա անունը դրեց Մովաբ, որ նշանակում է «Իմ հօրից»: Նա է մովաբացիների նախահայրը մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Կրտսերը նոյնպէս ծնեց որդի եւ նրա անունը դրեց Ամման, որ նշանակում է «Իմ ազգատոհմի որդի»: Նա է ամոնացիների նախահայրը մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Աբրահամն այդտեղից գնաց երկրի հարաւը, բնակուեց Կադէսի ու Սուրի միջեւ, ապա տարաբնակուեց Գերարայում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Աբրահամն իր կին Սառայի մասին ասում էր, թէ նա իր քոյրն է: Գերարացիների արքայ Աբիմելէքն ուղարկեց իր մարդկանց եւ կին առաւ Սառային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Գիշերն Աստուած Աբիմելէքին երեւաց երազում եւ ասաց. «Դու մեռնելու ես այն կնոջ պատճառով, որին առար, որովհետեւ այդ կինը ամուսին ունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Սակայն Աբիմելէքը, որ չէր մերձեցել նրան, ասաց. «Տէ՛ր, մի՞թէ դու կը սպանես բանից անտեղեակ ու արդար մարդկանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Չէ՞ որ նա ասաց ինձ՝ «Իմ քոյրն է», իսկ սա ասաց ինձ՝ «Իմ եղբայրն է»: Ես մաքուր սրտով ու արդար ձեռքով արեցի դա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Աստուած երազի մէջ ասաց նրան. «Գիտեմ, որ դու մաքուր սրտով ես արել այդ, դրա համար էլ ես խնայեցի քեզ, որ չմեղանչես իմ դէմ: Այդ պատճառով էլ թոյլ չտուեցի, որ մերձենաս նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Արդ, կնոջը վերադարձրո՛ւ իր ամուսնուն, որովհետեւ նա մարգարէ է, աղօթք կ՚անի քեզ համար, եւ դու կենդանի կը մնաս: Եթէ չվերադարձնես, իմացի՛ր, որ դու եւ բոլոր նրանք, ովքեր քո իւրայիններն են, կը մեռնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Աբիմելէքն առաւօտեան վաղ վեր կացաւ, կանչեց իր բոլոր ստրուկներին եւ նրանց պատմեց այս բոլոր բաները: Ամէնքը խիստ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Աբիմելէքը կանչեց Աբրահամին ու ասաց նրան. «Այդ ի՞նչ փորձանք բերեցիր դու մեր գլխին: Մենք ի՞նչ մեղք էինք գործել քո դէմ, որ իմ ու իմ թագաւորութեան վրայ այդպիսի մեծամեծ մեղքեր բարդեցիր: Դու ինձ հետ արեցիր այն, ինչ ոչ ոք չէր արել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Աբիմելէքն ասաց Աբրահամին. «Ի՞նչ մտածեցիր, որ նման բան արեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Աբրահամը պատասխանեց. «Ես կարծեցի, թէ գուցէ այս վայրում էլ աստուածապաշտութիւն չկայ, եւ հնարաւոր է, որ ինձ սպանեն իմ կնոջ պատճառով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Բայց նա, արդարեւ, իմ քոյրն է իմ հօր եւ ոչ թէ մօր կողմից, եւ դարձաւ իմ կինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Երբ Աստուած ինձ հանեց իմ հօր տնից, ես կնոջս ասացի. «Այս արդար քայլն արա՛ ինձ համար. ուր էլ գնանք, իմ մասին կ՚ասես, թէ՝ իմ եղբայրն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Աբիմելէքն առաւ հազար սատեր, արջառ ու ոչխար, ստրուկներ ու ստրկուհիներ եւ տուեց Աբրահամին: Նրան վերադարձրեց նաեւ նրա կին Սառային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Աբիմելէքն ասաց Աբրահամին. «Ահա քո դիմաց փռուած է իմ երկիրը, ուր հաճելի է քեզ, այնտեղ էլ բնակուի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Իսկ Սառային դիմելով՝ ասաց. «Ահա հազար սատեր եմ տալիս քո եղբօրը: Այն թող պատուի վկայութիւն լինի քեզ եւ քեզ հետ գտնուող բոլոր կանանց համար: Այսուհետեւ կը պատմես ամբողջ ճշմարտութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Աբրահամն աղօթեց Աստծուն, որը բուժեց Աբիմելէքին, ինչպէս նաեւ նրա կնոջն ու նրա աղախիններին: Նրանք արդէն կարողանում էին երեխայ ունենալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Մինչ այդ Տէրը Աբրահամի կին Սառայի պատճառով Աբիմելէքի ողջ տան կանանց զրկել էր երեխայ ունենալու կարողութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Տէրն այցելեց Սառային, ինչպէս ասել էր, եւ կատարեց Սառային տուած իր խոստումը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Սառան յղիացաւ ու Աբրահամի համար ծեր տարիքում որդի ծնեց ճիշտ այն ժամանակ, ինչպէս Աստուած յայտնել էր Աբրահամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Աբրահամն իր որդու անունը, որին ծնեց Սառան նրա համար, դրեց Իսահակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Աբրահամն ութերորդ օրը թլփատեց իր որդի Իսահակին, ինչպէս պատուիրել էր նրան Տէր Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Աբրահամը հարիւր տարեկան էր, երբ ունեցաւ իր որդի Իսահակին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Սառան ասաց. «Աստուած ուրախութիւն պարգեւեց ինձ, եւ ով որ լսի այդ մասին, ինձ հետ կ՚ուրախանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Նա աւելացրեց. «Ո՞վ կ՚ասէր Աբրահամին, թէ Սառան երեխայ կը սնուցանի, քանի որ ծեր հասակում որդի ծնեցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Մանուկն աճեց, նրան կրծքից կտրեցին, եւ Աբրահամն իր որդի Իսահակի կրծքից կտրուելու առթիւ մեծ խնջոյք արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Երբ Սառան տեսաւ, որ եգիպտուհի Ագարից Աբրահամի ունեցած որդին խաղում է իր որդի Իսահակի հետ, ասաց Աբրահամին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, '«Հեռացրո՛ւ քո աղախնին եւ նրա որդուն, որպէսզի քո աղախնի որդին իմ որդի Իսահակի հետ հաւասար ժառանգութիւն չստանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Իր որդու մասին ասուած այդ խօսքերը ցաւ պատճառեցին Աբրահամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Աստուած ասաց Աբրահամին. «Մանկան եւ աղախնի մասին ասուած խօսքերը թող քեզ ցաւ չպատճառեն: Ինչ որ ասի քեզ Սառան, լսի՛ր նրան, որովհետեւ Իսահակի միջոցով ես դու սերունդդ շարունակելու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'բայց քո աղախնի որդու սերունդն էլ ես նշանաւոր կը դարձնեմ, որովհետեւ նա էլ քո սերմից է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Առաւօտեան վեր կացաւ Աբրահամը, առաւ հաց ու մի տիկ ջուր, տուեց Ագարին, մանկանը դրեց նրա շալակին եւ տնից դուրս հանեց: Ագարը թափառում էր անապատում, Երդման ջրհորի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Տիկի ջուրն սպառուեց, մայրը մանկանը դրեց մի եղեւնու տակ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'եւ գնաց նստեց նրա դիմաց, մի նետընկեց հեռաւորութեան վրայ՝ ասելով. «Թող ես չտեսնեմ իմ որդու մահը»: Նա նստել էր նրա դիմաց: Երեխան բարձրաձայն լալիս էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Աստուած լսեց երեխայի ձայնը, որ գալիս էր այնտեղից: Աստուած երկնքից Ագարին ձայն տուեց ու ասաց. «Ի՞նչ է պատահել, Ագա՛ր: Մի՛ վախեցիր, որովհետեւ Աստուած լսեց քո որդու ձայնը այնտեղից, ուր նա գտնւում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Բռնի՛ր քո մանկան ձեռքից, որովհետեւ ես նրան մեծ ազգի նախահայր եմ դարձնելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Աստուած բացեց Ագարի աչքերը, սա տեսաւ ըմպելի ջրի մի ջրհոր, գնաց, տիկը լցրեց ջրով ու խմեցրեց երեխային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Եւ Աստուած երեխայի հետ էր. սա աճեց, դարձաւ աղեղնաւոր');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'եւ բնակուեց Փառանի անապատում: Մայրը նրա համար Եգիպտացիների երկրից կին առաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Այդ ժամանակներում Աբիմելէքը, նրա սենեկապետ Ոքոզաթն ու նրա զօրքերի սպարապետ Փիքողը, խօսելով Աբրահամի հետ, ասացին. «Աստուած քեզ հետ է բոլոր այն գործերում, ինչ դու անում ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Արդ, Աստծու անունով ինձ երդուի՛ր, որ ո՛չ իմ, ո՛չ իմ զաւակի, ո՛չ իմ անուան դէմ չես մեղանչի, այլ կը վարուես այնպէս արդար, ինչպէս ես վարուեցի քո նկատմամբ, նոյնպէս եւ իմ երկրի նկատմամբ, ուր դու բնակւում ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Աբրահամն ասաց. «Երդւում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Աբրահամն Աբիմելէքին յանդիմանեց այն ջրհորի համար, որ Աբիմելէքի ծառաները խլել էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Աբիմելէքն ասաց նրան. «Ես չեմ իմացել, թէ ով է արել այդ բանը, իսկ դու էլ ինձ բան չես ասել: Ես միայն այսօր եմ լսում այդ մասին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Աբրահամն առաւ արջառներ ու ոչխարներ, տուեց Աբիմելէքին, եւ երկուսն իրար հետ հաշտութիւն կնքեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Աբրահամը եօթը որոջ առանձնացրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Աբիմելէքը հարցրեց Աբրահամին. «Ի՞նչ են նշանակում այս եօթը որոջները, որոնց առանձնացրիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Նա պատասխանեց. «Այս եօթը որոջները ստացիր ինձնից ի հաւաստումն այն բանի, թէ ես եմ փորել այդ ջրհորը»: Դրա համար էլ այդ վայրը կոչուեց Երդման ջրհոր, Նա պատասխանեց. «Այս եօթը որոջները ստացիր ինձնից ի հաւաստումն այն բանի, թէ ես եմ փորել այդ ջրհորը»: Դրա համար էլ այդ վայրը կոչուեց Երդման ջրհոր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'որովհետեւ նրանք երկուսով միմեանց երդում տուեցին այնտեղ. Երդման ջրհորի մօտ հաշտութիւն կնքեցին: Աբիմելէքը, նրա սենեկապետ Ոքոզաթն ու նրա զօրքերի սպարապետ Փիքողը այնտեղից վեր կացան ու վերադարձան Փղշտացւոց երկիրը: որովհետեւ նրանք երկուսով միմեանց երդում տուեցին այնտեղ. Երդման ջրհորի մօտ հաշտութիւն կնքեցին: Աբիմելէքը, նրա սենեկապետ Ոքոզաթն ու նրա զօրքերի սպարապետ Փիքողը այնտեղից վեր կացան ու վերադարձան Փղշտացւոց երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Աբրահամը Երդման ջրհորի մօտ ծառ տնկեց, այնտեղ պաշտեց Տիրոջը, նրան կոչեց Աստուած յաւիտենական:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Աբրահամը Փղշտացւոց երկրում պանդուխտ մնաց երկար ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Այս դէպքերից յետոյ Աստուած փորձեց Աբրահամին: Նա ձայն տուեց նրան. «Աբրահա՛մ, Աբրահա՛մ»: Սա պատասխանեց. «Այստեղ եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Աստուած ասաց նրան. «Ա՛ռ քո միակ որդուն՝ քո սիրելի Իսահակին, գնա՛ մի բարձրադիր տեղ եւ այնտեղ՝ լերան վրայ, որ ցոյց կը տամ քեզ, ողջակիզի՛ր նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Աբրահամն առաւօտեան վեր կացաւ, համետը դրեց իր էշի վրայ, հետը վերցրեց երկու ստրուկ ծառաներ, իր որդի Իսահակին, ողջակիզութեան համար փայտ կոտրեց եւ ճանապարհ ընկաւ, եկաւ այն տեղը, որ Աստուած ասել էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Երրորդ օրը Աբրահամը բարձրացրեց իր աչքերը եւ հեռուից տեսաւ այդ տեղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Աբրահամն ասաց իր ծառաներին. «Նստեցէ՛ք այստեղ՝ էշի մօտ, իսկ ես ու այս պատանին գնանք այնտեղ, երկրպագութիւն անենք ու վերադառնանք ձեզ մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Աբրահամը վերցրեց ողջակիզութեան փայտը, դրեց այն իր որդի Իսահակի մէջքին, իր ձեռքն առաւ կրակն ու դանակը, եւ երկուսով գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Իսահակը դիմեց իր հօրը՝ Աբրահամին. «Հա՛յր»: Սա ասաց. «Ի՞նչ է, որդի՛ս»: Նա հարցրեց. «Ահա կրակը, եւ ահա փայտը, հապա ո՞ւր է ողջակիզելու ոչխարը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Սա պատասխանեց. «Աստուած կը հոգայ իր ողջակիզելու ոչխարի մասին, որդեա՛կ»: Նրանք երկուսով գնացին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'եւ հասան այն տեղը, որ նրան ցոյց էր տուել Աստուած: Աբրահամն այնտեղ զոհասեղան շինեց, վրան դրեց փայտը, իր որդի Իսահակին կապեց եւ դրեց զոհասեղանի փայտի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Աբրահամը երկարեց ձեռքը, որ վերցնի դանակն ու մորթի իր որդուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Տիրոջ հրեշտակը երկնքից ձայն տուեց նրան ու ասաց. «Աբրահա՛մ, Աբրահա՛մ»: Սա պատախանեց նրան. «Այստեղ եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Նա ասաց. «Ձեռք մի՛ տուր պատանուն, նրան որեւէ վնաս մի՛ պատճառիր, որովհետեւ այժմ համոզուեցի, որ դու երկիւղ ունես Աստծու նկատմամբ եւ ինձ համար չես խնայի քո որդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Աբրահամը բարձրացրեց իր աչքերը եւ տեսաւ, որ մացառուտ թփի մէջ եղջիւրներից մի խոյ է կախուած: Աբրահամը գնաց, առաւ խոյն ու այն ողջակիզեց իր որդի Իսահակի փոխարէն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Աբրահամն այդ վայրի անունը դրեց «Տէրը տեսաւ», եւ մինչեւ այսօր էլ ասում են՝ «Այդ լերան վրայ երեւաց Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Տիրոջ հրեշտակը երկնքից երկրորդ անգամ ձայն տալով՝ ասաց Աբրահամին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, '«Անձովս եմ երդւում, - ասում է Տէրը, - քանի որ դու արեցիր այդ բանը՝ ինձ համար չխնայեցիր քո սիրելի որդուն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'անչափ պիտի օրհնեմ քեզ եւ երկնքի աստղերի, ծովեզերքի աւազի չափ պիտի բազմացնեմ քո սերունդը: Քո սերունդը պիտի տիրանայ իր թշնամիների քաղաքներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'քո սերնդի շնորհիւ պիտի օրհնուեն աշխարհի բոլոր ազգերը այն բանի համար, որ անսացիր իմ ձայնին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Աբրահամը վերադարձաւ իր ծառաների մօտ: Նրանք միասին ելան գնացին դէպի Երդման ջրհորը, եւ Աբրահամը բնակուեց Երդման ջրհորի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Այս դէպքերից յետոյ Աբրահամին յայտնեցին, որ ահա Մեղքան եւս քո եղբայր Նաքորի համար ծնել է որդիներ՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'անդրանիկ որդի Ովքին, նրա եղբայր Բաւին, ասորիների նախահայր Կամուէլին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Քասադին, Ազաւին, Փալդասին, Յետդափին եւ Բաթուէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Եւ Բաթուէլը ծնել է Ռեբեկային: Սրանք են այն ութ որդիները, որոնց ծնեց Մեղքան Աբրահամի եղբայր Նաքորի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Նրա հարճը, որի անունը Ռեէմա էր, նա էլ ծնեց Տաբեկին, Դաամին, Տոքոսին եւ Մոքային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Սառան դարձաւ հարիւր քսանեօթը տարեկան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Նա մեռաւ կիրճի մէջ գտնուող Արբոկ քաղաքում: Սա Քանանացիների երկրում գտնուող Քեբրոնն է: Աբրահամը եկաւ, որ ողբայ ու սգայ Սառայի մահը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Աբրահամը հեռացաւ իր հանգուցեալի մօտից եւ դիմելով Քետի որդիներին՝ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '«Ես ձեր մէջ պանդուխտ ու օտարական եմ: Արդ, որպէս սեփականութիւն ինձ մի գերեզմանի հող տուէ՛ք ձեզ մօտ, որ թաղեմ իմ հանգուցեալին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Քետի որդիները պատասխան տուեցին Աբրահամին՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '«Լսի՛ր մեզ, տէ՛ր: Դու մեր մէջ Աստծու նշանակած թագաւորն ես: Քո հանգուցեալին թաղի՛ր մեր լաւագոյն գերեզմաններից մէկում, որովհետեւ մեզնից ոչ մէկը չի հրաժարուի քեզ շիրիմի համար տեղ տրամադրելուց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Աբրահամը ելաւ եւ գլուխ տուեց այդ երկրի ժողովրդին՝ Քետի որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Աբրահամը նրանց դիմելով՝ ասաց. «Եթէ դուք յօժար էք, որ իմ հանգուցեալին ես անձամբ թաղեմ, լսեցէ՛ք ինձ եւ իմ մասին բարեխօսեցէ՛ք Սահառի որդի Եփրոնին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'որ ինձ տայ իր ագարակի սահմաններում գտնուող զոյգ քարայրը այնքան արծաթով, որքան արժէ այն: Թող այն ձեր ներկայութեամբ ինձ տայ որպէս շիրմավայր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Եփրոնը քետացիների հետ նստած էր ժողովատեղում: Եփրոն քետացին պատասխան տուեց Աբրահամին եւ ի լուր Քետի որդիների ու բոլոր նրանց, ովքեր մտնում էին նրա քաղաքի դարպասով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'ասաց. «Նայի՛ր ինձ, տէ՛ր, եւ լսի՛ր ինձ: Ագարակը տալիս եմ քեզ, քեզ եմ տալիս նաեւ այնտեղ գտնուող քարայրը: Իմ բոլոր համաքաղաքացիների ներկայութեամբ այն քեզ եմ յանձնում: Թաղի՛ր քո հանգուցեալին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Աբրահամը գլուխ տուեց երկրի ժողովրդի առաջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Եփրոնի հետ խօսեց ի լուր երկրի ժողովրդի եւ ասաց. «Քանի որ անսացիր ինձ, ուրեմն լսի՛ր ինձ: Ես քեզ կը տամ ագարակի փոխարժէքը: Վերցրո՛ւ այն ինձնից, եւ ես այնտեղ կը թաղեմ իմ հանգուցեալին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Եփրոնն Աբրահամին պատասխանեց եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '«Ո՛չ, տէ՛ր իմ, լսել եմ, որ հողամասը չորս հարիւր սատեր արծաթ արժէ: Դա ի՞նչ է որ իմ ու քո միջեւ: Դու թաղի՛ր քո հանգուցեալին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Աբրահամը Եփրոնին լսելուց յետոյ կշռեց եւ նրան վճարեց չորս հարիւր սատեր արծաթը, ինչպէս խոստացել էր ի լուր Քետի որդիների, վաճառականների մօտ ընդունուած գնով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Եփրոնի ագարակը, որ Մամբրէի կաղնու հանդիպակաց զոյգ քարայրի մօտն էր, այսինքն՝ ագարակն ու նրա մէջ գտնուող քարայրը, ագարակի եւ նրա շրջակայքի բոլոր ծառերը դարձան Աբրահամի սեփականութիւնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Քետի որդիների ներկայութեամբ, որոնք մտնում էին քաղաքի դարպասով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Դրանից յետոյ Աբրահամն իր կին Սառային թաղեց ագարակի զոյգ քարայրում, որ Մամբրէի կաղնու դիմաց էր գտնւում, այսինքն՝ Քեբրոնում՝ Քանանացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Ագարակն ու նրա մէջ գտնուող քարայրը Քետի որդիների կողմից տրուեցին Աբրահամին իբրեւ նրա սեփական գերեզմանոց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Աբրահամը ծերացել էր, տարիքն առել: Եւ Տէրն օրհնեց Աբրահամին ըստ ամենայնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Աբրահամն ասաց իր տան աւագագոյն ծառային՝ իր ամբողջ ունեցուածքի կառավարչին. «Ձեռքդ դի՛ր իմ ազդրի տակ եւ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'քեզ երդուեցնեմ Տիրոջ՝ երկնքի Աստծու եւ երկրի Աստծու անունով, որ իմ որդի Իսահակի համար կին չես առնի քանանացիների դուստրերից (որոնց մէջ եմ բնակւում ես),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'այլ կը գնաս այն երկիրը, որտեղ ծնուել եմ, իմ տունը, եւ այնտեղից իմ որդի Իսահակի համար կին կ՚առնես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Ծառան նրան պատասխանեց. «Գուցէ կինը չցանկանայ ինձ հետ գալ այս երկիրը: Այդ դէպքում ես տանե՞մ քո որդուն այն երկիրը, որտեղ ծնուել ես դու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Աբրահամն ասաց. «Զգո՛յշ եղիր, իմ որդուն այնտեղ չվերադարձնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Երկնքի Տէր Աստուածը եւ երկրի Տէր Աստուածը, որն ինձ հանեց իմ հօր տնից ու այն երկրից, ուր ծնուել եմ, որը խօսեց ինձ հետ, երդուեց ինձ ու ասաց, թէ՝ «Քո սերունդներին եմ տալու այդ երկիրը», նա իր հրեշտակին կ՚ուղարկի քո առաջ, եւ այնտեղից կին կ՚առնես իմ որդի Իսահակի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Իսկ եթէ կինը չուզենայ քեզ հետ գալ այս երկիրը, քո տուած երդումից անպարտ համարուես, միայն թէ իմ որդուն այնտեղ չվերադարձնես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Աբրահամի ծառան ձեռքը դրեց իր տիրոջ ազդրի տակ եւ երդուեց նրան այդ բանի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Ծառան առաւ իր տիրոջ ուղտերից տասը ուղտ եւ գնաց՝ իր հետ ունենալով իր տիրոջ բոլոր բարիքներից: Նա ելաւ գնաց Միջագետք, Նաքորի քաղաքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Երեկոյեան ուղտերին նստեցրեց քաղաքից դուրս, ջրհորի մօտ այն պահին, երբ ջրուորը դուրս է գալիս ջրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Նա ասաց. «Իմ տէր Աբրահամի Տէր Աստուած, այսօր ինձ յաջողութիւն պարգեւի՛ր եւ ողորմի՛ր իմ տէր Աբրահամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Ահա ես ջրի աղբիւրի մօտ եմ, եւ այս քաղաքի բնակիչների դուստրերը գալիս են ջուր հանելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Թող լինի մի կոյս, որին ասեմ՝ «Թեքի՛ր սափորդ, որ խմեմ», իսկ նա ինձ պատասխանի՝ «Խմի՛ր, քո ուղտերին էլ ջուր կը տամ, մինչեւ որ յագենան խմելուց»: Թող նրան էլ նախատեսած լինես քո ծառայ Իսահակի համար, եւ դրանով էլ իմանամ, որ բարեհաճ ես եղել իմ տէր Աբրահամի նկատմամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Նա մտքում դեռ չէր վերջացրել իր խօսքը, երբ եկաւ Ռեբեկան, որը Աբրահամի եղբայր Նաքորի Մեղքա կնոջ որդի Բաթուէլի դուստրն էր: Նա ուսին սափոր ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Կոյսը դէմքով շատ գեղեցիկ էր, մի աղջիկ, որին դեռ տղամարդ չէր մօտեցել: Նա իջաւ աղբիւրի մօտ, լցրեց իր սափորն ու ելաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Ծառան ընդառաջ գնաց նրան ու ասաց. «Այդ սափորից ինձ մի քիչ ջո՛ւր տուր խմելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Նա պատասխանեց. «Խմի՛ր, տէ՛ր»: Նա իր սափորը փութով իջեցրեց իր թեւերի վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'ջուր տուեց նրան, մինչեւ որ դադարեց խմելուց: Ապա աւելացրեց. «Քո ուղտերի համար էլ ջուր կը հանեմ, այնքան, որ բոլորն էլ յագենան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Նա սափորի ջուրն իսկոյն թափեց գուռի մէջ եւ նորից գնաց ջրհորը՝ ջուր հանելու: Նա նրա բոլոր ուղտերի համար ջուր հանեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Մարդն ուշադիր հետեւում էր նրան ու լուռ մտածում, թէ Տէրը կը յաջողեցնի՞ իր գործը, թէ՞ ոչ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Երբ բոլոր ուղտերը յագեցան, մարդը նրան տուեց ոսկէ գինդեր՝ իւրաքանչիւրը մէկ դահեկանի քաշով, եւ տասը դահեկանի քաշով երկու ապարանջան դրեց նրա ձեռքերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Նա հարցրեց նրան ու ասաց. «Ու՞մ դուստրն ես դու, յայտնի՛ր ինձ, քո տանը մեզ համար իջեւանելու տեղ կա՞յ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Սա պատասխանեց նրան. «Ես Մեղքայի եւ Նաքորի որդի Բաթուէլի դուստրն եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Ապա աւելացրեց. «Յարդ ու խոտ շատ ունենք, նաեւ իջեւանելու տեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Մարդն ուրախացաւ, երկրպագեց Աստծուն եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, '«Օրհնեալ է իմ տէր Աբրահամի Տէր Աստուածը, որ իմ տիրոջը չզրկեց իր արդարութիւնից ու ճշմարտութիւնից: Տէրն ինձ յաջողութիւն պարգեւեց իմ տիրոջ եղբօր տանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Գնաց աղջիկն ու կատարուածի մասին պատմեց իր մօր տանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Ռեբեկան ունէր Լաբան անունով մի եղբայր: Լաբանը գնաց դուրս՝ դէպի աղբիւրը, այդ մարդու մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Երբ նա տեսաւ գինդերն ու իր քրոջ ձեռքերի ապարանջանները, եւ իր քոյր Ռեբեկայից լսած լինելով, թէ՝ «Այսպէս խօսեց ինձ հետ այդ մարդը»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'մօտեցաւ մարդուն, որ դեռ կանգնած էր իր ուղտերի կողքին, աղբիւրի մօտ, եւ ասաց նրան. «Արի տուն մտի՛ր, Տիրոջով օրհնեալ, ինչո՞ւ ես մնացել դրսում: Ես քեզ համար տուն եւ քո ուղտերի համար տեղ եմ պատրաստել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Մարդը մտաւ տուն, իսկ Լաբանը ուղտերի վրայից հանեց թամբերը: Ուղտերին յարդ ու խոտ տուեցին եւ ջուր՝ նրա ու նրա հետ եկածների ոտքերը լուալու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Նրանց առաջ հաց դրեցին, որ ուտեն: Ծառան ասաց. «Չեմ ուտի, մինչեւ չասեմ ասելիքս»: Նրանք ասացին. «Խօսի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Նա ասաց. «Ես Աբրահամի ծառան եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Տէրը մեծապէս օրհնեց իմ տիրոջը, եւ նա մեծ մարդ դարձաւ: Աստուած նրան արջառ ու ոչխար, արծաթ ու ոսկի, ծառաներ ու աղախիններ, ուղտեր ու էշեր տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Սառան՝ իմ տիրոջ կինը, ծերունական հասակում գտնուող իմ տիրոջը պարգեւեց մի որդի, որին իմ տէրը յանձնեց այն ամէնը, ինչ ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Իմ տէրն ինձ երդուեցնելով ասաց. «Իմ որդի Իսահակի համար քանանացիների աղջիկներից կին չառնես, այն քանանացիների, որոնց երկրում ես պանդխտեցի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'այլ կը գնաս իմ հօր տունը, իմ տոհմի մէջ եւ այնտեղից կին կը բերես իմ որդու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ես իմ տիրոջն ասացի. «Գուցէ կինն ինձ հետ չգայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Նա ասաց ինձ. «Իմ Տէր Աստուածը, որի հանդէպ վարուեցի այնպէս, ինչպէս հաճոյ էր նրան, քեզ հետ կ՚ուղարկի իր հրեշտակին, կը յաջողեցնի քո գործը, եւ դու իմ որդու համար կին կ՚առնես իմ ազգից ու իմ հօր տնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Ա՛յն ժամանակ դու ազատուած կը լինես իմ նզովքից: Իսկ եթէ գնաս իմ տոհմի մէջ, եւ կին չտան, ինձ տուած երդումից ազատ կը լինես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Երբ այսօր աղբիւրի մօտ եկայ, ասացի. «Իմ տէր Աբրահամի Տէր Աստուած, եթէ յաջողեցնելու ես իմ գործը, որի համար ես այժմ եկել եմ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ահա հասել եմ ջրի աղբիւրի մօտ, եւ քաղաքի մարդկանց դուստրերը գալիս են ջուր հանելու: Եւ այն կոյսը, որին ասեմ, թէ՝ ՚ Քո սափորից մի քիչ ջուր տո՛ւր խմելու»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'եւ նա ասի ինձ, թէ՝ ՚ Խմի՛ր, քո ուղտերի համար էլ ջուր կը հանեմ», նա էլ կը լինի այն կինը, որին նախատեսել է Տէրը իր ծառայ Իսահակի համար, որովհետեւ դրանից էլ կ՚իմանամ, որ բարեհաճ ես եղել իմ տէր Աբրահամի նկատմամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Դեռ իմ մտքում չէի վերջացրել իմ խօսքը, երբ իսկոյն երեւաց Ռեբեկան: Նա իր ուսին սափոր ունէր: Նա իջաւ աղբիւրը եւ ջուր հանեց: Ես ասացի նրան. «Ինձ ջուր տո՛ւր խմելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Նա իր ուսից փութով իջեցրեց սափորն ու ասաց. «Դու խմի՛ր, յետոյ քո ուղտերին էլ ջուր կը տամ»: Ես խմեցի, եւ նա իմ ուղտերին էլ ջուր տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Ես նրան հարցրի ու ասացի. «Դու ո՞ւմ դուստրն ես, ասա՛ ինձ»: Նա պատասխանեց. «Ես Մեղքայի եւ Նաքորի որդի Բաթուէլի դուստրն եմ»: Ես գինդեր դրեցի նրա ականջներին, ապարանջաններ՝ նրա ձեռքերին եւ ուրախացայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'երկրպագեցի Տիրոջը, օրհնեցի իմ տէր Աբրահամի Տէր Աստծուն, որ յաջողութիւն պարգեւեց իմ ազնիւ գործին՝ իմ տիրոջ եղբօր աղջկան կին առնելու նրա որդու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Արդ, եթէ իմ տիրոջ նկատմամբ շնորհ եւ արդար գործ էք անելու, ասացէ՛ք ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Իսկ եթէ ոչ, ցո՛յց տուէք ինձ, ա՞ջ գնամ, թէ՞ ձախ»: Պատասխան տուեցին Լաբանն ու Բաթուէլը եւ ասացին. «Տէրն է այսպէս կարգադրել, մենք չենք կարող դրական կամ բացասական պատասխան տալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Ահա Ռեբեկան առաջդ կանգնած է, ա՛ռ եւ գնա՛: Նա թող լինի քո տիրոջ որդու կինը, ինչպէս կարգադրել է Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Երբ Աբրահամի ծառան լսեց նրանց խօսքերը, երկրպագեց Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Ծառան հանեց ոսկէ ու արծաթէ զարդեր եւ զգեստներ, տուեց Ռեբեկային: Նա նուէրներ տուեց նաեւ նրա եղբայրներին ու մօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Կերան ու խմեցին նա եւ այն մարդիկ, որոնք նրա հետ էին, եւ ապա քնեցին: Առաւօտեան վեր կենալով՝ նա ասաց. «Ճանապարհեցէ՛ք ինձ, որ գնամ տիրոջս մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Ռեբեկայի եղբայրներն ու մայրը ասացին. «Թող աղջիկը մեզ մօտ մնայ մի տասը օր, յետոյ թող գնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Ծառան ասաց նրանց. «Ինձ մի՛ պահէք, որովհետեւ Տէրը յաջողութիւն է պարգեւել իմ գործին: Թողէ՛ք որ գնամ տիրոջս մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Ռեբեկայի եղբայրներն ասացին. «Կանչենք աղջկան եւ նրան հարցնենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Նրանք կանչեցին Ռեբեկային ու հարցրին. «Կը գնա՞ս այս մարդու հետ»: Նա պատասխանեց. «Կը գնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Նրանք ճանապարհեցին իրենց քոյր Ռեբեկային իր ունեցուածքով, ինչպէս նաեւ Աբրահամի ծառային ու նրանց, ովքեր նրա հետ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Նրանք օրհնելով Ռեբեկային՝ ասացին նրան. «Քո՛յր մեր, հազար ու բիւր դառնաս: Քո յետնորդները թող տիրանան քո թշնամիների քաղաքներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Ռեբեկան ու իր նաժիշտները վեր կացան, նստեցին ուղտերի վրայ եւ այդ մարդու հետ ճանապարհ ընկան: Ծառան Ռեբեկային առնելով գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Իսահակը եկել էր անապատ՝ Տեսիլքի ջրհորի մօտ, որովհետեւ բնակւում էր երկրի հարաւային կողմում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Իսահակը երեկոյեան ելաւ դաշտ՝ զբօսնելու: Նա իր աչքերը բարձրացնելով՝ տեսաւ, որ գալիս են տասը ուղտեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Աչքերը վեր բարձրացրեց նաեւ Ռեբեկան եւ տեսաւ Իսահակին: Նա անմիջապէս իջաւ ուղտից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'եւ հարցրեց ծառային. «Ո՞վ է այն մարդը, որ դաշտում մեզ ընդառաջ է գալիս»: Ծառան պատասխանեց. «Նա իմ տէրն է»: Ռեբեկան առաւ քողն ու գցեց իր վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Ծառան Իսահակին պատմեց այն ամէնը, ինչ արել էր ինքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Իսահակը մտաւ իր մօր՝ Սառայի տունը, առաւ Ռեբեկային, եւ սա դարձաւ նրա կինը: Իսահակը սիրեց նրան եւ մխիթարուեց իր մօր՝ Սառայի սգից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Աբրահամն առաւ մի կին էլ, որի անունը Քետտուրա էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Սա նրա համար ծնեց Զեմրանին, Յեկսանին, Մադանին, Մադիանին, Յեսբոկին եւ Սովիւէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Յեկսանը ծնեց Սաբային, Թեմանին եւ Դադանին: Դադանի որդիներն էին Ռագուէլը, Նաբդեէլը, Ասուրիիմը, Լատուսիիմը եւ Լովովմիմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Մադիամի որդիներն էին Գեփարը, Ափերը, Ենոքը, Աբիդան եւ Եդրագան: Սրանք բոլորը Քետտուրայի որդիներն էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Աբրահամն իր ողջ ունեցուածքը տուեց իր որդի Իսահակին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'իսկ իր հարճերի որդիներին, որոնք Աբրահամից էին, պարգեւներ տուեց եւ, քանի դեռ կենդանի էր, նրանց հեռացրեց իր որդի Իսահակի մօտից դէպի արեւելք՝ արեւելեան երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Աբրահամն ապրեց հարիւր եօթանասունհինգ տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Աբրահամը հոգին աւանդեց ու մեռաւ երջանիկ ծերութեան մէջ, զառամեալ, ալեւորած տարիքում, եւ գնաց միացաւ իր նախնիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Նրա որդիներ Իսահակն ու Իսմայէլը նրան թաղեցին քետացի Սահառի որդի Եփրոնի ագարակի զոյգ քարայրում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'որը գտնւում է Մամբրէի կաղնու դիմաց: Աբրահամին ու նրա կին Սառային թաղեցին այն ագարակում ու քարայրում, որ Աբրահամը Քետի որդիներից էր գնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Աբրահամի մահից յետոյ Աստուած օրհնեց նրա որդի Իսահակին, եւ Իսահակը բնակուեց Տեսիլքի ջրհորի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Սրանք են սերուդները Աբրահամի որդի Իսմայէլի, որին ծնեց եգիպտուհի Ագարը՝ Սառայի աղախինը, Աբրահամի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Ահա Իսմայէլի որդիների անուններն ըստ նրանց ցեղերի. Իսմայէլի անդրանիկը՝ Նաբեոթ, ապա Կեդար, Աբդեէլ, Մաբսամ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Մասմա, Իդումա, Մասէ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Քոլդադ, Թեմա, Յետուր, Նափէս եւ Կեդմա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Սրանք են Իսմայէլի որդիները, եւ սրանք են նրանց անուններն ըստ իրենց բնակավայրերի եւ իրենց վրանների, նրանց տասներկու իշխաններն ըստ իրենց ցեղերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Իսմայէլն ապրեց հարիւր երեսունեօթը տարի: Նա հոգին աւանդեց ու մեռաւ եւ գնաց միացաւ իր նախնիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Նա բնակութիւն հաստատեց Եւիլայից մինչեւ Սուր, որը գտնւում է Եգիպտոսի դիմաց, մինչեւ Ասորեստանի սահմանները: Նա բնակուեց իր բոլոր եղբայրների դէմ յանդիման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Սրանք են Աբրահամի որդի Իսահակի սերունդները. Աբրահամը ծնեց Իսահակին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Իսահակը քառասուն տարեկան էր, երբ ամուսնացաւ Ասորական Միջագետքում ապրող ասորի Բաթուէլի դուստր Ռեբեկայի հետ, որը ասորի Լաբանի քոյրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Իսահակն աղաչեց Տիրոջը իր կին Ռեբեկայի համար, որովհետեւ սա ամուլ էր: Աստուած լսեց նրան, եւ նրա կին Ռեբեկան յղիացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Նրա արգանդում իրար էին բախւում երեխաները: Նա ասաց. «Եթէ այսպէս էր լինելու ինձ, հապա ինչո՞ւ յղիացայ»: Եւ նա գնաց այդ մասին Տիրոջը հարցնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Տէրը նրան ասաց. «Քո արգանդում երկու ցեղ կայ, քո արգանդից երկու ժողովուրդ պիտի ծնուի: Մի ժողովուրդը միւս ժողովրդին պիտի գերիշխի, եւ աւագը կրտսերին պիտի ենթարկուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Երբ հասան նրա ծննդաբերելու օրերը, նրա որովայնում երկու երեխաներ կային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Անդրանիկ որդին ծնուեց բոլորովին շէկ, թաւամազ մորթով, եւ հայրը նրան կոչեց Եսաւ: Ապա Եսաւի գարշապարից բռնած ծնուեց նրա եղբայրը: Սրան էլ կոչեց Յակոբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Իսահակը վաթսուն տարեկան էր, երբ Ռեբեկան ծնեց նրանց: Մանուկները մեծացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Եսաւը հմուտ որսորդ էր եւ վայրենաբարոյ, իսկ Յակոբը մեղմաբարոյ էր ու տնակեաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Իսահակը սիրեց Եսաւին, որովհետեւ նրա որսը կերակուր էր իր համար, իսկ Ռեբեկան սիրեց Յակոբին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Յակոբը մի անգամ ապուր էր եփել, երբ Եսաւը դաշտից եկաւ քաղցից թուլացած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Եսաւն ասաց Յակոբին. «Այդ կարմրաւուն ապուրից տուր ուտեմ, որովհետեւ քաղցից թուլացած եմ» (դրա համար էլ նրան Եդոմ կոչեցին):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Յակոբն ասաց Եսաւին. «Կը տամ, եթէ այսօր ինձ վաճառես քո անդրանկութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Եսաւը պատասխանեց. «Ես մեռնելու վրայ եմ, էլ ինչի՞ս է պէտք անդրանկութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Յակոբն ասաց նրան. «Հէնց այսօր երդուի՛ր ինձ»: Եւ նա երդուեց նրան: Եսաւն իր անդրանկութիւնը վաճառեց Յակոբին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'իսկ Յակոբը Եսաւին տուեց հաց ու ոսպապուր: Սա կերաւ, խմեց ու վեր կացաւ գնաց: Այսպիսով Եսաւն արհամարհեց իր անդրանկութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Սով եղաւ երկրում. ոչ այն սովը, որ եղել էր Աբրահամի ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Իսահակը գնաց փղշտացիների արքայ Աբիմելէքի մօտ, Գերարա: Նրան երեւաց Տէրն ու ասաց. «Եգիպտոս մի՛ իջիր, այլ բնակուի՛ր այն երկրում, որտեղ ասացի քեզ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'իբրեւ պանդուխտ ապրի՛ր այս երկրում, որ ես լինեմ քեզ հետ եւ օրհնեմ քեզ, որովհետեւ քեզ ու քո սերունդներին եմ տալու այս ողջ երկիրը: Ես հաստատ կը պահեմ այն երդումը, որ տուեցի քո հայր Աբրահամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Ես բազմացնելու եմ քո սերունդները երկնքի աստղերի չափ, քո զաւակներին եմ տալու այս ամբողջ երկիրը, եւ քո սերունդների միջոցով օրհնուելու են երկրի բոլոր ազգերը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'ի հատուցումն այն բանի, որ քո հայր Աբրահամը լսեց իմ խօսքը, պահեց իմ հրամանները, իմ պատուիրանները, իմ կանոններն ու օրէնքները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Իսահակը բնակուեց գերարացիների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Տեղի մարդիկ հարցրին նրա կին Ռեբեկայի մասին, եւ նա ասաց. «Իմ քոյրն է»: Նա վախեցաւ ասել «Իմ կինն է». գուցէ Ռեբեկայի պատճառով տեղի մարդիկ սպանէին իրեն, որովհետեւ Ռեբեկան դէմքով գեղեցիկ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Նա այնտեղ մնաց երկար ժամանակ: Փղշտացիների արքայ Աբիմելէքը պատուհանից դուրս ձգուեց ու տեսաւ, որ Իսահակը կատակում է իր կին Ռեբեկայի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Աբիմելէքը կանչեց Իսահակին եւ ասաց նրան. «Ուրեմն նա քո կինն է: Ինչո՞ւ, սակայն, ասացիր, թէ՝ «Իմ քոյրն է»: Իսահակն ասաց նրան. «Որովհետեւ մտածեցի, թէ գուցէ նրա պատճառով սպանուեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Աբիմելէքը նրան ասաց. «Ինչո՞ւ այդ բանն արեցիր մեզ հետ: Քիչ էր մնում, որ իմ ազգակիցներից մէկը պառկէր քո կնոջ հետ եւ մեզ մեղքի մէջ գցէիր»: Եւ Աբիմելէքը հրաման արձակեց իր ողջ ժողովրդին՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, '«Բոլոր նրանք, ովքեր կը դիպչեն այդ մարդուն կամ նրա կնոջը, մահուան կը դատապարտուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Իսահակը գարի ցանեց այդ երկրում եւ նոյն տարում էլ հարիւրապատիկ բերք ստացաւ: Տէրն օրհնեց նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'եւ սա հարստացաւ: Նա առաջադիմում էր, հարստանում այն աստիճան, որ մեծահարուստ դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Նա ունեցաւ ոչխարի ու արջառի հօտեր, բազում կալուածքներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Փղշտացիները նախանձեցին նրան եւ խցանեցին այն բոլոր ջրհորները, որ նրա հօր՝ Աբրահամի օրօք փորել էին նրա ծառաները. փղշտացիները');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'դրանք լցրին հողով: Աբիմելէքն ասաց Իսահակին. «Հեռացի՛ր մեր մօտից, որովհետեւ մեզնից շատ աւելի զօրաւոր եղար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Իսահակն այդտեղից գնաց ու վրան խփեց գերարացիների ձորում: Նա բնակուեց այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Իսահակը դարձեալ փորեց այն ջրհորները, որ փորել էին նրա հօր՝ Աբրահամի ծառաները, իսկ փղշտացիները նրա հայր Աբրահամի մահից յետոյ խցանել էին: Իսահակն այդ ջրհորները կոչեց այն անուններով, որ տուել էր դրա նց իր հայր Աբրահամը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Իսահակի ծառաները հող փորեցին գերարացիների ձորում եւ այնտեղ գտան ըմպելի ջրի աղբիւր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Գերարացիների հովիւները կռուեցին Իսահակի հովիւների հետ՝ ասելով, թէ իրենցն է այդ ջրհորը: Նրանք ջրհորը կոչեցին Անիրաւութիւն, քանի որ նրա հանդէպ անիրաւութիւն էին գործել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Իսահակը գնաց այդտեղից ու փորեց մի այլ ջրհոր եւս: Վէճ ծագեց սրա համար էլ: Իսահակը այն կոչեց Թշնամութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Նա գնաց այդտեղից եւ փորեց մի այլ ջրհոր եւս: Դրա շուրջ վէճ չառաջացաւ, եւ այդ պատճառով այն կոչեց Անդորրութիւն՝ ասելով, թէ՝ «Այժմ մեզ ընդարձակ տեղ տուեց Տէրը եւ բազմացրեց մեզ երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Իսահակն այդտեղից գնաց Երդման ջրհորի մօտ: Տէրն այդ գիշեր երեւաց նրան ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, '«Ես քո հօր Աստուածն եմ: Մի՛ վախեցիր, որովհետեւ քեզ հետ եմ, ես օրհնելու եմ քեզ, բազմացնելու եմ քո սերունդները ի սէր քո հայր Աբրահամի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Իսահակն այդտեղ զոհասեղան շինեց ու երկրպագեց Տիրոջը: Նա այդտեղ խփեց իր վրանը: Իսահակի ծառաները այդտեղ ջրհոր փորեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Գերարայից նրա մօտ գնացին Աբիմելէքը, նրա սենեկապետ Ոքոզաթը եւ նրա զօրքերի սպարապետ Փիքողը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Իսահակը նրանց ասաց. «Ինչո՞ւ եկաք ինձ մօտ, չէ՞ որ դուք ատեցիք ինձ եւ հալածեցիք ձեր մօտից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Նրանք պատասխանեցին. «Մենք պարզիպարզոյ տեսանք, որ Տէրը քեզ հետ է, ուստի ասացինք. «Հաշտութիւն թող լինի մեր եւ քո միջեւ: Մենք պայման թող դնենք քեզ հետ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'մեր նկատմամբ որեւէ վատ բան չանես, քանի որ մենք չենք մեղանչել քո դէմ, քեզ բարերարութիւն ենք արել եւ քեզ խաղաղութեամբ ճանապարհ դրել, որովհետեւ դու Տիրոջ օրհնած մարդն ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Իսահակը նրանց պատուին խնջոյք սարքեց, նրանք կերան, խմեցին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'եւ առաւօտեան վաղ վեր կենալով՝ երդուեցին միմեանց: Իսահակը ճանապարհ դրեց նրանց, եւ նրանք իր մօտից հաշտ ու խաղաղ գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Այդ օրը եկան Իսահակի ծառաները եւ յայտնեցին նրան իրենց փորած ջրհորի մասին, թէ՝ «Ջուր չենք գտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Իսահակն այդ ջրհորն անուանեց Երդումն: Դրա համար էլ այդ քաղաքը մինչեւ այսօր կոչւում է Երդման ջրհոր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Եսաւը քառասուն տարեկան հասակում կին առաւ քետացի Բէերի դուստր Յուդիթին եւ խեւացի Ելոմի դուստր Մասեմաթին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'որոնք վշտացնում էին Իսահակին եւ Ռեբեկային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Երբ Իսահակը ծերացաւ, եւ վատացաւ նրա աչքի տեսողութիւնը, կանչեց իր աւագ որդի Եսաւին ու ասաց նրան. «Որդեա՛կ իմ»: Սա ասաց. «Այստեղ եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Նա ասաց նրան. «Ահա ես ծերացել եմ եւ չգիտեմ, թէ երբ կը մեռնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Արդ, ա՛ռ քո զէնքը՝ աղեղն ու կապարճը, գնա՛ դաշտ եւ ինձ համար ո՛րս արա,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'ինձ համար պատրաստի՛ր իմ սիրած խորտիկները եւ բե՛ր, մատուցի՛ր ինձ, որ ուտեմ եւ օրհնեմ քեզ, քանի դեռ կենդանի եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Ռեբեկան լսեց այն, ինչ ասաց Իսահակն իր որդուն: Եսաւը գնաց դաշտ, որ որս անի իր հօր համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'իսկ Ռեբեկան, դիմելով իր որդի Յակոբին, ասաց. «Ես քո հօրից լսեցի այն, ինչ նա ասում էր քո եղբօրը: Նա նրան ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '«Ինձ ո՛րս բեր եւ ինձ համար խորտիկներ պատրաստի՛ր, որ ուտեմ եւ օրհնեմ քեզ Տիրոջ առաջ, քանի դեռ կենդանի եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Արդ, որդեա՛կ իմ, լսի՛ր, թէ ինչ եմ ասում քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Գնա՛ եւ հօտի միջից ինձ երկու մատղաշ ու ընտիր ուլ բե՛ր, որ դրանցով քո հօր համար նրա սիրած խորտիկները պատրաստեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Դու այն կը մատուցես քո հօրը, որ ուտի եւ քեզ օրհնի քո հայրը, քանի դեռ կենդանի է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Յակոբն ասաց իր մայր Ռեբեկային. «Իմ եղբայր Եսաւը մազոտ մարդ է, իսկ ես՝ լերկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Գուցէ շօշափի ինձ իմ հայրը, ես խայտառակ լինեմ նրա առաջ, եւ օրհնութեան փոխարէն անէծք թափուի գլխիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Մայրը նրան ասաց. «Թող ինձ վրայ լինի այդ անէծքը, որդեա՛կ, միայն թէ լսի՛ր իմ ասածը, գնա դրանք բե՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Նա գնաց եւ ուլերը բերեց իր մօր մօտ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'իսկ սա նրա հօր սիրած խորտիկները պատրաստեց: Ռեբեկան առաւ աւագ որդու ընտիր պատմուճանը, որ կար իր տանը, հագցրեց իր կրտսեր որդի Յակոբին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'ուլի մորթին փաթաթեց նրա թեւերին ու մերկ պարանոցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Նա իր պատրաստած խորտիկներն ու հացը տուեց իր որդի Յակոբի ձեռքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Սա տարաւ դրանք իր հօրն ու ասաց. «Հա՛յր իմ»: Նա ասաց. «Այստեղ եմ»: Հայրը հարցրեց. «Դու ո՞վ ես, որդեա՛կ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Յակոբը պատասխանեց հօրը. «Ես Եսաւն եմ՝ քո անդրանիկ որդին: Արեցի այնպէս, ինչպէս ասացիր ինձ: Արի նստի՛ր ու կե՛ր իմ որսից, որ օրհնես ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Իսահակն ասաց որդուն. «Այդ ինչպէ՞ս է, որ այդքան շուտ որս գտար, որդեա՛կ»: Նա պատասխանեց. «Ինչպէս Աստուած ինքը դրեց իմ առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Իսահակն ասաց Յակոբին. «Մօ՛տ արի, որ շօշափեմ քեզ, որդեա՛կ, որպէսզի իմանամ, թէ դո՞ւ ես իմ որդի Եսաւը, թէ՞ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Յակոբը մօտեցաւ իր հայր Իսահակին, սա շօշափեց նրան ու ասաց. «Ձայնդ Յակոբի ձայնն է, բայց ձեռքերդ Եսաւի ձեռքերն են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Իսահակը չճանաչեց նրան, որովհետեւ նրա ձեռքերը իր եղբայր Եսաւի ձեռքերի նման մազոտ էին: Նա օրհնեց նրան ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, '«Դո՞ւ ես իմ որդի Եսաւը»: Նա պատասխանեց. «Ես եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Իսահակն ասաց. «Մատուցի՛ր ինձ, որ ուտեմ քո որսից, որդեա՛կ, որպէսզի օրհնեմ քեզ»: Յակոբը մատուցեց նրան, եւ նա կերաւ: Նրան գինի բերեց, եւ նա խմեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Նրա հայր Իսահակը ասաց նրան. «Մօ՛տ արի եւ համբուրի՛ր ինձ, որդեա՛կ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Յակոբը մօտեցաւ, համբուրեց նրան: Իսահակն առաւ նրա հագուստի հոտը եւ օրհնելով նրան՝ ասաց. «Իմ որդին Տիրոջ օրհնած բերրի արտի հոտն ունի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Թող Աստուած քեզ մաս հանի երկնքի ցօղից, երկրի պարարտութիւնից եւ ցորենի ու գինու առատութիւն պարգեւի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Թող քեզ ծառայեն ժողովուրդները, եւ իշխանները թող քեզ երկրպագեն: Քո եղբօր տէրը լինես, թող քեզ երկրպագեն քո հօր որդիները: Ով անիծի քեզ, ինքն անիծեալ թող լինի, իսկ ով օրհնի քեզ, ինքն օրհնեալ թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Երբ Իսահակը իր որդի Յակոբին օրհնելը վերջացրեց, եւ Յակոբը գնաց իր հայր Իսահակի մօտից, որսից եկաւ նրա եղբայր Եսաւը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Սա եւս խորտիկներ պատրաստեց եւ մատուցելով իր հօրը՝ ասաց. «Թող վեր կենայ իմ հայրը, ուտի իր որդու որսից, որպէսզի օրհնի ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Եսաւի հայր Իսահակը հարցրեց նրան. «Ո՞վ ես դու»: Սա պատասխանեց. «Ես Եսաւն եմ՝ քո անդրանիկ որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Իսահակը մեծապէս զարմացաւ ու ասաց. «Իսկ այն ո՞վ էր, որ ինձ համար որս որսաց, բերեց մատուցեց, ես կերայ ամենից, երբ դեռ դու չէիր եկել, օրհնեցի նրան, եւ նա թող օրհնեալ լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Երբ Եսաւը լսեց իր հայր Իսահակի խօսքերը, անչափ դառնացաւ, մեծ աղմուկ բարձրացրեց ու ասաց իր հօրը. «Արդ, ի՛նձ էլ օրհնիր, հա՛յր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Իսահակն ասաց նրան. «Քո եղբայրը եկաւ նենգութեամբ եւ առաւ քեզ համար սահմանուած օրհնութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Եսաւն ասաց. «Իրաւամբ նրա անունը Յակոբ է դրուել, որովհետեւ այս երկրորդ անգամն է, որ խաբում է ինձ. նախ խլեց իմ անդրանկութիւնը, իսկ այժմ խլեց ինձ համար սահմանուած օրհնութիւնը»: Եսաւն ասաց իր հօրը. «Եւ ոչ մի օրհնութիւն չթողեցի՞ր ինձ, հա՛յր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Պատասխան տուեց Իսահակն ու ասաց նրան. «Քանի որ նրան դարձրի քո տէրը եւ նրա բոլոր եղբայրներին դարձրի նրա ծառաները եւ նրան ապահովեցի ցորենով ու գինով, քե՛զ համար ինչ անեմ, որդեա՛կ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Եսաւը հարցրեց հօրը. «Միթէ մէ՞կ օրհնութիւն ունես, հա՛յր. ի՛նձ էլ օրհնիր, հա՛յր»: Երբ Իսահակի սիրտը կսկծաց, Եսաւը բարձրաձայն լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Նրա հայր Իսահակը պատասխանեց նրան ու ասաց. «Երկրի պարարտութիւնից եւ վերեւից՝ երկնքի ցօղից պիտի լինի քո ապրուստը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Քո սրով պիտի ապրես եւ քո եղբօրը պիտի ծառայես: Բայց պիտի գայ ժամանակ, որ դու պիտի քանդես եւ շպրտես նրա լուծը քո պարանոցից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Եսաւը պահում էր Յակոբի նկատմամբ ունեցած ոխը այն օրհնութեան պատճառով, որ իր հայրը տուել էր նրան: Եսաւն ասաց իր մտքում. «Թող մօտենան իմ հօր մահուան սգի օրերը, որ սպանեմ Յակոբին՝ իմ եղբօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Ռեբեկային տեղեկացրին իր աւագ որդի Եսաւի խօսքերը, եւ նա մարդ ուղարկեց, կանչեց իր կրտսեր որդի Յակոբին ու ասաց նրան. «Ահա քո եղբայր Եսաւը սպառնում է սպանել քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Արդ, լսի՛ր իմ խօսքը, որդեա՛կ. ելիր գնա՛ Միջագետք, իմ եղբայր Լաբանի մօտ, Խառան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Նրա մօտ կ՚ապրես երկար ժամանակ, մինչեւ որ անցնի եղբօրդ զայրոյթն ու ցասումը քո դէմ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'եւ նա մոռանայ այն, ինչ արել ես դու նրան: Յետոյ մարդ կ՚ուղարկեմ, կը կանչեմ քեզ այնտեղից. չլինի թէ ձեր երկուսից էլ զրկուեմ նոյն օրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Ռեբեկան ասաց Իսահակին. «Յոգնել եմ Քետի ցեղի դուստրերից»: Եթէ Յակոբը կին առնի Քետի ցեղի դուստրերից՝ ա՛յս երկրի դուստրերից, էլ ինչո՞ւ եմ ապրում ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Իսահակը կանչեց Յակոբին, օրհնեց նրան ու պատուիրեց՝ ասելով. «Քանանացիների դուստրերից կին չառնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Գնա՛ Ասորիների Միջագետք, քո մօր հօր՝ Բաթուէլի տունը եւ այնտեղից, քո մօրեղբայր Լաբանի դուստրերից քեզ կին ա՛ռ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Իմ Աստուածը թող օրհնի քեզ, աճեցնի քեզ, բազմացնի քեզ, բազում ժողովուրդների նախահայր լինես: Նա քեզ եւ քեզնից յետոյ գալիք քո սերունդներին թող տայ իմ հայր Աբրահամի օրհնութիւնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'որպէսզի ժառանգես քո պանդխտութեան երկիրը, որ Աստուած տուել էր Աբրահամին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Իսահակը ճանապարհ դրեց Յակոբին, եւ սա գնաց Ասորիների Միջագետք, ասորի Բաթուէլի որդի Լաբանի մօտ, որը Ռեբեկայի՝ Յակոբի ու Եսաւի մօր եղբայրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Երբ Եսաւը տեսաւ, թէ Իսահակն օրհնեց Յակոբին, եւ սա գնաց Ասորիների Միջագետք, որ այնտեղից կին առնի, ինչպէս հայրը Յակոբին օրհնելիս պատուիրել էր ու ասել, թէ՝ «Քանանացիների դուստրերից կին չառնես»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Յակոբն էլ անսալով իր հօր ու մօր խօսքերին՝ գնացել էր Ասորիների Միջագետք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'համոզուեց, որ քանանացիների դուստրերը իր հայր Իսահակի աչքին հաճոյ չեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'ուստի գնաց Իսմայէլի մօտ եւ ի յաւելումն իր ունեցած կանանց, կին առաւ նաեւ Աբրահամի որդի Իսմայէլի դուստր Մայելէթին՝ Նաբէութի քրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Յակոբը Երդման ջրհորի մօտից ելաւ գնաց Խառան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Հասնելով մի տեղ՝ նա քնեց այնտեղ, որովհետեւ արեւն արդէն մայր էր մտել: Նա առաւ այնտեղի քարերից մէկը, դրեց գլխի տակ ու քնեց այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Նա երազ տեսաւ. երկրի վրայ հաստատուած էր մի սանդուղք, որի ծայրը հասնում էր երկինք, իսկ Աստծու հրեշտակները դրանով ելնում իջնում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Տէրը կանգնած էր սանդուղքի վրայ: Նա ասաց. «Ես Տէրն եմ, քո հայր Աբրահամի Աստուածը եւ Իսահակի Աստուածը: Մի՛ վախեցիր, որովհետեւ այն հողը, որի վրայ քնել ես դու, քեզ եմ տալու եւ քո սերունդներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Քո սերունդները երկրի աւազի չափ շատ են լինելու, տարածուելու են դէպի ծովակողմ, դէպի արեւելք, դէպի հիւսիս ու հարաւ: Քո շնորհիւ եւ քո սերունդների շնորհիւ օրհնուելու են աշխարհի բոլոր ազգերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Ես ահա քեզ հետ եմ, որ պահպանեմ քեզ քո բոլոր ճանապարհներին, որոնցով գնալու ես: Քեզ վերադարձնելու եմ այս երկիրը, որովհետեւ քեզ չեմ լքելու, մինչեւ որ չկատարեմ այն ամէնը, ինչ խոստացել եմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Զարթնեց Յակոբն իր քնից ու ասաց. «Տէրն այստեղ է, իսկ ես չգիտէի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Նա վախեցաւ եւ ասաց. «Սարսռազդեցիկ է այս վայրը, եւ սա այլ բան չէ, եթէ ոչ Աստծու տունը, իսկ սա էլ երկնքի դուռն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Առաւօտեան Յակոբը վեր կացաւ, վերցրեց այն քարը, որ դրել էր իր գլխի տակ, եւ այն կանգնեցրեց իբրեւ կոթող: Նա իւղով օծեց քարի գագաթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Յակոբն այդ վայրը կոչեց Աստծու տուն. նախկինում այդ քաղաքի անունը Ուլմաւուս էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Յակոբն ուխտ անելով՝ ասաց. «Եթէ Տէր Աստուած ինձ հետ լինի եւ ինձ պահպանի այն ճանապարհին, որով գնում եմ ես, ինձ ուտելու հաց տայ եւ հագնելու հագուստ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'ինձ ողջ-առողջ վերադարձնի իմ հօր տունը, ուրեմն թող նա լինի ինձ Տէր Աստուած,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'իսկ այն քարը, որ իբրեւ կոթող կանգնեցրի, թող ինձ համար լինի Աստծու տուն: Այն ամենից, Տէ՛ր, ինչ կը տաս ինձ, քեզ տասանորդ կը հանեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Յակոբը վեր կացաւ գնաց արեւելեան երկիրը, ասորի Բաթուէլի որդի Լաբանի մօտ, որը Ռեբեկայի՝ Յակոբի ու Եսաւի մօր եղբայրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Նա դաշտում մի ջրհոր տեսաւ: Այնտեղ մակաղել էր ոչխարների երեք հօտ. այդ ջրհորից ջուր էին տալիս ոչխարներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Ջրհորի բերանին մի մեծ քար կար: Բոլոր հօտերն այնտեղ էին հաւաքւում: Հովիւները գլորում էին ջրհորի բերանը ծածկող քարը, ջուր էին տալիս ոչխարներին եւ ապա քարը դարձեալ դնելով իր տեղը՝ փակում էին ջրհորի բերանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Յակոբը հարցրեց նրանց. «Եղբայրնե՛ր, որտեղի՞ց էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Նրանք պատասխանեցին. «Խառանից ենք»: Նա հարցրեց նրանց. «Դուք ճանաչո՞ւմ էք Նաքորի որդի Լաբանին»: Նրանք պատասխանեցին. «Ճանաչում ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Նա հարցրեց նրանց. «Նա ողջ-առո՞ղջ է»: Նրանք պատասխանեցին. «Ողջ-առողջ է»: Հէնց այդ պահին նրա դուստր Ռաքէլը գալիս էր ոչխարների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Յակոբն ասաց. «Օրը դեռ առջեւում է, ոչխարները հաւաքելու ժամանակը չէ, ջուր տուէ՛ք ոչխարներին եւ տարէ՛ք էլի արածեցնելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Նրանք ասացին. «Դա անհնար է, քանի դեռ չեն հաւաքուել բոլոր հովիւները եւ ջրհորի բերանից քարը չեն գլորել. դրանից յետոյ ջուր կը տանք ոչխարներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Մինչ նա խօսում էր նրանց հետ, ահա Լաբանի դուստր Ռաքէլը եկաւ իր հօր ոչխարների հետ, որովհետեւ նա էր արածեցնում իր հօր ոչխարները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Երբ Յակոբը տեսաւ իր մօրեղբայր Լաբանի դուստր Ռաքէլին եւ իր մօրեղբայր Լաբանի ոչխարները, մօտեցաւ, ջրհորի բերանից գլորեց քարը եւ ջրեց իր մօրեղբայր Լաբանի ոչխարները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Յակոբը համբուրեց Ռաքէլին ու բարձրաձայն լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Յակոբը Ռաքէլին յայտնեց, որ ինքը նրա հօրեղբայրն է՝ Ռեբեկայի որդին: Ռաքէլը գնաց ու հօրը պատմեց այն, ինչ պատահել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Երբ Լաբանը լսեց իր քրոջ որդի Յակոբի անունը, ընդառաջ գնաց, գիրկն առաւ նրան, համբուրեց ու տարաւ իր տունը: Յակոբը Լաբանին պատմեց այդ բոլոր բաները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Լաբանն ասաց նրան. «Իմ ոսկորներից եւ իմ միս ու արիւնից ես դու»: Յակոբը նրա մօտ մնաց մի ամբողջ ամիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Լաբանն ասաց Յակոբին. «Քանի որ դու իմ եղբայրն ես, ինձ ձրի չես ծառայի: Ասա՛ ինձ, ի՞նչ է քո վարձը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Լաբանն ունէր երկու դուստր: Աւագի անունը Լիա էր, իսկ կրտսերինը՝ Ռաքէլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Լիայի տեսողութիւնը թոյլ էր, իսկ Ռաքէլը բարեկազմ էր ու դէմքով գեղեցիկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Յակոբը սիրեց Ռաքէլին. նա ասաց. «Քեզ եօթը տարի կը ծառայեմ քո կրտսեր դուստր Ռաքէլի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Լաբանն ասաց նրան. «Աւելի լաւ է նրան քե՛զ տամ, քան օտար մարդու: Ապրի՛ր դու ինձ մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Յակոբը Ռաքէլի համար ծառայեց եօթը տարի, բայց նրա աչքին այդ տարիները օրեր թուացին, որովհետեւ սիրում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Յակոբն ասաց Լաբանին. «Տո՛ւր ինձ իմ հարսնացուին, որպէսզի պառկեմ նրա հետ, որովհետեւ սահմանուած ժամկէտը վերջացել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Լաբանը հաւաքեց տեղի բոլոր մարդկանց ու հարսանիք արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Երբ գիշերը վրայ հասաւ, Լաբանն առաւ իր դուստր Լիային, տարաւ Յակոբի մօտ, եւ Յակոբը պառկեց նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Լաբանն իր աղախին Զելփային իբրեւ նաժիշտ տուեց իր դուստր Լիային: Առաւօտեան Յակոբը տեսաւ, որ իր կողքինը Լիան է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Յակոբն ասաց Լաբանին. «Այս ի՞նչ արեցիր, մի՞թէ Ռաքէլի համար չծառայեցի քեզ, ինչո՞ւ խաբեցիր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Լաբանն ասաց. «Մեր երկրում ընդունուած չէ մեծից առաջ կրտսերին ամուսնացնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Արդ, սրա՛ համար էլ եօթը տարի ծառայիր, եւ ինձ համար աշխատած այդ եօթը տարուայ աշխատանքիդ համար սրա՛ն էլ քեզ կին կը տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Յակոբն այդպէս էլ արեց. նա եօթը տարի եւս ծառայեց սրա համար, եւ Լաբանն իր դուստր Ռաքէլին կնութեան տուեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Լաբանն իր աղախին Բալլային իբրեւ նաժիշտ տուեց իր դուստր Ռաքէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Յակոբը մտաւ Ռաքէլի ծոցը եւ Ռաքէլին սիրեց աւելի, քան Լիային: Նա սրա համար ծառայեց եւս եօթը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Երբ Տէրը տեսաւ, որ Լիան Յակոբի համար ատելի է, նրա արգանդը բեղմնաւոր դարձրեց, իսկ Ռաքէլը ամուլ մնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Յղիացաւ Լիան եւ Յակոբի համար ծնեց որդի: Նա նրան կոչեց Ռուբէն՝ ասելով. «Տէրը տեսաւ իմ տառապանքները: Արդ, ինձ պիտի սիրի իմ ամուսինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Դարձեալ յղիացաւ Լիան, Յակոբի համար ծնեց երկրորդ որդի եւ ասաց. «Քանի որ Տէրը լսեց, որ ատելի եմ, սրան էլ պարգեւեց ինձ»: Եւ նրա անունը դրեց Շմաւոն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Նա նորից յղիացաւ, ծնեց որդի եւ ասաց. «Այլեւս իմ կողքին կը լինի իմ ամուսինը, որովհետեւ նրա համար երեք որդի ծնեցի»: Դրա համար էլ նրան կոչեց Ղեւի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Նա մի անգամ էլ յղիացաւ, ծնեց որդի եւ ասաց. «Այս անգամ էլ պիտի գոհանամ Տիրոջից»: Եւ նրա անունը դրեց Յուդա: Դրանից յետոյ նա դադարեց երեխայ ունենալուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Երբ Ռաքէլը տեսաւ, որ ինքը Յակոբի համար որդի չի ծնում, նախանձեց իր քրոջը եւ Յակոբին ասաց. «Ինձ զաւակներ պարգեւի՛ր, այլապէս կը մեռնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Բարկացաւ Յակոբը Ռաքէլի վրայ ու ասաց նրան. «Մի՞թէ Աստծու փոխարինողն եմ ես, որ զրկել է քեզ ծննդաբերելուց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Ռաքէլն ասաց Յակոբին. «Ահա իմ աղախին Բալլան: Մտի՛ր նրա ծոցը, նա թող ծննդաբերի իմ ծնկների վրայ, որ ես նրա միջոցով որդիներ ունենամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Եւ նա իր աղախին Բալլային տուեց նրան կնութեան: Յակոբը մտաւ նրա ծոցը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Յղիացաւ Ռաքէլի նաժիշտ Բալլան եւ որդի ծնեց Յակոբի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Ռաքէլն ասաց. «Աստուած ինձ արդար դատեց, լսեց իմ ձայնը եւ ինձ որդի պարգեւեց»: Դրա համար էլ նրա անունը դրեց Դան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Դարձեալ յղիացաւ Ռաքէլի նաժիշտ Բալլան եւ երկրորդ որդի ծնեց Յակոբի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Ռաքէլն ասաց. «Աստուած ինձ օգնեց, որովհետեւ ընդհարուեցի քրոջս հետ եւ յաղթեցի»: Եւ որդու անունը դրեց Նեփթաղիմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Երբ Լիան տեսաւ, որ ինքը դադարել է ծնելուց, իր նաժիշտ Զելփային տուեց Յակոբին կնութեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Լիայի նաժիշտ Զելփան յղիացաւ եւ Յակոբի համար ծնեց որդի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Նա ասաց. «Ես երջանիկ եմ»: Եւ նրա անունը դրեց Գադ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Յղիացաւ Լիայի նաժիշտ Զելփան եւ երկրորդ որդի էլ ծնեց Յակոբի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Լիան ասաց. «Ես բախտաւոր եմ, որովհետեւ կանայք ինձ երանի են տալու»: Եւ որդու անունը դրեց Ասեր՝ Մեծութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ռուբէնը ցորենի հնձի օրերին գնաց, դաշտում մանրագորի խնձոր գտաւ եւ այն բերեց իր մայր Լիային: Ռաքէլը դիմելով իր քոյր Լիային՝ ասաց. «Քո որդու մանրագորներից մի քիչ տո՛ւր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Լիան պատասխանեց. «Բաւական չէ՞, որ խլեցիր իմ ամուսնուն, հիմա էլ իմ որդու մանրագո՞րն ես ուզում առնել»: Ռաքէլն ասաց. «Այդպէս չէ: Քո որդու մանրագորների փոխարէն թող նա այս գիշեր պառկի քեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Երբ երեկոյեան Յակոբը դաշտից վերադարձաւ տուն, նրան ընդառաջ գնաց Լիան ու ասաց. «Այսօր իմ ծոցը պիտի մտնես, որովհետեւ իմ որդու մանրագորների փոխարէն վարձել եմ քեզ»: Եւ նա գիշերը պառկեց նրա հետ: Աստուած անսաց Լիային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Սա յղիացաւ եւ Յակոբի համար ծնեց հինգերորդ որդի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Լիան ասաց. «Աստուած տուեց իմ վարձը այն բանի համար, որ իմ աղախնին տուեցի իմ ամուսնուն»: Եւ նա նրա անունը դրեց Իսաքար, որ նշանակում է վարձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Մի անգամ էլ յղիացաւ Լիան եւ Յակոբի համար ծնեց վեցերորդ որդի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Լիան ասաց. «Աստուած ինձ լաւ նուէր պարգեւեց. սրանից յետոյ ամուսինս ինձ կը սիրի, որովհետեւ նրա համար վեց որդի ծնեցի: Եւ նա նրա անունը դրեց Զաբուղոն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Դրանից յետոյ նա աղջիկ ծնեց եւ նրա անունը դրեց Դինա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Աստուած յիշեց Ռաքէլին, անսաց նրան եւ բեղմնաւոր դարձրեց նրա արգանդը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Սա յղիացաւ եւ Յակոբի համար ծնեց որդի: Ռաքէլն ասաց. «Աստուած ինձնից վերացրեց իմ ամլութեան նախատինքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Եւ նրա անունը դրեց Յովսէփ: Նա ասաց. «Աստուած թող ինձ պարգեւի մի որդի եւս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Երբ Ռաքէլը ծնեց Յովսէփին, Յակոբն ասաց Լաբանին. «Ինձ թո՛յլ տուր, որ գնամ իմ բնակավայրն ու իմ երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Տո՛ւր կանանց, որոնց համար ծառայեցի քեզ, ու իմ որդիներին, որպէսզի գնամ: Դու ինքդ էլ գիտես, թէ ինչ ծառայութիւն մատուցեցի քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Լաբանը պատասխանեց նրան. «Քանի որ արժանացայ քո բարեհաճութեանը, փորձով համոզուեցի, որ Աստուած ինձ օրհնեց իմ տուն քո ոտք դնելու առթիւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Լաբանն աւելացրեց. «Ասա՛ ինձ քո վարձը, եւ ես կը տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Յակոբն ասաց նրան. «Դու գիտես, թէ որքան ծառայեցի քեզ, եւ թէ որքան ոչխար էիր յանձնել ինձ: Իմ գալուց առաջ դրանք փոքրաթիւ էին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'իսկ այժմ դրանք անչափ աճել են: Տէր Աստուած քեզ օրհնեց քո տուն իմ ոտք դնելու առթիւ: Արդ, ե՞րբ եմ ես տուն-տեղ ունենալու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Լաբանը հարցրեց նրան. «Ի՞նչ տամ քեզ»: Յակոբը պատասխանեց. «Ինձ ոչինչ մի՛ տուր, բայց միայն հետեւեալն արա՛. ես դարձեալ արածեցնեմ ու պահպանեմ քո ոչխարները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Այսօր թող քո առաջով անցնի քո ամբողջ հօտը, եւ դու ջոկի՛ր իրարից բոլոր խատուտիկ ու գորշ ոչխարները եւ արածող բոլոր թուխ ոչխարները: Բոլոր խատուտիկ ոչխարներն ու պտաւոր այծերը թող լինեն իմ վարձը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Իմ արդար լինելը կ՚երեւայ վաղը, որ ես վարձ ունեմ քեզնից ստանալիք: Այն բոլոր այծերը, որոնք բծաւոր ու պտաւոր չեն, եւ ոչխարները, որոնք խայտաճամուկ չեն, թող ինձ գողօն համարուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Լաբանն ասաց նրան. «Թող քո ասածը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Լաբանն այդ օրը առանձնացրեց մոխրագոյն ու պտաւոր նոխազները, բոլոր մոխրագոյն ու պտաւոր այծերը, սպիտակ ու թուխ ոչխարները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'տուեց իր որդիներին եւ նրանց ուղարկեց Յակոբից հեռու երեք օրուայ ճանապարհ: Յակոբն արածեցնում էր Լաբանի մնացած հօտերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Յակոբն առաւ խնկենու, ընկուզենու եւ սօսու դալար ճիւղեր, հանեց դրանց կեղեւը, եւ երեւաց սպիտակը: Գաւազաններից կանաչ մասը քերծելուց յետոյ գաւազանների քերծուած սպիտակը գունագեղ էր երեւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Քերծած գաւազանները նա դրեց ջրի գուռերի մէջ, որ երբ հօտերը գան ջուր խմելու, այդ գաւազանների մօտ բեղմնաւորուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Մաքիները գաւազանների մօտ բեղմնաւորւում էին եւ ծնում խայտաճամուկ, պտաւոր ու խատուտիկ գառներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Յակոբը էգ գառներն առանձնացնում էր ու դնում մաքիների դիմաց, նաեւ՝ մոխրագոյն խոյերը եւ բոլոր խայտաճամուկ ոչխարները: Նա իր հօտն առանձնացնում էր, չէր խառնում Լաբանի հօտերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Երբ գալիս էր մաքիների զուգաւորուելով յղիանալու ժամանակը, Յակոբը գաւազանները դնում էր մաքիների դիմաց, գուռերի մէջ, որպէսզի նրանք բեղմնաւորուեն գաւազանների մօտ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'իսկ երբ մաքիները ծնում էին, այլեւս չէր դնում: Նշան չունեցողները լինում էին Լաբանի սեփականութիւնը, իսկ նշան ունեցողները՝ Յակոբի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Այսպիսով Յակոբը չափազանց շատ հարստացաւ. նա ունեցաւ շատ ոչխարներ ու արջառներ, ծառաներ ու աղախիններ, ուղտեր ու էշեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Յակոբի ականջին հասան Լաբանի որդիների ասածները, թէ՝ «Յակոբը տէր դարձաւ մեր հօր ողջ ունեցուածքին, մեր հօր ունեցուածքի շնորհիւ նա դիզեց մեծ հարստութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Յակոբը նայելով Լաբանի դէմքին՝ հասկացաւ, որ նա իր հետ այնպէս բարեացակամ չէ, ինչպէս առաջներում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Տէր Աստուած ասաց Յակոբին. «Վերադարձի՛ր քո հօր երկիրը, քո ցեղի մօտ, եւ ես կը լինեմ քեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Յակոբը մարդ ուղարկեց եւ Ռաքէլին ու Լիային կանչեց այն դաշտը, ուր հօտերն էին գտնւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Նա նրանց ասաց. «Նայելով ձեր հօր դէմքին՝ զգում եմ, որ նա ինձ հետ այնպէս բարեացակամ չէ, ինչպէս առաջներում էր: Սակայն իմ հօր Աստուածը ինձ հետ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Դուք ինքներդ էլ գիտէք, որ իմ ամբողջ ուժով ես ծառայեցի ձեր հօրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'բայց ձեր հայրը խաբեց ինձ, իմ վարձից տասը գառներ խլեց, սակայն Աստուած թոյլ չտուեց, որ նա ինձ վատութիւն անի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Եթէ նա ասի, թէ՝ «Երանգաւոր մաքիները թող լինեն քո վարձը», ապա բոլոր մաքիները երանգաւոր գառներ կը ծնեն, իսկ եթէ ասի, թէ՝ «Սպիտակները թող լինեն քո վարձը», ապա բոլոր մաքիները սպիտակ գառներ կը ծնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Աստուած ձեր հօր բոլոր մաքիները առաւ ու ինձ տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Երբ մաքիները բեղմնաւորւում էին, ես երազում, իմ աչքերով տեսնում էի, թէ ինչպէս նոխազներն ու խոյերը ելնում էին պտաւոր, խատուտիկ ու խայտաճամուկ մաքիների ու այծերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Երազի մէջ Աստծու հրեշտակն ինձ ասաց. «Յակո՛բ»: Ես պատասխանեցի. «Ի՞նչ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Նա ասաց. «Քո աչքով նայի՛ր ու տե՛ս, որ մաքիների ու էգ այծերի վրայ ելնող խոյերն ու արու այծերը ինչպէ՜ս պտաւոր են, խայտաճամուկ ու խատուտիկ: Չէ՞ որ ես տեսայ, թէ ինչքան անարդար վարուեց քեզ հետ Լաբանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ես այն Աստուածն եմ, որ երեւացի քեզ Աստծու տուն կոչուող վայրում, ուր ինձ համար կոթողը իւղով օծեցիր եւ ուխտ արեցիր: Արդ, դո՛ւրս արի այս երկրից, գնա՛ քո ծննդավայրը, եւ ես կը լինեմ քեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Պատասխան տուեցին Ռաքէլն ու Լիան եւ ասացին նրան. «Մի՞թէ սրանից յետոյ մենք մեր հօր ունեցուածքից բաժին եւ ժառանգութիւն կ՚ունենանք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'չէ՞ որ նա մեզ օտար համարեց, քանի որ վաճառեց մեզ եւ մեր փողը կերաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Այն հարստութիւնն ու փառքը, որ Աստուած առաւ մեր հօր ձեռքից, թող մերը լինի ու մեր որդիներինը: Արդ, ինչ որ ասել է քեզ Աստուած, արա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Յակոբը վեր կացաւ, առաւ իր կանանց ու երեխաներին եւ նրանց նստեցրեց ուղտերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Նա իր հետ վերցրեց իր ողջ ունեցուածքն ու հարստութիւնը, որ կուտակել էր Ասորիների Միջագետքում, որպէսզի գնայ Քանանացիների երկիրը՝ իր հայր Իսահակի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Լաբանը գնացել էր իր ոչխարները խուզելու: Ռաքէլը գողացաւ իր հօր կուռքերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'իսկ Յակոբը շեղեց իր աներոջ Լաբանի ուշադրութիւնը, որովհետեւ չէր ուզում յայտնել նրան, որ պիտի գնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Եւ նա գնաց իր ամբողջ ունեցուածքով: Նա անցաւ գետը եւ ուղղուեց դէպի Գաղաադ լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Երրորդ օրը ասորի Լաբանին յայտնեցին, որ Յակոբը գնացել է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Նա իր հետ վերցրեց իր եղբայրներին, հետապնդեց նրան՝ անցնելով եօթը օրուայ ճանապարհ եւ նրան հասաւ Գաղաադ լերան մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Գիշերը երազում Աստուած երեւաց ասորի Լաբանին ու ասաց նրան. «Զգո՛յշ եղիր, չլինի թէ Յակոբի հետ չարութեամբ խօսես»: Լաբանը հասաւ Յակոբին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Յակոբն իր վրանը խփել էր լերան վրայ, իսկ Լաբանն իր եղբայրներին դադար տուեց Գաղաադ լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Լաբանն ասաց Յակոբին. «Ինչո՞ւ արեցիր դու այդ բանը, ինչո՞ւ ինձնից գաղտնի հեռացար, կողոպտեցիր ինձ, իսկ իմ դուստրերին իբրեւ ռազմագերի տարար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Եթէ տեղեակ պահէիր ինձ, քեզ ճանապարհ կը դնէի ուրախութեամբ, թմբուկների ու քնարների նուագակցութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Մի՞թէ ես արժանի չէի, որ համբուրէի իմ որդիներին ու դուստրերին: Արդ, անմիտ բան ես արել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Ես հիմա կարող էի քեզ վատութիւն անել, բայց քո հօր Աստուածը երէկ ասաց ինձ. «Զգո՛յշ եղիր, չլինի թէ Յակոբի հետ չարութեամբ խօսես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Արդ, գնում ես, որովհետեւ շատ ես ցանկանում գնալ քո հօր տունը: Բայց ինչո՞ւ գողացար իմ աստուածները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Պատասխան տուեց Յակոբն ու ասաց Լաբանին. «Որովհետեւ վախեցայ: Մտածեցի, թէ գուցէ դու քո դուստրերին, նաեւ իմ ողջ ունեցուածքը կը խլես ինձնից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Յակոբն աւելացրեց. «Ում մօտ որ գտնես քո աստուածները, թող նա մեր եղբայրների ներկայութեամբ սպանուի: Արդ, քո ունեցածից ինչ որ գտնես ինձ մօտ, վերցրո՛ւ»: Նա ոչինչ չգտաւ նրա մօտ: Յակոբը, սակայն, չգիտէր, որ Ռաքէլն էր գողացել դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Լաբանը, մտնելով, խուզարկեց Յակոբի կացարանը, Լիայի կացարանն ու երկու հարճերի կացարանը, բայց ոչինչ չգտաւ: Դուրս գալով Լիայի կացարանից՝ Լաբանը մտաւ Ռաքէլի կացարանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Ռաքէլն առնելով կուռքերը՝ դրանք դրել էր ուղտի թամբի տակ եւ նստել դրանց վրայ: Լաբանը խուզարկեց ողջ վրանը, բայց ոչինչ չգտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Նա ասաց իր հօրը. «Մի՛ բարկացիր, տէ՛ր, որ քո ներկայութեամբ չեմ կարող ոտքի ելնել, որովհետեւ կանանց յատուկ վիճակի մէջ եմ»: Լաբանը խուզարկեց ողջ կացարանը, բայց կուռքերը չգտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Յակոբը զայրացած վիճում էր Լաբանի հետ: Յակոբը, պատասխան տալով Լաբանին, ասաց. «Ի՞նչ վնաս եմ տուել ես, կամ ո՞րն է իմ յանցանքը, որ հետապնդեցիր ինձ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'եւ խուզարկեցիր իմ ողջ ունեցուածքը: Իմ տանը քո ունեցուածքից որեւէ բան գտա՞ր. դի՛ր այն իմ եղբայրների ու քո եղբայրների առաջ, եւ նրանք թող դատ անեն մեր երկուսի միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Քսան տարի է, ինչ քեզ հետ էի, քո մաքիներն ու այծերը չստերջացան, եւ քո մաքիների խոյերը ես չկերայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Գազաններից յօշոտուած կենդանիները ես չբերեցի քեզ մօտ, այլ ես ինքս էի հատուցում ցերեկը գողացուածի ու գիշերը գողացուածի վնասը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Ցերեկը տանջւում էի շոգից, իսկ գիշերը՝ ցրտից: Քունը փախել էր աչքերիցս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Քսան տարի է, որ քո տանն էի: Տասնչորս տարի քո դուստրերի համար աշխատեցի եւ վեց տարի՝ քո հօտերի համար, բայց դու խաբեցիր ինձ եւ իմ բաժնից տասը ոչխար խլեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Եթէ ինձ հետ չլինէին իմ հօր Աստուածը, Աբրահամի Աստուածն ու Իսահակի երկիւղը, այժմ գուցէ ինձ ձեռնունայն յետ ուղարկէիր: Աստուած, սակայն, տեսաւ իմ չարչարանքն ու իմ ձեռքի գործը եւ երէկ քեզ յանդիմանեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Պատասխան տուեց Լաբանն ու ասաց Յակոբին. «Դուստրերդ իմ դուստրերն են, որդիներդ իմ որդիներն են, հօտերդ իմ հօտերն են: Այն ամէնը, ինչ տեսնում ես դու, իմն են ու իմ դուստրերինը: Արդ, հիմա ես ինչպէ՞ս կարող եմ վատութիւն անել իմ դուստրերին ու նրանց որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Արի պայման դնենք ես ու դու: Դա թող վկայութիւն լինի իմ ու քո միջեւ»: Նա իր խօսքը շարունակելով՝ ասաց նրան. «Ահա մեր միջեւ որպէս վկայ Աստծուց բացի ոչ ոք չկայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Եւ Յակոբը վերցրեց մի քար եւ կանգնեցրեց որպէս կոթող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Դիմելով իր եղբայրներին՝ նա ասաց. «Քարեր հաւաքեցէ՛ք»: Նրանք քարեր կուտակեցին, քարակոյտ սարքեցին եւ այդ քարակոյտի վրայ կերան ու խմեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Լաբանն այն կոչեց Վկայութեան կարկառ, իսկ Յակոբը կոչեց Վկայ կարկառ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Լաբանն ասաց նրան. «Այս քարակոյտն այսօր վկայ է իմ ու քո միջեւ»: Ահա թէ ինչու Լաբանն այն կոչեց Վկայութեան քարակոյտ, իսկ Յակոբն այն կոչեց Վկայ քարակոյտ: Լաբանն ասաց Յակոբին. «Ահա այս քարակոյտն ու այս կոթողը, որ կանգնեցրի իմ ու քո միջեւ. վկայ է այս քարակոյտը, վկայ է այս կոթողը»: Դրա համար էլ քարակոյտը կոչու»ց Վկայութիւն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'եւ Դիտանոց, որի մասին ասաց, թէ՝ «Աստծու աչքը թող ինձ ու քեզ վրայ լինի, որովհետեւ մենք, ահա, բաժանւում ենք միմեանցից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Եթէ վշտացնես իմ դուստրերին, եթէ իմ դուստրերի կենդանութեան օրօք կանայք առնես, զգո՛յշ եղիր, քանի որ մարդ չկայ, որ այդ բանը տեսնի, բայց Աստուա՛ծ վկայ կը լինի իմ ու քո միջեւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Լաբանն ասաց Յակոբին. «Ահա այս քարակոյտն ու այս կոթողը, որ կանգնեցրինք իմ ու քո միջեւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'վկայ թող լինի այս քարակոյտը, վկայ թող լինի այս կոթողը, որ ես չեմ անցնի քարակոյտից այն կողմ, իսկ դու էլ չես անցնի քարակոյտից ու կոթողից այս կողմ չար դիտաւորութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Մեր դատաւորը Աբրահամի Աստուածը, Նաքորի Աստուածը, նրանց հայրերի Աստուածը թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Եւ Յակոբը երդուեց իր հայր Իսահակի երկիւղով: Յակոբը զոհ մատուցեց լերան վրայ եւ կանչեց իր եղբայրներին, որ հաց ուտեն: Նրանք կերան, խմեցին ու գիշերեցին լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Լաբանն առաւօտեան վեր կացաւ, համբուրեց իր որդիներին ու դուստրերին, օրհնեց նրանց եւ վերադառնալով՝ գնաց իր բնակատեղին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Յակոբն էլ գնաց իր ճանապարհով: Նա տեսաւ Աստծու հրեշտակների բանակը. նրան ընդառաջ եկան Աստծու հրեշտակները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Յակոբը տեսնելով նրանց՝ ասաց. «Սա Աստծու բանակն է». եւ այդ վայրի անունը դրեց Բանակատեղի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Յակոբն իրենից առաջ բանագնացներ ուղարկելով իր եղբայր Եսաւի մօտ, Սէիր գաւառը, Եդոմի երկիրը՝ պատուէր տուեց նրանց ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, '«Այսպէս կ՚ասէք իմ տէր Եսաւին, թէ այսպէս է ասում քո ծառայ Յակոբը. «Լաբանի մօտ ապրեցի եւ մինչեւ հիմա այնտեղ մնացի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Ունեցայ արջառներ, ոչխարներ, էշեր, ծառաներ ու աղախիններ: Հիմա մարդ եմ ուղարկում իմ տէր Եսաւին՝ խնդրելու, որ քո ծառան շնորհ գտնի քո առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Բանագնացները Յակոբի մօտ վերադառնալով՝ ասացին. «Գնացինք քո եղբայր Եսաւի մօտ. նա, նրա հետ նաեւ չորս հարիւր տղամարդիկ, քեզ ընդառաջ են գալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Վախեցաւ Յակոբն ու կասկածանքի մէջ ընկաւ: Նա իր հետ եղած ժողովրդին, արջառները, ոչխարները եւ ուղտերը բաժանեց երկու խմբի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Յակոբը մտածեց. «Եթէ Եսաւը յարձակուի առաջին խմբի վրայ եւ ջարդի այն, ապա կը փրկուի երկրորդ խումբը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Եւ Յակոբն ասաց. «Իմ հայր Աբրահամի Աստուա՛ծ, իմ հայր Իսահակի Աստուա՛ծ, Տէ՛ր, ինձ ասացիր, թէ՝ «Գնա՛ քո ծննդավայրը եւ բարիք կ՚անեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Ես արժանի չեմ բոլոր այն արդարութիւններին ու ճշմարտութիւններին, որ արեցիր քո ծառային, որովհետեւ ցուպը ձեռքիս անցայ Յորդանանի այս կողմը, իսկ հիմա բաժանուել եմ երկու մասի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Փրկի՛ր ինձ իմ եղբայր Եսաւի ձեռքից, որովհետեւ ես նրանից վախենում եմ. գուցէ նա գայ եւ հարուածի ինձ ու մայրերին՝ իրենց երեխաների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Դու ասացիր, թէ՝ «Բարիք կ՚անեմ քեզ եւ քո սերունդները աւազի պէս կը բազմացնեմ, այնքան, որ անթիւ ու անհամար կը լինեն նրանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Եւ նա այդ գիշեր քնեց այդտեղ: Նա բերածներից իր ձեռքով, իբրեւ ընծայ, իր եղբայր Եսաւին ուղարկեց');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'երկու հարիւր այծ, քսան նոխազ, երկու հարիւր մաքի, քսան խոյ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'երեսուն ուղտ՝ իրենց նորածին ձագերի հետ, քառասուն կով եւ տասը ցուլ, քսան էշ եւ տասը քուռակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Նա իր ծառաներին յանձնեց հօտերն առանձին-առանձին եւ ասաց նրանց. «Դուք գնացէ՛ք ինձնից առաջ, հօտերն առանձին-առանձին՝ իրարից հեռու կը տանէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Նա առաջինին պատուիրեց՝ ասելով. «Եթէ քեզ հանդիպի իմ եղբայր Եսաւը եւ հարցնի, թէ՝ «Ո՞վ ես եւ ո՞ւր ես գնում, ո՞ւմ է պատկանում այն, ինչ քո առջեւից է գնում»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'կ՚ասես. «Քո ծառայ Յակոբի ընծաներն են, որ նա ուղարկում է իր տէր Եսաւին, իսկ ինքը գալիս է մեր ետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Նա պատուիրեց առաջինին, երկրորդին, երրորդին եւ բոլոր նրանց, ովքեր հօտերի հետ գնում էին առջեւից, եւ ասաց. «Երբ կը հանդիպէք Եսաւին, կ՚ասէք նրան այն, ինչ ասացի ես ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Դուք կ՚ասէք. «Ահա քո ծառայ Յակոբը գալիս է մեր ետեւից»: Նա ինքն իրեն մտածում էր. «Նրան կը մեղմեմ այն ընծաներով, որ ուղարկում եմ ինձնից առաջ, եւ ապա անձամբ կը հանդիպեմ նրան, թերեւս բարեացակամ լինի իմ նկատմամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Ընծաներն ուղարկուեցին իրենից առաջ, իսկ ինքն այդ գիշեր քնեց այդտեղ՝ Բանակատեղիում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Նոյն գիշերը վեր կենալով՝ նա առաւ իր երկու կանանց, երկու աղախիններին ու տասնմէկ որդիներին, անցկացրեց Յոբոկ գետի ծանծաղուտով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Նա նրանց ու իրեն պատկանող ամէն ինչ վերցրած՝ անցկացրեց գետով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Յակոբը մնաց միայնակ: Մի մարդ նրա հետ մարտնչեց մինչեւ առաւօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Երբ մարդը տեսաւ, որ չի կարողանում յաղթել նրան, կռուի ընթացքում բռնեց Յակոբի ազդրի ջլերը եւ անզգայացրեց դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Մարդն ասաց նրան. «Թո՛յլ տուր գնամ, որովհետեւ արդէն լուսացաւ»: Յակոբը պատասխանեց. «Թոյլ չեմ տայ, որ գնաս, մինչեւ ինձ չօրհնես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Մարդն ասաց նրան. «Ի՞նչ է քո անունը»: Նա պատասխանեց նրան՝ Յակոբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Մարդն ասաց նրան. «Այսուհետեւ քեզ Յակոբ թող չկոչեն, այլ Իսրայէլ թող լինի քո անունը, որովհետեւ դիմացար Աստծու հետ մաքառելիս, ուստի մարդկանց նկատմամբ էլ ուժեղ լինես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Յակոբը հարց տուեց. «Ասա՛ ինձ քո անունը»: Նա ասաց. «Ինչո՞ւ ես հարցնում իմ անունը»: Եւ նա տեղնուտեղը օրհնեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Յակոբն այդ տեղն անուանեց Երեւումն Աստուծոյ, որովհետեւ, - ասում է, - Աստծուն տեսայ դէմ առ դէմ, եւ փրկուեց հոգիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Երբ անյայտացաւ Աստծու տեսիլքը, նրա վրայ արեւ ծագեց, իսկ նա իր ազդրի պատճառով կաղալով էր գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Դրա համար էլ իսրայէլացիները մինչեւ օրս կենդանիների ազդրի ջլերը չեն ուտում, քանի որ Աստուած բռնել էր Յակոբի ազդրի ջլերը եւ անզգայացրել դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Յակոբն աչքերը բարձրացրեց ու տեսաւ իր եղբայր Եսաւին, որ գալիս էր չորս հարիւր հոգով: Յակոբն իր երեխաներին բաժանեց Լիայի, Ռաքէլի եւ երկու աղախինների միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Նա երկու աղախիններին ու նրանց որդիներին ուղարկեց առջեւից, Լիային ու նրա որդիներին՝ նրանցից յետոյ, իսկ Ռաքէլին ու Յովսէփին՝ ամենավերջում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Ինքն անցաւ նրանցից առաջ եւ եօթն անգամ գետին խոնարհուեց մինչեւ իր եղբօրը մօտենալը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Եսաւն ընդառաջ գնաց նրան, գրկեց եւ համբուրեց, փաթաթուեց վզին եւ համբուրեց նրան: Նրանք երկուսով լաց եղան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Եսաւը վեր նայելով տեսաւ կանանց ու երեխաներին եւ հարց տուեց. «Սրանք քո ի՞նչն են»: Նա պատասխանեց. «Իմ երեխաներն են, որոնցով Աստուած ողորմեց ինձ՝ քո ծառային»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Աղախիններն ու նրանց որդիները մօտեցան ու խոնարհուեցին նրա առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Մօտեցան նաեւ Լիան ու իր որդիները եւ խոնարհուեցին նրա առաջ: Յետոյ մօտեցան Յովսէփն ու Ռաքէլը եւ խոնարհուեցին նրա առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Եսաւը հարց տուեց. «Ի՞նչ է այս մեծ շարանը, որ ինձ հանդիպեց»: Նա պատասխանեց. «Որպէսզի քո ծառան շնորհ գտնի քո առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Եսաւն ասաց. «Ես էլ շատ ունեմ, եղբա՛յր, քոնը քեզ թող մնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Յակոբն ասաց. «Այդպէս չի լինի: Եթէ շնորհ եմ գտել քո առաջ, ուրեմն ընդունի՛ր ինձնից ընծաները. որովհետեւ քո դէմքը տեսայ այնպէս, ինչպէս մարդ Աստծու դէմքը տեսնի: Ուրախացի՛ր ինձ հետ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'եւ ընդունի՛ր իմ ընծաները, որ մատուցեցի քեզ, որովհետեւ ողորմեց ինձ Աստուած, եւ ես ամէն ինչ ունեմ»: Յակոբն ստիպեց նրան, եւ սա ընդունեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Եսաւն ասաց. «Ելնենք գնանք ուղիղ ճանապարհով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Յակոբն ասաց նրան. «Իմ տէրն ինքը գիտի, որ երեխաներս փոքր են, իսկ ոչխարն ու արջառը արդէն ծնել են: Եթէ դրանց ստիպեմ մի օրուայ ճանապարհ գնալ, ապա բոլոր անասունները կը սատկեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ուրեմն իմ տէրն իր ծառայի առջեւից թող գնայ, իսկ ես ըստ իմ կարողութեան ու անասունների ընթացքի, ըստ իմ երեխաների զօրութեան կը շարժուեմ, մինչեւ որ Սէիրում հասնեմ իմ տիրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Եսաւը հարցրեց. «Քեզ մօտ թողնե՞մ ինձ հետ եղած մարդկանց մի մասին»: Սա պատասխանեց. «Ի՞նչ կարիք կայ: Բաւական է, որ շնորհ գտայ քո առաջ, տէ՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Այդ օրը Եսաւը իր ճանապարհով վերադարձաւ Սէիր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'իսկ Յակոբը գնաց դէպի վրանը, այնտեղ իր համար տներ կառուցեց, իսկ իր հօտերի համար փարախ շինեց: Դրա համար էլ այդ վայրը կոչեց Վրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Վերադառնալով Ասորիների Միջագետքից՝ Յակոբն եկաւ սիկիմացիների Սաղէմ քաղաքը, որը գտնւում էր Քանանացիների երկրում, եւ բնակուեց քաղաքի դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Նա Սիւքեմի հայր Եմորից հարիւր ոչխարով մի կալուածք գնեց, ուր եւ խփեց իր վրանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Նա այնտեղ զոհասեղան կառուցեց եւ երկրպագեց Իսրայէլի Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Լիայի՝ Յակոբի համար ծնած դուստրը՝ Դինան, ելաւ այդ կողմի աղջիկներին տեսնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Նրան տեսաւ քոռեցի Եմորի որդի Սիւքեմը, որը երկրի իշխանն էր, առեւանգեց նրան, պառկեց նրա հետ եւ պղծեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Սիւքեմը, ամբողջ հոգով կապուելով Յակոբի դուստր Դինայի հետ, սիրեց աղջկան եւ քաղցրութեամբ խօսեց նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Սիւքեմը, դիմելով իր հայր Եմորին, ասաց. «Այս աղջկան ինձ համար կնութեան ա՛ռ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Յակոբն իմացաւ, որ Եմորի որդին պղծել է իր դուստր Դինային: Այդ ժամանակ իր որդիները դաշտում՝ անասունների մօտ էին: Յակոբը լուռ մնաց մինչեւ նրանց գալը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Սիւքեմի հայր Եմորը գնաց Յակոբի մօտ՝ հետը խօսելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Դաշտից եկան նաեւ Յակոբի որդիները: Երբ տղամարդիկ իմացան կատարուածի մասին, զայրացան: Նրանք շատ տխրեցին, որովհետեւ Սիւքեմը, Յակոբի դստեր ծոցը մտնելով, մեծ նախատինք էր հասցրել Իսրայէլին: Դա չպէտք է լինէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Եմորը նրանց դիմելով՝ ասաց. «Իմ որդի Սիւքեմը ամբողջ հոգով սիրել է ձեր դստերը: Արդ, աղջկան տուէ՛ք նրան կնութեան եւ խնամութիւն արէ՛ք մեզ հետ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'ձեր դուստրերին տուէ՛ք մեզ եւ մեր դուստրերին առէ՛ք ձեր որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Բնակուեցէ՛ք մեզ հետ: Մեր ընդարձակ երկիրը փռուած է ձեր առաջ, բնակուեցէ՛ք այնտեղ, վաստակեցէ՛ք եւ կալուածքներ ձեռք բերէք դրա մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Սիւքեմն ասաց նրա հօրն ու եղբայրներին. «Թող շնորհ գտնեմ ձեր առաջ: Ինչ էլ պահանջէք, կը տանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Ինչքան ուզէք, աւելացրէ՛ք պարգեւագինը եւ օժիտը, որքան էլ ասէք, կը տամ, միայն թէ այդ աղջկան տուէ՛ք ինձ կնութեան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Յակոբի որդիները խորամանկութեամբ պատասխանեցին Սիւքեմին ու նրա հայր Եմորին, քանի որ Սիւքեմը պղծել էր իրենց քոյր Դինային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Լիայի որդիները՝ Դինայի եղբայրներ Շմաւոնն ու Ղեւին, ասացին. «Չենք կարող անել այդ բանը՝ մեր քրոջը տալ անթլփատ մի մարդու, որովհետեւ դա մեզ համար նախատինք կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Մենք կը համակերպուենք ձեզ հետ եւ կը բնակուենք ձեր երկրում միայն այն դէպքում, եթէ դուք նմանուէք մեզ՝ թլփատուեն ձեր բոլոր արու զաւակները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Միայն այն ժամանակ մեր դուստրերին կը տանք ձեզ եւ ձեր դուստրերից մեզ կին կ՚առնենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Մենք կը բնակուենք ձեզ հետ եւ կը լինենք իբրեւ մէկ ժողովուրդ: Իսկ եթէ չլսէք մեզ՝ չթլփատուէք, մեր դուստրերին կ՚առնենք ու կը հեռանանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Եմորին ու Եմորի որդի Սիւքեմին հաճելի թուացին այս խօսքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Երիտասարդը չյապաղեց անել այդ բանը, որովհետեւ շատ էր սիրում Յակոբի դստերը: Նա իր հօր ընտանիքի անդամների մէջ ամենից աւելի յարգանք էր վայելում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Եմորն ու իր որդի Սիւքեմը եկան իրենց քաղաքի դարպասի մօտ եւ, դիմելով իրենց քաղաքի տղամարդկանց, ասացին նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '«Այդ մարդիկ հաշտ ու խաղաղ են մեզ հետ: Արդ, թող բնակուեն այս երկրում եւ վաստակ ձեռք բերեն այստեղ, որովհետեւ այս ընդարձակ երկիրը փռուած է նրանց առաջ: Նրանց դուստրերին մեզ կին առնենք եւ մեր դուստրերին տանք նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Այդ մարդիկ մեզ նման լինելով՝ կը բնակուեն մեզ հետ, եւ մենք կը լինենք իբրեւ մէկ ժողովուրդ միայն այն պայմանով, որ մեր բոլոր զաւակները թլփատուեն, ինչպէս որ իրենք են թլփատուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Միթէ այդ ձեւով նրանց ունեցուածքը, նրանց անասունը եւ նրանց չորքոտանին մերը չե՞ն լինի: Եթէ նրանց այդ պայմանն ընդունենք, նրանք կը բնակուեն մեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Եմորի ու նրա որդի Սիւքեմի հետ համաձայնեցին բոլոր նրանք, ովքեր անցնում էին իրենց քաղաքի դարպասով, եւ թլփատուեցին բոլոր տղամարդիկ, ովքեր անցնում էին այդ քաղաքի դարպասով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Երրորդ օրը, երբ դեռ նրանք ցաւերի մէջ էին, Յակոբի երկու որդիները՝ Դինայի եղբայրներ Շմաւոնն ու Ղեւին, ամէն մէկն առնելով իր սուրը, կազմ ու պատրաստ մտան քաղաքն ու կոտորեցին բոլոր արուներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Նրանք սրի քաշեցին նաեւ Եմորին ու նրա որդի Սիւքեմին, իսկ Սիւքեմի տնից առան Դինային ու գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Յակոբի միւս որդիները յարձակուեցին վիրաւորների վրայ եւ կողոպտեցին այն քաղաքը, ուր պղծել էին իրենց քոյր Դինային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Նրանք վերցրին քաղաքում եւ դաշտում գտնուող նրանց արջառն ու ոչխարը, նրանց էշերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'գերեվարեցին ողջ մնացած մարդկանց ու նրանց կանանց, աւար առան նրանց ամբողջ գոյքը: նրանք յափշտակեցին ե՛ւ քաղաքում, ե՛ւ տներում եղած ամէն ինչ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Այն ժամանակ Յակոբն ասաց Շմաւոնին ու Ղեւիին. «Դուք ինձ ատելի դարձրիք: Ես երկրի բոլոր բնակիչներին՝ քանանացիներին ու փերեզացիներին անխիղճ մարդ պիտի թուամ: Մենք սակաւաթիւ ենք: Եթէ նրանք հաւաքուեն, ինձ վրայ յարձակուեն ու հարուածեն ինձ, ապա կ՚ոչնչանամ ե՛ւ ես, ե՛ւ իմ տոհմը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Նրանք պատասխանեցին. «Հապա ինչպէ՞ս է, որ նրանք իբրեւ բոզ լլկեցին մեր քրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Աստուած ասաց Յակոբին. «Վե՛ր կաց գնա՛ բնակավայրդ՝ Բեթէլ, բնակուի՛ր այդ վայրում եւ այնտեղ զոհասեղան կառուցի՛ր Աստծուն, որ երեւաց քեզ քո եղբայր Եսաւից փախչելու ժամանակ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Յակոբն ասաց իր տնեցիներին ու իր հետ եղած բոլոր մարդկանց. «Վերացրէ՛ք ձեր միջից ձեզ մօտ եղած օտար աստուածները, մաքրուեցէ՛ք, փոխեցէ՛ք ձեր զգեստները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'որ վեր կենանք գնանք Բեթէլ, այնտեղ զոհասեղան կառուցենք Աստծուն, որը լսեց ինձ նեղ օրերին, ինձ հետ եղաւ եւ ինձ պահպանեց իմ ուղեւորութեան ընթացքում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Նրանք Յակոբին յանձնեցին իրենց մօտ եղած օտար աստուածներն ու իրենց ականջօղերը: Յակոբը դրանք թաղեց բեւեկնի ծառի տակ, Սիկիմում, այնպէս, որ դրանք կորած են մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Իսրայէլը չուեց Սիկիմից: Աստծու երկիւղը պատեց դրա շուրջը գտնուող քաղաքները, եւ նրանց բնակիչները չհետապնդեցին Իսրայէլի որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Յակոբն ինքը եւ իր հետ եղած ամբողջ ժողովուրդը եկան Լուզ, այսինքն՝ Բեթէլ, որը գտնւում է Քանանացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Նա այնտեղ զոհասեղան շինեց, եւ այդ վայրը կոչեց Բեթէլ, որովհետեւ այնտեղ էր, որ Աստուած երեւացել էր նրան, երբ նա փախչում էր իր եղբայր Եսաւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Մեռաւ Դեբորան՝ Ռեբեկայի դայեակը, եւ թաղուեց Բեթէլից ներքեւ, կաղնու տակ: Յակոբն այդ վայրի անունը դրեց Սգոյ կաղնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Աստուած երեւաց Յակոբին, երբ սա Լուզում էր: Երբ Յակոբը Ասորիների Միջագետքից եկաւ Լուզ, Աստուած օրհնելով նրան՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'ասաց. «Քո անունը Յակոբ է, բայց այլեւս Յակոբ չես կոչուելու, այլ Իսրայէլ կը լինի քո անունը»: Եւ նա կոչուեց Իսրայէլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Աստուած ասաց նրան. «Ես եմ քո ամենակարող Աստուածը: Աճի՛ր եւ բազմացի՛ր: Ցեղեր ու ցեղախմբեր պիտի ծնուեն քեզնից, եւ թագաւորներ պիտի ելնեն քո կողից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Այն երկիրը, որ տուել եմ Աբրահամին ու Իսահակին, քեզ եմ տալու, քոնը թող լինի: Քեզնից յետոյ քո սերնդին եմ տալու այդ երկիրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Եւ Աստուած վերացաւ նրանից, այն վայրից, որտեղ խօսել էր նրա հետ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'իսկ Յակոբը կոթող կանգնեցրեց այն տեղում, որտեղ խօսել էր նրա հետ, քարէ կոթող, նրա վրայ գինի թափեց, իւղով օծեց կոթողը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'եւ այն տեղը, որտեղ Աստուած խօսել էր իր հետ, կոչեց Բեթէլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Նա գնաց Բեթէլից, եւ երբ մօտեցաւ Քաբրաթա երկրին, որ մտնի Եփրաթա, Ռաքէլը ծննդաբերեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Նրա ծննդաբերութիւնը դժուարին եղաւ, եւ երկունքի ժամանակ մանկաբարձն ասաց նրան. «Արիացի՛ր, որովհետեւ էլի տղայ ես ունենում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Հոգին աւանդելիս, քանի որ մեռնում էր, նա որդու անունը դրեց Իմ վշտերի որդի, իսկ հայրը նրան կոչեց Բենիամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Մեռաւ Ռաքէլն ու թաղուեց Եփրաթայի՝ նոյն ինքը Բեթղեհէմի ճանապարհի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Յակոբը նրա շիրիմի վրայ կոթող կանգնեցրեց: Դա մինչեւ այսօր էլ յայտնի է իբրեւ Ռաքէլի շիրիմի կոթող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Իսրայէլը գնաց եւ իր վրանը խփեց Գադերի աշտարակից այն կողմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Երբ Իսրայէլը բնակուեց այդ երկրում, Ռուբէնը գնաց ու պառկեց իր հօր հարճի՝ Բալլայի հետ: Իսրայէլն իմացաւ, եւ այդ բանը վատ թուաց նրան: Յակոբն ունէր տասներկու որդի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Լիայից ծնուած որդիներն էին՝ Յակոբի անդրանիկ որդին՝ Ռուբէնը, Շմաւոնը, Ղեւին, Յուդան, Իսաքարը, Զաբուղոնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Ռաքէլից ծնուած որդիներն էին՝ Յովսէփն ու Բենիամինը: Ռաքէլի նաժիշտ Բալլայից ծնուած որդիներն էին՝ Դանն ու Նեփթաղիմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Լիայի նաժիշտ Զելփայից ծնուած որդիներն էին՝ Գադն ու Ասերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Ահա սրանք են Յակոբի որդիները, որ նա ունեցաւ Ասորիների Միջագետքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Յակոբը եկաւ իր հայր Իսահակի մօտ, Մամբրէի կողմերում դաշտային մի քաղաք, այսինքն՝ Քեբրոն, որ գտնւում է Քանանացիների երկրում, ուր պանդխտեցին Աբրահամն ու Իսահակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Իսահակն ապրեց հարիւր ութսուն տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Իսահակը հոգին աւանդեց ու մեռաւ տարիքն առած, խոր ծերութեան մէջ, նա գնաց միացաւ իր նախնիներին: Նրան թաղեցին իր որդիները՝ Եսաւն ու Յակոբը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Այս է Եսաւի, այսինքն՝ Եդոմի ծննդաբանութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Եսաւը կին առաւ քանանացիների դուստրերից Ադդային՝ քետացի Ելոնի դստերը, Ոլիբամային՝ խեւացի Սեբեգոնի որդի Անայի դստերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'եւ Բասեմաթին՝ Իսմայէլի դստերը, որը Նաբէութի քոյրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ադդան Եսաւի համար ծնեց Ելիփազին, իսկ Բասեմաթը ծնեց Ռագուէլին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Ոլիբաման ծնեց Յէուսին, Եգղոմին ու Կորխին: Սրանք Եսաւի այն որդիներն են, որ նա ունեցաւ Քանանացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Եսաւն առաւ իր կանանց, տղաներին ու աղջիկներին, իր տան բոլոր մարդկանց, ողջ ունեցուածքն ու անասունները, այն ամէնը, ինչ ստացել, ձեռք էր բերել Քանանացիների երկրում, եւ հեռացաւ իր եղբայր Յակոբի մօտից՝ Քանանացիների երկրից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'որովհետեւ նրանց անասուններն այնքան շատ էին, որ պանդխտութեան երկիրը ի վիճակի չէր նրանց բաւարարելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Ուստի Եսաւը՝ նոյն ինքը Եդոմը, հաստատուեց Սէիր լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Այս է Եսաւի՝ եդոմայեցիների նախահօր սերունդը Սէիր լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Սրանք են Եսաւի որդիների անունները. Ելիփազ՝ Եսաւի կին Ադդայի որդին, Ռագուէլ՝ Եսաւի կին Բասեմաթի որդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Ելիփազի որդիներն են՝ Թեմանը, Ոմարը, Սոփարը, Գոթոմն ու Կենէզը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Թամարը Ելիփազի՝ Եսաւի որդու հարճն էր եւ Ելիփազի համար ծնեց Ամաղէկին: Սրանք Ադդայի՝ Եսաւի կնոջ որդիներն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Ռագուէլի որդիներն են՝ Նաքոթը, Զարեհը, Ամման եւ Մեզան: Սրանք Բասեմաթի՝ Եսաւի կնոջ որդիներն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Ոլիբամայի՝ Սեբեգոնի որդի Անայի դստեր եւ Եսաւի կնոջ որդիներն են Յէուսը, Եգղոմն ու Կորխը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Եսաւի ցեղապետ յետնորդներն են. Եսաւի անդրանիկ որդու՝ Ելիփազի որդիները՝ ցեղապետ Թեմանը, ցեղապետ Ոմարը, ցեղապետ Սոփարը, ցեղապետ Կենէզը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'ցեղապետ Կորխը, ցեղապետ Գոթոմը, ցեղապետ Ամաղէկը: Սրանք Ադդայից ծնուած Ելիփազի ցեղապետերն են Եդոմացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Եսաւի որդի Ռագուէլի որդիներն են՝ ցեղապետ Նաքոթը, ցեղապետ Զարեհը, ցեղապետ Ամման, ցեղապետ Մոզէն: Սրանք Եսաւի կին Բասեմաթից ծնուած Ռագուէլի ցեղապետերն են Եդոմի երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Եսաւի կին Ոլիբամայի որդիներն են՝ ցեղապետ Յէուսը, ցեղապետ Եգղոմը, ցեղապետ Կորխը: Սրանք Եսաւի կին՝ Անայի դուստր Ոլիբամայից ծնուած ցեղապետերն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Սրանք են Եսաւի որդիները, եւ սրանք են նրանց ցեղապետերը՝ Եդոմի որդիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Սէիրում բնակուող քոռեցի Սէիրի որդիներն են՝ Ղոտանը, Սեբաղը, Սեբեգոնը, Անան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Դեսոնը, Ասերը եւ Ռիսոնը: Սրանք քոռեցու՝ Սէիրի որդու ցեղապետերն են Եդոմի երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Ղոտանի որդիներն են Քոռին, Եմման, իսկ Ղոտանի քոյրը Թամնան էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Սոբաղի որդիներն են՝ Գաղոմը, Մանաքաթը, Գեբաղը, Սոփարը եւ Ոնանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Սեբեգոնի որդիներն են՝ Այիէն եւ Ոնանը: Սա այն Ոնանն է, որ անապատում աղբիւր գտաւ, երբ արածեցնում էր իր հայր Սեբեգոնի էշերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Անայի որդիներն են՝ Դեսոնը եւ Ոլիբաման՝ Անայի դուստրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Դեսոնի որդիներն են՝ Ամադանը, Եսբանը, Յեթրանը եւ Քառանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ասերի որդիներն են՝ Բալլանը, Զուկանը, Ոսնիկանը եւ Ուկամը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Ռիսոնի որդիներն են՝ Ոսը եւ Առանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Քոռի ցեղապետերն են՝ ցեղապետ Ղոտանը, ցեղապետ Սոբաղը, ցեղապետ Սեբեգոնը, ցեղապետ Անան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'ցեղապետ Դեսոնը, ցեղապետ Ասերը, ցեղապետ Ռիսոնը: Սրանք Քոռի ցեղապետերն են իրենց գաւառներում, Եդոմի երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Սրանք են այն թագաւորները, որոնք թագաւորեցին Եդոմայեցիների երկրում, երբ դեռ որեւէ թագաւոր չէր թագաւորում Իսրայէլում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Եդոմում թագաւորեց Սեպփորի որդի Բաղակը. նրա քաղաքի անունը Դեննաբա էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Մեռաւ Բաղակը, եւ նրա փոխարէն թագաւորեց Զարեհի որդի Յոբաբը, որ Բոսորայից էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Մեռաւ Յոբաբը, եւ նրա փոխարէն թագաւորեց Ասոմը, որը Թեմանացիների երկրից էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Մեռաւ Ասոմը, եւ նրա փոխարէն թագաւորեց Բարադի որդի Ադադը: Սա էր, որ Մովաբացիների դաշտում կոտորեց Մադիամին: Նրա քաղաքի անունը Գեթէմ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Մեռաւ Ադադը, եւ նրա փոխարէն թագաւորեց Սամաղան՝ Մասեկկայից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Մեռաւ Սամաղան, եւ նրա փոխարէն թագաւորեց Սաւուղը՝ Ռոբոթից, որը գտնւում է գետի եզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Մեռաւ Սաւուղը, եւ նրա փոխարէն թագաւորեց Ոքոբորի որդի Բալլայենոնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Մեռաւ Ոքոբորի որդի Բալլայենոնը, եւ նրա փոխարէն թագաւորեց Բարադի որդի Ադադը: Նրա քաղաքի անունը Փոգով էր, իսկ նրա կնոջ անունը՝ Մետաբէէլ: Սա Մազոբի որդի Մատրէթի դուստրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Սրանք են Եսաւի սերունդների, Եսաւի ցեղապետերի անուններն ըստ իրենց ցեղերի, ըստ իրենց վայրերի՝ իրենց աշխարհում, եւ ըստ իրենց տոհմերի, համաձայն նրանց անունների. ցեղապետ Թամանա, ցեղապետ Ղոտան, ցեղապետ Յեթաթ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'ցեղապետ Ոլիբամասա, ցեղապետ Հեղա, ցեղապետ Փենոն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ցեղապետ Կենէզ, ցեղապետ Թեման, ցեղապետ Մազար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'ցեղապետ Մագեդիէլ, ցեղապետ Զաբոյին: Սրանք եդոմայեցիների ցեղապետերն են ըստ երկրում իրենց ստացած բնակավայրերի, եւ այս Եսաւն է, որ դարձաւ Եդոմի նախահայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Յակոբը բնակւում էր Քանանացիների երկրում՝ այնտեղ, ուր պանդխտել էր իր հայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Յակոբի սերունդը հետեւեալն է. Յովսէփը տասնեօթը տարեկան էր, երբ իր եղբայրների հետ ոչխարներ էր արածեցնում: Իր հօր կանանց՝ Բալլայի որդիներից եւ Զելփայի որդիներից փոքր էր նա: Որդիներն իրենց հայր Իսրայէլի մօտ վատաբանում էին Յովսէփին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'բայց Իսրայէլը Յովսէփին աւելի շատ էր սիրում, քան մնացած բոլոր որդիներին, որովհետեւ Յովսէփը նրա ծեր տարիքում ծնուած որդին էր: Նա նրա համար կարել էր տուել ծաղկազարդ մի պատմուճան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Երբ նրա եղբայրները տեսան, որ իրենց հայրը նրան սիրում է իր բոլոր որդիներից աւելի, ատեցին նրան եւ նրա հետ հանգիստ խօսել չէին կարողանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Երազ տեսաւ Յովսէփն ու այն պատմեց իր եղբայրներին: Դրա համար եղբայրները առաւել եւս ատեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Նա ասաց նրանց. «Լսեցէ՛ք իմ տեսած երազը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Թւում էր, թէ մի դաշտում հասկերի խուրձ էինք կապում: Իմ խուրձը բարձրացաւ, կանգնեց ուղիղ, իսկ ձեր խրձերը դարձան ու երկրպագեցին իմ խրձին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Եղբայրներն ասացին նրան. «Միթէ որպէս թագաւո՞ր պիտի թագաւորես մեզ վրայ, կամ տէր դառնալով պիտի տիրե՞ս մեզ»: Եւ նրանք առաւել եւս ատեցին նրան այդ երազների ու խօսքերի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Նա տեսաւ մի այլ երազ եւս եւ այն պատմեց իր հօրն ու եղբայրներին: Նա ասաց. «Ահա մի այլ երազ եւս տեսայ: Իբրեւ թէ արեգակն ու լուսինը եւ տասնմէկ աստղեր երկրպագում էին ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Հայրը սաստեց նրան ու ասաց. «Այդ ի՞նչ երազ է, որ տեսել ես: Հիմա ես, քո մայրը եւ եղբայրները պիտի գանք եւ երկրպագե՞նք քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Վրդովուեցին նրա եղբայրները, բայց հայրը մտքում պահեց նրա պատմածը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Նրա եղբայրները գնացին Սիւքեմ՝ իրենց հօր ոչխարներն արածեցնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Իսրայէլն ասաց Յովսէփին. «Չէ՞ որ հիմա քո եղբայրները ոչխարներ են արածեցնում Սիւքեմում: Արի՛ քեզ ուղարկեմ նրանց մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Յովսէփն ասաց նրան. «Ես պատրաստ եմ»: Իսրայէլն ասաց նրան. «Գնա տե՛ս, թէ ողջ-առո՞ղջ են քո եղբայրներն ու ոչխարները, եւ ինձ լուր բեր»: Եւ Յակոբը նրան ուղարկեց այնտեղ Քեբրոնի հովտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Յովսէփը եկաւ Սիւքեմ եւ մի մարդ տեսաւ նրան դաշտում մոլորուած: Սա հարցրեց. «Ի՞նչ ես փնտռում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Նա պատասխանեց. «Իմ եղբայրներին եմ փնտռում: Ասա՛ ինձ, որտե՞ղ են նրանք ոչխարներ արածեցնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Մարդն ասաց նրան. «Նրանք այստեղից քոչեցին գնացին, բայց ես լսեցի, որ նրանք ասում էին. «Գնանք Դոթայիմ»: Յովսէփը գնաց իր եղբայրների ետեւից եւ նրանց գտաւ Դոթայիմում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Նրա եղբայրները հեռուից առաջինը իրենք նկատեցին նրան, երբ նա դեռ չէր մօտեցել իրենց: Նրանք իրար մէջ չար խորհուրդ արեցին, որ սպանեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Իւրաքանչիւրն իր եղբօրը դիմելով՝ ասում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, '«Ահա երազատեսը գալիս է: Եկէք սպանենք նրան, նետենք այստեղի հորերից մէկի մէջ եւ ասենք, թէ՝ «Վայրի գազան է կերել նրան»: Այն ժամանակ տեսնենք, թէ ի՞նչ կը լինեն նրա երազները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Երբ Ռուբէնը լսեց դա, նրանց ձեռքից փրկեց նրան. նա ասաց. «Չսպանենք նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ռուբէնն աւելացրեց. «Չթափենք նրա արիւնը, այլ նետեցէ՛ք նրան այս անապատի հորերից մէկի մէջ: Ձեռք մի՛ տուէք նրան»: Դա ասում էր, որպէսզի նրան փրկի նրանց ձեռքից եւ հասցնի իր հօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Երբ Յովսէփն եկաւ իր եղբայրների մօտ, նրանք նրա վրայից հանեցին ծաղկազարդ պատմուճանը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'եւ նրան նետեցին հորի մէջ: Հորը դատարկ էր, մէջը ջուր չկար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Նրանք նստեցին հաց ուտելու: Աչքերը վեր բարձրացնելով՝ տեսան, որ իսմայէլացի ճանապարհորդներ են գալիս Գաղաադից, ուղտերը խնկերով, ռետինով ու խէժով բարձած, որպէսզի դրանք տանեն Եգիպտոս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Յուդան իր եղբայրներին ասաց. «Ի՞նչ օգուտ, եթէ սպանենք մեր եղբօրը եւ թաքցնենք նրա արիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Եկէք նրան վաճառենք իսմայէլացիներին, եւ մեր ձեռքը նրա արեամբ չպղծուի, որովհետեւ ի վերջոյ նա մեր եղբայրն է՝ նոյն միս ու արիւնից»: Եւ իր եղբայրները լսեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Այնտեղից անցնում էին մադիանացի վաճառականներ: Եղբայրները Յովսէփին քաշեցին-հանեցին հորից եւ քսան դահեկանով վաճառեցին իսմայէլացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Իսմայէլացիները Յովսէփին տարան Եգիպտոս: Ռուբէնը վերադարձաւ դէպի հորը եւ Յովսէփին հորի մէջ չգտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Նա պատառոտեց իր հագուստները, վերադարձաւ իր եղբայրների մօտ ու ասաց. «Պատանին այնտեղ չէ, ես այժմ ո՞ւր գնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Նրանք առան Յովսէփի պատմուճանը, մի ուլ մորթեցին, պատմուճանը թաթախեցին ուլի արեան մէջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'ապա ծաղկազարդ պատմուճանն ուղարկեցին իրենց հօրն ու ասացին. «Գտել ենք սա, տե՛ս, քո՞ որդու պատմուճանն է սա, թէ՞ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Նա ճանաչեց այն ու ասաց. «Այս պատմուճանը իմ որդունն է, վայրի գազան է կերել նրան, մի գազան է յօշոտել Յովսէփին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Եւ նա պատառոտեց իր հագուստները, քուրձ կապեց իր մէջքին եւ երկար ժամանակ սուգ էր պահում իր որդու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Հաւաքուեցին նրա բոլոր որդիներն ու դուստրերը, եկան նրան մխիթարելու, բայց չէր կամենում մխիթարուել: Նա ասում էր. «Ես այս սգով էլ կ՚իջնեմ գերեզման՝ իմ որդու մօտ»: Եւ հայրը ողբաց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Իսկ մադիանացիները Եգիպտոսում Յովսէփին վաճառեցին փարաւոնի դահճապետին՝ ներքինի Պետափրէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Այդ ժամանակ Յուդան հեռացաւ իր եղբայրներից եւ եկաւ Իրաս անունով ոդողոմացի մի մարդու մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Յուդան այնտեղ տեսաւ քանանացի մի մարդու դստերը, որի անունը Շաւա էր: Նա ամուսնացաւ նրա հետ եւ մտաւ նրա ծոցը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Սա յղիացաւ, ունեցաւ որդի եւ անունը դրեց Էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Շաւան նորից յղիացաւ, ունեցաւ որդի եւ նրա անունը դրեց Օնան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Նա մի որդի էլ ունեցաւ եւ նրա անունը դրեց Սելոմ: Շաւան Քասբիում էր, երբ ծնեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Յուդան իր անդրանիկ որդի Էրի համար մի կին առաւ, որի անունը Թամար էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Յուդայի անդրանիկ որդի Էրը հաճելի չթուաց Տիրոջը, եւ Աստուած առաւ նրա հոգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Յուդան ասաց Օնանին. «Մտի՛ր քո եղբօր կնոջ ծոցը, ամուսնացի՛ր նրա հետ եւ զաւա՛կ պարգեւիր քո եղբօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Երբ Օնանը հասկացաւ, որ զաւակը իրենը չի լինի, իր եղբօր կնոջ ծոցը մտնելիս սերմը թափեց գետին, որպէսզի զաւակ չտայ իր եղբօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Օնանի արածը Աստծուն դուր չեկաւ, ուստի նրա հոգին էլ առաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Յուդան ասաց իր հարս Թամարին. «Այրի՛ մնա քո հօր տանը, մինչեւ որ մեծանայ իմ որդի Սելոմը»: Յուդան վախենում էր, որ նա էլ կը մեռնի իր եղբայրների պէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Թամարը գնաց ու ապրեց իր հօր տանը: Շատ օրեր անցան, եւ մեռաւ Յուդայի կին Շաւան: Յուդան սգից դուրս գալուց յետոյ իր ոդողոմացի հովիւ Իրասի հետ գնաց Թամնա՝ իր ոչխարները խուզելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Այդ մասին իմացաւ նրա հարս Թամարը, որովհետեւ նրան յայտնել էին, թէ՝ «Ահա քո սկեսրայրը գալիս է Թամնա՝ իր ոչխարները խուզելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Թամարն իր վրայից հանեց այրիութեան զգեստները, քող նետեց երեսին, զարդարուեց ու նստեց Ենանի դարպասի մօտ, Թամնա տանող ճանապարհի վրայ, որովհետեւ տեսաւ, որ Սելոմը մեծացել է, բայց Յուդան իրեն կնութեան չի տալիս նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Երբ Յուդան տեսաւ նրան, կարծեց, թէ բոզ է, որովհետեւ նա երեսը ծածկել էր, ուստի ինքը նրան չճանաչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Իր ճանապարհը թեքելով՝ Յուդան գնաց դէպի նա եւ ասաց. «Թո՛յլ տուր մտնեմ ծոցդ»: Նա չգիտէր, որ դա իր հարսն է: Սա ասաց. «Ի՞նչ կը տաս ինձ, եթէ մտնես ծոցս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Նա պատասխանեց. «Քեզ իմ հօտից այծի ուլ բերել կը տամ»: Սա ասաց. «Իսկ մինչեւ բերել տալդ գրաւ կը տա՞ս»: Նա ասաց. «Ի՞նչ գրաւ տամ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Սա ասաց. «Տո՛ւր մատանիդ, մանեակդ եւ այն գաւազանը, որ քո ձեռքին է»: Եւ նա մտաւ նրա ծոցը: Թամարը յղիացաւ նրանից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'եւ վեր կացաւ գնաց: Նա իր վրայից հանեց քողը եւ հագաւ այրիութեան իր զգեստները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Յուդան իր ոդողոմացի հովուի միջոցով այծի ուլ ուղարկեց, որպէսզի այդ կնոջից յետ ստանայ գրաւը, բայց հովիւը չգտաւ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Դիմելով տեղի մարդկանց՝ նա հարցրեց նրանց. «Ու՞ր է այն բոզը, որ Ենանում էր, ճանապարհի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Նրանք պատասխանեցին. «Այստեղ ոչ մի բոզ չի եղել»: Վերադառնալով Յուդայի մօտ՝ նա ասաց. «Նրան չգտայ: Տեղի մարդիկ էլ ասացին. «Այստեղ բոզ չկայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Յուդան ասաց. «Գրաւը նրան թող մնայ, միայն թէ ծաղրի առարկայ չդառնանք: Ես ուլը տուել եմ, որ տանես, դու էլ այդ կնոջը չես գտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Երեք ամիս յետոյ Յուդային յայտնեցին, թէ՝ «Պոռնկացել է քո հարս Թամարը եւ ահա պոռնկանալու պատճառով յղիացել է»: Յուդան ասաց. «Դո՛ւրս հանեցէք նրան, թող ողջ-ողջ այրուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Իրեն տանելու ճանապարհին Թամարը գրաւներն ուղարկեց իր սկեսրայրին՝ ասելով. «Ես յղիացել եմ այն տղամարդուց, որին պատկանում են այս գրաւները»: Եւ աւելացրեց. «Ճանաչի՛ր, ո՞ւմն են այս մատանին, մանեակը եւ գաւազանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Յուդան ճանաչեց դրանք ու ասաց. «Նա աւելի արդար է, քան ես, որովհետեւ նրան իմ որդի Սելոմին կնութեան չտուեցի»: Եւ այլեւս չմտաւ նրա ծոցը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Երբ Թամարը ծննդաբերելու վրայ էր, նրա որովայնում երկու զաւակներ կային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Ծննդաբերութեան պահին զաւակներից մէկն աւելի շուտ հանեց իր ձեռքը: Մանկաբարձը նրա ձեռքին կարմիր թել կապեց ու ասաց. «Անդրանիկը սա թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Երբ սա ձեռքը յետ տարաւ, անմիջապէս դուրս ելաւ նրա եղբայրը: Մանկաբարձն ասաց. «Ինչո՞ւ ճեղքեցիր պատնէշը»: Եւ նա նրա անունը դրեց Փարէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Ապա դուրս ելաւ նրա եղբայրը, որի ձեռքին կարմիր թել էր կապուած, եւ նրա անունը դրեց Զարա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Յովսէփին տարան Եգիպտոս: Ոմն եգիպտացի՝ փարաւոնի ներքինի դահճապետ Պետափրէսը, նրան գնեց նրան Եգիպտոս տարած իսմայէլացիներից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Տէրը Յովսէփի հետ էր, նրա գործերը բարեյաջող էին, եւ նա մնաց իր տիրոջ տանը՝ Եգիպտոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Երբ իր տէրը տեսաւ, որ Տէրը նրա հետ է, եւ ինչ էլ որ ինքն անում է, Տէրը յաջողութիւն է տալիս նրան, Յովսէփը շնորհ գտաւ տիրոջ առաջ, քանի որ հաճելի էր եղել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Դրա համար էլ նա նրան իր տան վերակացու կարգեց եւ իր ողջ ունեցուածքը վստահեց Յովսէփին: Երբ տէրը նրան իր տան եւ իր ունեցած ամէն ինչին վերակացու կարգեց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Աստուած Յովսէփի համար օրհնեց եգիպտացու տունը, եւ այդ օրհնութիւնը տարածուեց նրա տանն ու դաշտում եղած ամբողջ ունեցուածքի վրայ: Այն ամէնն, ինչ տէրն ունէր, թողեց Յովսէփի տնօրինութեանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Պետափրէսը չգիտէր, թէ ինչ կայ իր տանը, բացի իր կերած հացից: Յովսէփը դէմքով շատ գեղեցիկ էր ու վայելչակազմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Այս բոլորից յետոյ նրա տիրոջ կինն իր աչքը գցեց Յովսէփի վրայ ու ասաց նրան. «Պառկի՛ր ինձ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Բայց նա մերժեց՝ իր տիրոջ կնոջն ասելով, թէ՝ «Եթէ իմ տէրը իր տան ողջ ունեցուածքը վստահել է ինձ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'եւ այս տանը ինձնից աւելի մեծ մարդ չկայ, ու ինձ ոչինչ չի արգելուած, քեզնից բացի, որովհետեւ նրա կինն ես, ապա ես ինչպէ՞ս կարող եմ անել այդ չար ու սոսկալի բանը եւ մեղանչել Աստծու առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Թէեւ նա ամէն օր այդ մասին էր խօսում Յովսէփի հետ, բայց Յովսէփը չէր համաձայնում պառկել նրա հետ, ոչ իսկ մօտենալ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Այնպէս պատահեց, որ մի օր Յովսէփը իր ինչ-որ գործով տուն մտաւ: Ընտանիքի անդամներից ոչ ոք չկար տանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Կինը բռնեց նրա շորերից ու ասաց. «Պառկի՛ր ինձ հետ»: Յովսէփը թողնելով իր շորերը նրա ձեռքում՝ դուրս փախաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Երբ կինը տեսաւ, որ նա շորերը իր ձեռքում թողած դուրս է փախել, տան անդամներին կանչելով՝ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, '«Տեսէ՛ք, ամուսինս եբրայեցի ծառայ բերեց տուն, որ մեզ խայտառակ անի: Նա, մտնելով իմ սենեակը, ասաց. «Պառկի՛ր ինձ հետ»: Ես բարձրաձայն աղաղակեցի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'իսկ նա, լսելով իմ բարձրաձայն աղաղակը, շորերն ինձ մօտ թողած՝ փախաւ, գնաց դուրս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Նա շորերը պահեց մօտը մինչեւ ամուսինը տուն եկաւ, նրա հետ խօսեց այս բաները՝ ասելով, թէ՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, '«Սենեակս մտաւ քո բերած եբրայեցի ծառան, որպէսզի խայտառակի ինձ: Նա ասաց՝ «Պառկի՛ր ինձ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Իսկ երբ լսեց, որ ձայնս բարձրացրի, շորերն ինձ մօտ թողած՝ փախաւ, գնաց դուրս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Երբ տէրը լսեց իր կնոջ պատմածը, թէ՝ «Այսպէս վարուեց ինձ հետ քո ծառան», խիստ բարկացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Յովսէփի տէրը բռնեց ու բանտ նետեց նրան, այնտեղ, ուր արքունի կալանաւորներ էին բանտարկուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Բայց Աստուած Յովսէփի հետ էր. նա ողորմութիւն պարգեւեց նրան, եւ այնպէս արեց, որ նա բանտապետի բարեհաճութեանն արժանանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Բանտապետը բանտն ու բանտում եղած բոլոր կալանաւորներին վստահեց Յովսէփին: Եւ ինչ էլ որ լինում էր այնտեղ, նա էր անողը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Բանտապետը նրա շնորհիւ բանտի գործերին չէր խառնւում, որովհետեւ ամէն ինչ յանձնուած էր Յովսէփի ձեռքը: Աստուած նրա հետ էր, եւ ինչ էլ որ ինքն անում էր, Տէրը յաջողութիւն էր տալիս նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Այս դէպքերից յետոյ Եգիպտոսի արքայի տակառապետն ու մատակարարը մեղանչեցին իրենց տիրոջ՝ եգիպտացիների արքայի հանդէպ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Բարկացաւ փարաւոնն իր երկու ներքինիների՝ տակառապետի եւ մատակարարի վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'նրանց բանտ նետեց դահճապետի մօտ, այն բանտը, ուր Յովսէփն էր արգելափակուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Դահճապետը նրանց յանձնարարեց Յովսէփին. սա սպասարկում էր նրանց: Նրանք որոշ ժամանակ մնացին բանտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Միեւնոյն գիշերը բանտում երազ տեսան եգիպտացիների արքայի տակառապետն ու մատակարարը՝ ամէն մէկն իր երազը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Առաւօտեան Յովսէփը մտաւ նրանց մօտ եւ տեսաւ, որ նրանք յուզուած են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Նա հարց տուեց փարաւոնի ներքինիներին, որոնք իր հետ իր տիրոջ բանտում էին. «Ինչո՞ւ ձեր դէմքերն այսօր մռայլ են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Նրանք պատասխանեցին. «Երազ ենք տեսել, եւ չկայ մէկը, որ կարողանայ մեկնել այն»: Յովսէփն ասաց նրանց. «Չէ՞ որ Աստծու օգնութեամբ հնարաւոր է դրանց մեկնութիւնը: Պատմեցէ՛ք ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Տակառապետը Յովսէփին պատմեց իր երազը եւ ասաց. «Երազում իմ առաջ երեւաց մի որթատունկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Որթատունկն ունէր երեք շատ կանաչ ճիւղեր եւ հասունացած խաղողի երեք ողկոյզներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Փարաւոնի բաժակն իմ ձեռքին էր. վերցնում էի խաղողը, ճմլում փարաւոնի բաժակի մէջ եւ բաժակը տալիս էի փարաւոնի ձեռքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Յովսէփն ասաց նրան. «Դրա մեկնութիւնը հետեւեալն է. երեք ճիւղերը երեք օրեր են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Կ՚անցնի երեք օր, փարաւոնը կը յիշի քո նախկին իշխանութիւնը եւ քեզ նոյն տակառապետի պաշտօնին կը նշանակի: Դու փարաւոնի բաժակը կը տաս նրա ձեռքը՝ ըստ քո նախկին իշխանութեան, ինչպէս անում էիր տակառապետ եղած ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Իսկ երբ գործդ յաջող ընթանայ, դու յիշի՛ր ինձ, ողորմած եղի՛ր իմ հանդէպ, յիշի՛ր ինձ փարաւոնի առաջ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'եւ ինձ ազատի՛ր այս բանտից, որովհետեւ առեւանգելով՝ ինձ բերեցին Եբրայեցիների երկրից. եւ այստեղ ոչինչ չարեցի, բայց ինձ նետեցին այս բանտախուցը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Երբ մատակարարը տեսաւ, որ նա երազին ուղիղ մեկնութիւն տուեց, ասաց Յովսէփին. «Ես էլ եմ երազ տեսել: Երազիս մէջ գլխիս վրայ ընտիր ալիւրով լի երեք զամբիւղ կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Վերեւի զամբիւղի մէջ կային մատակարարների պատրաստած այն բոլոր ուտելիքները, որ ուտում էր փարաւոն արքան: Թռչուններն ուտում էին իմ գլխի վրայ գտնուող զամբիւղից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Յովսէփը, դիմելով նրան, ասաց. «Այս է դրա մեկնութիւնը. երեք զամբիւղները երեք օրեր են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Երեք օր յետոյ փարաւոնը կը կտրի քո գլուխը, իսկ մարմինդ կը կախի ծառից, եւ երկնքի թռչունները կը յօշոտեն քո մարմինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Երեք օր յետոյ փարաւոնի ծննդեան տարեդարձի օրն էր: Փարաւոնը խնջոյք էր կազմակերպել իր բոլոր ծառաների համար: Ի թիւս իր ծառաների, նա յիշեց իր պաշտօնեաներ տակառապետին ու մատակարարին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Նա տակառապետին վերականգնեց իր պաշտօնում, եւ սա բաժակը տուեց փարաւոնի ձեռքը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'իսկ մատակարարին կախեց ծառից, ինչպէս մեկնել էր Յովսէփը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Տակառապետը, սակայն, չյիշեց Յովսէփին. նա մոռացաւ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Երկու տարի անց փարաւոնը երազ տեսաւ: Երազում ինքը կանգնած էր գետի եզերքին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'իսկ գետից դուրս էին գալիս տեսքով գեղեցիկ ու մարմնով պարարտ եօթը երինջներ, որոնք արածում էին այնտեղ՝ ճահճուտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Դրանցից յետոյ գետից դուրս էին գալիս տեսքով տգեղ ու մարմնով նիհար եօթը այլ երինջներ եւ միւս երինջների հետ արածում գետի եզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Տեսքով տգեղ ու մարմնով նիհար եօթը երինջներն ուտում էին տեսքով գեղեցիկ ու պարարտ եօթը երինջներին: Զարթնեց փարաւոնը: Նորից քուն մտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Նա տեսաւ մի երկրորդ երազ. ահա մէկ ցօղունից բուսնում էին ընտիր ու գեղեցիկ եօթը հասկեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ապա բուսան չորուկ ու խորշակահար եօթը այլ հասկեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'եւ չորուկ ու խորշակահար եօթը հասկերը կուլ տուեցին ընտիր ու լի եօթը հասկերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Զարթնեց փարաւոնը եւ տեսաւ, որ երազ էր: Առաւօտեան խռովուեց նրա հոգին: Նա մարդ ուղարկեց, կանչել տուեց Եգիպտոսի բոլոր երազահաններին, երկրի բոլոր իմաստուններին եւ պատմեց իր երազները, բայց չգտնուեց մէկը, որ կարողանար մեկնել փարաւոնի երազները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Տակառապետը, դիմելով փարաւոնին, ասաց. «Այսօր յիշեցնեմ իմ յանցանքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Երբ փարաւոնը բարկացել էր իր ծառաների վրայ, ինձ ու մատակարարին արգելափակել էր դահճապետի տանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Մենք երկուսս էլ երազ տեսանք միեւնոյն գիշերը. իւրաքանչիւրս տեսաւ ի՛ր երազը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Այնտեղ մեզ հետ էր դահճապետի ծառայ եբրայեցի մի պատանի: Պատմեցինք նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'եւ նա մեկնեց մեզ մեր երազները՝ տալով իւրաքանչիւրիս իր երազի մեկնութիւնը: Եւ եղաւ, որ ինչպէս մեկնել էր մեզ, այնպէս էլ կատարուեց. ես եկայ հասայ իմ պաշտօնին, իսկ նրան կախեցին ծառից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Փարաւոնը մարդ ուղարկեց ու կանչել տուեց Յովսէփին: Հանեցին նրան բանտից, երեսն ածիլեցին, փոխեցին նրա պատմուճանը, եւ նա ներկայացաւ փարաւոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Փարաւոնն ասաց Յովսէփին. «Երազ եմ տեսել, եւ չկայ մէկը, որ մեկնի այն: Ես լսել եմ քո մասին: Ասում են, որ եթէ երազները պատմեն քեզ, դու կը մեկնես դրանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Պատասխան տալով՝ Յովսէփն ասաց փարաւոնին. «Առանց Աստծու օգնութեան փարաւոնի համար փրկարար ոչ մի պատասխան չի լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Փարաւոնը, դիմելով Յովսէփին, ասաց. «Երազումս ինձ թւում էր, թէ կանգնած էի գետի եզերքին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'եւ, իբրեւ թէ, գետից ելնում էին մարմնով պարարտ ու տեսքով գեղեցիկ եօթը երինջներ, որոնք արածում էին այնտեղ՝ ճահճուտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Ապա, դրանցից յետոյ գետից դուրս էին գալիս տեսքով շատ այլանդակ ու զզուելի եւ մարմնով նիհար եօթը երինջներ, որոնցից աւելի զզուելին չեմ տեսել ողջ Եգիպտացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Յոթը նիհար ու զզուելի երինջներն ուտում էին գեղեցիկ ու պարարտ առաջին եօթը երինջներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Նրանք թէեւ կուլ էին տալիս վերջիններիս, բայց չէր երեւում, որ նրանք սրանց կուլ են տուել. նրանց տեսքը առաջուայ պէս զզուելի էր: Զարթնեցի ու նորից քնեցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Դարձեալ երազում տեսայ, որ, իբրեւ թէ, մէկ ցօղունից բուսնում էին լի ու գեղեցիկ եօթը հասկեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Նրանց կողքին բուսան բարակ, չորուկ ու խորշակահար եօթը այլ հասկեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'եւ չորուկ ու խորշակահար եօթը հասկերը կուլ էին տալիս գեղեցիկ ու լի հասկերը: Երազներս պատմեցի երազահաններին, բայց ոչ մէկը չկար, որ դրանք մեկնէր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Յովսէփն ասաց փարաւոնին. «Փարաւոնի տեսած երազները մէկ իմաստ ունեն. Աստուած փարաւոնին յայտնել է այն, ինչ անելու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Եօթը գեղեցիկ երինջները եօթը տարի են նշանակում, եւ եօթը գեղեցիկ հասկերը նոյնպէս եօթը տարի են նշանակում: Փարաւոնի տեսած երազները մէկ իմաստ ունեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Դրանցից յետոյ ելած տգեղ ու վտիտ եօթը երինջները եօթը տարի են նշանակում, իսկ չորուկ ու խորշակահար եօթը հասկերը նշանակում են, որ եօթը տարի սով է լինելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Փարաւոնին ասածիս իմաստն այն է, որ Աստուած փարաւոնին յայտնել է այն, ինչ անելու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Ահա ողջ Եգիպտացիների երկրում լինելու են բերքառատ եօթը տարիներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Դրանցից յետոյ կը գան սովի եօթը տարիներ, եւ կը մոռացուի երկրում եղած բերքի առատութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Սովը կը սպառի երկիրը, եւ մարդիկ չեն իմանայ բերքի առատութիւնը դրան յաջորդող սովի պատճառով, քանի որ սովը շատ սաստիկ է լինելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Փարաւոնի երազի երկու անգամ կրկնուելը վկայում է, որ Աստծու խօսքը հաստատապէս կատարուելու է, եւ Աստուած չի յապաղի այն ի կատար ածելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Արդ, տե՛ս, գտի՛ր խոհեմ ու իմաստուն մի մարդու, որ դառնայ փարաւոնի խորհրդականը, եւ նրան վերակացու նշանակի՛ր Եգիպտացիների երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Փարաւոնը երկրի վրայ նաեւ գործակալներ թող նշանակի, որ Եգիպտացիների երկրի առատութեան եօթը տարիների ընթացքում բերքի մէկ հինգերորդ մասը հարկ վերցնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Նրանք թող հաւաքեն առաջին եօթը տարիների բերքի ամբողջ պաշարը, ցորենը թող դրուի փարաւոնի տրամադրութեան տակ, եւ պարէնը թող պահուի քաղաքներում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Երկրի պարէնը թող պահուի Եգիպտացիների երկրի վրայ տարածուելիք սովի եօթը տարիների համար, որպէսզի երկիրը սովից չկոտորուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Յովսէփի խօսքերը հաճելի թուացին փարաւոնին ու նրա բոլոր պաշտօնեաներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Փարաւոնն ասաց իր բոլոր պաշտօնեաներին. «Մի՞թէ կը գտնենք այսպիսի մի մարդ, որ իր անձի մէջ կրի Աստծու ոգին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Եւ փարաւոնն ասաց Յովսէփին. «Քանի որ Աստուած քեզ յայտնեց այդ ամէնը, ուրեմն քեզնից աւելի իմաստուն ու խելացի մարդ չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Դո՛ւ եղիր իմ տան վերակացուն, եւ քո հրամանին թող ենթարկուի իմ ամբողջ ժողովուրդը: Իմ գահո՛վ միայն ես քեզնից բարձր կը լինեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Փարաւոնն ասաց Յովսէփին. «Ահա այսօր քեզ վերակացու եմ կարգում Եգիպտացիների երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Եւ փարաւոնը մատից հանելով իր մատանին՝ դրեց Յովսէփի մատին, նրան հագցրեց բեհեզեայ պատմուճան, ոսկէ մանեակ անցկացրեց նրա պարանոցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'նրան նստեցրեց իր երկրորդ կառքը: Մունետիկը Յովսէփի առաջից գնալով՝ այդ մասին ազդարարեց, եւ նա վերակացու կարգուեց Եգիպտացիների երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Փարաւոնն ասաց Յովսէփին. «Ահա ես փարաւոնն եմ: Ամբողջ Եգիպտացիների երկրում ոչ ոք իրաւունք չունի նոյնիսկ իր ոտքը կամ ձեռքը բարձրացնելու առանց քո հրամանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Եւ փարաւոնը Յովսէփի անունը դրեց Փսոմփթոմբանէ, իսկ Արեգ քաղաքի քուրմ Պետափրէսի դուստր Ասանէթին նրան տուեց կնութեան: Եւ Յովսէփը գնաց փարաւոնի մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Յովսէփը երեսուն տարեկան էր, երբ ներկայացաւ եգիպտացիների փարաւոն արքային: Յովսէփը, գնալով փարաւոնի մօտից, շրջեց ողջ Եգիպտոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Երկիրը առատութեան եօթը տարիների ընթացքում հարուստ բերք տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Յովսէփը հաւաքեց Եգիպտացիների երկրի առատութեան եօթը տարիների ողջ բերքը՝ ամէն մի քաղաքի շուրջը գտնուող դաշտերի բերքը ամբարելով այդ քաղաքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Յովսէփը ծովի աւազի չափ շատ ցորեն հաւաքեց ու ամբարեց այնտեղ այնքան, որ հնարաւոր չէր հաշուել, քանի որ անթիւ-անհամար էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Երբ դեռ չէր եկել եօթը տարուայ սովը, Յովսէփն ունեցաւ երկու որդի, որոնց ծնել էր Արեգ քաղաքի քուրմ Պետափրէսի դուստր Ասանէթը նրա համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Յովսէփն անդրանիկ որդու անունը դրեց Մանասէ, «Որովհետեւ, - ասում է, - Աստուած ինձ մոռացնել տուեց իմ ու իմ հօր բոլոր վշտերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Երկրորդ որդու անունը դրեց Եփրեմ, «Որովհետեւ, - ասում է, - Աստուած ինձ բազմացրեց իմ տառապանքների երկրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Անցան Եգիպտացիների երկրի առատութեան եօթը տարիները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'եւ վրայ հասան սովի եօթը տարիները, ինչպէս ասել էր Յովսէփը: Սով եղաւ ամբողջ երկրում, որովհետեւ ողջ Եգիպտացիների երկրում հաց չէր գտնւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Սովի մատնուեց համայն Եգիպտացիների երկիրը, եւ ամբողջ ժողովուրդը հացի համար աղաղակ բարձրացրեց փարաւոնի առաջ: Փարաւոնն ասաց բոլոր եգիպտացիներին. «Գնացէ՛ք Յովսէփի մօտ, եւ ինչ որ ասի նա ձեզ, կատարեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Սով էր ամբողջ երկրում: Յովսէփը բացեց ցորենի բոլոր շտեմարանները եւ ցորեն էր վաճառում բոլոր եգիպտացիներին: Սովը սաստկացաւ Եգիպտացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Եւ բոլոր երկրներից գալիս էին Եգիպտոս՝ Յովսէփից հաց գնելու, որովհետեւ սովը սաստկանում էր ամբողջ աշխարհում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Յակոբը իմանալով, որ ցորենի վաճառք կայ Եգիպտացիների երկրում, ասում է իր որդիներին. «Ինչո՞ւ էք յապաղում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Իմացել եմ, որ Եգիպտոսում ցորեն կայ: Գնացէ՛ք այնտեղ եւ մեզ համար մի քիչ պարէն գնեցէ՛ք, որ ապրենք, սովամահ չլինենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Յովսէփի տասը եղբայրները իջան Եգիպտոսից ցորեն գնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Յակոբը Յովսէփի եղբայր Բենիամինին չթողեց, որ գնայ իր եղբայրների հետ, որովհետեւ ասում էր, թէ՝ «Գուցէ նա կը հիւանդանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Իսրայէլի որդիներն այլ ճանապարհորդների հետ եկան ցորեն գնելու, քանի որ Քանանացիների երկրում սով էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Յովսէփը երկրի իշխանն էր, ուստի ինքն էր ցորեն վաճառում երկրի ողջ ժողովրդին: Յովսէփի եղբայրները, գալով, գլուխները խոնարհեցին մինչեւ գետին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Երբ Յովսէփը տեսաւ իր եղբայրներին, ճանաչեց նրանց, բայց օտար ձեւացրեց իրեն, խստագոյնս խօսեց նրանց հետ եւ ասաց. «Որտեղի՞ց էք գալիս»: Նրանք պատասխանեցին. «Քանանացիների երկրից. եկել ենք պարէն գնելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Յովսէփը ճանաչեց իր եղբայրներին, բայց նրանք չճանաչեցին իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Յովսէփը յիշեց իր տեսած երազները եւ ասաց նրանց. «Դուք լրտեսներ էք եւ եկել էք երկիրը հետախուզելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Նրանք ասացին. «Ո՛չ, տէ՛ր: Մենք՝ քո ծառաները, եկել ենք ցորեն գնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Մենք ամէնքս մի մարդու զաւակներ ենք: Խաղաղասէր մարդիկ ենք մենք, քո ծառաները լրտեսներ չեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Յովսէփն ասաց նրանց. «Ո՛չ, դուք եկել էք երկիրը հետախուզելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Նրանք պատասխանեցին. «Մենք՝ քո ծառաները, տասներկու եղբայրներ էինք, Քանանացիների երկրում մի մարդու որդիներ: Այս պահին մեր կրտսեր եղբայրն իր հօր մօտ է, իսկ միւսն այլեւս չկայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Յովսէփն ասաց նրանց. «Ահա թէ ինչպիսի փորձի պիտի ենթարկուէք. հէնց դրա համար ասացի ձեզ՝ դուք լրտեսներ էք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Երդւում եմ փարաւոնի արեւով, որ այստեղից դուրս չէք գայ, քանի ձեր կրտսեր եղբայրն այստեղ չի եկել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Արդ, ձեզնից մէկին ուղարկեցէ՛ք, որ այստեղ բերի ձեր եղբօրը, իսկ դուք կը մնաք արգելարանում, մինչեւ որ պարզուի, թէ ճի՞շտ էք ասում, թէ՞ ոչ: Հակառակ դէպքում, երդւում եմ փարաւոնի արեւով, որ դուք լրտեսներ էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Եւ երեք օր նրանց բանտարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Յովսէփը երրորդ օրն ասաց նրանց. «Այսպէս արէք, որպէսզի փրկուէք. ես ինքս էլ աստուածավախ մարդ եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Եթէ խաղաղասէր մարդիկ էք, ձեր եղբայրներից մէկն այստեղ՝ բանտում կը մնայ, իսկ մնացածներդ կը տանէք ձեր գնած ցորենը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Ձեր կրտսեր եղբօրն ինձ մօտ կը բերէք, որ հաւատամ ձեր ասածներին, ապա թէ ոչ՝ մահուան կը դատապարտուէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Նրանք այդպէս էլ արեցին: Նրանք՝ եղբայրները, միմեանց ասացին. «Այո՛, մենք մեր եղբօր նկատմամբ մեղաւոր ենք, որովհետեւ անտեսեցինք նրա հոգու մղձաւանջը, երբ նա մեզ աղաչում էր, իսկ մենք նրան չլսեցինք: Դրա համար էլ մեր գլխին է իջնում այս պատուհասը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Պատասխան տուեց Ռուբէնն ու ասաց նրանց. «Ես ձեզ չասացի՞, թէ՝ «Մեղք մի՛ գործէք պատանու դէմ», իսկ դուք ինձ չլսեցիք: Հիմա նրա արեան գինն է պահանջւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Նրանք չգիտէին, որ Յովսէփը հասկանում էր նրանց, որովհետեւ թարգմանիչ ունէր: Եւ նրանցից մեկուսանալով՝ Յովսէփը լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Նա դարձեալ եկաւ նրանց մօտ եւ խօսեց նրանց հետ: Ապա նրանցից առանձնացնելով Շմաւոնին՝ նրանց ներկայութեամբ շղթայեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Յովսէփը հրամայեց, որ նրանց պարկերը լցնեն ցորենով, իւրաքանչիւրի արծաթը դնեն իր պարկի մէջ եւ ճանապարհի պաշար տան: Այդպէս էլ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Նրանք բարձելով իրենց էշերը՝ գնացին այնտեղից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Նրանցից մէկը, իջեւանում իր գրաստին կեր տալու համար բացելով իր պարկը, տեսաւ, որ իր արծաթի քսակը դրուած է իր պարկի բերանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Այն ժամանակ նա ասաց իր եղբայրներին. «Դրամը վերադարձրել են ինձ, ահա իմ պարկի մէջ է»: Նրանք զարմացան, իրար անցան ու ասացին. «Այս ի՞նչ արեց մեզ Աստուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Նրանք եկան իրենց հայր Յակոբի մօտ, Քանանի երկիրը, պատմեցին նրան այն ամէնը, ինչ պատահել էր իրենց հետ, եւ ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '«Մարդը, որ երկրի տէրն էր, մեզ հետ շատ խիստ խօսեց եւ մեզ, իբրեւ այդ երկրի լրտեսներ, բանտ նետեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Մենք նրան ասացինք. «Մենք խաղաղասէր մարդիկ ենք, լրտեսներ չենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Մենք տասներկու եղբայրներ ենք՝ մեր հօր որդիները: Մէկը չկայ, իսկ կրտսերն այս պահին մեր հօր մօտ է՝ Քանանացիների երկրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Երկրի տէրը մեզ ասաց. «Ձեր խաղաղասէր լինելը սրանով կ՚իմանամ, եթէ ձեր մի եղբօրն այստեղ՝ ինձ մօտ թողնէք, ձեր գնած ցորենը վերցնէք տանէք ձեր տուն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'եւ ձեր կրտսեր եղբօրը բերէք ինձ մօտ: Այն ժամանակ ես կ՚իմանամ, որ դուք լրտեսներ չէք, այլ խաղաղասէր մարդիկ էք, եւ ձեր այս եղբօրն էլ կը վերադարձնեմ ձեզ, եւ դուք այս երկրում առեւտուր կ՚անէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Երբ նրանք դատարկում էին իրենց պարկերը, իւրաքանչիւրի արծաթի քսակը իր պարկում էր: Եւ երբ նրանք տեսան իրենց արծաթի քսակները, իրենք եւ իրենց հայրը խիստ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Նրանց հայրը՝ Յակոբը, ասաց նրանց. «Ինձ անզաւակ էք թողնում: Յովսէփը չկայ, Շմաւոնը չկայ, հիմա էլ Բենիամինի՞ն էք վերցնելու: Այս բոլորը իմ գլխին են թափւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ռուբէնը, դիմելով հօրը, ասաց. «Դու իմ երկու որդիներին կը սպանես, եթէ նրան չվերադարձնեմ քեզ: Դու Բենիամինին վստահիր ինձ, եւ ես նրան կը վերադարձնեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Նա ասաց. «Իմ որդին ձեզ հետ չի իջնի, որովհետեւ սրա եղբայրը մեռաւ, եւ միայն սա է մնացել: Եթէ սա հիւանդանայ ձեր գնացած ճանապարհին, ապա դուք ինձ վշտով այս ծեր հասակում գերեզման կ՚իջեցնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Սովը աւելի ու աւելի էր սաստկանում երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Երբ կերան-սպառեցին Եգիպտացիների երկրից բերած ցորենը, հայրն ասաց նրանց. «Դարձեալ գնացէ՛ք եւ մի քիչ պարէն գնեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Յուդան, դիմելով նրան, ասաց. «Մարդը մեզ կտրուկ ու յստակ ասաց. «Իմ աչքին չերեւաք, եթէ ձեր կրտսեր եղբայրը ձեզ հետ չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Արդ, եթէ թողնես, որ մեր եղբայրը գայ մեզ հետ, կը գնանք եւ պարէն կը գնենք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'իսկ եթէ մեր եղբօրը մեզ հետ չթողնես, չենք գնայ, որովհետեւ այդ մարդը մեզ հետ խօսեց ու ասաց. «Իմ աչքին չերեւաք, եթէ ձեր կրտսեր եղբայրը ձեզ հետ չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Իսրայէլն ասաց. «Այդ ի՞նչ փորձանք բերեցիք իմ գլխին, ինչո՞ւ յայտնեցիք այդ մարդուն, թէ եղբայր ունէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Նրանք ասացին. «Այդ մարդը հարցուփորձ արեց մեր եւ մեր ընտանիքի մասին, թէ՝ «Տակաւին կենդանի՞ է ձեր հայրը», թէ՝ «Եղբայր ունէ՞ք»: Եւ մենք յայտնեցինք նրան ըստ նրա հարցերի: Ի՞նչ իմանայինք, թէ ասելու է մեզ. «Բերէ՛ք ձեր եղբօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Յուդան ասաց իր հայր Իսրայէլին. «Թո՛յլ տուր, որ պատանին գայ ինձ հետ, վեր կենանք գնանք, որպէսզի ե՛ւ մենք, ե՛ւ դու, ե՛ւ մեր ընտանիքի անդամները ապրենք, սովամահ չլինենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ես նրա համար պատասխանատու եմ. ինձնի՛ց կը պահանջես նրան: Եթէ նրան յետ չբերեմ ու քո առաջ չկանգնեցնեմ, թող մեղաւոր լինեմ իմ ամբողջ կեանքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Որովհետեւ եթէ չդանդաղէինք, ապա երկու անգամ գնացած-եկած կը լինէինք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Իրենց հայր Իսրայէլն ասաց նրանց. «Ճիշտ էք ասում: Այդպէս էլ արէք: Մեր երկրի բարիքներով լցրէ՛ք ձեր ամանները, այդ մարդուն իբրեւ նուէր տարէ՛ք կնդրուկ, մեղր, խունկ, խէժ, բեւեկն եւ ընկոյզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Կրկնակի արծաթ վերցրէ՛ք ձեզ հետ, ինչպէս նաեւ այն արծաթը, որ ձեր պարկերի մէջ յետ բերեցիք, տարէ՛ք ձեզ հետ, գուցէ դա սխալմունք էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Վերցրէ՛ք նաեւ ձեր եղբօրն ու գնացէ՛ք այդ մարդու մօտ: Իմ Աստուածը թող այնպէս անի, որ շնորհ գտնէք այդ մարդու մօտ, եւ նա կ՚արձակի ձեզ հետ ձեր միւս եղբօրն ու Բենիամինին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Բայց ես ինչպէս անզաւակացայ, այնպէս էլ անզաւակ մնացի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Եւ մարդիկ, առնելով նուէրներ ու կրկնակի արծաթ, Բենիամինի հետ գնացին իջան Եգիպտոս եւ ներկայացան Յովսէփին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Երբ Յովսէփը տեսաւ նրանց եւ իր եղբայր Բենիամինին՝ ասաց պալատի կառավարիչին. «Այս մարդկանց տուն տա՛ր, անասուն մորթի՛ր եւ ճաշ պատրաստի՛ր, որովհետեւ այս մարդիկ կէսօրին ինձ հետ են ճաշելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Մարդն արեց այնպէս, ինչպէս ասել էր Յովսէփը, եւ մարդկանց տարաւ Յովսէփի տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Այս մարդիկ տեսնելով, որ իրենց տարան Յովսէփի տունը, ասացին. «Նախորդ անգամ մեր պարկերում մեզ վերադարձուած արծաթի պատճառով է, որ մեզ բերեցին այստեղ, որպէսզի մեզ խուզարկեն: Նրանք մեզ վրայ կը յարձակուեն, մեզ կը ստրկացնեն եւ կը տիրանան մեր էշերին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Մօտենալով Յովսէփի պալատի կառավարիչին՝ նրանք դռան մօտ ասացին նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, '«Աղաչում ենք քեզ, տէ՛ր, լսի՛ր մեզ: Երբ առաջին անգամ եկանք պարէն գնելու');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'եւ վերադառնալիս իջեւան հասանք, բացելով մեր պարկերը՝ տեսանք, որ իւրաքանչիւրիս արծաթը իր պարկի մէջ է: Արդ, արծաթը նոյն կշռով յետ ենք բերել, ահա այն մեր ձեռքին է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Ուրիշ արծաթ էլ ենք բերել մեզ հետ, որ պարէն գնենք: Մենք չգիտենք, թէ ով է արծաթը դրել մեր պարկերի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Նա ասաց նրանց. «Խաղաղութիւն ընդ ձեզ, մի՛ վախեցէք: Ձեր եւ ձեր հայրերի Աստուածն է դրել գանձերը ձեր պարկերի մէջ, իսկ ես արդէն ստացել եմ ձեր արծաթը եւ գոհացել եմ»: Եւ նա բանտից հանեց ու նրանց մօտ բերեց Շմաւոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Մարդը նրանց տարաւ ներս՝ Յովսէփի տունը: Ջուր բերեցին, որ նրանք լուանան իրենց ոտքերը, եւ նա նրանց գրաստներին կեր տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Նրանք պատրաստեցին ընծաները, երբ Յովսէփը դեռ չէր եկել կէսօրին, որովհետեւ լսել էին, որ այնտեղ է ճաշելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Յովսէփը տուն մտաւ, եւ նրանք այդ տանը նրան մատուցեցին իրենց ձեռքերում բռնած ընծաները եւ գլուխ խոնարհեցին նրան մինչեւ գետին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Յովսէփը, դիմելով նրանց, հարցրեց. «Ինչպէ՞ս էք, ողջ-առո՞ղջ է ձեր ծերունի հայրը, որի մասին ասել էիք, թէ տակաւին կենդանի է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Նրանք պատասխանեցին. «Ողջ-առողջ է քեզ ծառայ մեր հայրը, տակաւին կենդանի է»: Նա ասաց. «Այդ մարդն օրհնեալ է Աստծուց»: Եւ նրանք խոնարհուելով գլուխ տուեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Յովսէփը բարձրացրեց իր աչքերը եւ, տեսնելով իր համամայր եղբայր Բենիամինին, հարցրեց. «Սա՞ է ձեր կրտսեր եղբայրը, որի մասին ասել էիք, թէ կը բերէք ինձ մօտ»: Եւ ասաց. «Աստուած թող ողորմի քեզ, որդեա՛կ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Յուզուեց Յովսէփը, իր եղբօր համար ճմլուեց սիրտը եւ ուզում էր լաց լինել: Եւ, մտնելով իր սենեակը, նա լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Յետոյ նա լուաց երեսը, դուրս եկաւ եւ, զսպելով իրեն, ասաց. «Ճա՛շ մատուցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Քանի որ եգիպտացիները զզւում էին եբրայեցիներից եւ նրանց հետ սեղան չէին նստում, ուստի նրան եւ նրանցից իւրաքանչիւրին, ինչպէս նաեւ նրա հետ ճաշող եգիպտացիներից իւրաքանչիւրին ճաշ մատուցեցին առանձին-առանձին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Նրա դիմաց նստեց անդրանիկը՝ ըստ իր աւագութեան, իսկ կրտսերը՝ ըստ իր կրտսերութեան: Եւ մարդիկ զարմացել էին իւրաքանչիւրն իր եղբօր համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Նրանք Յովսէփից ստացան իրենց ճաշի բաժինը, եւ Բենիամինի բաժինը բոլորի բաժնի հնգապատիկը դարձաւ: Նրանք նրա հետ խմեցին ու գինովցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Յովսէփն իր պալատի կառավարչին հրաման տուեց եւ ասաց. «Այդ մարդկանց պարկերը լցրէ՛ք պարէնով այնքան, որքան կարող են տանել, եւ իւրաքանչիւրի արծաթը դրէ՛ք իր պարկի բերանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Իմ արծաթէ սկիհը դրէ՛ք կրտսեր եղբօր պարկի մէջ: Այնտեղ դրէ՛ք նաեւ նրա ցորենի գինը»: Եւ արուեց ըստ Յովսէփի ասածի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Առաւօտեան թոյլ տուեցին, որ նրանք գնան իրենց էշերով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Երբ նրանք քաղաքից դուրս ելան, բայց դեռ հեռու չէին գնացել, Յովսէփն ասաց իր պալատի կառավարիչին. «Վե՛ր կաց, հետապնդի՛ր այդ մարդկանց, հասի՛ր նրանց ու ասա՛. «Ինչո՞ւ էք լաւութեան դիմաց վատութիւն անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ինչո՞ւ գողացաք արծաթէ սկիհը: Չէ՞ որ դրանով էր խմում իմ տէրը եւ դրանով էր գուշակութիւն անում: Արդ, ձեր արածը չար գործ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Երբ նա հասաւ նրանց, այդպէս էլ ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Նրանք պատասխանեցին նրան. «Ինչո՞ւ է տէրը այդպիսի բաներ ասում: Քա՛ւ լիցի, որ քո ծառաները նման բան արած լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Եթէ մեր պարկերում գտնուած արծաթը Քանանացիների երկրից մենք վերադարձրել ենք ձեզ, էլ ինչո՞ւ քո տիրոջ տնից արծաթ կամ ոսկի պիտի գողանայինք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Արդ, քո ծառաներից ում մօտ որ գտնուի սկիհը, թող մահուան դատապարտուի, իսկ մենք՝ մնացածներս, լինենք մեր տիրոջ ստրուկները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Նա ասաց. «Թող լինի այնպէս, ինչպէս ասացիք. ում մօտ որ գտնուի սկիհը, թող նա դառնայ իմ ստրուկը, իսկ մնացածներդ համարուէք անպարտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Եւ նրանցից իւրաքանչիւրն շտապ իջեցնելով իր բեռը՝ բացեց իր պարկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Կառավարիչը, աւագից սկսած մինչեւ կրտսերը, խուզարկեց եւ սկիհը գտաւ Բենիամինի պարկի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Նրանք պատառոտեցին իրենց զգեստները, եւ իւրաքանչիւրն իր բեռը բարձելով իր էշի վրայ՝ վերադարձաւ քաղաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Յուդան ու իր եղբայրները ներկայացան Յովսէփին, երբ նա դեռ տանն էր, եւ նրա առաջ երեսի վրայ ընկան գետին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Յովսէփն ասաց նրանց. «Այս ի՞նչ է ձեր արածը, մի՞թէ չգիտէք, որ այնպիսի մի մարդ, ինչպիսին ես եմ, գուշակելու կարողութիւն ունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Յուդան ասաց. «Ի՞նչ պատասխան տանք մեր տիրոջը, ի՞նչ ասենք կամ ինչպէ՞ս արդարանանք: Աստուած բռնեց քո ծառաների գործած յանցանքը: Արդ, ահա մեր տիրոջ ստրուկներն ենք ե՛ւ մենք, ե՛ւ նա, ում մօտ գտնուեց սկիհը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Նա ասաց. «Քա՛ւ լիցի, ես այդպիսի բան չեմ անի: Այն մարդը, որի մօտ գտնուել է սկիհը, նա՛ թող լինի իմ ստրուկը, իսկ դուք ողջ ու անվնաս գնացէ՛ք ձեր հօր մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Յուդան, մօտենալով նրան, ասաց. «Աղաչում եմ, տէ՛ր, թո՛յլ տուր, որ քո ծառան մի բան ասի քո առաջ: Մի՛ բարկացիր քո ծառայի վրայ, որովհետեւ փարաւոնից յետոյ դո՛ւ ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Տէ՛ր, դու հարցրեցիր քո ծառաներին եւ ասացիր, թէ՝ «Հայր կամ եղբայր ունէ՞ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Եւ մենք պատասխանեցինք մեր տիրոջը. «Ունենք տարիքն առած մի հայր եւ մի կրտսեր եղբայր, որ նա ունեցել է ծեր տարիքում: Սրա եղբայրը մեռել է, եւ սա մնացել է իր մօր միակ որդին, եւ հայրը սիրում է նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Դու քո ծառաներին ասացիր. «Նրան բերէ՛ք ինձ մօտ, եւ ես կը հոգամ նրա մասին«:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Մենք ասացինք մեր տիրոջը. «Երեխան չի կարող բաժանուել իր հօրից, որովհետեւ եթէ բաժանուի իր հօրից, հայրը կը մեռնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Դու ասացիր քո ծառաներին. «Եթէ ձեր կրտսեր եղբայրը ձեզ հետ չիջնի, չհամարձակուէք երեւալ իմ աչքին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Երբ մենք գնացինք քո ծառայի՝ մեր հօր մօտ եւ յայտնեցինք նրան մեր տիրոջ խօսքերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'մեր հայրն ասաց. «Նորից գնացէ՛ք եւ մի քիչ պարէն գնեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Մենք ասացինք. «Չենք կարող այնտեղ իջնել, եթէ մեր կրտսեր եղբայրը մեզ հետ չիջնի: Մենք միայն այդ պայմանով կ՚իջնենք: Եթէ մեր կրտսեր եղբայրը մեզ հետ չլինի, ապա այդ մարդուն ներկայանալ չենք կարող»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Քո ծառան՝ մեր հայրը, մեզ ասաց. «Դուք ինքներդ էլ գիտէք, որ իմ կին Ռաքէլն ինձ համար երկու որդի ծնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Մէկը տնից հեռացաւ, եւ դուք ասացիք, թէ նա գազանի բաժին դարձաւ: Նրան այլեւս չեմ տեսել մինչեւ հիմա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Արդ, եթէ սրան էլ տանէք իմ մօտից, եւ ճանապարհին նա հիւանդանայ, ապա դուք ինձ վշտով այս ծեր հասակում գերեզման կ՚իջեցնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Արդ, եթէ մենք գնանք քո ծառայի՝ մեր հօր մօտ, եւ պատանին մեզ հետ չլինի, ապա մեր հօր կեանքը կախուած կը լինի սրա կեանքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Այնպէս որ, եթէ նա այդ երեխային մեզ հետ չտեսնի, կը մեռնի, եւ մենք՝ քո ծառաները, քո ծառային՝ մեր հօրը, ծեր հասակում խոցուած սրտով գերեզման կ՚իջեցնենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ես՝ քո ծառան, այդ մանկանն իր հօրից ստացել եմ իմ երաշխաւորութեամբ: Ես ասել եմ. «Եթէ նրան չվերադարձնեմ ու չներկայացնեմ քեզ, ապա իմ ամբողջ կեանքում թող յանցաւոր լինեմ հօրս առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Արդ, այս մանկան փոխարէն ես՝ քո ծառան, լինեմ իմ տիրոջ ստրուկը, իսկ պատանին թող գնայ իր եղբայրների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Որովհետեւ ինչպէ՞ս կարող եմ իմ հօրը ներկայանալ, եթէ այս պատանին մեզ հետ չլինի: Թող ես չտեսնեմ այն դժբախտութիւնը, որ հօրս է վիճակուելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Յովսէփը չկարողացաւ իրեն զսպել իր շուրջը գտնուող բոլոր եգիպտացիների ներկայութեամբ եւ ասաց. «Բոլորին դո՛ւրս հանէք»: Երբ նրանցից ոչ ոք չմնաց նրա մօտ, նա եղբայրներին յայտնեց իր ով լինելը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Նա բարձրաձայն լաց եղաւ այնպէս, որ դա լսեցին եգիպտացիները, եւ եղելութիւնը յայտնի դարձաւ փարաւոնի արքունիքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Յովսէփն ասաց իր եղբայրներին. «Ես Յովսէփն եմ: Իրօք, դեռ կենդանի՞ է իմ հայրը»: Նրա եղբայրները չէին կարողանում նրան պատասխանել, որովհետեւ տակնուվրայ եղան նրա ներկայութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Յովսէփն ասաց եղբայրներին. «Մօտեցէ՛ք ինձ»: Նրանք մօտ գնացին: Յովսէփն ասաց. «Ես ձեր եղբայր Յովսէփն եմ, որին դուք վաճառեցիք, որ Եգիպտոս տանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Բայց դուք մի՛ տրտմէք, մի՛ նեղուէք, որ ինձ վաճառել էք այստեղ բերելու համար, որովհետեւ Աստուած ձեզ փրկելու համար է ուղարկել ինձ այստեղ ձեզնից առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Հիմա երկրի վրայ եղած սովի երկրորդ տարին է, եւ հինգ տարի եւս կայ, որ ո՛չ վար է լինելու, ո՛չ հունձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Աստուած ձեզնից առաջ ինձ ուղարկել է այստեղ, որ երկրի վրայ պահպանի ձեր սերնդին եւ կերակրի ձեզ՝ մնացածներիդ մեծ մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Արդ, ոչ թէ դուք էք ինձ ուղարկել այստեղ, այլ՝ Աստուած: Նա ինձ դարձրեց փարաւոնի գործերի վերակացու, նրա ողջ տան տէրը եւ համայն Եգիպտացիների երկրի իշխանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Արդ, շտապ գնացէ՛ք իմ հօր մօտ եւ ասացէ՛ք նրան. «Այսպէս է ասում քո որդի Յովսէփը. Աստուած ինձ ողջ Եգիպտացիների երկրի տէր է դարձրել: Արի իջի՛ր ինձ մօտ եւ մի՛ դանդաղիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Դու կը բնակուես Գեսեմ երկրում՝ Արաբիայում եւ մօտ կը լինես ինձ, դու, քո որդիները, քո որդիների որդիները քո ոչխարներով ու արջառներով, ամբողջ ունեցուածքով: Ես քեզ կը կերակրեմ այստեղ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'որովհետեւ դեռ հինգ տարի եւս սով է լինելու, որպէսզի չկոտորուէք դու, քո որդիները, եւ չոչնչանայ քո ամբողջ ունեցուածքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ահա դուք եւ Բենիամինը ձեր սեփական աչքերով տեսնում էք, որ անձամբ ես եմ խօսում ձեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Իմ հօրը պատմեցէ՛ք այն փառքի մասին, որին ես հասել եմ Եգիպտոսում, նաեւ այն մասին, ինչ տեսել էք: Իմ հօրը շտապ բերէ՛ք այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Եւ նա փաթաթուեց իր եղբայր Բենիամինի պարանոցին ու լաց եղաւ. Բենիամինն էլ լաց եղաւ նրա պարանոցին փաթաթուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Յովսէփը համբուրեց նաեւ իր բոլոր եղբայրներին եւ գրկախառնուած լաց եղաւ: Դրանից յետոյ միայն իր եղբայրները խօսեցին նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Լուրը հասաւ փարաւոնի պալատ. ասացին. «Յովսէփի եղբայրներն են եկել»: Ուրախացան փարաւոնն ու նրա պաշտօնեաները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Փարաւոնն ասաց Յովսէփին. «Քո եղբայրներին ասա՛՝ «Այսպէ՛ս արէք. լցրէ՛ք ձեր պարկերը, գնացէ՛ք Քանանացիների երկիրը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'եւ, վերցնելով ձեր հօրն ու ձեր ունեցուածքը, եկէ՛ք ինձ մօտ: Ես ձեզ կը տամ Եգիպտոսի բոլոր բարիքներից, եւ դուք կը վայելէք երկրի սերուցքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Դու այսպիսի կարգադրութիւն կ՚անես. «Եգիպտացիների երկրից առէ՛ք սայլեր ձեր մանուկների ու կանանց համար եւ ձեր հօրը վերցնելով՝ բերէ՛ք այստեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Ձեր աչքերը թող ագահութեամբ չնայեն ձեր ունեցուածքի վրայ, որովհետեւ ողջ Եգիպտացիների երկրի բարիքները ձերն են լինելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Այդպէս էլ արեցին Իսրայէլի որդիները: Յովսէփը փարաւոն արքայի կարգադրութեան համաձայն՝ նրանց տուեց սայլեր ու ճանապարհի պաշար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Նա բոլորին երկուական պատմուճան տուեց, իսկ Բենիամինին տուեց երեք հարիւր դահեկան եւ հինգ պատմուճան՝ փոխնիփոխ հագնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Նոյնպէս եւ, հօրը տանելու համար, նա տուեց տասը էշի վրայ բեռնուած Եգիպտոսի բոլոր բարիքներից, պարէնով բեռնաւորուած տասը ջորի, նաեւ՝ հօր համար ճանապարհի պաշար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Նա ճանապարհեց իր եղբայրներին, եւ սրանք գնացին: Նա նրանց ասաց. «Ճանապարհին չվիճէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Նրանք Եգիպտոսից ելան-գնացին Քանանացիների երկիրը, իրենց հօր՝ Յակոբի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Պատմեցին նրան եւ ասացին. «Քո որդի Յովսէփը կենդանի է, նա ողջ Եգիպտացիների երկրի իշխանն է»: Յակոբը զարմացաւ, որովհետեւ չէր հաւատում նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Նրանք իրենց հօրը հաղորդեցին այն ամէնը, ինչ ասել էր Յովսէփը: Նրանց հայր Յակոբը, տեսնելով այն սայլերը, որ Յովսէփն էր ուղարկել՝ իրեն տանելու համար, վերակենդանացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Իսրայէլն ասաց. «Բաւ է ինձ, որ իրօք տակաւին կենդանի է իմ որդի Յովսէփը: Քանի ողջ եմ, գնամ տեսնեմ նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Իսրայէլն իր ամբողջ ունեցուածքով ճանապարհ ընկաւ եւ եկաւ Երդման ջրհորի մօտ: Նա զոհ մատուցեց իր հայր Իսահակի Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Գիշերը Աստուած տեսիլքի մէջ Իսրայէլին ասաց. «Յակո՛բ, Յակո՛բ»: Սա հարցրեց. «Դու ո՞վ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Նա պատասխանեց. «Ես քո հայրերի Աստուածն եմ: Մի՛ վախեցիր Եգիպտոս իջնելուց, որովհետեւ քեզ այնտեղ մեծ ազգ եմ դարձնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ես քեզ հետ կ՚իջնեմ Եգիպտոս, եւ ինքս էլ քեզ ընդմիշտ կը հանեմ այնտեղից: Եւ Յովսէփն իր ձեռքով կը փակի քո աչքերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Յակոբը Երդման ջրհորի մօտից ելաւ, եւ Իսրայէլի որդիներն իրենց հայր Յակոբին, կահկարասին ու կանանց տեղաւորեցին այն սայլերի վրայ, որ Յովսէփն էր ուղարկել՝ նրան բերելու համար: Վերցնելով իրենց ունեցուածքն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'ու Քանանացիների երկրում ձեռք բերած ամէն ինչ, Եգիպտոս մտան Յակոբն ու նրա ողջ սերունդը՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'իր որդիներն ու որդիների որդիները, իր դուստրերն ու դուստրերի դուստրերը: Նա իր ողջ սերունդը բերեց Եգիպտոս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Սրանք են Իսրայէլի այն որդիների անունները, որոնք Եգիպտոս մտան. այն է՝ Յակոբն ու իր որդիները: Յակոբի անդրանիկ որդին էր Ռուբէնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Ռուբէնի որդիներն են՝ Ենոքը, Փալլուսը, Ասրոնն ու Քարմին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Շմաւոնի որդիներն են՝ Յամուէլը, Յամինը, Ահոդը, Յաքինը, Սահառն ու քանանացի կնոջից ծնուած Սաւուղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Ղեւիի որդիներն են՝ Գերսոնը, Կահաթն ու Մերարին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Յուդայի որդիներն են՝ Էրը, Օնանը, Սելոմը, Փարէսն ու Զարան: Էրն ու Օնանը մեռան Քանանացիների երկրում: Փարէսի որդիները եղան Ասրոմն ու Յամուէլը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Իսաքարի որդիներն են՝ Թողան, Փուդը, Յասուբն ու Զամամը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Զաբուղոնի որդիներն են՝ Սերեդը, Ալլոնն ու Էէլը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Սրանք Լիայի որդիներն են, որոնց, նաեւ իր դուստր Դինային, նա ծնեց Յակոբի համար՝ Ասորիների Միջագետքում. բոլորը՝ որդիներն ու դուստրերը, երեսուներեք հոգի էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Գադի որդիներն են՝ Սափոնը, Մեդիսը, Սաւնիան, Թաւսոբամը, Այեդիսը, Արոյէլիսը եւ Արիէլիսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Ասերի որդիներն են՝ Յեմնան, Յեսուան, Յէուլը, Բարիան եւ նրանց քոյր Սարան: Բարիայի որդիներն են՝ Քոբորը եւ Մելքիէլը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Սրանք որդիներն են Զելփայի, որին Լաբանը տուել էր իր դուստր Լիային: Սա Յակոբի համար ունեցաւ այս տասնվեց որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Ռաքէլի՝ Յակոբի կնոջ որդիներն են՝ Յովսէփն ու Բենիամինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Եգիպտացիների երկրում Արեգ քաղաքի քուրմ Պետրափրեսի դուստր Ասանէթից Յովսէփն ունեցաւ իր Մանասէ ու Եփրեմ որդիներին: Մանասէն ասորի հարճից ունեցաւ որդիներ, որոնցից մէկն էր Մաքիրը: Մաքիրը ծնեց Գաղաադին: Եփրեմի՝ Մանասէի եղբօր որդիներն են՝ Սուտաղաամն ու Տաամը: Սուտաղաամի որդին է Եդ»մը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Բենիամինի որդիներն են՝ Բաղան, Բոքորն ու Ասբեէն: Բաղան ծնեց որդիներ՝ Գէերային, Նէեմանին, Անաքիսին, Ռոսին, Մամփիմին ու Ոփիմինին: Գէերան ծնեց Արադին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Սրանք Ռաքէլի որդիներն են, որոնց նա ծնեց Յակոբի համար. բոլորը՝ տասնութ հոգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Դանի որդիներից մէկն է Ասոմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Նեփթաղիմի որդիներն են՝ Ասիէլը, Գոնին, Ասարն ու Սիլլեմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Սրանք որդիներն են Բալայի, որին Լաբանը տուեց իր դուստր Ռաքէլին. Բալլան ծնեց սրանց Յակոբի համար. բոլորը՝ եօթը հոգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Յակոբի կողից ծնուած եւ նրա հետ Եգիպտոս մտած բոլոր մարդկանց թիւը, չհաշուած Յակոբի որդիների կանանց, վաթսունվեց է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Յովսէփը Եգիպտոսում ունեցաւ երկու որդի: Այսպիսով Յակոբի ընտանիքի՝ Եգիպտոս մտած բոլոր տղամարդկանց թիւը եօթանասունհինգ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Յակոբը իրենից առաջ Յուդային ուղարկեց Յովսէփի մօտ, որպէսզի սա ընդառաջ գայ նրան Քաջաց քաղաքի մօտ՝ Ռամէսի երկրում, իսկ ինքն եկաւ Գեսեմ երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Յովսէփը լծեց իր կառքը եւ Քաջաց քաղաքի մօտ ընդառաջ գնաց իր հայր Իսրայէլին: Երբ Յովսէփը հանդիպեց նրան, փաթաթուեց նրա վզին եւ հեկեկալով լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Իսրայէլն ասաց Յովսէփին. «Այսուհետեւ կարող եմ մեռնել, որովհետեւ տեսայ քո երեսը, եւ դու տակաւին կենդանի ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Յովսէփն ասաց իր եղբայրներին ու իր հօր ընտանիքին. «Գնամ յայտնեմ փարաւոնին, որ Քանանացիների երկրում բնակուող իմ եղբայրներն ու հօրս ընտանիքը եկել են ինձ մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Նրանք խաշնարածներ են եւ իրենց անասունները, արջառներն ու ողջ ունեցուածքը բերել են այստեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Արդ, եթէ փարաւոնը կանչի ձեզ ու հարցնի, թէ՝ «Ի՞նչ է ձեր գործը»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'կ՚ասէք, որ «Մենք՝ քո ծառաները, մանուկ հասակից մինչեւ այժմ խաշնարածներ ենք, մենք եւ մեր հայրը», որպէսզի նա թոյլ տայ ձեզ բնակուել Գեսեմ երկրում, որովհետեւ եգիպտացիները խորշում են ոչխարների հովիւներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Յովսէփն եկաւ եւ այդ մասին պատմեց փարաւոնին: Նա ասաց. «Իմ հայրն ու եղբայրները իրենց ոչխարներով ու արջառներով, իրենց ամբողջ ունեցուածքով եկել են Քանանացիների երկրից եւ ահա Գեսեմում են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Նա իր եղբայրներից հինգին հետն առնելով՝ ներկայացրեց փարաւոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Փարաւոնը հարցրեց Յովսէփի եղբայրներին. «Ի՞նչ գործ էք անում»: Նրանք պատասխանեցին փարաւոնին. «Թէ՛ մենք, թէ՛ մեր հայրերը՝ քո ծառաները, ոչխարների հովիւներ ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Նրանք ասացին փարաւոնին. «Պանդխտութեան ենք եկել այս երկիրը, որովհետեւ քո ծառաների ոչխարները կեր չունեն, քանի որ Քանանացիների երկրում սաստկացել է սովը: Արդ, թո՛յլ տուր, որ մենք՝ քո ծառաները, բնակուենք Գեսեմ երկրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Փարաւոնը, դիմելով Յովսէփին, ասաց. «Քո հայրն ու քո եղբայրները եկել են քեզ մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Ահա Եգիպտացիների երկիրը քո առջեւ է. արգաւանդ մի շրջանում բնակեցրո՛ւ քո հօրն ու եղբայրներին: Նրանք թող բնակուեն Գեսեմ երկրում: Իսկ եթէ գիտես, որ նրանց մէջ կան կարող մարդիկ, իմ ոչխարների հօտերի վրայ վերակացու կարգի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Յովսէփն իր հայր Յակոբին բերեց ու ներկայացրեց փարաւոնին: Եւ Յակոբն օրհնեց փարաւոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Փարաւոնը հարցրեց Յակոբին. «Քանի՞ տարեկան ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Յակոբը պատասխանեց փարաւոնին. «Պանդխտութեան մէջ անցկացրած տարիներիս թիւը հարիւր երեսուն է: Քիչ ու դժուարին են եղել իմ ապրած տարիները եւ չեն հասել իմ նախնիների պանդխտութեան մէջ անցկացրած տարիներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Յակոբն օրհնեց փարաւոնին եւ հեռացաւ նրա մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Յովսէփը իր հօրն ու եղբայրներին բնակեցրեց Եգիպտացիների երկրի բարեբեր մի շրջանում՝ Ռամէսի երկրում, ինչպէս հրամայել էր փարաւոնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Յովսէփը օրապահիկ էր տալիս իր հօրն ու եղբայրներին, իսկ իր հօր ընտանիքի բոլոր անդամներին՝ ցորեն ըստ շնչի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Պարէնն սպառուել էր ողջ երկրում, քանի որ սովը խիստ սաստկացել էր: Սովից հիւծուեցին Եգիպտացիների երկիրն ու Քանանացիների երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Յովսէփը ցորեն վաճառելով հաւաքեց Եգիպտացիների երկրի ու Քանանացիների երկրի ողջ արծաթը, որի դիմաց այդ երկրների մարդկանց պարէն էր տալիս: Յովսէփը ամբողջ արծաթը տարաւ փարաւոնի արքունիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Արծաթն սպառուեց Եգիպտացիների երկրից ու Քանանացիների երկրից: Բոլոր եգիպտացիները եկան Յովսէփի մօտ ու ասացին. «Մեզ հա՛ց տուր. ինչո՞ւ մեռնենք քո աչքի առաջ, քանի որ արծաթը վերջացաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Յովսէփն ասաց նրանց. «Եթէ արծաթն սպառուել է, բերէ՛ք ձեր անասունները, եւ ես ձեր անասունների փոխարէն հաց կը տամ ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Նրանք անասունները բերեցին Յովսէփի մօտ, իսկ Յովսէփը ձիու, ոչխարի, արջառի եւ էշի փոխարէն նրանց հաց էր տալիս: Նա այդ տարի նրանց բոլոր անասունների փոխարէն նրանց կերակրեց հացով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Այդ տարին անցաւ. նրանք երկրորդ տարին եկան Յովսէփի մօտ եւ ասացին. «Արդեօ՞ք կորստի կը մատնուենք մեր տիրոջ կողմից: Տէ՛ր, եթէ արծաթ կար, վերջացաւ, եթէ ոչխարներ եւ անասուններ՝ քեզ մօտ են: Մենք այլեւս ոչինչ չունենք մեր տիրոջը տալու, բացի մեր անձերից ու մեր հողից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Արդ, որպէսզի քո աչքի առաջ սովամահ չլինենք, եւ երկիրն էլ չկործանուի, ստացի՛ր մեզ եւ մեր հողը հացի փոխարէն. մենք ու մեր հողը թող լինենք փարաւոնի սեփականութիւն: Սերմացու տո՛ւր, որ ցանենք, ապրենք ու չմեռնենք, եւ երկիրն էլ չկործանուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Եւ Յովսէփը գնեց ողջ Եգիպտացիների երկիրը փարաւոնի համար, որովհետեւ եգիպտացիներն իրենց հողերը վաճառեցին փարաւոնին, քանի որ սովը սաստիկ սպառնում էր նրանց կեանքին: Այսպիսով երկիրը դարձաւ փարաւոնի սեփականութիւն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'եւ սա Եգիպտոսի մի ծայրից մինչեւ միւս ծայրը բնակուող ժողովրդին դարձրեց իր ստրուկը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'բացի քրմերի կալուածքներից, որովհետեւ Յովսէփը դրանք չգնեց, քանի որ փարաւոնը քրմերին առատօրէն պարգեւատրում էր, եւ նրանք սնւում էին այն պարգեւներով, որ նրանց էր տալիս փարաւոնը: Այդ է պատճառը, որ նրանք չվաճառեցին իրենց կալուածքները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Յովսէփը բոլոր եգիպտացիներին ասաց. «Ահա ձեզ եւ ձեր հողը ես գնեցի փարաւոնի համար: Առէ՛ք ձեր սերմացուն եւ ցանեցէ՛ք ձեր հողերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Երբ բերքը կը ստանաք, փարաւոնին կը տաք դրա մէկ հինգերորդ մասը, իսկ չորս հինգերորդը թող ձեզ լինի իբրեւ հողի սերմացու եւ սնունդ՝ ձեզ, ձեր ընտանիքի բոլոր անդամների ու ձեր երեխաների համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Նրանք ասացին. Մեզ փրկեցիր, մենք արժանացանք մեր տիրոջ գթութեանը, ուստի թող լինենք փարաւոնի ստրուկները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Յովսէփը նրանց համար օրէնք սահմանեց, որ մինչեւ այսօր էլ գործում է Եգիպտացիների երկրում. բերքի մէկ հինգերորդ մասը տուրք տալ փարաւոնին, բացի քրմական հողերից, որոնք փարաւոնին չէին պատկանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Իսրայէլը բնակուեց Եգիպտացիների երկրում՝ Գեսեմում: Նրանք այնտեղ կալուածքներ ստացան, խիստ աճեցին ու բազմացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Յակոբը Եգիպտացիների երկրում ապրեց տասնեօթը տարի, եւ նա դարձաւ հարիւր քառասունեօթը տարեկան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Երբ մօտեցան Իսրայէլի մահուան օրերը, նա կանչեց իր որդի Յովսէփին ու ասաց նրան. «Եթէ ես շնորհ գտայ քո առաջ, ապա ձեռքդ դի՛ր իմ զիստի տակ ու խոստացի՛ր, որ իմ նկատմամբ արդար եւ ողորմած կը լինես եւ ինձ Եգիպտոսում չես թաղի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'երբ միանամ իմ նախնիներին, ինձ թող տանեն Եգիպտոսից ու թաղեն նրանց գերեզմանում»: Յովսէփն ասաց. «Կ՚անեմ ինչպէս ասացիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Յակոբն ասաց. «Երդուի՛ր ինձ»: Եւ նա երդուեց նրան, մինչ Իսրայէլը խոնարհուեց նրա գաւազանի գլխի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Այս դէպքերից յետոյ Յովսէփին յայտնեցին, թէ՝ «Քո հայր Յակոբը հիւանդ է»: Յովսէփը վերցնելով իր երկու որդիներին՝ Մանասէին ու Եփրեմին, եկաւ Յակոբի մօտ: Այդ մասին Յակոբին տեղեակ պահեցին՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, '«Ահա քո որդի Յովսէփը քեզ մօտ է գալիս»: Իսրայէլն ուժերը հաւաքեց ու նստեց անկողնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Յակոբն ասաց Յովսէփին. «Իմ Աստուածն ինձ երեւաց Լուզում՝ Քանանացիների երկրում, օրհնեց ինձ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'ու ասաց. «Ահա ես կ՚աճեցնեմ ու կը բազմացնեմ քեզ, բազում ազգերի նախահայր կը դարձնեմ: Այս երկիրը քեզ կը տամ իբրեւ յաւիտենական ժառանգութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Արդ, մինչեւ իմ Եգիպտոս գալը Եգիպտոսում ծնուած քո երկու որդիները իմն են: Եփրեմն ու Մանասէն ինձ համար թող լինեն ինչպէս Ռուբէնն ու Շմաւոնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'իսկ միւս զաւակները, որոնց ծնունդ կը տաս սրանցից յետոյ, թող քոնը լինեն: Նրանք իրենց ժառանգութիւնն ստանալու համար թող կոչուեն իրենց եղբայրների անուամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Երբ ես գալիս էի Ասորիների Միջագետքից ու մի ասպարէզի չափ մօտեցել էի Քաբրաթա երկրին, Քանանացիների երկրում մեռաւ քո մայր Ռաքէլը: Ես նրան թաղեցի ճանապարհին, Եփրաթա չհասած. դա Բեթղեհէմն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Երբ Իսրայէլը տեսաւ Յովսէփի որդիներին, հարց տուեց. «Սրանք քո ի՞նչն են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Յովսէփը պատասխանեց հօրը. «Իմ որդիներն են, որոնց Աստուած պարգեւեց ինձ այստեղ»: Յակոբն ասաց. «Նրանց բե՛ր ինձ մօտ, որ օրհնեմ նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Իսրայէլի աչքերը ծերութեան պատճառով տկարացել էին, նա լաւ չէր տեսնում: Յովսէփը նրանց մօտեցրեց նրան, Յակոբը համբուրեց նրանց ու իր գիրկն առաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Իսրայէլն ասաց Յովսէփին. «Ահա ոչ միայն կարօտս առայ քեզնից, այլեւ Աստուած ինձ ցոյց տուեց նաեւ քո զաւակներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Յովսէփը նրանց վերցրեց նրա ծնկներից, եւ նրանք մինչեւ գետին խոնարհուեցին նրա առաջ: Յովսէփը առաւ իր երկու որդիներին՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Եփրեմին ունենալով իր աջ կողմում, այսինքն՝ Իսրայէլի ձախ կողմում, եւ Մանասէին իր ձախ կողմում, այսինքն՝ Իսրայէլի աջ կողմում, ու մօտեցրեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Իսրայէլը մեկնելով իր աջ ձեռքը՝ դրեց Եփրեմի գլխին, որ կրտսերն էր, իսկ ձախը՝ Մանասէի գլխին եւ փոխեց ձեռքերի տեղը, քանի որ Մանասէն էր անդրանիկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Օրհնեց նրանց եւ ասաց. «Աստուած, որին հաճոյ եղան իմ նախնիները՝ Աբրահամն ու Իսահակը, Աստուած, որ պահպանեց ինձ իմ մանկութիւնից մինչեւ այսօր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Հրեշտակը, որ փրկեց ինձ ամէն տեսակ փորձանքներից, թող օրհնի այս մանուկներին, թող սրանց մէջ վերապրի իմ անունը եւ իմ նախնիների՝ Աբրահամի ու Իսահակի անունը, նրանք օրհնեալ լինեն երկրի վրայ եւ շատ բազմանան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Յովսէփը տեսաւ, որ հայրն իր աջը դրել է Եփրեմի գլխին, եւ դա ծանր թուաց նրան: Յովսէփն ուզեց օգնել հօրը, որ նա իր ձեռքը հանի Եփրեմի գլխի վրայից եւ դնի Մանասէի գլխին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Յովսէփն ասաց իր հօրը. «Կարգն այդպէս չէ, հա՛յր, որովհետեւ սա է անդրանիկը: Քո աջը դիր սրա՛ գլխին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Հայրը, սակայն, այդ չկամեցաւ, այլ ասաց. «Գիտեմ, որդեա՛կ, գիտեմ: Սա նոյնպէս ժողովուրդ թող դառնայ, փառաւորուի, բայց սրա կրտսեր եղբայրը նրանից մեծ կը լինի: Նրա որդին բազում ազգերի նախահայր կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Յակոբն այդ օրը օրհնեց նրանց՝ ասելով. «Իսրայէլը թող ձեր միջոցով օրհնեալ լինի: Թող ասեն. «Աստուած քեզ հետ թող վարուի այնպէս, ինչպէս Եփրեմի ու Մանասէի հետ»: Եւ նա Եփրեմին աւելի առաջ դասեց, քան Մանասէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Իսրայէլն ասաց Յովսէփին. «Ահա մեռնում եմ: Աստուած ձեզ հետ լինի եւ ձեզ վերադարձնի ձեր նախնիների երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ես քեզ իբրեւ սեփականութիւն տալիս եմ իմ սրով ու աղեղով ամորհացիներից գրաւած Սիկիմը, որն աւելի մեծ է, քան քո եղբայրների բաժինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Յակոբը կանչեց իր որդիներին ու ասաց. «Հաւաքուեցէ՛ք, որ ձեզ յայտնեմ այն, ինչ պատահելու է ձեզ հետագայում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Հաւաքուեցէ՛ք եւ լսեցէ՛ք, Յակոբի որդիներ, լսեցէ՛ք ձեր հայր Իսրայէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ռուբէ՛ն, իմ անդրանիկ որդի, իմ զօրութիւն ու իմ որդիների սկիզբ. դու ինձ հետ խիստ վարուեցիր եւ մեծ յանդգնութեամբ կշտամբեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Ջրի նման մի՛ եռա, քանզի մտել ես մահիճը քո հօրու պղծել այնժամ մահիճը նրա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Եղբայրներ Շմաւոնն ու Ղեւինանիրաւութիւն գործեցին կամովին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Խորհրդին նրանց մասնակից չի լինի անձն իմ.նրանց դաւին յօժար չէ սիրտն իմ. ցասումով իրենց մարդ սպանեցինհաճոյքի համար ջլակոտոր արեցին ցուլեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Անիծեալ լինի ցասումը նրանց,քանզի յանդուգն էր. անիծուի նրանց ոխն ու մոլուցքը,քանզի սաստիկ էր:Կը բաժանեմ ես նրանց Յակոբի մէջ,կը ցրեմ նրանց Իսրայէլի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Յուդա՛, քեզ կ՚օրհնեն եղբայրները քո.ձեռքը քո կ՚իջնի թիկունքի վրայ թշնամիներիդ:Հօրդ որդիներն գլուխ խոնարհեն պիտի քո առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Յուդա՛, կորի՛ւն առիւծի,իմ շառաւիղից ելար, որդեա՛կ իմ,Ելար, բազմեցիր, ննջեցիր դու որպէս առիւծ,որպէս կորիւն առիւծի:Ո՞վ պիտի արդեօք արթնացնի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Յուդայից իշխան չի պակասելու, ոչ էլ առաջնորդ՝ նրա կողերից,մինչեւ որ գայ նա, ում պատկանում են հանդերձեալները: Նրա՛ն են սպասում ժողովուրդները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Իր աւանակին կը կապի որթից,իսկ որթի ոստից՝ էշի քուռակին:Իր պատմուճանը կը լուայ գինովեւ իր հագուստը՝ խաղողի արեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Գինուց զուարթ են աչքերը նրա,իսկ ատամներն սպիտակ՝ կաթից աւելի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Զաբուղոնը կը բնակուի ծովի եզերքին, որպէս նաւերի նա նաւահանգիստու կը տարածուի նա մինչեւ Սիդոն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Իսաքարը բարուն ցանկացաւ եւ հանգիստ ապրեց իր տարածքներում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Տեսնելով, որ հանգիստը լաւ է, հողը՝ բարեբեր, ուսերը դրեց աշխատանքի տակու դարձաւ բարիք ստեղծող մի մարդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Դանը կը դատի իր ժողովրդին Իսրայէլի մէջ մէկ մարդու նման.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Դանը թող լինի օձ դարանակալ ճանապարհի վրայ՝խայթելու համար ձիու գարշապարն ու ցած գցելու հեծեալին նրա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Մնա՜լ, սպասե՜լ Տիրոջ փրկութեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Գադն աւազակների ծուղակը կ՚ընկնիեւ ինքն էլ, սակայն, կը հետապնդի աւազակներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Ասերի հացը առատ կը լինի,իշխաններին էլ նա պարէն կը տայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Նեփթաղիմը բարձրուղէշ ծառ է,որ իր բազում ճիւղերով գեղեցկութիւն է սփռում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Փառքի բարձրացած որդեա՛կ իմ Յովսէփ, որդեա՛կ իմ՝ դարձած դու նախանձելի,դարձի՛ր դու ինձ մօտ, որդեա՛կ իմ մատաղ, բանսարկուները բամբասում էին, դատափետում քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Նրա դէմ ոխով բորբոքւում էին աղեղնաւորներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Փշրուեցին զօրութեամբ աղեղները նրանց,ու թուլացան ջլերը նրանց բազուկներիՅակոբի հզօր Աստծու ձեռքով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'նրա՛ կողմից, ով զօրացրեց Իսրայէլին՝Աստծուց քո հօր:Եւ քեզ օգնեց Աստուածն իմ,նա օրհնեց քեզ ի վերուստ օրհնութեամբ մի երկնային,ամէն ինչով լի երկրի օրհնութեամբեւ օրհնեց նաեւ ստինք ու արգանդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Քո հօր օրհնութիւնն ու մօր օրհնութիւննառաւել ուժեղ, քան օրհնանքը յաւերժական լեռների,քան օրհնանքը յաւիտենական բլուրների,իջնի թող գլխի վրայ Յովսէփի ու գլխին նրա եղբայրների,որոնց առաջնորդեց նա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Բենիամի՛ն՝ յափշտակող գա՛յլ,առաւօտեան իր որսն ուտող,երեկոյեան պատառ բաշխող»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Այս բոլորը՝ Յակոբի որդիները, տասներկու ցեղերն են: Սա է ահա, ինչ որ խօսեց նրանց հայրը իրենց հետ: Նա իւրաքանչիւրին օրհնեց իրեն արժանի օրհնութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Նա պատուիրեց նրանց՝ ասելով. «Ես գնում եմ իմ նախնիների գիրկը: Ինձ թաղեցէ՛ք իմ նախնիների մօտ, այն քարայրում, որ քետացի Եփրոնի ագարակում է, այն զոյգ քարայրում, որ այդ դաշտում է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Մամբրէի կաղնու դիմաց, Քանանացիների երկրում: Այդ քարայրը Աբրահամը գնել էր քետացի Եփրոնից իբրեւ սեփական շիրմավայր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Այնտեղ են թաղել Աբրահամին ու նրա կնոջը՝ Սառային: Այնտեղ են թաղել Իսահակին ու նրա կնոջը՝ Ռեբեկային: Այնտեղ են թաղել Լիային. սա ագարակի եւ նրա մէջ գտնուող քարայրի այն կալուածքն է, որ գնուեց Քետի որդիներից: Այնտեղ են թաղել Աբրահամին ու նրա կնոջը՝ Սառային: Այնտեղ են թաղել Իսահակին ու նրա կնոջը՝ Ռեբեկային: Այնտեղ են թաղել Լիային. սա ագարակի եւ նրա մէջ գտնուող քարայրի այն կալուածքն է, որ գնուեց Քետի որդիներից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Յակոբը դադարեց իր որդիներին պատուիրան տալուց, ոտքերը յետ բերեց մահիճի մէջ, մեռաւ եւ գնաց իր նախնիների գիրկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Յովսէփն ընկնելով իր հօր երեսին՝ լաց եղաւ նրա վրայ եւ համբուրեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Յովսէփը հրամայեց դի զմռսող իր սպասաւորներին զմռսել իր հօրը. զմռսողները զմռսեցին Իսրայէլին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Լրացան նրա քառասուն օրերը. այդքան էր տեւում թաղելու կարգը: Եգիպտոսը եօթանասուն օր սգաց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Սգոյ օրերն անցնելուց յետոյ Յովսէփը խօսեց փարաւոնի իշխանների հետ եւ ասաց. «Եթէ շնորհ եմ գտել ձեր առաջ, ապա դիմեցէ՛ք փարաւոնին եւ ասացէ՛ք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'որ իմ հայրը երդուեցրել է ինձ ու ասել. «Ահա ես մեռնում եմ: Ինձ կը թաղես այն շիրիմում, որ ես ինձ համար փորել եմ Քանանացիների երկրում»: Արդ, թո՛յլ տուր գնամ, թաղեմ իմ հօրն ու վերադառնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Փարաւոնն ասաց. «Գնա՛, թաղի՛ր քո հօրը, ինչպէս որ նա երդուեցրել է քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Յովսէփը գնաց, որ թաղի իր հօրը: Նրա հետ գնացին նաեւ փարաւոնի բոլոր ծառաները, նրա պալատի աւագանին, Եգիպտացիների երկրի բոլոր աւագները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Յովսէփի ամբողջ ընտանիքը, նրա եղբայրները, նրա հօր ընտանիքի բոլոր անդամները: Իսկ մերձաւորներին, ոչխարներին ու արջառներին թողեցին Գեսեմ երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Նրա հետ գնացին նաեւ կառքերն ու հեծեալները եւ դարձան մի հսկայ բանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Նրանք հասան Յորդանանի այն կողմը գտնուող Ատադի կալը եւ այնտեղ սաստիկ ողբ ու կոծ արեցին նրա վրայ: Նա հօր համար եօթը օր սուգ արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Քանանացիների երկրի բնակիչները, տեսնելով Ատադի կալում արուած սուգը, ասացին. «Եգիպտացիները մեծ սգի մէջ են»: Դրա համար էլ այդ վայրը կոչուեց Եգիպտոսի Սուգ. այն Յորդանանի միւս կողմն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Իսրայէլի որդիները նրա դիակի հետ վարուեցին այնպէս, ինչպէս նա էր պատուիրել իրենց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'վերցրին նրան ու թաղեցին այնտեղ: Նրա որդիները նրան տարան Քանանացիների երկիրը եւ թաղեցին Մամբրէի կաղնու դիմաց, զոյգ քարայրում, որ Աբրահամը գնել էր քետացի Եփրոնից իբրեւ սեփական շիրմավայր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Յովսէփը վերադարձաւ Եգիպտոս. ինքը, իր եղբայրները եւ իր հօրը թաղելու համար իր հետ գնացած բոլոր մարդիկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Երբ Յովսէփի եղբայրները տեսան, որ իրենց հայրը մահացել է, ասացին. «Գուցէ Յովսէփը ոխ է պահել մեր դէմ եւ վրէժ կը լուծի այն բոլոր չարիքների համար, որ մենք պատճառեցինք նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Նրանք եկան Յովսէփի մօտ ու ասացին. «Քո հայրը երբ դեռ չէր մեռել, մեզ երդուեցրել էր');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'ու ասել. «Այսպէս կ՚ասէք Յովսէփին. նրանք չարիք գործեցին քո դէմ, բայց դու կը ներես նրանց յանցանքներն ու մեղքերը»: Արդ, ների՛ր քո հօր Աստծու ծառաների յանցանքները»: Յովսէփն իրեն ասուած այս խօսքերի համար լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Նրա եղբայրները գալով իր մօտ՝ ընկան նրա ոտքերն ու ասացին. «Ահա մենք քո ծառաներն ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Յովսէփը նրանց ասաց. «Մի՛ վախեցէք, որովհետեւ ես էլ Աստծու մարդն եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Դուք մտածեցիք ինձ չարիք պատճառել, բայց Աստուած իմ նկատմամբ բարի վարուեց, ինչպէս որ եղաւ այսօր, որովհետեւ մարդկանց մեծ բազմութիւն կերակրեցի ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Նա ասաց նրանց. «Մի՛ վախեցէք: Ես կը կերակրեմ ձեզ եւ ձեր ընտանիքները»: Յովսէփը մխիթարեց եւ հանգստացրեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Եւ Եգիպտոսում բնակուեցին Յովսէփն ինքը, իր եղբայրներն ու իր հօր ողջ գերդաստանը: Յովսէփն ապրեց հարիւր տասը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Յովսէփը տեսաւ Եփրեմի որդիների մինչեւ երրորդ սերունդը: Մանասէի որդի Մաքիրի որդիները ծնուեցին Յովսէփի ծնկներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Յովսէփը, դիմելով իր եղբայրներին, ասաց. «Ահա ես մեռնում եմ: Աստուած թող այցելի ձեզ, հանի այս երկրից ու տանի այն երկիրը, որ Աստուած երդուել է տալ մեր նախնիներին՝ Աբրահամին, Իսահակին ու Յակոբին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Յովսէփը երդուեցրեց Իսրայէլի որդիներին ու ասաց. «Այն ժամանակ, երբ Աստուած ձեզ կ՚այցելի, այստեղից կը հանէք նաեւ իմ ոսկորները եւ կը տանէք ձեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Յովսէփը վախճանուեց հարիւր տասը տարեկան հասակում: Թաղեցին նրան ու տապանի մէջ դրեցին Եգիպտոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Սրանք են Իսրայէլի այն որդիների անունները, որոնք իրենց հօր հետ մտան Եգիպտոս, իւրաքանչիւրն իր ամբողջ ընտանիքով մտաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ռուբէն, Շմաւոն, Ղեւի, Յուդա,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Իսաքար, Զաբուղոն եւ Բենիամին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Դան եւ Նեփթաղիմ, Գադ եւ Ասեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Յակոբից սերուած բոլոր մարդիկ եօթանասունհինգ հոգի էին: Յովսէփը գտնւում էր Եգիպտոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Վախճանուեց Յովսէփը. նաեւ նրա բոլոր եղբայրներն ու ամբողջ սերունդը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Իսրայէլի որդիները, սակայն, աճեցին ու բազմացան: Նրանք խիստ բազմացան ու հզօրացան, որովհետեւ երկիրը նպաստում էր նրանց բազմանալուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Գահ բարձրացաւ մի ուրիշ թագաւոր, որը Յովսէփին չէր ճանաչում: Նա իր ժողովրդին ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, '«Իսրայէլի որդիների սերունդը մեծ է զօրութեամբ եւ զօրանում է մեզնից աւելի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Արդ, եկէք ինչ-որ բան հնարենք նրանց դէմ, գուցէ աւելի բազմանան, եւ երբ պատերազմ ծագի, նրանք միանան թշնամիներին ու մեր դէմ կռուելով՝ դուրս ելնեն այս երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Եւ նա վերակացուներ կարգեց նրանց վրայ, որ գործի լծելով՝ չարչարեն նրանց: Նրանք փարաւոնի համար կառուցեցին Փիդոն, Ռամեսէ եւ Ովն անառիկ քաղաքները: Ովնը Արեգ քաղաքն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Բայց որքան ճնշում էին նրանց, նրանք այնքան աւելի էին բազմանում ու անչափ հզօրանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Եգիպտացիները զզուեցնում էին Իսրայէլի որդիներին, բռնութիւն գործադրելով նեղում էին նրանց, տաժանակիր աշխատանքի էին լծում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'նրանց կեանքը մաշում կաւի, աղիւսաշինութեան ու դաշտային բոլոր գործերի մէջ՝ բռնութեամբ ստիպելով նրանց, որ ծառայեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Եգիպտացիների արքան դիմեց եբրայեցիների մանկաբարձներին. նրանցից մէկի անունը Սեփորա էր, իսկ երկրորդի անունը՝ Փուա: Եւ արքան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'ասաց. «Երբ երկունքով բռնուած եբրայեցի կանանց մօտ գնաք ծննդաբերութեան օգնելու, եթէ ծնուածը արու լինի, սպանեցէ՛ք նրան, իսկ եթէ էգ լինի, ո՛ղջ թողէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Մանկաբարձները, աստուածավախ լինելով, չարեցին այն, ինչ եգիպտացիների արքան հրամայել էր իրենց. նրանք ողջ էին թողնում նաեւ արուներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Եգիպտացիների արքան կանչեց մանկաբարձներին ու ասաց նրանց. «Ինչո՞ւ էք այդպէս վարւում, ինչո՞ւ էք ողջ թողնում արուներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Մանկաբարձները պատասխանեցին փարաւոնին. «Եբրայեցի կանայք եգիպտացի կանանց նման չեն. նրանք ծննդաբերում են մինչեւ որ մանկաբարձները իրենց մօտ գան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Նրանք ծննդաբերում էին, եւ Աստուած բարութիւն էր անում մանկաբարձներին, ուստի ժողովուրդը խիստ բազմանում էր ու անչափ հզօրանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Քանի որ մանկաբարձները աստուածավախ էին, նրանք տուն-տեղ դրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Փարաւոնն իր ամբողջ ժողովրդին հրամայելով՝ ասաց. «Եբրայեցիներից ծնուած բոլոր արու զաւակներին գե՛տը նետեցէք, իսկ բոլոր աղջիկ զաւակներին ո՛ղջ թողէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Այնտեղ էր գտնւում Ղեւիի ցեղից մի մարդ, որն ամուսնացաւ Ղեւիի դուստրերից մէկի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Սա յղիացաւ ու ծնեց մի արու զաւակ: Տեսնելով, որ նա գեղեցիկ է, երեք ամիս թաքցրին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Երբ այլեւս չէին կարող նրան թաքցնել, նրա մայրն առաւ եղէգից հիւսուած մի զամբիւղ, այն ծեփեց կպրաձիւթով, դրա մէջ դրեց մանկանը եւ զամբիւղը դրեց ծանծաղուտ մի տեղ, գետափին մօտիկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Մանկան քոյրը հեռուից հետեւում էր՝ տեսնելու համար, թէ ինչ կը պատահի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Այդ ժամանակ էր, որ փարաւոնի դուստրն եկաւ գետում լողանալու, իսկ նրա նաժիշտները քայլում էին գետի ափով: Ծանծաղուտի մէջ զամբիւղ նկատելով՝ նա մի նաժիշտ ուղարկեց, որ վերցնի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Նա բացեց եւ տեսաւ երեխային: Երեխան լաց էր լինում զամբիւղում: Փարաւոնի դուստրը, խղճալով նրան, ասաց. «Եբրայեցիների երեխաներից է դա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Մանկան քոյրն ասաց փարաւոնի դստերը. «Ուզո՞ւմ ես, որ եբրայեցիներից մի դայեակ կին կանչեմ, նա թող կերակրի այդ մանկանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Փարաւոնի դուստրն ասաց՝ «գնա՛»: Աղջիկը գնաց ու կանչեց մանկան մօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Փարաւոնի դուստրը նրան ասաց. «Վերցրո՛ւ այդ մանկանը եւ կերակրի՛ր նրան ինձ համար: Ես կը տամ քո վարձը»: Կինը վերցրեց մանկանը եւ կերակրեց նրան: Երբ մանուկը մեծացաւ, կինը նրան բերեց փարաւոնի դստեր մօտ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'եւ մանուկը նրան որդեգիր դարձաւ: Նա նրան Մովսէս կոչեց ասելով՝ ջրից եմ հանել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Շատ օրեր յետոյ, երբ Մովսէսը մեծացաւ, գնաց իր ազգակիցների՝ իսրայէլացիների մօտ, ականատես եղաւ նրանց չարչարանքներին: Նա նկատեց, որ մի եգիպտացի ծեծում էր իր եբրայեցի եղբայրներից մէկին՝ մի իսրայէլացու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Մովսէսն այս ու այն կողմ նայեց եւ ոչ ոքի չտեսնելով, սպանեց եգիպտացուն եւ նրան թաղեց աւազի տակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Յաջորդ օրը նա տեսաւ իրար հետ կռուող երկու եբրայեցիների եւ անիրաւութիւն անողին ասաց. «Ինչո՞ւ ես ծեծում ընկերոջդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Սա պատասխանեց. «Ո՞վ է քեզ իշխան ու դատաւոր կարգել մեզ վրայ, թէ՞ ինձ էլ ես ուզում սպանել, ինչպէս որ երէկ սպանեցիր եգիպտացուն»: Մովսէսը վախեցաւ՝ մտածելով, որ եղելութիւնը յայտնի է դարձել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Երբ փարաւոնը լսեց այդ դէպքի մասին, պահանջեց, որ սպանեն Մովսէսին: Մովսէսը փախաւ փարաւոնի պատճառով ու բնակուեց Մադիամի երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Մադիամի երկիրը գալով՝ նա նստեց մի ջրհորի մօտ: Մադիանացիների քուրմն ունէր եօթը դուստր, որոնք արածեցնում էին իրենց հօր ոչխարները: Նրանք եկել էին ջուր հանելու եւ լցնելու աւազանները, որպէսզի ջրեն իրենց հօր ոչխարները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Բայց եկան ուրիշ հովիւներ եւ աղջիկներին հեռու քշեցին: Մովսէսը ոտքի ելաւ եւ պաշտպանեց նրանց, ջուր հանեց ու ջրեց նրանց ոչխարները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Աղջիկներն եկան իրենց հօր՝ Հռագուէլի մօտ: Սա նրանց հարցրեց. «Ինչո՞ւ այսօր օրը ցերեկով վերադարձաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Նրանք պատասխանեցին. «Մի եգիպտացի տղամարդ մեզ փրկեց այդ հովիւների ձեռքից, ջուր հանեց ու ջրեց մեր ոչխարները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Հայրը հարցրեց իր դուստրերին. «Իսկ ո՞ւր է նա, ինչո՞ւ թողեցիք այդ մարդուն: Արդ, կանչեցէ՛ք նրան, որ հաց ուտի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Եւ Մովսէսը բնակուեց այդ մարդու մօտ, եւ սա իր դուստր Սեփորային Մովսէսին կնութեան տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Կինը յղիացաւ ու ծնեց որդի, որին Մովսէսը Գերսամ անուանեց ասելով՝ ես պանդուխտ եմ օտար երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Շատ օրեր անց մեռաւ եգիպտացիների թագաւորը: Իսրայէլացիները, որոնք տանջւում էին տաժանակիր աշխատանքի մէջ, աղաղակ բարձրացրին. նրանց աղաղակը հասաւ Աստծուն: Եւ Աստուած լսեց նրանց հեծութիւնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'յիշեց իր ուխտը, որ կապել էր Աբրահամի, Իսահակի ու Յակոբի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Աստուած իր հայեացքն ուղղեց իսրայէլացիներին: Նա յայտնուեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Մովսէսն արածեցնում էր իր աներոջ՝ Յոթորի՝ մադիանացիների քրմի ոչխարները: Նա ոչխարները տարաւ անապատ ու հասաւ Աստծու լեռը՝ Քորէբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Տիրոջ հրեշտակը երեւաց նրան մորենու միջից կրակի բոցով: Մովսէսը տեսնում էր, որ մորենին հրով վառւում էր, բայց չէր այրւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Մովսէսն ինքն իրեն ասաց. «Գնամ տեսնեմ այս մեծ տեսարանը: Ինչպէ՞ս է, որ մորենին չի այրւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Երբ Տէրը նկատեց, որ Մովսէսը տեսնելու համար մօտ է գնում, մորենու միջից ձայն տուեց նրան ու ասաց. «Մովսէ՛ս, Մովսէ՛ս»: Սա ասաց. «Ի՞նչ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Աստուած ասաց. «Մի՛ մօտեցիր այստեղ: Կօշիկներդ հանի՛ր քո ոտքերից, որովհետեւ այն վայրը, ուր կանգնած ես դու, սուրբ հող է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Եւ աւելացրեց. «Ես քո հօր Աստուածն եմ, Աբրահամի Աստուածը, Իսահակի Աստուածը ու Յակոբի Աստուածը»: Եւ Մովսէսը շուռ տուեց իր երեսը, որովհետեւ վախենում էր նայել Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Տէրն ասաց Մովսէսին. «Ես ականատես եղայ Եգիպտոսում գտնուող իմ ժողովրդի կրած տառապանքներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'լսեցի վերակացուների պատճառով նրանց բարձրացրած աղաղակը, տեղեակ եմ նրանց վշտերին: Ես իջայ, որ նրանց փրկեմ եգիպտացիների ձեռքից, նրանց հանեմ այդ երկրից, նրանց տանեմ մի լաւ ու ընդարձակ երկիր՝ Քանանացիների, Քետացիների, Ամորհացիների, Փերեզացիների, Խեւացիների, Գերգեսացիների ու Յ»բուսացին»րի »րկիրը« ուր կաթ ու մ»ղր է հոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Արդ, ահաւասիկ իսրայէլացիների աղաղակը հասել է ինձ. ես տեսայ այն տառապանքները, որ նրանք կրում են եգիպտացիների ձեռքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Արդ, արի՛ քեզ ուղարկեմ եգիպտացիների արքայ փարաւոնի մօտ, որ իմ ժողովրդին՝ իսրայէլացիներին հանես Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Մովսէսն ասաց Աստծուն. «Ես ո՞վ եմ, որ գնամ եգիպտացիների արքայ փարաւոնի մօտ եւ իսրայէլացիներին հանեմ Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Աստուած ասաց. «Ես քեզ հետ կը լինեմ, եւ երբ այս լերան վրայ Աստծուն պաշտէք, այդ քեզ համար նշան կը լինի, որ ե՛ս եմ ուղարկել քեզ, որպէսզի իմ ժողովրդին հանես Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Մովսէսն ասաց Աստծուն. «Ես կը գնամ իսրայէլացիների մօտ ու նրանց կ՚ասեմ. «Ձեր հայրերի Աստուածն է առաքել ինձ ձեզ մօտ»: Եւ եթէ նրանք հարցնեն ինձ, թէ ի՞նչ է նրա անունը, ես ի՞նչ պատասխան տամ նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Աստուած ասաց Մովսէսին. «Ես այն Աստուածն եմ, որ Է»: Եւ աւելացրեց. «Այսպէս կ՚ասես իսրայէլացիներին. «Որ Է-ն առաքեց ինձ ձեզ մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Աստուած դարձեալ ասաց Մովսէսին. «Այսպէս կ՚ասես իսրայէլացիներին. «Ձեր հայրերի Տէր Աստուածը՝ Աբրահամի Աստուածը, Իսահակի Աստուածը եւ Յակոբի Աստուածն է առաքել ինձ ձեզ մօտ»: Այս է իմ յաւիտենական անունը, որ յիշատակ է ազգից ազգ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Արդ, գնա հաւաքի՛ր իսրայէլացի ծերերին ու նրանց ասա՛. «Ձեր հայրերի Տէր Աստուածը՝ Աբրահամի Աստուածը, Իսահակի Աստուածը եւ Յակոբի Աստուածը երեւաց ինձ ու ասաց. «Ես այցելեցի ձեզ ու գիտեմ, թէ ինչ բաներ պատահեցին ձեզ հետ Եգիպտոսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Ես ասում եմ. «Ձեզ հանելու եմ Եգիպտացիների՝ չարչարանքների երկրից եւ տանելու եմ Քանանացիների, Քետացիների, Ամորհացիների, Փերեզացիների, Գերգեսացիների, Խեւացիների ու Յեբուսացիների երկիրը, ուր կաթ ու մեղր է հոսում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Նրանք կը լսեն քեզ: Դու իսրայէլացի ծերերի հետ կը մտնես եգիպտացիների արքայ փարաւոնի մօտ եւ կ՚ասես նրան. «Եբրայեցիների Տէր Աստուածը մեզ կանչում է իր մօտ: Հիմա պիտի գնանք երեք օրուայ ճանապարհ դէպի անապատ, որպէսզի մեր Աստծուն զոհ մատուցենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ես գիտեմ, որ եգիպտացիների արքան թոյլ չի տայ, որ դուք գնաք, բայց հզօր մի ձեռք կը ստիպի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Ես ձեռքս մեկնելով պիտի հարուածեմ Եգիպտոսին իմ բոլոր զարմանահրաշ գործերով, որ պիտի գործեմ նրանց մէջ, եւ դրանից յետոյ միայն նա պիտի ազատ արձակի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Ես եգիպտացիների ներկայութեամբ շնորհներ եմ տալու իմ ժողովրդին, որ երբ դուրս գաք, ձեռնունայն դուրս չգաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ամէն մի կին իր հարեւանից կամ իր հարեւանութեամբ բնակուողից թող ուզի ոսկէ ու արծաթէ անօթներ եւ զգեստներ: Դուք կը զարդարէք ձեր տղաներին ու ձեր աղջիկներին եւ այդպիսով կողոպտած կը լինէք եգիպտացիներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Պատասխան տուեց Մովսէսն ու ասաց. «Եթէ ինձ չհաւատան, իմ ասածը չլսեն, (քանի որ նրանք կարող են ասել, թէ՝ Աստուած քեզ չի երեւացել), ես ի՞նչ ասեմ նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Տէրն ասաց նրան. «Այդ ի՞նչ է քո ձեռքին»: Սա ասաց. «Գաւազան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Նա ասաց. «Գետի՛ն գցիր դա»: Մովսէսը գետին գցեց գաւազանը, այն օձ դարձաւ, եւ Մովսէսը փախաւ դրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Տէրն ասաց Մովսէսին. «Երկարի՛ր ձեռքդ եւ բռնի՛ր դրա պոչից»: Նա երկարեց ձեռքն ու բռնեց պոչից, եւ օձը գաւազան դարձաւ իր ձեռքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '«Այդպէս կ՚անես, որպէսզի քեզ հաւատան, որ քեզ երեւացել է նրանց հայրերի Աստուածը՝ Աբրահամի Աստուածը, Իսահակի Աստուածը եւ Յակոբի Աստուածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Տէրը նորից ասաց նրան. «Ձեռքդ ծոցդ դի՛ր»: Նա ձեռքը դրեց իր ծոցը, ապա հանեց այն իր ծոցից, եւ ձեռքը ձեան նման սպիտակեց, ինչպէս բորոտների մօտ է լինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Աստուած ասաց. «Ձեռքդ ծոցդ դի՛ր»: Նա ձեռքը դրեց իր ծոցը, յետոյ հանեց այն իր ծոցից, եւ ձեռքը վերստացաւ իր մարմնի նախկին գոյնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Աստուած ասաց. «Եթէ չհաւատան քեզ եւ չունկնդրեն առաջին նշանի ձայնին, ապա կը հաւատան քո երկրորդ նշանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Եթէ պատահի, որ չհաւատան երկու նշաններին էլ, չանսան քո ասածին, ապա գետից ջուր կը վերցնես, կը թափես գետին, եւ գետից քո առած ջուրը գետնի վրայ արիւն կը դառնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Մովսէսն ասաց Տիրոջը. «Աղաչում եմ քեզ, Տէ՛ր, մինչեւ օրս ես պերճախօս չեմ եղել, ոչ իսկ երբ սկսեցիր խօսել քո ծառայի հետ, որովհետեւ անվարժ եմ խօսում, ծանրախօս եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Տէրն ասաց Մովսէսին. «Ո՞վ է մարդուն բերան տուել, կամ ո՞վ է ստեղծել խուլին ու համրին, տեսնողին ու կոյրին: Մի՞թէ ոչ ես՝ Աստուածս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Արդ, գնա՛, ես կը բացեմ քո բերանը, քեզ կը սովորեցնեմ, որ ասես այն, ինչ պէտք է ասել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Մովսէսն ասաց. «Աղաչում եմ քեզ, Տէ՛ր, մի այլ կարող մարդու ընտրիր, նրան ուղարկիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Տէրը խիստ բարկացաւ Մովսէսի վրայ ու ասաց. «Մի՞թէ ղեւտացի Ահարոնը քո եղբայրը չէ: Գիտեմ, որ նա քո փոխարէն փայլուն կը խօսի: Նա քեզ ընդառաջ կ՚ելնի եւ քեզ տեսնելով՝ ամբողջ հոգով կ՚ուրախանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Կը խօսես նրա հետ եւ իմ պատգամները կը դնես նրա շրթներին: Ես կը բացեմ քո բերանն ու նրա բերանը, ձեզ կը սովորեցնեմ այն, ինչ պէտք է անէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ժողովրդի հետ քո փոխարէն նա կը խօսի, նա կը լինի քո խօսափողը, իսկ դու նրա համար կը լինես ներշնչող Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Այն գաւազանը, որ օձ դարձաւ, կ՚առնես ձեռքդ եւ դրանով նշաններ կը գործես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Մովսէսը գնաց իր աներոջ՝ Յոթորի մօտ ու ասաց նրան. «Վերադառնամ Եգիպտոսում գտնուող իմ եղբայրների մօտ եւ տեսնեմ, թէ տակաւին կենդանի՞ են»: Յոթորն ասաց Մովսէսին. «Բարի ճանապարհ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Այս դէպքերից բազում օրեր անց, երբ վախճանուել էր եգիպտացիների արքան, Տէրը Մադիամում ասաց Մովսէսին. «Գնա՛, վերադարձի՛ր Եգիպտոս, որովհետեւ արդէն մեռել են բոլոր նրանք, ովքեր ուզում էին խլել քո կեանքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Մովսէսը, առնելով իր կնոջն ու երեխաներին, նրանց նստեցրեց գրաստների վրայ ու վերադարձաւ Եգիպտոս: Մովսէսն իր ձեռքն առաւ գաւազանը, որ Աստուած էր տուել իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Տէրն ասաց Մովսէսին. «Եգիպտոս գնալիս ու վերադառնալիս փարաւոնի առաջ ջանա՛, որ անես բոլոր այն նշանները, որոնք անելու շնորհը տուել եմ քո ձեռքը: Ես խստասիրտ կը դարձնեմ փարաւոնին, եւ նա ազատ չի արձակի ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Դու կ՚ասես փարաւոնին. «Այսպէս է ասում Տէրը. իմ անդրանիկ որդին Իսրայէլն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Քեզ ասացի՝ ազա՛տ արձակիր իմ ժողովրդին, որ պաշտի ինձ: Իսկ եթէ չուզենաս ազատ արձակել նրան, այդ դէպքում ես կը սպանեմ քո անդրանիկ որդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Ճանապարհին, իջեւանում, Մովսէսին հանդիպեց Տիրոջ հրեշտակը, որն ուզում էր սպանել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Սեպփորան, վերցնելով մի սուր քար, թլփատեց իր անթլփատ որդուն եւ հրեշտակի ոտքերն ընկնելով՝ ասաց. «Ահա կատարուեց իմ մանկան թլփատութեան կարգը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Հրեշտակը հեռացաւ նրանից, քանի որ նա ասել էր, թէ՝ «Կատարուեց իմ մանկան թլփատութեան կարգը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Տէրն ասաց Ահարոնին. «Գնա՛ անապատ՝ Մովսէսին ընդառաջ»: Նա գնաց, նրան հանդիպեց Աստծու լերան վրայ ու համբուրեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Մովսէսն Ահարոնին յայտնեց իրեն ուղարկող Տիրոջ բոլոր պատգամներն ու բոլոր այն նշանները, որ պատուիրել էր իրեն կատարել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Մովսէսն ու Ահարոնը գնացին եւ հաւաքեցին իսրայէլացիների ամբողջ ծերակոյտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Ահարոնը նրանց հաղորդեց բոլոր այն պատգամները, որ Տէրը յայտնել էր Մովսէսին, եւ Մովսէսը նշաններ գործեց ժողովրդի առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Ժողովուրդը հաւատաց եւ ուրախացաւ, որ Աստուած այցելել է իսրայէլացիներին, ականատես եղել իրենց տառապանքներին: Ժողովուրդը խոնարհուեց ու երկրպագեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Այնուհետեւ Մովսէսն ու Ահարոնը եկան փարաւոնի մօտ ու ասացին նրան. «Այսպէս է ասում Իսրայէլի Տէր Աստուածը. «Արձակի՛ր իմ ժողովրդին, որ իմ պատուին տօն կատարի անապատում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Փարաւոնն ասաց. «Ո՞վ է նա, որի ձայնին անսալով՝ պիտի ազատ արձակեմ իսրայէլացիներին: Այդ Տիրոջը ես չեմ ճանաչում եւ իսրայէլացիներին էլ չեմ արձակում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Նրան ասացին. «Եբրայեցիների Աստուածն է կանչել մեզ իր մօտ: Արդ, երեք օրուայ ճանապարհ պիտի գնանք անապատով, որպէսզի զոհ մատուցենք մեր տէր Աստծուն, այլապէս մեզ մահ կամ սպանութիւն է սպասում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Եգիպտացիների արքան նրանց ասաց. «Մովսէս եւ Ահարոն, դուք ինչո՞ւ էք մարդկանց կտրում իրենց գործից: Ամէն մէկը թող գնայ իր գործին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Եւ փարաւոնը շարունակեց. «Ահա երկրիս մէջ խիստ բազմանում է ժողովուրդը, նրանց գործից չկտրենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Փարաւոնն այդ օրը ժողովրդի գործավարներին ու նրանց վերակացուներին հրամայեց՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '«Այդ մարդկանց այլեւս յարդ չտաք աղիւս շինելու համար, ինչպէս տալիս էիք մինչեւ օրս: Իրենք թող գնան ու իրենց համար յարդ հայթայթեն: Եւ ստիպեցէ՛ք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'որ, որքան առաջ էին նրանք աղիւս շինում, նոյնքան էլ շինեն այսուհետեւ. բան չպակասեցնէ՛ք: Անգործ մնալու պատճառով է, որ նրանք աղաղակում են ու ասում. «Գնանք, զոհ մատուցենք մեր Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Թող մարդկանց գործն է՛լ աւելի ծանրանայ, որպէսզի դրանով զբաղուեն եւ ոչ թէ դատարկ բաների մասին մտածեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Ժողովրդի գործավարները եւ նրանց վերակացուները խիստ ծանր աշխատանքի լծեցին նրանց եւ, դիմելով ժողովրդին, ասացին. «Այսպէս է ասում փարաւոնը. «Ձեզ այլեւս յարդ չեմ տայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Դուք ինքներդ գնացէ՛ք, ձեզ համար յարդ հաւաքեցէ՛ք, ուր որ գտնէք, բայց սահմանուած չափից ոչինչ չպիտի պակասի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Ժողովուրդը սփռուեց ամբողջ Եգիպտոսով մէկ, որպէսզի եղէգ հաւաքի յարդ պատրաստելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Գործավարներն ստիպում էին նրանց անընդհատ աշխատել՝ ասելով. «Ձեր ամենօրեայ գործն արէք այն չափով, ինչպէս որ երբ յարդ էին տալիս ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Եւ իսրայէլացի գործավարները տանջանքի էին ենթարկւում փարաւոնի՝ իրենց վրայ նշանակած վերակացուներից, որոնք ասում էին. «Ինչո՞ւ այսօր էլ աղիւս չէք շինում այնքան, որքան մինչեւ օրս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Իսրայէլացի գործավարները գնացին բողոքեցին փարաւոնին՝ ասելով. «Ինչո՞ւ ես այդպէս վարւում քո ծառաների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Քո ծառաներին յարդ չեն տալիս, բայց հրամայում են, որ աղիւս շինենք: Քո ծառաներն, ահա, տանջանքի մէջ են: Դու կեղեքում ես քո ժողովրդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Փարաւոնը նրանց ասաց. «Դուք ծոյլ ու անբան մարդիկ էք, դրա համար էլ ասում էք. «Գնանք զոհ մատուցենք մեր Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Արդ, գնացէք աշխատեցէ՛ք, որովհետեւ ոչ ոք ձեզ յարդ չի տալու, բայց դուք աղիւսի սահմանուած քանակը պէտք է տաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Իսրայէլացիների գործավարները, տեսնելով իրենց այս ծանր կացութիւնը, իրար մէջ ասացին. «Ոչ ոք չի նուազեցնի աղիւս շինելու մեր ամենօրեայ քանակը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Նրանք հանդիպեցին Մովսէսին ու Ահարոնին, որոնք փարաւոնի պալատից ելնելով՝ գալիս էին իրենց մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Նրանք ասացին նրանց. «Թող Աստուած աչքի առաջ ունենայ ձեզ եւ դատի, քանի որ մեր հօտը գարշելի դարձրիք փարաւոնի ու նրա պաշտօնեաների աչքին: Դուք սուր տուեցիք նրա ձեռքը, որ նա մեզ սպանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Դիմելով Տիրոջը՝ Մովսէսն ասաց. «Տէ՛ր, ինչո՞ւ չարչարեցիր քո ժողովրդին եւ ինչո՞ւ ուղարկեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Այն պահից, երբ մտայ փարաւոնի պալատը քո անունից նրա հետ խօսելու համար, նա չարչարեց ժողովրդին, իսկ դու երբեք չես փրկում քո ժողովրդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Տէրն ասաց Մովսէսին. «Հիմա կը տեսնես, թէ ինչ եմ անելու փարաւոնին: Նա հզօր ձեռքի միջոցով պիտի արձակի նրանց, եւ բարձրացուած բազուկով նրանց պիտի հանի նաեւ իր երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Աստուած խօսեց Մովսէսի հետ եւ ասաց նրան. «Ե՛ս եմ Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ես երեւացի Աբրահամին, Իսահակին ու Յակոբին: Նրանց Աստուածը ես եմ, իմ անունը Տէր է, բայց ես դա նրանց չյայտնեցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ես նրանց հետ ուխտ եմ կնքել, որ նրանց տամ Քանանացիների երկիրը, ուր նրանք պանդխտեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ես լսեցի հեծեծանքը իսրայէլացիների, որոնց եգիպտացիները ստրկացրել են, եւ յիշեցի ձեզ տուած իմ ուխտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Գնա՛ իսրայէլացիների մօտ ու ասա՛ նրանց. «Ե՛ս եմ Տէրը: Ես ձեզ ազատելու եմ եգիպտացիների բռնութիւնից, ձեզ փրկելու եմ նրանց ծառայելուց, ձեզ ազատելու եմ իմ հզօր բազկով ու նրանց գլխին մեծամեծ պատիժներ հասցնելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Ձեզ պիտի դարձնեմ իմ ժողովուրդը եւ պիտի լինեմ ձեր Աստուածը: Դուք պիտի գիտենաք, որ ե՛ս եմ ձեր Տէր Աստուածը, որ ձեզ ազատելու եմ եգիպտացիների բռնութիւնից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'եւ ձեզ տանելու եմ այն երկիրը, որ երդուեցի տալ Աբրահամին, Իսահակին ու Յակոբին: Այն ձեզ եմ տալու որպէս ժառանգութիւն, որովհետեւ ե՛ս եմ Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Մովսէսը այս բանը հաղորդեց իսրայէլացիներին, բայց նրանք չլսեցին նրան վհատութեան եւ տաժանակիր աշխատանքի պատճառով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Տէրը, խօսելով Մովսէսի հետ, ասաց. «Մտի՛ր ու խօսի՛ր եգիպտացիների արքայ փարաւոնի հետ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'որ նա իսրայէլացիներին արձակի Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Մովսէսը, Տիրոջը դիմելով, ասաց. «Իսրայէլացիներն իսկ ինձ չլսեցին, փարաւոնն ինձ ինչո՞ւ պիտի լսի: Ես ճարտարախօս չեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Տէրը խօսեց Մովսէսի ու Ահարոնի հետ եւ իսրայէլացիներին ու եգիպտացիների արքայ փարաւոնին ուղղուած հրաման տուեց՝ հանելու իսրայէլացիներին Եգիպտացիների երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ահա Մովսէսի ու Ահարոնի ընտանիքների առաջնորդների անունները. Իսրայէլի անդրանիկ որդի Ռուբէնի որդիներն են՝ Ենոքն ու Փալլուսը, Ասրոնն ու Քարմին: Սա Ռուբէնի ազգատոհմն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Շմաւոնի որդիներն են՝ Յամուէլը, Յամինը, Ահոդը, Յաքինը, Սահառն ու Սաւուղը, որը փիւնիկեցի կնոջից էր ծնուել: Սրանք Շմաւոնի որդիների տոհմերն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ղեւիի որդիների անունները, ըստ իրենց ընտանիքների, հետեւեալն են. Գեթսոն, Կահաթ եւ Մերարի: Ղեւին ապրեց հարիւր երեսունեօթը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Գեթսոնի որդիներն են՝ Լոբենին եւ Սեմէին՝ իրենց նահապետների ընտանիքներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Կահաթի որդիներն են՝ Ամրամը, Սահառը, Քեբրոնն ու Ոզիէլը: Կահաթն ապրեց հարիւր երեսուներեք տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Մերարիի որդիներն են՝ Մոոլին ու Մուսին: Սրանք Ղեւիի ընտանիքներն են ըստ իրենց ցեղերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Ամրամն ամուսնացաւ իր հօրեղբօր դուստր Յոքաբեէթի հետ, եւ սա նրանից ունեցաւ Ահարոնին, Մովսէսին ու նրանց քոյր Մարիամին: Ամրամն ապրեց հարիւր երեսունեօթը տարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Սահառի որդիներն են՝ Կորխը, Նափեգն ու Զեքրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Ոզիէլի որդիներն են՝ Միսայէլը, Ելիսափանն ու Սեթրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Ահարոնն ամուսնացաւ Ամինադաբի դուստր, Նաասոնի քոյր Եղիսաբէթի հետ: Սա նրանից ունեցաւ Նաբադին, Աբիուդին, Եղիազարին ու Իթամարին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Կորխի որդիներն են՝ Ասիրը, Եղկանան ու Բիասափը: Սրանք Կորխի յետնորդներն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Ահարոնի որդի Եղիազարը ամուսնացաւ Փուտիէլի դուստրերից մէկի հետ, եւ սա նրանից ունեցաւ Փենեէսին: Սրանք են ղեւտացիների ընտանիքների առաջնորդները ըստ իրենց ցեղերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Այս Ահարոնին ու Մովսէսին էր, որ Աստուած ասաց՝ իսրայէլացիներին հանել իրենց զօրքով հանդերձ Եգիպտացիների երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Եւ սրանք էին, որ դիմեցին եգիպտացիների արքայ փարաւոնին՝ դուրս հանելու Եգիպտոսից իսրայէլացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Սրանք այն Մովսէսն ու Ահարոնն են, որոնց օրօք Տէրը Եգիպտացիների երկրում խօսելով Մովսէսի հետ՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'ասաց նրան. «Ե՛ս եմ Տէրը: Եգիպտացիների արքայ փարաւոնին հաղորդի՛ր այն ամէնը, ինչ ասում եմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Եւ Մովսէսը, դիմելով Տիրոջը, ասաց. «Չէ՞ որ ես անվարժ եմ խօսում, փարաւոնն ինձ ինչպէ՞ս կը լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Տէրն ասաց Մովսէսին. «Ահա ես քեզ փարաւոնի համար մի աստուած դարձրի, իսկ քո եղբայր Ահարոնը թող լինի քո մարգարէն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Դու Ահարոնին կը յայտնես այն ամէնը, ինչ կը պատուիրեմ քեզ, իսկ քո եղբայր Ահարոնը թող դիմի փարաւոնին, որ սա իսրայէլացիներին արձակի իր երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ես կը կարծրացնեմ փարաւոնի սիրտը, բայց եւ կը բազմապատկեմ իմ նշաններն ու զարմանահրաշ գործերը Եգիպտացիների երկրում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'փարաւոնը ձեզ չի լսի, ես իմ ձեռքը կը դնեմ Եգիպտոսի վրայ եւ իմ զօրութեամբ մեծապէս վրէժխնդիր լինելով՝ Եգիպտացիների երկրից կը հանեմ իմ ժողովրդին՝ իսրայէլացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Եւ եգիպտացիները կ՚իմանան, որ ե՛ս եմ Տէրը: Ես իմ ձեռքը կը մեկնեմ դէպի Եգիպտոս եւ իսրայէլացիներին դուրս կը հանեմ նրանց միջից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Մովսէսն ու Ահարոնը արեցին այնպէս, ինչպէս Տէրն էր պատուիրել իրենց. նրանք այդպէս էլ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Մովսէսն ութսուն տարեկան էր, իսկ Ահարոնը՝ ութսուներեք տարեկան, երբ նրանք խօսեցին փարաւոնի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Տէրը, դիմելով Մովսէսին ու Ահարոնին, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '«Եթէ փարաւոնը խօսի ձեզ հետ ու ասի՝ «Մեզ նշան կամ զարմանահրաշ գործ ցոյց տուէ՛ք», այն ժամանակ քո եղբայր Ահարոնին կ՚ասես. «Ա՛ռ քո գաւազանը, այն գետին գցի՛ր փարաւոնի ու նրա պաշտօնեաների առաջ, եւ դա վիշապ կը դառնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Մովսէսն ու Ահարոնը մտան փարաւոնի մօտ եւ արեցին այնպէս, ինչպէս իրենց պատուիրել էր Տէրը: Ահարոնը գաւազանը գցեց փարաւոնի ու նրա պաշտօնեաների առաջ, եւ դա վիշապ դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Փարաւոնը կանչեց եգիպտացի իմաստուններին ու կախարդներին: Եգիպտացի մոգերը նոյնն արեցին իրենց կախարդութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Իւրաքանչիւրն իր գաւազանը գցեց գետին, եւ դրանք վիշապներ դարձան, բայց Ահարոնի գաւազանը կուլ տուեց նրանց գաւազանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Կարծրացաւ փարաւոնի սիրտը, եւ նա չլսեց նրանց, ինչպէս որ ասել էր Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Տէրն ասաց Մովսէսին. «Փարաւոնի սիրտը կարծրացել է. նա որոշել է չարձակել ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Առաւօտեան գնա՛ փարաւոնի մօտ: Երբ նա դէպի գետը կը գնայ, կանգնի՛ր գետի եզերքին, նրա դիմաց, եւ քո ձեռքն ա՛ռ այն գաւազանը, որ օձ դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Դու նրան կ՚ասես. «Եբրայեցիների Տէր Աստուածն է ուղարկել ինձ քեզ մօտ՝ ասելով. «Արձակի՛ր իմ ժողովրդին, որ նա պաշտի ինձ անապատում: Մինչեւ հիմա ինձ չլսեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Տէրն այսպէս է ասում. «Սրանով կ՚իմանաս, որ ե՛ս եմ Տէրը. ահա ես իմ ձեռքի գաւազանով կը հարուածեմ գետի ջրին, եւ այն կը վերածուի արեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Գետի մէջ եղած ձկները կը սատկեն, գետը կը նեխի, եւ եգիպտացիները չեն կարողանայ գետից ջուր խմել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Տէրն ասաց Մովսէսին. «Ահարոնին ասա՛, որ առնի գաւազանը եւ ձեռքը մեկնի Եգիպտոսի ջրերի վրայ՝ նրանց գետերի վրայ, նրանց լճերի վրայ, նրանց ջրաւազանների վրայ, նրանց ջրակոյտերի վրայ, եւ ջուրը կը վերածուի արեան: Արեան պիտի վերածուի ողջ Եգիպտացիների երկրում գտնուող անգամ փայտէ ու քարէ ամանն»րի մէջ »ղած ջուրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Մովսէսն ու Ահարոնը արեցին այնպէս, ինչպէս որ իրենց պատուիրել էր Տէրը. փարաւոնի ու նրա պաշտօնեաների առաջ Ահարոնը վեր բարձրացնելով իր գաւազանը՝ հարուածեց գետի ջրին եւ գետի բոլոր ջրերը վերածեց արեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Գետում եղած ձկները սատկեցին, գետը նեխեց, եւ եգիպտացիները չէին կարողանում գետից ջուր խմել: Եգիպտացիների ամբողջ երկրում արիւն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Իրենց կախարդութեամբ նոյնն արեցին նաեւ եգիպտացի մոգերը: Կարծրացաւ փարաւոնի սիրտը, եւ, ինչպէս որ ասել էր Տէրը, նա չլսեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Փարաւոնը վերադարձաւ, մտաւ իր պալատը: Այս դէպքը չէր ազդել նրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Բոլոր եգիպտացիները հորեր փորեցին գետի շուրջը, որպէսզի խմելու ջուր ունենան, որովհետեւ գետից չէին կարողանում ջուր խմել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Եօթը օր էր անցել, որ Տէրը հարուած էր հասցրել գետին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Տէրն ասաց Մովսէսին. «Մտի՛ր փարաւոնի մօտ ու ասա՛ նրան. «Այսպէս է ասում Տէրը. արձակի՛ր իմ ժողովրդին, որ նա պաշտի ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Եթէ չուզենաս արձակել, ես, ահա, գորտերով կ՚ապականեմ քո բովանդակ երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Գետի մէջ գորտեր կը վխտան, եւ դրանք, գետից դուրս գալով, կը մտնեն քո պալատները, քո սենեակների պահարանները, քո անկողինները, քո պաշտօնեաների ու քո ժողովրդի տները, քո թոնիրներն ու քո խմորի զանգուածների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Գորտերը կը բարձրանան նաեւ քեզ վրայ, քո ժողովրդի ու քո պաշտօնեաների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Տէրն ասաց Մովսէսին. «Քո եղբայր Ահարոնին ասա՛. «Ձեռքիդ գաւազանը մեկնի՛ր գետի վրայ, ջրանցքների, ճահիճների վրայ եւ գորտեր դուրս բե՛ր Եգիպտացիների երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Ահարոնն իր ձեռքը մեկնեց եգիպտացիների ջրերի վրայ ու գորտեր դուրս բերեց: Գորտերն ելան ու ծածկեցին Եգիպտացիների երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Իրենց կախարդութիւններով նոյնն արեցին նաեւ եգիպտացի մոգերը եւ գորտեր դուրս բերեցին Եգիպտացիների երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Կանչելով Մովսէսին ու Ահարոնին՝ փարաւոնն ասաց. «Աղօթեցէ՛ք Տիրոջը, որ նա գորտերը հեռացնի ինձնից ու իմ ժողովրդից, որ ես արձակեմ ձեր ժողովրդին, նրանք գնան զոհ մատուցեն Տիրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Մովսէսն ասաց փարաւոնին. «Ժամանակ սահմանի՛ր, թէ ե՛րբ աղօթեմ քեզ համար, քո պաշտօնեաների ու քո ժողովրդի համար, որպէսզի գորտերը չքանան քո, քո ժողովրդի մօտից ու ձեր տներից եւ մնան միայն գետում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Նա ասաց. «Վաղը»: Սա ասաց. «Թող ասածիդ պէս լինի, եւ դու կ՚իմանաս, որ մեր տէր Աստծուց բացի մի ուրիշ աստուած չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Գորտերը կը չքանան քո պալատներից, քո, քո ծառաների, քո ժողովրդի մօտից եւ կը մնան միայն գետի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Մովսէսն ու Ահարոնը դուրս ելան փարաւոնի մօտից: Մովսէսն աղօթեց Տիրոջը, որպէսզի գորտերը հեռանան, ինչպէս որ խոստացել էր փարաւոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Տէրն արեց այնպէս, ինչպէս որ խնդրել էր Մովսէսը: Գորտերը չքացան տներից, բակերից ու դաշտերից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Դրանք հաւաքեցին կոյտ-կոյտ, եւ երկիրը լցուեց գարշահոտութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Երբ փարաւոնը տեսաւ, որ դժուարութիւնը վերացել է, նորից կարծրացաւ նրա սիրտը, նա չլսեց նրանց, ինչպէս որ ասել էր Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Տէրն ասաց Մովսէսին. «Ահարոնին ասա՛, որ ձեռքի գաւազանը մեկնի ու հարուածի գետնին, որպէսզի մժեղ լինի մարդկանց, անասունների եւ Եգիպտացիների ամբողջ երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Այդպէս էլ արեցին. Ահարոնն իր գաւազանը մեկնեց ու հարուածեց գետնին: Մժեղ եղաւ մարդկանց, անասունների ու Եգիպտացիների ամբողջ երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Իրենց կախարդութիւններով նոյնը ուզեցին անել նաեւ մոգերը, որպէսզի մժեղ հանեն, բայց չկարողացան: Մժեղ լցուեց մարդկանց ու անասունների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Մոգերն ասացին փարաւոնին. «Սրա մէջ Աստծու մատը խառն է»: Կարծրացաւ փարաւոնի սիրտը, եւ նա, ինչպէս որ ասել էր Տէրը, չլսեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Տէրն ասաց Մովսէսին. «Առաւօտեան վե՛ր կաց, գնա կանգնի՛ր փարաւոնի առաջ, երբ նա դէպի գետը կը գնայ: Նրան կ՚ասես. «Այսպէս է ասում Տէրը. արձակի՛ր իմ ժողովրդին, որ նա պաշտի ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Իսկ եթէ չուզենաս արձակել իմ ժողովրդին, ես, ահա, շնաճանճեր կ՚ուղարկեմ քեզ վրայ, քո պաշտօնեաների ու քո ժողովրդի վրայ եւ ձեր տների վրայ: Եգիպտացիների տներն ու նրանց բնակեցրած երկիրը կը լցուեն շնաճանճերով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Նոյն օրը ես զարմանահրաշ գործեր կ՚անեմ իմ ժողովրդի բնակած Գեսեմ երկրում, եւ այնտեղ շնաճանճեր չեն լինի, որպէսզի իմանաս, որ ե՛ս եմ Տէրը՝ ամբողջ երկրի Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ես պիտի բաժանեմ իմ ժողովրդին քո ժողովրդից: Վաղն իսկ այդ նշանը կը կատարուի քո երկրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Եւ Տէրն այդպէս էլ արեց: Բազում շնաճանճեր թափուեցին փարաւոնի պալատների, նրա պաշտօնեաների տների ու Եգիպտացիների ամբողջ երկրի վրայ: Շնաճանճերից կործանուեց երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Կանչելով Մովսէսին ու Ահարոնին՝ փարաւոնն ասաց. «Գնացէ՛ք, այս երկրում զո՛հ մատուցէք ձեր տէր Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Մովսէսն ասաց. «Ընդունուած չէ, որ եգիպտացիների պիղծ անասունները զոհ մատուցենք մեր տէր Աստծուն, քանի որ, եթէ եգիպտացիների պիղծ անասունները զոհ մատուցենք նրան, մեզ կը քարկոծեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Ուրեմն՝ երեք օրուայ ճանապարհ գնանք դէպի անապատ եւ զոհ մատուցենք մեր տէր Աստծուն, ինչպէս որ մեզ ասել է Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Փարաւոնն ասաց. «Ես արձակում եմ ձեզ, անապատում զո՛հ մատուցէք ձեր տէր Աստծուն: Միայն թէ հեռու չգնաք: Արդ, նաեւ ինձ համար աղօթեցէ՛ք Տիրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Մովսէսն ասաց. «Ես քեզնից կը հեռանամ, կ՚աղօթեմ Աստծուն, եւ վաղն իսկ շնաճանճերը կը չքանան փարաւոնի, նրա պաշտօնեաների ու ժողովրդի վրայից: Միայն թէ փարաւոնը ժողովրդին նորից չխաբի՝ չարգելի նրան գնալ ու Տիրոջ համար զոհ մատուցել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Մովսէսը փարաւոնի մօտից դուրս ելաւ եւ աղօթեց Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Տէրն արեց այնպէս, ինչպէս որ ասել էր Մովսէսը. շնաճանճերը վերացրեց փարաւոնի, նրա պաշտօնեաների ու ժողովրդի վրայից: Մի շնաճանճ անգամ չմնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Բայց դրանից յետոյ էլ փարաւոնի սիրտը կարծրացաւ, եւ նա չուզեց արձակել ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Տէրն ասաց Մովսէսին. «Գնա՛ փարաւոնի մօտ ու նրան ասա՛, որ այսպէս է ասում եբրայեցիների Տէր Աստուածը. «Արձակի՛ր իմ ժողովրդին, որ պաշտեն ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Իսկ եթէ չուզենաս արձակել իմ ժողովրդին եւ դեռ պահես նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Տիրոջ ձեռքը, ահա, կ՚իջնի դաշտում գտնուող քո անասունների հօտերի՝ ձիերի, էշերի, ուղտերի, արջառների ու ոչխարների վրայ, եւ շատ մեծ կոտորած կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Ես զարմանահրաշ գործեր կ՚անեմ՝ եգիպտացիների հօտերը եւ իսրայէլացիների հօտերը կը զատորոշեմ, եւ ոչ մի իսրայէլացու անասուն չի կորչի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Եւ Աստուած ժամկէտ նշանակեց ու ասաց. «Վաղն իսկ Տէրը կ՚իրագործի այդ բանը երկրի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Եւ Տէրը յաջորդ օրն իսկ արեց այդ բանը. եգիպտացիների բոլոր անասունները սատկեցին, իսկ իսրայէլացիների ոչ մի անասուն չոչնչացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Երբ փարաւոնը տեսաւ, որ իսրայէլացիների ոչ մի անասուն չի ոչնչացել, կարծրացաւ նրա սիրտը, եւ նա ժողովրդին չարձակեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Տէրը Մովսէսին ու Ահարոնին ասաց. «Լիքը ձեռքով հնոցի մոխիր վերցրէ՛ք, Մովսէսը փարաւոնի ու նրա պաշտօնեաների առաջ այն թող շաղ տայ դէպի երկինք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Մոխիրը թող թափուի Եգիպտացիների ամբողջ երկրի վրայ: Խոցեր թող առաջանան մարդկանց ու անասունների վրայ եւ ուռուցքներ՝ Եգիպտացիների ամբողջ երկրի մարդկանց ու անասունների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Նրանք վերցրին հնոցի մոխիրը, եւ Մովսէսը փարաւոնի առաջ այն շաղ տուեց դէպի երկինք: Մարդկանց ու անասունների վրայ խոցեր եւ ուռուցքներ առաջացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Մոգերը խոցերի պատճառով չէին կարողանում Մովսէսի առաջ կանգնել, որովհետեւ խոցեր առաջացան նաեւ մոգերի ու Եգիպտացիների ամբողջ երկրի մարդկանց վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Տէրը կարծրացրեց փարաւոնի սիրտը, եւ, ինչպէս որ ասել էր Տէրը Մովսէսին, փարաւոնը չլսեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Տէրն ասաց Մովսէսին. «Առաւօտեան վե՛ր կաց, կանգնի՛ր փարաւոնի առաջ ու նրան ասա՛, որ այսպէս է ասում եբրայեցիների Տէր Աստուածը. «Արձակի՛ր իմ ժողովրդին, որ պաշտի ինձ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'այլապէս այս անգամ ամէն տեսակ փորձանքներով պիտի պատուհասեմ նաեւ քեզ, քո պաշտօնեաներին ու քո ժողովրդին, որպէսզի իմանաս, որ ամբողջ աշխարհում ինձ նման ուրիշ մէկը չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Որովհետեւ իմ ձեռքը մեկնելով՝ մահացու հարուած պիտի հասցնեմ քեզ ու քո ժողովրդին, եւ դու պիտի վերանաս երկրի երեսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Ես քեզ խնայեցի այն նպատակով, որ քեզ ցոյց տամ իմ զօրութիւնը, եւ իմ անունը յայտնի լինի ողջ երկրում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'բայց դու դեռեւս ձեռքիդ տակ ես պահում իմ ժողովրդին եւ չարչարում նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Ես, ահա, վաղն իսկ, հէնց այս ժամին այնպիսի սաստիկ կարկուտ տեղացնեմ, որպիսին դեռեւս չի եղել Եգիպտոսում իր գոյութեան օրուանից մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Արդ, շտապի՛ր հաւաքել քո անասունները եւ այն ամէնը, ինչ ունես դաշտում, որովհետեւ դաշտում գտնուող ու դեռեւս տուն չմտած մարդկանց ու անասունների վրայ կարկուտ է թափուելու եւ ոչնչացնելու է նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Փարաւոնի պաշտօնեաներից նա, ով մի անգամ տեսել էր Տիրոջ սարսափը, իր ծառաներին ու անասունները հաւաքեց տան մէջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'իսկ ով չանսաց Տիրոջ խօսքերին, դաշտում թողեց իր ծառաներին ու անասունները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Տէրն ասաց Մովսէսին. «Ձեռքդ մեկնի՛ր դէպի երկինք, եւ թող կարկուտ թափուի Եգիպտացիների երկրի վրայ, ինչպէս նաեւ մարդկանց ու անասունների եւ Եգիպտացիների երկրի դաշտերի բոլոր բոյսերի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Մովսէսը ձեռքը մեկնեց դէպի երկինք, Տէրը որոտ ու կարկուտ ուղարկեց, եւ երկրի վրայ սկսեց կրակ թափուել: Տէրը կարկուտ տեղացրեց Եգիպտացիների ամբողջ երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Կարկուտ էր տեղում, բայց կարկուտի մէջ բորբոքուած կրակ կար: Կարկուտն այնքան խոշոր էր, որ նմանը չէր եղել Եգիպտացիների ամբողջ երկրի վրայ ազգի առաջացումից ի վեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Կարկուտը հարուածեց Եգիպտացիների ամբողջ երկիրը, այն ամէնը, ինչ դաշտում էր մնացել՝ մարդուց սկսած մինչեւ անասուն: Կարկուտը հարուած հասցրեց դաշտում եղած ամբողջ բուսականութեանը, ջարդուփշուր արեց դաշտում եղած բոլոր ծառերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Իսրայէլացիների ապրած Գեսեմ երկրում, սակայն, կարկուտ չտեղաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Փարաւոնը մարդ ուղարկելով՝ կանչեց Մովսէսին ու Ահարոնին եւ ասաց նրանց. «Մեղք եմ գործել: Այսուհետեւ Տէրն արդար է, իսկ ես ու իմ ժողովուրդը ամբարիշտներ ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Ինձ համար աղօթեցէ՛ք Տիրոջը, որ Աստծու որոտը, կարկուտն ու կրակը դադարեն մեզ վրայ թափուելուց: Ես ձեզ կ՚արձակեմ, այլեւս դուք այստեղ չէք մնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Մովսէսն ասաց նրան. «Երբ դուրս կը գամ այս քաղաքից, ձեռքս կը մեկնեմ առ Աստուած, եւ ձայները կը դադարեն, կարկուտ ու անձրեւ այլեւս չեն տեղայ, որպէսզի դու համոզուես, որ երկիրը Տիրոջն է պատկանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Բայց գիտեմ, որ դու եւ քո պաշտօնեաները դեռեւս չէք վախենում տէր Աստծուց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Կտաւատն ու գարին կարկտահարուեցին, որովհետեւ գարին հասած էր, կտաւատը՝ սերմնակալած,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'իսկ ցորենն ու հաճարը կարկտահար չեղան, որովհետեւ դեռ չէին հասունացած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Մովսէսը փարաւոնի մօտից ելաւ ու գնաց քաղաքից դուրս, ձեռքը մեկնեց Տիրոջը, եւ ձայներն ու կարկուտը դադարեցին, անձրեւ այլեւս չտեղաց երկրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Երբ փարաւոնը տեսաւ, որ անձրեւը, կարկուտն ու ձայները դադարել են, դարձեալ մեղք գործեց. նա կարծրացրեց իր ու իր պաշտօնեաների սիրտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Կարծրացաւ փարաւոնի սիրտը, եւ նա իսրայէլացիներին չարձակեց, ինչպէս որ յայտնել էր Տէրը Մովսէսի միջոցով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Դիմելով Մովսէսին՝ Տէրն ասաց. «Մտի՛ր փարաւոնի մօտ, որովհետեւ ես կարծրացրել եմ նրա ու նրա պաշտօնեաների սիրտը, որպէսզի իմ նշանները հերթով թափուեն նրանց գլխին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'որպէսզի դուք պատմէք ձեր որդիներին ու ձեր որդիների որդիներին, թէ որքան եմ ես ծաղրուծանակի ենթարկել եգիպտացիներին, ինչպէս նաեւ պատմէք իմ այն նշանների մասին, որ կատարեցի նրանց մօտ, որպէսզի ճանաչէք, թէ ե՛ս եմ Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Մովսէսն ու Ահարոնը մտան փարաւոնի մօտ եւ ասացին նրան. «Այսպէս է ասում եբրայեցիների Տէր Աստուածը. «Մինչեւ ե՞րբ չես պատկառելու ինձնից: Արձակի՛ր իմ ժողովրդին, որպէսզի պաշտի ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Եթէ չկամենաս արձակել իմ ժողովրդին, ես, ահա, վաղն իսկ, հէնց այս ժամին շատ մորեխ կը թափեմ քո սահմաններից ներս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Դրանք կը ծածկեն ողջ երկրի երեսը, եւ դու չես կարողանայ տեսնել երկիրը: Դրանք կը խժռեն բոլոր մնացած այն բաները, որ ձեզ թողել է կարկուտը, կը խժռեն բոլոր տունկերը, որ բուսել են երկրի վրայ ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Քո պալատները, քո պաշտօնեաների եւ Եգիպտացիների ամբողջ երկրի բոլոր տները այնպէս կը լցուեն մորեխներով, որ ո՛չ ձեր հայրերը, ո՛չ էլ նրանց նախահայրերը երբեք չեն տեսել երկրի վրայ իրենց ծնուած օրից մինչեւ այսօր»: Եւ Մովսէսը դուրս եկաւ փարաւոնի մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Փարաւոնի պաշտօնեաներն իրեն ասացին. «Այս խոչընդոտը մինչեւ ե՞րբ պիտի լինի մեր առաջ: Արձակի՛ր մարդկանց, որպէսզի պաշտեն իրենց տէր Աստծուն: Գուցէ ուզում ես տեսնել, թէ ինչպէ՞ս է կործանւում Եգիպտոսը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Եւ նրանք Մովսէսին ու Ահարոնին վերադարձրին փարաւոնի մօտ: Փարաւոնը նրանց ասաց. «Գնացէք պաշտեցէ՛ք ձեր տէր Աստծուն: Գնացողները, սակայն, ովքե՞ր են լինելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Մովսէսն ասաց. «Կը գնանք մենք մեր երիտասարդներով ու ծերերով, մեր տղաներով ու աղջիկներով, կը գնանք մեր արջառների ու ոչխարների հետ, որովհետեւ մեր տէր Աստծու տօնն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Փարաւոնն ասաց նրանց. «Թող այդպէս լինի: Տէրը ձեզ հետ: Քանզի արձակում եմ ձեզ. բայց մի՞թէ ձեր ունեցուածքն էլ եմ ազատ արձակում: Տեսնո՞ւմ էք, որ չարութիւն կայ ձեր մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Այդպէս չի լինի: Նախ թող գնան միայն տղամարդիկ եւ պաշտեն Աստծուն, քանի որ դուք հէնց այդ էիք ուզում»: Եւ նրանց վռնդեցին փարաւոնի մօտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Տէրն ասաց Մովսէսին. «Ձեռքդ մեկնի՛ր Եգիպտացիների երկրի վրայ, եւ մորեխ պիտի ելնի Եգիպտացիների երկրի վրայ եւ պիտի խժռեն երկրի այն ողջ բուսականութիւնն ու ծառերի պտուղները, որ փրկուել են կարկտից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Մովսէսը ձեռքը մեկնեց դէպի երկինք, եւ Տէրը մի ամբողջ ցերեկ ու գիշեր հարաւային հողմ բարձրացրեց երկրի վրայ: Երբ առաւօտ եղաւ, հարաւային հողմն առաւ մորեխն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'ու ցրեց Եգիպտացիների ամբողջ երկրի վրայ, նրա սահմաններից ներս: Ո՛չ դրանից առաջ էր այդքան մորեխ եղել, եւ ո՛չ էլ դրանից յետոյ այդքան մորեխ եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Մորեխը ծածկեց ամբողջ երկիրը, եւ երկիրը բուսականութիւնից զրկուեց: Մորեխը կերաւ երկրի այն ողջ բուսականութիւնն ու ծառերի պտուղները, որ փրկուել էին կարկտից: Եգիպտացիների ամբողջ երկրում կանաչ բան չմնաց ո՛չ ծառերի, ո՛չ էլ դաշտային տունկերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Փարաւոնն շտապ կանչեց Մովսէսին ու Ահարոնին եւ ասաց. «Ես մեղք գործեցի ձեր տէր Աստծու եւ ձեր դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Արդ, ներեցէ՛ք իմ այս յանցանքը եւս եւ աղաչեցէ՛ք ձեր տէր Աստծուն, որ ինձ ազատի այս մորեխներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Մովսէսը գնաց փարաւոնի մօտից եւ աղօթեց Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Աստուած ծովի կողմից սաստիկ հողմ բարձրացրեց, հողմն առաւ մորեխն ու լցրեց Կարմիր ծովը: Եգիպտացիների ամբողջ երկրում մորեխ չմնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Տէրը կարծրացրեց փարաւոնի սիրտը, եւ նա չարձակեց իսրայէլացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Տէրն ասաց Մովսէսին. «Ձեռքդ մեկնի՛ր դէպի երկինք, եւ Եգիպտացիների երկրի վրայ թող խաւար լինի՝ թանձրամած խաւար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Մովսէսը ձեռքը մեկնեց դէպի երկինք, եւ Եգիպտացիների ամբողջ երկրի վրայ երեք օր խաւար, մէգ ու մութ եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Երեք օր եղբայրն իր եղբօրը չտեսաւ, երեք օր ոչ ոք իր անկողնուց վեր չելաւ, մինչդեռ բոլոր իսրայէլացիների բոլոր բնակավայրերում լոյս էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Փարաւոնը, կանչելով Մովսէսին ու Ահարոնին, ասաց նրանց. «Գնացէք պաշտեցէ՛ք ձեր տէր Աստծուն, ձեր ունեցուածքը վերցրէ՛ք ձեզ հետ, բայց ձեր արջառն ու ոչխարը թողէ՛ք այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Մովսէսն ասաց. «Ողջակիզութեան ու զոհաբերութեան անասուններ դու ի՛նքդ մեզ պիտի տաս, որ մատուցենք մեր տէր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Մեր անասուններն էլ մեզ հետ պիտի գնան, մենք մի կճղակ անգամ չենք թողնելու այստեղ, որովհետեւ մեր տէր Աստծուն դրանցից պիտի զոհ մատուցենք: Մինչեւ մեր այնտեղ հասնելը մենք դեռ չգիտենք, թէ ինչ պիտի զոհաբերենք մեր տէր Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Տէրը կարծրացրեց փարաւոնի սիրտը, եւ փարաւոնը չուզեց արձակել նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Փարաւոնն ասաց. «Հեռացի՛ր ինձնից, զգո՛յշ եղիր, այլեւս չհամարձակուես իմ աչքին երեւալ, որովհետեւ այն օրը, որ երեւաս ինձ, կը սպանուես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Մովսէսն ասաց. «Դու արդէն ասացիր. այլեւս աչքիդ չեմ երեւայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Տէրն ասաց Մովսէսին. «Մի պատուհաս էլ պիտի հասցնեմ փարաւոնին ու Եգիպտոսին, որից յետոյ փարաւոնը ձեզ կ՚արձակի այստեղից: Բայց երբ նա արձակի ձեզ, կ՚արձակի ձեր ամբողջ ունեցուածքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Արդ, ժողովրդին գաղտնի յայտնի՛ր, որ իւրաքանչիւր տղամարդ եգիպտացի իր ընկերոջից եւ իւրաքանչիւր կին իր եգիպտացի հարեւանուհուց թող խնդրի ոսկեայ եւ արծաթեայ զարդեր ու զգեստներ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Տէրը շնորհ պարգեւեց իր ժողովրդին եգիպտացիների առաջ, եւ սրանք զարդեր տուին նրանց: Մովսէսը եգիպտացիների, փարաւոնի, նրա բոլոր պաշտօնեաների առաջ ու ժողովրդի աչքին շատ յարգարժան դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Մովսէսն ասաց փարաւոնին. «Այսպէս է ասում Տէրը. «Կէս գիշերին ես կը մտնեմ Եգիպտոս,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'եւ Եգիպտացիների երկրում կը մեռնեն բոլոր անդրանիկ զաւակները՝ իր գահին բազմած փարաւոնի անդրանիկ որդուց սկսած մինչեւ երկանքի մօտ աշխատող աղախնի անդրանիկ որդին, բոլոր անասունների առաջնածինները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Եւ Եգիպտացիների ամբողջ երկրում այնպիսի մեծ աղաղակ կը բարձրանայ, որի նմանը չի եղել, եւ այդպիսին չի էլ լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Բայց իսրայէլացիների շրջանում մի շուն անգամ չի կլանչելու մարդկանց ու անասունների վրայ, որպէսզի իմանաս, թէ ինչպիսի զարմանահրաշ գործեր է անում Տէրը եգիպտացիների ու իսրայէլացիների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Այս բոլոր ծառաներդ պիտի գան ծնրադրեն իմ առաջ, երկրպագեն ինձ ու ասեն. «Ելէք գնացէ՛ք դու եւ քո ողջ ժողովուրդը, որին դու ես առաջնորդում: Այդ ժամանակ էլ ես կ՚ելնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Եւ Մովսէսը փարաւոնի մօտից դուրս ելաւ խիստ զայրացած: Տէրն ասաց Մովսէսին. «Փարաւոնը ձեզ չպիտի լսի, որպէսզի ես Եգիպտացիների երկրում է՛լ աւելի շատ նշաններ ցոյց տամ ու զարմանահրաշ գործեր անեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Մովսէսն ու Ահարոնը Եգիպտացիների երկրում փարաւոնի առաջ արեցին այս բոլոր նշաններն ու զարմանահրաշ գործերը: Տէրը կարծրացրեց փարաւոնի սիրտը, եւ փարաւոնը չուզեց իսրայէլացիներին Եգիպտացիների երկրից արձակել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Տէրը Եգիպտացիների երկրում խօսեց Մովսէսի ու Ահարոնի հետ եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '«Այս ամիսը թող ձեզ համար ամիսների սկիզբը լինի. այն թող տարուայ առաջին ամիսը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Դու խօսի՛ր իսրայէլացի ողջ ժողովրդի հետ ու ասա՛. «Այս ամսի տասներորդ օրը ամէն մարդ թող մի ոչխար առնի ըստ իր ընտանիքի՝ ամէն մի տան համար մէկ ոչխար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Եթէ մի ընտանիքի անդամները այնքան քիչ են, որ չեն կարող մէկ ոչխար ուտել, ապա ընտանիքի մեծը, ըստ ընտանիքի թուի թող միանայ իր հարեւանի կամ ընկերոջ հետ, եւ իւրաքանչիւրը թող ստանայ ոչխարի համապատասխան բաժինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ձեր այդ ոչխարը որեւէ պակասութիւն թող չունենայ, լինի արու, մէկ տարեկան ու անարատ: Այն կարող է գառ կամ ուլ լինել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Այն կը պահէք մինչեւ այս ամսի տասնչորսերորդ օրը, եւ իսրայէլացիները այն թող մորթեն երեկոյեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Թող վերցնեն նրա արիւնից ու քսեն այն տան դռան սեմին երկու տեղ ու դռան շրջանակի վերեւը այն տան, ուր այն ուտելու են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Այդ գիշեր թող ուտեն կրակի վրայ խորոված միսը, այն թող ուտեն բաղարջ հացով ու դառն խոտերով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Դրանք հում կամ խաշած չուտէք, այլ՝ կրակի վրայ խորովելով: Կ՚ուտէք նաեւ ոչխարի գլուխը, ոտքերն ու փորոտիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Առաւօտեան դրանից ոչինչ թող չմնայ: Ոչխարի ոսկորները մի՛ ջարդէք, այլ, ինչ որ աւելանայ դրանից, կրակով կ՚այրէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Եւ կ՚ուտէք այսպէս. ձեր գօտիները թող ձեր մէջքին լինեն, ձեր կօշիկները՝ ձեր ոտքերին, ձեր ցուպերը՝ ձեր ձեռքին: Արագ կ՚ուտէք, որովհետեւ Տիրոջ զատիկն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Այդ գիշեր ես պիտի անցնեմ Եգիպտացիների ամբողջ երկրով եւ պիտի պատուհասեմ Եգիպտացիների երկրի բոլոր արու առաջնածիններին՝ թէ՛ մարդկանց, թէ՛ անասունների: Եգիպտացիների բոլոր աստուածներից վրէժ պիտի լուծեմ, որովհետեւ ե՛ս եմ Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Եւ նշուած արիւնը այն տների վրայ, ուր ուտելու էք, թող ձեզ նշան լինի: Ես, տեսնելով այդ արիւնը, պիտի խնայեմ ձեզ, եւ ձեր գլխին չեն իջնի մահաբեր այն հարուածները, որոնցով պիտի պատուհասեմ Եգիպտացիների երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Այդ օրը ձեզ համար յիշարժան թող լինի, եւ դուք, իբրեւ Տիրոջ տօն, այդ օրը տօնեցէ՛ք սերնդէսերունդ: Դա, իբրեւ կարգ, յաւիտեան կը տօնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, '«Եօթը օր բաղարջ հաց կ՚ուտէք, առաջին իսկ օրից սկսած ձեր տնից կը վերացնէք թթխմորը: Բոլոր նրանք, ովքեր առաջին օրից մինչեւ եօթներորդ օրը թթխմորով հաց կ՚ուտեն, կը վերացուեն իսրայէլացիների միջից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Առաջին օրը թող սուրբ հռչակուի: Ձեզ համար թող սուրբ լինի նաեւ նուիրական եօթներորդ օրը: Այդ օրերին ոչ մի աշխատանք չկատարէք, այլ կատարեցէք միայն այն, ինչ կապուած է իւրաքանչիւր մարդու անձնական կարիքների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Իմ այս պատուիրանները կը պահէք, որպէսզի այդ օրը ես ձեր ժողովրդին հանեմ Եգիպտացիների երկրից: Այդ օրը, իբրեւ կարգ, ձեր ժողովրդի մէջ կը նշէք յաւիտենապէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Առաջին ամսուայ տասնչորսերորդ օրուայ երեկոյից սկսած բաղարջ հաց կ՚ուտէք մինչեւ ամսի քսանմէկերորդ օրուայ երեկոն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Եօթը օր ձեր տներում թթխմոր չպիտի լինի: Բոլոր նրանք, ովքեր թթխմորով հաց կ՚ուտեն, կը վերացուեն Իսրայէլի ժողովրդի միջից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ձեր երկիրն եկած եկուորներ լինեն թէ տեղաբնակներ, ոչ ոք թթխմորով հաց թող չուտի: Ձեր բոլոր բնակավայրերում բաղարջ հաց պիտի ուտէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Մովսէսը կանչեց բոլոր իսրայէլացի ծերերին ու նրանց ասաց. «Գնացէ՛ք, ձեր իւրաքանչիւր ընտանիքի համար մի ոչխար առէ՛ք եւ մորթեցէ՛ք զատկի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Վերցրէ՛ք մի խուրձ ծոթրին, այն թաթախեցէ՛ք դռան մօտ եղած արեան մէջ եւ դրանով նշան արէ՛ք դռան սեմին երկու տեղ եւ դռան շրջանակի վերեւը: Բայց ձեզնից ոչ ոք մինչեւ առաւօտ իր տան դռնից դուրս չգայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Տէրն անցնելու է եգիպտացիներին կոտորելու համար: Նա, տեսնելով դռան սեմին երկու տեղ եւ դռան շրջանակի վերեւում եղած արիւնը, կ՚անցնի կը գնայ այդ դռնով եւ Ոչնչացնողին թոյլ չի տայ մտնել ձեր տներն ու կոտորել ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Այս խօսքերը մինչեւ յաւիտեան օրէնք թող լինեն քեզ եւ քո որդիների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Երբ կը մտնէք այն երկիրը, որ Տէրը, իր խոստման համաձայն, տալու է ձեզ, կը կատարէք այդ ծիսակատարութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Եթէ պատահի, որ ձեր որդիները հարցնեն ձեզ, թէ՝ «Ի՞նչ է նշանակում այս ծիսակատարութիւնը»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'նրանց կը պատասխանէք, որ Տիրոջ համար զատկի զոհն է սա, այն Տիրոջ, որ Եգիպտոսում եգիպտացիներին կոտորելիս խնայեց իսրայէլացիներին, փրկեց մեր ընտանիքները»: Ժողովուրդը խոնարհուեց ու երկրպագութիւն արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Իսրայէլացիները գնացին ու արեցին այնպէս, ինչպէս Տէրն էր պատուիրել Մովսէսին ու Ահարոնին. նրանք այդպէս էլ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Երբ կէս գիշեր եղաւ, Տէրը Եգիպտացիների երկրում կոտորեց եգիպտացի բոլոր անդրանիկ զաւակներին՝ իր գահին բազմած փարաւոնի անդրանիկից մինչեւ բանտի մէջ արգելափակուած գերի կնոջ անդրանիկը, նաեւ անասունների բոլոր առաջնածինները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Գիշերը վեր կացան փարաւոնն ինքը, նրա բոլոր պաշտօնեաներն ու բոլոր եգիպտացիները: Եգիպտացիների ամբողջ երկրում մեծ աղաղակ բարձրացաւ, որովհետեւ տուն չկար, որտեղ մեռել չլինէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Փարաւոնը գիշերով կանչեց Մովսէսին ու Ահարոնին եւ ասաց նրանց. «Դուք եւ իսրայէլացիներդ վեր կացէք գնացէ՛ք իմ ժողովրդի միջից, գնացէք պաշտեցէ՛ք ձեր տէր Աստծուն, ինչպէս որ ասացիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ձեզ հետ տարէ՛ք նաեւ ձեր արջառն ու ոչխարը, ինչպէս որ ասացիք, բայց ինձ էլ օրհնեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Եւ եգիպտացիներն ստիպում էին իսրայէլացի ժողովրդին, որ շտապ դուրս գան երկրից, որովհետեւ ասում էին. «Նրանց պատճառով մենք բոլորս էլ կը մեռնենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Ժողովուրդն իր հունցած, բայց դեռեւս չհասած խմորը շորերի մէջ փաթաթելով՝ ուսն առաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Իսրայէլացիներն արեցին այնպէս, ինչպէս իրենց հրամայել էր Մովսէսը. եգիպտացիներից նրանք ուզեցին ոսկեայ, արծաթեայ զարդեր ու զգեստներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Տէրը շնորհ պարգեւեց իր ժողովրդին եգիպտացիների առաջ. սրանք զարդեր տուին նրանց: Այսպիսով նրանք կողոպտեցին եգիպտացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Իսրայէլացիները՝ վեց հարիւր հազար տղամարդ, հետիոտն, բացի մնացած բազմութիւնից, Ռամեսից մեկնեցին Սոկքոթ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Նրանց հետ ճանապարհ ընկաւ մի խառնիճաղանջ բազմութիւն, մեծ քանակութեամբ արջառ, ոչխար ու այլ անասուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Նրանք Եգիպտոսից բերած ու դեռ չհասած խմորով բաղարջ հաց եփեցին, որովհետեւ այն դեռ չէր խմորուել, քանի որ եգիպտացիները երկրից հանել էին իրենց, եւ իրենք չէին կարողացել սպասել ու իրենց ճանապարհի պաշար չէին արել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Իսրայէլացիներն իրենք ու իրենց հայրերը Եգիպտացիների երկրում եւ Քանանացիների երկրում ապրեցին չորս հարիւր երեսուն տարի: Երբ չորս հարիւր երեսուն տարին վերջացաւ, նոյն օրն իսկ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Տիրոջ ամբողջ ժողովուրդը գիշերով Եգիպտացիների երկրից դուրս եկաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Իսրայէլացիները Տիրոջ հրամանով այդ գիշերը անքուն մնացին, որպէսզի նա նրանց դուրս բերի Եգիպտացիների երկրից. դա Տիրոջ անքուն մնալու այն գիշերն էր, որ բոլոր իսրայէլացիները սերնդէսերունդ պիտի յիշեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Տէրը Մովսէսին ու Ահարոնին ասաց. «Սա է զատկի կարգը. ոչ մի օտարական չպիտի ուտի դրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Որեւէ մէկը իր ծառային ու փողով գնուած ստրուկին թող թլփատի եւ թլփատուելուց յետոյ միայն թող նա ուտի դրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Պանդուխտն ու վարձկանը թող չուտեն դրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Տա՛ն մէջ պէտք է ուտուի այն. միսը տնից դուրս չպիտի հանէք եւ դրա ոսկորը չպիտի ջարդէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Իսրայէլի ողջ ժողովուրդը պէտք է կատարի դա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Եթէ մի օտարական մօտենայ ձեզ եւ ուզենայ կատարել Տիրոջ զատիկը, դու պէտք է թլփատես նրա բոլոր արու զաւակներին, եւ դրանից յետոյ միայն նա կարող է մօտենալ կատարելու զատիկը: Նա կը համարուի երկրի տեղաբնակ: Ոչ մի անթլփատ դրանից չպէտք է ուտի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Օրէնքը հաւասարապէս տարածւում է եւ՛ տեղաբնակի, եւ՛ ձեզ մօտ ապրել ցանկացող օտարականի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Բոլոր իսրայէլացիներն արեցին այնպէս, ինչպէս պատուիրել էր Տէրը Մովսէսին ու Ահարոնին. նրանք այդպէս էլ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Ահա այդ օրն էր, որ Տէրը բոլոր իսրայէլացիներին հանեց Եգիպտացիների երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Տէրը խօսեց Մովսէսի հետ եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '«Ինձ նուիրաբերի՛ր բոլոր իսրայէլացիների անդրանիկ զաւակներին, ամէն մի նախածին, մարդ թէ անասուն, որովհետեւ իմն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Մովսէսն ասաց ժողովրդին. «Յիշեցէ՛ք այս օրը, երբ դուք դուրս եկաք Եգիպտոսից՝ ստրկութեան այս տնից, որովհետեւ Տէրը ձեզ իր հզօր ձեռքով հանեց այստեղից: Թթխմորով հաց չպիտի ուտէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'որովհետեւ դուք այսօր, գարնանային վաղահաս բերքի ամսին էք դուրս գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Երբ քո Տէր Աստուածը քեզ տանի քո հայրերին խոստացած Քանանացիների, Քետացիների, Ամորհացիների, Խեւացիների, Յեբուսացիների, Փերեզացիների ու Գերգեսացիների երկիրը, ուր կաթ ու մեղր է հոսում, ապա հէնց այդ ամսին այս ծիսակատարութիւնը կ՚անես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Եօթը օր բաղարջ հաց կ՚ուտէք, իսկ եօթներորդ օրը Տիրոջ տօնը կը լինի. բաղարջ հաց կ՚ուտէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Ձեր տանը թթխմորով հաց չլինի, քո ողջ երկրի սահմաններում թթխմոր չերեւայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Այդ օրը քո որդուն կը պատմես՝ ասելով. «Դա կատարւում է ի յիշատակ այն բանի, ինչ արել է ինձ Տէր Աստուածը, երբ դուրս էի գալիս Եգիպտոսից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Ասածս նշան արա՛ ձեռքիդ վրայ, նաեւ նշան՝ ճակատիդ, որ յիշես: Տիրոջ օրէնքները թող քո բերանում լինեն, քանի որ Տիրոջ հզօր ձեռքն է հանել քեզ Եգիպտոսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Այս օրէնքները կը պահպանէք տարէցտարի ձեր կեանքի բոլոր օրերում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, '«Երբ քո Տէր Աստուածը քեզ կը տանի Քանանացիների երկիրը, ինչպէս խոստացել է քեզ ու քո հայրերին, եւ այն կը տայ քեզ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Տիրոջ համար կ՚առանձնացնես անդրանիկ բոլոր արու ծնունդներին եւ քո արջառների ու ոչխարների առաջնածիններին, որոնք պիտի ծնուեն: Դրանք բոլորը Տիրոջը կը նուիրաբերես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Առաջնածին էշը կը փոխանակես ոչխարի հետ, իսկ եթէ չուզենաս փոխանակել, ապա դա փրկագին կը տաս: Քո որդիների բոլոր անդրանիկ զաւակներին կը փրկագնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Եթէ դրանից յետոյ որդիդ հարցնի քեզ ու ասի, թէ՝ «Ի՞նչ է այս», նրան կ՚ասես, թէ՝ «Տէրը հզօր ձեռքով է հանել մեզ Եգիպտացիների երկրից՝ ստրկութեան տնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Երբ փարաւոնի սիրտը կարծրացաւ ու մեզ չարձակեց, Տէրը Եգիպտացիների երկրում կոտորեց բոլոր անդրանիկներին՝ մարդկանց անդրանիկ զաւակներից մինչեւ անասունների առաջնածինները: Հէնց դրա համար էլ ես Տիրոջն եմ նուիրաբերում բոլոր առաջնածին արուներին, իսկ իմ որդիներից բոլոր անդրանիկ զաւակն»րին փրկագին կը տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ասածս նշան արա՛ ձեռքիդ վրայ, նաեւ նշան՝ ճակատիդ, որ յիշես, թէ Տէրը ինչպէս է հզօր ձեռքով մեզ հանել Եգիպտոսից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Երբ փարաւոնն արձակեց ժողովրդին, Աստուած նրանց կարճ ճանապարհով՝ Փղշտացիների երկրով չառաջնորդեց, որովհետեւ Աստուած մտածեց, թէ ժողովուրդը պատերազմի բռնուելով՝ գուցէ վախենայ ու Եգիպտոս վերադառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Դրա համար Աստուած ժողովրդին շրջանցիկ՝ անապատի ճանապարհով տարաւ դէպի Կարմիր ծով: Իսրայէլացիները Եգիպտացիների երկրից դուրս եկան հինգերորդ սերնդի ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Մովսէսն իր հետ տարաւ Յովսէփի ոսկորները, որովհետեւ Յովսէփը, երդուեցնելով Իսրայէլի որդիներին, ասել էր. «Երբ Տէրը ձեզ այցի գայ, իմ ոսկորները կը հանէք այստեղից ու կը տանէք ձեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Սոկքոթից դուրս գալով՝ իսրայէլացիները եկան եւ կայք հաստատեցին Ոթոմում՝ անապատի եզրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Աստուած ցերեկը նրանց առաջնորդում էր ամպի սիւնով, որպէսզի ճանապարհ ցոյց տայ նրանց, իսկ գիշերը՝ հրէ սիւնով, որպէսզի գիշեր-ցերեկ նրանք ուղեցոյց ունենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Ցերեկը ամպի սիւնը, իսկ գիշերը հրէ սիւնը միշտ ամբողջ ժողովրդի աչքի առաջ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Տէրը, խօսելով Մովսէսի հետ, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '«Իսրայէլացիներին ասա՛, որ վերադառնան, կայք հաստատեն Մագդողի ու ծովի միջեւ գտնուող հանգրուանում, Բեէղսեպփոնի դիմաց: Դրանց դիմաց՝ Կարմիր ծովի եզերքին կայք կը հաստատես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Փարաւոնը իսրայէլացիներիդ մասին կ՚ասի, թէ՝ «Մոլորուել են այս երկրում, որովհետեւ անապատը շրջափակել է նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Ես պիտի կարծրացնեմ փարաւոնի սիրտը, նա պիտի հետապնդի նրանց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'իսկ ես պիտի փառաւորուեմ փարաւոնի ու նրա ամբողջ զօրքի առաջ: Եւ բոլոր եգիպտացիները պիտի իմանան, որ ե՛ս եմ Տէրը»: Եւ այդպէս էլ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Եգիպտացիների արքային յայտնեցին, թէ՝ «Ժողովուրդը փախել է»: Փարաւոնի ու նրա պաշտօնեաների սրտերն ըմբոստացան ժողովրդի դէմ, եւ նրանք ասացին. «Այդ ի՞նչ արեցինք, ինչո՞ւ թոյլ տուեցինք, որ իսրայէլացիները գնան, եւ մենք զրկուենք մեր ստրուկներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Փարաւոնը լծեց իր կառքը եւ իր հետ տարաւ իր ամբողջ ժողովրդին: Նա վերցրեց վեց հարիւր ընտիր կառքեր, եգիպտացիների ամբողջ հեծելազօրն ու դրանց զօրավարներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Տէրը կարծրացրեց եգիպտացիների արքայ փարաւոնի սիրտը, եւ սա հետապնդեց իսրայէլացիներին: Իսրայէլացիները գնում էին՝ ձեռքները բարձր պահած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Եգիպտացիները հետապնդեցին նրանց ու նրանց գտան ծովեզերքի մօտ՝ կայք հաստատած: Փարաւոնի ողջ հեծելազօրն ու կառքերը, նրա հեծեալներն ու բանակը կանգնեցին հանգրուանածների դիմաց, Բեէղսեպփոնի դէմ առ դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Փարաւոնը մօտեցաւ: Իսրայէլացիները բարձրացնելով իրենց աչքերը՝ տեսան, որ եգիպտացիները կայք են հաստատել իրենց թիկունքում. սաստիկ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Իսրայէլացիները աղաղակ բարձրացրին առ Աստուած ու Մովսէսին ասացին. «Իբր թէ Եգիպտացիների երկրում գերեզմաններ չկայի՞ն, որ մեզ բերեցիր այստեղ՝ անապատում սպանուելու: Այս ի՞նչ բերեցիր մեր գլխին, ինչո՞ւ մեզ հանեցիր Եգիպտոսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Մի՞թէ Եգիպտացիների երկրում քեզ չասացինք, թէ՝ «Թո՛յլ տուր, որ ծառայենք եգիպտացիներին»: Մեզ համար աւելի լաւ կը լինէր, որ ծառայէինք եգիպտացիներին, քան մեռնէինք այս անապատում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Մովսէսն ասաց ժողովրդին. «Քաջալերուեցէ՛ք, պի՛նդ կացէք եւ կը տեսնէք Տիրոջ արած փրկութիւնը, որ նա պարգեւելու է ձեզ այսօր, քանզի այսօր ձեր տեսած եգիպտացիներին այլեւս յար յաւիտեան չէք տեսնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Տէ՛րը պիտի պատերազմի ձեր փոխարէն, դուք լո՛ւռ մնացէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Տէրն ասաց Մովսէսին. «Ինչո՞ւ ես կանչում ինձ: Ասա՛ իսրայէլացիներին, որ շարժուեն գնան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Իսկ դու ա՛ռ գաւազանդ, ձեռքդ մեկնի՛ր ծովի վրայ, ճեղքի՛ր այն, եւ իսրայէլացիները թող մտնեն ծովի մէջ ու անցնեն ինչպէս ցամաքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ես կը կարծրացնեմ փարաւոնի եւ բոլոր եգիպտացիների սիրտը, սրանք նրանց յետեւից ծով կը մտնեն, եւ ես կը փառաւորուեմ փարաւոնի, նրա ամբողջ զօրքի, կառքերի ու հեծելազօրի առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Բոլոր եգիպտացիները կը գիտենան, որ ե՛ս եմ Տէրը, երբ փառաւորուեմ փարաւոնի, նրա կառքերի ու հեծելազօրի առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Իսրայէլացիների բանակի առջեւից գնացող Աստծու հրեշտակը ելաւ ու անցաւ գնաց նրանց յետեւը: Վերացաւ ամպի սիւնը նրանց առջեւից ու կանգնեց նրանց թիկունքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Ամպի սիւնը մտաւ եգիպտացիների ու իսրայէլացիների բանակների միջեւ: Խաւար ու մէգ պատեց: Գիշերն անցաւ, բայց ողջ գիշերը բանակները իրար չմօտեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Մովսէսը ձեռքը մեկնեց ծովի վրայ, եւ հարաւային հողմի ուժով ողջ գիշեր ծովը յետ մղուեց. բացուեց ծովի յատակը, ջուրը երկուսի բաժանուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Իսրայէլացիները մտան յատակը բացուած ծովի մէջ ու առաջ շարժուեցին ինչպէս ցամաքով: Ջուրը նրանց աջ ու ձախ կողմերից պարիսպ էր դարձել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Եգիպտացիները հետապնդեցին նրանց, եւ փարաւոնի ամբողջ հեծելազօրը, նրա կառքերն ու հեծեալները նրանց յետեւից մտան ծովը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Առաւօտեան Տէրը հրի ու ամպի սեան միջով նայեց եգիպտացիների բանակին եւ խուճապի մատնեց եգիպտացիների բանակը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'նա կաշկանդեց նրանց կառքերի անիւները, եւ նրանք դժուարութեամբ էին առաջ շարժւում: Եգիպտացիներն ասացին. «Հեռո՛ւ փախչենք իսրայէլացիներից, որովհետեւ Տէրը յօգուտ նրանց է պատերազմում եգիպտացիներիս դէմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Տէրն ասաց Մովսէսին. «Ձեռքդ մեկնի՛ր ծովի վրայ, եւ ջրերը թող միանան ու ծածկեն եգիպտացիներին, նրանց կառքերն ու հեծեալներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Մովսէսը ձեռքը մեկնեց ծովի վրայ, եւ ջրերն առաւօտեան վերադարձան իրենց տեղը: Եգիպտացիները փորձեցին փախչել ջրից, բայց Տէրը եգիպտացիներին թափեց ծովը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'եւ, նորից իրար միացնելով ծովի ջրերը, ծածկեց կառքերը, հեծեալներին եւ փարաւոնի բոլոր զօրքերին, որոնք ծով էին մտել նրանց հետ: Նրանցից ոչ ոք կենդանի չմնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Իսրայէլացիները ծովի միջով կարծես ցամաքի վրայով էին գնում, իսկ ջուրը նրանց աջ ու ձախ կողմերից պարիսպ էր դարձել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Տէրն այդ օրը իսրայէլացիներին փրկեց եգիպտացիների ձեռքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Իսրայէլացիները տեսան եգիպտացիների դիակները, որոնք ծովի ափ էին նետուած: Իսրայէլացիները տեսնելով Տիրոջ հզօր ձեռքը, եգիպտացիների գլխին բերած փորձանքը՝ վախեցան Տիրոջից, հաւատացին Աստծուն ու նրա ծառայ Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Այդ ժամանակ Մովսէսն ու իսրայէլացիները հետեւեալ օրհներգն ուղղեցին Աստծուն՝ ասելով. «Օրհնենք Տիրոջը, որ փառքով է փառաւորուած: Նրանց երիվարներն ու հեծեալներին թափեց ծովը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Տէրը ինձ համար ընդունելի օգնական եղաւ, նա ինձ համար փրկութիւն եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Նա՛ է իմ Աստուածը, եւ ես նրան եմ փառաւորելու: Նա իմ հօր Աստուածն է, եւ ես պիտի մեծարեմ նրան: Տէրը խորտակում է պատերազմները, նրա անունը Տէր է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Նա փարաւոնի կառքերն ու զօրքերը ծովը թափեց,նաեւ ընտիր հեծեալներին ու զօրավարներին: Նրանք ջրասոյզ եղան Կարմիր ծովում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Ծովը ծածկեց նրանց, նրանք քարի պէս ընկղմուեցին ծովի յատակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Քո աջը, Տէ՛ր, զօրութեամբ փառաւորուեց, քո աջը, Տէ՛ր, խորտակեց թշնամուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Դու փառքի հզօրութեամբ ջարդուփշուր արեցիր հակառակորդներին, առաքեցիր քո բարկութիւնը, եւ այն հրոյ ճարակ դարձրեց նրանց ինչպէս եղէգ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Քո զայրոյթի հողմից ճեղքուեցին ջրերը, պարիսպների նման դիզուեցին ջրերը, ծովի մէջ քարացան ալիքները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Թշնամին ասաց. «Հետապնդեմ ու հասնեմ նրանց, բաժանեմ աւարը եւ դրանցով յագուրդ տամ ինձ: Սրի քաշեմ նրանց, որ իմ ձեռքը տիրի նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Դու քո հողմն առաքեցիր, նրանց ծածկեց ծովը, եւ նրանք կապարի նման սուզուեցին ջրերի խորքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Աստուածների մէջ, Տէ՛ր, ո՞վ կայ քեզ նման, եւ կամ ո՞վ կարող է նմանուել քեզ՝ փառաւորեալդ սրբերի մէջ, փառքով սքանչացեալդ, որ նշաններ ես գործում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Աջ ձեռքդ մեկնեցիր, եւ երկիրը կուլ տուեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Արդարութեամբ առաջնորդեցիր քո այս ժողովուրդին, որին փրկեցիր, քո զօրութեամբ մխիթարեցիր նրան քո սուրբ բնակավայրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Ժողովուրդները լսեցին լուրն այս ու բարկացան: Սարսափը պատեց Քանանացիների երկրի բնակիչներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Խուճապահար եղան Եդոմի դատաւորներն ու մովաբացիների իշխանները: Դող բռնեց նրանց, հալումաշ եղան Քանանացիների երկրի բոլոր բնակիչները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Թող պատեն նրանց ահն ու սարսափը, քո բազկի հզօրութեամբ թող քարանան նրանք, մինչեւ որ անցնի քո ժողովուրդը, Տէ՛ր, մինչեւ որ անցնի քո այս ժողովուրդը, որին ստացար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Տա՛ր, բնակեցրո՛ւ նրանց այն լերան վրայ,որ ժառանգութիւնն է քո,քո պատրաստած բնակավայրում, որ սրբութիւն ես դարձրել, Տէ՛ր:Տէ՛ր, քո ձեռքե՛րը պատրաստեցին այդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Տէրը յաւիտենական, առաւել քան յաւիտենական թագաւոր է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Երբ փարաւոնի հեծելազօրն իր կառքերով ու հեծեալներով ծով մտաւ, Տէրը նրա վրայ թափեց ծովի ջրերը, իսկ իսրայէլացիները յատակը բացուած ծովի միջով անցան գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Մարիամ մարգարէն՝ Ահարոնի քոյրը, իր ձեռքն առաւ թմբուկը, եւ բոլոր կանայք գնացին նրա յետեւից՝ թմբուկ խփելով ու պարելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Առաջից գնում էր Մարիամն ու ասում. «Օրհնենք Տիրոջը, քանզի նա փառքով է փառաւորուած. նա երիվարներն ու հեծեալներին ծովը թափեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Մովսէսը իսրայէլացիներին Կարմիր ծովից տարաւ հասցրեց Սուր կոչուած անապատը: Նրանք երեք օրուայ ճանապարհ գնացին անապատի միջով, բայց խմելու ջուր չգտան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Եկան Մեռա, բայց Մեռայում էլ չկարողացան ջուր խմել, որովհետեւ այն դառն էր: Դրա համար Մովսէսն այդ վայրն անուանեց Դառնութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Ժողովուրդը տրտնջաց Մովսէսի դէմ ու ասաց. «Ի՞նչ խմենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Մովսէսն աղաղակեց առ Աստուած. եւ Տէրը նրան մի փայտ ցոյց տուեց: Մովսէսն այն նետեց ջրի մէջ, եւ ջուրը քաղցրահամ դարձաւ: Այնտեղ Աստուած ժողովրդին տուեց օրէնք ու իրաւունք եւ այնտեղ էլ փորձութեան ենթարկեց նրան: Նա ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, '«Եթէ ուշադիր լսես քո տէր Աստծու ձայնը, նրա համար հաճելի գործեր կատարես, ունկնդիր լինես նրա պատուիրաններին ու ենթարկուես նրա բոլոր հրամաններին, քեզ վրայ չեմ թափի բոլոր այն հիւանդութիւնները, որ թափեցի եգիպտացիների վրայ, քանզի ես եմ քեզ բժշկող Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Եւ եկան հասան Եղիմ: Այնտեղ կային ջրի տասներկու աղբիւր ու եօթանասուն արմաւենի: Նրանք կայք հաստատեցին այնտեղ, ջրի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Իսրայէլացի ամբողջ ժողովուրդը Եղիմից ճանապարհ ընկաւ ու եկաւ Սին անապատը, որը գտնւում է Եղիմի ու Սինայի միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Եգիպտացիների երկրից դուրս գալու երկրորդ ամսուայ տասնհինգերորդ օրը իսրայէլացի ողջ ժողովուրդը անապատում դժգոհեց Մովսէսից ու Ահարոնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Իսրայէլացիներն ասացին նրանց. «Աւելի լաւ կը լինէր Տիրոջ հարուածների զոհը դառնայինք Եգիպտացիների երկրում, երբ մսով լի կաթսաների մօտ էինք նստում ու կուշտ հաց ուտում, քան բերէիք մեզ այս անապատը, որ ողջ ժողովրդին սովամահ անէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Տէրն ասաց Մովսէսին. «Ահա ես ձեզ հաց կը թափեմ երկնքից: Իմ ժողովուրդը թող վեր կենայ ու այն հաւաքի, ինչքան անհրաժեշտ է իւրաքանչիւր օրուայ համար: Ես այդ կերպ կը փորձեմ նրանց, թէ կ՚ենթարկուե՞ն իմ օրէնքներին, թէ ո՞չ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Վեցերորդ օրը թող պատրաստեն նախորդ իւրաքանչիւր օրուայ համար հաւաքածի կրկնապատիկը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Մովսէսն ու Ահարոնը ասացին իսրայէլացի ամբողջ ժողովրդին. «Երեկոյեան կ՚իմանաք, որ Տէրն է ձեզ հանել Եգիպտացիների երկրից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'իսկ առաւօտեան ականատես կը լինէք Տիրոջ փառքին, որովհետեւ նա լսել է Աստծու հանդէպ ձեր տրտունջը: Մենք ովքե՞ր ենք, որ տրտնջում էք մեր դէմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Մովսէսն ասաց. «Տէրը լսեց մեր դէմ ուղղուած ձեր տրտունջը, դրա համար էլ նա երեկոները ձեզ ուտելու միս, իսկ առաւօտները յագենալու չափ հաց պիտի տայ: Մենք ովքե՞ր ենք, որ ձեր տրտունջը մեր դէմ էք ուղղում. ձեր տրտունջը Աստծու դէմ է ուղղուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Մովսէսն ասաց Ահարոնին. «Իսրայէլացի ամբողջ ժողովրդին յայտնի՛ր. «Մօտեցէ՛ք Տիրոջը, որովհետեւ նա լսեց ձեր տրտունջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Մինչ Ահարոնը խօսում էր իսրայէլացի ամբողջ ժողովրդի հետ, նրանք նայեցին դէպի անապատ, եւ ահա Տիրոջ փառքը երեւաց ամպի ձեւով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Տէրը խօսելով Մովսէսի հետ՝ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '«Լսեցի իսրայէլացիների տրտունջը: Արդ, խօսի՛ր նրանց հետ ու ասա՛. «Երեկոները միս կ՚ուտէք, իսկ առաւօտները հացով կը յագենաք: Եւ կ՚իմանաք, որ ես եմ ձեր Տէր Աստուածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Երեկոյեան լորամարգիներ թափուեցին ու ծածկեցին բանակատեղին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Առաւօտեան, երբ ցօղը վերանում էր բանակատեղիի շրջապատից, անապատի երեսին գինձի սպիտակ սերմի նման մանր եւ երկրի վրայի եղեամի նման մի բան կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Երբ իսրայէլացիները տեսան այն, իրար ասացին. «Ի՞նչ է սա»: Որովհետեւ չգիտէին, թէ դա ինչ է: Մովսէսն ասաց նրանց. «Դա այն հացն է, որ Տէրը ձեզ տուել է ուտելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Տէրը հետեւեալն է պատուիրել. «Իւրաքանչիւր ոք դրանցից թող հաւաքի այնքան, որքան անհրաժեշտ է մէկ մարդու համար, ըստ ձեր ընտանիքների շնչերի թուի: Հաւաքեցէ՛ք ըստ վրանում գտնուող իւրաքանչիւր մարդու թուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Իսրայէլացիներն այդպէս էլ արեցին. հաւաքեցին ոմանք շատ, ոմանք քիչ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Չափեցին եւ տեսան, որ ումը որ շատ էր, սահմանուած չափից չաւելացաւ, իսկ ումը՝ քիչ, սահմանուած չափից չպակասեց: Իւրաքանչիւրը իր կարիքի չափով էր հաւաքել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Մովսէսն ասաց նրանց. «Ոչ ոք մինչեւ առաւօտ դրանից աւելցուկ չթողնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Ոմանք, սակայն, Մովսէսին չլսեցին. դրանից աւելցուկ մնաց առաւօտեան: Դա որդնոտեց ու նեխեց: Մովսէսը զայրացաւ նրանց վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Դրանից յետոյ ամէն առաւօտ իւրաքանչիւրը հաւաքում էր իրեն պէտք եղածի չափ: Երբ արեւը տաքացնում էր, այն հալւում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Վեցերորդ օրը հաւաքեցին պէտք եղածի կրկնապատիկը՝ ամէն մէկի համար երկուական բաժին: Ժողովրդի բոլոր առաջնորդները գնացին Մովսէսի մօտ ու նրան յայտնեցին այդ մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Մովսէսն ասաց. «Այս է Տիրոջ ասածը. «Վաղը շաբաթ է, Տիրոջ հանգստեան սուրբ օրը: Ինչ որ եփելու էք, եփեցէ՛ք, ինչ որ թխելու էք, թխեցէ՛ք այսօր, իսկ մնացած ամէն ինչ թողէ՛ք ամանների մէջ մինչեւ առաւօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Եւ դա թողեցին մինչեւ առաւօտ, ինչպէս նրանց հրամայել էր Մովսէսը. այն չնեխեց, չորդնոտեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Մովսէսն ասաց. «Այդ կերէ՛ք այսօր, քանի որ Տիրոջ շաբաթ օրն է այսօր, դրանից այսօր դաշտում չէք գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Վեց օր կը հաւաքէք դա, իսկ եօթներորդ օրը՝ շաբաթ օրը դրանից չի լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Եօթներորդ օրը ժողովրդի միջից ոմանք ելան դրանից հաւաքելու, բայց չգտան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Տէրն ասաց Մովսէսին. «Մինչեւ ե՞րբ չպիտի անսաք իմ պատուիրաններին ու օրէնքներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Տեսաք, որ Տէրը ձեզ հանգստեան օր նշանակեց այս շաբաթ օրը: Դրա համար էլ նա վեցերորդ օրը ձեզ երկու օրուայ հաց տուեց՝ ասելով. «Ձեզնից իւրաքանչիւրը թող նստի իր տանը, եօթներորդ օրը թող ոչ ոք չելնի այդ տեղից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Եւ ժողովուրդը եօթներորդ օրը հանգստացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Իսրայէլացիները իրենց կերածի անունը դրեցին ման: Դա գինձի սերմի նման սպիտակ էր ու մեղրախորիսխի համ ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Մովսէսն ասաց. «Ահա թէ ինչ հրամայեց Աստուած. «Մի ամանի մէջ մէկ չափ մանանայ լցրէ՛ք եւ այն պահեցէ՛ք ձեր սերունդների համար, որպէսզի աչքի առաջ ունենաք այն հացը, որ դուք կերաք անապատում, երբ Տէրը ձեզ հանեց Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Մովսէսն ասաց Ահարոնին. «Մի ոսկէ սափոր ա՛ռ, դրա մէջ մէկ չափ մանանայ լցրո՛ւ եւ դի՛ր Աստծու առաջ՝ պահելու ձեր սերունդների համար, ինչպէս Տէրն է հրամայել Մովսէսին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Եւ Ահարոնն այն ի պահ դրեց Կտակարանների արկղի առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Իսրայէլացիները քառասուն տարի մանանայ կերան, մինչեւ որ հասան մի բնակեցուած շրջան: Նրանք մանանայ էին ուտում, մինչեւ որ հասան փիւնիկեցիների կողմերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Մէկ չափը հաւասար է երեք գրիւի մէկ տասներորդ մասի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Իսրայէլացի ամբողջ ժողովուրդը Տիրոջ կարգադրութեան համաձայն խումբ-խումբ գնաց Սին անապատից եւ կայք հաստատեց Ռափիդիմում: Այստեղ, սակայն, ջուր չկար, որ ժողովուրդը խմէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Ժողովուրդն սկսեց մեղադրել Մովսէսին՝ ասելով. «Մեզ ջո՛ւր տուր, որ խմենք»: Մովսէսը նրանց ասաց. «Ինչո՞ւ էք ինձ մեղադրում, ինչո՞ւ էք փորձում Տիրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Ժողովուրդն այնտեղ ծարաւ զգալով՝ տրտնջաց Մովսէսի դէմ ու ասաց. «Ինչո՞ւ մեզ հանեցիր Եգիպտոսից, որ ծարաւից կոտորուե՞նք մենք եւ մեր երեխաներն ու անասունները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Մովսէսը պաղատագին խնդրելով Տիրոջը՝ ասաց. «Ի՞նչ անեմ ես այս ժողովրդին: Մի քիչ էլ մնայ՝ ինձ կը քարկոծեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Տէրն ասաց Մովսէսին. «Գնա՛ ժողովրդի առջեւից, քեզ հետ վերցրո՛ւ ժողովրդի ծերերին, ձեռքդ ա՛ռ քո այն գաւազանը, որով հարուածեցիր գետին, եւ ճամփայ ընկի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Ես քեզնից առաջ այնտեղ հասնելով՝ կը կանգնեմ Քորէբի ժայռի վրայ: Կը հարուածես ժայռին, դրանից ջուր կը բխի, եւ քո ժողովուրդը կը խմի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Մովսէսն իսրայէլացիների ներկայութեամբ այդպէս էլ արեց: Նա այդ վայրը կոչեց Փորձութիւն եւ Մեղադրանք, որովհետեւ իսրայէլացիները մեղադրել էին եւ Տիրոջը փորձել՝ ասելով. «Տէրը մեր մէ՞ջ է, թէ՞ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Ամաղէկացիներն եկան ու Ռափիդիմում պատերազմեցին իսրայէլացիների դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Մովսէսն ասաց Յեսուին. «Ուժեղ տղամարդիկ ընտրի՛ր եւ առաւօտեան վեր կենալով պատերազմի՛ր ամաղէկացիների դէմ: Ես կը գամ ու կը կանգնեմ բլրի գագաթին, եւ Աստծու գաւազանը կը լինի իմ ձեռքին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Յեսուն արեց այնպէս, ինչպէս իրեն ասել էր Մովսէսը. նա պատերազմեց ամաղէկացիների դէմ: Մովսէսը, Ահարոնն ու Ովրը բարձրացան բլրի գագաթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Երբ Մովսէսը բարձր էր պահում ձեռքերը, առաւելութեան էին հասնում իսրայէլացիները, իսկ երբ իջեցնում էր ձեռքերը, առաւելութեան էին հասնում ամաղէկացիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Եւ քանի որ Մովսէսի ձեռքերը յոգնելուց ծանրանում էին, Ահարոնն ու Ովրը մի քար առան եւ նրա տակը դրեցին: Մովսէսը նստեց դրա վրայ, իսկ Ահարոնն ու Ովրը՝ մէկն այս կողմից, միւսն այն կողմից նրա ձեռքերը բռնած բարձր էին պահում: Այսպիսով Մովսէսի ձեռքերը մինչեւ արեւի մայր մտն»լը բարձրացած մնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Յեսուն սրակոտոր արեց ամաղէկացիներին ու նրանց ողջ զօրքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Տէրն ասաց Մովսէսին. «Այս դէպքը որպէս յիշատակ գրի՛ առ: Հաղորդի՛ր Յեսուին, որ ամաղէկացիների յիշատակը ջնջելու եմ երկրի վրայ՝ երկնքի ներքոյ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Մովսէսը Տիրոջ համար զոհասեղան շինեց եւ դրա անունը դրեց՝ «Տէրն իմ ապաւէնն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Նա ասաց. «Այսպէս կոչեցի, քանի որ Տէրն իր անտեսանելի ձեռքով պատերազմում է ամաղէկացիների դէմ սերնդից սերունդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Մադիամի քուրմ Յոթորը՝ Մովսէսի աները, իմացաւ այն ամէնը, ինչ Տէրն արել էր Մովսէսին ու իսրայէլացի ժողովրդին. այն, որ Տէրը իսրայէլացիներին հանել էր Եգիպտոսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Երբ Մովսէսն իր կին Սեփորային յետ ուղարկեց, Մովսէսի աները՝ Յոթորը, իր հետ վերցրեց Սեփորային');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'ու նրա երկու որդիներին, որոնցից մէկի անունը Գերսամ էր եւ նշանակում էր՝ «Պանդուխտ էի օտար երկրում»,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'իսկ երկրորդի անունը՝ Եղիազար, որ նշանակում էր՝ «Իմ հօր Աստուածը իմ օգնականն է եւ նա փրկեց ինձ փարաւոնի ձեռքից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Յոթորը, որ Մովսէսի աներն էր, նրա կնոջ եւ նրա որդիների հետ եկաւ Մովսէսի մօտ՝ անապատ, ուր նա բնակւում էր Աստծու լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Յայտնեցին Մովսէսին՝ ասելով. «Ահա քո աներ Յոթորը, կինդ ու երկու որդիներդ նրա հետ գալիս են քեզ մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Մովսէսն ընդառաջ գնաց իր աներոջը, ծնրադրեց նրա առաջ եւ համբուրեց նրան: Նրանք ողջագուրուեցին խաղաղութեամբ, եւ Մովսէսը նրան տարաւ իր վրանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Մովսէսն իր աներոջը պատմեց այն ամէնը, ինչ իսրայէլացիների համար Տէրն արել էր փարաւոնի ու եգիպտացիների դէմ, բոլոր այն չարչարանքները, որ իրենք կրել էին ճանապարհին, եւ թէ ինչպէս էր Տէրը փրկել իրենց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Յոթորը զարմացաւ այն բոլոր բարեգործութիւնների համար, որ Տէրն արել էր նրանց, եւ թէ ինչպէս էր նրանց ազատել եգիպտացիների ու փարաւոնի ձեռքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Յոթորն ասաց. «Օրհնեալ լինի Տէրը, որ փրկել է սրանց եգիպտացիների ու փարաւոնի ձեռքից, որ ժողովրդին ազատել է եգիպտացիների ձեռքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Հիմա գիտեմ, որ Տէրն աւելի մեծ է, քան բոլոր աստուածները: Դա երեւաց, երբ եգիպտացիները բռնանում էին նրանց վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Մովսէսի աները՝ Յոթորը, ողջակէզ ու զոհ մատուցեց Աստծուն: Մովսէսը, Ահարոնն ու իսրայէլացի բոլոր ծերերը Մովսէսի աներոջ հետ գնացին Տիրոջ առաջ ճաշելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Առաւօտեան Մովսէսը նստեց ժողովրդին դատելու: Ողջ ժողովուրդը առաւօտից մինչեւ երեկոյ կանգնել էր Մովսէսի շուրջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Յոթորը տեսնելով այն ամէնը, ինչ Մովսէսն անում էր ժողովրդի համար, ասաց. «Այդ ի՞նչ ես անում դու ժողովրդին: Ինչո՞ւ ես դու միայն նստած, իսկ ժողովուրդը առաւօտից մինչեւ երեկոյ կանգնած է շուրջդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Մովսէսն ասաց աներոջը. «Որովհետեւ ժողովուրդը գալիս է ինձ մօտ Աստծուց իրաւունք հայցելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Երբ նրանց միջեւ վէճ է ծագում, գալիս են ինձ մօտ: Ես դատում եմ նրանցից իւրաքանչիւրին եւ յայտնում Աստծու հրամաններն ու օրէնքները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Մովսէսի աները նրան ասաց. «Արածդ ճիշտ չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Սոսկալի տանջանքներով ես տանջւում դու եւ քեզ հետ եղող ամբողջ ժողովուրդը: Քեզ համար ծանր է այդ գործը, դա միայնակ անել չես կարող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Արդ, լսի՛ր ինձ, ես քեզ խորհուրդ պիտի տամ, եւ Աստուած քեզ հետ կը լինի: Աստծու մօտ եղի՛ր ժողովրդի ներկայացուցիչը եւ մարդկանց ասածը հաղորդի՛ր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Նրանց տեղեակ կը պահես Աստծու հրամաններին ու օրէնքներին, նրանց ցոյց կը տաս այն ճանապարհը, որով ընթանալու են, եւ այն գործերը, որ պէտք է կատարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Դու ողջ ժողովրդի միջից ընտրի՛ր ուժեղ տղամարդկանց՝ աստուածապաշտ, արդարադատ, գոռոզութիւնն ատող մարդկանց ու ժողովրդի վրայ սրանց հազարապետներ, հարիւրապետներ, յիսնապետներ ու տասնապետներ կարգի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Նրանք մշտապէս թող դատեն ժողովրդին, կարեւոր գործերը թող յանձնեն քեզ, իսկ փոքր դատաստանները թող անեն իրենք. դրանով կը թեթեւացնես քո գործերը, եւ նրանք կը լինեն քո օգնականները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Եթէ այս բանն անես, Աստուած կը զօրացնի քեզ, դու կը կարողանաս տոկալ, եւ ողջ ժողովուրդը խաղաղութեամբ կը վերադառնայ իր տեղը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Մովսէսն անսաց իր աներոջ ասածին եւ արեց այն ամէնը, ինչ նա ասաց իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Մովսէսը բոլոր իսրայէլացիների միջից ընտրեց ուժեղ տղամարդկանց, ժողովրդի վրայ նրանց հազարապետներ, հարիւրապետներ, յիսնապետներ ու տասնապետներ կարգեց: Սրանք ամբողջ ժամանակ պատրաստ էին ժողովրդին դատելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Նրանք կարեւոր գործերը յանձնում էին Մովսէսին, իսկ փոքր գործերը դատում էին իրենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Մովսէսը ճանապարհ դրեց իր աներոջը, եւ սա գնաց իր երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Եգիպտացիների երկրից իսրայէլացիների դուրս գալուց երեք ամիս անց, առաջին իսկ օրը նրանք հասան Սինայի անապատը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Նրանք դուրս գալով Ռափիդիմից, եկան Սինայի անապատը եւ կայք հաստատեցին այնտեղ, անապատում: Իսրայէլացիները կայք հաստատեցին այնտեղ, լերան դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Մովսէսը բարձրացաւ Աստծու լեռը: Աստուած լերան վրայից կանչեց նրան ու ասաց. «Այսպէս կ՚ասես Յակոբի յետնորդներին եւ կը յայտնես Իսրայէլի որդիներին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '«Դուք ինքներդ տեսաք, թէ ինչեր բերեցի եգիպտացիների գլխին, իսկ ձեզ, ինչպէս արծիւն է իր թեւերի վրայ առնում, բարձրացրի ինձ մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Արդ, եթէ ուշադիր լսէք իմ ասածը եւ պահէք իմ դրած ուխտը, դուք բոլոր ազգերի մէջ կը լինէք իմ ընտրեալ ժողովուրդը, որովհետեւ իմն է ամբողջ երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Դուք կը լինէք ինձ համար որպէս թագաւորութիւն, որպէս քահանայութիւն եւ որպէս սուրբ ազգ: Իմ այս ասածները դու կը հաղորդես իսրայէլացիներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Մովսէսը վերադարձաւ, կանչեց ժողովրդի ծերերին եւ նրանց հաղորդեց բոլոր այն խօսքերը, որ նրան պատուիրել էր Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Ժողովուրդը միահամուռ պատասխան տուեց ու ասաց. «Այն ամէնը, ինչ ասել է Աստուած, կը կատարենք ու կը հնազանդուենք»: Մովսէսը ժողովրդի ասածը հաղորդեց Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Տէրն ասաց Մովսէսին. «Ահա ես քեզ մօտ պիտի գամ ամպի սեան մէջ, որ ժողովուրդը լսի այն, ինչ ես ասելու եմ քեզ, եւ նա յաւիտեան պիտի հաւատայ քեզ»: Մովսէսը ժողովրդի ասածը հաղորդեց Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Տէրն ասաց Մովսէսին. «Իջի՛ր, կարգադրի՛ր ժողովրդին, մաքրի՛ր նրանց այսօր եւ վաղը, նաեւ թող լուանան իրենց զգեստները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'որպէսզի երրորդ օրը պատրաստ լինեն, որովհետեւ երրորդ օրը Տէրը ողջ ժողովրդի աչքի առաջ իջնելու է Սինա լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Ժողովրդի ու լերան միջեւ տարածութիւն կը թողնես եւ կ՚ասես. «Զգո՛յշ եղէք, լերան վրայ մարդ չբարձրանայ ու դրան չմօտենայ, որովհետեւ ով մօտենայ լերան, մահուամբ պիտի պատժուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Լերան մօտեցողին որեւէ ձեռք չդիպչի, որովհետեւ դրան դիպչողը կը քարկոծուի կամ նետահար կը լինի. անասուն լինի, թէ մարդ՝ չի ապրի: Նրանք կարող են լեռը բարձրանալ միայն այն ժամանակ, երբ որոտները, շեփորահարութիւնն ու ամպը վերանան լերան վրայից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Մովսէսը լեռից իջաւ ժողովրդի մօտ ու մաքրեց նրանց: Նրանք լուացին իրենց զգեստները: Մովսէսն ասաց ժողովրդին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, '«Պատրա՛ստ եղէք, երեք օր կանանց չմերձենաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Երրորդ օրն առաւօտեան Սինա լերան վրայ որոտներ լսուեցին, փայլատակումներ ու միգախառն ամպ երեւաց. եւ շեփորի ձայնը ուժգին հնչում էր: Բանակատեղում գտնուող ողջ ժողովուրդը զարհուրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Մովսէսը ժողովրդին բանակատեղիից տարաւ Աստծուն ընդառաջ եւ կանգնեցրեց Սինա լերան ստորոտի շուրջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Սինա լեռն ամբողջովին ծխում էր, քանի որ Աստուած նրա վրայ իջել էր իբրեւ հուր: Նրա ծուխը բարձրանում էր ինչպէս հնոցի ծուխ: Բոլոր մարդիկ խիստ զարհուրեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'որովհետեւ շեփորի ձայնը տարածւում էր աւելի հեռու եւ հնչում էր չափազանց ուժեղ: Մովսէսը խօսում էր, իսկ Աստուած որոտաձայն պատասխանում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Տէրն իջաւ Սինա լերան վրայ, լերան կատարին: Տէրը Մովսէսին կանչեց լերան գագաթը, եւ Մովսէսը բարձրացաւ այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Աստուած խօսեց Մովսէսի հետ՝ ասելով. «Իջի՛ր, կարգադրի՛ր քո ժողովրդին. Աստծուն տեսնելու համար չմերձենան եւ այդ պատճառով նրանցից շատերը չկորչեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Աստծուն մօտեցող քահանաներն էլ թող մաքրուեն, որպէսզի Տէրը կորստեան չմատնի նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Մովսէսն ասաց Աստծուն. «Ժողովուրդը չի կարող Սինա լեռը բարձրանալ, որովհետեւ դու ինքդ ես մեզ պատուիրել եւ ասել, թէ՝ «Մարդկանց ու լերան միջեւ տարածութիւն կը թողնես եւ լեռը սուրբ կը հռչակես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Տէրն ասաց նրան. «Գնա՛, իջի՛ր ու յետոյ այստեղ բարձրացի՛ր Ահարոնի հետ, բայց քահանաներն ու ժողովուրդը թող չյանդգնեն բարձրանալ Աստծու մօտ, որպէսզի Տէրը նրանց կորստեան չմատնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Մովսէսն իջաւ ժողովրդի մօտ եւ ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Տէրը յայտնեց հետեւեալ բոլոր պատգամները՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '«Ե՛ս եմ քո Տէր Աստուածը, որ քեզ հանեցի Եգիպտացիների երկրից՝ ստրկութեան տնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Ինձնից բացի այլ աստուածներ չպիտի լինեն քեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Վերեւում՝ երկնքում, ներքեւում՝ երկրի վրայ, եւ երկրի խորքի ջրերի մէջ եղած որեւէ բանի նմանութեամբ քեզ կուռքեր չպիտի կերտես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Չպիտի երկրպագես ու չպիտի պաշտես դրանց, որովհետեւ ե՛ս եմ քո Տէր Աստուածը՝ մի նախանձոտ Աստուած. հայրերի մեղքերի համար պատժում եմ որդիներին, ինձ ատող մարդկանց նոյնիսկ երրորդ ու չորրորդ սերնդին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'իսկ ինձ սիրող ու իմ հրամանը կատարող մարդկանց մինչեւ հազարերորդ սերնդին ողորմում եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Քո տէր Աստծու անունն զուր տեղը չպիտի արտասանես, որովհետեւ Տէրը արդար չի համարում նրան, ով իր անունը զուր տեղն է արտասանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Յիշի՛ր շաբաթ օրը, որպէսզի սուրբ պահես այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Վեց օր պիտի աշխատես եւ պիտի կատարես քո բոլոր գործերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Եօթներորդ օրը քո տէր Աստծու շաբաթ օրն է: Այդ օրը դու ոչ մի գործ չպիտի անես, ոչ էլ քո տղան ու աղջիկը, քո ծառան ու քո աղախինը, քո էշն ու քո եզը, քո բոլոր անասունները, քեզ մօտ գտնուող օտարականն ու քեզ մօտ բնակուող պանդուխտը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'որովհետեւ Տէր Աստուած վեց օրում ստեղծեց երկինքն ու երկիրը, ծովն ու այն ամէնը, ինչ դրանց մէջ է, իսկ եօթներորդ օրը հանգստացաւ: Դրա համար էլ Տէրն օրհնեց եօթներորդ օրը եւ այն սուրբ հռչակեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Պատուի՛ր քո հօրն ու քո մօրը, որպէսզի բարիք գտնես, երկար ապրես բարեբեր այն երկրի վրայ, որ Տէր Աստուած տալու է քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Մի՛ սպանիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Մի՛ շնացիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Մի՛ գողացիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Քո հարեւանի դէմ սուտ վկայութիւն մի՛ տուր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ո՛չ քո մերձաւորի տան, ո՛չ նրա ագարակի վրայ աչք մի՛ ունեցիր: Ո՛չ քո մերձաւորի կնոջ վրայ, ո՛չ նրա ծառայի վրայ, ո՛չ նրա աղախնու վրայ, ո՛չ նրա եզան վրայ, ո՛չ նրա էշի վրայ, ո՛չ նրա անասունի վրայ, ո՛չ այն ամենի վրայ, ինչ քո մերձաւորինն է, աչք մի՛ ունեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Ողջ ժողովուրդը լսում էր որոտը, շեփորի ձայնը, տեսնում փայլատակումներն ու ծխացող լեռը: Ողջ ժողովուրդը զարհուրեց, ընկրկեց ու կանգնեց հեռու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Մարդիկ ասացին Մովսէսին. «Դո՛ւ խօսիր մեզ հետ, եւ մենք կը հնազանդուենք: Աստուած թող չխօսի մեզ հետ, թէ չէ կարող ենք մեռնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Մովսէսն ասաց նրանց. «Սրտապնդուեցէ՛ք, որովհետեւ Աստուած ձեզ փորձելու համար եկաւ ձեզ մօտ, որպէսզի նրա երկիւղը լինի ձեր մէջ, եւ դուք մեղք չգործէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Ժողովուրդը լեռից հեռու էր կանգնած, իսկ Մովսէսը մտաւ մառախուղի մէջ, ուր գտնւում էր Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Տէրն ասաց Մովսէսին. «Այսպէս կ՚ասես Յակոբի սերնդին եւ կը հաղորդես Իսրայէլի որդիներին. «Դուք ինքներդ տեսաք, որ ես երկնքից խօսեցի ձեզ հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ձեզ համար ոսկէ ու արծաթէ աստուածներ չպատրաստէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Ինձ համար հողաշէն զոհասեղան կը պատրաստէք եւ դրա վրայ, ամէն տեղ, ուր կը դնեմ իմ անունը, կը մատուցէք ձեր ողջակէզներն ու ձեր խաղաղութեան զոհերը, ձեր ոչխարներն ու ձեր արջառները: Ես կը գամ քեզ մօտ ու կ՚օրհնեմ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Իսկ եթէ զոհասեղանը քարից կառուցես, դրա քարերը յղկուած թող չլինեն, որովհետեւ եթէ քո ձեռքի գործիքը դիպցնես դրան, ապա դա պղծուած կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Իմ զոհասեղանի վրայ աստիճաններով չբարձրանաս, որպէսզի դրա վրայ քո ամօթոյքը չերեւայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '«Սրանք են այն կանոնները, որ պիտի յայտնես նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Եթէ գնես եբրայեցի մի ստրուկ, վեց տարի նա թող ծառայի քեզ եւ եօթներորդ տարում առանց փրկագնի ազատ թող արձակուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Եթէ նա միայնակ է տունդ մտել, միայնակ էլ թող գնայ, իսկ եթէ իր կնոջ հետ է մտել, կինն էլ թող գնայ նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Եթէ իր տէրը նրան կին տայ, եւ կինը նրա համար տղաներ եւ աղջիկներ ծնի, ապա կինն ու զաւակները թող պատկանեն նրա տիրոջը, իսկ նա թող գնայ միայնակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Եթէ ստրուկն առարկելով ասի, թէ՝ «Սիրեցի իմ տիրոջը, իմ կնոջն ու իմ զաւակներին եւ ազատութիւն չեմ ուզում», ապա նրա տէրը նրան թող կանգնեցնի Աստծու ատեանին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'այնուհետեւ բերի իր տան դռան սեմի մօտ, հերիւնով ծակի նրա ականջը, եւ նա նրան թող ծառայի ցմահ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Եթէ որեւէ մէկն իր աղջկան որպէս աղախին վաճառի, ապա այդ աղջիկը թող չազատագրուի, ինչպէս ազատագրւում են ստրկուհիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Եթէ այդ աղախինը, որը սահմանուած էր իր տիրոջ համար, այլեւս հաճելի չլինի նրան, ապա Տէրը թող փրկագնով վաճառի նրան, բայց օտարազգի մարդու վաճառելու իրաւունք չունի, թէ չէ նրան անարգած կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Եթէ նա իր գնած աղախնին սահմանել է իր որդու համար, նրա հետ թող վարուի այնպէս, ինչպէս վարւում է իր դուստրերի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Եթէ ամուսնացած մի մարդ ամուսնանայ նաեւ մի ուրիշ կնոջ հետ, թող չզրկի նախկին կնոջը գոյութեան միջոցներից, զգեստներից ու ամուսնական պարտականութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Եթէ ամուսինն այս երեք պահանջները չկատարի նրա նկատմամբ, ապա կինն առանց փրկագնի՝ ձրի, ազատ թող արձակուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '«Եթէ որեւէ մարդ հարուածի մէկին, եւ սա մահանայ, ապա հարուածողը մահապատժի թող ենթարկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Եթէ սպանութիւնը կատարուել է ոչ թէ սպանողի կամքով, այլ Աստուած է մատնել նրան նրա ձեռքը, ապա սպանողին թող ցոյց տրուի մի տեղ, ուր նա ապաստան թող գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Եթէ մէկը չարանենգօրէն սպանի իր մերձաւորին եւ փախուստի դիմելով ապաստանի իմ զոհասեղանին, դարձեալ կ՚առնես նրան ու կը սպանես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Ով որ հարուածի իր հօրը կամ մօրը, մահապատժի թող ենթարկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Եթէ մէկը գողանայ մի իսրայէլացու եւ վաճառի, եւ կամ իր մօտ գտնեն նրան, ապա սա մահապատժի թող ենթարկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Ով որ վատաբանի իր հօրն ու իր մօրը, մահապատժի թող ենթարկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Եթէ երկու մարդիկ կռուեն, եւ նրանցից մէկը քարով կամ բռունցքով հարուածի միւսին, եւ սա ոչ թէ մահանայ, այլ անկողին ընկնի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'ապա եթէ տուժածը ոտքի կանգնի եւ կարողանայ ցուպի օգնութեամբ քայլել, հարուածողը թող անպարտ լինի, բայց տուժածի աշխատանքից զրկուելու վնասի ու բժշկութեան համար թող հատուցում վճարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Եթէ մէկը գաւազանով հարուածի իր ստրուկին կամ իր ստրկուհուն, եւ սրանք մեռնեն նրա հարուածից, ապա տէրը վրէժխնդրութեան պիտի ենթարկուի դատաստանով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'իսկ եթէ նրանք մէկ կամ երկու օր ապրեն, տէրը վրէժխնդրութեան չի ենթարկուի, քանի որ նա նրանց իր արծաթով է գնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Եթէ երկու տղամարդիկ կռուելիս զարնուեն մի յղի կնոջ, եւ կինը պտուղը դեռ չձեւաւորուած վիժի, հարուածողը թող հատուցի վնասը. ինչ որ պահանջի կնոջ ամուսինը, նա թող վճարի ըստ սահմանուած կարգի եւ տայ աղաչելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Իսկ եթէ պտուղը ձեւաւորուած լինի, ապա թող հատուցի ըստ այս կարգի. կեանքի դիմաց՝ կեանք, աչքի դիմաց՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'աչք, ատամի դիմաց՝ ատամ, ձեռքի դիմաց՝ ձեռք, ոտքի դիմաց՝ ոտք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'խարանի դիմաց՝ խարան, վէրքի դիմաց՝ վէրք, հարուածի դիմաց՝ հարուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Եթէ մէկը հարուածի իր ստրկի կամ իր ստրկուհու աչքին ու կուրացնի նրան, ապա իր կուրացրած աչքի համար նրանց ազատ թող արձակի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Եթէ ջարդի իր ստրկի կամ ստրկուհու ատամը, ապա իր ջարդած ատամի համար նրանց ազատ թող արձակի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '«Եթէ մի ցուլ հարուածի մի տղամարդու կամ կնոջ, եւ սրանք մեռնեն, ապա ցուլը թող քարկոծուի, նրա միսը թող չուտեն, իսկ ցուլի տէրը անպարտ թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Եթէ ցուլը նախկինում եւս հարուածող է եղել, եւ այդ առթիւ նրա տիրոջը բողոքած են եղել, բայց սա ցուլին մէջտեղից չի վերացրել, եւ եթէ ցուլը տղամարդ կամ կին սպանի, ապա ցուլը թող քարկոծուի, իսկ ցուլի տէրը միաժամանակ մահապատժի թող ենթարկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Իսկ եթէ տիրոջ վրայ փրկագին նշանակուի, ապա իր խլած կեանքի դիմաց տէրը թող վճարի նշանակուած փրկագինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Եթէ ցուլը մի տղայի կամ մի աղջկայ հարուածի, նոյն կերպ թող վարուեն նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Եթէ ցուլը մի ստրուկի կամ ստրկուհու հարուածի, ցլատէրը նրանց տիրոջը երեսուն սիկղ արծաթ թող վճարի, իսկ ցուլը թող քարկոծուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Եթէ մէկը փոս բացելուց կամ ջրհոր փորելուց յետոյ դրանք չծածկի, եւ դրանց մէջ արջառ կամ էշ ընկնի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'փոսի տէրը արծաթ թող վճարի անասունի տիրոջը, իսկ լէշը թող յանձնուի իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Եթէ մէկի ցուլը հարուածի մի ուրիշ մարդու ցուլին, եւ սա սատկի, կենդանի մնացած ցուլը թող վաճառեն եւ դրա արժէքը թող բաժանեն: Թող բաժանեն նաեւ սպանուած ցուլը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Իսկ եթէ նախկինում էլ գիտէին, որ ցուլը հարուածող է եղել, եւ այդ մասին դրա տիրոջը բողոքած են եղել, բայց նա իր ցուլը մէջտեղից չի վերացրել, թող ցուլ հատուցուի ցուլի փոխարէն, իսկ սպանուած ցուլը թող տրուի տիրոջը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, '«Եթէ մէկը արջառ կամ ոչխար գողանայ, մորթի կամ վաճառի այն, ապա մէկ արջառի փոխարէն հինգ արջառ թող հատուցի, իսկ մէկ ոչխարի փոխարէն՝ չորս ոչխար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Եթէ գողին մահացու հարուած հասցնեն տան պատին անցք բացելիս, թող դա սպանութիւն չդիտուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Իսկ եթէ դէպքը արեւածագից յետոյ կատարուի, սպանողը մահապարտ կը դիտուի եւ մահուան կ՚ենթարկուի: Եթէ գողը հատուցելու ոչինչ չունի, ապա ինքը թող վաճառուի, որպէսզի հատուցի իր գողացածի փոխարէն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Իսկ եթէ նա բռնուի, եւ գողօնը՝ արջառ, էշ եւ ոչխար, գտնուի իր մօտ, ապա նա կրկնակին թող հատուցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Եթէ մէկն իր անասունն արածեցնելիս թոյլ է տալիս, որ անասունն արածի ուրիշի հանդում, ապա իր հանդից թող հատուցի ըստ փչացրած բերքի չափի: Իսկ եթէ հանդը փչացրել է ամբողջութեամբ, ապա թող հատուցի իր հանդի ու իր այգու ընտիր հատուածով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Եթէ մէկը իր հանդի փշերը վառելու համար կրակ անի, եւ նրա վառած կրակը տարածուի ու այրի մէկ ուրիշի կալը կամ ցորենի շեղջը կամ հանդը, ապա վնասը թող հատուցի նա, ով հրդեհի համար մեղաւոր է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Եթէ մէկը մի մարդու արծաթ կամ որեւէ այլ իր տայ պահելու, եւ այն գողացուի այդ մարդու տնից, եթէ գողը գտնուի, թող կրկնակին հատուցի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'իսկ եթէ գողը չգտնուի, ապա տան տէրը թող Աստծու առաջ երդուի, որ ինքն ամենեւին չի իւրացրել այդ մարդու իրեն պահ տուած իրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Արջառի ու էշի, ոչխարի ու հագուստի եւ ամէն տեսակ բաների կորուստներին վերաբերող եւ վէճ յարուցող խնդիրների իսկութիւնը պարզելու նպատակով երկու կողմերը թող կանգնեն Աստծու դատաստանի առաջ: Նրանցից ում որ Աստուած մեղաւոր ճանաչի, նա կրկնակին թող հատուցի միւսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Եթէ մէկը մի մարդու էշ, եզ, ոչխար կամ որեւէ այլ անասուն ի պահ տայ եւ պահ տրուածը վնասուածք ստանայ, սատկի կամ յափշտակուի, եւ այդ բանը հաստատող ոչ մի վկայ չլինի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'ապա երկուսի միջեւ թող Աստծուն տրուած երդումը որպէս վկայութիւն լինի: Նա, ում մօտ անասունը պահ է տրուած եղել, եթէ երդուի, որ երբեք նենգ մտադրութիւն չի ունեցել միւսի տուած աւանդի նկատմամբ, ապա տէրը թող բաւարարուի դրանով, իսկ պահողը թող չտուգանուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Իսկ եթէ ապացուցուի, որ իրօք իր մօտից են գողացել, ապրանքի տիրոջը թող հատուցի վնասը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Իսկ եթէ պահ տրուած անասունին մի գազան է յօշոտել, որպէս ապացոյց նա թող բերի անասունի լէշը եւ վնասը չհատուցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Եթէ մէկը մի իր կամ անասուն խնդրի մէկ ուրիշից, եւ դրանք ջարդուեն, սատկեն կամ յափշտակուեն, իսկ տէրը դրանց մօտ ներկայ չլինի, ապա աւանդը վերցնողը թող հատուցի վնասը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Եթէ դէպքը կատարուելիս տէրը աւանդի մօտ ներկայ լինի, աւանդ վերցնողը վնասը թող չհատուցի: Եթէ դա վարձով է փոխ առել, վնասն այդ վարձով էլ թող հատուցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, '«Եթէ մէկը խաբի չնշանուած մի կոյսի եւ պառկի նրա հետ, գլխագին թող վճարի ու ամուսնանայ նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Եւ եթէ աղջկայ հայրը չհամաձայնի նրան կնութեան տալ իր աղջկան, խաբողը նրա հօրը արծաթ թող վճարի այնքան, ինչքան գլխագին է սահմանուած կոյսերի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Մի՛ թողէք, որ կախարդներն ապրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Ով որ կենակցի անասունի հետ, նրան մահապատժի ենթարկեցէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Ով որ կուռքերին զոհ մատուցի, մահապատժի թող ենթարկուի: Զոհ մատուցեցէ՛ք միայն Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Պանդուխտին մի՛ չարչարէք, մի՛ նեղէք նրան, որովհետեւ դուք եւս պանդուխտ էիք Եգիպտացիների երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Ոչ մի այրի կնոջ կամ որբի մի՛ տանջէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Եթէ տանջէք նրանց, եւ նրանք բողոք բարձրացնելով դիմեն ինձ, ես կը լսեմ նրանց ձայնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'սաստիկ կը բարկանամ, սրակոտոր կ՚անեմ ձեզ, ձեր կանայք կ՚այրիանան, իսկ ձեր զաւակները որբ կը դառնան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Եթէ արծաթ ես փոխ տալիս աղքատ եղբօրդ, նեղը մի՛ գցիր նրան եւ տոկոսներ մի՛ պահանջիր նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Եթէ գրաւ վերցնես մէկի բաճկոնը, մինչեւ արեւի մայր մտնելը վերադարձրո՛ւ այն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'որովհետեւ դա նրա եւ՛ վերարկուն է, եւ՛ նրա մերկութիւնը ծածկող հանդերձը, որով եւ նա քնում է: Եւ եթէ նա բողոքի ինձ, ես կը լսեմ նրան, որովհետեւ ողորմած եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Քո աստուածներին մի՛ վատաբանիր եւ քո ժողովրդի առաջնորդին մի՛ հայհոյիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Քո կալի ու հնձանի արդիւնքը մի՛ կտրիր ինձնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Քո որդիներից անդրանիկներին ինձ կը նուիրաբերես: Նոյն կերպ կը վարուես քո արջառի, ոչխարի ու էշի առաջնածինների հետ: Դրանք եօթը օր թող մնան իրենց մօր մօտ, իսկ ութերորդ օրը դրանք կը նուիրաբերես ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Իմ այս ասածները կատարելով՝ դուք ինձ համար սուրբ մարդիկ կը լինէք: Գազանի յօշոտած կենդանու միս մի՛ կերէք, այլ շա՛նը նետեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '«Ականջ մի՛ դիր սուտ լուրերին:Յանձն մի՛ առ յօգուտ անիրաւի անիրաւ վկայ լինել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Մեծամասնութեանը հետեւելով՝ չար գործերի յետեւից մի՛ ընկիր: Բազմութեանը մի՛ խառնուիր՝ անիրաւութիւն գործելու համար նրան ենթարկուելով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'եւ դատի տակ ընկածին յանիրաւի մի՛ խղճա դատաստանի ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Եթէ հանդիպես քո թշնամու մոլորուած եզան կամ էշին, դրան կը դարձնես ու կը հասցնես իր տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Եթէ տեսնես, որ մէկի գրաստը բեռան ծանրութեան տակ ընկել է, նրա կողքից անտարբեր մի՛ անցիր, այլ նրան օգնելով բարձրացրո՛ւ այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Մի՛ շեղիր դատի ընթացքը, եթէ նոյնիսկ դատուողը քո ծանօթն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Հեռու կը մնաս ամէն տեսակ անիրաւ գործերից: Մահուան չդատապարտես անպարտին ու արդարին: Մեղաւորին կաշառուելով չարդարացնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Կաշառք չվերցնես, որովհետեւ կաշառքը կուրացնում է անգամ պայծառատեսների աչքերը եւ աւերում արդար գործերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Պանդուխտին մի՛ ճնշիր. դուք գիտէք պանդուխտ մարդկանց վիճակը, որովհետեւ դուք եւս պանդուխտ էիք Եգիպտացիների երկրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '«Վեց տարի կը մշակես քո հողը եւ կը հաւաքես դրա բերքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Եօթներորդ տարում չես մշակի այն եւ կը թողնես, որ հանգստանայ: Քո ցեղի աղքատները թող ուտեն ինքնաբոյս բերքը, իսկ դրանից աւելացածները թող ուտեն վայրի գազանները: Այդպէս կը վարուես քո այգու եւ քո ձիթաստանի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Վեց օր կ՚աշխատես, իսկ եօթներորդ օրը կը թողնես, որ հանգստանան քո եզն ու էշը, հանգստանան նաեւ քո աղախնու եւ օտարականի որդիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Ինչ որ ասացի ձեզ, կը կատարէք: Օտար աստուածներ մի՛ պաշտէք, նրանց անունները ձեր բերանից չլսուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, '«Տարուայ մէջ երեք անգամ ինձ համար տօն կը կատարէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Բաղարջակերաց տօնը կը պահէք: Նոր բերքի ամսին եօթը օր բաղարջ հաց կ՚ուտէք, ինչպէս պատուիրել եմ ձեզ, որովհետեւ դուք ա՛յդ ժամանակ ելաք Եգիպտացիների երկրից: Իմ առաջ դատարկաձեռն չերեւաս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Ինչ էլ որ ցանած լինես քո հանդում, կը կատարես ամառուայ քո առաջին բերքը քաղելու տօնը: Տօն կը կատարես նաեւ տարուայ վերջում, երբ հանդից հաւաքած կը լինես քո բերքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Քո ժողովրդի բոլոր արու զաւակները տարուայ մէջ երեք անգամ պէտք է ներկայանան տէր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Քո արած զոհաբերութեան արիւնը թթխմորով հացի վրայ չթափես, եւ իմ տօնին արուած զոհաբերութեան ճարպը մինչեւ առաւօտ չպահես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Քո առաջին բերքի արդիւնքը կը բերես քո տէր Աստծու տունը: Գառը իր մօր կաթի մէջ չեփես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '«Եւ ահա ես իմ հրեշտակին ուղարկում եմ քեզ մօտ, որպէսզի նա քո առաջից գնալով՝ քեզ պահպանի ճանապարհին ու տանի այն երկիրը, որ պատրաստեցի քեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Զգո՛յշ եղիր անձիդ նկատմամբ, լսի՛ր ու հնազանդուի՛ր նրան, որպէսզի նա չխորշի քեզնից, որովհետեւ նա իմ անունով է գործելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Եթէ ուշադիր լսես իմ խօսքը եւ կատարես այն ամէնը, ինչ ասել եմ քեզ, ես կը լինեմ քո թշնամիների թշնամին եւ կը դառնամ քո հակառակորդների հակառակորդը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'որովհետեւ իմ հրեշտակը քեզ առաջնորդ կը լինի, քեզ կը տանի ամորհացիների, քետացիների, փերեզացիների, քանանացիների, գերգեսացիների, խեւացիների ու յեբուսացիների մօտ, որոնց ես կոտորելու եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Չերկրպագես նրանց աստուածներին, չպաշտես նրանց եւ չկատարես այն, ինչ նրանք են կատարում, այլ քարուքա՛նդ արա դրանք եւ ջարդիր փշրի՛ր նրանց յուշարձանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Պաշտի՛ր քո տէր Աստծուն, եւ ես կ՚օրհնեմ քո հացն ու ջուրը եւ ձեզնից կը վանեմ հիւանդութիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Քո երկրում անսեռունակ տղամարդ եւ ամուլ կին չեն լինելու: Ես աւելացնելու եմ քո կեանքի տարիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Ես պիտի ուղարկեմ իմ ահը, որ դա առաջնորդի քեզ, պիտի սարսափեցնեմ բոլոր այն ազգերին, որոնց երկիրը ոտք պիտի դնես: Քո բոլոր հակառակորդներին փախուստի պիտի մատնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Քո առաջից իշամեղուներ պիտի ուղարկեմ, որ քեզնից հեռու քշեն ամորհացիներին, խեւացիներին, քանանացիներին ու քետացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Մի տարուայ ընթացքում չէ, որ պիտի հեռացնեմ նրանց քեզնից, որպէսզի երկիրը անապատի չվերածուի, եւ քո շրջակայքում չբազմանան երկրի գազանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Կամաց-կամաց պիտի հեռացնեմ դրանց քեզնից, մինչեւ որ բազմանաս ու ժառանգես երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Քո երկրի տարածքը սահմանելու եմ Կարմիր ծովից մինչեւ Փղշտացիների ծովը եւ անապատից մինչեւ Եփրատ մեծ գետը: Ձեր ձեռքը պիտի յանձնեմ այդ երկրի բնակիչներին ու նրանց հեռու պիտի քշեմ քեզնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Դու նրանց ու նրանց չաստուածների հետ ուխտ չդնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Նրանք քո երկրում չպիտի բնակուեն, որպէսզի իմ նկատմամբ յանցանքի չմղեն քեզ, որովհետեւ, եթէ ծառայես նրանց չաստուածներին, նրանք գայթակղութիւն կը լինեն քեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Աստուած ասաց Մովսէսին. «Բարձրացէ՛ք Տիրոջ մօտ դու, Ահարոնը, Նաբադը, Աբիուդն ու Իսրայէլի ծերերից եօթանասուն տղամարդ: Նրանք Տիրոջը թող երկրպագեն հեռուից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Աստծուն թող մօտենայ միայն Մովսէսը, իսկ միւսները թող չմօտենան: Ժողովուրդը նրանց հետ թող չբարձրանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Մովսէսն եկաւ ու ժողովրդին յայտնեց Աստծու բոլոր պատգամներն ու կանոնները: Ողջ ժողովուրդը միաձայն պատասխան տուեց ու ասաց. «Կը կատարենք բոլոր այն պատգամները, որ տուել է Տէրը, կ՚ենթարկուենք դրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Մովսէսը գրի առաւ Տիրոջ բոլոր պատգամները: Մովսէսն առաւօտեան վեր կենալով՝ զոհասեղան կառուցեց լերան ստորոտին եւ տասներկու վէմ կանգնեցրեց՝ ըստ Իսրայէլի տասներկու ցեղերի թուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Նա ուղարկեց իսրայէլացի երիտասարդներ, որոնք ողջակէզներ մատուցեցին, փրկութեան համար Աստծուն հորթեր զոհաբերեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Մովսէսն առնելով զոհերի արեան կէսը՝ լցրեց ամանների մէջ, իսկ արեան միւս կէսը հեղեց զոհասեղանի առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Նա, վերցնելով ուխտի գիրքը, կարդաց ի լուր ժողովրդի: Ժողովուրդն ասաց. «Այն ամէնը, ինչ ասել է Տէրը, կը կատարենք, կ՚ենթարկուենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Մովսէսը, վերցնելով արիւնը, շաղ տուեց ժողովրդի վրայ ու ասաց. «Սա այն ուխտի արիւնն է, որ կնքեց Տէրը ձեզ հետ, որպէսզի կատարէք նրա բոլոր պատգամները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Մովսէսը, Ահարոնը, Նաբադը, Աբիուդն ու իսրայէլացի ծերերից եօթանասուն տղամարդ բարձրացան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'եւ տեսան այն տեղը, ուր կանգնել էր Իսրայէլի Աստուածը: Նրա կանգնած տեղը կարծես շափիւղայի աղիւսներով էր զարդարուած, եւ դա ջինջ երկնքի նմանութիւնն ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Իսրայէլացի ընտրեալներից ոչ մէկը չմեռաւ: Նրանք յայտնուեցին այնտեղ, ուր գտնւում էր Աստուած: Եւ կերան ու խմեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Տէրն ասաց Մովսէսին. «Բարձրացի՛ր ինձ մօտ՝ լեռը, այնտեղ եղի՛ր, եւ քեզ պիտի տամ քարէ այն տախտակները, որոնց վրայ գրելու եմ իմ օրէնքներն ու պատուիրանները: Դրանք նրանց համար օրէնսդրութիւն պիտի լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Մովսէսն ու նրա սպասաւոր Յեսուն բարձրացան Աստծու լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Մովսէսն ասաց ծերերին. «Հանգստացէ՛ք այստեղ, մինչեւ որ մենք վերադառնանք ձեզ մօտ: Ահարոնն ու Ովրը ձեզ հետ են: Եթէ որեւէ մէկը վէճ ունենայ, թող գնայ նրանց մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Մովսէսը բարձրացաւ լեռը, եւ ամպը ծածկեց լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Տիրոջ փառքն իջաւ Սինա լերան վրայ, եւ ամպն այն ծածկեց վեց օր: Տէրը եօթներորդ օրը Մովսէսին կանչեց ամպի միջից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Տիրոջ փառքի տեսիլքը բորբոքուած կրակի նման իջաւ Իսրայէլի որդիների առաջ, լերան գագաթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Մովսէսը մտաւ ամպի մէջ ու բարձրացաւ լեռը: Մովսէսը լերան վրայ մնաց քառասուն օր ու քառասուն գիշեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Տէրը խօսեց Մովսէսի հետ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '«Իսրայէլի որդիներին կ՚ասես, որ առնեն ինձ սահմանուած ընծաները: Թող առնեն նրանցից, ում սրտից են բխում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Սրանք են այն ընծաները, որ դուք կ՚առնէք նրանցից. ոսկի, արծաթ, պղինձ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'կապոյտ, ծիրանի եւ կրկնակի կարմիր կտաւ, նրբահիւս բեհեզ, այծի մազ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'խոյերի կարմիր ներկուած մորթիներ, կապոյտ ներկուած մորթիներ եւ կարծր փայտեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'լոյսի համար ձէթ եւ օծութեան իւղի ու խնկի համար բաղադրանիւթեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'սարդիոնի քարեր, վակասի վրայ ագուցուելու քարեր եւ պատմուճան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Ինձ համար սրբարան կը կառուցես, եւ ես կ՚երեւամ ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Դու խորանն ու նրա ամբողջ սպասքը ինձ համար կը պատրաստես ըստ այն օրինակի, որ լերան վրայ ցոյց կը տամ քեզ: Այսպէս կը պատրաստես.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Վկայութեան տապանակ կը պատրաստես կարծր փայտից: Երկուսուկէս կանգուն թող լինի դրա երկարութիւնը, մէկուկէս կանգուն՝ դրա լայնութիւնը, մէկուկէս կանգուն՝ դրա բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Այն կը պատես մաքուր ոսկով՝ ներսից ու դրսից կ՚ոսկեզօծես այն: Դրա վրայ շուրջանակի կը դնես ոսկէ պսակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Դրա համար չորս ոսկէ օղակներ կը ձուլես եւ կը դնես դրա չորս կողմերին. երկու օղակները՝ մի կողմից, եւ երկու օղակները՝ միւս կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Կարծր փայտից լծակներ կը պատրաստես եւ դրանք կը պատես ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Լծակները կ՚անցկացնես տապանակի կողքերին ամրացուած օղակների մէջ, որպէսզի դրանցով բարձրացնեն տապանակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Լծակները վկայութեան տապանակի օղակների մէջ թող մնան՝ լինեն դրան ամրացուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Տապանակի մէջ կը դնես այն պատուիրանները, որ ես պիտի տամ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Քաւութեան խնկամանի կափարիչը կը պատրաստես մաքուր ոսկուց: Երկուսուկէս կանգուն թող լինի դրա երկարութիւնը, մէկուկէս կանգուն՝ դրա լայնութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Կոփածոյ երկու ոսկեայ քերովբէներ կը պատրաստես եւ դրանք կը դնես կափարիչի երկու ծայրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Քերովբէներից մէկը թող լինի կափարիչի մի ծայրին, իսկ միւսը՝ միւս ծայրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Երկու քերովբէներ կը դնես դրա երկու ծայրերին. թող քերովբէները դէպի վեր տարածեն իրենց թեւերը եւ իրենց թեւերով հովանի անեն կափարիչի վրայ: Նրանց գլուխները թող լինեն միմեանց յանդիման, որպէսզի քերովբէների երեսները նայեն կափարիչին: Կափարիչը կը դնես տապանակի վրայ՝ վերեւի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Տապանակի մէջ կը դնես այն պատուիրանները, որ ես պիտի տամ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ես քեզ կը յայտնուեմ այնտեղ եւ վկայութեան տապանակի կափարիչի վրայ գտնուող երկու քերովբէների արանքից քեզ հետ կը խօսեմ այն ամենի մասին, ինչ պատուիրելու եմ քեզ Իսրայէլի որդիների վերաբերեալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '«Սեղան կը պատրաստես կարծր փայտից: Երկու կանգուն թող լինի դրա երկարութիւնը, մէկ կանգուն՝ դրա լայնութիւնը, եւ մէկուկէս կանգուն՝ դրա բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Այն կը պատես մաքուր ոսկով: Դրա վրայ շուրջանակի կը դնես ոսկէ պսակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Դրա չորս կողմը մէկ թզաչափ բարձրութեամբ շրջանակ կը դնես եւ այն չորս կողմից կը պատիս ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Եւ չորս ոսկէ օղակներ կը պատրաստես եւ օղակները կը դնես չորս անկիւններին, ուր, պսակից ներքեւ, դրա չորս ոտքերն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Օղակները կը ծառայեն այն բանին, որ լծակները դրանց մէջ անցկացնելով՝ կը բարձրացնեն սեղանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Լծակները կը պատրաստես չփչացող փայտից եւ դրանք կը պատես մաքուր ոսկով: Դրանցից բռնելով՝ կը բարձրացուի սեղանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Կը պատրաստես դրա խնկամաններն ու սկուտեղները, դրա գաւաթներն ու սկիհները, որոնցով գինի պիտի մատուցես: Մաքուր ոսկուց կը պատրաստես դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Սեղանի վրայ, իմ առաջ, մշտապէս կը դնես առաջաւորութեան հաց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '«Մաքուր ոսկուց աշտանակ կը պատրաստես: Քանդակազարդ կ՚անես աշտանակը եւ այնպէս, որ բունը, ճիւղերը, սկահակները, գնդիկներն ու շուշանաձեւ ծաղիկները միաձոյլ լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Վեց ճիւղեր պէտք է տարածուեն նրա կողքերից. աշտանակի երեք ճիւղերը պէտք է լինեն մի կողմից, իսկ աշտանակի միւս երեք ճիւղերը՝ միւս կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Ամէն մի ճիւղ պէտք է ունենայ գնդիկից ու ծաղկից բաղկացած երեք ընկուզաձեւ սկահակներ: Միւս ճիւղերն էլ պէտք է ունենան գնդիկից ու ծաղկից բաղկացած երեք ընկուզաձեւ սկահակներ: Այսպէս թող լինեն աշտանակի կողքերից դուրս եկած վեց ստեղները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'աշտանակի բունը պէտք է ունենայ գնդիկից ու ծաղկից բաղկացած չորս սկահակներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Իրենց բնի կողքերից դուրս եկած երկու ճիւղերի տակ պէտք է լինի մի գնդիկ: Իրենց բնի կողքերից դուրս եկած երկու միւս ճիւղերի տակ նոյնպէս պէտք է լինի մի գնդիկ: Նոյն ձեւով կը պատրաստես աշտանակի կողքերից դուրս եկած վեց ճիւղերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'այնպէս, որ նրանց գնդիկներն ու ճիւղերը դուրս եկած լինեն իրենց բնի կողքերից՝ ամբողջութեամբ քանդակազարդ, մէկ կտոր մաքուր ոսկուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Դրա համար կը պատրաստես եօթը կանթեղ եւ կանթեղները կը դնես աշտանակի վրայ այնպէս, որ դրանք լուսաւորեն դէմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Դրա ունելիներն ու պատուանդանը կը պատրաստես մաքուր ոսկուց: Այս ամբողջ սպասքը մի տաղանդ մաքուր ոսկուց կը պատրաստես: Դրա ունելիներն ու պատուանդանը կը պատրաստես մաքուր ոսկուց: Այս ամբողջ սպասքը մի տաղանդ մաքուր ոսկուց կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Ուշադի՛ր եղիր, կ՚անես ըստ այն օրինակի, որ քեզ ցոյց տրուեց լերան վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '«Նրբահիւս բեհեզից, կապոյտ, ծիրանի եւ կրկնակի կարմիր կտաւից տասշերտանի վարագոյրով խորան կը պատրաստես: Այն կը զարդարես ասեղնագործ քերովբէներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Վարագոյրի ամէն շերտի երկարութիւնը պէտք է լինի քսանութ կանգուն, իսկ լայնութիւնը՝ չորս կանգուն: Բոլոր շերտերի չափսը նոյնը պէտք է լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Հինգ շերտերը պէտք է միացած լինեն իրար: Իրար պէտք է միացած լինեն նաեւ միւս հինգ շերտերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Շերտերի կցուածքի մի կողմից մէկ շերտի եզերքին կապոյտ ճարմանդներ պէտք է դնես: Նոյնը պէտք է անես նաեւ երկրորդ կցուածքի արտաքին շերտի եզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Յիսուն ճարմանդ կը դնես մի շերտի վրայ, յիսուն ճարմանդ էլ՝ կը դնես երկրորդ կցուածքի շերտի կողմից: Բոլոր ճարմանդները միմեանց դիմաց պէտք է լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Կը պատրաստես յիսուն ոսկէ օղակներ եւ շերտերը իրար կը միացնես կեռիկներով: Այսպիսով կը ստացուի մի խորան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Խորանի համար այծի մազից հիւսուած ծածկոց կը պատրաստես: Տասնմէկ շերտերից թող բաղկացած լինի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Ամէն մի շերտի երկարութիւնը պէտք է լինի երեսուն կանգուն, իսկ լայնութիւնը՝ չորս կանգուն: Տասնմէկ շերտերի չափսը նոյնը պէտք է լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Հինգ շերտերը իրար կը միացնես առանձին եւ վեց շերտերը՝ առանձին: Վեցերորդ շերտը իբրեւ կրկնակի ծածկոց թող կախուի խորանի ճակատի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Յիսուն ճարմանդ կը պատրաստես կցուածքի ամէն շերտի եզերքին, յիսուն ճարմանդ էլ՝ երկրորդ կցուածքի շերտի եզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Կը պատրաստես յիսուն պղնձէ օղակներ եւ ճարմանդները օղակների մէջ անցկացնելով՝ իրար կը միացնես շերտերը: Կը ստացուի մի ամբողջութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Շերտերի աւելացած մասերը կը տեղաւորես վրանի տակ. շերտի այդ աւելացած մասի կէսով կը ծածկես վրանի ծայրամասերը՝ յետեւի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Վրանի վարագոյրների երկարութեան աւելացած մասից մի կանգուն թող կախուի այս կողմից եւ մի կանգուն՝ այն կողմից: Վրանի ծայրերը թող ծածկուեն այս ու այն կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Վրանի ծածկը կը պատրաստես խոյերի շիկակարմիր մորթուց, իսկ դրա վրայ էլ մի ծածկ կը դնես կապոյտ մորթուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Վրանի ուղղահայեաց մոյթերը կը պատրաստես կարծր փայտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Ամէն մոյթի երկարութիւնը տասը կանգուն թող լինի, իսկ ամէն մոյթի հաստութիւնն ու լայնութիւնը մէկուկէս կանգուն թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Ամէն մի մոյթ թող ունենայ իրար ագուցուած երկու ծղնի: Այդպէս կը պատրաստես վրանի բոլոր մոյթերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Վրանի հիւսիսային կողմում կը դնես քսան մոյթեր');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'եւ այդ քսան մոյթերի համար կը պատրաստես քառասուն արծաթէ խարիսխներ. երկու խարիսխ՝ վրանի մի մոյթի երկու կողմերի համար եւ երկու խարիսխ՝ մի մոյթի երկու կողմերի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Վրանի միւս՝ հարաւային կողմում նոյնպէս կը դնես քսան մոյթեր իրենց քառասուն արծաթէ խարիսխներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Երկու խարիսխ՝ մի մոյթի երկու կողմերի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Վրանի յետեւի՝ ծովահայեաց կողմում վեց մոյթ կը դնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Երկու մոյթ կը դնես խորանի անկիւններին՝ յետեւի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Ներքեւի կողմից դրանք պէտք է իրար հաւասար լինեն: Նոյն ձեւով հաւասար թող լինեն դրա իրար ագուցուած զոյգ խոյակները: Նոյն ձեւով կը շինես երկու անկիւնների մոյթերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Այսպիսով կը ստացուի ութ մոյթ: Դրանց խարիսխները արծաթից թող լինեն. տասնվեց խարիսխ: Երկու խարիսխ՝ մի մոյթի համար նրա երկու կողմերից, եւ երկու խարիսխ էլ՝ միւս մոյթի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Կարծր փայտից նիգեր կը պատրաստես. հինգ նիգ՝ վրանի մի կողմի մոյթի համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'հինգ նիգ՝ վրանի երկրորդ կողմի միւս մոյթի համար եւ հինգ նիգ՝ վրանի թիկունքի՝ ծովահայեաց կողմի մոյթի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Մի նիգ էլ մոյթերի մի ծայրից մինչեւ միւսն անցկացուելով՝ դրանք թող միացնի իրար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Մոյթերը կը պատես ոսկով: Կը պատրաստես ոսկէ օղակներ, որոնց մէջ կը հագցնես նիգերը: Նիգերը կը պատես ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Վրանը կը կանգնեցնես այն ձեւով, որ ցոյց տրուեց քեզ լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից վարագոյր կը պատրաստես: Այն կը զարդարես ասեղնագործուած քերովբէով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Այն կ՚ամրացնես կարծր փայտից շինուած եւ ոսկով պատած չորս մոյթերի վրայ: Դրանց խոյակները թող լինեն ոսկուց, իսկ խարիսխները՝ արծաթից: Վարագոյրը կը ձգես մոյթից մոյթ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Վկայութեան տապանակը կը տանես այնտեղ, վարագոյրի ներսի կողմը, եւ վարագոյրը ձեզ համար սրբութիւնը կ՚առանձնացնի սրբութիւնների սրբութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Սրբութիւնների սրբութեան տեղում վկայութեան տապանակը կը ծածկես վարագոյրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Զոհասեղանը կը դնես վարագոյրի դրսի կողմը, իսկ աշտանակը՝ զոհասեղանի դիմաց, վրանի հարաւային կողմում: Զոհասեղանը կը դնես վրանի հիւսիսային կողմում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից կը պատրաստես վրանի դռան առագաստը՝ նկարազարդ մի գործ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Առագաստի համար կարծր փայտից հինգ մոյթ կը պատրաստես եւ դրանք կ՚ոսկեզօծես: Դրանց խոյակները թող լինեն ոսկուց: Դրանց համար հինգ պղնձէ խարիսխ կը ձուլես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '«Կարծր փայտից զոհասեղան կը պատրաստես: Հինգ կանգուն թող լինի դրա երկարութիւնը, հինգ կանգուն՝ լայնութիւնը: Քառակուսի թող լինի զոհասեղանը: Երեք կանգուն թող լինի դրա բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Դրա չորս անկիւնների վրայ եղջիւրներ կ՚անես այնպէս, որ դրանք միաձոյլ լինեն զոհասեղանի հետ: Դրանք կը պատես պղնձով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Զոհասեղանի համար շրջանակ կը պատրաստես: Դրա խուփը, տաշտերը, մեծ պատառաքաղները, կրակարանները եւ ամբողջ սպասքը պղնձից կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Դրա համար պղնձից վանդակաւոր կասկարայ կը պատրաստես: Կասկարայի համար չորս կողմից չորս պղնձէ օղակներ կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Դրանք կը դնես զոհասեղանի կասկարայի տակ՝ ներքեւի մասում: Կասկարան թող հասնի մինչեւ զոհասեղանի մէջտեղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Զոհասեղանի համար լծակներ կը պատրաստես՝ լծակներ կարծր փայտից, եւ դրանք կը պատես պղնձով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Լծակները կը մտցնես օղակների մէջ: Լծակները թող լինեն զոհասեղանի երկու կողմերից, որպէսզի հնարաւոր լինի այն բարձրացնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Փայտեայ շինուածքների մէջը դատարկ թող լինի: Կը պատրաստես ըստ այն օրինակի, որ ցոյց է տրուել քեզ լերան վրայ: Այդպէս կը պատրաստես այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, '«Վրանի առաջ բակ կը շինես, բակի հարաւային կողմում՝ նրբահիւս բեհեզից պատրաստուած առագաստ: Հարիւր կանգուն թող լինի բակի մի կողմի երկարութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Մոյթերը թող լինեն քսան հատ, դրանց պղնձէ խարիսխները՝ քսան հատ: Դրանց օղակներն ու խոյակները թող արծաթից լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Նոյն ձեւով հիւսիսային կողմում առագաստների երկարութիւնը թող լինի հարիւր կանգուն: Դրանց պղնձէ մոյթերը թող լինեն քսան հատ, դրանց պղնձէ խարիսխները՝ քսան հատ: Դրանց գալարազարդերը, մոյթերը եւ խարիսխները թող լինեն արծաթապատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Ծովահայեաց բակի առագաստների լայնութիւնը թող լինի յիսուն կանգուն: Դրանց մոյթերը թող լինեն տասը հատ, դրանց խարիսխները՝ տասը հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Արեւելեան կողմի առաջին բակի առագաստների լայնութիւնը թող լինի յիսուն կանգուն: Դրանց մոյթերը թող լինեն տասը հատ, դրանց խարիսխները՝ տասը հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Առագաստների մի կողմի բարձրութիւնը թող լինի տասնհինգ կանգուն: Դրանց մոյթերը թող լինեն երեք, դրանց խարիսխները՝ երեք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Առագաստների միւս կողմի բարձրութիւնը թող լինի տասնհինգ կանգուն: Դրանց մոյթերը թող լինեն երեք հատ, դրանց խարիսխները՝ երեք հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Բակի դռան վարագոյրի բարձրութիւնը թող լինի քսան կանգուն: Կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից պատրաստուած թող լինի այն՝ նկարագեղ ասեղնագործութեամբ: Դրանց մոյթերը թող լինեն չորս հատ, խարիսխներն էլ՝ չորս հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Բակի շրջակայ բոլոր մոյթերը արծաթապատ թող լինեն, դրանց խոյակները՝ արծաթից, դրանց խարիսխները՝ պղնձից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Բակի երկարութիւնը հարիւր կանգուն թող լինի, լայնութիւնը՝ յիսուն, իսկ բարձրութիւնը՝ տասնհինգ կանգուն: Առագաստը նրբահիւս բեհեզից թող լինի: Դրանց խարիսխները պղնձից թող լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Վրանի ամբողջ սպասքը, դրա բոլոր գործիքները եւ բակի բոլոր ցիցերը պղնձից թող լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '«Իսրայէլացիներին կարգադրի՛ր, որ քեզ ձիթենու զուլալ, անարատ, ծեծուած ձիթապտղի ձէթ բերեն լոյսի համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'որպէսզի մշտավառ ճրագ լինի վկայութեան խորանում, ուխտի վարագոյրից դուրս: Եւ Ահարոնն ու նրա որդիները երեկոյից մինչեւ առաւօտ թող այն վառեն Տիրոջ առաջ: Դա Իսրայէլի որդիների կողմից հաստատուած յաւիտենական օրէնք թող լինի ձեր սերունդների մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '«Դու Իսրայէլի որդիներից քեզ մօտ կը բերես քո եղբայր Ահարոնին, նրա հետ նաեւ նրա որդիներին՝ Նաբադին ու Աբիուդին, Եղիազարին ու Իթամարին, որպէսզի ինձ համար քահանայութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Ի պատիւ եւ ի փառս քո եղբայր Ահարոնի սրբազան զգեստներ կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Դու կը խօսես մտքով իմաստուն բոլոր մարդկանց հետ, որոնց ես իմաստութեան ոգով եմ լցրել, որ նրանք Ահարոնին սրբազան զգեստներ պատրաստեն սրբութեան համար, որոնցով էլ նա քահանայութեան պաշտօն է կատարելու ինձ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Սրանք են այն զգեստները, որ նրանք պիտի պատրաստեն. մինչեւ ոտքի թաթերը հասնող երկարաւուն զգեստ, ուսի ու լանջի վակասներ, բեհեզէ պատմուճան, խոյր եւ գօտի: Սրբազան զգեստներ թող պատրաստեն քո եղբայր Ահարոնի ու նրա որդիների համար, որպէսզի ինձ համար քահանայութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Նրանք թող վերցնեն ոսկի, կապոյտ, ծիրանի ու կարմիր կտաւ եւ նրբահիւս բեհեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Վակասը թող պատրաստեն մաքուր ոսկուց, կապոյտ, ծիրանի ու կարմիր նրբահիւս բեհեզից՝ այն զարդարելով նուրբ ասեղնագործութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Երկու վակասները թող իրար միանան՝ երկու կողմերից իրար կապուելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Վակասի վերեւի մասը նոյն ձեւով պէտք է պատրաստուած լինի՝ մաքուր ոսկուց, կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Զմրուխտէ երկու ակնաքար կ՚առնես եւ դրանց վրայ կը փորագրես Իսրայէլի որդիների անունները. նրանցից վեցի անունները կը փորագրես մի ակնաքարի վրայ եւ միւս վեցինը՝ երկրորդ ակնաքարի վրայ, ըստ իրենց ցեղերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Դա ակնագործների արուեստին վայել մի գործ պէտք է լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Իսրայէլի որդիների անունները կը քանդակես երկու ակնաքարերի վրայ այնպէս, ինչպէս կնիքներն են քանդակում: Դրանց շուրջը ոսկով կը զարդարես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Երկու ակնաքարերը կը զետեղես ուսի վրայ դրուող վակասի վրայ, որպէսզի դրանք Իսրայէլի որդիների յիշատակի ակնաքարերը լինեն: Ահարոնը, ի յիշատակ նրանց, Աստծու առաջ իր երկու ուսերի վրայ պէտք է կրի Իսրայէլի որդիների անունները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Օղակ ու ճարմանդ կը պատրաստես մաքուր ոսկուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Մաքուր ոսկուց կը պատրաստես այդ երկու կապիչները, որոնք ծաղկազարդ մանուածքով հիւսկէններ պէտք է լինեն: Կապիչները կ՚ամրացնես ուսանոցի երկու օղակներին՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'նրանց վտաւակների մօտ, առջեւի կողմից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, '«Դատաստանի լանջապանակը նկարազարդ կտորից կը պատրաստես. վակասի նման՝ ոսկուց, կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Քառակուսի կը պատրաստես այն՝ մէկ թիզ երկարութեամբ եւ մէկ թիզ լայնութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Դրա վրայ ակնաքարերը կը շարես չորս շարք ընդելուզուածքով: Ակնաքարերի շարքերը այսպէս թող լինեն. առաջինը՝ զմրուխտ, սարդիոն եւ տպազիոն՝ մէկ շարք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Երկրորդ շարքը՝ նռնաքար, շափիւղայ եւ յասպիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Երրորդ շարքը՝ գոճազմ, ագատ եւ սուտակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Չորրորդ շարքը՝ յակինթ, բիւրեղ եւ եղնգաքար: Դրանք թող դասաւորուեն ըստ իրենց նշուած շարքերի՝ ընդելուզուած, ոսկով ամրացուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Իսրայէլի որդիների անուններով փորագրուած ակնաքարերը թող լինեն թուով տասներկու՝ ըստ նրանց անունների թուի: Իւրաքանչիւրն ըստ այդ տասներկու ցեղերի թող ունենայ իր անունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Լանջապանակի վրայ մաքուր ոսկուց շինուած ոլորուն շղթայ կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Լանջապանակի վրայ երկու ոսկէ օղակներ կը պատրաստես եւ երկու օղակներ կ՚ամրացնես լանջապանակի երկու ծայրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Երկու ոսկէ շղթաներ կ՚անցկացնես լանջապանակի ծայրին գտնուող երկու օղակների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Երկու շղթաների երկու ծայրերը կը մտցնես երկու օղակների մէջ եւ վակասի առջեւի կողմից տանելով՝ կ՚անցկացնես վակասի ետեւի կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Երկու ոսկէ օղակներ էլ կը պատրաստես եւ դրանք կ՚ամրացնես լանջապանակի ներքեւի երկու ծայրերին, վակասին կցուած եզրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Երկու ոսկէ այլ օղակներ կը պատրաստես եւ դրանք կ՚անցկացնես վակասի երկու ուսերին, ներքեւի կողմից, միմեանց դէմ դիմաց: Դրա կոճակները թող լինեն վակասի գօտու վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Լանջապանակի ու վակասի օղակների միջով կապոյտ թել անցկացնելով՝ դրանք թող պինդ ամրացուեն իրար այնպէս, որ լանջապանակը լինի վակասի գօտու վրայ եւ վակասից չառանձնանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Երբ Ահարոնը սրբարան կը մտնի, նա իր կրծքի վրայ թող կրի Իսրայէլի որդիների անուններով քանդակուած դատաստանի լանջապանակը, որպէսզի Աստծու առաջ յաւիտենապէս պահպանի նրանց յիշատակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Դատաստանի լանջապանակին կ՚ամրացնես շղթաների ծայրերը եւ լանջապանակի երկու կողմերից կը կապես: Երկու վահանաձեւ կոճակ կը դնես վակասի երկու ուսերին, առջեւի կողմից եւ ներքեւից: Դատաստանի լանջապանակի վրայ կը դնես յանդիմանութիւնն ու ճշմարտութիւնը: Դա թող լինի Ահարոնի կրծքի վրայ« »րբ նա սրբարան մտն»լով՝ ն»րկայանայ Տիրոջը: Եւ Ահարոնը Տիրոջ առաջ իր կրծքի վրայ միշտ թող կրի Իսրայէլի որդիների դատաստանի լանջապանակը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, '«Պճղնաւոր ներքին պատմուճան կը պատրաստես ամբողջութեամբ կապոյտ թելով հիւսուած կտաւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Դրա վերին մասը շուրջանակի կլոր կտրելով՝ բացուածք կը թողնես: Միացման տեղերը ամբողջական՝ մէկ կտոր թող լինեն, որպէսզի այդ զգեստը չպատռուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Ներքին պատմուճանների քղանցքներին, ներքեւի մասում մանուած կապոյտ, ծիրանի ու կարմիր թելերով եւ նրբահիւս բեհեզով նռան ծաղկաբողբոջներ կը գործես: Դրանք կը գործես ներքին պատմուճանների քղանցքների շուրջբոլորը: Այդ զարդերը թող ունենան նռան ծաղկաբողբոջի ձեւը, եւ դրանց միջ»ւ շուրջանակի ոսկէ զանգակն»ր թող լին»ն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Ոսկէ զանգակներն ու նռան ծաղկաբողբոջները շուրջանակի թող զարդարեն ներքին պատմուճանների քղանցքները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Դա թող հագնի Ահարոնը, որպէսզի, երբ պաշտամունք է կատարում, Տիրոջ առաջ սրբարան մտնելիս ու ելնելիս լսուեն դրանց արձակած ձայները, եւ Ահարոնը չմեռնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Մաքուր ոսկուց թիթեղ կը պատրաստես եւ դրա վրայ, ինչպէս կնիքի վրայ են փորագրում, «Սրբութիւն Տեառն» կը փորագրես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Այն կ՚ամրացնես նրբահիւս կապոյտ ժապաւէնի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Դա կը կապես Ահարոնի գլխին դրուող խոյրի վրայ՝ ճակատի կողմից: Ահարոնը պէտք է կրի Իսրայէլի որդիների նուիրած բոլոր ընծաները, եթէ նոյնիսկ նրանք անօրէնութիւններ գործած լինեն դրանք նուիրելիս: Դա միշտ Ահարոնի ճակատին պէտք է լինի, որպէսզի այդ ընծաները ընդունելի լին»ն Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Մինչեւ ոտքի թաթերը հասնող երկարաւուն պատուճանը բեհեզից կը պատրաստես: Բեհեզից կը պատրաստես նաեւ ապարօշն ու նախշազարդ գօտին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Ահարոնի որդիների համար պատմուճաններ, գօտիներ եւ խոյրեր կը պատրաստես պատուի եւ փառքի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Դրանք կը հագցնես քո եղբայր Ահարոնին ու նրա որդիներին: Կ՚օծես նրանց, կ՚օրհնես ու կը սրբագործես նրանց, որպէսզի ինձ համար քահանայութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Նրանց համար կտաւից անդրավարտիքներ կը պատրաստես, որպէսզի դրանք նրանց մէջքից մինչեւ սրունքները հասնելով՝ ծածկեն նրանց ամօթոյքը: Ահարոնն ու նրա որդիները թող հագնեն այն, երբ մտնեն վկայութեան խորանը, կամ երբ պաշտամունք կատարելու համար մօտենան սուրբ սեղանին: Նրանք մեղք թող չգործեն, որպէսզի չմեռնեն: Դա թող լինի յաւիտենական օրէնք իր եւ իրեն յաջորդող սերնդի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '«Ահա թէ ինչպէս կը վարուես նրանց հետ: Կը սրբագործես նրանց, որպէսզի ինձ համար քահանայութիւն անեն: Հօտից կը վերցնես ոչ արատաւոր մի զուարակ եւ ոչ արատաւոր երկու խոյ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'նաեւ բաղարջ հաց, իւղով հունցուած բաղարջ կարկանդակներ ու իւղով շաղուած բաղարջ բլիթներ: Այդ բոլորը իւղով հունցուած ընտիր ալիւրով կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Դրանք կը դնես մի սկուտեղի վրայ եւ սկուտեղով էլ կը նուիրաբերես դրանք, ինչպէս նաեւ զուարակն ու երկու խոյերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Ահարոնին ու նրա որդիներին կը բերես վկայութեան խորանի դռան մօտ եւ նրանց կը լուանաս ջրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Զգեստներն առնելով՝ քո եղբայր Ահարոնի ներքնազգեստի վրայ կը հագցնես երկարաւուն պատուճանը, վակասն ու լանջապանակը: Լանջապանակը կ՚ամրացնես վակասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Խոյրը կը դնես նրա գլխին, իսկ թիթեղեայ սուրբ պսակը կը դնես խոյրի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Կը վերցնես օծութեան իւղից, կը քսես նրա գլխին եւ կ՚օծես նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Մօտ կը բերես նրա որդիներին, նրանց նոյնպէս կը հագցնես զգեստները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Ահարոնի ու նրա որդիների մէջքին կը կապես գօտիները, ապարօշները կը դնես նրանց գլխին եւ նրանց քահանայութիւնը ինձ համար յաւիտենական կը լինի: Այսպէս կը սրբագործես դու Ահարոնին ու նրա որդիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Զուարակը կը բերես վկայութեան խորանի դռան մօտ, եւ Ահարոնն ու նրա որդիները վկայութեան խորանի դռան մօտ իրենց ձեռքերը կը դնեն զուարակի գլխին Տիրոջ առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Զուարակը կը մորթես Տիրոջ առաջ, վկայութեան խորանի դռան մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Կը վերցնես զուարակի արիւնից քո մատով ու կը քսես զոհասեղանի եղջիւրաձեւ անկիւններին, իսկ մնացած ամբողջ արիւնը կը հեղես զոհասեղանի յատակին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Կը վերցնես փորոտիքը ծածկող ամբողջ ճարպը, լեարդի տակի բլթակը եւ երկու երիկամներն իրենց ճարպի հետ, կը դնես զոհասեղանի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Զուարակի միսը, նրա մորթին ու կղկղանքը թող այրեն բանակատեղիից դուրս: Դա հէնց մեղքերի համար է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Կ՚առնես խոյերից մէկը, եւ Ահարոնն ու նրա որդիները իրենց ձեռքերը կը դնեն խոյի գլխին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Կը մորթես խոյը եւ վերցնելով նրա արիւնը՝ կը հեղես զոհասեղանի շուրջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Խոյը կը բաժանես մասերի, ջրով կը լուանաս նրա փորոտիքն ու ոտքերը եւ դրանք նրա գլխի հետ կը դնես կտրտած մասերի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Զոհասեղանի վրայ դրուած ամբողջ խոյը կը լինի Տիրոջն առաքուած անուշահոտ ողջակէզ: Դա Տիրոջը մատուցուած զոհն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Կ՚առնես երկրորդ խոյը, եւ Ահարոնն ու նրա որդիները իրենց ձեռքերը կը դնեն խոյի գլխին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Կը մորթես խոյը, կը վերցնես նրա արիւնից եւ կը քսես Ահարոնի աջ ականջի բլթակին, նրա որդիների աջ ականջի բլթակին, Ահարոնի աջ ձեռքի ծայրերին, նրա աջ ոտքի ծայրերին, նրա որդիների աջ ականջների բլթակներին, նրանց աջ ձեռքերի ծայրերին, նրանց աջ ոտքերի ծայրերին: Մնացած արիւնը կը հ»ղ»ս զոհաս»ղանի շուրջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Կ՚առնես զոհասեղանի վրայ գտնուող արիւնից ու օծութեան իւղից եւ կը ցանես Ահարոնի ու նրա զգեստների վրայ, նրա որդիների ու նրա որդիների զգեստների վրայ: Թող սրբագործուեն Ահարոնն ու իր զգեստները, նրա հետ նաեւ՝ նրա որդիներն ու նրա որդիների զգեստները: Խոյի արիւնը կը հեղես զոհաս»ղանի շուրջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Կ՚առնես խոյի ճարպը, դմակը, փորոտիքը ծածկող ճարպը, լեարդի տակի բլթակը, երկու երիկամներն իրենց ճարպի հետ եւ աջ զիստը»: Դա սրբազան նուիրագործութիւնն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, '«Տիրոջ առաջ դրուած բաղարջների սկուտեղից կը վերցնես մի հաց, իւղով հունցուած մի կարկանդակ ու մի բլիթ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'այդ ամէնը կը դնես Ահարոնի ձեռքերի վրայ, նրա որդիների ձեռքերի վրայ եւ որպէս ընծայ կը նուիրաբերես Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Դրանք կը վերցնես նրանց ձեռքերից եւ ողջակէզների զոհասեղանի վրայ կ՚այրես իբրեւ անուշահոտ զոհ Տիրոջ առաջ»: Դա Տիրոջ համար կատարուող զոհաբերութիւն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, '«Կ՚առնես Ահարոնին քահանայ օծելու համար զոհուած խոյի կուրծքը եւ այն որպէս ընծայ կը նուիրաբերես Տիրոջը, իսկ մնացեալը կը լինի քո բաժինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Կը սրբագործես խոյի կուրծքը որպէս նուիրաբերութիւն, ինչպէս նաեւ՝ նրա զիստը, որը նուիրագործուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Եւ այն ամէնը, ինչ Ահարոնի եւ նրա որդիների կողմից որպէս բաժին կը հանուի խոյից, յաւիտենական օրէնք պիտի լինի Ահարոնի եւ նրա որդիների համար իսրայէլացիների մօտ, քանզի դա է ըստ օրինի նրանց հասանելիք բաժինը: Եւ դա իսրայէլացիների՝ իրենց փրկութեան համար Տիրոջ առաջ զոհաբ»րու»լիք ընծան թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Ահարոնի սրբազան զգեստները իրենից յետոյ թող պատկանեն իր որդիներին, որպէսզի նրանք օրհնուեն ու օծուեն այդ զգեստները հագած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Եօթը օր այդ զգեստները թող հագնի այն քահանան, որը նրա որդիներից լինելով՝ պիտի փոխարինի նրան, որպէսզի վկայութեան խորան մտնի սրբարանում պաշտամունք կատարելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Կը վերցնես նուիրագործութեան խոյը եւ դրա միսը կ՚եփես մի սուրբ վայրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Ահարոնն ու նրա որդիները թող ուտեն խոյի մսից: Վկայութեան խորանի դռան մօտ թող ուտեն նաեւ սկուտեղի վրայի բաղարջ հացերը եւ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'այն բաները, որ իրենց ձեռնադրութեան եւ սրբագործութեան որպէս քաւութիւն ծառայեցին: Որեւէ օտարական թող դրանցից չուտի, որովհետեւ դրանք սրբութիւններ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Եթէ նուիրագործութեան զոհի մսից ու հացից մնայ մինչեւ առաւօտ, ապա մնացորդները կ՚այրես կրակով. այն թող չուտուի, որովհետեւ Տիրոջ սրբութիւնն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Այն ամէնը, ինչ կարգադրում եմ քեզ Ահարոնի ու նրա որդիների վերաբերեալ, կը կատարես: Եօթը օր կը կատարես նրանց օրհնութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Մեղքերի քաւութեան զուարակը կը զոհես սրբութեան օրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Զոհ մատուցելու համար զոհասեղանը պէտք է սրբագործուած լինի: Զոհասեղանը սրբագործելու համար եօթը օր պէտք է այն մաքրես, օծես, եւ զոհասեղանը կը լինի սրբութիւն սրբոց: Զոհասեղանին դիպչող ամէն ոք կը սրբագործուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '«Ահա թէ ինչ պիտի զոհես զոհասեղանի վրայ. մշտնջենապէս, ամէն օր մէկ տարեկան ոչ արատաւոր երկու գառ պիտի զոհես զոհասեղանի վրայ. դա մշտնջենական զոհաբերութիւն է լինելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Մի գառ կը զոհես առաւօտեան, իսկ երկրորդ գառը կը զոհես երեկոյեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Ամէն մի գառան հետ կը բերես նաեւ շուրջ մէկուկէս լիտր զտուած իւղ՝ շաղուած երեք կիլոգրամ ընտիր ալիւրի հետ, ինչպէս նաեւ մէկուկէս լիտր գինի իբրեւ ընծայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Երկրորդ գառը կը զոհես երեկոյեան այնպէս, ինչպէս առաւօտեան զոհուած գառը՝ բերելով նոյն ընծաները: Այն որպէս անուշահոտ զոհ կը մատուցես Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Ձեր ազգի մէջ դա պիտի լինի վկայութեան խորանի դռան մօտ, Տիրոջ առաջ կատարուող մշտնջենական զոհաբերութիւն: Ես քեզ յայտնուելու եմ այնտեղ, որպէսզի խօսեմ քեզ հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Այնտեղ պիտի երեւամ Իսրայէլի որդիներին ու պիտի սրբագործուեմ իմ փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ես պիտի սրբագործեմ վկայութեան խորանն ու զոհասեղանը, պիտի սրբագործեմ Ահարոնին ու նրա որդիներին, որպէսզի նրանք ինձ համար քահանայութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ես պիտի անուանուեմ Իսրայէլի որդիների մէջ եւ պիտի լինեմ նրանց Աստուածը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Նրանք պիտի գիտենան, որ ե՛ս եմ իրենց Տէր Աստուածը, որ իրենց հանեց Եգիպտացիների երկրից, որպէսզի նրանք տան իմ անունը, եւ ես լինեմ իրենց Տէր Աստուածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '«Խնկարկութեան սեղան կը պատրաստես կարծր փայտից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Այն կը շինես մէկ կանգուն երկարութեամբ եւ մէկ կանգուն լայնութեամբ. քառակուսի թող լինի: Երկու կանգուն թող լինի դրա բարձրութիւնը: Դրա եղջիւրաւոր անկիւնները սեղանի հետ միաձոյլ թող լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Մաքուր ոսկով կը պատես այն, ինչպէս նաեւ դրա կասկարան, չորս եզերքներն ու եղջիւրաւոր անկիւնները: Դրա շուրջբոլորը ոսկէ պսակ կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Պսակի ներքեւի մասում, երկու կողմերին մաքուր ոսկուց երկուական օղակներ կը պատրաստես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Դրանք կ՚ամրացնես նրա երկու կողմերին, որպէսզի լծակները օղակների մէջ անցկացնելով կարելի լինի բարձրացնել խնկարկութեան սեղանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Լծակները կը պատրաստես կարծր փայտից ու դրանք կը պատես ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Խնկարկութեան սեղանը կը դնես վկայութեան տապանակի առջեւ գտնուող վարագոյրի դիմաց (վկայութեան վրայ գտնուող քաւութեան դիմաց), ուր ես երեւալու եմ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Ահարոնը դրա վրայ, իբրեւ կարգ, ամէն առաւօտ մանր աղացած խունկ թող ծխի. թող խունկ ծխի դրա վրայ երբ կանթեղներն է պատրաստում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Երբ Ահարոնը երեկոյեան վառի կանթեղները, Տիրոջ առաջ, խնկարկութեան սեղանի վրայ միշտ խունկ թող ծխի: Դա նրանց ազգի մէջ խնկարկութեան մշտնջենական կարգ թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Խնկարկութեան սեղանի վրայ օտար խունկ մի՛ ծխէք, ողջակէզներ, ուտուելիք ու խմուելիք ընծաներ մի՛ մատուցէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Ահարոնը տարին մէկ անգամ խնկարկութեան սեղանի եղջիւրաւոր անկիւնների վրայ քաւութեան ծէս պէտք է անի. նա այն պէտք է մաքրի մեղքերի քաւութեան համար զոհուող կենդանու արեամբ: Նրա սերունդները տարին մէկ անգամ թող սրբագործեն այն, որովհետեւ դա Տիրոջ սրբութիւնների սրբութիւնն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Տէրը խօսեց Մովսէսի հետ ու ասաց. «Երբ Իսրայէլի որդիների թիւն իմանալու համար մարդահամար կը կատարես, նրանք Տիրոջը պէտք է տան իրենց հոգու փրկագինը՝ ըստ իրենց անձերի թուի: Մարդահամարի ժամանակ մահացութեան դէպքեր չպիտի լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Մարդահամարի ենթարկուողները պէտք է փրկագին վճարեն սրբարանի երկդրամեանի կէսը: Երկդրամեանը քսան դանգի է հաւասար: Երկդրամեանի կէսը թող լինի Տիրոջը հասանելիք տուրքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Քսան տարեկան եւ աւելի բարձր տարիք ունեցող բոլոր նրանք, ովքեր կ՚անցնեն մարդահամարով, Տիրոջը հասանելիք տուրքը պէտք է վճարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Մեծահարուստը թող չաւելացնի, իսկ աղքատը թող չպակասեցնի իսրայէլացիների՝ Տիրոջը որպէս տուրք հասանելիք կէսդրամեանը, որպէսզի դա ձեզ համար քաւութիւն լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Որպէս տուրք Տիրոջ հասանելիք դրամը կը վերցնես Իսրայէլի որդիներից եւ այն կը յատկացնես վկայութեան խորանի սպասաւորութեանը: Դա Տիրոջ առաջ Իսրայէլի որդիների համար յիշատակ կը լինի ի քաւութիւն նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Տէրը խօսեց Մովսէսի հետ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '«Պղնձէ լուացարան պատրաստի՛ր: Պղնձից շինի՛ր նրա պատուանդանը, որպէսզի լուացուեն նրա մէջ: Այն կը դնես վկայութեան խորանի ու զոհասեղանի միջեւ: Դրա մէջ ջուր կը լցնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Ահարոնն ու նրա որդիները այդ ջրով կը լուանան իրենց ձեռքերն ու ոտքերը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'երբ մտնեն վկայութեան խորանը, ջրով թող լուացուեն, որպէսզի չմեռնեն: Կամ երբ պաշտամունք կատարելու եւ Տիրոջը ողջակէզներ մատուցելու համար մօտենան զոհասեղանին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'թող լուանան իրենց ձեռքերն ու ոտքերը, որպէսզի չմեռնեն: Դա նրանց համար, նրա եւ նրանից յետոյ գալիք նրա յետնորդների համար յաւիտենական կարգ թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Տէրը խօսեց Մովսէսի հետ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '«Վերցրո՛ւ անուշահոտ համեմունքներ. զմռնենու հինգ հարիւր սիկղ ընտիր ծաղիկներ, դրա կէսի չափ՝ երկու հարիւր յիսուն սիկղ անուշաբոյր կինամոն, երկու հարիւր յիսուն սիկղ անուշաբոյր խնկեղէգ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'հինգ հարիւր սիկղ սրբարանի հիրիկ եւ ձիթապտղի շուրջ վեց լիտր ձէթ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Դրանցից կը պատրաստես սուրբ օծութեան համար իւղ այնպէս, ինչպէս վարպետ իւղագործները ձէթ են պատրաստում: Այն սուրբ օծութեան համար իւղ թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Դրանով կ՚օծես վկայութեան խորանը, վկայութեան տապանակը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'զոհասեղանն ու նրա ամբողջ սպասքը, աշտանակն ու նրա ամբողջ սպասքը, խնկարկութեան սեղանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'ողջակէզների սեղանն ու նրա ամբողջ սպասքը, աւազանն ու նրա պատուանդանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Կը սրբագործես դրանք, եւ դրանք կը լինեն սրբութիւնների սրբութիւն: Ամէն ոք, որ դիպչի դրան, կը մաքրուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Կ՚օծես Ահարոնին ու նրա որդիներին, կը սրբագործես նրանց, որպէսզի նրանք ինձ համար քահանայութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Կը խօսես Իսրայէլի որդիների հետ ու կ՚ասես. «Այս իւղը ձեր սերունդների մէջ ձեր սուրբ օծութեան համար թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Մարդու մարմնին թող չքսուի այն: Ձեզ համար նոյն բաղադրութեամբ նման բան չպատրաստէք, որովհետեւ դա սրբութիւն է եւ ձեզ համար սրբութիւն էլ թող մնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Ով այդպիսի բան պատրաստի, եւ ով դրանից օտարականի տայ, թող վերանայ իր ժողովրդի միջից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Տէրն ասաց Մովսէսին. «Վերցրո՛ւ անուշաբոյր համեմունքներ. ստաշխ, եղնգաքար, անուշաբոյր քաղբան եւ մաքուր կնդրուկ: Դրանք թող քաշով իրար հաւասար լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Դրանք իրար խառնելով՝ մաքուր, սուրբ խունկ կը պատրաստես, ինչպէս վարպետ իւղագործներն են պատրաստում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Դրանք մանր կ՚աղաս եւ կը դնես վկայութեան դիմաց՝ վկայութեան խորանի մէջ, ուր պիտի երեւամ քեզ: Ձեր պատրաստած այդ խունկը ձեզ համար սրբութիւնների սրբութիւն թող լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Ձեզ համար նոյն բաղադրութեամբ խունկ մի՛ պատրաստէք, որովհետեւ դա ձեզ համար սրբութիւն պիտի լինի Տիրոջ առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Այն մարդը, որ հոտոտելու համար այս բաղադրութեամբ խունկ կը պատրաստի, կը վերանայ իր ժողովրդի միջից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Տէրը խօսեց Մովսէսի հետ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '«Ես, ահա, Յուդայի ազգից ընտրեցի Բեսելիէլին, որը որդին է Ուրիի, իսկ սա՝ որդին Ովրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Ես նրան լցրի ամէն գործի համար անհրաժեշտ գիտութեան, հանճարի եւ իմաստութեան աստուածային ոգով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'որպէսզի նա մտածի ու ստեղծագործի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'որպէսզի մշակի ոսկին, արծաթն ու պղինձը, մանի կապոյտ, ծիրանի ու կարմիր կտաւը, զբաղուի արհեստի կատարելութիւն հանդիսացող ակնագործութեամբ, նաեւ ատաղձագործութեամբ, որ գործի դնի ամէն մի արհեստ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Ահա ես նրան օգնական եմ տալիս Դանի ցեղից Աքիսամի որդի Եղիաբին: Ամէն մի ուշիմ մարդու հոգու մէջ դրի շնորհ, որպէսզի անի այն, ինչ պատուիրել եմ քեզ, այսինքն՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'պատրաստի վկայութեան խորանը, կտակարանների տապանակն ու նրա կափարիչը, խորանի ամբողջ սպասքն ու զոհարանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'զոհասեղանն ու նրա ամբողջ սպասքը, սուրբ աշտանակն ու նրա բոլոր զարդերը, խնկարկութեան սեղանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'ողջակէզների սեղանն ու նրա բոլոր մասերը, աւազանն ու նրա պատուանդանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'ծիսակատարութեան զգեստները, Ահարոն քահանայի սրբազան զգեստներն ու նրա որդիների՝ ինձ համար քահանայութիւն անելու զգեստները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'օծութեան իւղն ու սրբարանի խնկի համեմունքները: Այս բոլորը, ինչ մի անգամ պատուիրել եմ քեզ, կը պատրաստես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Տէրը խօսեց Մովսէսի հետ եւ ասաց. «Իսրայէլի որդիներին հաղորդի՛ր հետեւեալը. «Զգո՛յշ եղէք, պահեցէ՛ք իմ շաբաթ օրերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'որովհետեւ դա ձեր սերնդի մէջ իմ ու ձեր միջեւ դրուած պայմանն է, որպէսզի ճանաչէք, թէ ե՛ս եմ ձեզ սրբագործող Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Կը պահէք շաբաթ օրերը, որովհետեւ Տիրոջ եւ ձեզ համար դա սրբութիւն է: Ով այն պղծի, թող մահուան դատապարտուի: Ամէն ոք, ով այդ օրը գործ կ՚անի, թող վերանայ իր ժողովրդի միջից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Վեց օր գործ կ՚անես, իսկ եօթներորդ օրը Տիրոջ սուրբ հանգստեան շաբաթ օրն է: Ով որ շաբաթ օրը գործ կ՚անի, թող մահուան դատապարտուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Իսրայէլի որդիները թող պահեն շաբաթ օրերը, որպէսզի դրանք ձեր սերնդի մէջ ի կատար ածուեն որպէս յաւիտենական ուխտ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'իմ ու Իսրայէլի որդիների միջեւ: Դա իմ յաւիտենական պայմանն է, որովհետեւ Տէրը վեց օրում ստեղծեց երկինքն ու երկիրը, իսկ եօթներորդ օրը դադար տուեց եւ հանգստացաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Երբ Աստուած Սինա լերան վրայ աւարտեց իր խօսքը, Մովսէսին տուեց վկայութեան երկու տախտակները՝ Աստծու մատով գրուած քարէ տախտակները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Ժողովուրդը տեսնելով, որ Մովսէսն ուշացաւ լեռից իջնելու, հաւաքուեց Ահարոնի մօտ ու ասաց նրան. «Դե՛հ, մեզ առաջնորդող աստուածներ ստեղծի՛ր, որովհետեւ չգիտենք, թէ ինչ եղաւ այն մարդը՝ Մովսէսը, որ մեզ Եգիպտոսից դուրս բերեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Ահարոնն ասաց նրանց. «Ձեր կանանց, ձեր տղաների ու աղջիկների ականջներից հանեցէ՛ք ոսկէ գինդերը եւ բերէ՛ք ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Բոլորը իրենց ականջներից հանեցին ոսկէ գինդերը եւ բերեցին տուեցին Ահարոնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Ահարոնը դրանք առնելով նրանցից՝ կաղապարի մէջ ձուլեց եւ կերտեց ձուլածոյ մի հորթ: Նրանք ասացին. «Սա՛ է քո աստուածը, Իսրայէ՛լ, որ քեզ դուրս բերեց Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Երբ Ահարոնն այդ տեսաւ, կուռքի առաջ զոհասեղան շինեց: Ահարոնը յայտարարեց. «Վաղը Տիրոջ տօնն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Առաւօտեան վեր կենալով՝ նա ողջակէզներ արեց եւ փրկութեան զոհեր մատուցեց: Ժողովուրդը նստեց, որ կերուխում անի, ապա վեր կացաւ, որ պարի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Տէրը Մովսէսին ասաց. «Շո՛ւտ արա, գնա իջի՛ր այստեղից, որովհետեւ անօրինութիւն է կատարում քո ժողովուրդը, որին դուրս բերեցիր Եգիպտացիների երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Նրանք շատ շուտ շեղուեցին այն ճանապարհից, որ ցոյց տուեցիր նրանց: Նրանք ձուլածոյ հորթ են կերտել, երկրպագում են նրան, զոհեր մատուցում ու ասում. «Սա՛ է քո աստուածը, Իսրայէ՛լ, որ քեզ դուրս բերեց Եգիպտացիների երկրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Տէրն ասաց Մովսէսին. «Ես տեսնում եմ, որ այս ժողովուրդը կամակոր է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Արդ, թո՛յլ տուր ինձ, որ նրանց վրայ թափեմ իմ զայրոյթը՝ կոտորեմ նրանց, իսկ քեզ մեծ ազգ դարձնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Մովսէսն աղաչեց իր տէր Աստծուն՝ ասելով. «Տէ՛ր, ինչո՞ւ ես այդպէս խիստ զայրանում քո ժողովրդի վրայ, որին քո մեծ զօրութեամբ ու հզօր բազկով դուրս բերեցիր Եգիպտացիների երկրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Այնպէս չլինի, որ եգիպտացիներն ասեն. «Չար մտադրութեամբ դուրս բերեց նրանց, որպէսզի լեռների վրայ կոտորի, երկրի երեսից վերացնի նրանց»: Մեղմացրո՛ւ քո զայրոյթը, հրաժարուի՛ր քո ժողովրդին չարիք պատճառելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Յիշի՛ր քո ծառաներ Աբրահամին, Իսահակին ու Յակոբին, որոնց անձովդ երդուեցիր, խօսեցիր նրանց հետ՝ ասելով. «Երկնքի աստղերի չափ պիտի բազմացնեմ ձեր սերունդը»: Եւ այն երկիրը, որ խոստացար տալ նրանց զաւակներին, նրանք յաւիտեան պիտի տիրանան դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Եւ Տէրը հրաժարուեց պատճառել այն չարիքները, որոնցով սպառնում էր պատժել ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Մովսէսը վերադարձաւ եւ իջաւ լեռից: Նրա ձեռքին էին վկայութեան երկու տախտակները: Քարէ տախտակների երկու երեսին՝ այս ու այն կողմից գրուած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Տախտակներն Աստծու գործն էին, իսկ տախտակների վրայ գրուած գիրը Աստծու արձանագրած գիրն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Յեսուն, լսելով աղաղակող ժողովրդի ձայնը, Մովսէսին ասաց. «Բանակատեղիից պատերազմի ձայն է գալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Մովսէսն ասաց. «Դա ո՛չ յաղթանակած կտրիճների ճիչ է, ո՛չ էլ պարտուած զօրքի աղաղակ: Գինուց ընդարմացած մարդկանց ձայնն է, որ լսում եմ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Երբ Մովսէսը մօտեցաւ բանակատեղիին եւ տեսաւ հորթն ու պարողներին, խիստ զայրացաւ, նետեց ձեռքում եղած երկու տախտակներն ու ջարդուփշուր արեց դրանք լերան ստորոտին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Վերցնելով նրանց կերտած հորթը՝ Մովսէսը կրակը նետեց այն, ապա մանրեց, փոշու վերածեց, փոշին խառնեց ջրի մէջ ու տուեց ժողովրդին, որ խմի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Մովսէսն ասաց Ահարոնին. «Ի՞նչ է արել քեզ այս ժողովուրդը, որ նրան այդպիսի մեծ մեղքերի մղեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Ահարոնն ասաց Մովսէսին. «Մի՛ զայրացիր, տէ՛ր իմ, որովհետեւ դու ինքդ էլ գիտես, որ քո ժողովուրդը չարամէտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Նրանք ասացին. «Մեզ համար առաջնորդող աստուածներ ստեղծիր, որովհետեւ չգիտենք, թէ ինչ պատահեց այն մարդուն՝ Մովսէսին, որը Եգիպտոսից դուրս բերեց մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Ես նրանց ասացի. «Եթէ որեւէ մէկը ոսկի ունի, նրանից հանեցէ՛ք դա եւ բերէ՛ք»: Նրանք ինձ տուեցին ոսկին, ես այն նետեցի կրակը, եւ ահա ստացուեց այս հորթը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Մովսէսը տեսաւ, որ ժողովուրդը պատուիրանազանց է եղել, որովհետեւ Ահարոնը նրանց յանցագործութեան էր մղել ի չարախնդութիւն իրենց թշնամիների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Մովսէսը, կանգնելով բանակատեղիի մուտքի մօտ, ասաց. «Ով Տիրոջն է պատկանում, ինձ մօտենայ»: Նրա շուրջը հաւաքուեցին Ղեւիի բոլոր որդիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Մովսէսը նրանց ասաց. «Այսպէս է ասում Իսրայէլի Տէր Աստուածը. «Իւրաքանչիւրը իր սուրը թող կապի իր ազդրին: Բանակատեղիի մի մուտքից միւսը գնացէք-եկէք, եւ ձեզնից իւրաքանչիւրը թող սպանի իր եղբօրը, իւրաքանչիւրը՝ իր ընկերոջը, իւրաքանչիւրը՝ իր մերձաւորին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Ղեւիի որդիներն արեցին այնպէս, ինչպէս ասել էր Մովսէսը: Այդ օրը ժողովրդի միջից շուրջ երեք հազար մարդ կոտորուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Մովսէսն ասաց նրանց. «Այսօր իւրաքանչիւրդ ձեր ձեռքով ծառայեցիք Տիրոջը. մէկն սպանեց իր որդուն, միւսն՝ իր եղբօրը, որի համար այսօր ձեզ վրայ կ՚իջնի Տիրոջ օրհնութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Յաջորդ օրը Մովսէսն ասաց ժողովրդին. «Դուք մեծ մեղք էք գործել, բայց ես հիմա կը բարձրանամ Աստծու մօտ, որպէսզի ձեր մեղքերի համար քաւութիւն խնդրեմ նրանից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Մովսէսը վերադարձաւ Տիրոջ մօտ ու ասաց նրան. «Աղաչում եմ քեզ, Տէ՛ր, այդ ժողովուրդը մեծ մեղք է գործել, որովհետեւ իր համար ոսկէ աստուածներ է կերտել: Արդ, եթէ ներելու ես իրենց մեղքերը, ների՛ր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'իսկ եթէ չես ներելու, ուրեմն իմ անունը ջնջի՛ր քո մատեանից, ուր գրել ես ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Տէրն ասաց Մովսէսին. «Ես իմ մատեանից կը ջնջեմ նրան, ով մեղանչել է իմ դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Բայց հիմա գնա՛, իջի՛ր եւ այդ ժողովրդին առաջնորդի՛ր այն վայրը, որի մասին ասել եմ քեզ: Իմ հրեշտակը կը գնայ քո առաջից: Այն օրը, սակայն, երբ պիտի այցելեմ ձեզ, նրանց մեղքերը իրենց վրայ պիտի դնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Եւ Տէրը ժողովրդին պատուհասեց այն հորթի համար, որ կերտել էր Ահարոնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Տէրն ասաց Մովսէսին. «Ելէ՛ք այստեղից դու եւ քո ժողովուրդը, որին դուրս բերեցիր Եգիպտացիների երկրից, եւ գնացէ՛ք այն երկիրը, որ երդուել եմ տալ Աբրահամին, Իսահակին ու Յակոբին՝ ասելով՝. «Ձեր սերնդին եմ տալու այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ես քո առաջից կ՚ուղարկեմ իմ հրեշտակին, որ հալածի քանանացիներին, ամորհացիներին, քետացիներին, փերեզացիներին, գերգեսացիներին, խեւացիներին ու յեբուսացիներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'քեզ կը տանեմ այն երկիրը, ուր կաթ ու մեղր է հոսում: Բայց ես, կամակո՛ր ժողովուրդ, քեզ հետ դուրս չպիտի ելնեմ, որպէսզի ճանապարհին քեզ չկոտորեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Ժողովուրդը, լսելով այդ խիստ խօսքերը, մեծ սուգ արեց, սգաւորի զգեստներ հագաւ, ոչ ոք իր վրայ զարդ չկրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Տէրն ասաց Մովսէսին. «Դու իսրայէլացիներին ասա՛. «Դուք կամակոր ժողովուրդ էք: Զգո՛յշ եղէք, թէ չէ մի այլ պատուհաս էլ կը բերեմ ձեր գլխին եւ կը կոտորեմ ձեզ: Արդ, հանեցէ՛ք ձեր շքեղ պատմուճանները, ձեր զարդերը, որպէսզի ցոյց տամ ձեզ, թէ ինչ եմ անելու ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Իսրայէլացիները Քորեբ լերան մօտ հանեցին իրենց զարդերն ու պատմուճանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Մովսէսն իր վրանը խփեց բանակատեղիից դուրս՝ առանձին մի տեղում: Դա կոչուեց Վկայութեան վրան: Ով ինչ հայցում էր Տիրոջից, գալիս էր բանակատեղիից դուրս գտնուող Վկայութեան վրանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Երբ Մովսէսը դէպի վրանն էր գնում, ողջ ժողովուրդը՝ ամէն մէկն իր վրանի դռան մօտ կանգնած, ուշադիր դիտում էր նրան. նրանք հայեացքով հետեւում էին Մովսէսին, մինչեւ որ նա գնում մտնում էր իր վրանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Երբ Մովսէսը մտնում էր վրանը, ամպի մի սիւն էր իջնում ու կանգնում վրանի դռան մօտ, եւ Տէրը խօսում էր Մովսէսի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Ողջ ժողովուրդը, տեսնելով վրանի դռան մօտ կանգնած ամպի սիւնը, ոտքի էր կանգնում, իւրաքանչիւրը երկրպագում էր իր վրանի դռան մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Տէրը Մովսէսի հետ խօսում էր դէմ յանդիման, ինչպէս մէկը կը խօսէր իր բարեկամի հետ, եւ ապա Մովսէսը վերադառնում էր բանակատեղի: Բայց նրա սպասաւոր Յեսուն՝ Նաւէի որդին, վրանից դուրս չէր գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Մովսէսն ասաց Տիրոջը. «Ահա ինձ ասում ես. «Տա՛ր այս ժողովրդին», բայց դու չես յայտնել, թէ ում ես ուղարկելու ինձ հետ: Դու ինձ ասացիր՝ «Քեզ բոլորից բարձր եմ դասում, դու վայելում ես իմ շնորհը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Արդ, եթէ քո շնորհին եմ արժանացել ես, ինձ յայտնապէս երեւայ, որպէսզի իմանամ, թէ ինչով եմ արժանացել քո շնորհին, իմանամ, որ քո այս ժողովուրդը մեծ ազգ է լինելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Տէրն ասաց. «Ես ինքս պիտի գնամ քո առաջից ու պիտի տեղաւորեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Մովսէսն ասաց նրան. «Եթէ դու ինքդ մեզ հետ չգնաս, ուրեմն ինձ այստեղից մի՛ հանիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Եւ ինչի՞ց պիտի իմացուի, թէ ես ու քո ժողովուրդն, իրօք, քո շնորհին ենք արժանացել: Եթէ դու մեզ հետ գնաս, ես ու քո ժողովուրդը կը փառաւորուենք շատ աւելի, քան երկրի վրայ եղած բոլոր ազգերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Տէրն ասաց Մովսէսին. «Այդ քո ասածն էլ կը կատարեմ, որովհետեւ դու իմ շնորհին ես արժանացել, եւ քեզ աւելի եմ ճանաչում, քան մնացած բոլորին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Մովսէսն ասաց. «Ցո՛յց տուր ինձ քո փառքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Տէրն ասաց. «Ես իմ փառքով կ՚անցնեմ քո առաջից, քո առաջ կը կոչեմ իմ անունը՝ Տէր, կ՚ողորմեմ նրան, ում ողորմելու եմ, եւ կը գթամ նրան, ում գթալու եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Եւ Տէրն աւելացրեց. «Դու չես կարող տեսնել իմ երեսը, որովհետեւ մարդ չի կարող տեսնել իմ երեսն ու կենդանի մնալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Տէրը շարունակեց. «Ահա իմ առաջ մի տեղ կայ, կանգնի՛ր այս ժայռի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Երբ ես անցնեմ իմ փառքով, քեզ կը դնեմ ժայռի ծերպի մէջ եւ իմ ձեռքով կը ծածկեմ քեզ, մինչեւ որ անցնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Իմ ձեռքը քո վրայից կը վերցնեմ, եւ ապա դու ինձ կը տեսնես թիկունքից: Բայց իմ դէմքը քեզ չի երեւայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Տէրն ասաց Մովսէսին. «Դու ինքդ նախկին տախտակների նման քարէ երկու տախտակներ կոփի՛ր եւ ինձ մօտ՝ լեռը բարձրացի՛ր: Տախտակների վրայ կը գրեմ այն պատգամները, որ արձանագրուած էին քո ջարդուփշուր արած նախկին տախտակների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Պատրա՛ստ եղիր վաղը, որ վաղ առաւօտեան բարձրանաս Սինա լեռը եւ այնտեղ ինձ սպասես լերան գագաթին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Հետդ ոչ ոք թող չբարձրանայ, ոչ ոք ամենեւին չերեւայ լերան վրայ: Արջառ ու ոչխար չարածեն լերան մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Մովսէսը նախկինների նմանութեամբ քարէ երկու տախտակներ կոփեց: Առաւօտեան վեր կենալով՝ Մովսէսը բարձրացաւ Սինա լեռը, ինչպէս Տէրն էր հրամայել նրան: Մովսէսն իր հետ վերցրեց քարէ երկու տախտակները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Տէրն իջաւ ամպի մեջ, կանգնեց այնտեղ՝ նրա դիմաց, ու կոչեց իր անունը՝ Տէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Տէրն անցաւ Մովսէսի առաջ՝ ասելով. «Տէր Աստուած եմ, գթացող եւ ողորմած, համբերատար, բարեգութ ու ճշմարիտ, որ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'արդարութիւնն է պաշտպանում, իր ողորմածութիւնն է ցուցաբերում հազարաւոր սերունդների հանդէպ, վերացնում անօրէնութիւնները, անիրաւութիւններն ու մեղքերը, մեղաւորին չի ազատում պատժից, հայրերի գործած մեղքերը բարդում է որդիների եւ որդիների որդիների վրայ մինչեւ երրորդ ու չորրորդ ս»րունդը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Մովսէսն իսկոյն խոնարհուելով՝ երկրպագութիւն արեց');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'ու ասաց. «Տէ՛ր, եթէ քո շնորհին եմ արժանացել, ուրեմն իմ Տէրը մեզ հետ թող գնայ, որովհետեւ այս ժողովուրդը կամակոր է: Դու կը ներես մեր անօրէնութիւններն ու մեղքերը, եւ մենք կը լինենք քոնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Տէրն ասաց Մովսէսին. «Ահա ես քո ու ամբողջ ժողովրդի առաջ քեզ հետ ուխտ եմ դնում: Ես այնպիսի զարմանահրաշ գործեր պիտի անեմ, որ ամբողջ երկրի վրայ եւ բոլոր ազգերի մէջ չեն կատարուել: Ամբողջ ժողովուրդը, նրանց թւում նաեւ դու, ականատես պիտի լինէք Տիրոջ գործերին: Որովհետեւ ձեզ համար »ս զարմանահրաշ գործ»ր պիտի ան»մ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Ըստ ամենայնի դու ուշադիր եղիր, թէ ինչ եմ կարգադրելու քեզ այսօր: Ես, ահա, ձեզնից հեռացնելու եմ ամորհացիներին, քանանացիներին, քետացիներին, փերեզացիներին, խեւացիներին, գերգեսացիներին ու յեբուսացիներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Զգո՛յշ եղիր, ուխտ չկապես այն երկրի բնակիչների հետ, ուր մուտք ես գործելու: Չլինի թէ գայթակղուէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Քարուքանդ կ՚անէք նրանց բագինները, ջարդուփշուր կ՚անէք նրանց արձանները, ամբողջովին կը կտրէք նրանց սրբազան անտառները եւ կրակի կը տաք նրանց աստուածների արձանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Օտար աստուածների չերկրպագէք, որովհետեւ Տէր Աստուածը նախանձոտ է, այո՛, Աստուած նախանձոտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Չլինի թէ ձեր մարդիկ ուխտ կապեն այդ երկրի բնակիչների հետ եւ նրանց աստուածներին պաշտամունք մատուցելով՝ պոռնկանան, զոհեր մատուցեն նրանց աստուածներին, եւ նրանց հրաւէրն ընդունելով՝ չլինի թէ դու էլ ուտես նրանց զոհաբերած անասունների մսից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'քո տղաներին ամուսնացնես նրանց դուստրերի հետ, քո դուստրերին կնութեան տաս նրանց տղաներին, քո դուստրերը նրանց աստուածներին պաշտամունք մատուցելով՝ պոռնկանան ու պոռնկացնեն նաեւ քո՛ տղաներին՝ աստուածներին պաշտամունք մատուցելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Քեզ համար աստուածների կուռքեր չձուլես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Կը պահես Բաղարջակերաց տօնը. նոր բերք քաղելու ամսին, ինչպէս պատուիրել եմ քեզ, եօթը օր բաղարջ հաց կ՚ուտես, քանի որ նոր բերք քաղելու ամսին ես դուրս եկել Եգիպտոսից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Ինձ պիտի պատկանեն բոլոր մարդկանց անդրանիկ արու զաւակները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'նաեւ՝ քո անասունների՝ արջառի ու ոչխարի առաջնածին արուները: Էշի առաջնածինին կը փոխանակես գառով, իսկ եթէ չփոխանակես այն, ինձ կը տաս դրա փոխարժէքը: Քո որդիների բոլոր անդրանիկների փրկագինը կը տաս ինձ: Իմ առաջ ձեռնունայն չերեւաս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Վեց օր կ՚աշխատես, իսկ եօթներորդ օրը կը հանգստանաս: Կը հանգստանաս նաեւ ցանքի ու հնձի ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Եօթնօրեակի տօնը ինձ համար կը կատարես ցորենի հնձի սկզբում, իսկ բերքահաւաքի տօնը՝ տարուայ կէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Տարին երեք անգամ քո բոլոր արու երեխաները թող ներկայանան Իսրայէլի տէր Աստծուն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'որովհետեւ ես ազգեր պիտի հեռացնեմ քո մօտից, պիտի ընդարձակեմ քո սահմանները, ոչ ոք աչք չպիտի ունենայ քո երկրի վրայ, եթէ տարուայ մէջ երեք անգամ ներկայանաս տէր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Ինձ զոհաբերած անասունի արիւնը թթխմորով հացի վրայ չթափես, եւ զատկի տօնի զոհը մինչեւ առաւօտ չմնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Քո երկրի առաջին բերքը կը տանես քո տէր Աստծու տունը:Գառը իր մօր կաթի մէջ չեփես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Տէրն այնուհետեւ ասաց Մովսէսին «Գրի՛ առ այդ պատգամները, որովհետեւ այդ խօսքերով եմ ես ուխտ կապում քեզ հետ եւ Իսրայէլի հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Մովսէսը Տիրոջ հետ էր քառասուն օր ու քառասուն գիշեր: Նա հաց չկերաւ, ջուր չխմեց եւ տախտակների վրայ գրի առաւ ուխտի խօսքերը՝ տասը պատուիրանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Երբ Մովսէսն իջնում էր Սինա լեռից, ուխտի երկու տախտակները Մովսէսի ձեռքին էին: Լեռից իջնելիս Մովսէսը չգիտէր, որ Տիրոջ հետ խօսելու պատճառով իր երեսը ճառագում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Ահարոնն ու բոլոր իսրայէլացիները, տեսնելով Մովսէսի ճառագող երեսը, վախեցան մօտենալ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Մովսէսը կանչեց նրանց. Ահարոնն ու ժողովրդի բոլոր առաջնորդները գնացին նրա մօտ, եւ Մովսէսը խօսեց նրանց հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Ապա նրան մօտեցան բոլոր իսրայէլացիները, եւ Մովսէսը պատմեց նրանց այն ամէնը, ինչ Տէրը խօսել էր իր հետ Սինա լերան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Երբ Մովսէսը նրանց հաղորդած իր խօսքը վերջացրեց, երեսը ծածկեց քօղով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Երբ Մովսէսը Տիրոջ հետ խօսելու համար ներկայանում էր նրան, հանում էր քօղը մինչեւ այնտեղից հեռանալը: Եւ երբ հեռանում էր այնտեղից, նա բոլոր իսրայէլացիներին հաղորդում էր այն, ինչ Տէրը հրամայել էր իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Իսրայէլացիները տեսնում էին, որ Մովսէսի երեսը ճառագում է: Մովսէսն այն ժամանակ քօղով ծածկում էր երեսը մինչեւ խօսելու համար նրա մօտ մտնելը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Մովսէսը հաւաքեց ամբողջ իսրայէլացի ժողովրդին ու ասաց նրանց. «Ահա այն բաները, որ Տէրն ասաց, որ պէտք է անել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, '«Վեց օր պիտի աշխատէք, իսկ եօթներորդ օրը պիտի հանգստանաք. շաբաթ օրը սուրբ է՝ Տիրոջ հանգստեան օրը: Ով որ այդ օրն աշխատի, կը մեռնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Շաբաթ օրը ձեր բոլորի տներում կրակ չպիտի վառուի, որովհետեւ ե՛ս եմ Տէրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Մովսէսը, դիմելով իսրայէլի ամբողջ ժողովրդին, ասաց. «Այս է այն պատգամը, որ պատուիրել է Տէրը՝ ասելով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '«Դուք ձեր մէջ տուրք հաւաքեցէ՛ք Տիրոջ համար: Ում սրտով ինչ անցնի, այն թող նուիրի Տիրոջը. ոսկի, արծաթ, պղինձ, կապոյտ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'ծիրանի եւ կրկնակի կարմիր գոյնի մանուած թելեր, նրբահիւս բեհեզ, այծի մազ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'խոյի կարմիր ներկուած մորթի, կապոյտ ներկուած մորթիներ, կարծր փայտեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'լուսաւորութեան համար ձէթ, օծութեան իւղի համար համեմունքներ, խնկի բաղադրամասեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'սարդիոն քարեր, զմրուխտ քարեր, վակասի եւ երկարաւուն պատմուճանի համար քարեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, '«Ձեր միջի խելահասները թող գան ու անեն այն ամէնը, ինչ պատուիրել է Տէրը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'վրանն ու նրա ծածկը, նրա ծոպաւոր վարագոյրներն ու օղակները, նրա տախտակներն ու նիգերը, նրա մոյթերն ու խարիսխները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'վկայութեան տապանակը, նրա լծակները, կափարիչը, քօղը, բակի առագաստն ու նրա մոյթերը, զմրուխտ քարերը, խնկերը, օծութեան իւղը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'զոհասեղանն ու նրա ամբողջ սպասքը, զոհասեղանի ամպհովանին, նրա լծակներն ու ամբողջ սպասքը, առաջաւորութեան հացը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'լոյսի աշտանակն ու նրա բոլոր մասերը, նրա կանթեղներն ու լուսաւորութեան ձէթը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'խնկարկութեան սեղանն ու նրա լծակները, օծութեան իւղը, խնկերի համեմունքները, վրանի դռան վարագոյրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'ողջակէզների զոհասեղանն ու նրա պղնձէ կասկարան, նրա լծակներն ու ամբողջ սպասքը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'աւազանն ու նրա պատուանդանը, բակի առագաստը, նրա մոյթերն ու խարիսխները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'բակի դռան առագաստը, վրանի ցցերն ու բակի ցցերը, դրանց պարանները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'այն զգեստները, որոնցով սրբազան պաշտամունք պիտի կատարեն սրբարանում, Ահարոն քահանայի սրբազան զգեստներն ու Ահարոնի որդիների քահանայութեան զգեստները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Բոլոր իսրայէլացիները գնացին Մովսէսի մօտից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'եւ ամէն մէկը բերեց իր սրտից բխածը. նրանք Տիրոջն էին նուիրաբերում այն ամէնը, ինչ անհրաժեշտ էր վկայութեան խորանի, նրա կահաւորանքի, բոլոր սրբազան զգեստների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Բոլոր տղամարդիկ, ում մտքով ինչ որ անցնում էր, բերեցին: Ոմանք՝ իրենց կանանց թանկագին քարերը, գինդերը, մատանիները, ծամակալները, մանեակներն ու ամէն տեսակ ոսկէ զարդեր: Բոլոր տղամարդիկ իրենց ունեցած ոսկէ իրերը նուիրաբերում էին Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Ամէն տղամարդ, ում մօտ կային կապոյտ, ծիրանի եւ կարմիր գոյնի մանուած թելեր, նրբահիւս բեհեզ, այծի մազ, խոյերի կարմիր ներկուած մորթիներ, կապոյտ ներկուած մորթիներ, բերում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Նուիրաբերողները արծաթէ ու պղնձէ նուէրներ էին բերում Տիրոջը: Ում մօտ կահոյքի համար պիտանի կարծր փայտ կար, բերում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Բոլոր շնորհալի կանայք իրենց ձեռքով կապոյտ, ծիրանի ու կարմիր գոյնի թելեր ու բեհեզ էին հիւսում եւ նուէր բերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Բոլոր կանայք յօժարակամ այծերի մազ էին մանում հմտութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Ցեղապետները բերում էին զմրուխտէ քարեր, վակասի ու լանջապանակի համար անհրաժեշտ քարեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'խնկերի համար համեմունքներ, լուսաւորութեան համար ձէթ ու օծութեան իւղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Բոլոր տղամարդիկ ու կանայք յօժարակամ գալիս էին կատարելու այն բոլոր գործերը, որ Տէրը պատուիրել էր անել Մովսէսի միջոցով: Իսրայէլացիները նուէրներ էին մատուցում Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Մովսէսն ասաց իսրայէլացիներին. «Տեսէ՛ք, Աստուած ընտրել է յատկապէս Յուդայի ցեղից Բեսելիէլին՝ Ուրիի որդուն, որը որդին էր Ովրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Աստուած նրան լցրել է ամէն ինչի համար անհրաժեշտ աստուածային իմաստութեան ոգով, հանճարով եւ գիտութեամբ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'որպէսզի նա ամէն մի գործ կատարի հմտութեամբ, մշակի ոսկին, արծաթն ու պղինձը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'տաշի թանկարժէք քարերը, մշակի փայտը եւ ամէն մի գործ կատարի վարպետօրէն, որովհետեւ Տէրը նրան իմաստութիւն է պարգեւել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'ինչպէս որ Դանի ցեղից Աքիսամի որդի Եղիաբին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'որոնց իմաստուն միտք պարգեւեց, որպէսզի սրանք սովորեն ու կատարեն սուրբ գործի համար անհրաժեշտ ամէն տեսակ գործեր՝ ոստայնանկութիւն անեն կապոյտ, ծիրանի ու կարմիր ներկուած թելերով եւ բեհեզով, նկարեն, քանդակեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Բեսելիէլը, Եղիաբն ու ընդունակ բոլոր տղամարդիկ, որոնց Տէրը գործի մէջ խելամուտ լինելու համար իմաստութիւն եւ գիտութիւն էր պարգեւել, ըստ ամենայնի կատարեցին սրբարանը հանդերձաւորելու աշխատանքները այնպէս, ինչպէս հրամայել էր Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Մովսէսը կանչեց Բեսելիէլին, Եղիաբին ու բոլոր նրանց, ովքեր ընդունակ էին գործ անելու, եւ որոնց Աստուած իմաստութեան ոգի էր պարգեւել, բոլորին, ովքեր յօժար կամքով ուզում էին ձեռնարկել ու աւարտել այդ գործը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Նրանք Մովսէսից ստացան այն բոլոր նուէրները, որ իսրայէլացիները բերել էին սրբարանը հանդերձաւորելու համար: Ամէն առաւօտ նրանք ընդունում էին նաեւ նուիրատուների բերած նուէրները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Գալիս էին սրբարանի գործերը կատարող բոլոր վարպետները, որպէսզի իւրաքանչիւրն ըստ իր մասնագիտութեան գործադրի իր վարպետութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Նրանք խօսեցին Մովսէսի հետ ու ասացին. «Ժողովուրդը շատ աւելին է բերում, քան անհրաժեշտ է Աստծու հրամայած գործը կատարելու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Մովսէսը կարգադրեց բանակատեղիում յայտարարութիւն անել եւ ասել. «Տղամարդ լինի թէ կին, սրբարանի համար այլեւս նուէրներ չպատրաստի»: Դրանից յետոյ ժողովրդին արգելեցին նուէրներ բերել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Բերում էին միայն իրենց արդէն իսկ գործածները, որպէսզի աւարտեն բոլոր գործերը: Եւ մարդիկ դադարեցին բերելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Գործի ընդունակ բոլոր մարդիկ արհեստաւորների հետ նրբահիւս բեհեզից, կապոյտ, ծիրանի ու կրկնակի կարմիր կտաւից պատրաստեցին տասշերտանի խորանը, այն զարդարեցին ասեղնագործ քերովբէներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Մէկ շերտի երկարութիւնը քսանութ կանգուն էր, իսկ լայնութիւնը՝ չորս կանգուն: Բոլոր շերտերի չափսը նոյնն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Հինգ շերտերը միացուած էին միւս հինգ շերտերին, իսկ միւս հինգ շերտերն էլ միացուած էին միւս հնգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Նա կապոյտ ճարմանդներ դրեց մի շերտի եզրին՝ միացման տեղում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Նոյնն արեց միացուող երկրորդ շերտի արտաքին կցուածքի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Յիսուն ճարմանդ դրեց մի շերտի եւ յիսուն ճարմանդ էլ դրեց երկրորդ կցուածքի շերտի կողմից, որպէսզի ճարմանդներից իւրաքանչիւրը միանայ միւսին: Պատրաստեց ոսկէ յիսուն օղակներ եւ դրանցով շերտերը միացրեց միմեանց: Ստացուեց մի խորան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Խորանի համար այծի մազից հիւսուած ծածկեր պատրաստեց. տասնմէկ շերտից շինեց դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Մէկ շերտի երկարութիւնը երեսուն կանգուն էր, իսկ լայնութիւնը՝ չորս կանգուն: Տասնմէկ շերտերի չափսը նոյնն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Հինգ շերտերը միացրեց առանձին, եւ վեց շերտերն էլ՝ առանձին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Միացման տեղում, շերտերի եզրին դրեց յիսուն ճարմանդ եւ յիսուն ճարմանդ էլ դրեց երկրորդ կցուածքի շերտի եզրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Պատրաստեց յիսուն պղնձէ օղակներ, եւ դրանք իրար կցեց, որ վրանը միակտուր դառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Խորանի ծածկը պատրաստեց խոյերի կարմիր ներկուած մորթիներից, իսկ կապոյտ մորթուց պատրաստուած ծածկը դրեց վերին կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Խորանի երկու մոյթերը պատրաստեց կարծր փայտից եւ դրեց ուղղահայեաց դիրքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Մէկ մոյթի երկարութիւնը տասը կանգուն էր, իսկ հաստութիւնն ու լայնութիւնը՝ մէկուկէս կանգուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Ամէն մի մոյթի վրայ դրեց իրար ագուցուած երկու ծղնի: Այդպէս պատրաստեց նաեւ խորանի բոլոր մոյթերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Խորանի համար մոյթեր պատրաստեց. քսան մոյթ դրեց հարաւային կողմում եւ այդ քսան մոյթերի համար պատրաստեց քառասուն խարիսխ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'մէկ մոյթի երկու կողմերի համար՝ երկու խարիսխ եւ միւս մոյթի երկու կողմերի համար էլ՝ երկու խարիսխ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Վրանի երկրորդ՝ հիւսիսային կողմի համար պատրաստեց քսան մոյթ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'եւ արծաթէ քառասուն խարիսխ. մէկ մոյթի համար՝ երկու խարիսխ, եւ միւս մոյթի համար էլ՝ երկու խարիսխ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Վրանի յետեւի՝ ծովահայեաց կողմում դրեց վեց մոյթ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'եւ երկու մոյթ էլ դրեց վրանի անկիւններին՝ յետեւի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Ներքեւի կողմից նրանք իրար հաւասար էին: Նոյն ձեւով հաւասար էին գլխի՝ իրար միացուած կողմից: Նոյն ձեւով շինեց նաեւ երկու անկիւնների մոյթերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Այսպիսով ստացուեց ութ մոյթ: Դրանց խարիսխներն արծաթից էին, ընդամէնը տասնվեց խարիսխ. մէկ մոյթի համար՝ երկու խարիսխ, եւ երկու խարիսխ էլ՝ միւս մոյթի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Կարծր փայտից նիգեր պատրաստեց. հինգ նիգ՝ վրանի մի կողմի մի մոյթի համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'հինգ նիգ՝ վրանի երկրորդ կողմի միւս մոյթի համար, եւ հինգ նիգ՝ վրանի թիկունքի՝ ծովահայեաց կողմի մոյթի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Մէջտեղի նիգը մոյթերի մի ծայրից մինչեւ միւսն անցկացնելով՝ միացրեց իրար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Երկու մոյթերը պատեց ոսկով: Ոսկուց պատրաստեց նրանց երկու օղակները, որոնց մէջ մտնում էին նիգերը: Նիգերը պատեց ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից վարագոյր պատրաստեց: Այն զարդարեց ասեղնագործուած քերովբէով');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'եւ ամրացրեց կարծր փայտից շինուած չորս մոյթերի վրայ: Դրանց խոյակները ոսկուց էին, իսկ չորս խարիսխները՝ արծաթից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Վկայութեան խորանի դռան առագաստը պատրաստեց կապոյտ, ծիրանի ու կարմիր կտաւից եւ նրբահիւս բեհեզից՝ վրան ասեղնագործուած քերովբէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Շինեց խորանի հինգ մոյթերն ու դրանց օղակները, դրանց խոյակները պատեց ոսկով: Դրանց պղնձէ խարիսխները հինգն էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Բեսելիէլը տապանակը կառուցեց կարծր փայտից. երկուսուկէս կանգուն էր դրա երկարութիւնը, մէկուկէս կանգուն էր դրա լայնութիւնը, մէկուկէս կանգուն էր դրա բարձրութիւնը: Այն ներսից ու դրսից պատեց ոսկով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'դրա վրայ շուրջանակի ոսկէ պսակ շինեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Չորս ոսկէ օղակներ ձուլեց դրա չորս կողմերի համար. երկու օղակներ՝ մի կողմից, եւ երկու օղակներ՝ միւս կողմից: Դրանք հագցրեց լծակներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Լծակները շինեց կարծր փայտից եւ դրանք պատեց ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Լծակները տապանակի կողքերից մտցրին օղակների մէջ, որպէսզի դրանցով բարձրացնեն այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Տապանակի կափարիչը պատրաստեցին մաքուր ոսկուց. երկուսուկէս կանգուն էր դրա երկարութիւնը, մէկուկէս կանգուն՝ դրա լայնութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Կափարիչի երկու ծայրերի երկու քերովբէները պատրաստեց ոսկուց. կատարեալ մի գործ շինեց դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Մի քերովբէն դրուած էր կափարիչի մի ծայրին, իսկ միւս քերովբէն՝ կափարիչի միւս ծայրին: Երկու քերովբէները միաձոյլ էին կափարիչի երկու ծայրերի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Քերովբէները դէպի վեր էին տարածել իրենց թեւերը եւ իրենց թեւերով հովանի էին անում կափարիչի վրայ: Կափարիչի վրայ քերովբէների դէմքերը իրար դէմ դիմաց էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Առաջաւորութեան սեղանը պատրաստեց մաքուր ոսկուց: Դրա համար ոսկէ չորս օղակներ ձուլեց. երկուսը՝ մի կողմի, եւ երկուսը՝ միւս կողմի համար: Պատրաստեց նաեւ լծակներ, որպէսզի դրանցով բարձրացնեն սեղանը: Տապանակի ու սեղանի լծակները պատրաստեց կարծր փայտից եւ դրանք պատեց ոսկով: Երկու կանգուն էր ս»ղանի »րկարութիւնը« մէկուկէս կանգուն՝ դրա լայնութիւնը, եւ մէկուկէս կանգուն՝ դրա բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Այն պատեց մաքուր ոսկով եւ դրա համար շուրջանակի ոսկէ պսակներ պատրաստեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Դրա վրայ շուրջանակի, մէկ թզաչափ բարձրութեամբ շրջանակ դրեց եւ դրա շրջանակի չորս կողմը ոսկէ պսակներ դրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Սեղանի համար ոսկէ չորս օղակներ պատրաստեց եւ օղակներն ամրացրեց չորս անկիւններին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'որոնք նրա չորս ոտքերի վրայ էին՝ պսակի տակ: Օղակները լծակների համար իբրեւ ագոյց ծառայեցին, որպէսզի մարդիկ լծակներից բռնած բարձրացնեն սեղանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Կարծր փայտից երկու լծակներ պատրաստեց, որպէսզի դրանցով բարձրացնեն սեղանը, եւ դրանք պատեց ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Մաքուր ոսկուց պատրաստեց սեղանի անօթները՝ դրա խնկամաններն ու սկուտեղները, դրա գաւաթներն ու սկիհները, որոնցով գինի են մատուցում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Ոսկուց պատրաստեց լոյսի միաձոյլ աշտանակը՝ բունն ու նրա երկու կողմերի ճիւղերը: Աշտանակի բնից բաժանւում էին ճիւղերը՝ երեքը մի կողմից, եւ երեքը միւս կողմից՝ իրար հաւասար: Ոսկուց պատրաստեց դրա բոլոր միաձոյլ, ընկուզաձեւ ծայրեր ունեցող լուսակալները, դրա ճրագակալները, որոնց վրայ ճրագամանն»րն »ն դրւում« »ւ աշտանակի »օթն»րորդ կանթ»ղը« որը բնի ամենավերին մասում է դրւում: Մաքուր ոսկուց պատրաստեց դրա վրայ գտնուող եօթը ճրագամանները, ունելիներն ու մոխրակալները: Քանդակազարդ արեց աշտանակը, բունն ու նրա ճիւղերը, նրա սկահակները: Գնդիկներն ու շուշանաձ»ւ ծաղիկն»րը միաձոյլ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Վեց ճիւղեր էին բաժանւում նրա երկու կողմերից. երեք ճիւղը՝ աշտանակի մի կողմից, եւ երեք ճիւղը՝ աշտանակի միւս կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Մի ճիւղն ունէր գնդիկից ու շուշանաձեւ ծաղկից բաղկացած երեք ընկուզաձեւ սկահակ, եւ միւս ճիւղն էլ ունէր գնդիկից ու շուշանաձեւ ծաղկից բաղկացած երեք ընկուզաձեւ սկահակ: Այսպէս բոլոր վեց ճիւղերը բաժանուած էին աշտանակի երկու կողմերից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Աշտանակի բնի վրայ քանդակուած էին ընկուզաձեւ չորս սկահակներ իրենց գնդիկներով ու շուշանաձեւ ծաղիկներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Երկու ճիւղերի տակ մէկական գնդիկ ու ծաղիկ՝ բնին ձուլուած: Այսպէս էին բնից բաժանուած վեց ճիւղերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Դրանց գնդիկներն ու ծաղիկները միաձոյլ էին՝ բոլորը քանդակուած մի կտոր մաքուր ոսկուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Դրա եօթը ճրագամանները, ունելիներն ու մոխրակալները մաքուր ոսկուց էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Մի տաղանդ մաքուր ոսկուց պատրաստեց աշտանակն ու դրա բոլոր մասերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Նա ոսկեպատ զոհասեղանը պատրաստեց կարծր փայտից: Այն քառակուսի էր. հինգ կանգուն էր երկարութիւնը, հինգ՚ կանգուն՝ լայնութիւնը, եւ երեք կանգուն՝ բարձրութիւնը: Դրա եղջիւրաւոր անկիւնները զոհասեղանի հետ միաձոյլ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Մաքուր ոսկով պատեց այն, ինչպէս նաեւ դրա կափարիչը, բոլոր կողերն ու եղջիւրաւոր անկիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Դրա չորս կողմերի համար պատրաստեց ոսկէ պսակներ, պսակների տակ, երկու կողմերին երկու ոսկէ օղակներ ամրացրեց, որպէսզի այն բարձրացնելիս լծակները մտցնեն այդ օղակների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Լծակները պատրաստեց կարծր փայտից եւ դրանք պատեց ոսկով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Նա վարպետ իւղագործների՛ նման պատրաստեց օծութեան սուրբ իւղը եւ խնկերի համեմունքները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Զոհասեղանը պղնձապատեց այն բուրվառների պղնձով, որոնք Կորխի ժողովրդի հետ ապստամբած մարդկանց ձեռքին էին: Կարծր փայտից պատրաստեց այն: Զոհասեղանը քառակուսի էր. հինգ կանգուն էր դրա երկարութիւնը, հինգ կանգուն՝ լայնութիւնը, իսկ երեք կանգուն՝ բարձրութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Զոհասեղանի չորս կողմը պատրաստեց եղջիւրաւոր անկիւններ, որոնք զոհասեղանի հետ միաձոյլ էին: Նա դրանք պատեց պղնձով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Նա պատրաստեց զոհասեղանի ամբողջ սպասքը՝ խարիսխները, կափարիչը, տաշտերը, մեծ պատառաքաղներն ու բուրվառները: Դրա ամբողջ սպասքը պատրաստեց պղնձից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Նա բուրվառներից պատրաստեց զոհասեղանի ցանցաւոր կասկարաները, որոնք շրջանակի տակից հասնում էին մինչեւ զոհասեղանի մէջտեղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Զոհասեղանի կասկարայի չորս կողմերին ամրացրեց պղնձէ չորս օղակներ, որպէսզի լծակներն անցկացնեն այդ օղակների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Լծակները շինեց կարծր փայտից եւ դրանք պատեց պղնձով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Լծակներն անցկացրին զոհասեղանի կողքերին գտնուող օղակների մէջ, որպէսզի զոհասեղանը դրանցով բարձրացնեն: Այն ամբողջովին պատրաստուած էր տախտակներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Պղնձէ աւազանն ու դրա պղնձէ պատուանդանը պատրաստեց ուխտաւոր այն կանանց հայելիների պղնձից, որոնք վրանը խփած օրը վկայութեան խորանի դռան մօտ էին հաւաքուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Կառուցեց մի բակ, որ դէպի հարաւ էր նայում: Բակի առագաստները նրբահիւս բեհեզից էին՝ հարիւր կանգուն երկարութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Դրանց սիւները քսան հատ էին, դրանց պղնձէ խարիսխները՝ քսան հատ: Սիւների խարիսխներն ու խոյակները արծաթից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Հիւսիսային կողմի առագաստն ունէր հարիւր կանգուն երկարութիւն: Դրա սիւները քսան հատ էին, պղնձէ խարիսխները՝ քսան հատ: Սիւների խարիսխներն ու խոյակները արծաթից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Ծովահայեաց բակի առագաստները յիսուն կանգուն էին: Դրանց սիւները տասը հատ էին, խարիսխները՝ տասը հատ: Սիւների խարիսխներն ու խոյակները արծաթից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Արեւելեան կողմի բակի առագաստը յիսուն կանգուն էր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'յետեւի կողմի բակի առագաստները տասնհինգ կանգուն էին: Դրանց սիւները երեք հատ էին, խարիսխները՝ երեք հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Բակի դռան միւս կողմի առագաստները տասնհինգ կանգուն էին: Դրանց սիւները երեք հատ էին, խարիսխները՝ երեք հատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Խորանի չորս կողմերի բոլոր առագաստները նրբահիւս բեհեզից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Սիւների խարիսխները պղնձից էին, սիւների դրուագներն ու դրանց գալարազարդերը՝ արծաթից, դրանց խոյակները՝ արծաթապատ, բակի բոլոր սիւները՝ արծաթապատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Բակի դռան վարագոյրները կապոյտ, ծիրանի ու կարմիր կտաւից էին եւ նրբահիւս բեհեզով զարդարուած: Քսան կանգուն էր դրանց երկարութիւնը, տասնհինգ կանգուն՝ բարձրութիւնը: Դրանց լայնութիւնը հաւասար էր բակի առագաստների լայնութեանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Դրանց մոյթերը չորս հատ էին, դրանց պղնձէ խարիսխները՝ չորս հատ: Դրանց գալարազարդերը արծաթից էին, իսկ դրանց խոյակները՝ արծաթապատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Բակի ու խորանի չորս կողմերի բոլոր ցցերը պղնձից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Ահա վկայութեան խորանի կառուցման պայմանը. կառուցել այնպէս, ինչպէս Աստուած հրամայել էր Մովսէսին, որպէսզի ղեւտացիները Ահարոն քահանայի որդի Իթամարի միջոցով այնտեղ պաշտամունք կատարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Յուդայի ցեղից Բեսելիէլը՝ Ուրիի որդին, որը որդին էր Ովրի, արեց այնպէս, ինչպէս Տէրը հրամայել էր Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Բեսելիէլին օգնում էր Դանի ցեղից Աքիսամի որդի Եղիաբը, որը կապոյտ, ծիրանի ու կարմիր կտաւ եւ նրբահիւս բեհեզ գործածելով՝ կատարում էր ոստայնանկութեանը, ասեղնագործութեանն ու նկարչութեանը վերաբերող աշխատանքներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Սրբարանի բոլոր գործերի համար օգտագործուած ոսկու կշիռը, որը գոյացած էր նուէրներից, եղաւ քսանինը տաղանդ եւ եօթը հարիւր երեսուն սիկղ՝ ըստ սրբարանի սիկղի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Մարդկանցից հաւաքուած արծաթէ նուէրները կշռում էին հարիւր տաղանդ եւ հազար եօթը հարիւր եօթանասունհինգ սիկղ՝ ըստ սրբարանի սիկղի. մարդագլուխ մի դրամ՝ սրբարանի սիկղի հետ համեմատած կէս սիկղ: Քսան տարեկան եւ աւելի բարձր տարիք ունեցող մարդիկ, ովքեր անցնում էին մարդահամարից, վ»ց հարիւր »ր»ք հազար հինգ հարիւր յիսուն հոգի էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Հարիւր տաղանդ արծաթ ձուլուեց խորանի հարիւր խոյակների եւ վարագոյրի խոյակների համար.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'հարիւր տաղանդ հարիւր խոյակի համար, մէկ տաղանդ ամէն մի խոյակի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Հազար եօթը հարիւր եօթանասունհինգ սիկղը գործածուեց մոյթերի գալարազարդերի համար, ոսկով պատուեցին դրանց խոյակները եւ զարդարուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Նուիրուած պղինձը եօթանասուն տաղանդ եւ երկու հազար չորս հարիւր սիկղ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Դրանով պատրաստուեցին վկայութեան խորանի դռան խարիսխները, պղնձէ զոհասեղանը, պղնձէ զոհասեղանի կասկարան, զոհասեղանի ամբողջ սպասքը, բակի չորս կողմերի խարիսխները, բակի դռան խարիսխները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'խորանի բոլոր ցցերը, բակի չորս կողմի բոլոր ցցերը, եւ կապոյտ, ծիրանի ու կարմիր կտաւից ու նրբահիւս բեհեզից հիւսուած պարանների ծայրերի օղերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Պատրաստեց ծիսական զգեստներ, որպէսզի սրբարանում դրանցով պաշտամունք կատարեն: Պատրաստեց նաեւ սրբարանում Ահարոն քահանայի հագնելիք զգեստներն այնպէս, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Վակասը պատրաստեցին ոսկով, կապոյտ, ծիրանի ու կարմիր կտաւով եւ նրբահիւս բեհեզով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Ոսկու թերթերը թել-թել կտրում էին, որպէսզի դրանք կապեն կապոյտ, ծիրանի ու կարմիր ժապաւէնով եւ նրբահիւս բեհեզով: Նկարազարդ վակասի համար պատրաստեցին փոկեր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'որպէսզի այն ամրացնեն երկու կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Նոյն ձեւով՝ ոսկով եւ կապոյտ, ծիրանի ու կարմիր կտաւով եւ նրբահիւս բեհեզով պատրաստեցին թիկնոցը, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Ոսկով ժապաւինուած եւ ընդելուզուած զմրուխտէ երկու ակնաքարերի վրայ փորագրեցին Իսրայէլի որդիների անուններն այնպէս, ինչպէս կնիքներն են փորագրում, եւ դրանք ամրացրեցին վակասի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Իսրայէլի որդիների յիշատակի ակնաքարերը ամրացրին վակասի ուսին, ինչպէս որ հրամայել էր Տէրը Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Լանջապանակը պատրաստեցին ոսկով, կապոյտ, ծիրանի ու կարմիր կտաւով եւ նրբահիւս բեհեզով, բանուածքով, այնպէս, ինչպէս վակասն էին պատրաստել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Քառակուսի եւ կրկնածալ արեցին լանջապանակը. այն ունէր մի թզաչափ երկարութիւն եւ մի թզաչափ լայնութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Դրա վրայ կար ակնաքարերի չորս շարք: Առաջին շարքի վրայ կային սարդիոն, տպազիոն եւ զմրուխտ: Դա առաջին շարքն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Երկրորդ շարքը նռնաքար էր, շափիւղայ եւ յասպիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Երրորդ շարքը սուտակ էր, մեղեսիկ եւ ագատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Չորրորդ շարքը ոսկեքար էր, եղնգաքար եւ բիւրեղ՝ ոսկով պատուած եւ ընդելուզուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Ակնաքարերն ըստ Իսրայէլի որդիների անունների էին: Նրանց տասներկու անունները գրուած եւ փորագրուած էին ըստ տասներկու ցեղերից իւրաքանչիւրի անունների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Լանջապանակի երկու օղակների վրայ ամրացրին մաքուր ոսկուց պատրաստուած հիւսկէն շղթաներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Պատրաստեցին ոսկէ երկու կոճակներ եւ ոսկէ երկու օղակներ. ոսկէ երկու օղակներն ամրացրին լանջապանակի վերին երկու ծայրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Հիւսկէն շղթաները լանջապանակի երկու կողմերից ամրացրին երկու օղակների մէջ, իսկ երկու շղթաների ծայրերը մտցրին երկու անցքերի մէջ: Լանջապանակը դրեցին վակասի ուսերին՝ երեսի կողմից իրար դէմ դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Պատրաստեցին ոսկէ երկու այլ օղակներ եւ լանջապանակի ներսի կողմից ամրացրին վակասին կցուած մասի երկու ծայրերին: Պատրաստեցին ոսկէ երկու այլ օղակներ եւ դրեցին վակասի երկու ուսերին՝ ներսի կողմից՝ վակասի առջեւի միացման տեղում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Լանջապանակի օղակների ու վակասի օղակների միջով կապոյտ ժապաւէն անցկացնելով՝ այդ երկուսը միացրին իրար այնպէս, որ լանջապանակն ու վակասը միմեանցից չառանձնանան, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Վակասից բացի ամբողջութեամբ կապոյտ ժապաւէններով հիւսուած կտաւից ներքին պատմուճաններ պատրաստեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Դրանց օձիքը հիւսածոյ գործուածքի ճիշտ մէջտեղից էր, օձիքի բացուածքը շուրջանակի չքանդուող եզերք ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Դրանց քղանցքներին մանուած կապոյտ, ծիրանի ու կարմիր ժապաւէններով եւ նրբահիւս բեհեզով նռան ծաղկաբողբոջներ գործեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Մաքուր ոսկուց զանգակներ պատրաստեցին եւ զանգակները ներքին պատմուճանների քղանցքներին, շուրջանակի, դրեցին նռնազարդերի միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Նռնազարդերն ու զանգակները ներքին պատմուճանների քղանցքներին, շուրջանակի, յաջորդում էին միմեանց: Քահանաները պաշտամունք կատարելիս այդ զգեստները պէտք է հագնէին, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Նրանք բեհեզէ հիւսածոյ զգեստներ պատրաստեցին Ահարոնի ու նրա որդիների համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'ինչպէս նաեւ բեհեզէ ապարօշներ, բեհեզէ խոյր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'բեհեզէ անդրավարտիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Նրանց համար պատրաստեցին բեհեզից եւ մանուած կապոյտ, ծիրանի ու կարմիր ժապաւէններով հիւսուած գօտիներ՝ զարդանախշ մի գործ, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Սուրբ պսակի թիթեղը պատրաստեցին մաքուր ոսկուց եւ դրա վրայ փորագրեցին «Սրբութիւն Տեառն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Այն կապեցին կապոյտ մի ժապաւէնով, որպէսզի վերեւի կողմից ամրացնեն խոյրի վրայ, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Աւարտուեց վկայութեան խորանի ամբողջ գործը: Իսրայէլի որդիներն արեցին ամէն ինչ. ինչպէս Տէրն էր հրամայել Մովսէսին, այդպէս էլ արեցին: Նուէրներից աւելացած ոսկին նրանք վերածեցին սպասքի, որոնցով Տիրոջ առաջ պաշտամունք են կատարում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Մովսէսի մօտ, խորան բերեցին զգեստները, վրանի ծածկն ու դրա բոլոր մասերը, դրա ճարմանդները, փայտերը, միջաձողերը, դրա մոյթերը, վերջինիս խարիսխները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'խոյերի կարմիր ներկուած, մշակուած եւ անմշակ մորթիները, կապոյտ վարագոյրները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'կտակարանների տապանակը ծածկող վարագոյրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'լծակները, կափարիչը, առաջաւորութեան սեղանն ու դրա ամբողջ սպասքը, առաջաւորութեան հացը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'սուրբ աշտանակն ու դրա ճրագամանները, կանթեղներն ու դրա բոլոր մասերը, լուսաւորութեան ձէթը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'ոսկէ սեղանը, օծութեան իւղը, խնկերի համեմունքները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'վրանի դռան վարագոյրը, վրանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'պղնձէ զոհասեղանը, դրա լծակներն ու ամբողջ սպասքը, աւազանն ու դրա պատուանդանը, բակի առագաստը, դրա սիւներն ու խարիսխները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'վրանի դռան եւ բակի դռան վարագոյրները, պարաններն ու ցցերը, վկայութեան խորանի ամբողջ սպասքը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'սրբարանում պաշտամունք կատարելու սրբազան զգեստները, Ահարոն քահանայի սրբազան զգեստներն ու նրա որդիների քահանայութեան համար նախատեսուած զգեստները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Ինչ Տէրը պատուիրել էր Մովսէսին, Իսրայէլի որդիներն այդ ամէնը կատարեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Մովսէսը տեսաւ բոլոր գործերը, որ նրանք կատարել էին այնպէս, ինչպէս Տէրն էր հրամայել Մովսէսին: Նրանք ճիշտ նոյն ձեւով էին կատարել: Եւ Մովսէսն օրհնեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Տէրը խօսեց Մովսէսի հետ եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '«Առաջին ամսի առաջին օրը կը կանգնեցնես վկայութեան խորանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'այնտեղ կը դնես վկայութեան տապանակը եւ տապանակը կը ծածկես վարագոյրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Ներս կը տանես սեղանը եւ դրա վրայ կը դասաւորես հացը: Ներս կը տանես աշտանակը, դրա վրայ կը դնես նրա ճրագամանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Կը տեղաւորես ոսկէ սեղանը, որպէսզի խունկ ծխես վկայութեան տապանակի առաջ: Վարագոյրի քօղը կ՚իջեցնես վկայութեան խորանի դռան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Ողջակէզների զոհասեղանը կը դնես վկայութեան խորանի դռան մօտ եւ շուրջանակի կ՚օծես վրանն ու այն ամէնը, ինչ նրա մէջ է. դրանց չորս բոլորը կը սրբես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Աւազանը կը դնես վկայութեան խորանի ու զոհասեղանի միջեւ եւ դրա մէջ ջուր կը լցնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Բակը շուրջանակի կ՚օծես եւ կ՚իջեցնես բակի դռան քօղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Կ՚առնես օծութեան իւղը, կ՚օծես խորանն ու այն ամէնը, ինչ դրա մէջ է. կը սրբագործես դա ու դրա ամբողջ սպասքը. այնուհետեւ դրանք սրբութիւն կը լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Կ՚օծես ողջակէզների զոհասեղանն ու դրա ամբողջ սպասքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Կը սրբագործես զոհասեղանը, եւ դա սրբութիւնների սրբութիւն կը լինի: Կ՚օծես աւազանն ու նրա պատուանդանը եւ կը սրբագործես այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Ահարոնին ու նրա որդիներին կը բերես վկայութեան խորանի դուռը եւ նրանց կը լուանաս ջրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Ահարոնին կը հագցնես սրբազան պատմուճանը, կ՚օծես նրան, կը սրբագործես նրան, եւ նա ինձ համար քահանայութիւն կ՚անի: Կը բերես նրա որդիներին, նրանց կը հագցնես պատմուճաններ, կ՚օծես նրանց այնպէս, ինչպէս օծեցիր նրանց հօրը, եւ նրանք ինձ համար քահանայութիւն կ՚անեն: Նրանց քահանայական օծումը իր»նց ց»ղ»րի մէջ յաւիտ»նական թող լինի»: Ահարոնին կը հագցնես սրբազան պատմուճանը, կ՚օծես նրան, կը սրբագործես նրան, եւ նա ինձ համար քահանայութիւն կ՚անի: Կը բերես նրա որդիներին, նրանց կը հագցնես պատմուճաններ, կ՚օծես նրանց այնպէս, ինչպէս օծեցիր նրանց հօրը, եւ նրանք ինձ համար քահանայութիւն կ՚անեն: Նրանց քահանայական օծումը իր»նց ց»ղ»րի մէջ յաւիտ»նական թող լինի»: Ահարոնին կը հագցնես սրբազան պատմուճանը, կ՚օծես նրան, կը սրբագործես նրան, եւ նա ինձ համար քահանայութիւն կ՚անի: Կը բերես նրա որդիներին, նրանց կը հագցնես պատմուճաններ, կ՚օծես նրանց այնպէս, ինչպէս օծեցիր նրանց հօրը, եւ նրանք ինձ համար քահանայութիւն կ՚անեն: Նրանց քահանայական օծումը իր»նց ց»ղ»րի մէջ յաւիտ»նական թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Մովսէսն արեց այն ամէնը, ինչ Տէրը պատուիրել էր իրեն. նա հէնց այդպէս էլ արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Եգիպտացիների երկրից նրանց դուրս գալու երկրորդ տարուայ առաջին ամսին, ամսուայ սկզբին վրանը կանգնեցուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Մովսէսը կառուցեց վրանը, դրեց դրա խարիսխները եւ կանգնեցրեց դրա մոյթերը, դրանց վրայ ամրացրեց խոյակները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'տեղադրեց միջաձողերը, տասշերտանի վարագոյրը տարածեց վրանի վրայ: Վրանի ծածկոցները գցեց դրա վրայ եւ ամրացրեց վրանի ծածկերը վերեւից, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Առաւ օրէնքի քարէ տախտակները, դրեց տապանակի մէջ, նիգերն անցկացրեց տապանակի վրայ եւ կափարիչը դրեց տապանակի վրայից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Տապանակը տարաւ խորանի ներսը, վրան քաշելով վարագոյրը՝ ծածկեց վկայութեան տապանակը, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Սեղանը դրեց վկայութեան խորանի մէջ՝ խորանի հիւսիսային կողմից, խորանի վարագոյրից դուրս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Դրա վրայ Տիրոջ առաջ դասաւորեց առաջաւորութեան հացը, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Աշտանակը դրեց վկայութեան խորանի մէջ, սեղանի դիմաց, խորանի հարաւային կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Ճրագամանները դրեց դրա վրայ, Տիրոջ առաջ, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Ոսկէ սեղանը դրեց վկայութեան խորանի մէջ, վարագոյրի դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Համեմունքներից պատրաստուած խունկը դրեց դրա վրայ, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Նա կախեց խորանի դռան վարագոյրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Ողջակէզների զոհասեղանը դրեց վկայութեան խորանի դռան մօտ եւ դրա վրայ ողջակէզներ ու զոհեր մատուցեց, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Աւազանը դրեց վկայութեան խորանի ու զոհասեղանի միջեւ եւ դրա մէջ ջուր լցրեց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'որպէսզի Մովսէսը, Ահարոնն ու նրա որդիները դրանով լուանան իրենց ձեռքերն ու ոտքերը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'երբ վկայութեան խորանը մտնեն կամ երբ զոհասեղանին մօտենան պաշտամունք կատարելու: Նրանք լուացւում էին դրա միջի ջրով, ինչպէս Տէրն էր հրամայել Մովսէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Բակ կառուցեց խորանի');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'ու զոհասեղանի չորս կողմը եւ քաշեց բակի դռան վարագոյրը: Այսպիսով Մովսէսն աւարտեց իր ամբողջ գործը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Ամպը ծածկեց վկայութեան խորանը, եւ խորանը լցուեց Տիրոջ փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Մովսէսը չէր կարողանում մտնել վկայութեան խորան, որովհետեւ ամպը ծածկել էր այն, եւ խորանը լցուած էր Տիրոջ փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Երբ ամպը վերանում էր խորանի վրայից, Իսրայէլի որդիները չւում էին իրենց ամբողջ բազմութեամբ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'իսկ երբ ամպը չէր վերանում, չէին չւում մինչեւ այն օրը, որ ամպը վերանար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'որովհետեւ իսրայէլացիների ողջ երթի ընթացքում Տիրոջ ամպը ցերեկները կանգնում էր խորանի վրայ, իսկ գիշերները իսրայէլացիների առաջ դրա վրայ կրակ էր վառվում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, '');
