INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Գիրք ազգաբանութեան Յիսուս Քրիստոսի՝ Դաւթի որդու, Աբրահամի որդու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Աբրահամը ծնեց Իսահակին. Իսահակը՝ Յակոբին. Յակոբը ծնեց Յուդային եւ նրա եղբայրներին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Յուդան ծնեց Փարեսին եւ Զարային՝ Թամարից. Փարեսը ծնեց Եզրոնին. Եզրոնը ծնեց Արամին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Արամը ծնեց Ամինադաբին. Ամինադաբը ծնեց Նաասոնին. Նաասոնը ծնեց Սաղմոնին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Սաղմոնը ծնեց Բոոսին՝ Ռաքաբից. Բոոսը ծնեց Օբէդին՝ Հռութից. Օբէդը ծնեց Յեսսէին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Յեսսէն ծնեց Դաւիթ արքային: Դաւիթը ծնեց Սողոմոնին՝ Ուրիայի կնոջից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Սողոմոնը՝ Րոբովամին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Րոբովամը ծնեց Աբիային. Աբիան ծնեց Ասափին. Ասափը ծնեց Յոսափատին. Յոսափատը ծնեց Յորամին. Յորամը ծնեց Օզիային.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Օզիան ծնեց Յովաթամին. Յովաթամը ծնեց Աքազին. Աքազը ծնեց Եզեկիային.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Եզեկիան ծնեց Մանասէին. Մանասէն ծնեց Ամոսին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Ամոսը ծնեց Յոսիային. Յոսիան ծնեց Յեքոնիային եւ նրա եղբայրներին՝ Բաբելոնում գերութեան ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Բաբելոնում գերութիւնից յետոյ Յեքոնիան ծնեց Սաղաթիէլին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Սաղաթիէլը ծնեց Զորոբաբէլին. Զորոբաբէլը ծնեց Աբիուդին. Աբիուդը ծնեց Եղիակիմին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Եղիակիմը ծնեց Ազորին. Ազորը ծնեց Սադոկին. Սադոկը ծնեց Աքինին. Աքինը ծնեց Եղիուդին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Եղիուդը ծնեց Եղիազարին. Եղիազարը ծնեց Մատթանին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Մատթանը ծնեց Յակոբին. Յակոբը ծնեց Յովսէփին՝ Մարիամի մարդուն, որի նշանածն էր կոյս Մարիամը, որից ծնուեց Յիսուս, որ անուանուեց Քրիստոս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Արդ, Աբրահամից մինչեւ Դաւիթը բոլոր սերունդները՝ տասնչորս սերունդ. եւ Դաւթից մինչեւ Բաբելոնի մէջ գերութիւնը՝ տասնչորս սերունդ. Բաբելոնի մէջ գերութիւնից մինչեւ Քրիստոս՝ տասնչորս սերունդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Յիսուս Քրիստոսի ծնունդը այսպէս եղաւ. նրա մայրը՝ Մարիամը, որ Յովսէփի նշանածն էր, նախքան նրանց՝ իրար մօտենալը, Սուրբ Հոգուց յղիացած գտնուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Եւ Յովսէփը՝ նրա մարդը, քանի որ արդար էր եւ չէր կամենում նրան խայտառակել, մտածեց առանց աղմուկի արձակել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Եւ մինչ նա այս բանի մասին էր մտածում, ահա Տիրոջ հրեշտակը երազի մէջ երեւաց նրան եւ ասաց. «Յովսէ՛փ, Դաւթի՛ որդի, մի՛ վախեցիր քեզ մօտ առնելու Մարիամին՝ քո կնոջը, որովհետեւ նրա մէջ ծնուածը Սուրբ Հոգուց է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Նա մի որդի պիտի ծնի, եւ նրա անունը Յիսուս պիտի դնես, քանի որ նա պիտի փրկի իր ժողովրդին՝ իր մեղքերից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Սակայն այս ամէնը եղաւ, որպէսզի կատարուի, ինչ որ Տիրոջ կողմից ասուել էր Եսայի մարգարէի բերանով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '«Ահա կոյսը պիտի յղիանայ եւ մի որդի պիտի ծնի, եւ նրան պիտի կոչեն Էմմանուէլ, որ նշանակում է Աստուած մեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Եւ Յովսէփը քնից արթնանալով՝ արեց, ինչպէս հրամայել էր իրեն Տիրոջ հրեշտակը, եւ իր կնոջն առաւ իր մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Բայց նրա հետ չյարաբերուեց, մինչեւ Մարիամը ծնեց իր անդրանիկ որդուն եւ նրա անունը դրեց Յիսուս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Երբ Յիսուս ծնուեց Հրէաստանի Բեթղեհէմ քաղաքում, Հերովդէս արքայի օրով, ահա արեւելքից մոգեր եկան Երուսաղէմ եւ ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '«Ո՞ւր է հրեաների արքան, որ ծնուեց, որովհետեւ նրա աստղը տեսանք արեւելքում եւ եկանք նրան երկրպագելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Եւ երբ Հերովդէս արքան լսեց այս, խռովուեց, նրա հետ՝ եւ Երուսաղէմի ամբողջ ժողովուրդը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Եւ հաւաքելով բոլոր քահանայապետներին ու ժողովրդի օրէնսգէտներին՝ հարցրեց նրանց, թէ ո՞ւր պիտի ծնուի Քրիստոսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Եւ նրանք ասացին նրան. «Հրէաստանի Բեթղեհէմ քաղաքում, որովհետեւ մարգարէի միջոցով այսպէս է գրուած.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '«Եւ դու, Բեթղեհէ՛մ, Յուդայի՛ երկիր, Յուդայի քաղաքների մէջ փոքրագոյնը չես. քեզնից մի իշխան պիտի ելնի ինձ համար, որ պիտի հովուի իմ ժողովրդին՝ Իսրայէլին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Այն ժամանակ Հերովդէսը գաղտնի կանչեց մոգերին եւ նրանցից ստուգեց աստղի երեւալու ժամանակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Եւ նրանց Բեթղեհէմ ուղարկելով՝ ասաց. «Գնացէ՛ք ստոյգ իմացէք մանկան մասին եւ երբ գտնէք, տեղեկացրէ՛ք ինձ, որպէսզի ես էլ գնամ երկրպագեմ նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Եւ նրանք երբ թագաւորից լսեցին այս, գնացին: Եւ ահա այն աստղը, որ տեսել էին արեւելքում, առաջնորդեց նրանց, մինչեւ որ եկաւ կանգնեց այն տեղի վրայ, ուր մանուկն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Աստղը տեսնելուն պէս չափազանց ուրախացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Եւ երբ այն տունը մտան, տեսան մանկանը իր մօր՝ Մարիամի հետ միասին եւ ընկան ու երկրպագեցին նրան. եւ բանալով իրենց գանձատուփերը՝ նրան նուէրներ մատուցեցին՝ ոսկի, կնդրուկ եւ զմուռս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Եւ երազի մէջ Աստծուց հրաման առնելով չվերադառնալ Հերովդէսի մօտ, այլ ճանապարհով գնացին իրենց երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Եւ երբ նրանք այնտեղից գնացին, ահա Տիրոջ հրեշտակը երազի մէջ երեւաց Յովսէփին ու ասաց. «Վե՛ր կաց, վերցրո՛ւ այդ մանկանը եւ նրա մօրը ու փախի՛ր Եգիպտոս. եւ այնտեղ մնա՛ մինչեւ որ քեզ ասեմ. քանի որ Հերովդէսը փնտռում է այդ մանկանը կորստ»ան մատն»լու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Եւ նա վեր կացաւ, առաւ մանկանն ու նրա մօրը, գիշերով, եւ գնաց Եգիպտոս ու այնտեղ մնաց մինչեւ Հերովդէսի մահը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'որպէսզի կատարուի մարգարէի բերանով Տիրոջ կողմից ասուածը, թէ՝ Եգիպտոսի՛ց պիտի կանչեմ իմ Որդուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Այն ժամանակ, երբ Հերովդէսը տեսաւ, որ մոգերից խաբուեց, սաստիկ բարկացաւ եւ մարդ ուղարկեց ու կոտորեց այն բոլոր մանուկներին, որ Բեթղեհէմում եւ նրա սահմաններում էին գտնւում եւ երկու տարեկան ու դրանից ցած էին՝ ըստ այն ժամանակի, որն ստուգ»լ էր մոգ»րից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Այն ժամանակ կատարուեց Երեմիա մարգարէի բերանով ասուածը, թէ՝ Ռամայում մի ձայն գուժեց. ողբ ու լաց ու սաստիկ կոծ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Ռաքէլը լալիս էր իր զաւակների վրայ եւ չէր ուզում մխիթարուել, քանի որ նրանք այլեւս չկային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Երբ Հերովդէսը վախճանուեց, ահա Տիրոջ հրեշտակը երազի մէջ երեւաց Յովսէփին Եգիպտոսում եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '«Վե՛ր կաց, վերցրո՛ւ այդ մանկանն ու իր մօրը եւ վերադարձի՛ր Իսրայէլի երկիրը, որովհետեւ մեռան նրանք, որ այդ մանկան մահն էին ուզում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Եւ Յովսէփը վեր կացաւ, առաւ մանկանն ու մօրը եւ եկաւ Իսրայէլի երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Իսկ երբ լսեց, թէ Արքեղայոսը թագաւորել է Հրէաստանի վրայ իր հօր՝ Հերովդէսի փոխարէն, վախեցաւ այնտեղ գնալ. եւ երազի մէջ հրաման առնելով՝ գնաց Գալիլիայի կողմերը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'եւ եկաւ բնակուեց Նազարէթ կոչուող քաղաքում, որպէսզի կատարուի մարգարէների խօսքը, թէ՝ Նազովրեցի պիտի կոչուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Այն օրերին Յովհաննէս Մկրտիչը գալիս է քարոզելու Հրէաստանի անապատում եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '«Ապաշխարեցէ՛ք, որովհետեւ երկնքի արքայութիւնը մօտեցել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Սա՛ է այն մարդը, որի մասին Եսայի մարգարէի բերանով ասուեց. «Անապատում կանչողի ձայնն է, պատրաստեցէ՛ք Տիրոջ ճանապարհը եւ հարթեցէ՛ք նրա շաւիղները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Եւ ինքը՝ Յովհաննէսը, ուղտի մազից զգեստ ունէր եւ կաշուէ գօտի՝ իր մէջքին, իսկ նրա կերակուրն էր մորեխ ու վայրի մեղր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Այն ժամանակ նրա մօտ էին գնում բոլոր երուսաղէմացիները, ամբողջ Հրէաստանն ու Յորդանանի շրջակայքի ժողովուրդը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'մկրտւում էին նրանից Յորդանան գետում եւ խոստովանում էին իրենց մեղքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Եւ նա տեսնելով սադուկեցիներից եւ փարիսեցիներից շատերին, որոնք եկել էին իր մկրտութեանը, ասաց նրանց. «Իժերի՛ ծնունդներ, ո՞վ ձեզ սովորեցրեց փախչել վերահաս բարկութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Այսուհետեւ ապաշխարութեան արժանի գործեր կատարեցէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'եւ մի՛ յաւակնէք ասել դուք ձեզ, թէ՝ Աբրահամը մեր հայրն է. ասում եմ ձեզ, որ Աստուած կարող է այս քարերից էլ Աբրահամի որդիներ դուրս բերել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'որովհետեւ կացինն ահա ծառերի արմատին է դրուած: Ամէն ծառ, որ բարի պտուղ չի տայ, կտրւում եւ կրակն է գցւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ես ձեզ ջրով եմ մկրտում ապաշխարութեան համար, բայց ով գալիս է ինձնից յետոյ, ինձնից աւելի հզօր է, եւ ես արժանի չեմ հանելու նրա կօշիկները. նա կը մկրտի ձեզ Սուրբ Հոգով եւ հրով. նա,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'որի քամհարը իր ձեռքում է, եւ կը մաքրի իր կալը, ցորենը կը հաւաքի իր շտեմարանում եւ յարդը կ՚այրի անշէջ կրակով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Այն ժամանակ Յիսուս Գալիլիայից Յորդանան եկաւ, Յովհաննէսի մօտ՝ նրանից մկրտուելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Իսկ Յովհաննէսն ընդդիմացաւ նրան ու ասաց. «Ի՛նձ պէտք է, որ քեզնից մկրտուեմ, եւ դու ի՞նձ մօտ ես գալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Յիսուս պատասխանեց եւ ասաց նրան. «Թո՛յլ տուր հիմա, որովհետեւ այսպէս վայել է, որ մենք կատարենք Աստծու ամէն արդարութիւն»: Եւ ապա նրան թոյլ տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Եւ երբ Յիսուս մկրտուեց, իսկոյն ջրից դուրս ելաւ. եւ ահա երկինքը բացուեց նրան, եւ նա տեսաւ Աստծու Հոգին, որն իջնում էր ինչպէս աղաւնի եւ գալիս էր իր վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Եւ ահա՝ մի ձայն երկնքից, որ ասում էր. «Դա՛ է իմ սիրելի Որդին, որն ունի իմ ամբողջ բարեհաճութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Դրանից յետոյ Յիսուս անապատ տարուեց Հոգուց՝ սատանայից փորձուելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Եւ քառասուն օր ու քառասուն գիշեր ծոմ պահեց, ապա քաղց զգաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Եւ փորձիչը՝ սատանան, մօտենալով նրան՝ ասաց. «Եթէ Աստծու Որդին ես, ասա՛, որ այս քարերը հաց լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Նա պատասխանեց եւ ասաց. «Գրուած է՝ միայն հացով չի ապրի մարդ, այլ՝ այն ամէն խօսքով, որ դուրս է գալիս Աստծու բերանից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Ապա սատանան նրան տարաւ սուրբ քաղաքը եւ կանգնեցրեց նրան տաճարի աշտարակի վրայ ու ասաց նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, '«Եթէ Աստծու Որդին ես, քեզ այստեղից ցա՛ծ գցիր, որովհետեւ գրուած է՝ իր հրեշտակներին պատուիրուած է քո մասին, եւ ձեռքերի վրայ պիտի վերցնեն քեզ, որպէսզի երբեք քո ոտքը քարին չխփես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Յիսուս դարձեալ նրան ասաց. «Գրուած է՝ քո Տէր Աստծուն պիտի չփորձես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Սատանան նորից նրան առաւ տարաւ մի շատ բարձր լերան վրայ եւ ցոյց տուեց նրան աշխարհի բոլոր թագաւորութիւններն ու դրանց փառքը եւ նրան ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, '«Այս բոլորը քեզ կը տամ, եթէ գետին ընկնելով ինձ պաշտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Այն ժամանակ Յիսուս նրան ասաց. «Ետե՛ւս գնա, սատանա՛, որովհետեւ գրուած է՝ պիտի երկրպագես քո Տէր Աստծո՛ւն եւ միայն նրա՛ն պիտի պաշտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Ապա սատանան նրան թողեց. եւ ահա հրեշտակներ մօտեցան ու ծառայում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Եւ երբ Յիսուս լսեց, թէ Յովհաննէսը բանտարկուել է, մեկնեց գնաց Գալիլիա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Եւ թողնելով Նազարէթը՝ եկաւ բնակուեց Կափառնայումում, ծովեզերքի մօտ, Զաբուղոնի եւ Նեփթաղիմի սահմաններում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'որպէսզի կատարուի Եսայի մարգարէի բերանով ասուած խօսքը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '«Երկի՛ր Զաբուղոնի եւ երկի՛ր Նեփթաղիմի, ճանապա՛րհ ծովի, միւս ա՛փը Յորդանանի, Գալիլիա՛ հեթանոսների,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'խաւարի մէջ նստած ժողովուրդը մեծ լոյս տեսաւ. եւ լոյս ծագեց նրանց վրայ, որ նստում էին մահուան երկրի եւ ստուերների մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Դրանից յետոյ Յիսուս սկսեց քարոզել եւ ասել. «Ապաշխարեցէ՛ք, որովհետեւ երկնքի արքայութիւնը մօտեցել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Մինչ Յիսուս Գալիլիայի ծովեզերքով քայլում էր, տեսաւ երկու եղբայրների՝ Սիմոնին, որ Պետրոս էր կոչւում, եւ նրա եղբայր Անդրէասին. ծովի մէջ ուռկան էին գցում, քանի որ ձկնորսներ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Եւ նրանց ասաց. «Իմ յետեւի՛ց եկէք, եւ ես ձեզ մարդկանց որսորդներ պիտի դարձնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Եւ նրանք իսկոյն թողնելով ուռկանները՝ գնացին նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Եւ այնտեղից առաջ գնալով, տեսաւ երկու այլ եղբայրների՝ Զեբեդէոսի որդի Յակոբոսին եւ նրա եղբայր Յովհաննէսին, մինչ նաւակի մէջ էին իրենց հօր՝ Զեբեդէոսի հետ միասին եւ իրենց ուռկանները կարգի էին բերում. եւ նրանց էլ կանչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Նրանք իսկոյն թողնելով նաւակը եւ իրենց հօրը՝ գնացին նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Եւ Յիսուս շրջում էր Գալիլիայի բոլոր կողմերը, ուսուցանում էր նրանց ժողովարաններում, քարոզում էր արքայութեան Աւետարանը եւ բժշկում ժողովրդի մէջ եղած բոլոր հիւանդութիւններն ու բոլոր ախտերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Եւ նրա համբաւը տարածուեց ամբողջ Ասորիքում. եւ նրա մօտ բերեցին բոլոր հիւանդներին, որոնք տառապում էին պէսպէս ցաւերով ու տանջանքներով. ե՛ւ դիւահարների, ե՛ւ լուսնոտների, ե՛ւ անդամալոյծների. եւ նրանց բժշկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Եւ Գալիլիայից, Դեկապոլսից, Երուսաղէմից, Հրէաստանից եւ Յորդանանի միւս կողմից բազում ժողովուրդ նրա յետեւից էր գնում. եւ բժշկեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Եւ տեսնելով ժողովրդի բազմութիւնը՝ բարձրացաւ լերան վրայ: Եւ երբ այնտեղ նստեց, նրա մօտ եկան իր աշակերտները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'եւ նա սկսեց նրանց ուսուցանել ու ասել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '- Երանի՜ հոգով աղքատներին, որովհետեւ նրանցն է երկնքի արքայութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, '- Երանի՜ սգաւորներին, որովհետեւ նրանք պիտի մխիթարուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, '- Երանի՜ հեզերին, որովհետեւ նրանք երկիրը պիտի ժառանգեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, '- Երանի՜ նրանց, որ քաղցն ու ծարաւն ունեն արդարութեան, որովհետեւ նրանք պիտի յագենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, '- Երանի՜ ողորմածներին, որովհետեւ նրանք ողորմութիւն պիտի գտնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, '- Երանի՜ նրանց, որ սրտով մաքուր են, որովհետեւ նրանք Աստծուն պիտի տեսնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, '- Երանի՜ խաղաղարարներին, որովհետեւ նրանք Աստծու որդիներ պիտի կոչուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, '- Երանի՜ նրանց, որ հալածւում են արդարութեան համար, որովհետեւ նրանցն է երկնքի արքայութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, '- Երանի՜ է ձեզ, երբ ձեզ նախատեն ու հալածեն եւ իմ պատճառով ձեր մասին ամէն տեսակ չար խօսք՝ սուտ ասեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Ցնծացէ՛ք եւ ուրախացէ՛ք, որովհետեւ երկնքում ձեր վարձը շատ է, քանի որ այսպէս հալածեցին մարգարէներին, որոնք ձեզնից առաջ են եղել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '«Դո՛ւք էք երկրի աղը. սակայն եթէ աղը անհամանայ, ինչո՞վ այն կ՚աղուի. այնուհետեւ ոչ մի բանի պիտանի չի լինի, այլ միայն դուրս կը թափուի եւ մարդկանց ոտքի կոխան կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Դո՛ւք էք աշխարհի լոյսը. մի քաղաք, որ լերան վրայ է կանգնած, չի կարող թաքնուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Եւ ճրագ վառելով կաթսայի տակ չեն դնում, այլ՝ աշտանակի վրայ, եւ նա լոյս է տալիս բոլոր նրանց, որ տան մէջ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Թող այդպէս փայլի ձեր լոյսը մարդկանց առաջ, որպէսզի տեսնեն ձեր բարի գործերն ու փառաւորեն ձեր Հօրը, որ երկնքում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, '«Մի՛ կարծէք, թէ Օրէնքը կամ մարգարէներին ջնջելու եկայ. չեկայ ջնջելու, այլ՝ լրացնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Ճշմարիտ եմ ասում ձեզ. մինչեւ որ երկինք ու երկիր անցնեն, մի յովտ իսկ, - որ մի նշանախեց է, - Օրէնքից եւ մարգարէներից չի անցնի, մինչեւ որ այս բոլորը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Ով որ այս պատուիրաններից, փոքրերի՛ց անգամ մի բան կը ջնջի եւ մարդկանց այդպէ՛ս կ՚ուսուցանի, երկնքի արքայութեան մէջ փոքր պիտի համարուի. իսկ ով կը կատարի եւ կ՚ուսուցանի, երկնքի արքայութեան մէջ նա մեծ պիտի համարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Բայց ասում եմ ձեզ, որ, եթէ ձեր արդարութիւնը աւելի չլինի, քան օրէնսգէտներինը եւ փարիսեցիներինը, երկնքի արքայութիւնը չէք մտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Լսել էք, թէ ինչ ասուեց նախնիներին. «Մի՛ սպանիր», որովհետեւ, ով որ սպանի, ենթակայ կը լինի դատաստանի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Իսկ ես ձեզ ասում եմ, թէ՝ ամէն մարդ, որ զուր տեղը բարկանում է իր եղբօր վրայ, ենթակայ կը լինի դատաստանի, եւ ով որ իր եղբօրն ասի՝ յիմար, ենթակայ կը լինի ատեանի, եւ ով որ իր եղբօրն ասի՝ ապուշ, ենթակայ կը լինի գեհենի կրակին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Եթէ սեղանի վրայ քո ընծան մատուցելու լինես եւ այնտեղ յիշես, թէ քո եղբայրը քո դէմ մի ոխ ունի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'քո ընծան թո՛ղ սեղանի առաջ եւ գնա՛ նախ հաշտուի՛ր քո եղբօր հետ եւ ապա ե՛կ քո ընծան մատուցի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Եթէ մէկը քեզ հետ խնդիր ունի եւ քեզ դատի է կանչում, մինչ նրա հետ դեռ ճանապարհին ես, եղի՛ր իրաւախոհ կանխաւ. գուցէ նա քեզ դատաւորին յանձնի, եւ դատաւորը՝ դահճին, ու դու բանտ նետուես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Ճշմարիտ եմ ասում քեզ, այնտեղից դուրս չես գայ, մինչեւ չվճարես վերջին դահեկանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Լսել էք, թէ ինչ ասուեց. «Մի՛ շնանար».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'իսկ ես ձեզ ասում եմ. ամէն մարդ, որ կնոջ նայում է նրան ցանկանալու համար, արդէն շնացաւ նրա հետ իր սրտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Եթէ քո աջ աչքը քեզ գայթակղեցնում է, հանի՛ր այն եւ դէ՛ն գցիր քեզնից. որովհետեւ քեզ համար լաւ է, որ քո անդամներից մէկը կորչի, եւ քո ամբողջ մարմինը չընկնի գեհեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Եւ եթէ քո աջ ձեռքը քեզ գայթակղեցնում է, կտրի՛ր այն եւ դէ՛ն գցիր քեզնից. որովհետեւ քեզ համար լաւ է, որ քո անդամներից մէկը կորչի, եւ քո ամբողջ մարմինը չընկնի գեհեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Արդարեւ ասուել է. «Ով որ արձակի իր կնոջը, թող նրան արձակման թուղթը տայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Իսկ ես ձեզ ասում եմ. ամէն մարդ, որ իր կնոջն արձակում է առանց պոռնկութեան պատճառի, նա՛ է, որ նրան շնութեան է մղում. եւ ով որ արձակուածին է առնում, շնանում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Լսել էք դարձեալ, թէ ինչ ասուեց նախնիներին. «Երդմնազանց մի՛ լինիր, այլ արա՛ Տիրոջն այն, ինչ երդուել ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Իսկ ես ձեզ ասում եմ՝ ամենեւի՛ն չերդուել. ո՛չ երկնքի վրայ, որովհետեւ Աստծու աթոռն է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ո՛չ երկրի վրայ, որովհետեւ նրա ոտքերին պատուանդան է, եւ ո՛չ Երուսաղէմի վրայ, որովհետեւ մեծ Արքայի քաղաքն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Եւ քո գլխով էլ չերդուես, որովհետեւ չես կարող մի մազ իսկ սպիտակ կամ սեւ դարձնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Այլ ձեր խօսքը լինի՝ այոն՝ այո, եւ ոչը՝ ոչ. որովհետեւ դրանից աւելին չարից է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Լսել էք՝ ինչ ասուեց. «Աչքի փոխարէն՝ աչք եւ ատամի փոխարէն՝ ատամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Իսկ ես ձեզ ասում եմ. չարին հակառակ չկանգնե՛լ. այլ եթէ մէկը քո աջ ծնօտին ապտակ տայ, նրան մի՛ւսն էլ դարձրու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Եւ եթէ մէկը կամենայ քեզ բռնադատել եւ քո շապիկն առնել, նրան քո բաճկո՛նն էլ թող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Եւ եթէ մէկը քեզ հարկադրի մի մղոն ճանապարհ անցնել, նրա հետ երկո՛ւ էլ գնա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Տո՛ւր նրան, ով քեզնից խնդրում է. եւ ով կամենում է քեզնից փոխ առնել, երես մի՛ դարձրու նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Լսել էք արդարեւ, թէ ինչ ասուեց. «Պիտի սիրես ընկերոջդ եւ պիտի ատես քո թշնամուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Իսկ ես ձեզ ասում եմ. սիրեցէ՛ք ձեր թշնամիներին, օրհնեցէ՛ք ձեզ անիծողներին, բարութի՛ւն արէք ձեզ ատողներին եւ աղօթեցէ՛ք նրանց համար, որ չարչարում են ձեզ եւ հալածում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'որպէսզի որդիները լինէք ձեր Հօր, որ երկնքում է. քանի որ նա իր արեգակը ծագեցնում է չարերի եւ բարիների վրայ եւ անձրեւ է թափում արդարների եւ մեղաւորների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Եթէ սիրէք միայն նրանց, որոնք ձեզ սիրում են, ձեր վարձն ի՞նչ է. չէ՞ որ մաքսաւորներն էլ նոյնն են անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Եւ եթէ միայն ձեր բարեկամներին ողջոյն տաք, ի՞նչ աւելի բան էք անում. չէ՞ որ մաքսաւորներն ու մեղաւորները նոյնն են անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Արդ, կատարեա՛լ եղէք դուք, ինչպէս որ ձեր երկնաւոր Հայրն է կատարեալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '«Զգո՛յշ եղէք, որ ձեր ողորմութիւնը մարդկանց առջեւ չանէք, որպէս թէ այն լինէր ի ցոյց նրանց. այլապէս վարձ չէք ընդունի ձեր Հօրից, որ երկնքում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Այլ երբ ողորմութիւն անես, փող մի՛ հնչեցրու քո առջեւ, ինչպէս անում են կեղծաւորները ժողովարաններում եւ հրապարակներում, որպէսզի փառաւորուեն մարդկանցից: Ճշմարիտ եմ ասում ձեզ, ա՛յդ իսկ է նրանց վարձը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Այլ երբ դու ողորմութիւն անես, թող քո ձախ ձեռքը չիմանայ, թէ ինչ է անում քո աջը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'որպէսզի քո ողորմութիւնը ծածուկ լինի, եւ քո Հայրը, որ տեսնում է, ինչ որ ծածուկ է, կը հատուցի քեզ յայտնապէս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, '«Եւ երբ աղօթես, չլինե՛ս կեղծաւորների նման, որոնք սիրում են ժողովարաններում եւ հրապարակների անկիւններում աղօթքի կանգնել, որպէսզի մարդկանց երեւան. ճշմարիտ եմ ասում ձեզ, ա՛յդ իսկ է նրանց վարձը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Այլ դու երբ աղօթես, մտի՛ր քո սենեակը, փակի՛ր քո դռները եւ ծածո՛ւկ աղօթիր քո Հօրը, եւ քո Հայրը, որ տեսնում է, ինչ որ ծածուկ է, կը հատուցի քեզ յայտնապէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Աղօթք անելիս շատախօս մի՛ լինէք ինչպէս հեթանոսները, որովհետեւ նրանք կարծում են, թէ իրենց շատ խօսքերի պատճառով լսելի կը լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Արդ, նրանց չնմանուէ՛ք, որովհետեւ ձեր Հայրը գիտէ, թէ ինչ է ձեզ պէտք, նախքան որ դուք նրանից մի բան ուզէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Եւ արդ, դուք այսպէ՛ս աղօթեցէք».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, '«Հա՛յր մեր, որ երկնքում ես. սո՛ւրբ թող լինի քո անունը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'քո թագաւորութի՛ւնը թող գայ. քո կա՛մքը թող լինի երկրի վրայ, ինչպէս որ երկնքում է՛.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'մեր հանապազօրեայ հացը տո՛ւր մեզ այսօր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'եւ ների՛ր մեզ մեր յանցանքները, ինչպէս որ մենք ենք ներում նրանց, որ յանցանք են գործում մեր դէմ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'եւ մի՛ տար մեզ փորձութեան, այլ փրկի՛ր մեզ չարից. որովհետեւ քո՛նն է թագաւորութիւնը եւ զօրութիւնը եւ փառքը յաւիտեանս. ամէն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Եթէ դուք մարդկանց ներէք իրենց յանցանքները, ձեր երկնաւոր Հայրն էլ ձեզ կը ների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Իսկ եթէ դուք մարդկանց չներէք իրենց յանցանքները, ձեր Հայրն էլ ձե՛զ չի ների ձեր յանցանքները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, '«Երբ ծոմ պահէք, տրտմերես մի՛ լինէք կեղծաւորների նման, որոնք իրենց երեսները այլանդակում են, որպէսզի մարդկանց այնպէս երեւան, թէ ծոմ են պահում. ճշմարիտ եմ ասում ձեզ, ա՛յդ իսկ է նրանց վարձը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Այլ երբ դու ծոմ պահես, օծի՛ր քո գլուխը եւ լուա՛ քո երեսը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'որպէսզի չերեւաս մարդկանց որպէս ծոմ պահող, այլ քո Հօրը՝ գաղտնաբար. եւ քո Հայրը, որ տեսնում է, ինչ որ ծածուկ է, կը հատուցի քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, '«Գանձեր մի՛ դիզէք ձեզ համար երկրի վրայ, ուր ցեց եւ ժանգ ոչնչացնում են, եւ ուր գողեր պատերն են ծակում ու գողանում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'այլ գանձեր դիզեցէ՛ք ձեզ համար երկնքում, որտեղ ո՛չ ցեց եւ ո՛չ ժանգ չեն ոչնչացնում, եւ ո՛չ էլ գողերը պատերն են ծակում ու գողանում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'քանի որ, ուր ձեր գանձերն են, այնտեղ եւ ձեր սրտերը կը լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Մարմնի ճրագը աչքն է. եթէ քո աչքը պարզ է, քո ամբողջ մարմինը լուսաւոր կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Իսկ եթէ քո աչքը պղտոր է, քո ամբողջ մարմինը խաւար կը լինի: Եւ արդ, եթէ քո մէջ եղած լոյսը խաւար է, ապա խաւարը՝ որչա՜փ եւս աւելի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, '«Ոչ ոք չի կարող երկու տիրոջ ծառայել. կա՛մ մէկին կ՚ատի եւ միւսին կը սիրի, կա՛մ մէկին կը մեծարի եւ միւսին կ՚արհամարհի. չէք կարող ծառայել Աստծուն եւ՝ մամոնային»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, '«Դրա համար ասում եմ ձեզ. ձեր կեանքի համար հոգ մի՛ արէք, թէ ի՛նչ պիտի ուտէք կամ ի՛նչ պիտի խմէք, եւ ոչ էլ ձեր մարմնի համար, թէ ի՛նչ պիտի հագնէք. չէ՞ որ կեանքը աւելին է, քան կերակուրը, եւ մարմինը՝ քան զգեստը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Նայեցէ՛ք երկնքի թռչուններին. ո՛չ վարում են, ո՛չ հնձում եւ ո՛չ էլ շտեմարանների մէջ հաւաքում. եւ ձեր երկնաւոր Հայրը կերակրում է նրանց. չէ՞ որ դուք աւելին էք, քան նրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Եւ արդ, ձեզնից ո՞վ կարող է հոգս անելով՝ իր հասակի վրայ մէկ կանգուն աւելացնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Եւ հագուստի համար ինչո՞ւ էք հոգս անում. նայեցէ՛ք վայրի շուշանին, ինչպէ՜ս է աճում. ո՛չ ջանք է թափում եւ ո՛չ հիւսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Ասում եմ ձեզ, որ Սողոմոնն իսկ, իր ամբողջ փառքի մէջ, չհագնուեց նրանցից մէկի նման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Իսկ եթէ դաշտի միջի խոտին, որ այսօր կայ եւ վաղը հնոց կը նետուի, այդպէ՛ս է հագցնում Աստուած, որքա՜ն եւս առաւել՝ ձե՛զ, թերահաւատնե՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Այսուհետեւ հոգ մի՛ արէք ու մի՛ ասէք՝ ի՛նչ պիտի ուտենք կամ ի՛նչ պիտի խմենք կամ ի՛նչ պիտի հագնենք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'որովհետեւ հեթանոսներն են այդ բոլորը որոնում. քանի որ ձեր երկնաւոր Հայրը գիտէ, թէ այդ բոլորը ձեզ պէտք է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Նախ խնդրեցէ՛ք Աստծու արքայութիւնը եւ նրա արդարութիւնը, եւ այդ բոլորը Աստուած ձեզ աւելիով կը տայ: Այսուհետեւ հոգ մի՛ արէք վաղուայ մասին, որովհետեւ վաղուայ օրը իր մասին կը հոգայ. օրուայ հոգսը բաւ է օրուայ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '«Մի՛ դատէք, որ Աստծուց չդատուէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'որովհետեւ ինչ դատաստանով, որ դատէք, նրանով էք դատուելու. եւ ինչ չափով, որ չափում էք, նրանով պիտի չափուի ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Ինչո՞ւ քո եղբօր աչքի մէջ շիւղը տեսնում ես, իսկ քո աչքի մէջ գերանը չես տեսնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'կամ ինչպէ՞ս քո եղբօրն ասում ես՝ թո՛ղ որ հանեմ այդ շիւղը քո աչքից, եւ ահա քո աչքում գերան կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Կեղծաւո՛ր, նախ հանի՛ր քո աչքից այդ գերանը եւ ապա յստակ կը տեսնես՝ քո եղբօր աչքից շիւղը հանելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Մի՛ տուէք սրբութիւնը շներին. եւ ձեր մարգարիտները խոզերի առաջ մի՛ գցէք, որպէսզի դրանք ոտքի կոխան չանեն եւ դառնալով ձեզ չպատառոտեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Խնդրեցէ՛ք Աստծուց, եւ նա կը տայ ձեզ, փնտռեցէ՛ք եւ կը գտնէք, բախեցէ՛ք, եւ կը բացուի ձեր առաջ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'որովհետեւ, ով որ ուզի, ստանում է, ով որ փնտռի, գտնում է, եւ ով որ բախի, նրա առաջ կը բացուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ձեզնից ո՞վ է այն մարդը, որից իր որդին եթէ հաց ուզի, միթէ քա՞ր կը տայ նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'եւ կամ եթէ ձուկ ուզի, միթէ օ՞ձ կը տայ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Արդ, եթէ դուք, որ չար էք, գիտէք ձեր որդիներին բարի պարգեւներ տալ, որքա՜ն եւս առաւել ձեր Հայրը, որ երկնքում է, բարիքներ կը տայ նրանց, որ նրանից ուզում են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, '«Այն ամէնը, ինչ կը կամենաք, որ մարդիկ ձեզ անեն, այդպէս եւ դո՛ւք արէք նրանց, որովհետեւ ա՛յդ իսկ են Օրէնքն ու մարգարէները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '«Մտէ՛ք նեղ դռնով. ինչքա՜ն լայն է դուռը եւ ընդարձակ՝ ճանապարհը, որ դէպի կորուստ է տանում, եւ բազմաթիւ են նրանք, որ մտնում են դրանով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Ինչքա՜ն անձուկ է դուռը եւ նեղ՝ ճանապարհը, որ տանում է դէպի կեանք, եւ սակաւաթիւ են նրանք, որ գտնում են այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, '«Զգո՛յշ եղէք սուտ մարգարէներից, որոնք մօտենում են ձեզ ոչխարների զգեստներով, բայց ներսից յափշտակող գայլեր են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Իրենց գործերի՛ց կը ճանաչէք նրանց. միթէ փշերից խաղող եւ տատասկից թուզ կը քաղե՞ն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Այսպէս, ամէն բարի ծառ բարի պտուղ է տալիս, եւ չար ծառ չար պտուղ է տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Լաւ ծառը չի կարող վատ պտուղ տալ, ոչ էլ վատ ծառը՝ լաւ պտուղ տալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Ամէն ծառ, որ բարի պտուղ չի տալիս, կտրւում եւ կրակն է նետւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Ուրեմն՝ իրենց գործերի՛ց կը ճանաչէք նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, '«Ոչ ամէն մարդ, որ ինձ «Տէ՜ր, Տէ՜ր» է ասում, երկնքի արքայութիւն կը մտնի, այլ նա՛, ով կատարում է կամքը իմ Հօր, որ երկնքում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Այն օրը շատերն ինձ պիտի ասեն. «Տէ՜ր, Տէ՜ր, չէ՞ որ քո անունով մարգարէացանք եւ քո անունով դեւեր հանեցինք եւ քո անունով բազում զօրաւոր գործեր արեցինք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Եւ այն ժամանակ ես նրանց պիտի ասեմ. «Ես ձեզ երբեք չեմ ճանաչել, հեռո՛ւ կացէք ինձանից դուք ամէնքդ, որ անօրէնութիւն էք գործում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Ով որ լսում է իմ այս խօսքերը եւ կատարում է դրանք, կը նմանուի մի իմաստուն մարդու, որ իր տունը շինեց ժայռի վրայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'անձրեւները թափուեցին, եւ գետերը յորդեցին, հողմերը փչեցին եւ զարկեցին այդ տանը, բայց չկործանուեց, որովհետեւ ժայռի վրայ էր հաստատուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Իսկ ով որ լսում է իմ այս խօսքերը եւ դրանք չի կատարում, կը նմանուի մի յիմար մարդու, որ իր տունը շինեց աւազի վրայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'անձրեւները թափուեցին, գետերը բարձրացան, հողմերը փչեցին եւ զարկեցին տանը, եւ նա ընկաւ. եւ նրա կործանումը շատ մեծ եղաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Երբ Յիսուս այս բոլոր խօսքերն աւարտեց, ժողովուրդը զարմանում էր նրա վարդապետութեան վրայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'որովհետեւ ուսուցանում էր ինչպէս մէկը, որ հեղինակութիւն ունի եւ ոչ թէ՝ ինչպէս օրէնսգէտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Երբ Յիսուս իջաւ լեռից, նրա յետեւից շատ ժողովուրդ գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Եւ ահա մի բորոտ մօտենալով՝ նրան երկրպագում էր ու ասում. «Տէ՛ր, եթէ կամենաս, կարող ես ինձ մաքրել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Յիսուս իր ձեռքը երկարեց, դիպցրեց նրան եւ ասաց. «Կամենում եմ, մաքրուի՛ր»: Եւ իսկոյն բորոտութիւնը նրանից մաքրուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Եւ Յիսուս նրան ասաց. «Զգո՛յշ եղիր, ոչ ոքի չասես, այլ գնա՛ դու քեզ ցո՛յց տուր քահանային եւ մատուցի՛ր Մովսէսի հրամայած ընծան՝ նրանց իբրեւ վկայութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Կափառնայում մտնելիս նրան մօտեցաւ մի հարիւրապետ. աղաչում էր նրան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'եւ ասում. «Տէ՛ր, ծառաս տանը անդամալոյծ ընկած է եւ չարաչար տանջւում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Յիսուս նրան ասաց. «Ես կը գամ եւ կը բժշկեմ նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Հարիւրապետը պատասխանեց եւ ասաց. «Տէ՛ր, ես արժանի չեմ, որ դու իմ յարկի տակ մտնես. այլ խօսքո՛վ ասա, եւ իմ ծառան կը բժշկուի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'քանի որ ես էլ իշխանութեան տակ եղող մարդ եմ, ինձ ենթակայ զինուորներ ունեմ. սրան ասում եմ՝ գնա՛, եւ գնում է, եւ մի ուրիշին, թէ՝ ե՛կ, եւ գալիս է. եւ իմ ծառային, թէ՝ արա՛ այս, եւ անում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Երբ Յիսուս այս լսեց, զարմացաւ եւ իր հետ գնացողներին ասաց. «Ճշմարիտ եմ ասում ձեզ, Իսրայէլի մէջ իսկ այսպիսի հաւատ չգտայ երբեք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Բայց ասում եմ ձեզ, որ արեւելքից եւ արեւմուտքից շատերը պիտի գան ու երկնքի արքայութեան մէջ սեղան պիտի նստեն Աբրահամի, Իսահակի եւ Յակոբի հետ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'իսկ արքայութեան որդիները պիտի ելնեն արտաքին խաւարը. այնտեղ պիտի լինի լաց եւ ատամների կրճտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Եւ Յիսուս հարիւրապետին ասաց. «Գնա՛, եւ ինչպէս հաւատացիր, այնպէս թող լինի քեզ»: Եւ այդ նոյն ժամին նրա ծառան առողջացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Յիսուս Պետրոսի տունը գալով՝ տեսաւ, որ նրա զոքանչը տաքութեան մէջ պառկած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Բռնեց նրա ձեռքից, եւ ջերմութիւնը նրան թողեց. ոտքի կանգնեց եւ ծառայում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Երբ երեկոյ եղաւ, նրա մօտ բազում դիւահարներ բերեցին, եւ նա խօսքով դեւերին հանեց ու բոլոր հիւանդներին բժշկեց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'որպէսզի կատարուի Եսայի մարգարէի բերանով ասուած խօսքը. «Նա մեր հիւանդութիւնները իր վրայ վերցրեց եւ մեր ցաւերը կրեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Յիսուս իր շուրջը բազում ժողովուրդ տեսնելով՝ հրամայեց միւս կողմ գնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Եւ մի օրէնսգէտ, մօտենալով, ասաց նրան. «Վարդապե՛տ, ես էլ քո յետեւից կը գամ, ուր էլ որ գնաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Յիսուս նրան ասաց. «Աղուէսները որջ ունեն, եւ երկնքի թռչունները՝ բոյն. բայց մարդու Որդին մի տեղ չունի, որ իր գլուխը դնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Եւ իր աշակերտներից մէկն ասաց. «Տէ՛ր, ինձ թո՛յլ տուր, որ գնամ նախ իմ հօրը թաղեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Յիսուս նրան ասաց. «Դու իմ յետեւի՛ց արի եւ թո՛յլ տուր, որ մեռեալնե՛րը թաղեն իրենց մեռելներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Երբ նա նաւակ մտաւ, նրա յետեւից գնացին իր աշակերտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Եւ ահա ծովի վրայ մեծ փոթորիկ առաջացաւ, այնքան, որ նաւակը ծածկուեց ալիքներից: Իսկ ինքը ննջում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Եւ աշակերտները մօտենալով՝ վեր կացրին նրան ու ասացին. «Տէ՛ր, փրկի՛ր մեզ, որովհետեւ կորչում ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Նրանց ասաց. «Ինչո՞ւ էք վախկոտ, թերահաւատնե՛ր»: Այն ժամանակ, վեր կենալով, սաստեց հողմերին եւ ծովին, ու մեծ խաղաղութիւն եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Եւ մարդիկ զարմացան ու ասում էին. «Ինչպիսի՜ մէկն է սա, որ հողմերն ու ծովը հնազանդւում են սրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Եւ երբ այն կողմ, գերգեսացիների երկիրն անցաւ, նրան պատահեցին գերեզմաններից ելած երկու դիւահար, այնքան սաստիկ կատաղած, որ այդ ճանապարհով որեւէ մէկը չէր կարող անցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Եւ ահա նրանք աղաղակեցին ու ասացին. «Ի՞նչ կայ մեր եւ քո միջեւ, Յիսո՛ւս, Որդի՛ Աստծու, մեզ տարաժամ տանջելո՞ւ եկար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Եւ նրանցից քիչ հեռու արօտական խոզերի մի երամակ կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Եւ դեւերը աղչում էին նրան ու ասում. «Թէ մեզ այստեղից հանես, մեզ թո՛յլ տուր գնալ խոզերի երամակը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Եւ նա նրանց ասաց՝ գնացէ՛ք: Դեւերը դուրս ելնելով՝ գնացին խոզերի երամակ: Եւ ամբողջ երամակը դարաւանդից դիմեց դէպի ծով, ու ջրերի մէջ սատկեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Իսկ խոզարածները փախան եւ քաղաք գնալով՝ պատմեցին ամէն ինչ, նաեւ՝ դիւահարների դէպքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Եւ ահա ամբողջ քաղաքը Յիսուսին ընդառաջ ելաւ. երբ նրան տեսան, աղաչեցին, որ իրենց սահմաններից հեռու գնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Եւ նաւակ մտնելով՝ Յիսուս անցաւ ծովի միւս կողմը. եւ եկաւ իր քաղաքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Եւ ահա նրա մօտ բերեցին մի անդամալոյծ, որ պառկած էր մահճի մէջ: Յիսուս նրանց հաւատը տեսնելով՝ ասաց անդամալոյծին. «Քո մեղքերը քեզ ներուած են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Եւ ահա օրէնսգէտներից ոմանք իրենց մտքում ասացին՝ դա հայհոյում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Եւ Յիսուս իմանալով նրանց մտածումները՝ նրանց ասաց. «Ինչո՞ւ դուք ձեր սրտերում չար բան էք խորհում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'ի՞նչն է դիւրին. ասել՝ քեզ ներուա՞ծ են քո մեղքերը, թէ՞ ասել՝ վե՛ր կաց եւ քայլի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Արդ, որպէսզի իմանաք, որ մարդու Որդին իշխանութիւն ունի երկրի վրայ մեղքերը ներելու, - ասաց նա այդ ժամանակ անդամալոյծին, - վե՛ր կաց, վերցրո՛ւ քո մահիճը եւ գնա՛ քո տունը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Եւ նա վեր կենալով՝ իր տունը գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Երբ ժողովուրդը այս տեսաւ, զարմացաւ. եւ փառաւորում էր Աստծուն՝ մարդկանց այսպիսի իշխանութիւն տուողին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Եւ Յիսուս այնտեղով անցնելով՝ տեսաւ Մատթէոս անունով մի մարդու, որ նստել էր մաքսատանը, ու նրան ասաց. «Իմ յետեւի՛ց արի»: Եւ նա վեր կենալով՝ գնաց նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Եւ երբ Յիսուս նրա տանը սեղան էր նստել, ահա բազմաթիւ մաքսաւորներ ու մեղաւորներ եկան բազմեցին Յիսուսի եւ նրա աշակերտների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Երբ փարիսեցիները այդ տեսան, ասացին նրա աշակերտներին. «Ինչո՞ւ է ձեր վարդապետը մաքսաւորների ու մեղաւորների հետ ուտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Իսկ Յիսուս, երբ լսեց, նրանց ասաց. «Առողջներին բժիշկ պէտք չէ, այլ՝ հիւանդներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Գնացէ՛ք, սովորեցէ՛ք, թէ ինչ է նշանակում՝ ողորմութիւն եմ կամենում եւ ոչ՝ զոհ. քանզի ես արդարներին կանչելու չեմ եկել, այլ՝ մեղաւորներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Այն ժամանակ Յովհաննէսի աշակերտները մօտեցան նրան եւ ասացին. «Ինչո՞ւ մենք եւ փարիսեցիները յաճախ ծոմ ենք պահում, իսկ քո աշակերտները չեն պահում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Յիսուս նրանց ասաց. «Միթէ կարելի՞ բան է, որ հարսանքաւորները սուգ պահեն, քանի փեսան նրանց հետ է. բայց կը գան օրեր, երբ փեսան նրանցից կը վերցուի, եւ ապա ծոմ կը պահեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Ոչ ոք չօգտագործուած կտաւի կտորը հնացած ձորձի վրայ չի կարկատի, քանի որ այն իր լրիւ չափով կը պատռի կը հանի զգեստից, եւ պատռուածքը աւելի վատ կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ոչ էլ նոր գինին հին տիկերի մէջ են դնում. ապա թէ ոչ տիկերը կը պատռուեն. ե՛ւ գինին դուրս կը թափուի, ե՛ւ տիկերը կը փչանան. այլ նոր գինին նոր տիկերի մէջ են լցնում, եւ երկուսն էլ պահւում են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Մինչ Յիսուս նրանց այս բաներն էր ասում, ահա մի իշխանաւոր, մօտենալով, երկրպագեց նրան ու ասաց. «Իմ դուստրը հէնց նոր մեռաւ, սակայն գայիր եւ քո ձեռքը նրա վրայ դնէիր, եւ նա կը կենդանանար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Յիսուս վեր կացաւ եւ իր աշակերտների հետ միասին գնաց նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Եւ ահա տասներկու տարուց ի վեր արիւնահոսութիւն ունեցող մի կին, յետեւից մօտենալով Յիսուսին, դիպաւ նրա զգեստի քղանցքին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'քանի որ մտքում ասում էր. «Եթէ միայն դիպչեմ նրա զգեստին, կը փրկուեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Իսկ Յիսուս, երբ դարձաւ ու նրան տեսաւ, ասաց. «Քաջալերուի՛ր, դո՛ւստր, քո հաւա՛տը քեզ փրկեց»: Եւ նոյն ժամին կինը բժշկուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Երբ Յիսուս իշխանաւորի տունը եկաւ եւ տեսաւ փողհարներին ու մեծ ամբոխ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'նրանց ասաց. «Հեռո՛ւ գնացէք, որովհետեւ այդ աղջիկը ոչ թէ մեռած է, այլ ննջում է».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'եւ նրանք ծաղրում էին նրան: Եւ երբ ամբոխը դուրս ելաւ, նա ներս մտաւ, բռնեց նրա ձեռքից, եւ աղջիկը վեր կացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Եւ այս լուրը ամբողջ այդ երկրով մէկ տարածուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Եւ մինչ Յիսուս անցնում էր այն տեղով, երկու կոյրեր գնացին նրա յետեւից. նրանք աղաղակում էին ու ասում. «Ողորմի՛ր մեզ, Դաւթի՛ Որդի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Երբ նա տուն եկաւ, կոյրերը մօտեցան նրան: Յիսուս նրանց ասաց. «Հաւատո՞ւմ էք, որ ես այդ բանը ձեզ կարող եմ անել»: Նրանք ասացին նրան՝ այո՛, Տէ՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Այն ժամանակ դիպաւ նրանց աչքերին եւ ասաց. «Ըստ ձեր հաւատի թող լինի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Եւ բացուեցին նրանց աչքերը: Եւ Յիսուս նրանց խստիւ պատուիրեց եւ ասաց. «Զգո՛յշ կացէք, ոչ ոք չիմանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Իսկ նրանք ելան եւ նրա համբաւը տարածեցին ամբողջ այդ երկրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Եւ երբ նրանք դուրս եկան, ահա նրա մօտ բերեցին մի համր, դիւահար մարդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Եւ երբ դեւը դուրս եկաւ, համրը խօսեց. եւ ժողովուրդը զարմացաւ ու ասաց. «Այսպիսի բան Իսրայէլում երբեք տեսնուած չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Իսկ փարիսեցիներն ասում էին. «Դա դեւերի իշխանի միջոցով է հանում դեւերին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Եւ Յիսուս շրջում էր բոլոր քաղաքներում եւ գիւղերում, ուսուցանում նրանց ժողովարաններում, քարոզում արքայութեան Աւետարանը եւ բժշկում էր ժողովրդի բոլոր ախտերն ու հիւանդութիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Եւ տեսնելով ժողովրդի բազմութիւնը՝ Յիսուս գթաց նրանց, որովհետեւ յոգնած էին եւ ցրուած, ինչպէս ոչխարներ, որոնք հովիւ չունեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Այն ժամանակ իր աշակերտներին ասաց. «Հունձը առատ է, իսկ մշակները՝ սակաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Արդ, աղաչեցէ՛ք հնձի Տիրոջը, որ մշակներ հանի իր հնձի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Եւ նա իր մօտ կանչելով իր տասներկու աշակերտներին՝ նրանց իշխանութիւն տուեց պիղծ դեւերի վրայ՝ հանելու դրանք եւ բժշկելու ամէն ցաւ եւ ամէն հիւանդութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Եւ տասներկու առաքեալների անունները սրանք էին. առաջին՝ Սիմոն Պետրոս կոչուածը, եւ նրա եղբայրը Անդրէաս,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Զեբեդէոսի որդի Յակոբոս եւ նրա եղբայրը Յովհաննէս, Փիլիպպոս եւ Բարթողոմէոս, Թովմաս եւ Մատթէոս մաքսաւոր, Ալփէոսի որդի Յակոբոս եւ Ղեբէոս, որ Թադէոս կոչուեց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Սիմոն Կանանացի եւ Յուդա Իսկարիովտացի, որ եւ մատնեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Նրանց Տասներկուսին Յիսուս ուղարկեց, պատուիրեց նրանց ու ասաց. «Հեթանոսների շրջաններով չգնաք եւ սամարացիների որեւէ քաղաքը չմտնէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'այլ աւելի շուտ գնացէ՛ք Իսրայէլի տան կորած ոչխարների մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Եւ երբ գնաք, քարոզեցէ՛ք եւ ասացէ՛ք. «Երկնքի արքայութիւնը մօտեցել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Հիւանդներին բժշկեցէ՛ք, բորոտներին մաքրեցէ՛ք, դեւերին հանեցէ՛ք, ձրի առաք, ձրի էլ տուէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Մի՛ ունեցէք ո՛չ ոսկի, ո՛չ արծաթ եւ ո՛չ էլ պղինձ դրամ՝ ձեր գօտիների մէջ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ո՛չ պարկ՝ ճանապարհի համար. ո՛չ երկու զգեստ, ո՛չ կօշիկներ եւ ո՛չ էլ ցուպ. որովհետեւ մշակն արժանի է իր կերակրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Որ քաղաքը կամ գիւղը մտնէք, հարցրէ՛ք, թէ ո՛վ է այնտեղ արժանաւորը, եւ այնտեղ մնացէ՛ք, մինչեւ որ այդտեղից դուրս ելնէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Եւ երբ այն տունը մտնէք, ողջո՛յն տուէք նրան ու ասացէ՛ք. «Ողջո՜յն այս տանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Եթէ տունն արժանի է, ձեր ողջոյնը նրա վրայ թող իջնի. իսկ եթէ արժանի չէ, ձեր ողջոյնը ձեզ թող վերադառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Եւ եթէ մի քաղաք չընդունի ձեզ եւ չլսի ձեր խօսքերը, այդ քաղաքից դուրս գնալիս՝ ձեր ոտքերից փոշին թօթափեցէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Ճշմարիտ եմ ասում ձեզ, սոդոմացիների եւ գոմորացիների երկրի համար աւելի հեշտ պիտի լինի դատաստանի օրը, քան այդ քաղաքի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, '«Ահա ես ձեզ ուղարկում եմ որպէս ոչխարներ՝ գայլերի մէջ: Այսուհետեւ խորագէ՛տ եղէք օձերի պէս եւ միամիտ՝ աղաւնիների նման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Զգուշացէ՛ք մարդկանցից, որովհետեւ պիտի մատնեն ձեզ ատեանների եւ պիտի տանջեն ձեզ իրենց ժողովարաններում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'ձեզ պիտի տանեն կուսակալների ու թագաւորների առաջ իմ պատճառով, որ իմ մասին վկայութիւն տաք նրանց եւ հեթանոսներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Բայց երբ ձեզ մատնեն, հոգ մի՛ արէք, թէ ինչպէս կամ ինչ պիտի խօսէք, որովհետեւ այդ ժամին ձեզ կը տրուի այն, ինչ պիտի խօսէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'քանի որ ոչ թէ դուք էք, որ պիտի խօսէք, այլ ձեր Հօր Հոգին, որ պիտի խօսի ձեր միջոցով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Եղբայրն իր եղբօրը մահուան պիտի մատնի, եւ հայրը՝ որդուն: Եւ որդիները հայրերի դէմ պիտի ելնեն ու նրանց պիտի սպանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Եւ իմ անուան համար բոլորից պիտի ատուէք. իսկ ով մինչեւ վերջ համբերի, նա պիտի փրկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Եւ երբ ձեզ հալածեն այս քաղաքում, կը փախչէք դէպի մէկ ուրիշը. եւ եթէ ձեզ դրանից էլ հալածեն, կը փախչէք դէպի այն միւսը: Ճշմարիտ եմ ասում ձեզ, Իսրայէլի քաղաքները դեռ վերջացրած պիտի չլինէք, նախքան մարդու Որդու գալը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Աշակերտը աւելին չէ, քան վարդապետը, եւ ոչ էլ ծառան՝ քան իր տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Աշակերտին հերիք է, եթէ լինի իր վարդապետի նման, եւ ծառային՝ իր տիրոջ նման. եթէ տանտիրոջը Բէեղզեբուղ կոչեցին, որչա՜փ եւս առաւել՝ նրա ընտանիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Այսուհետեւ նրանցից չվախենաք, որովհետեւ չկայ ծածուկ բան, որ չյայտնուի, եւ գաղտնի բան, որ չիմացուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ինչ ձեզ ասում եմ խաւարի մէջ, դուք ասացէք լոյսի՛ մէջ. եւ ինչ լսում էք ականջի մէջ փսփսուքով, հրապարակեցէ՛ք տանիքների վրայից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Եւ մի՛ վախեցէք նրանցից, որ մարմինն են սպանում, բայց հոգին սպանել չեն կարող. այլ դուք առաւել վախեցէ՛ք նրանից, ով կարող է գեհենի մէջ կորստեան մատնել հոգին եւ մարմինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Չէ՞ որ երկու ճնճղուկ մէկ դահեկանի է վաճառւում, բայց նրանցից մէկն անգամ առանց ձեր Հօր գետին չի ընկնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'եւ ձեր գլխի մազերը բոլորն իսկ հաշուուած են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Արդ, մի՛ վախեցէք, քանի որ բազում ճնճղուկներից լաւ էք դուք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Ով որ ինձ կը խոստովանի մարդկանց առաջ, ես էլ կը խոստովանեմ նրան իմ Հօր առաջ, որ երկնքում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Եւ ով ինձ կ՚ուրանայ մարդկանց առաջ, ես էլ նրան կ՚ուրանամ իմ Հօր առաջ, որ երկնքում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, '«Մի՛ կարծէք, թէ եկայ խաղաղութիւն հաստատելու երկրի վրայ. չեկայ հաստատելու խաղաղութիւն, այլ՝ սուր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'քանի որ եկայ, որ բաժանեմ որդուն իր հօրից, եւ դստերը՝ իր մօրից, եւ հարսին՝ իր կեսուրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Մարդու թշնամիները իր տնեցիները կը լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Ով իր հօրը եւ կամ մօրը ինձնից աւելի է սիրում, ինձ արժանի չէ. ով իր որդուն կամ դստերը ինձնից աւելի է սիրում, ինձ արժանի չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Եւ ով իր խաչը չի վերցնում ու իմ յետեւից չի գալիս, ինձ արժանի չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Ով որ իր անձը գտնում է, այն կը կորցնի. եւ ով իր անձը կորցրեց ինձ համար, այն կը գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Ով ձե՛զ է ընդունում, ի՛նձ է ընդունում, եւ ով ի՛նձ է ընդունում, ընդունում է ինձ ուղարկողի՛ն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Ով մարգարէին ընդունում է իբրեւ մարգարէի, մարգարէի վարձ կը ստանայ. ով արդարին ընդունում է իբրեւ արդարի, արդարի վարձ կը ստանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Եւ ով այս փոքրիկներից մէկին միայն մի բաժակ սառը ջուր կը տայ խմելու իբրեւ աշակերտ, ճշմարիտ եմ ասում ձեզ, իր վարձը չպիտի կորցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Եւ երբ Յիսուս վերջացրեց իր տասներկու աշակերտներին պատուէր տալը, այնտեղից գնաց՝ քարոզելու եւ ուսուցանելու շրջակայ քաղաքներում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Իսկ Յովհաննէսը, երբ բանտում լսեց Քրիստոսի գործերի մասին, ուղարկեց իր աշակերտներին եւ նրանց միջոցով ասաց նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '«Դո՞ւ ես, որ գալու էիր, թէ՞ ուրիշին սպասենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Յիսուս պատասխան տուեց նրանց եւ ասաց. «Գնացէք պատմեցէ՛ք Յովհաննէսին, ինչ որ դուք լսեցիք եւ տեսաք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'կոյրերը տեսնում են, կաղերը՝ քայլում, բորոտները՝ մաքրւում, խուլերը՝ լսում, մեռելները՝ յառնում, եւ աղքատներին քարոզւում է Աւետարանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Եւ երանի՜ է նրան, ով իմ պատճառով չի գայթակղւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Երբ Յովհաննէսի աշակերտները գնացին, Յիսուս սկսեց ժողովրդին ասել Յովհաննէսի մասին. «Ի՞նչ տեսնելու ելաք անապատում. հողմից շարժուող եղէ՞գ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Հապա ի՞նչ տեսնելու ելաք. փափուկ զգեստներով զարդարուած մա՞րդ. ահա նրանք, որ փափուկ բաներ են հագել, թագաւորների պալատներում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ապա ի՞նչ տեսնելու ելաք. մի մարգարէ՞. այո՛, ասում եմ ձեզ. առաւե՛լ քան մի մարգարէ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'որովհետեւ նա է, որի մասին գրուած է. «Ահա ես կ՚ուղարկեմ իմ պատգամաւորին քո առջեւից, որ քո առաջ քո ճանապարհը պատրաստի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Ճշմարիտ եմ ասում ձեզ, կանանցից ծնուածների մէջ Յովհաննէս Մկրտչից աւելի մեծը չի ելել. բայց երկնքի արքայութեան մէջ ամենից յետինը նրանից մեծ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Յովհաննէս Մկրտչի օրերից մինչեւ այժմ երկնքի արքայութիւնը բռնադատւում է. եւ հզօրներն են յափշտակում այն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'քանի որ ամբողջ Օրէնքը եւ մարգարէները մարգարէացան մինչեւ Յովհաննէսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Եւ եթէ ուզում էք ընդունել, Յովհաննէ՛սն է Եղիան, որ գալու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Ով լսելու ականջ ունի, թող լսի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Ո՞ւմ նմանեցնեմ այս սերնդին. նման է նա մանուկների, որոնք նստած են հրապարակներում, կանչում են իրենց ընկերներին եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'ձեզ համար փող հնչեցրինք, բայց չպարեցիք. ձեզ համար ողբ երգեցինք, բայց դուք լաց ու կոծ չարեցիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Եկաւ Յովհաննէսը. ո՛չ ուտում էր եւ ո՛չ խմում. եւ ասացին՝ նրա մէջ դեւ կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Եկաւ մարդու Որդին. ուտում է եւ խմում. եւ ասում են՝ ահա ուտող եւ խմող մարդ, բարեկամ՝ մաքսաւորների եւ մեղաւորների. բայց իմաստութիւնը արդարացուեց իր որդիների կողմից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Այն ժամանակ նա սկսեց պարսաւել այն քաղաքները, որոնց մէջ նրա բազում զօրաւոր գործերը տեղի ունեցան, բայց նրանք չապաշխարեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '«Վա՜յ քեզ, Քորազին, վա՜յ քեզ, Բեթսայիդա. որովհետեւ եթէ Տիւրոսում եւ Սիդոնում տեղի ունեցած լինէին այն զօրաւոր գործերը, որ ձեր մէջ արուեցին, վաղուց արդէն քուրջով եւ մոխրով ապաշխարած կը լինէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Բայց ասում եմ ձեզ, Տիւրոսի եւ Սիդոնի երկրի համար աւելի տանելի կը լինի դատաստանի օրը, քան ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Եւ դո՛ւ, Կափառնայո՛ւմ, միթէ մինչեւ երկի՞նք պիտի բարձրանաս. ո՛չ, պիտի իջնես մինչեւ դժոխք. որովհետեւ եթէ Սոդոմում եղած լինէին այս զօրաւոր գործերը, որ եղան քո մէջ, արդարեւ մինչեւ այսօր նրանք կանգուն կը լինէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Բայց ասում եմ ձեզ, որ սոդոմացիների երկրի համար դատաստանի օրը աւելի տանելի կը լինի, քան քեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Այն ժամանակ Յիսուս պատասխան տուեց եւ ասաց. «Գոհութիւն եմ յայտնում քեզ, Հա՛յր, Տէ՛ր երկնքի եւ երկրի, որ ծածկեցիր այս բանը իմաստուններից եւ գիտուններից ու յայտնեցիր մանուկներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Այո՛, Հա՛յր, քանի որ այսպէս հաճելի եղաւ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Ամենայն ինչ տրուեց ինձ իմ Հօրից. եւ ոչ ոք չի ճանաչում Որդուն, եթէ ոչ՝ Հայրը. եւ ոչ ոք չի ճանաչում Հօրը, եթէ ոչ՝ Որդին, եւ նա, ում Որդին ուզենայ յայտնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Եկէ՛ք ինձ մօտ, բոլոր յոգնածներդ ու բեռնաւորուածներդ, եւ ես ձեզ կը հանգստացնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Իմ լուծը ձեր վրայ վերցրէ՛ք եւ սովորեցէ՛ք ինձնից, որ հեզ եմ եւ սրտով խոնարհ. եւ ձեզ համար հանգիստ պիտի գտնէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'որովհետեւ իմ լուծը քաղցր է եւ իմ բեռը՝ թեթեւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Յիսուս, շաբաթ օրով, անցաւ արտերի միջով. նրա աշակերտները քաղցած էին եւ սկսեցին հասկ պոկել եւ ուտել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Փարիսեցիները երբ այս տեսան, Յիսուսին ասացին. «Ահա քո աշակերտները անում են մի բան, որ շաբաթ օրն անել օրինաւոր չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Եւ նա նրանց ասաց. «Դուք չէ՞ք կարդացել, թէ ինչ արեց Դաւիթը, երբ քաղց զգաց նա եւ նրանք, որ նրա հետ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Թէ ինչպէս մտաւ Աստծու տունը եւ կերաւ առաջաւորութեան հացը, որն ուտել օրէնք չէր ո՛չ նրա եւ ո՛չ էլ նրա հետ եղողների համար, այլ միայն՝ քահանաների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Կամ թէ Օրէնքում չէ՞ք կարդացել, որ շաբաթ օրերը տաճարում քահանաները պղծում են շաբաթը եւ անմեղ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Բայց ասում եմ ձեզ, որ այստեղ տաճարից մեծ մէկը կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Եւ եթէ իմանայիք, թէ ի՛նչ է՝ ողորմութիւն եմ կամենում եւ ոչ՝ զոհ, ապա դուք անպարտներին չէիք դատապարտի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'ուրեմն մարդու Որդին շաբաթ օրուայ տէրն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Յիսուս այստեղից մեկնելով՝ եկաւ նրանց ժողովարանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Այնտեղ կար մի մարդ, որի ձեռքը գօսացած էր: Յիսուսին հարցրին ու ասացին. «Շաբաթ օրը թոյլատրելի՞ է բժշկել». որպէսզի նրան ամբաստանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Եւ նա ասաց նրանց. «Ո՞վ է ձեզնից այն մարդը, որ մի ոչխար ունենայ, եւ դա շաբաթ օրն ընկնի փոսի մէջ, միթէ չի՞ բռնի ու վեր հանի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Իսկ արդ, մարդը ոչխարից որքա՜ն եւս առաւել է. ապա ուրեմն, պէտք է շաբաթ օրը բարիք գործել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Այն ժամանակ մարդուն ասաց՝ ձեռքդ երկարի՛ր. եւ նա երկարեց. եւ առողջացաւ գօսացած ձեռքը, ինչպէս միւսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Իսկ փարիսեցիները դուրս գալով՝ նրա դէմ խորհուրդ արին, թէ ինչպէս կորստեան մատնեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Երբ Յիսուս այդ իմացաւ, այդտեղից մեկնեց: Նրա յետեւից գնաց շատ ժողովուրդ, եւ նա բոլորին բժշկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Եւ խստիւ պատուիրեց նրանց, որ իր մասին ոչ ոքի բան չասեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'որպէսզի կատարուի այն, ինչ որ ասուեց Եսայի մարգարէի բերանով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Այն ժամանակ նրա մօտ բերուեց կոյր ու համր մի դիւահար, եւ նա բժշկեց նրան, այնպէս որ համրն ու կոյրը խօսում էր ու տեսնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ամբողջ ժողովուրդը զարմացաւ եւ ասում էր. «Միթէ սա՞ է Քրիստոսը՝ Դաւթի Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Բայց երբ փարիսեցիները լսեցին, ասացին. «Նա դեւերին այլ կերպ չի հանում, եթէ ոչ Բէեղզեբուղի՝ դեւերի իշխանի միջոցով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Երբ Յիսուս նրանց մտածումներն իմացաւ, նրանց ասաց. «Ինքն իր մէջ բաժանուած ամէն թագաւորութիւն աւերւում է, եւ ինքն իր մէջ բաժանուած ամէն քաղաք կամ տուն կանգուն չի մնայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'եւ եթէ սատանան սատանային հանում է, ուրեմն՝ ինքն իր մէջ բաժանուեց. արդ, նրա թագաւորութիւնը ինչպէ՞ս կարող է կանգուն մնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Եւ եթէ ես Բէեղզեբուղով եմ հանում դեւերին, ձեր որդիները ինչո՞վ կը հանեն. դրա համար էլ նրանք կը լինեն ձեր դատաւորները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Իսկ եթէ Աստծու Հոգով եմ հանում դեւերին, ուրեմն Աստծու արքայութիւնը հասել է ձեր վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Կամ՝ ինչպէ՞ս կարող է մէկը մտնել հզօր մի մարդու տունը եւ յափշտակել նրա գոյքերը, եթէ նախ չկապի հզօրին եւ ապա նրա տունը կողոպտի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Ով ինձ հետ չէ՝ իմ դէմ է, եւ ով ինձ հետ չի հաւաքում՝ ցրում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, '«Դրա համար ասում եմ ձեզ. ամէն մեղք եւ հայհոյանք կը ներուեն մարդկանց, բայց Հոգու դէմ հայհոյանքը չպիտի ներուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Եւ ով որ մարդու Որդու դէմ խօսք ասի, նրան պիտի ներուի, բայց ով ասի Սուրբ Հոգու դէմ, նրան չպիտի ներուի ո՛չ այս աշխարհում եւ ո՛չ էլ հանդերձեալում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Կա՛մ ծառը բարի արէք, եւ նրա պտուղն էլ բարի կը լինի, կա՛մ ծառը չար արէք, եւ նրա պտուղն էլ չար կը լինի. քանի որ իր պտղից է ծառը ճանաչւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Իժերի՛ ծնունդներ, դուք, որ չար էք, ինչպէ՞ս կը կարողանաք բարի բաներ խօսել, քանի որ բերանը սրտի լիութիւնից է, որ խօսում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Բարի մարդը իր սրտի բարի գանձերից հանում է բարի բաներ, իսկ չար մարդը իր սրտի չար գանձերից հանում է չար բաներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Բայց ասում եմ ձեզ, թէ մարդիկ իրենց խօսած ամէն դատարկ բանի համար դատաստանի օրը հաշիւ պիտի տան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'որովհետեւ՝ քո խօսքերով պիտի արդարանաս եւ քո խօսքերով պիտի դատապարտուես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Այն ժամանակ օրէնսգէտներից եւ փարիսեցիներից ոմանք նրան պատասխան տուեցին ու ասացին. «Վարդապե՛տ, քեզնից մի նշան ենք կամենում տեսնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Նա պատասխան տուեց նրանց ու ասաց. «Չար եւ շնացող ազգը նշան է փնտռում. այլ նշան չի տրուի նրան, բայց միայն Յովնան մարգարէի նշանը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'որովհետեւ, ինչպէս Յովնանը երեք օր ու երեք գիշեր կէտի փորի մէջ էր, նոյնպէս եւ մարդու Որդին երկրի ընդերքում՝ երեք օր ու երեք գիշեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Նինուէի մարդիկ դատաստանի ժամանակ այս ազգի դէմ պիտի դուրս գան եւ պիտի դատապարտեն նրան, քանի որ նրանք Յովնանի քարոզութեամբ ապաշխարեցին. եւ ահաւասիկ այստեղ Յովնանից մեծը կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Հարաւի Դշխոն դատաստանի ժամանակ պիտի դուրս գայ այս ազգի դէմ եւ պիտի դատապարտի նրան, որովհետեւ նա երկրի ծագերից եկաւ լսելու Սողոմոնի իմաստութիւնը. եւ ահա այստեղ Սողոմոնից մեծը կայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, '«Սակայն պիղծ ոգին դուրս է ելնում մարդուց, շրջում է անջրդի վայրերում, հանգիստ է որոնում եւ չի գտնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Այն ժամանակ ասում է՝ դառնամ իմ տունը, որտեղից դուրս եկայ. եւ գալիս է ու այն գտնում դատարկ՝ մաքրուած ու կարգի բերուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Այն ժամանակ գնում եւ վերցնում է իր հետ իրենից աւելի չար եօթը այլ ոգիներ եւ մտնում բնակւում է այնտեղ. եւ այդ մարդու վերջը լինում է աւելի վատ, քան առաջ էր. այսպէս պիտի լինի եւ այս չար սերնդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Մինչ Յիսուս դեռ խօսքն ուղղում էր բազմութեանը, ահա նրա մայրն ու նրա եղբայրները կանգնած էին դրսում եւ ուզում էին խօսել նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Եւ մէկն ասաց նրան. «Ահա քո մայրն ու քո եղբայրները դրսում կանգնած են եւ ուզում են քեզ հետ խօսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Նա այդ ասողին պատասխանեց ու ասաց. «Ո՞վ է իմ մայրը, կամ ովքե՞ր են իմ եղբայրները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Եւ իր ձեռքը երկարելով դէպի իր աշակերտները՝ ասաց. «Ահա՛ իմ մայրը եւ իմ եղբայրները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'որովհետեւ, ով կատարում է կամքը իմ Հօր, որ երկնքում է, նա՛ է ինձ եղբայր եւ քոյր եւ մայր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Այդ օրը Յիսուս տնից դուրս գալով՝ նստեց ծովեզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Եւ նրա մօտ շատ ժողովուրդ հաւաքուեց, այնպէս որ նա նաւակ մտաւ ու նստեց. իսկ ամբողջ ժողովուրդը կանգնած էր ծովեզերքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Եւ նրանց հետ առակներով շատ բաներ էր խօսում եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, '«Ահա մի սերմնացան ելաւ սերմանելու. եւ երբ նա սերմանում էր, մի մաս սերմ ընկաւ ճանապարհի եզերքին, եւ երկնքի թռչունը եկաւ եւ այն կերաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Եւ ուրիշ մի մաս ընկաւ ապառաժի վրայ, ուր շատ հող չկար. եւ իսկոյն բուսաւ, քանի որ հողը խորութիւն չունէր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'երբ արեւը ծագեց, խանձուեց. եւ քանի որ արմատներ չկային, չորացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Եւ ուրիշ մի մաս ընկաւ փշերի մէջ, ու փշերը բարձրացան եւ այն խեղդեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Եւ մէկ ուրիշ մաս ընկաւ պարարտ հողի վրայ եւ պտուղ տուեց. կար որ մէկին՝ հարիւր. եւ կար որ մէկին՝ վաթսուն. եւ կար որ մէկին՝ երեսուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Ով լսելու ականջ ունի, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Եւ աշակերտները մօտենալով՝ նրան ասացին. «Ինչո՞ւ ես առակներով խօսում նրանց հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Նա պատասխանեց եւ ասաց նրանց. «Քանի որ ձե՛զ է տրուած իմանալ երկնքի արքայութեան խորհուրդները, իսկ նրանց տրուած չէ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'որովհետեւ՝ ով ունի, նրան պիտի տրուի եւ պիտի աւելացուի, իսկ ով չունի, նրանից պիտի վերցուի ունեցածն էլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Նրանց հետ առակներով եմ խօսում նրա համար, որ նայում են եւ չեն տեսնում, լսում են եւ չեն իմանում ու չեն հասկանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Եւ նրանց վրայ կատարւում է Եսայու մարգարէութիւնը, որ ասում է՝ պիտի լսէք, պիտի լսէք ու պիտի չիմանաք, պիտի նայէք, պիտի նայէք ու պիտի չտեսնէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'որովհետեւ այս ժողովրդի սիրտը կարծրացաւ, եւ իրենց ականջներով ծանր են լսում. եւ փակեցին իրենց աչքերը, որպէսզի երբեք աչքերով չտեսնեն ու ականջներով չլսեն եւ սրտով չիմանան եւ դարձի չգան, ու ես նրանց չբժշկեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Բայց երանի՜ է ձեր աչքերին, որ տեսնում են, ու ձեր ականջներին, որ լսում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Ճշմարիտ եմ ասում ձեզ, որ շատ մարգարէներ ու արդարներ ցանկացան տեսնել, ինչ որ դուք տեսնում էք, բայց չտեսան, եւ լսել՝ ինչ որ դուք լսում էք, բայց չլսեցին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, '«Եւ արդ, լսեցէ՛ք դուք սերմնացանի առակը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'ամէն մէկից, ով լսում է արքայութեան խօսքը եւ չի հասկանում, չարը գալիս է եւ յափշտակում նրա սրտում սերմանուածը. դա այն է, որ ճանապարհի եզերքին սերմանուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Եւ որ ապառաժի վրայ սերմանուեց, այն է, որ երբ լսում է խօսքը, իսկոյն ուրախութեամբ էլ ընդունում է այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Բայց քանի որ ինքն իր մէջ արմատներ չունի, այլ մի որոշ ժամանակի համար է հաւատում, երբ խօսքի համար նեղութիւն եւ հալածանքներ լինեն, իսկոյն սայթաքում ընկնում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Իսկ որ փշերի մէջ սերմանուեց, այն է, որ լսում է խօսքը, բայց աշխարհիս հոգսերը եւ հարստութեան պատրանքները խեղդում են խօսքը, եւ սա լինում է անպտուղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Իսկ որ լաւ հողի մէջ սերմանուեց, այն է, որ երբ լսում է խօսքը եւ հասկանում, պտուղ է տալիս. կայ որ մէկի դիմաց՝ հարիւր, կայ որ մէկի դիմաց՝ վաթսուն եւ կայ որ մէկի դիմաց՝ երեսուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Նա մէկ ուրիշ առակ էլ նրանց առաջ դրեց ու ասաց. «Երկնքի արքայութիւնը նմանուեց մի մարդու, որ իր արտի մէջ բարի սերմ սերմանեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Եւ երբ մարդիկ քնի մէջ էին, նրա թշնամին եկաւ եւ ցանած ցորենի վրայ որոմ ցանեց ու գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Եւ երբ ցորենը բուսաւ ու պտուղ տուեց, ապա երեւաց եւ այն որոմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Տանտիրոջ ծառաները մօտեցան ու ասացին նրան. «Տէ՛ր, չէ՞ որ քո արտի մէջ դու բարի սերմ սերմանեցիր, ուրեմն որտեղի՞ց է այդ որոմը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Եւ տէրն ասաց նրանց. «Թշնամի մարդ է արել այդ»: Ծառաները նրան ասացին. «Կամենո՞ւմ ես, որ գնանք ու քաղենք հանենք այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Եւ տէրը նրանց ասաց. «Ո՛չ, մի գուցէ որոմը քաղելիս, ցորենն էլ նրա հետ արմատախիլ անէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Թողէ՛ք, որ երկուսն էլ միասին աճեն մինչեւ հունձը, եւ հնձի ժամանակ ես հնձողներին կ՚ասեմ՝ նախ այդ որոմը քաղեցէ՛ք եւ դրանից խուրձեր կապեցէ՛ք այրելու համար, իսկ ցորենը հաւաքեցէ՛ք իմ շտեմարանների մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Նրանց առաջ նա մէկ ուրիշ առակ էլ դրեց ու ասաց. «Երկնքի արքայութիւնը նման է մանանեխի հատիկի, որ մի մարդ, առնելով, սերմանեց իր արտի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Այն փոքր է, քան բոլոր սերմերը. սակայն երբ աճում է, բոլոր բանջարներից աւելի է մեծանում ու ծառ է լինում, այն աստիճան, որ երկնքի թռչունները գալիս են ու նրա ճիւղերի վրայ հանգստանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Նա մէկ ուրիշ առակ էլ պատմեց նրանց ու ասաց. «Երկնքի արքայութիւնը նման է թթխմորի, որ մի կին, առնելով, դրեց երեք չափ ալիւրի մէջ, մինչեւ որ ամբողջը խմորուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Այս բոլորը Յիսուս առակներով պատմեց բազմութեանը եւ առանց առակի ոչինչ չէր ասում նրանց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'որպէսզի կատարուի մարգարէի կողմից ասուածը. «Իմ բերանը առակներով պիտի բանամ եւ աշխարհի սկզբից ի վեր ծածկուած բաները պիտի յայտնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Այն ժամանակ Յիսուս արձակելով ժողովրդին՝ տուն եկաւ. աշակերտները մօտեցան նրան ու ասացին. «Մեկնի՛ր մեզ համար արտի որոմների առակը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Նա պատասխանեց եւ ասաց. «Այն, որ սերմանում է բարի սերմը, մարդու Որդին է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'իսկ արտը այս աշխարհն է. բարի սերմը նրանք են, որ արքայութեան որդիներն են, իսկ որոմը չարի որդիներն են.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'եւ թշնամին, որ այն ցանեց, սատանան է. իսկ հունձը այս աշխարհի վախճանն է, եւ հնձողները հրեշտակներ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Ինչպէս որոմը հաւաքւում է եւ կրակի մէջ այրւում, այնպէս կը լինի այս աշխարհի վախճանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Մարդու Որդին կ՚ուղարկի իր հրեշտակներին, եւ նրանք կը հաւաքեն նրա արքայութիւնից բոլոր գայթակղութիւնները եւ նրանց, որոնք անօրինութիւն են գործում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'Եւ կը գցեն նրանց բոցավառ հնոցի մէջ. այնտեղ կը լինի լաց եւ ատամների կրճտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Այն ժամանակ արդարները երկնքի արքայութեան մէջ կը ծագեն ինչպէս արեգակը: Ով լսելու ականջ ունի, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '«Դարձեալ՝ երկնքի արքայութիւնը նման է արտի մէջ թաքցուած գանձի, որ մի մարդ, գտնելով, նորից թաքցնում է. եւ ուրախութիւնից գնում վաճառում է իր ամբողջ ունեցածը եւ այդ արտը գնում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Դարձեալ՝ երկնքի արքայութիւնը նման է մի վաճառականի, որ գեղեցիկ մարգարիտներ էր որոնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'եւ գտնելով մի թանկարժէք մարգարիտ՝ գնաց վաճառեց իր ամբողջ ունեցածը եւ այդ մարգարիտը գնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Դարձեալ՝ երկնքի արքայութիւնը նման է ծով նետուած ուռկանի, որ ամէն տեսակ բան է հաւաքել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'երբ լցուել էր, այն ցամաք հանելով եւ նստելով՝ լաւերը մի առ մի հաւաքեցին ամանների մէջ, իսկ անպէտքը դուրս գցեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Այնպէս էլ կը լինի այս աշխարհի վախճանին: Հրեշտակները կ՚ելնեն եւ չարերին արդարների միջից կը բաժանեն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'ու կը գցեն նրանց բոցավառ հնոցի մէջ. այնտեղ կը լինի լաց եւ ատամների կրճտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Յիսուս իր աշակերտներին ասաց. «Այս բոլորը իմացա՞ք»: Նրան ասացին՝ այո՛, Տէ՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Եւ Յիսուս նրանց ասաց. «Դրա համար երկնքի արքայութեանն աշակերտած ամէն օրէնսգէտ նման է տանուտէր մարդու, որ իր գանձից հանում է նորը եւ հինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Երբ Յիսուս այս առակները վերջացրեց, այնտեղից մեկնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Եւ գալով իր գաւառը՝ նրանց ուսուցանում էր իրենց ժողովարանում, այնպէս որ նրանք զարմանում ու ասում էին. «Սրան որտեղի՞ց են այս իմաստութիւնը եւ զօրութեան գործերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Սա հիւսնի որդին չէ՞. սրա մայրը չէ՞, որ Մարիամ է կոչւում. եւ սրա եղբայրները՝ Յակոբոս, Յովսէս, Սիմոն եւ Յուդա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Եւ սրա քոյրերը բոլորը մեզ մօտ չե՞ն. եւ արդ, որտեղի՞ց է սրան այս բոլորը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Եւ նրանով գայթակղւում էին: Իսկ Յիսուս նրանց ասաց. «Չկայ անարգուած մարգարէ, բայց միայն՝ իր գաւառում եւ իր տանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Եւ նրանց անհաւատութեան պատճառով այնտեղ զօրաւոր շատ գործեր չարեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Այն ժամանակ Հերովդէս չորրորդապետը լսեց Յիսուսի համբաւը եւ իր ծառաներին ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, '«Նա՛ է Յովհաննէս Մկրտիչը. մեռելներից յարութիւն է առել, եւ դրա համար նրա միջոցով զօրաւոր գործեր են լինում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Արդարեւ Հերովդէսը ձերբակալել էր Յովհաննէսին, նրան կապել եւ բանտի մէջ էր դրել իր եղբօր՝ Փիլիպպոսի կնոջ՝ Հերովդիայի պատճառով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'որովհետեւ Յովհաննէսը նրան ասում էր. «Օրինաւոր չէ, որ դու նրան իբրեւ կին ունենաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Եւ կամենում էր նրան սպանել, բայց վախենում էր ժողովրդից, քանի որ նրան որպէս մարգարէ էին ընդունում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Եւ երբ Հերովդէսի ծննդեան տարեդարձը հասաւ, Հերովդիայի դուստրը հրաւիրեալների առաջ պարեց. եւ հաճելի թուաց Հերովդէսին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'ուստի եւ՝ նա երդումով խոստացաւ նրան տալ, ինչ էլ որ ուզի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Եւ նա, առաջուց խրատուած լինելով իր մօրից, ասաց. «Տո՛ւր ինձ այստեղ, սկուտեղի վրայ, Յովհաննէս Մկրտչի գլուխը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Եւ թագաւորը տխրեց, բայց երդման եւ սեղանակիցների պատճառով հրամայեց նրան տալ այդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Եւ մարդ ուղարկեց, գլխատել տուեց Յովհաննէսին բանտի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Եւ նրա գլուխը բերուեց սկուտեղով ու տրուեց աղջկան: Եւ սա տարաւ այն իր մօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Իսկ Յովհաննէսի աշակերտները եկան վերցրին մարմինը եւ թաղեցին. եւ եկան պատմեցին Յիսուսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Երբ Յիսուս այդ լսեց, այնտեղից նաւակով առանձին գնաց մի ամայի տեղ: Երբ ժողովրդի բազմութիւնը լսեց այս, քաղաքներից հետիոտն նրա յետեւից գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Եւ երբ նա ցամաք ելաւ, տեսաւ բազում ժողովուրդ, գթաց նրանց եւ բժշկեց նրանց հիւանդներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Երեկոյեան դէմ, աշակերտները մօտեցան նրան եւ ասացին. «Այս տեղը ամայի է, եւ օրը տարաժամել է. արձակի՛ր այդ ժողովրդի բազմութիւնը, որպէսզի գնայ շրջակայ գիւղերը իր համար ուտելիք գնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Եւ Յիսուս ասաց. «Հարկ չկայ, որ նրանք գնան, դո՛ւք նրանց ուտելու բան տուէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Եւ նրանք ասացին նրան. «Այստեղ ուրիշ բան չունենք, բացի հինգ նկանակից եւ երկու ձկից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Եւ նրանց ասաց. «Այստե՛ղ բերէք այդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Եւ հրամայեց ժողովրդի բազմութիւնը նստեցնել խոտի վրայ. եւ վերցնելով հինգ նկանակն ու երկու ձկները՝ նայեց դէպի երկինք, օրհնեց, կտրեց եւ նկանակները աշակերտներին տուեց. իսկ աշակերտները՝ ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Բոլորը կերան ու յագեցան: Եւ տասներկու սակառ լիքը կտորտանքների մնացորդներ վերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Եւ նրանք, որ կերան, մօտ հինգ հազար հոգի էին՝ չհաշուած կանանց եւ երեխաներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Եւ նա իսկոյն իր աշակերտներին ստիպեց նաւակ մտնել եւ առաջանալ դէպի միւս կողմը, մինչեւ որ ինքը ժողովրդի բազմութիւնն արձակի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Եւ երբ ժողովրդի բազմութիւնն արձակեց, առանձին լեռ բարձրացաւ աղօթելու համար: Եւ երբ երեկոյ եղաւ, այնտեղ էր, մենակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Նաւակը ցամաքից մղոններով հեռացել էր՝ դէս ու դէն քշուելով ալիքներից, քանի որ քամին դիմացից էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Եւ գիշերուայ ուշ ժամին Յիսուս եկաւ նրանց մօտ՝ քայլելով ծովի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Երբ աշակերտները նրան տեսան ծովի վրայ քայլելիս, տագնապահար եղան եւ ասացին. «Ինչ-որ ուրուական է». ու սարսափից աղաղակեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Յիսուս իսկոյն խօսեց նրանց հետ ու ասաց. «Սրտապնդուեցէ՛ք, ես եմ, մի՛ վախեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Պետրոսը նրան պատասխանեց ու ասաց. «Տէ՛ր, եթէ դու ես, հրամայի՛ր ինձ ջրի վրայով քեզ մօտ գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Եւ նա ասաց՝ արի՛: Եւ Պետրոսը նաւակից իջնելով՝ քայլեց ջրի վրայով ու եկաւ Յիսուսի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Սակայն տեսնելով ուժգին քամին՝ վախեցաւ: Եւ երբ սկսեց սուզուել, աղաղակեց ու ասաց. «Տէ՛ր, փրկի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Եւ իսկոյն Յիսուս երկարեց իր ձեռքը, բռնեց նրան ու ասաց. «Թերահաւա՛տ, ինչո՞ւ երկմտեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Եւ երբ նրանք նաւակ բարձրացան, քամին հանդարտուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Եւ նրանք, որ նաւակի մէջ էին, մօտեցան, երկրպագեցին նրան ու ասացին. «Արդարեւ Աստծու Որդին ես դու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Եւ կտրել անցնելով՝ ցամաք ելան Գեննեսարէթում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Եւ երբ այդ տեղի մարդիկ նրան ճանաչեցին, մարդ ուղարկեցին ամբողջ գաւառով մէկ ու բոլոր հիւանդներին նրա մօտ բերեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Եւ աղաչում էին նրան, որ գոնէ միայն նրա զգեստի քղանցքներին դիպչեն. եւ նրանք, որ մի անգամ դիպան, բժշկուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Այն ժամանակ Յիսուսին մօտեցան փարիսեցիներ ու օրէնսգէտներ, որոնք Երուսաղէմից էին, եւ ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '«Ինչո՞ւ քո աշակերտները նախնիների աւանդութիւնը զանց են անում, քանի որ, երբ հաց են ուտում, ձեռքները չեն լուանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Նա պատասխան տուեց եւ ասաց նրանց. «Իսկ դուք ինչո՞ւ զանց էք անում Աստծու պատուիրանը՝ ձեր աւանդութեան պատճառով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'քանի որ Աստուած ասաց. «Մեծարի՛ր քո հօրը եւ մօրը».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'եւ ով վատաբանում է հօրը կամ մօրը, մահուամբ պիտի պատժուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Իսկ դուք ասում էք. ով իր հօրը կամ մօրը ասի, թէ՝ այն, ինչ ինձնից օգտուելու ես, Աստծուն ընծայ է, այլեւս չի մեծարի իր հօրը կամ իր մօրը. ուրեմն՝ Աստծու խօսքը արհամարհում էք ձեր աւանդութեան պատճառով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Կեղծաւորնե՛ր, Եսային լաւ է մարգարէացել ձեր վրայ եւ ասել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '«Այս ժողովուրդը շրթունքներով է ինձ մեծարում, բայց իրենց սիրտը հեռացած բաժանուած է ինձնից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'զուր են ինձ պաշտում. մարդկանց կողմից պատուիրուած վարդապետութիւններ են ուսուցանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Եւ Յիսուս իր մօտ կանչելով ժողովրդին՝ ասաց. «Լսեցէ՛ք եւ իմացէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'ոչ թէ՝ ինչ որ բերանով է մտնում, ա՛յն է պղծում մարդուն, այլ ինչ որ ելնում է բերանից՝ ա՛յն է պղծում մարդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Այն ժամանակ նրա աշակերտները մօտեցան եւ ասացին նրան. «Գիտե՞ս, որ փարիսեցիները, երբ այդ խօսքը լսեցին, գայթակղուեցին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Նա պատասխանեց նրանց եւ ասաց. «Ամէն տունկ, որ իմ երկնաւոր Հայրը չի տնկել, արմատախիլ պիտի արուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Թողէ՛ք նրանց. կոյրեր են, կոյրերի առաջնորդ. երբ կոյրն է առաջնորդում կոյրին, սխալւում է, եւ երկուսն էլ փոսն են ընկնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Պետրոսը պատասխան տուեց նրան եւ ասաց. «Այս առակը բացատրի՛ր մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Յիսուս ասաց. «Դեռեւս դո՞ւք էլ անհասկացող էք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'չէ՞ք իմանում, թէ ամէն ինչ, որ բերան է մտնում, որովայն է գնում եւ դուրս է ելնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Իսկ ինչ ելնում է բերանից, սրտից է գալիս, եւ ա՛յն է մարդուն պղծում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'քանի որ սրտից է, որ ելնում են չար խորհուրդներ, սպանութիւններ, շնութիւններ, պոռնկութիւններ, գողութիւններ, սուտ վկայութիւններ, հայհոյանքներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Այս բոլորն են, որ պղծում են մարդուն. իսկ անլուայ ձեռքերով ուտելը մարդուն չի պղծում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Յիսուս այդտեղից ելնելով՝ գնաց Տիւրոսի եւ Սիդոնի կողմերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Եւ ահա, այդ շրջաններից եկած քանանացի մի կին աղաղակում էր ու ասում. «Ողորմի՛ր ինձ, Տէ՛ր, Դաւթի՛ Որդի, աղջիկս չարաչար դիւահարւում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Բայց նա նրան պատասխան չտուեց, եւ նրա աշակերտները մօտենալով՝ աղաչում էին նրան ու ասում. «Արձակի՛ր նրան, որովհետեւ մեր յետեւից աղաղակում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Նա պատասխան տուեց եւ ասաց. «Այլ տեղ չեմ ուղարկուած, եթէ ոչ Իսրայէլի տան կորուսեալ ոչխարների մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Իսկ կինը մօտենալով՝ երկրպագում էր նրան ու ասում. «Տէ՛ր, օգնի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Նա պատասխանեց նրան եւ ասաց. «Լաւ չէ մանուկների հացն առնել ու շներին գցել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Եւ նա ասաց. «Այո՛, Տէ՛ր, որովհետեւ շներն էլ կերակրւում են իրենց տիրոջ սեղանից ընկած փշրանքներով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Այն ժամանակ նրան պատասխանեց եւ ասաց. «Ո՛վ կին, մեծ է քո հաւատը, թող քեզ լինի՝ ինչպէս որ կամենում ես»: Եւ նրա դուստրը նոյն ժամին բժշկուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Եւ Յիսուս մեկնելով այդտեղից՝ եկաւ Գալիլիայի ծովեզերքը եւ, լեռը բարձրանալով, նստեց այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Նրան մօտեցաւ բազում ժողովուրդ. նրանց մէջ կային կաղեր, կոյրեր, համրեր, հաշմուածներ եւ ուրիշ շատեր: Սրանց բերին գցեցին նրա ոտքերի առջեւ, եւ նա նրանց բժշկեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'այնպէս որ, ժողովուրդը զարմանում էր՝ տեսնելով, որ համրերը խօսում են, կաղերը՝ քայլում, հաշմանդամները՝ բժշկւում, կոյրերը՝ տեսնում. եւ փառք էին տալիս Իսրայէլի Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Եւ Յիսուս իր մօտ կանչելով աշակերտներին՝ ասաց. «Խղճում եմ այս ժողովրդին, որովհետեւ ահա երեք օր է, որ ինձ մօտ են եւ բան չունեն, որ ուտեն. եւ նրանց չեմ կամենում սոված արձակել. գուցէ ճանապարհին ուժասպառ լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Աշակերտները նրան ասացին. «Իսկ այժմ, այս ամայութեան մէջ որտեղի՞ց է մեզ այնչափ հաց՝ այսքան ժողովուրդ կշտացնելու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Եւ Յիսուս նրանց ասաց. «Քանի՞ նկանակ ունէք»: Եւ նրանք ասացին՝ եօթը, եւ մի քանի ձուկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Եւ նա հրամայեց ժողովրդին, որ նստեն գետնի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Եւ վերցնելով եօթը նկանակն ու ձկները՝ գոհութիւն յայտնեց Աստծուն եւ կտրեց ու տուեց աշակերտներին, եւ նրանք էլ՝ ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Բոլորը կերան ու յագեցան. եւ եօթը լիքը զամբիւղ կտորտանքների մնացորդներ վերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Եւ նրանք, որ կերան, մօտ չորս հազար հոգի էին՝ չհաշուած կանանց ու երեխաներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Երբ նա ժողովրդի բազմութիւնը արձակեց, նաւակ բարձրացաւ ու եկաւ Մագդաղիայի սահմանները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Փարիսեցիներն ու սադուկեցիները մօտեցան ու փորձելով՝ նրանից ուզում էին, որ ցոյց տայ իրենց երկնային մի նշան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Իսկ նա պատասխան տուեց եւ ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, '«Չար եւ շնացող մի սերունդ նշան է ուզում, եւ սակայն նրան նշան չպիտի տրուի, բացի Յովնան մարգարէի նշանից»: Եւ նրանց թողեց ու գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Աշակերտներն էլ գնացին ծովի այն կողմը, բայց մոռացան հաց վերցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Յիսուս նրանց ասաց. «Տեսէ՛ք, զգո՛յշ եղէք սադուկեցիների եւ փարիսեցիների խմորից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Աշակերտները իրենց մէջ խորհում էին ու ասում. «Որովհետեւ հաց չենք վերցրել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Յիսուս այդ իմացաւ ու ասաց. «Թերահաւատնե՛ր, ինչո՞ւ էք ձեր մտքում խորհում, թէ հաց չունէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Դեռեւս չէ՞ք իմանում եւ չէ՞ք յիշում հինգ նկանակը, որ կերակրեց հինգ հազարին. եւ քանի՞ սակառ վերցրիք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'ոչ էլ եօթը նկանակը՝ չորս հազարին. եւ քանի՞ սակառ վերցրիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Արդ, ինչպէ՞ս չէք իմանում, թէ հացի համար չէ, որ ձեզ ասացի՝ զգոյշ լինել փարիսեցիների եւ սադուկեցիների խմորից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Այն ժամանակ իմացան, թէ չէր ասել, որ զգուշանան խմորից, այլ՝ փարիսեցիների եւ սադուկեցիների ուսուցումից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Եւ Յիսուս Փիլիպպեան Կեսարիայի կողմերը գնալով՝ հարցրեց աշակերտներին ու ասաց. «Մարդիկ իմ մասին ի՞նչ են ասում, ո՞վ է մարդու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Եւ նրանք ասացին. «Մէկը, թէ՝ Յովհաննէս Մկրտիչը, եւ ուրիշներ՝ Եղիան, իսկ ոմանք, թէ՝ Երեմիան, կամ մարգարէներից մէկը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Յիսուս նրանց ասաց. «Իսկ դուք իմ մասին ի՞նչ էք ասում, ո՞վ եմ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Սիմոն Պետրոսը պատասխանեց ու ասաց. «Դու ես Քրիստոսը՝ կենդանի Աստծու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Յիսուս պատասխանեց եւ նրան ասաց. «Երանի՜ է քեզ, Սիմո՛ն, Յովնանի՛ որդի, որովհետեւ մարմինը եւ արիւնը չէ, որ յայտնեց քեզ, այլ՝ իմ Հայրը, որ երկնքում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Եւ ես քեզ ասում եմ, որ դու վէմ ես, եւ այդ վէմի վրայ պիտի շինեմ իմ եկեղեցին, ու դժոխքի դռները այն չպիտի յաղթահարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Եւ քեզ պիտի տամ երկնքի արքայութեան բանալիները, եւ ինչ որ մի անգամ կապես երկրի վրայ, կապուած պիտի լինի երկնքում: Եւ ինչ որ արձակես երկրի վրայ, արձակուած պիտի լինի երկնքում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Այն ժամանակ խստիւ պատուիրեց աշակերտներին, որ ոչ ոքի չասեն, թէ ինքն է Քրիստոսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Դրանից յետոյ Յիսուս սկսեց յստակօրէն յայտնել աշակերտներին, թէ պէտք է, որ ինքը Երուսաղէմ գնայ, բազում չարչարանքներ կրի եւ անարգուի քահանայապետներից, օրէնսգէտներից, ժողովրդի ծերերից, սպանուի եւ երրորդ օրը յարութիւն առնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Եւ Պետրոսը նրան մի կողմ տանելով՝ սկսեց վիճել նրա հետ ու ասել. «Քա՛ւ լիցի քեզ, Տէ՛ր, այդ քեզ չի պատահի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Եւ նա դառնալով Պետրոսին՝ ասաց. «Ետե՛ւս գնա, սատանա՛յ, դու գայթակղութիւն ես ինձ համար. որովհետեւ քո խորհուրդը Աստծունը չէ, այլ՝ մարդկանցը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Այն ժամանակ Յիսուս իր աշակերտներին ասաց. «Եթէ մէկը կամենում է հետեւել ինձ, թող ուրանայ իր անձը, վերցնի իր խաչը եւ գայ իմ յետեւից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'որովհետեւ ով կամենայ իր անձը փրկել, այն կը կորցնի. եւ ով ինձ համար իր անձը կորցնի, կը գտնի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Ի՛նչ օգուտ կ՚ունենայ մարդ, եթէ այս ամբողջ աշխարհը շահի, բայց իր անձը կործանի: Կամ՝ մարդ իր անձի փոխարէն ի՞նչ փրկանք պիտի տայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'քանի որ մարդու Որդին գալու է իր Հօր փառքով՝ իր հրեշտակների հետ միասին. եւ այն ժամանակ իւրաքանչիւրին կը հատուցի ըստ իր գործերի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Ճշմարիտ եմ ասում ձեզ, որ այստեղ գտնուողների մէջ կան ոմանք, որոնք մահը չեն ճաշակի, մինչեւ որ չտեսնեն մարդու Որդուն՝ եկած իր արքայութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Եւ վեց օր յետոյ Յիսուս իր հետ վերցրեց Պետրոսին, Յակոբոսին եւ նրա եղբօրը՝ Յովհաննէսին եւ նրանց հանեց, առանձին, մի բարձր լեռ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'եւ նրանց առաջ պայծառակերպուեց. եւ նրա դէմքը փայլեց ինչպէս արեգակը. եւ նրա զգեստները դարձան սպիտակ ինչպէս լոյսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Եւ ահա նրանց երեւացին Մովսէսն ու Եղիան, որ խօսում էին նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Պետրոսը պատասխան տուեց եւ ասաց Յիսուսին. «Տէ՛ր, լաւ է, որ մենք այստեղ ենք. եթէ կամենաս, երեք տաղաւարներ շինենք, մէկը՝ քեզ համար, մէկը՝ Մովսէսի, մէկն էլ՝ Եղիայի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Եւ մինչ նա դեռ խօսում էր, ահա մի լուսաւոր ամպ նրանց վրայ հովանի եղաւ. ամպից մի ձայն եկաւ ու ասաց. «Դա՛ է իմ սիրելի Որդին, որին հաւանեցի, դրա՛ն լսեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Երբ աշակերտները այս լսեցին, իրենց երեսի վրայ ընկան եւ սաստիկ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Եւ Յիսուս, մօտենալով, դիպաւ նրանց ու ասաց. «Ոտքի՛ ելէք եւ մի՛ վախեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Նրանք աչքները բարձրացրին եւ Յիսուսից բացի ոչ ոքի չտեսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Եւ մինչ լեռից իջնում էին, Յիսուս նրանց պատուիրեց ու ասաց. «Այդ տեսիլքը մարդու չասէք, մինչեւ որ մարդու Որդին մեռելներից յարութիւն առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Աշակերտները նրան հարցրին եւ ասացին. «Հապա ինչո՞ւ օրէնսգէտներն ասում են, թէ նախ Եղիան պիտի գայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Եղիան կը գայ եւ կը վերահաստատի ամէն ինչ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'բայց ձեզ ասում եմ, որ Եղիան արդէն իսկ եկել է. բայց նրան չճանաչեցին, այլ, ինչ որ կամեցան, արեցին նրան. նոյնպէս եւ մարդու Որդին նրանց ձեռքով չարչարուելու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Այն ժամանակ աշակերտները հասկացան, թէ Յովհաննէս Մկրտչի մասին էր ասել իրենց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Երբ ժողովրդի մէջ եկան, մի մարդ մօտեցաւ, ծնկի եկաւ եւ ասաց. «Տէ՛ր, ողորմի՛ր իմ որդուն, որովհետեւ լուսնոտութիւնից է տառապում եւ չարաչար տանջւում է. շատ անգամ կրակի մէջ է ընկնում եւ երբեմն՝ ջրի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Նրան քո աշակերտների մօտ տարայ, եւ չկարողացան բժշկել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Յիսուս պատասխան տուեց ու ասաց. «Ո՛վ անհաւատ եւ մոլորուած սերունդ, մինչեւ ե՞րբ ձեզ հետ պիտի լինեմ, մինչեւ ե՞րբ ձեզ պիտի հանդուրժեմ. նրան ինձ մօ՛տ բեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Եւ Յիսուս նրան սաստեց, դեւը նրանից դուրս եկաւ, եւ մանուկը հէնց այդ րոպէից բժշկուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Այն ժամանակ աշակերտները, առանձին, մօտեցան եւ Յիսուսին ասացին. «Մենք ինչո՞ւ այն հանել չկարողացանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Եւ Յիսուս նրանց ասաց. «Ձեր թերահաւատութեան պատճառով. ճշմարիտ եմ ասում ձեզ, եթէ մանանեխի հատիկի չափ հաւատ ունենաք, այս լերանը կ՚ասէք՝ տեղափոխուի՛ր այստեղից այնտեղ, եւ կը տեղափոխուի. եւ որեւէ բան ձեզ համար անհնարին չի լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Բայց այս տեսակ դեւը այլ կերպ դուրս չի ելնում, եթէ ոչ աղօթքով ու ծոմապահութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Եւ մինչ նրանք Գալիլիայում դեռ շրջում էին, Յիսուս իր աշակերտներին ասաց. «Մարդու Որդին մատնուելու է մարդկանց ձեռքը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'ու նրան պիտի սպանեն, եւ նա երրորդ օրը յարութիւն պիտի առնի»: Եւ նրանք շատ տխրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Երբ նրանք Կափառնայում եկան, երկդրամեան տուրքը պահանջողները մօտեցան Պետրոսին եւ ասացին. «Ձեր վարդապետը երկդրամեանը չի՞ տալիս»: Եւ Պետրոսն ասաց՝ այո՛:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Եւ երբ տուն մտան, Յիսուս կանխեց նրան ու ասաց. «Քեզ ինչպէ՞ս է թւում, Սիմո՛ն. ազգերի թագաւորները հարկերը կամ տուրքը ումի՞ց են առնում, իրենց որդիների՞ց, թէ՞ օտարներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Եւ երբ ասաց՝ օտարներից, Յիսուս նրան ասաց. «Ապա ուրեմն որդիներն ազատ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Բայց որպէսզի նրանց չգայթակղեցնենք, գնա՛ ծով ու կարթ գցի՛ր, եւ առաջին ձուկը, որ դուրս կ՚ելնի, վերցրո՛ւ ու բա՛ց նրա բերանը եւ մի արծաթ դրամ կը գտնես. այն ա՛ռ եւ իմ ու քո տեղ նրանց կը տաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Այն օրը աշակերտները մօտեցան Յիսուսին եւ ասացին. «Մեզնից ո՞վ է մեծ երկնքի արքայութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Եւ Յիսուս իր մօտ կանչեց մի մանուկ, կանգնեցրեց նրան նրանց մէջ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'ու ասաց. «Ճշմարիտ եմ ասում ձեզ, եթէ չդառնաք ու չլինէք մանուկների պէս, երկնքի արքայութիւնը չէք մտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Արդ, ով իր անձը խոնարհեցնում է ինչպէս այս մանուկը, երկնքի արքայութեան մէջ նա՛ է մեծ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Եւ ով որ իմ անունով մի այսպիսի մանուկ ընդունելու լինի, ի՛նձ կ՚ընդունի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Եւ ով որ ինձ հաւատացող այս փոքրիկներից մէկին գայթակղեցնի, նրա համար լաւ կը լինի, որ նրա պարանոցից էշի երկանաքար կախուի, եւ նա սուզուի ծովի խորքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Վա՜յ աշխարհին՝ գայթակղութիւնների պատճառով. գայթակղութիւններ պէտք է որ գան, բայց վա՜յ այն մարդուն, որի միջոցով կը գայ գայթակղութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Եթէ քո ձեռքը կամ ոտքը քեզ գայթակղեցնում է, կտրի՛ր այն եւ դէ՛ն գցիր քեզնից. լաւ է, որ դու մէկ ձեռքով կամ կաղ մտնես կեանք, քան երկու ձեռք ու երկու ոտք ունենաս եւ յաւիտենական կրակի մէջ ընկնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Եւ եթէ քո աչքն է գայթակղեցնում քեզ, հանի՛ր այն եւ դէ՛ն գցիր քեզնից. լաւ է, որ դու միականի մտնես կեանք, քան երկու աչք ունենաս եւ ընկնես գեհենի կրակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Զգո՛յշ եղէք, որ այս փոքրիկներից մէկին չարհամարհէք. ասում եմ ձեզ, որ երկնքում նրանց հրեշտակները մշտապէս տեսնում են երեսն իմ Հօր, որ երկնքում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'որովհետեւ մարդու Որդին եկաւ փրկելու կորածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, '«Ձեզ ինչպէ՞ս է թւում. եթէ մի մարդ հարիւր ոչխար ունենայ, եւ նրանցից մէկը մոլորուի, իննսունինը ոչխարը լերան վրայ չի՞ թողնի ու գնայ որոնելու մոլորուածին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Եւ եթէ պատահի, որ այն գտնի, ճշմարիտ եմ ասում ձեզ, թէ նրա վրայ աւելի կ՚ուրախանայ, քան իննսունիննի վրայ, որ մոլորուած չեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Այսպէս՝ իմ երկնաւոր Հօր կամքը չէ, որ այս փոքրիկներից մէկը կորչի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, '«Եթէ եղբայրդ քո դէմ մեղանչի, գնա յանդիմանի՛ր նրան, երբ դու եւ նա մենակ էք. եթէ քեզ լսի, քո եղբօրը շահեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Իսկ եթէ քեզ չլսի, ա՛ռ քեզ հետ մէկին եւ կամ երկուսին, որպէսզի երկու կամ երեք վկաների բերանով հաստատուի ամէն ինչ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Իսկ եթէ նրանց էլ չլսի, կ՚ասես հաւատացեալների ժողովում. իսկ եթէ նրանց էլ չլսի, թող նա քեզ համար լինի ինչպէս հեթանոսը եւ մաքսաւորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Ճշմարիտ եմ ասում ձեզ, ինչ որ կապէք երկրի վրայ, կապուած պիտի լինի երկնքում: Եւ ինչ որ արձակէք երկրի վրայ, թող արձակուած լինի երկնքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Դարձեալ ձեզ ասում եմ. եթէ ձեզնից երկուսը միաբանուեն երկրի վրայ որեւէ խնդրանքի համար, ինչ էլ որ խնդրեն, կը կատարուի նրանց համար իմ Հօր կողմից, որ երկնքում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'որովհետեւ ուր երկու կամ երեք հոգի հաւաքուած լինեն իմ անունով, այնտեղ եմ ես, նրանց մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Այն ժամանակ Պետրոսը մօտեցաւ նրան ու ասաց. «Տէ՛ր, քանի՞ անգամ, եթէ եղբայրս իմ դէմ մեղանչի, պէտք է ներեմ նրան. մինչեւ եօ՞թն անգամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Յիսուս նրան ասաց. «Քեզ չեմ ասում, թէ՝ մինչեւ եօթն անգամ, այլ՝ մինչեւ եօթանասուն անգամ եօթը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, '«Այսպէս, երկնքի արքայութիւնը նմանւում է մի թագաւորի, որ կամեցաւ ծառաների հետ իր հաշիւները կարգադրել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Եւ երբ սկսեց հաշիւն ընդունել, նրա մօտ բերուեց տասը հազար քանքարի մի պարտապան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Եւ քանի որ նա վճարելու բան չունէր, նրա տէրը հրամայեց վաճառել նրան եւ նրա կնոջն ու որդիներին եւ այն ամէնը, ինչ նա ունէր, եւ պարտքը հատուցել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Եւ ծառան գետին ընկնելով՝ երկրպագում էր նրան եւ ասում. «Համբերո՛ղ եղիր իմ հանդէպ, եւ բոլորը կը վճարեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Այդ ծառայի տէրը, գթալով, արձակեց նրան եւ պարտքը նրան շնորհեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Իսկ ծառան դուրս ելնելով՝ գտաւ իր ծառայակիցներից մէկին, որ իրեն հարիւր դահեկան պարտք էր: Եւ նրան բռնելով՝ խեղդում էր ու ասում. «Վճարի՛ր ինձ, ինչ որ պարտք ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Իսկ ծառայակիցը, ընկնելով նրա ոտքերը, աղաչում էր նրան եւ ասում. «Համբերո՛ղ եղիր իմ հանդէպ, եւ կը վճարեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Իսկ սա չէր կամենում. գնաց նրան բանտ նետել տուեց, մինչեւ որ պարտքը վճարէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Նրա ծառայակիցները, երբ տեսան եղածը, շատ տրտմեցին եւ եկան ու իրենց տիրոջը պատմեցին այն ամէնը, ինչ եղել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Այն ժամանակ տէրը կանչեց նրան եւ ասաց. «Չա՛ր ծառայ, քո ամբողջ պարտքը քեզ շնորհեցի նրա համար, որ աղաչեցիր ինձ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'իսկ պէտք չէ՞ր, որ դու էլ գթայիր քո ծառայակցին, ինչպէս ես էլ քեզ գթացի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Եւ նրա տէրը բարկանալով՝ նրան յանձնեց դահիճներին, մինչեւ որ հատուցէր բոլոր պարտքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Նոյնը պիտի անի ձեզ եւ իմ Հայրը, որ երկնքում է, եթէ ձեզանից իւրաքանչիւրը սրտանց չների իր եղբօրը՝ նրա յանցանքները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Եւ երբ Յիսուս աւարտեց այս խօսքերը, Գալիլիայից տեղափոխուեց եւ եկաւ Հրէաստանի սահմանները, Յորդանանի միւս կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Եւ նրա յետեւից բազում ժողովուրդ գնաց, եւ այնտեղ նրանց բժշկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Եւ փարիսեցիները, մօտենալով նրան, փորձեցին եւ ասացին. «Օրինաւո՞ր է, որ մէկն իր կնոջը արձակի ամէն մի յանցանքի պատճառով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Նա պատասխանեց նրանց եւ ասաց. «Դուք չէ՞ք կարդացել, թէ նա, ով սկզբից ստեղծեց, արու եւ էգ արեց նրանց եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'դրա համար տղամարդը պիտի թողնի հօրը եւ մօրը ու պիտի գնայ իր կնոջ յետեւից. եւ երկուսը մէկ մարմին պիտի լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Ապա ուրեմն՝ ոչ թէ երկու, այլ մէկ մարմին են: Արդ, ինչ որ Աստուած միացրեց, մարդը թող չբաժանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Նրան ասացին. «Իսկ Մովսէսը ինչո՞ւ մեզ պատուիրեց ապահարզանի թուղթ տալ ու արձակել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Յիսուս նրանց ասաց. «Մովսէսը ձեր խստասրտութեան պատճառով ձեզ թոյլ տուեց արձակել ձեր կանանց, բայց սկզբից այդպէս չի եղել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Սակայն ասում եմ ձեզ, թէ ով իր կնոջն արձակում է, եւ դա պոռնկութեան պատճառով չէ, եւ ուրիշին է առնում, շնանում է. շնանում է եւ նա, ով արձակուածին է առնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Իր աշակերտները նրան ասացին. «Եթէ այդպիսին է պարագան մարդու եւ կնոջ համար, լաւ է չամուսնանալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Եւ նա նրանց ասաց. «Բոլորն ընդունակ չեն այդ բանին, այլ՝ նրանք, որոնց տրուած է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'որովհետեւ կան ներքինիներ, որոնք իրենց մօր որովայնից այդպէս են ծնուել. կան ներքինիներ էլ, որոնք մարդկանց կողմից են ներքինի դարձել. ներքինիներ էլ կան, որոնք երկնքի արքայութեան համար իրենք իրենց ներքինիներ են դարձր»լ. ով կարող է տան»լ« թող տանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Այն ժամանակ նրա մօտ մանուկներ բերուեցին, որ նրանց վրայ ձեռք դնի ու աղօթք անի. իսկ նրա աշակերտները սաստում էին բերողներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Յիսուս ասաց. «Թո՛յլ տուէք այդ մանուկներին եւ մի՛ արգելէք, որ նրանք ինձ մօտ գան, որովհետեւ երկնքի արքայութիւնը այդպիսիներինն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Եւ նրանց վրայ ձեռք դրեց ու այդտեղից գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Եւ ահա մէկը մօտենալով նրան՝ ասաց. «Բարի՛ վարդապետ, ի՞նչ բարիք գործեմ, որ յաւիտենական կեանքն ունենամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Եւ նա նրան ասաց. «Ինչո՞ւ ես ինձ բարու մասին հարցնում. մէ՛կ է բարին. եթէ կամենում ես յաւիտենական կեանքը մտնել, պահի՛ր պատուիրանները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Նա ասաց. «Որո՞նք»: Յիսուս նրան ասաց. «Մի սպանիրը, մի շնանարը, մի գողանարը, սուտ մի վկայիրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'քո հօրն ու մօրը մեծարիրը եւ քո ընկերոջը քո անձի պէս պիտի սիրեսը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Երիտասարդը նրան ասաց. «Այդ բոլորը իմ մանկութիւնից ի վեր պահել եմ. արդ, էլ ի՞նչ բանով պակաս եմ դեռ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Յիսուս նրան ասաց. «Եթէ կամենում ես կատարեալ լինել, գնա վաճառի՛ր քո ունեցուածքը ու տո՛ւր աղքատներին. եւ երկնքում գանձեր կ՚ունենաս. եւ դու արի՛ իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Երբ երիտասարդը այս խօսքը լսեց, տրտմած գնաց. որովհետեւ շատ հարստութիւն ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Յիսուս աշակերտներին ասաց. «Ճշմարիտ եմ ասում ձեզ, որ հարուստը դժուարութեամբ կը մտնի երկնքի արքայութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Դարձեալ ասում եմ ձեզ՝ աւելի հեշտ է, որ պարանը ասեղի ծակով մտնի, քան թէ հարուստը՝ Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Երբ աշակերտները այս լսեցին, շատ զարմացան ու ասացին. «Իսկ ո՞վ կը կարողանայ փրկուել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Յիսուս նրանց նայեց եւ ասաց. «Մարդկանց համար այդ անկարելի է, բայց Աստծու համար ամէն ինչ կարելի է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Այն ժամանակ Պետրոսը պատասխան տուեց ու ասաց նրան. «Ահա՛ւասիկ, մենք թողեցինք ամէն բան եւ եկանք քո յետեւից. արդ, մենք ի՞նչ կ՚ունենանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Յիսուս նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, թէ դուք, որ եկաք իմ յետեւից, երկրորդ գալստեան, երբ որ մարդու Որդին իր փառքի աթոռին կը նստի, դուք էլ կը նստէք տասներկու աթոռների վրայ՝ դատելու Իսրայէլի տասներկու ցեղերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Եւ ամէն ոք, որ թողել է տուն կամ եղբայրներ, կամ քոյրեր, կամ հայր, կամ մայր, կամ կին, կամ որդիներ, կամ ագարակներ՝ իմ անուան համար, հարիւրապատիկ պիտի ստանայ եւ յաւիտենական կեանքը պիտի ժառանգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Շատ առաջիններ վերջին պիտի լինեն, եւ վերջիններ՝ առաջին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '«Երկնքի արքայութիւնը նման է մի տանուտէրի, որ առաւօտեան ելաւ իր այգու համար մշակներ վարձելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Եւ մշակների օրավարձը մէկ դահեկան սակարկելով՝ նրանց ուղարկեց իր այգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Եւ առաւօտեան ժամը իննի մօտ դուրս ելնելով՝ տեսաւ ուրիշների, որ պարապ կանգնել էին հրապարակում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Նրանց էլ ասաց. «Դո՛ւք էլ գնացէք իմ այգին, եւ ինչ որ արժան է, կը տամ ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Նրանք եւս գնացին: Եւ դարձեալ դուրս ելնելով կէսօրին ու կէսօրից յետոյ ժամը երեքի մօտ՝ նոյն ձեւով արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Եւ ժամը հինգի մօտ դուրս ելնելով՝ գտաւ ուրիշների, որ պարապ կանգնել էին. նրանց ասաց. «Ինչո՞ւ էք այստեղ ամբողջ օրը պարապ կանգնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Նրան ասացին. «Որովհետեւ մեզ ոչ ոք չվարձեց»: Նրանց ասաց. «Դո՛ւք էլ գնացէք այգին, եւ ինչ որ արժան է, կը ստանաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Եւ երբ երեկոյ եղաւ, այգու տէրը իր գործավարին ասաց. «Կանչի՛ր մշակներին եւ տո՛ւր նրանց վարձը՝ սկսած վերջիններից մինչեւ առաջինները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Երբ եկան ժամը հինգի մօտ վարձուածները, իւրաքանչիւրը մէկ դահեկան ստացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Առաջիններն էլ գալով՝ կարծում էին, թէ աւելի կը ստանան, բայց նրանք էլ իւրաքանչիւրը մէկ դահեկան ստացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Երբ առան, տրտնջում էին տանտիրոջից ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, '«Դրանք՝ այդ վերջինները, մէկ ժամ գործ արեցին, իսկ դու դրանց հաւասար արեցիր մեզ, որ տարանք օրուայ ծանրութիւնը եւ տօթը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Նա պատասխանեց նրանցից մէկին եւ ասաց. «Ընկե՛ր, քեզ չեմ զրկում. չէ՞ որ ինձ հետ մէկ դահեկանի սակարկեցիր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'ստացի՛ր քոնը եւ գնա՛. այս վերջիններին կամենում եմ տալ որքան եւ քեզ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'միթէ իրաւունք չունե՞մ իմ ունեցածի հետ վարուելու, ինչպէս կամենում եմ: Կամ թէ՝ նախանձո՞ւմ ես, որ ես առատաձեռն եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Այսպէս, վերջինները առաջին պիտի լինեն, եւ առաջինները՝ վերջին. որովհետեւ բազում են կանչուածները, բայց սակաւ են ընտրեալները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Երբ Յիսուս Երուսաղէմ էր բարձրանում, Տասներկուսին առանձին իր հետ վերցրեց եւ ճանապարհին ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '«Ահաւասիկ Երուսաղէմ ենք բարձրանում, եւ մարդու Որդին պիտի մատնուի քահանայապետերին ու օրէնսգէտներին. եւ նրան մահուան պիտի դատապարտեն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'ու նրան հեթանոսներին պիտի մատնեն՝ ծաղրուելու, ծեծուելու եւ խաչը հանուելու համար, սակայն նա երրորդ օրը յարութիւն պիտի առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Այն ժամանակ նրան մօտեցաւ Զեբեդէոսի որդիների մայրը՝ իր որդիների հետ միասին. նա երկրպագում էր ու նրանից մի բան ուզում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Եւ նա նրան ասաց. «Ի՞նչ ես ուզում»: Կինն ասաց նրան. «Ասա՛, որ սրանք՝ իմ այս երկու որդիները, նստեն քո արքայութեան մէջ, մէկը՝ քո աջ կողմում եւ միւսը՝ ձախ կողմում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Յիսուս պատասխանեց եւ ասաց. «Չէք իմանում՝ ինչ էք խնդրում. կարո՞ղ էք խմել այն բաժակը, որը ես խմելու եմ. կամ՝ մկրտուել այն մկրտութեամբ, որով ես մկրտուելու եմ»: Նրան ասացին՝ կարող ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Յիսուս նրանց ասաց. «Իմ բաժակը կը խմէք, եւ այն մկրտութեամբ, որով ես մկրտւում եմ, կը մկրտուէք, բայց նստեցնել իմ աջ եւ ձախ կողմերում՝ ես չէ, որ կը տամ, այլ այդ նրանց համար է, որոնց տրուած է իմ Հօրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Եւ տասը աշակերտները, այս լսելով, բարկացան երկու եղբայրների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Յիսուս նրանց իր մօտ կանչեց ու ասաց. «Գիտէք, որ ազգերի իշխանաւորները տիրում են ազգերի վրայ, եւ մեծամեծները իշխում են նրանց վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Ձեր մէջ եւս չպէտք է այդպէս լինի. այլ ձեզնից ով կը կամենայ մեծ լինել, ձեր ծառան պիտի լինի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'եւ ձեզնից ով կը կամենայ առաջին լինել, ձեր ծառան պիտի լինի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'ինչպէս որ մարդու Որդին չեկաւ ծառայութիւն ընդունելու, այլ ծառայելու եւ իր անձը տալու որպէս փրկանք շատերի փոխարէն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Եւ երբ նրանք Երիքովից դուրս էին գալիս, Յիսուսի յետեւից բազում ժողովուրդ գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Եւ ահա երկու կոյրեր նստած էին ճանապարհի եզերքին: Երբ լսեցին, թէ Յիսուս անցնում է, աղաղակեցին ու ասացին. «Ողորմի՛ր մեզ, Յիսո՛ւս, Դաւթի՛ Որդի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Եւ ամբոխը յանդիմանեց նրանց, որ լռեն: Իսկ նրանք առաւել եւս աղաղակում էին ու ասում. «Ողորմի՛ր մեզ, Տէ՛ր, Դաւթի՛ Որդի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Յիսուս տեղում կանգ առաւ, կանչեց նրանց եւ ասաց. «Ի՞նչ էք կամենում, որ ձեզ անեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Նրան ասացին. «Որ մեր աչքերը բացուեն, Տէ՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Եւ գթալով՝ Յիսուս դիպաւ նրանց աչքերին, եւ նրանք իսկոյն տեսան ու գնացին նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Երբ Երուսաղէմին մօտեցան եւ եկան Բեթփագէ, Ձիթենեաց լերան մօտ, այն ժամանակ Յիսուս իր աշակերտներից երկուսին ուղարկեց ու նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, '«Գնացէ՛ք այդ գիւղը, որ ձեր դիմացն է, եւ այնտեղ կը գտնէք կապուած մի էշ եւ նրա հետ՝ մի քուռակ. արձակեցէ՛ք բերէք ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Եւ եթէ մէկը ձեզ բան ասի, կ՚ասէք, որ Տիրոջը պէտք են. եւ նա իսկոյն դրանք կ՚ուղարկի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Բայց այս բոլորը եղաւ, որպէսզի կատարուի մարգարէի խօսքը, որ ասում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '«Ասացէ՛ք Սիոնի դստերը, ահա դէպի քեզ է գալիս քո թագաւորը՝ հեզ եւ նստած էշի ու էշի քուռակի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Աշակերտները գնացին եւ արեցին, ինչպէս Յիսուս իրենց հրամայել էր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'եւ էշն ու քուռակը բերեցին, նրանց վրայ զգեստներ գցեցին. եւ նա նստեց դրանց վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Եւ բազում ժողովուրդ իրենց զգեստները փռեցին ճանապարհի վրայ, իսկ ուրիշներ ծառերից ճիւղեր էին կտրում ու սփռում ճանապարհի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Առաջից եւ յետեւից գնացող ժողովրդի բազմութիւնը աղաղակում էր ու ասում. «Օրհնութի՜ւն Դաւթի Որդուն, օրհնեա՜լ է նա, որ գալիս է Տիրոջ անունով, օրհնութի՜ւն՝ բարձունքներում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Եւ երբ նա մտաւ Երուսաղէմ, ամբողջ քաղաքը դղրդաց, եւ ասում էին՝ ո՞վ է սա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Իսկ ժողովրդի բազմութիւնն ասում էր. «Սա Յիսուս մարգարէն է, որ Գալիլիայի Նազարէթ քաղաքից է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Եւ Յիսուս մտաւ տաճար ու դուրս հանեց բոլոր նրանց, որ տաճարի մէջ վաճառում ու գնումներ էին անում. նա շուռ տուեց լումայափոխների սեղաններն ու աղաւնեվաճառների աթոռները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Եւ նրանց ասաց. «Գրուած է՝ իմ տունը աղօթքի տուն պիտի կոչուի, իսկ դուք աւազակների որջ էք արել այդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Տաճարի մէջ կոյրեր եւ կաղեր Յիսուսին մօտեցան, եւ նա բժշկեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Երբ քահանայապետներն ու օրէնսգէտները տեսան այն սքանչելիքները, որ նա արեց, եւ մանուկներին, որ տաճարի մէջ աղաղակում էին ու ասում՝ օրհնութի՜ւն Դաւթի Որդուն, բարկացան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'եւ ասացին նրան. «Լսո՞ւմ ես՝ դրանք ինչ են ասում»: Յիսուս նրանց ասաց. «Այո՛, դուք չէ՞ք կարդացել, թէ՝ երեխաների ու ծծկերների բերանով օրհնութիւն կատարեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Եւ նրանց թողնելով՝ ելաւ քաղաքից դուրս, դէպի Բեթանիա. եւ այնտեղ գիշերեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Եւ առաւօտեան երբ քաղաք վերադարձաւ, քաղց զգաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Եւ ճանապարհի վրայ մի թզենի տեսնելով՝ եկաւ դէպի այն եւ նրա վրայ ոչինչ չգտաւ, այլ միայն՝ տերեւ: Եւ թզենուն ասաց. «Այսուհետեւ քեզնից յաւիտեան պտուղ թող չլինի»: Եւ նոյն պահին թզենին չորացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Երբ աշակերտները այս տեսան, զարմացան ու ասացին. «Ինչպէ՞ս թզենին իսկոյն չորացաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Ճշմարիտ եմ ասում ձեզ, եթէ հաւատ ունենաք եւ չերկմտէք, ոչ միայն կ՚անէք այդ թզենուն պատահածը, այլ թէկուզ եւ այդ լերանն ասէք՝ ելի՛ր ու ծովն ընկիր, այն կը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Եւ ամէն ինչ, որ ուզէք աղօթքի մէջ հաւատով, կը ստանաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Եւ երբ տաճար եկաւ, մինչ ուսուցանում էր, նրան մօտեցան քահանայապետները, ժողովրդի ծերերը եւ ասացին. «Ի՞նչ իշխանութեամբ ես այդ անում, եւ ո՞վ տուեց քեզ այդ իշխանութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Ես էլ ձեզ մի բան հարցնեմ. եթէ ինձ ասէք, ես էլ ձե՛զ կ՚ասեմ, թէ ինչ իշխանութեամբ եմ այս անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Յովհաննէսի մկրտութիւնը որտեղի՞ց էր՝ երկնքի՞ց, թէ՞՝ մարդկանցից»: Նրանք իրար մէջ խորհուրդ էին անում ու ասում. «Եթէ ասենք՝ երկնքից, մեզ կ՚ասի՝ իսկ ինչո՞ւ չհաւատացիք նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'իսկ եթէ ասենք՝ մարդկանցից, ժողովրդից վախենում ենք, որովհետեւ բոլորն էլ Յովհաննէսին որպէս մարգարէ են ընդունում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Պատասխանեցին Յիսուսին ու ասացին՝ չգիտենք: Նա էլ նրանց ասաց. «Ես էլ ձեզ չեմ ասի, թէ ինչ իշխանութեամբ եմ այս անում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, '«Բայց ինչպէ՞ս է ձեզ թւում. մի մարդ երկու որդի ունէր: Առաջինին մօտենալով՝ նա ասաց. «Որդեա՛կ, գնա՛ այսօր աշխատի՛ր այգում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Սա պատասխանեց ու ասաց. «Գնում եմ, տէ՛ր». ու չգնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Մօտեցաւ միւսին էլ եւ նոյնն ասաց: Սա պատասխանեց ու ասաց. «Չեմ ուզում»: Բայց յետոյ զղջաց եւ գնաց այգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Արդ, երկուսից ո՞վ կատարեց հօր կամքը»: Նրանք ասացին՝ վերջինը: Յիսուս նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ մաքսաւորներ ու պոռնիկներ ձեզնից առաջ պիտի հասնեն արքայութիւն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'որովհետեւ Յովհաննէսը արդարութեան ճանապարհով եկաւ, եւ նրան չհաւատացիք. իսկ մաքսաւորներ ու պոռնիկներ հաւատացին նրան. եւ դուք այդ տեսաք եւ յետոյ էլ չզղջացիք, որ նրան հաւատայիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '«Լսեցէ՛ք մի այլ առակ. մի տանուտէր կար, որ այգի տնկեց եւ այն ցանկապատեց ու նրա մէջ հնձան փորեց եւ աշտարակ շինեց. ապա այն վարձու տուեց մշակներին եւ գնաց հեռու երկիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Երբ պտղի ժամանակը մօտեցաւ, իր ծառաներին ուղարկեց այն մշակների մօտ, որպէսզի բերքից իր բաժինը առնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Իսկ մշակները նրա ծառաներին բռնելով՝ մէկին տանջեցին, մէկին սպանեցին, մէկին քարկոծեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Դարձեալ ուրիշ ծառաներ ուղարկեց՝ թուով աւելի, քան առաջինները: Եւ սրանց էլ նոյնն արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Յետոյ նրանց մօտ ուղարկեց իր որդուն ու ասաց՝ թերեւս իմ այս որդուց ամաչեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Իսկ մշակները, երբ տեսան որդուն, իրենց մտքում ասացին՝ սա է ժառանգը, եկէք սպանենք սրան եւ սրա ժառանգութիւնը մենք սեփականացնենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Եւ նրան բռնեցին հանեցին այգուց դուրս եւ սպանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Արդ, երբ այգու տէրը գայ, այդ մշակներին ի՞նչ կ՚անի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Նրանք ասացին նրան. «Չարերին չարաչար կ՚ոչնչացնի եւ այգին կը տայ այլ մշակների, որոնք նրան կը տան պտուղներն իրենց ժամանակին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Յիսուս նրանց ասաց. «Սուրբ Գրքերում երբեւիցէ չէ՞ք կարդացել՝ այն վէմը, որ կառուցողները անարգեցին, նա՛ է, որ եղաւ անկիւնաքար. Տիրոջից եղաւ այս, եւ մեր աչքին սքանչելի է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Դրա համար ասում եմ ձեզ, որ ձեզնից կը վերցուի Աստծու արքայութիւնը եւ կը տրուի այն ազգին, որ պտղաբեր կը դարձնի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Եւ ով այս վէմի վրայ ընկնի, կը փշրուի, եւ ում վրայ այն ընկնի, նրան կը ճզմի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Երբ քահանայապետները եւ օրէնսգէտներ ու փարիսեցիներ նրա առակները լսեցին, իմացան, որ իրենց համար ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Եւ ուզում էին նրան բռնել, բայց վախեցան ժողովրդից, քանի որ իբրեւ մարգարէ էին ընդունում նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Յիսուս դարձեալ պատասխանեց եւ առակներով ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '«Երկընքի արքայութիւնը նմանուեց մի թագաւորի, որ իր որդու համար հարսանիք արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Եւ ուղարկեց իր ծառաներին՝ հրաւիրուածներին հարսանիքի կանչելու. ու նրանք չուզեցին գալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Դարձեալ ուրիշ ծառաներ ուղարկեց՝ ասելով. «Հրաւիրուածներին ասացէ՛ք՝ ահա իմ ճաշկերոյթը պատրաստեցի. իմ զուարակները եւ իմ պարարտ անասունները մորթուած են, ու ամէն ինչ պատրաստ է, եկէ՛ք հարսանիքի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Սակայն նրանք, բանի տեղ չդնելով, գնացին՝ մէկն իր ագարակը, մէկն իր առեւտրին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'ուրիշներ էլ բռնեցին նրա ծառաներին, անպատուեցին ու սպանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Իսկ թագաւորը երբ լսեց, բարկացաւ եւ իր զօրքն ուղարկեց ու բնաջնջեց սպանողներին եւ այրեց նրանց քաղաքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Ապա իր ծառաներին ասաց. «Հարսանիքը պատրաստ է, բայց հրաւիրուածները արժանի չէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Արդ, գնացէ՛ք հրապարակները եւ ում որ գտնէք, կանչեցէ՛ք հարսանիքի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Եւ ծառաները ճանապարհների վրայ ելնելով՝ հաւաքեցին բոլոր նրանց, ում գտան՝ ե՛ւ չարերին, ե՛ւ բարիներին. եւ հարսանիքը լցուեց հրաւիրուածներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Եւ երբ թագաւորը ներս մտաւ հրաւիրուածներին նայելու, այնտեղ տեսաւ մի մարդու, որ հարսանիքի զգեստ չէր հագել, ու նրան ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, '«Ընկե՛ր, որ հարսանիքի զգեստ չունէիր, ինչպէ՞ս այստեղ մտար»: Եւ նա պապանձուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Այն ժամանակ թագաւորը ծառաներին ասաց. «Կապեցէ՛ք դրա ոտքերն ու ձեռքերը եւ դո՛ւրս հանեցէք դրան, արտաքին խաւարը. այնտեղ կը լինի լաց եւ ատամների կրճտում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'որովհետեւ կանչուածները բազում են, իսկ ընտրեալները՝ սակաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Այն ժամանակ փարիսեցիները գնացին խորհուրդ արեցին նրա մասին, թէ ինչպէս խօսքերով նրան որոգայթ լարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Եւ նրա մօտ ուղարկեցին իրենց աշակերտներից ոմանց՝ հերովդէսականների հետ միասին եւ ասացին. «Վարդապե՛տ, գիտենք, որ ճշմարտախօս ես եւ Աստծու ճանապարհը ճշմարտութեամբ ես ուսուցանում. եւ ոչ մէկից չես քաշւում ու ոչ մի մարդու աչառութիւն չ»ս անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Արդ, ասա՛ մեզ, ինչպէ՞ս է քեզ թւում. պէ՞տք է հարկ տալ կայսրին, թէ՞՝ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Յիսուս հասկացաւ նրանց խորամանկութիւնն ու ասաց. «Ինչո՞ւ էք ինձ փորձում, կեղծաւորնե՛ր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'ինձ հարկի դահեկա՛ն ցոյց տուէք»: Եւ նրանք մի դահեկան բերեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Եւ նա ասաց նրանց. «Այս պատկերը կամ գիրը ո՞ւմն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Նրանք ասացին՝ կայսրինը: Այն ժամանակ նրանց ասաց. «Գնացէ՛ք, տուէ՛ք կայսրինը՝ կայսեր եւ Աստծունը՝ Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Երբ այս լսեցին, զարմացան եւ թողեցին նրան ու գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Նոյն օրը նրան մօտեցան սադուկեցիները, որոնք ասում էին, թէ յարութիւն չկայ. հարց տուեցին նրան ու ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '«Վարդապե՛տ, Մովսէսն ասաց, որ՝ եթէ մէկն անժառանգ մեռնի, նրա եղբայրը նրա կնոջը պիտի առնի եւ իր եղբօրը զաւակ հասցնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Մեզ մօտ եօթը եղբայրներ կային. առաջինը կին առաւ ու ապա մեռաւ. եւ որովհետեւ զաւակ չունէր, կնոջն իր եղբօրը թողեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Նոյնպէս եւ երկրորդը եւ երրորդը, մինչեւ եօթներորդը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Բոլորից յետոյ կինն էլ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Արդ, յարութեան ժամանակ եօթից ո՞ւմ կին կը լինի նա, քանի որ բոլորն էլ նրան իբրեւ կին ունեցան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Յիսուս պատասխանեց նրանց ու ասաց. «Մոլորուածնե՛ր, ո՛չ Գրքերն էք հասկանում եւ ո՛չ էլ Աստծու զօրութիւնը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'որովհետեւ յարութեան ժամանակ ո՛չ կին են առնում եւ ո՛չ էլ մարդու գնում, այլ կը լինեն՝ ինչպէս հրեշտակները երկնքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Բայց մեռելների յարութեան մասին չէ՞ք կարդացել Աստծուց ձեզ ասուածը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'ե՛ս եմ Աբրահամի Աստուածը, Իսահակի Աստուածը եւ Յակոբի Աստուածը. եւ Աստուած՝ մեռելների Աստուածը չէ, այլ՝ կենդանիների»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Երբ ժողովուրդը այս լսեց, զարմացաւ նրա ուսուցման վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Իսկ փարիսեցիները երբ լսեցին, թէ նա պապանձեցրեց սադուկեցիներին, ի մի հաւաքուեցին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'եւ նրանցից մէկը նրան փորձելով՝ հարցրեց ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '«Վարդապե՛տ, Օրէնքի մէջ ո՞ր պատուիրանն է մեծ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Եւ Յիսուս նրան ասաց. «Պիտի սիրես քո Տէր Աստծուն քո ամբողջ սրտով, քո ամբողջ հոգով ու քո ամբողջ մտքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Այս է մեծը եւ առաջին պատուիրանը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'եւ երկրորդը սրա նման է. պիտի սիրես քո ընկերոջը, ինչպէս քո անձը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Այս երկու պատուիրաններից են կախուած ամբողջ Օրէնքը եւ մարգարէները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Եւ երբ փարիսեցիները հաւաքուեցին, Յիսուս նրանց հարցրեց ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '«Ի՞նչ կարծիք ունէք Քրիստոսի մասին, ո՞ւմ որդին է»: Նրան ասացին՝ Դաւթի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Յիսուս նրանց ասաց. «Իսկ Դաւիթն ինչպէ՞ս նրան Սուրբ Հոգով կոչում է Տէր եւ ասում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '«Տէրն իմ տիրոջն ասաց՝ նստի՛ր իմ աջ կողմում, մինչեւ որ քո թշնամիներին դնեմ քո ոտքերի տակ իբրեւ պատուանդան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Իսկ եթէ Դաւիթը նրան Տէր է կոչում, ինչպէ՞ս նրա որդին կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Եւ ոչ ոք նրան մի բառ պատասխան չկարողացաւ տալ: Եւ այդ օրուանից ոչ ոք չէր համարձակւում նրան մի որեւէ բան հարցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Այն ժամանակ Յիսուս խօսեց ժողովրդին եւ իր աշակերտներին ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '«Մովսէսի աթոռի վրայ նստեցին օրէնսգէտներն ու փարիսեցիները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'ամէն ինչ, որ նրանք ձեզ ասեն, արէ՛ք եւ պահեցէ՛ք, բայց մի՛ արէք ըստ նրանց գործերի, քանի որ ասում են, բայց չեն անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Ծանր ու դժուարակիր բեռներ են կապում եւ դնում մարդկանց ուսերի վրայ, բայց իրենց մատով անգամ չեն կամենում շարժել դրանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Եւ իրենց բոլոր գործերն անում են՝ ի ցոյց մարդկանց. լայնացնում են իրենց գրապանակները եւ երկարացնում են իրենց զգեստների ծոպերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Սիրում են ընթրիքների ժամանակ պատուոյ տեղերը, ժողովարաններում՝ նախապատիւ աթոռները եւ հրապարակներում ողջոյններ առնել');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'ու մարդկանցից կոչուել՝ ռաբբի, որ նշանակում է ուսուցիչ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Բայց դուք որեւէ մէկին ուսուցիչ մի՛ կոչէք, որովհետեւ ձեր ուսուցիչը մէկ է, եւ դուք բոլորդ եղբայրներ էք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Եւ երկրի վրայ ոչ մէկին ձեզ հայր մի՛ կոչէք, որովհետեւ մէ՛կ է ձեր Հայրը, որ երկնքում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Եւ ուսուցիչներ չկոչուէք, որովհետեւ Քրիստոս է ձեր ուսուցիչը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Եւ ձեզնից մեծը ձեր սպասաւորը պիտի լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Ով իր անձը բարձրացնում է, կը խոնարհուի. եւ ով խոնարհեցնում է իր անձը, կը բարձրանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ երկնքի արքայութիւնը փակում էք մարդկանց առաջ. դուք չէք մտնում եւ մտնողներին էլ թոյլ չէք տալիս, որ մտնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ շրջում էք ծովի ու ցամաքի վրայ՝ անգամ մէկին նորահաւատ դարձնելու համար, եւ երբ նա այդպիսին է դառնում, նրան ձեզանից կրկնակի անգամ աւելի գեհենի որդի էք դարձնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Վա՜յ ձեզ, կո՛յր առաջնորդներ, որ ասում էք՝ ով որ երդուի տաճարի վրայ, այդ երդումը ոչինչ չի նշանակում. բայց ով որ երդուի տաճարի մէջ եղած ոսկու վրայ, պարտաւորւում է այն կատարել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Յիմարնե՛ր եւ կոյրե՛ր, ի՞նչն է մեծ՝ ոսկի՞ն, թէ՞ տաճարը, որ սրբացնում է ոսկին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Եւ՝ ով որ երդուի սեղանի վրայ, այդ երդումը ոչինչ չի նշանակում. բայց ով որ երդուի նրա վրայ գտնուող ընծայի վրայ, պարտաւորւում է այն կատարել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Յիմարնե՛ր եւ կոյրե՛ր, ի՞նչն է մեծ՝ ընծա՞ն, թէ՞ սեղանը, որ սրբագործում է ընծան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Իսկ արդ, ով որ երդուեց սեղանի վրայ, երդուած կը լինի նրա վրայ եւ այն ամենի վրայ, որ սեղանի վրայ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Եւ ով երդուեց տաճարի վրայ, երդուած կը լինի նրա եւ նրա մէջ բնակուող Աստծու վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Եւ ով երդուեց երկնքի վրայ, երդուած կը լինի Աստծու աթոռի եւ նրա վրայ նստողի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ տալիս էք անանուխի եւ սամիթի ու չամանի տասանորդը, բայց թողել էք օրէնքի ամենից կարեւորները՝ արդարադատութիւնը, ողորմութիւնը եւ հաւատը. հարկ էր այս անել եւ այն չթողն»լ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Կո՛յր առաջնորդներ, որ մժղուկները քամում էք եւ ուղտերը կուլ էք տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ բաժակի ու պնակի դուրսը մաքրում էք, մինչ ներսից նրանք լի են ձեր գողութեամբ եւ անժուժկալութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Կո՛յր փարիսեցի, նախ մաքրի՛ր բաժակի եւ պնակի ներսը, որպէսզի դրանց դուրսն էլ մաքուր լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ նման էք սպիտակեցրած գերեզմանների, որոնք դրսից գեղեցիկ են երեւում, մինչ ներսից լի են մեռելների ոսկորներով եւ ամենայն ապականութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Նոյնպէս եւ դուք, դրսից մարդկանց արդար էք երեւում, մինչ ներսից լի էք կեղծաւորութեամբ եւ անօրէնութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Վա՜յ ձեզ կեղծաւորներիդ՝ օրէնսգէտներիդ եւ փարիսեցիներիդ, որ մարգարէների շիրիմներն էք շինում եւ արդարների գերեզմաններն էք զարդարում ու ասում էք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, '«Եթէ մենք մեր հայրերի օրօք լինէինք, մարգարէների սպանութեանը մասնակից չէինք լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Ապա ուրեմն դուք ինքներդ ձեր մասին վկայում էք, թէ որդիներն էք նրանց, որոնք կոտորում էին մարգարէներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Ուրեմն դուք էլ լրացրէ՛ք ձեր հայրերի արածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, '«Օձե՛ր, իժերի՛ ծնունդներ, ինչպէ՞ս պիտի փախչէք գեհենի դատապարտութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Դրա համար ահա ես ձեզ մօտ ուղարկում եմ մարգարէներ, իմաստուններ ու օրէնսգէտներ. նրանցից ոմանց դուք պիտի սպանէք եւ խաչը պիտի հանէք. նրանցից ոմանց էլ պիտի տանջէք ձեր ժողովարաններում ու քաղաքից քաղաք պիտի հալածէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'որպէսզի ձեր վրայ ընկնի մեղքը երկրի վրայ թափուած ամէն արդար արեան՝ արդար Աբէլի արիւնից մինչեւ արիւնը Բարաքիայի որդի Զաքարիայի, որին սպանեցիք տաճարի եւ զոհասեղանի միջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Ճշմարիտ եմ ասում ձեզ, այս բոլորը պիտի գայ այս սերնդի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, '«Երուսաղէ՜մ, Երուսաղէ՜մ, որ կոտորում էիր մարգարէներին եւ քարկոծում էիր քեզ մօտ ուղարկուածներին. քանի՜ անգամ կամեցայ հաւաքել քո մանուկներին, ինչպէս հաւն է հաւաքում իր ձագերին թեւերի տակ, բայց չկամեցաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Ահա ձեր տունը աւերակ կը թողնուի ձեզ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'բայց ձեզ ասում եմ, որ այսուհետեւ ինձ այլեւս չէք տեսնի, մինչեւ որ ասէք՝ օրհնեա՜լ է նա, որ գալիս է Տիրոջ անունով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Յիսուս տաճարից դուրս ելած՝ գնում էր. եւ աշակերտները մօտեցան՝ նրան ցոյց տալու տաճարի շինութիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Եւ նա պատասխանեց ու նրանց ասաց. «Տեսնո՞ւմ էք այդ ամէնը. ճշմարիտ եմ ասում ձեզ, այդտեղ չպիտի մնայ քար քարի վրայ, որ չքանդուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Եւ մինչ դեռ նստած էր Ձիթենեաց լերան վրայ, աշակերտները առանձին մօտեցան նրան ու ասացին. «Ասա՛ մեզ, այդ ե՞րբ կը լինի, եւ կամ քո գալստեան ու այս աշխարհի վախճանի նշանն ի՞նչ կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Զգո՛յշ եղէք, գուցէ մէկը ձեզ խաբի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'որովհետեւ շատերը կը գան իմ անունով ու կ՚ասեն, թէ՝ ես եմ Քրիստոսը. եւ շատերին կը մոլորեցնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Լսելու էք պատերազմների ձայներ եւ պատերազմների լուրեր. զգո՛յշ եղէք, չխռովուէք, որովհետեւ պէտք է, որ այդ ամէնը լինի, բայց դա դեռ վախճանը չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Ազգ ազգի դէմ պիտի ելնի, եւ թագաւորութիւն՝ թագաւորութեան դէմ, եւ պիտի լինեն սով, համաճարակ ու տեղ-տեղ երկրաշարժներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Սակայն այս ամէնը սկիզբն է երկանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Այն ժամանակ ձեզ նեղութեան պիտի մատնեն եւ պիտի սպանեն ձեզ. եւ իմ անուան պատճառով բոլոր ազգերի կողմից ատելի պիտի լինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Եւ այն ժամանակ շատերը պիտի գայթակղուեն եւ միմեանց պիտի մատնեն ու միմեանց պիտի ատեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Եւ բազում սուտ մարգարէներ պիտի ելնեն ու շատերին պիտի մոլորեցնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Եւ անօրինութեան շատանալուց՝ շատերի սէրը պիտի ցամաքի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Բայց ով մինչեւ վերջ համբերեց, նա պիտի փրկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Եւ արքայութեան այս Աւետարանը պիտի քարոզուի ամբողջ աշխարհում՝ ի վկայութիւն բոլոր հեթանոսների. եւ ապա պիտի գայ վախճանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, '«Արդ, երբ տեսնէք սարսափելի սրբապղծութիւնը, - որի մասին ասուած է Դանիէլ մարգարէի միջոցով, - որ հաստատուած է սուրբ վայրում (ով ընթերցում է, թող հասկանայ),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'այն ժամանակ, ովքեր Հրէաստանում կը լինեն, թող փախչեն լեռները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'եւ ով տանիքի վրայ կը լինի, իր տնից բան վերցնելու համար թող ցած չիջնի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'եւ ով հանդում կը լինի, իր վերնազգեստը վերցնելու համար թող յետ չդառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Բայց վա՜յ այդ օրերին յղիներին ու ստնտուներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Աղօթեցէ՛ք, որ ձեր փախուստը չլինի ձմրանը եւ ոչ էլ շաբաթ օրը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'որովհետեւ այդ ժամանակ մեծ նեղութիւն պիտի լինի, որպիսին չի եղել աշխարհի արարչագործութեան սկզբից մինչեւ այժմ եւ այլեւս չի էլ լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Եւ եթէ այդ օրերը չկարճեցուէին, ոչ մի մարմին չէր ազատուի. բայց ընտրեալների պատճառով այդ օրերը պիտի կարճեցուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Այն ժամանակ եթէ մէկը ձեզ ասի՝ ահա՛ Քրիստոսը այստեղ է կամ այնտեղ, չհաւատաք նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'որովհետեւ սուտ քրիստոսներ եւ սուտ մարգարէներ պիտի ելնեն եւ մեծամեծ նշաններ ու զարմանալի գործեր պիտի ցոյց տան՝ Աստծու ընտրեալներին անգամ մոլորեցնելու աստիճան, եթէ հնար լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Ահա ձեզ առաջուց ասացի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Ապա եթէ ձեզ ասեն՝ ահա՛ անապատի մէջ է, չելնէք, կամ թէ՝ ահա՛ մառանում է, չհաւատաք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'որովհետեւ ինչպէս փայլակը, որ ելնում է արեւելքից եւ երեւում է մինչեւ արեւմուտք, մարդու Որդու գալուստը այնպէս կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Ուր որ դիակն է, այնտե՛ղ կը հաւաքուեն արծիւները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, '«Այդ օրերի նեղութիւնից անմիջապէս յետոյ, արեգակը պիտի խաւարի, եւ լուսինը իր լոյսը չպիտի տայ, եւ աստղերը երկնքից պիտի ընկնեն, ու երկնքի զօրութիւններ պիտի շարժուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Եւ ապա երկնքի վրայ մարդու Որդու նշանը պիտի երեւայ, ու այդ ժամանակ երկրի բոլոր ազգերը լացուկոծ պիտի անեն եւ պիտի տեսնեն մարդու Որդուն, որ գալիս է երկնքի ամպերի վրայով՝ զօրութեամբ եւ բազում փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Եւ նա պիտի ուղարկի իր հրեշտակներին մեծ շեփորով, ու պիտի հաւաքեն նրա ընտրեալներին չորս կողմերից՝ երկնքի ծագերից մինչեւ միւս ծագերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, '«Թզենո՛ւց սովորեցէք առակը. որովհետեւ, երբ նրա ոստերը կակղեն, եւ տերեւը ցցուի, կ՚իմանաք, որ ամառը մօտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Նոյնպէս եւ դուք՝ երբ այս բոլորը տեսնէք, իմացէ՛ք, թէ մօտ է Նա, դռների առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Ճշմարիտ եմ ասում ձեզ, որ այս սերունդը չպիտի անցնի, մինչեւ որ այս ամէնը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Երկինք եւ երկիր պիտի անցնեն, բայց իմ խօսքերը չպիտի անցնեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, '«Բայց այդ օրուայ եւ ժամուայ մասին ոչ ոք չգիտէ. ո՛չ երկնքի հրեշտակները եւ ո՛չ էլ Որդին, այլ՝ միայն Հայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Եւ ինչպէս Նոյի օրերն էին, այնպէս պիտի լինի մարդու Որդու գալստեանը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'որովհետեւ, ինչպէս որ ջրհեղեղից առաջ եղած օրերն էին, - երբ ուտում էին եւ խմում, կին էին առնում ու մարդու էին գնում, մինչեւ այն օրը, երբ Նոյը տապանը մտաւ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'ու նրանք բան չիմացան մինչեւ որ ջրհեղեղը եկաւ ու վերցրեց տարաւ բոլորին, - այնպէս պիտի լինի մարդու Որդու գալստեանն էլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Այն ժամանակ, եթէ դաշտի մէջ երկու հոգի լինեն, մէկը պիտի վերցուի, եւ միւսը պիտի թողնուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Եւ եթէ երկու կին աղան մի երկանքի վրայ, մէկը պիտի վերցուի, եւ միւսը պիտի թողնուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Արթո՛ւն կացէք, որովհետեւ չգիտէք, թէ ո՛ր ժամին կը գայ ձեր Տէրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Ա՛յս իմացէք. եթէ տանտէրը գիտենար, թէ ո՛ր ժամին գող կը գայ, կը հսկէր եւ չէր թողնի, որ իր տունը ծակեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Դրա համար դուք էլ պատրա՛ստ եղէք, որովհետեւ այն ժամին, երբ չէք սպասում, մարդու Որդին կը գայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, '«Իսկ ո՞վ է այն հաւատարիմ եւ իմաստուն ծառան, որին իր տէրը իր ծառաների վրայ կարգեց՝ իր ժամին կերակուր տալու համար նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Երանի՜ է այն ծառային, որին տէրը, գալով, կը գտնի այդպէս արած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Ճշմարիտ եմ ասում ձեզ, որ նրան կը կարգի իր ամբողջ ունեցուածքի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Իսկ եթէ չար ծառան իր մտքում ասի՝ իմ տէրը ուշանում է գալ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'եւ սկսի իր ծառայակիցներին հարուածել եւ հարբեցողների հետ ուտի եւ խմի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'եւ այդ ծառայի տէրը գայ այն օրը, երբ չէր սպասում, եւ այն ժամին, երբ չէր իմանում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'նրան կը սպանի եւ կեղծաւորների վախճանին կ՚արժանացնի. այնտեղ կը լինի լաց ու ատամների կրճտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '«Այն ժամանակ երկնքի արքայութիւնը պիտի նմանեցուի տասը կոյսերի, որոնք իրենց լապտերներն առած՝ փեսային եւ հարսին դիմաւորելու ելան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Նրանցից հինգը յիմար էին, իսկ հինգը՝ իմաստուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Յիմարները լապտերներն առան, բայց իրենց հետ պահեստի ձէթ չվերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Իսկ իմաստունները իրենց լապտերների հետ միասին ամաններով ձէթ վերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Եւ երբ փեսան ուշացաւ, ամէնքն էլ նիրհեցին եւ քուն մտան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Եւ կէսգիշերին ձայն լսուեց՝ ահա՛ փեսան գալիս է, նրան դիմաւորելո՛ւ ելէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Այն ժամանակ բոլոր կոյսերը վեր կացան եւ իրենց լապտերները կարգի բերեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Յիմարները իմաստուններին ասացին. «Ձեր այդ իւղից տուէ՛ք մեզ, որովհետեւ ահա մեր լապտերները հանգչում են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Իմաստունները պատասխան տուեցին եւ ասացին. «Գուցէ թէ՛ մեզ եւ թէ՛ ձեզ չբաւականացնի, ուստի գնացէ՛ք վաճառողների մօտ եւ ձեզ համար գնեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Երբ նրանք գնացին, որ գնեն, փեսան եկաւ, եւ ովքեր պատրաստ էին, նրա հետ հարսանիքի սրահը մտան, ու դուռը փակուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Յետոյ եկան միւս կոյսերն էլ ու ասացին. «Տէ՛ր, տէ՛ր, բա՛ց արա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Նա պատասխան տուեց ու ասաց. «Ճշմարիտ եմ ասում ձեզ, որ ձեզ չեմ ճանաչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Արթո՛ւն կացէք, որովհետեւ չգիտէք ո՛չ օրը եւ ո՛չ էլ ժամը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, '«Նոյնպէս, մի մարդ, հեռու երկիր գնալիս, կանչեց իր ծառաներին եւ իր ունեցուածքը նրանց տուեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'մէկին տուեց հինգ քանքար, միւսին՝ երկու եւ մի ուրիշին՝ մէկ. իւրաքանչիւրին ըստ իր կարողութեան. եւ գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Ով հինգն առաւ, իսկոյն գնաց, դրանով գործ արեց եւ հինգ եւս շահեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Նոյնպէս նա էլ, որ երկուսն առաւ, երկու եւս շահեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Իսկ ով մէկն առաւ, գնաց հողը փորեց եւ իր տիրոջ դրամը թաքցրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Շատ ժամանակ անց, այն ծառաների տէրը եկաւ եւ նրանց հետ հաշիւ տեսաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Ով հինգ քանքար էր առել, մօտենալով՝ հինգ քանքար եւս տուեց ու ասաց. «Տէ՛ր, հինգ քանքար տուիր ինձ. արդ, ահաւասիկ վրան հինգ քանքար եւս շահեցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Իր տէրը նրան ասաց. «Ապրե՛ս, բարի՛ եւ հաւատարի՛մ ծառայ, որովհետեւ այդ քչի մէջ հաւատարիմ եղար, շատի վրայ կը կարգեմ քեզ. մտի՛ր քո տիրոջ ուրախութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Ով երկու քանքարն էր առել, նա էլ մօտեցաւ ու ասաց. «Տէ՛ր, ինձ երկու քանքար տուիր, ահաւասիկ երկու այլ քանքար եւս, որ դրանց վրայ շահեցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Իր տէրը նրան ասաց. «Ապրե՛ս, բարի՛ եւ հաւատարի՛մ ծառայ, որովհետեւ այդ քչի մէջ հաւատարիմ եղար, շատի վրայ կը կարգեմ քեզ. մտի՛ր քո տիրոջ ուրախութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Մօտեցաւ նաեւ նա, որ մէկ քանքար էր առել, ու ասաց. «Տէ՛ր, գիտէի, որ դու մի խիստ մարդ ես, հնձում ես, ինչ որ չես սերմանել, եւ հաւաքում ես այնտեղից, ուր չես ցանել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'վախեցայ. գնացի եւ թաքցրի քո այս քանքարը հողի մէջ: Արդ, ահա՛ւասիկ, քոնը՝ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Տէրը պատասխան տուեց եւ ասաց նրան. «Չա՛ր եւ ծո՛յլ ծառայ, գիտէիր, որ հնձում եմ, ուր չեմ սերմանել, եւ հաւաքում այնտեղից, ուր չեմ ցանել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'դու պէտք է իմ այդ դրամը լումայափոխների մօտ դնէիր, եւ ես, գալով, տոկոսով միասին պահանջէի այն, ինչ որ իմն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Արդ, դրանից առէ՛ք այդ քանքարը եւ տուէ՛ք նրան, ով տասը քանքար ունի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'քանի որ՝ ով ունի, նրան պիտի տրուի եւ ունեցածը պիտի աւելացուի, իսկ ով չունի, նրանից ունեցածն էլ պիտի վերցուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Իսկ այդ անպիտան ծառային հանեցէ՛ք դուրս, արտաքին խաւարը. այնտեղ կը լինի լաց եւ ատամների կրճտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '«Արդ, երբ որ մարդու Որդին գայ իր փառքով եւ բոլոր հրեշտակները՝ իր հետ, այն ժամանակ նա պիտի նստի իր փառքի գահի վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'ու նրա առաջ պիտի հաւաքուեն բոլոր ազգերը, եւ նա նրանց միմեանցից պիտի զատի, ինչպէս մի հովիւ, որ զատում է ոչխարները այծերից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Եւ ոչխարները իր աջին պիտի կանգնեցնի, իսկ այծերը՝ ձախին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Այն ժամանակ թագաւորը պիտի ասի նրանց, որ իր աջին են. «Եկէ՛ք, իմ Հօր օրհնեալնե՛ր, ժառանգեցէ՛ք աշխարհի սկզբից ձեզ համար պատրաստուած արքայութիւնը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'որովհետեւ քաղցած էի, եւ ինձ ուտելիք տուիք, ծարաւ էի, եւ ինձ ջուր տուիք՝ խմելու. օտար էի, եւ ինձ ձեր մէջ առաք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'մերկ էի, եւ ինձ հագցրիք, հիւանդ էի, եւ ինձ տեսնելու եկաք, բանտում էի, եւ ինձ այցի եկաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Այն ժամանակ արդարները պիտի պատասխանեն նրան ու ասեն. «Տէ՛ր, ե՞րբ տեսանք քեզ քաղցած ու կերակրեցինք, կամ՝ ծարաւ եւ ջուր տուեցինք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'ե՞րբ տեսանք քեզ օտար եւ մեր մէջ առանք, կամ՝ մերկ եւ հագցրինք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'ե՞րբ տեսանք քեզ հիւանդ կամ բանտի մէջ ու եկանք քեզ այցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Թագաւորը պիտի պատասխանի ու ասի նրանց. «Ճշմարիտ եմ ասում ձեզ, քանի որ իմ այս փոքր եղբայրներից մէկին արեցիք այդ՝ ի՛նձ համար արեցիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Այն ժամանակ նա պիտի ասի նրանց, որ իր ձախին են. «Անիծեալնե՛ր, գնացէ՛ք ինձնից յաւիտենական կրակը, որ պատրաստուած է սատանայի եւ իր հրեշտակների համար.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'որովհետեւ քաղցած էի, եւ ինձ ուտելիք չտուիք, ծարաւ էի, եւ ինձ ջուր չտուիք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'օտար էի, եւ ինձ ձեր մէջ չառաք, մերկ էի, եւ ինձ չհագցրիք, հիւանդ էի ու բանտի մէջ, եւ ինձ տեսնելու չեկաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Այն ժամանակ նրանք էլ պիտի պատասխանեն ու ասեն. «Տէ՛ր, ե՞րբ տեսանք քեզ քաղցած, կամ ծարաւ, կամ օտար, կամ մերկ, կամ հիւանդ, կամ բանտի մէջ ու քեզ չծառայեցինք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Այն ժամանակ պիտի պատասխանի նրանց ու ասի. «Ճշմարիտ եմ ասում ձեզ, որովհետեւ այս փոքրերից մէկին ա՛յդ չարեցիք, ինձ համար էլ չարեցիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Եւ նրանք պիտի գնան դէպի յաւիտենական տանջանք, իսկ արդարները՝ յաւիտենական կեանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Երբ Յիսուս այս բոլոր խօսքերը վերջացրեց, իր աշակերտներին ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '«Գիտէք, որ երկու օր յետոյ զատիկ է, եւ մարդու Որդին պիտի մատնուի խաչը ելնելու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Այն ժամանակ քահանայապետները եւ օրէնսգէտներն ու ժողովրդի ծերերը հաւաքուեցին Կայիափա անունով քահանայապետի դահլիճը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'եւ խորհուրդ արեցին, որպէսզի նենգութեամբ բռնեն Յիսուսին ու սպանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Բայց ասում էին. «Ո՛չ այս տօնին, որպէսզի ժողովրդի մէջ խռովութիւն չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Երբ Յիսուս եկաւ Բեթանիա, բորոտ Սիմոնի տունը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'նրան մօտեցաւ մի կին, որ մի շիշ թանկարժէք իւղ ունէր, եւ թափեց այն նրա գլխին, մինչ նա սեղան էր նստել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Երբ աշակերտներն այս տեսան, բարկացան ու ասացին. «Ինչի՞ համար է անուշահոտ իւղի այդ վատնումը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'քանի որ կարելի էր մեծ գնով վաճառել այդ եւ տալ աղքատներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Յիսուս իմացաւ ու նրանց ասաց. «Ինչո՞ւ էք նեղութիւն տալիս այդ կնոջը. նա իմ հանդէպ մի բարի գործ կատարեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'աղքատներին ամէն ժամ ձեզ հետ ունէք, բայց ինձ միշտ ձեզ հետ չէք ունենայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Իմ մարմնի վրայ այդ իւղը թափելով՝ նա իմ թաղուելը կանխանշեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Բայց ճշմարիտ եմ ասում ձեզ, որ ամբողջ աշխարհում, ուր էլ այս Աւետարանը քարոզուի, պիտի պատմուի դրա յիշատակին, նաեւ ինչ որ դա արեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Այն ժամանակ Տասներկուսից մէկը՝ Յուդա Իսկարիովտացի կոչուածը, գնաց քահանայապետների մօտ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, '«Ի՞նչ կը կամենաք ինձ տալ, որ ես նրան ձեզ մատնեմ»: Եւ նրանք երեսուն արծաթ դրամ խոստացան նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Դրանից յետոյ նա առիթ էր որոնում, որ նրան մատնի նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Եւ Բաղարջակերաց տօնի առաջին օրը աշակերտները մօտեցան Յիսուսին եւ ասացին. «Ո՞ւր ես կամենում՝ պատրաստենք քեզ համար զատկական ընթրիքը, որ ուտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Եւ Յիսուս նրանց ասաց. «Գնացէ՛ք քաղաք այսինչ անձի մօտ եւ նրան ասացէ՛ք. «Վարդապետն ասում է՝ իմ ժամանակը մօտեցել է, քեզ մօտ եմ անելու զատիկը իմ աշակերտների հետ միասին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Եւ աշակերտները արեցին, ինչպէս Յիսուս իրենց հրամայեց, ու պատրաստեցին զատկական ընթրիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Եւ երբ երեկոյ եղաւ, տասներկու աշակերտների հետ սեղան էր նստել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Եւ մինչ նրանք դեռ ուտում էին, նա ասաց. «Ճշմարիտ եմ ասում ձեզ, որ ձեզանից մէկն ինձ մատնելու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Եւ նրանք խիստ տխրեցին. նրանցից իւրաքանչիւրն սկսեց ասել նրան. «Միթէ ե՞ս եմ, Տէ՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Նա պատասխան տուեց ու ասաց. «Ով իր ձեռքն ինձ հետ պնակի մէջ մտցրեց, նա՛ է ինձ մատնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Մարդու Որդին կը գնայ այս աշխարհից, ինչպէս նրա մասին գրուած է, բայց վա՜յ այն մարդուն, ում ձեռքով կը մատնուի մարդու Որդին: Աւելի լաւ կը լինէր նրա համար, եթէ այդ մարդը ծնուած չլինէր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Յուդան, որ մատնելու էր նրան, պատասխանեց ու ասաց. «Միթէ ե՞ս եմ, Վարդապե՛տ»: Նրան ասաց՝ դու ասացիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Եւ մինչ նրանք դեռ ուտում էին, Յիսուս հաց վերցրեց, օրհնեց ու կտրեց եւ տուեց աշակերտներին ու ասաց. «Առէ՛ք, կերէ՛ք, այս է իմ մարմինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Եւ բաժակ վերցնելով՝ գոհութիւն յայտնեց, տուեց նրանց ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, '«Խմեցէ՛ք դրանից բոլորդ, որովհետեւ այդ է նոր ուխտի իմ արիւնը, որ թափւում է շատերի համար՝ իրենց մեղքերի թողութեան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Բայց ասում եմ ձեզ, այսուհետեւ ես այլեւս որթատունկի բերքից չեմ խմի մինչեւ այն օրը, երբ ձեզ հետ կը խմեմ նորը իմ Հօր արքայութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Եւ օրհներգեցին ու ելան Ձիթենեաց լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Այն ժամանակ Յիսուս նրանց ասաց. «Դուք ամէնքդ այս գիշեր իմ պատճառով գայթակղուելու էք. որովհետեւ գրուած է, թէ՝ հովուին պիտի հարուածեմ, եւ հօտի ոչխարները պիտի ցրուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Եւ իմ յարութիւն առնելուց յետոյ, ձեզնից առաջ պիտի գնամ Գալիլիա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Պետրոսը պատասխանեց եւ ասաց նրան. «Թէպէտ եւ ամէնքը քո պատճառով գայթակղուեն, սակայն ես չեմ գայթակղուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Յիսուս նրան ասաց. «Ճշմարիտ եմ ասում քեզ, որ այս գիշեր, դեռ աքաղաղը չկանչած, երեք անգամ ինձ պիտի ուրանաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Պետրոսը նրան ասաց. «Թէ քեզ հետ մեռնել իսկ ինձ հասնի, քեզ չեմ ուրանայ»: Նոյնն ասացին բոլոր աշակերտներն էլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Այն ժամանակ Յիսուս նրանց հետ եկաւ մի տեղ, որի անունը Գեթսեմանի էր, եւ նրանց ասաց. «Նստեցէ՛ք այդտեղ, մինչեւ որ գնամ աղօթեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Եւ իր հետ վերցնելով Պետրոսին եւ Զեբեդէոսի երկու որդիներին՝ սկսեց տրտմել եւ տագնապել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Այն ժամանակ նրանց ասաց. «Հոգիս տխուր է մահու չափ. այստե՛ղ մնացէք եւ ինձ հետ հսկեցէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Եւ մի փոքր առաջ գնալով՝ ընկաւ իր երեսի վրայ, աղօթեց ու ասաց. «Հա՛յր իմ, եթէ կարելի է, այս բաժակը թող ինձնից հեռու անցնի, բայց ոչ՝ ինչպէս ես եմ կամենում, այլ՝ ինչպէս դու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Նա եկաւ աշակերտների մօտ եւ նրանց քնի մէջ գտաւ ու Պետրոսին ասաց. «Այդպէ՜ս, չկարողացա՞ք մէկ ժամ արթուն մնալ ինձ հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Արթո՛ւն մնացէք եւ աղօ՛թք արէք, որպէսզի փորձութեան մէջ չընկնէք. հոգիս յօժար է, բայց մարմինս՝ տկար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Դարձեալ, երկրորդ անգամ, Յիսուս գնաց աղօթքի կանգնեց ու ասաց. «Հա՛յր իմ, եթէ կարելի չէ, որ այս բաժակը ինձնից հեռու անցնի, ապա այն կը խմեմ. քո կա՛մքը թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Եւ գալով՝ դարձեալ նրանց քնի մէջ գտաւ, որովհետեւ նրանց աչքերը ծանրացել էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Թողեց նրանց ու երրորդ անգամ գնաց աղօթքի կանգնեց. եւ դարձեալ նոյն խօսքն ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Այն ժամանակ եկաւ աշակերտների մօտ ու նրանց ասաց. «Ննջեցէ՛ք այսուհետեւ ու հանգստացէ՛ք, քանի որ ահա ժամը հասել է, եւ մարդու Որդին մեղաւորների ձեռքն է մատնւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Վե՛ր կացէք գնանք այստեղից. որովհետեւ ահա հասաւ նա, ով ինձ մատնելու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Եւ մինչ նա դեռ այսպէս խօսում էր, ահա Յուդան՝ Տասներկուսից մէկը, եկաւ. ու նրա հետ՝ քահանայապետների եւ ժողովրդի ծերերի կողմից բազում ամբոխ՝ սրերով ու մահակներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Եւ նա, որ նրան մատնելու էր, նրանց նշան էր տուել ու ասել. «Ում հետ ես համբուրուեմ, նա՛ է, նրան կը բռնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Եւ սա իսկոյն մօտենալով Յիսուսին՝ ասաց. «Ողջո՜յն, Վարդապե՛տ». ու նրա հետ համբուրուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Իսկ Յիսուս նրան ասաց. «Ընկե՛ր, սրա՞ համար դու եկար»: Այն ժամանակ, մօտենալով, ձեռք բարձրացրին Յիսուսի վրայ ու նրան բռնեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Եւ ահա Յիսուսի հետ գտնուողներից մէկը ձեռքը երկարեց եւ իր սուրը հանեց ու հարուածեց քահանայապետի ծառային եւ նրա ականջը կտրեց պոկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Այն ժամանակ Յիսուս նրան ասաց. «Քո սուրը ետ դիր իր տեղը, որովհետեւ, ովքեր սուր են վերցնում, սրով կ՚ընկնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Եւ կամ կարծո՞ւմ ես, թէ չեմ կարող իմ Հօրն աղաչել, որ նա հիմա ինձ համար այստեղ հասցնի հրեշտակների աւելի քան տասներկու գնդեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Էլ ինչպէ՞ս պիտի կատարուէին Սուրբ Գրքերում գրուածները, թէ՝ այսպէս պէտք է լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Այն ժամանակ Յիսուս ամբոխին ասաց. «Սրերով եւ մահակներով իմ դէմ էք ելել՝ բռնելու ինձ իբրեւ մի աւազակի՞: Միշտ ձեզ մօտ, տաճարում նստում էի եւ ուսուցանում, ու ինձ չբռնեցիք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'բայց այս բոլորը եղաւ, որպէսզի մարգարէների Գրուածքները կատարուեն»: Այն ժամանակ աշակերտները բոլորն էլ թողեցին նրան ու փախան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Իսկ նրանք բռնելով Յիսուսին՝ տարան Կայիափա քահանայապետի մօտ, ուր օրէնսգէտներն ու ծերերը հաւաքուել էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Եւ Պետրոսը հեռուից նրան հետեւելով՝ գնաց մինչեւ քահանայապետի գաւիթը եւ ներս մտնելով՝ սպասաւորների հետ նստեց՝ տեսնելու համար վախճանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Իսկ քահանայապետներն ու ամբողջ ատեանը Յիսուսի մասին սուտ վկայութիւն էին փնտռում, որպէսզի նրան սպանեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'բայց ներկայացող բազում սուտ վկաների մէջ չէին գտնում այն: Յետոյ առաջ եկան երկու սուտ վկաներ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'ասացին. «Սա ասում էր՝ Աստծու տաճարը կարող եմ քանդել եւ երեք օրում շինել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Եւ քահանայապետը վեր կենալով՝ նրան ասաց. «Պատասխան չե՞ս տալիս, քո մասին ի՞նչ ամբաստանութիւն են անում դրանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Եւ Յիսուս լուռ էր մնում: Քահանայապետը խօսեց եւ նրան ասաց. «Երդուեցնում եմ քեզ կենդանի Աստուծով, որ մեզ ասես, թէ դո՞ւ ես Քրիստոսը՝ Աստծու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Յիսուս նրան ասաց. «Դու ասացիր: Բայց ասում եմ ձեզ. այսուհետեւ մարդու Որդուն կը տեսնէք նստած ամենազօր Աստծու աջ կողմում եւ եկած երկնքի ամպերի վրայով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Այն ժամանակ քահանայապետը պատռեց իր զգեստներն ու ասաց. «Հայհոյեց, էլ ինչի՞ են պէտք մեզ վկաներ. ահա հիմա լսեցիք նրա հայհոյանքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Ի՞նչ է ձեր կամքը»: Նրանք պատասխանեցին ու ասացին՝ մահապարտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Այն ժամանակ թքեցին նրա երեսին, բռունցքով հարուածեցին նրան, եւ ոմանք էլ ապտակեցին նրան ու ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, '«Մարգարէացի՛ր մեզ, դո՛ւ, Քրիստո՛ս, ո՞վ է, որ քեզ հարուածեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Իսկ Պետրոսը նստած էր դուրսը՝ գաւթում. մի աղախին մօտեցաւ նրան ու ասաց. «Դո՛ւ էլ գալիլիացի Յիսուսի հետ էիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Նա ուրացաւ բոլորի առաջ ու ասաց. «Չգիտեմ՝ դու ինչ ես խօսում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Եւ երբ նա գաւթից դուրս ելաւ, նրան տեսաւ մի այլ կին եւ այնտեղ կանգնածներին ասաց. «Սա էլ Յիսուս Նազովրեցու հետ էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Եւ դարձեալ նա երդումով ուրացաւ, թէ՝ այդ մարդուն չեմ ճանաչում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Եւ մի քիչ յետոյ այնտեղ գտնուողները, մօտենալով, Պետրոսին ասացին. «Իրօք, դու էլ նրանցից ես, քանի որ քո խօսուածքն էլ քեզ յայտնի է անում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Այն ժամանակ նա սկսեց նզովք կարդալ ու երդուել, թէ՝ այդ մարդուն չեմ ճանաչում: Եւ իսկոյն աքաղաղը կանչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Եւ Պետրոսը յիշեց Յիսուսի խօսքը, որ նա ասել էր, թէ՝ դեռ աքաղաղը չկանչած՝ երեք անգամ ինձ պիտի ուրանաս: Եւ դուրս ելնելով՝ դառնապէս լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Երբ առաւօտ եղաւ, բոլոր քահանայապետները եւ ժողովրդի ծերերը խորհուրդ արեցին Յիսուսի դէմ՝ նրան սպանելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Նրան կապեցին, առան գնացին եւ յանձնեցին պոնտացի Պիղատոս կուսակալի ձեռքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Այն ժամանակ Յուդան, որ Յիսուսին մատնել էր, տեսնելով, որ Յիսուս դատապարտուեց, զղջաց, արծաթ դրամները վերադարձրեց քահանայապետներին եւ ժողովրդի ծերերին ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, '«Մեղանչեցի, որովհետեւ արդար արիւն մատնեցի»: Իսկ նրանք ասացին. «Մեր հոգը չէ, դո՛ւ գիտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Եւ արծաթ դրամները նետեց տաճարի մէջ եւ հեռացաւ ու գնաց ինքն իրեն կախեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Իսկ քահանայապետները արծաթ դրամները վերցնելով՝ ասացին. «Օրինաւոր չէ դրանք ընդունել տաճարի գանձանակի մէջ, քանի որ արեան գին են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Եւ խորհուրդ անելով՝ դրանով գնեցին բրուտի ագարակը՝ որպէս գերեզման օտարների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Այդ պատճառով այդ ագարակը կոչուել է Արեան ագարակ՝ մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Այն ժամանակ կատարուեց, ինչ ասուել էր Երեմիա մարգարէի բերանով. «Եւ առան երեսուն կտոր արծաթը՝ վաճառուածի գինը, որ նշանակուել էր իսրայէլացիներից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'եւ այն տուեցին բրուտի ագարակի համար, ինչպէս Տէրը ինձ հրամայել էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Եւ Յիսուս կանգնեց կուսակալի առաջ. կուսակալը հարցրեց նրան ու ասաց. «Դո՞ւ ես հրեաների թագաւորը»: Եւ Յիսուս ասաց. «Դու ես ասում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Իսկ երբ նա ամբաստանւում էր քահանայապետների ու ծերերի կողմից, ոչինչ չպատասխանեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Այն ժամանակ Պիղատոսը նրան ասաց. «Չե՞ս լսում, ինչքան դրանք քո դէմ են վկայում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Եւ նրան չպատասխանեց եւ ոչ մի բան, այնպէս որ կուսակալը շատ զարմացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Սակայն կուսակալը սովորութիւն ունէր տօնի առիթով ժողովրդի համար արձակել մի բանտարկեալ, ում նրանք կամենային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Այն ժամանակ ունէին մի նշանաւոր բանտարկեալ, որի անունը Յեսու Բարաբբա էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Երբ հաւաքուեցին, Պիղատոսը նրանց ասաց. «Այս երկուսից որի՞ն էք ուզում, որ ձեզ համար արձակեմ. Յեսու Բարաբբայի՞ն, թէ՞ Յիսուսին՝ Քրիստոս կոչուածին».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'քանի որ Պիղատոսը գիտէր, որ նախանձից մատնել էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Եւ մինչ նա ատեան էր նստում, իր կինը նրան լուր ուղարկեց ու ասաց. «Քո եւ այդ արդարի միջեւ ոչինչ չկայ, որովհետեւ այսօր երազումս նրա պատճառով գլխովս շատ բաներ անցան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Իսկ քահանայապետներն ու ծերերը համոզեցին ժողովրդին, որ Բարաբբային ուզեն եւ Յիսուսին կորստեան մատնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Կուսակալը պատասխան տուեց ու ասաց նրանց. «Այս երկուսից որի՞ն էք ուզում, որ ձեզ համար արձակեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Եւ նրանք ասացին՝ Բարաբբային: Պիղատոսը նրանց ասաց. «Իսկ ի՞նչ անեմ Յիսուսին՝ Քրիստոս կոչուածին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Ամէնքը ասացին՝ թող խաչուի: Եւ նա ասաց. «Ի՞նչ չար բան արեց»: Եւ նրանք առաւել եւս աղաղակում էին ու ասում՝ թող խաչուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Եւ Պիղատոսը տեսնելով, թէ ոչինչ չի օգնում, այլ է՛լ աւելի խռովութիւն է լինում, ջուր վերցնելով՝ լուաց ձեռքերը ժողովրդի առաջ ու ասաց. «Այդ արդարի արիւնից ես անմասն եմ. դո՛ւք գիտէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Ամբողջ ժողովուրդը պատասխանեց ու ասաց. «Դրա արիւնը՝ մեր վրայ եւ մեր որդիների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Այն ժամանակ Պիղատոսը նրանց համար արձակեց Բարաբբային եւ Յիսուսին գանակոծել տալով՝ տուեց նրանց ձեռքը, որ խաչուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Այն ժամանակ կուսակալի զինուորները Յիսուսին վերցրին տարան ապարանք եւ ամբողջ գունդը նրա գլխին հաւաքեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Մերկացրին նրան եւ նրա վրայ կարմիր վերնազգեստ գցեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Եւ փշերից պսակ պատրաստելով՝ դրեցին նրա գլխին եւ մի եղէգ՝ նրա աջ ձեռքին. նրա առաջ ծնկի գալով՝ ծաղրում էին ու ասում. «Ողջո՜յն, հրեաների՛ թագաւոր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Եւ թքելով նրա վրայ՝ եղէգն առնում էին ու խփում նրա գլխին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Եւ երբ նրան ծաղրուծանակի ենթարկեցին, նրա վրայից հանեցին քղամիդը ու նրան հագցրին իր զգեստը. եւ տարան նրան խաչը հանելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Եւ դուրս ելնելով՝ գտան կիւրենացի մի մարդ՝ Սիմոն անունով, ու նրան ստիպեցին, որ նա խաչը կրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Եւ հասնելով Գողգոթա կոչուած տեղը, որ նշանակում է կառափնատեղի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Յիսուսին լեղի խառնած գինի տուեցին խմելու, եւ երբ համտեսեց, չկամեցաւ խմել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Եւ նրան խաչը հանելով՝ բաժանեցին նրա զգեստները՝ վիճակ գցելով, որպէսզի կատարուի այն խօսքը, որ ասուեց մարգարէի կողմից. «Իմ զգեստները բաժանեցին իրենց մէջ եւ իմ պատմուճանի վրայ վիճակ էին գցում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Ու նստած՝ նրան պահպանում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Եւ նրա գլխի վերեւը դրեցին նրա յանցապարտութեան գիրը, թէ՝ սա՛ է Յիսուսը՝ հրեաների թագաւորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Միեւնոյն ժամանակ նրա հետ խաչը հանեցին երկու աւազակներ՝ մէկը նրա աջից, եւ միւսը՝ ձախից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Եւ մօտով անցնողները հայհոյում էին նրան, շարժում էին գլուխներն ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, '«Վա՛հ, դու որ քանդում էիր տաճարը եւ երեք օրից այն շինում, փրկի՛ր քեզ. եթէ Աստծու Որդի ես, իջի՛ր այդ խաչից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Նոյնպէս եւ քահանայապետները, օրէնսգէտներով ու ծերերով հանդերձ, ծաղրում էին նրան ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '«Ուրիշներին փրկեց, ինքն իրեն չի կարողանում փրկել. եթէ Իսրայէլի թագաւոր է, հիմա թող այդ խաչից իջնի. եւ դրան կը հաւատանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Եթէ դա յոյսը դրել էր Աստծու վրայ, թող նա այժմ դրան փրկի, եթէ ուզում է դրան. քանի որ ասաց, թէ՝ Աստծու Որդի եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Նրա հետ խաչուած աւազակներն էլ էին նոյն ձեւով նախատում նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Եւ կէսօրին ամբողջ երկրի վրայ խաւար եղաւ մինչեւ ժամը երեքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Ժամը երեքի մօտ Յիսուս բարձր ձայնով գոչեց ու ասաց. «Էլի՜, Էլի՜, լա՞մա սաբաքթանի», այսինքն՝ Աստուա՜ծ իմ, Աստուա՜ծ իմ, ինչո՞ւ թողեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Այնտեղ կանգնածներից ոմանք, երբ լսեցին, ասացին. «Դա Եղիային է կանչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Եւ նրանցից մէկը իսկոյն վազեց, քացախով թաթախուած սպունգ վերցրեց եւ մի եղէգի վրայ անցկացնելով՝ տուեց նրան, որ խմի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Իսկ ուրիշներ ասում էին. «Թո՛ղ, տեսնենք, թէ Եղիան կը գա՞յ, որ դրան փրկի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Եւ Յիսուս դարձեալ բարձր ձայնով աղաղակեց եւ հոգին աւանդեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Եւ ահա տաճարի վարագոյրը վերեւից մինչեւ ներքեւ երկուսի պատռուեց, եւ երկիրը շարժուեց, եւ ժայռեր ճեղքուեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'եւ գերեզմանները բացուեցին, եւ ննջեցեալ սրբերի բազում մարմիններ յարութիւն առան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'ու նրա յարութիւնից յետոյ գերեզմաններից ելնելով մտան սուրբ քաղաքը եւ շատերին երեւացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Իսկ հարիւրապետը եւ նրանք, որ իր հետ Յիսուսին պահպանում էին, երբ տեսան երկրաշարժը եւ պատահածները, սաստիկ վախեցան ու ասացին. «Արդարեւ, Աստծու Որդի էր սա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Այնտեղ շատ կանայք կային, որոնք կանգնած հեռուից նայում էին եւ որոնք Գալիլիայից եկել էին Յիսուսի յետեւից՝ նրան ծառայելու համար.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'նրանց մէջ էին Մարիամ Մագդաղենացին, Յակոբի եւ Յովսէի մայր Մարիամը եւ Զեբեդէոսի որդիների մայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Երբ երեկոյ եղաւ, եկաւ Յովսէփ անունով արիմաթիացի մի մեծահարուստ մարդ, որ Յիսուսին աշակերտել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Սա Պիղատոսի մօտ գնալով՝ Յիսուսի մարմինը խնդրեց: Այն ժամանակ Պիղատոսը հրամայեց, որ մարմինը տրուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Եւ Յովսէփը, մարմինն առնելով, պատեց մաքուր կտաւով');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'եւ դրեց նոր գերեզմանի մէջ, որ փորել էր տուել ժայռի մէջ: Եւ մի մեծ քար, որպէս կափարիչ, գերեզմանի դռան առաջ գլորեց ու գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Այնտեղ էր Մարիամ Մագդաղենացին եւ միւս Մարիամը. նրանք նստած էին գերեզմանի դիմաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Եւ հետեւեալ օրը, որ ուրբաթի յաջորդ օրն է, քահանայապետներն ու փարիսեցիները հաւաքուեցին Պիղատոսի մօտ ու ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, '«Տէ՛ր, յիշեցինք, թէ այն մոլորեցնողը, քանի կենդանի էր, ասում էր, թէ՝ երեք օրից յարութիւն պիտի առնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Արդ, հրամայի՛ր, որ մինչեւ երեք օր գերեզմանի ապահովութեանը հոգ տարուի. գուցէ աշակերտները գիշերով գան եւ գողանան նրան ու ժողովրդին ասեն, թէ՝ մեռելներից յարութիւն առաւ. եւ վերջին մոլորութիւնը աւելի վատ լինի, քան առաջինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Պիղատոսը նրանց ասաց. «Զինուորներ ունէք. գնացէ՛ք ապահովութեանը հոգ տարէք, ինչպէս որ գիտէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Եւ նրանք գնացին գերեզմանի ապահովութեանը հոգ տանելու եւ վէմը կնքեցին՝ զինուորներ նշանակելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Շաբաթ օրուայ երեկոյեան, երբ կիրակին լուսանում էր, Մարիամ Մագդաղենացին եւ միւս Մարիամը եկան գերեզմանը տեսնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Եւ ահա մեծ երկրաշարժ եղաւ, որովհետեւ Տիրոջ հրեշտակը երկնքից իջնելով՝ մօտեցաւ, դռնից վէմը մի կողմ գլորեց ու նստեց նրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Նրա տեսքը փայլակի նման էր, ու նրա զգեստը՝ սպիտակ, ինչպէս ձիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Նրա ահից պահապանները խռովուեցին եւ մեռելների պէս եղան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Հրեշտակը խօսեց ու կանանց ասաց. «Դուք մի՛ վախեցէք, գիտեմ, որ փնտռում էք Յիսուսին, որ խաչուեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'այստեղ չէ նա, քանի որ յարութիւն առաւ, ինչպէս ինքն ասել էր. եկէ՛ք, տեսէ՛ք այն տեղը, ուր պառկած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Եւ իսկոյն գնացէ՛ք, ասացէ՛ք նրա աշակերտներին, թէ յարութիւն առաւ. եւ ահա նա ձեզնից առաջ գնում է Գալիլիա. այնտեղ նրան կը տեսնէք: Ահա ասացի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Եւ իսկոյն, ահով եւ մեծ ուրախութեամբ, գերեզմանից դուրս ելնելով՝ վազեցին աշակերտներին պատմելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Եւ յանկարծ Յիսուս նրանց դիմացը ելաւ ու ասաց՝ ողջո՜յն ձեզ. եւ նրանք մօտենալով՝ նրա ոտքերին փարուեցին ու երկրպագեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Այն ժամանակ Յիսուս նրանց ասաց. «Մի՛ վախեցէք. գնացէ՛ք ասացէք իմ եղբայրներին, որ գնան Գալիլիա եւ այնտեղ ինձ տեսնեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Երբ նրանք գնացին, ահա զինուորներից ոմանք քաղաք եկան ու');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'քահանայապետներին պատմեցին այն բոլորը, ինչ որ պատահել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Եւ նրանք ծերերի հետ միասին հաւաքուելով՝ խորհուրդ արեցին, շատ դրամ տուեցին զինուորներին ու ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, '«Կ՚ասէք, թէ նրա աշակերտները, գիշերով գալով, գողացան նրան, մինչ մենք քնի մէջ էինք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Եւ եթէ այդ լուրը կուսակալին հասնի, մենք նրան կը գոհացնենք եւ ձեզ հոգսից կ՚ազատենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Եւ նրանք դրամն առնելով՝ արեցին այնպէս, ինչպէս որ իրենց սովորեցրել էին: Եւ այս զրոյցը տարածուած է հրեաների մէջ մինչեւ այսօր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Իսկ տասնմէկ աշակերտները գնացին Գալիլիա, այն լեռը, ուր Յիսուս իրենց հետ ժամադրուել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Երբ նրան տեսան, երկրպագեցին նրան, իսկ ոմանք երկմտեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Եւ Յիսուս մօտենալով՝ խօսեց նրանց հետ ու ասաց. «Ինձ է տրուած ամէն իշխանութիւն երկնքում եւ երկրի վրայ. ինչպէս Հայրը ինձ ուղարկեց, ես էլ ձեզ եմ ուղարկում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Գնացէ՛ք ուրեմն աշակերտ դարձրէ՛ք բոլոր ազգերին, նրանց մկրտեցէ՛ք Հօր եւ Որդու եւ Սուրբ Հոգու անունով: Ուսուցանեցէ՛ք նրանց պահել այն բոլորը, ինչ որ ձեզ պատուիրեցի: Եւ ահա ես ձեզ հետ եմ բոլոր օրերում՝ մինչեւ աշխարհի վախճանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Յիսուս Քրիստոսի՝ Աստծու Որդու Աւետարանի սկիզբը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Ինչպէս որ գրուած է մարգարէների գրքերում. «Ահաւասիկ ես ուղարկում եմ իմ պատգամաւորին քո առաջից, որ կը պատրաստի քո ճանապարհը քո առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Անապատում կանչողի ձայնն է. «Պատրաստեցէ՛ք Տիրոջ ճանապարհը եւ հարթեցէ՛ք նրա շաւիղները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Յովհաննէսը մկրտում էր անապատում եւ քարոզում ապաշխարութեան մկրտութիւն՝ մեղքերի թողութեան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Ամբողջ Հրէաստանը եւ բոլոր երուսաղէմացիները գնում էին նրա մօտ եւ մկրտւում նրանից Յորդանան գետում՝ խոստովանելով իրենց մեղքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Եւ Յովհաննէսը հագել էր ուղտի մազից զգեստ եւ մէջքին՝ կաշուէ գօտի. եւ նրա կերակուրն էր մորեխ եւ վայրի մեղր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Նա քարոզում էր եւ ասում. «Իմ յետեւից կը գայ ինձնից աւելի հզօրը, որի առաջ արժանի չեմ խոնարհուելու՝ նրա կօշիկների կապերն արձակելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ես ձեզ մկրտեցի ջրով, իսկ նա ձեզ կը մկրտի Սուրբ Հոգով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Այն օրերին Յիսուս եկաւ Գալիլիայի Նազարէթ քաղաքից եւ Յովհաննէսից մկրտուեց Յորդանանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Եւ նոյն ժամին, երբ ջրից դուրս էր գալիս, տեսաւ երկինքը՝ պատռուած, եւ Աստծու Հոգին, որպէս աղաւնի, որ իջնում էր իր վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Երկնքից մի ձայն եկաւ, որն ասում էր. «Դո՛ւ ես իմ սիրելի Որդին, որ ունես իմ ամբողջ բարեհաճութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Եւ անմիջապէս Հոգին նրան հանեց տարաւ դէպի անապատ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Եւ նա այնտեղ էր քառասուն օր՝ փորձուելով սատանայից: Եւ նա գազանների հետ էր, իսկ հրեշտակները ծառայում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Յովհաննէսի բանտարկուելուց յետոյ Յիսուս Գալիլիա եկաւ. քարոզում էր Աստծու Աւետարանը եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, '«Ժամանակը հասել է, եւ մօտեցել է Աստծու արքայութիւնը. ապաշխարեցէ՛ք եւ հաւատացէ՛ք Աւետարանին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Երբ նա անցնում էր Գալիլիայի ծովեզրով, տեսաւ Սիմոնին եւ նրա եղբայր Անդրէասին, որոնք ուռկանները ծովն էին գցել, որովհետեւ ձկնորսներ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Եւ Յիսուս նրանց ասաց. «Իմ յետեւի՛ց եկէք, եւ ես ձեզ կը դարձնեմ մարդկանց որսորդներ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Եւ իսկոյն ուռկանները թողնելով՝ գնացին նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Այստեղից մի քիչ առաջ գնալով՝ տեսաւ Զեբեդէոսի որդի Յակոբոսին եւ նրա եղբայր Յովհաննէսին. սրանց էլ տեսաւ իրենց նաւակի մէջ, մինչ ուռկաններն էին կարգի բերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Եւ կանչեց նրանց. եւ նրանք իսկոյն նաւակի մէջ թողնելով իրենց հօրը՝ Զեբեդէոսին, վարձկան ձկնորսների հետ միասին, գնացին նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Եւ մտան Կափառնայում: Եւ Յիսուս նոյն շաբաթ օրն իսկ ժողովարան մտնելով՝ ուսուցանում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Եւ նրանք զարմանում էին նրա քարոզութեան վրայ, որովհետեւ նրանց ուսուցանում էր իշխանութեամբ եւ ոչ՝ ինչպէս օրէնսգէտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Արդ, նրանց ժողովարանում մի մարդ կար՝ պիղծ ոգուց բռնուած, որն աղաղակեց եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '«Թո՛յլ տուր, ի՞նչ ես ուզում մեզնից, Յիսո՛ւս Նազովրեցի. մեզ կորստեան մատնելո՞ւ եկար. գիտենք քեզ, թէ ով ես դու, Աստծու Սուրբն ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Յիսուս սաստեց նրան ու ասաց. «Ձայնդ կտրի՛ր եւ դո՛ւրս ել դրանից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Եւ պիղծ ոգին սաստիկ ցնցեց դիւահարին եւ բարձրաձայն աղաղակելով՝ դուրս ելաւ նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Եւ ամէնքը զարմացան, այնպէս որ հարցնում էին իրար եւ ասում. «Այս ի՞նչ նոր վարդապետութիւն է, որ իշխանութեամբ պիղծ ոգիներին էլ է սաստում, եւ նրանք հնազանդւում են նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Եւ նրա համբաւը տարածուեց Գալիլիայի բոլոր կողմերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Եւ ժողովարանից դուրս ելնելով, անմիջապէս եկաւ Սիմոնի եւ Անդրէասի տունը՝ Յակոբոսի եւ Յովհաննէսի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Սիմոնի զոքանչը տաքութեան մէջ պառկած էր. իսկոյն ասացին նրա մասին Յիսուսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Եւ նա մօտենալով՝ նրա ձեռքը բռնեց եւ նրան ոտքի կանգնեցրեց. եւ տենդը նրան թողեց. եւ նա ծառայում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Երբ երեկոյ եղաւ, արեւի մայր մտնելու ժամանակ, նրա մօտ էին բերում բոլոր հիւանդներին եւ դիւահարներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Եւ ամբողջ քաղաքը հաւաքուել էր դռների առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Եւ նա տեսակ-տեսակ հիւանդութիւններից բազում հիւանդներ բժշկեց եւ բազում դեւեր հանեց. եւ թոյլ չէր տալիս դեւերին խօսել, որովհետեւ գիտէին նրան, որ Քրիստոսն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Եւ առաւօտեան մօտ, լոյսը բացուելուց առաջ, վեր կացաւ եւ ելաւ գնաց ամայի մի տեղ ու այնտեղ աղօթում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Նրա յետեւից նրան փնտռելու գնաց Սիմոնը եւ նրանք, որ նրա հետ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Եւ երբ գտան նրան, ասացին. «Ամէնքը փնտռում են քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Եւ նրանց ասաց. «Եկէ՛ք գնանք այլ մօտակայ գիւղաքաղաքներ եւս, որպէսզի այնտեղ էլ քարոզեմ, որովհետեւ հէնց դրա համար եմ եկել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Եւ ամբողջ Գալիլիայում նրանց ժողովարաններում քարոզում եւ դեւեր էր հանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Նրա մօտ եկաւ մի բորոտ. նա ծնկի եկած աղաչում էր եւ ասում. «Տէ՛ր, եթէ կամենաս, կարո՛ղ ես ինձ մաքրել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Իսկ Յիսուս գթալով՝ ձեռքը երկարեց, դիպաւ նրան եւ ասաց. «Կամենում եմ, մաքրուի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Եւ երբ նրան այս ասաց, բորոտութիւնը նրանից իսկոյն գնաց, եւ նա մաքրուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Եւ Յիսուս իսկոյն դուրս հանեց նրան եւ խստիւ պատուիրեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, '«Զգո՛յշ եղիր, ոչ ոքի բան չասես, այլ գնա՛, քեզ քահանային ցո՛յց տուր եւ մաքրուելուդ համար ընծայ տուր այն, ինչ հրամայել էր Մովսէսը՝ նրանց համար իբրեւ վկայութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Բայց նա դուրս գնալով՝ սկսեց եռանդուն կերպով քարոզել եւ լուրը տարածել այն աստիճան, որ Յիսուս չէր կարողանում այլեւս յայտնապէս քաղաք մտնել, այլ դուրսը, ամայի տեղերում էր մնում. եւ բոլոր կողմերից ժողովուրդը նրա մօտ էր գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Մի քանի օր յետոյ, երբ նա դարձեալ Կափառնայում մտաւ, լուր տարածուեց, թէ տանն է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'եւ շատեր հաւաքուեցին, այնպէս որ այլեւս տեղ չմնաց, ոչ իսկ դռան առջեւ: Եւ նրանց քարոզում էր Աստծու խօսքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Եւ եկան նրա մօտ՝ բերելով մի անդամալոյծի, որին տանում էին չորս հոգով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Եւ երբ ամբոխի պատճառով Յիսուսին չկարողացան մօտենալ, քանդեցին երդիկը այն տան, ուր գտնւում էր նա. եւ բացելով առաստաղը, իջեցրին այն մահիճը, որի մէջ էր անդամալոյծը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Եւ Յիսուս, տեսնելով նրանց հաւատը, անդամալոյծին ասաց. «Որդեա՛կ, քո մեղքերը քեզ ներուած են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Օրէնսգէտներից մի քանիսը, որ նստած էին այնտեղ, իրենց մտքում խորհում էին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '«Այս ի՞նչ է խօսում, սա հայհոյում է. ո՞վ կարող է մեղքերին թողութիւն տալ, եթէ ոչ՝ միայն Աստուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Եւ Յիսուս իր հոգում իմացաւ, որ այնպէս են խորհում իրենց մտքում. ուստի ասաց. «Ինչո՞ւ ձեր մտքում այդ էք խորհում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'ո՞րն է աւելի դիւրին. անդամալոյծին ասե՞լ՝ քո մեղքերը քեզ ներուած են, թէ՞ ասել՝ վե՛ր կաց, ա՛ռ մահիճդ եւ գնա՛ քո տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Բայց որպէսզի իմանաք, որ մարդու Որդին երկրի վրայ իշխանութիւն ունի ներելու մեղքերը, - ասաց նա անդամալոյծին, -');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'քե՛զ եմ ասում, վե՛ր կաց, ա՛ռ քո մահիճը եւ գնա՛ քո տունը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Եւ վեր կացաւ ու անմիջապէս վերցնելով մահիճը՝ բոլորի առաջ դուրս ելաւ, այնպէս որ ամէնքը զարմացան եւ փառք էին տալիս Աստծուն ու ասում. «Այսպիսի բան երբեք չենք տեսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Եւ նա դարձեալ ծովեզերք գնաց. եւ ամբողջ ժողովուրդը նրա մօտ էր գալիս, եւ նա ուսուցանում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Եւ մինչ նա անցնում էր, տեսաւ Ալփէոսի որդի Ղեւիին, որ մաքսատանը նստած գործի վրայ էր, ու նրան ասաց՝ արի՛ իմ յետեւից: Եւ Ղեւին վեր կացաւ գնաց նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Եւ երբ Յիսուս նրա տանը սեղան նստեց, բազում մաքսաւորներ եւ մեղաւորներ էլ Յիսուսի ու նրա աշակերտների հետ սեղան նստեցին, որովհետեւ շատերն էին նրա յետեւից գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Իսկ օրէնսգէտներն ու փարիսեցիները երբ տեսան, որ նա մաքսաւորների եւ մեղաւորների հետ է ուտում, նրա աշակերտներին ասացին. «Ինչո՞ւ էք մեղաւորների ու մաքսաւորների հետ ուտում եւ խմում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Երբ Յիսուս լսեց, նրանց ասաց. «Առողջներին բժիշկ պէտք չէ, այլ՝ հիւանդներին. եւ ես չեմ եկել արդարներին կանչելու, այլ՝ մեղաւորներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Յովհաննէսի աշակերտները եւ փարիսեցիները ծոմ էին պահում. եկան եւ նրան ասացին. «Ինչո՞ւ Յովհաննէսի աշակերտները եւ փարիսեցիները ծոմ են պահում, իսկ քո աշակերտները չեն պահում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Եւ Յիսուս նրանց ասաց. «Միթէ կարելի՞ է, որ հարսանքաւորները ծոմ պահեն, երբ փեսան նրանց հետ է. այնքան ժամանակ, որ փեսան իրենց հետ է, պէտք չէ, որ ծոմ պահեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Բայց կը գան օրեր, երբ փեսան նրանցից կը վերցուի, եւ ապա այն օրը նրանք էլ ծոմ կը պահեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Նոր, չօգտագործուած կտաւի կտորը ոչ ոք հնացած զգեստի վրայ չի կարկատի, ապա թէ ոչ նոր կտորը ամբողջութեամբ հին զգեստից կը պոկուի, եւ պատռուածքը աւելի վատ կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Եւ ոչ ոք հին տիկերի մէջ նոր գինի չի լցնի, ապա թէ ոչ նոր գինին կը պայթեցնի տիկերը, գինին կը թափուի, եւ տիկերը կը փչանան: Այլ նո՛ր գինին նո՛ր տիկերի մէջ պէտք լցուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Մի շաբաթ օրով նա անցնում էր ցորենի արտերի միջով: Եւ նրա աշակերտները գնալու ժամանակ սկսեցին հասկ պոկել եւ ուտել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Եւ փարիսեցիները նրան ասացին. «Տե՛ս, քո աշակերտները շաբաթ օրով ի՛նչ են անում, մի բան, որ օրինաւոր չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Յիսուս նրանց ասաց. «Դուք երբեւիցէ չէ՞ք կարդացել, թէ ինչ արեց Դաւիթը, երբ կարիք ունեցաւ եւ քաղց զգաց ինքը եւ նրանք, որ իր հետ էին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'թէ ինչպէս Աբիաթար քահանայապետի օրով մտաւ Աստծու տունը եւ կերաւ առաջաւորութեան հացը՝ տալով նաեւ նրանց, որ իր հետ էին. մի բան, որ, բացի քահանաներից, ուրիշների համար օրինաւոր չէր ուտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Եւ ասաց նրանց. «Շաբաթ օրը մարդո՛ւ համար է, եւ ոչ թէ մարդը՝ շաբաթ օրուայ համար.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'ապա ուրեմն՝ մարդու Որդին տէրն է եւ շաբաթ օրուայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Եւ նա նորից ժողովարան մտաւ. այնտեղ կար մի մարդ, որի ձեռքը չորացած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Եւ նրան ուշադրութեամբ դիտում էին՝ տեսնելու, թէ շաբաթ օրով նրան կը բժշկի՞, որպէսզի ամբաստանեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Եւ Յիսուս ասաց այն մարդուն, որի ձեռքը չորացած էր. «Վե՛ր կաց, մէջտե՛ղ արի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Ապա ասաց նրանց. «Շաբաթ օրով ի՞նչ բան է օրինաւոր անել. բարի գո՞րծ գործել, թէ՞ չարիք անել. մի հոգի՞ ազատել, թէ՞ կորստեան մատնել»: Եւ նրանք լռեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Եւ Յիսուս, ցասումով լցուած, նայելով նրանց եւ տրտմելով նրանց սրտի կուրութեան համար, ասաց մարդուն. «Երկարի՛ր ձեռքդ»: Եւ նա երկարեց, ու նրա ձեռքը առողջացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Փարիսեցիները հերովդէսականների հետ իսկոյն դուրս ելան եւ խորհուրդ էին անում նրա դէմ, թէ ինչպէս նրան կորստեան մատնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Իսկ Յիսուս իր աշակերտների հետ միասին գնաց ծովեզերք: Եւ Գալիլիայից բազում ժողովուրդ էր գնում նրա յետեւից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'նաեւ Հրէաստանից, Երուսաղէմից, Յորդանանի միւս կողմից, ինչպէս նաեւ Տիւրոսի եւ Սիդոնի շրջակայքից բազում ժողովուրդ, երբ լսում էր, թէ նա ինչքան բան է անում, գալիս էր նրա մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Եւ նա իր աշակերտներին ասաց, որ իր համար մի նաւակ պատրաստ լինի ամբոխի պատճառով, որպէսզի իրեն չնեղեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Քանի որ շատերին բժշկեց, ուստի ամէն տեսակ հիւանդութիւններ ունեցող մարդիկ գալիս էին, խռնւում նրա շուրջը, որպէսզի դիպչեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Եւ պիղծ ոգիները, երբ տեսնում էին նրան, ընկնում էին նրա առաջ, աղաղակում էին ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, '«Դու Աստծու Որդի ես»: Իսկ նա խստիւ պատուիրում էր նրանց, որ իր ինքնութիւնը չյայտնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Յիսուս լեռը բարձրացաւ եւ իր մօտ կանչեց նրանց, որոնց ինքը կամեցաւ. եւ նրանք գնացին նրա մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Նա նշանակեց Տասներկուսին, որ իր շուրջը լինեն, եւ նրանց քարոզելու ուղարկի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'ու նրանք իշխանութիւն ունենան ցաւեր բուժելու եւ դեւեր հանելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Եւ Սիմոնի անունը Պետրոս դրեց');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'եւ Զեբեդէոսի որդու՝ Յակոբոսի ու նրա եղբօր՝ Յովհաննէսի անունները դրեց Բաներեգէս, որ նշանակում է՝ Որոտման որդիներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Նաեւ՝ Անդրէասին եւ Փիլիպպոսին եւ Բարթողոմէոսին եւ մաքսաւոր Մատթէոսին եւ Թովմասին եւ Ալփէոսի որդի Յակոբոսին եւ Թադէոսին եւ Սիմոն Կանանացուն');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'եւ Յուդա Իսկարիովտացուն, որը եւ նրան մատնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Նրանք տուն վերադարձան. եւ ժողովուրդը նորից եկաւ նրանց հետ, այնպէս որ նրանք հաց ուտելու անգամ ժամանակ չունեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Եւ երբ Յիսուսի իւրայինները լսեցին, ելան եկան նրան բռնելու, որովհետեւ կարծում էին, թէ խելքը կորցրել է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Իսկ Երուսաղէմից իջած օրէնսգէտներն ասում էին, թէ դրա մէջ Բէեղզեբուղ կայ, եւ դեւերի իշխանի ձեռքով է հանում դեւերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Եւ նա իր մօտ կանչելով նրանց՝ առակներով էր խօսում նրանց հետ. «Ինչպէ՞ս կարող է սատանան սատանային դուրս հանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Եւ արդ, եթէ մի թագաւորութիւն ինքն իր մէջ բաժանուի, այդ թագաւորութիւնը չի կարող կանգուն մնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Եւ եթէ մի տուն ինքն իր մէջ բաժանուի, այդ տունը չի կարող կանգուն մնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Եւ եթէ սատանան ինքն իր դէմ դուրս գայ եւ բաժանուած լինի, չի կարող կանգուն մնալ, այլ նրա վախճանը հասել է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Ոչ ոք չի կարող հզօրի տունը մտնելով՝ նրա ունեցածը կողոպտել, եթէ նախ չկապոտի հզօրին. եւ ապա միայն կը կողոպտի նրա տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Ճշմարիտ եմ ասում ձեզ, որ մարդկանց որդիներին, որքան էլ հայհոյեն, ամէն մեղք եւ հայհոյանք կը ներուի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'բայց ով որ հայհոյի Սուրբ Հոգուն, յաւիտեանս թողութիւն չի ունենայ, այլ նա յանցապարտ պիտի մնայ յաւիտենական մեղքով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Այսպէս խօսեց, որովհետեւ ասում էին՝ նրա մէջ պիղծ դեւ կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Եկան նրա եղբայրներն ու մայրը եւ դրսում կանգնած՝ մարդ ուղարկեցին ու կանչեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Եւ այնտեղ ժողովուրդը նստել էր նրա շուրջը: Եւ երբ ասացին նրան՝ ահա՛ւասիկ քո մայրն ու քո եղբայրները դրսում են եւ քեզ են ուզում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'նրանց պատասխանեց եւ ասաց. «Ո՞վ է իմ մայրը կամ՝ իմ եղբայրները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Ապա նայեց իր շուրջը, իր աշակերտներին, որոնք նստած էին, եւ ասաց. «Ահա՛ւասիկ իմ մայրը եւ իմ եղբայրները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'որովհետեւ, ով Աստծու կամքն է կատարում, նա՛ է իմ եղբայրը եւ քոյրը եւ մայրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Նորից նա սկսեց ուսուցանել ծովեզերքի մօտ, եւ նրա շուրջը խռնուեց բազում ժողովուրդ, այնպէս որ նա մտաւ ու նստեց մի նաւակի մէջ, ծովի վրայ, մինչ ամբողջ ժողովուրդը ծովեզերքին շուրջանակի բռնել էր ցամաքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Եւ նա առակներով նրանց շատ բան էր ուսուցանում եւ նրանց ասում իր քարոզութեան մէջ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '«Լսեցէ՛ք, ահաւասիկ մի սերմանող սերմանելու ելաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Եւ պատահեց, որ սերմանելու ժամանակ սերմի մի մասն ընկաւ ճանապարհի եզերքը, եւ թռչունները եկան ու կերան այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Ուրիշ մի մաս ընկաւ ապառաժի վրայ, որտեղ շատ հող չկար. եւ շուտով բուսաւ, որովհետեւ հողը խորը չէր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'բայց երբ արեւը ծագեց, խանձուեց. եւ քանի որ արմատներ չունէր, չորացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Մի ուրիշ մաս ընկաւ փշերի մէջ. փշերը բարձրացան եւ խեղդեցին այն, եւ պտուղ չտուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Իսկ մի ուրիշ մաս էլ ընկաւ լաւ հողի վրայ, բուսնելով աճեց ու պտուղ տուեց. մէկի դիմաց՝ երեսուն, մէկի դիմաց՝ վաթսուն եւ մէկի դիմաց՝ հարիւր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Եւ ասում էր. «Ով որ լսելու ականջ ունի, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Եւ երբ առանձին մնաց, նրա շուրջը եղողները, աշակերտների հետ միասին, հարցրին նրան այս առակի մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Եւ նրանց ասաց. «Ձեզ է տրուած իմանալ Աստծու արքայութեան խորհուրդները, բայց նրանց համար, որ ձեզնից դուրս են, ամէն ինչ առակներով կը լինի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'որպէսզի նայելով հանդերձ չտեսնեն եւ լսելով հանդերձ չիմանան, որ մի գուցէ երբեւէ դարձի գան, եւ իրենց ներուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Եւ ասաց նրանց. «Այս առակը չէ՞ք հասկանում, ապա ինչպէ՞ս պիտի հասկանաք բոլոր առակները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Նա, որ սերմանում է, Աստծու խօսքն է սերմանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Ճանապարհի եզերքին սերմանուածները այն մարդիկ են, որոնք լսում են խօսքը, եւ սատանան գալիս է եւ դուրս է հանում նրանց սրտերի մէջ սերմանուած խօսքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Ապառաժի վրայ սերմանուածները այն մարդիկ են, որ, երբ լսում են խօսքը, իսկոյն ուրախութեամբ ընդունում են այն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'եւ որովհետեւ իրենց մէջ արմատներ չունեն, այլ մի որոշ ժամանակի համար են, երբ խօսքի պատճառով նեղութիւն կամ հալածանք է վրայ հասնում, իսկոյն գայթակղւում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Իսկ նրանք, որ սերմանուեցին փշերի մէջ, այն մարդիկ են, որ լսում են խօսքը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'սակայն այս աշխարհի հոգսերը եւ հարստութեան պատրանքները ներխուժում եւ խեղդում են խօսքը, եւ այն անպտուղ է լինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Եւ լաւ հողի մէջ սերմանուածները այն մարդիկ են, որ լսում են խօսքը եւ ընդունում ու պտուղ են տալիս. մէկի դիմաց՝ երեսուն, մէկի դիմաց՝ վաթսուն եւ մէկի դիմաց՝ հարիւր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Եւ նրանց ասաց. «Միթէ ճրագը բերւում է, որ կաթսայի կամ մահճի տա՞կ դրուի: Չէ՞ որ աշտանակի վրայ է դրւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Արդ, ծածուկ բան չկայ, որ չյայտնուի, եւ գաղտնի բան չի եղել, որ ի յայտ չգայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Թէ մէկը լսելու ականջ ունի, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Եւ նրանց ասաց. «Զգո՛յշ եղէք, թէ ինչ էք լսում, եւ ինչ որ լսում էք, աւելին կը տրուի ձեզ. ինչ չափով, որ չափում էք, նոյնով Աստուած պիտի չափի ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Ով որ ունի, նրան պիտի տրուի. իսկ ով որ չունի, նրանից պիտի վերցուի, ինչ էլ որ նա ունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Եւ ասում էր. «Այսպէ՛ս է Աստծու արքայութիւնը. որպէս թէ մի մարդ հողի մէջ սերմեր ցանի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'եւ նա ննջի թէ վեր կենայ, գիշեր եւ ցերեկ, սերմերը կը բուսնեն ու կ՚աճեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'եւ նա չի իմանայ, թէ հողը ինքն իրենից բերք է տալիս. նախ՝ խոտը, ապա՝ հասկը եւ ապա՝ ատոք ցորենը հասկի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Սակայն երբ սերմը իր պտուղը տայ, իսկոյն մանգաղ է ուղարկում, որովհետեւ հնձի ժամանակը հասել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Եւ ասում էր. «Ինչի՞ նմանեցնենք Աստծու արքայութիւնը կամ ի՞նչ օրինակով ներկայացնենք այն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'նման է մանանեխի հատիկին, որը, երբ սերմանւում է հողի մէջ, աւելի մանր է լինում, քան երկրի վրայ եղող բոլոր սերմերը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'իսկ երբ սերմանուի, բուսնում եւ լինում է աւելի մեծ, քան ամէն տունկ, եւ արձակում է մեծ ճիւղեր, այնքան, որ երկնքի թռչունները նրա հովանու տակ կարող են բնակուել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Եւ այնպիսի առակներով էր նրանց ասում խօսքը, որ կարողանային հասկանալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Եւ առանց առակի նրանց հետ ոչինչ չէր խօսում, բայց իր աշակերտների համար առանձին ամէն ինչ մեկնում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Այդ նոյն օրը, երեկոյեան դէմ, աշակերտներին ասաց. «Եկէ՛ք անցնենք ծովի միւս կողմը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Թողնելով ժողովրդին՝ նրան իրենց հետ տարան նաւակով, ինչպէս նաեւ՝ միւս նաւակները, որ նրա հետ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Եւ մեծ հողմամրրիկ բարձրացաւ ու ալիքները նաւակի մէջ էր թափում, այնպէս որ նաւակը գրեթէ լցւում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Իսկ ինքը նաւախելի կողմը բարձի վրայ ննջում էր. նրան արթնացրին եւ ասացին. «Վարդապե՛տ, քեզ համար բնաւ հոգ չէ՞, որ ահա մենք կորչում ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Եւ նա, արթնանալով, սաստեց հողմին եւ ասաց ծովին. «Դադարի՛ր, լռի՛ր»: Եւ հողմը դադարեց, ու մեծ խաղաղութիւն եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Եւ նրանց ասաց. «Ինչո՞ւ այդպէս վախկոտ էք. դեռեւս հաւատ չունէ՞ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Եւ նրանք սաստիկ վախեցան եւ միմեանց ասում էին. «Ո՞վ է արդեօք սա, որ թէ՛ հողմը, թէ՛ ծովը հնազանդւում են սրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Եւ Յիսուս եկաւ ծովի հանդիպակաց կողմը, գերգեսացիների երկիրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Եւ երբ նա նաւակից դուրս ելաւ, գերեզմաններից նրա դէմն ելաւ մի մարդ, որին բռնել էր մի պիղծ ոգի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'եւ որի բնակութեան տեղն իսկ գերեզմանների մէջ էր: Եւ ոչ ոք նրան շղթաներով անգամ չէր կարող կապել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'որովհետեւ շատ անգամ ոտնակապերով եւ շղթաներով կապուած էր, բայց շղթաները փշրել էր ու ոտնակապերը՝ ջարդել: Ոչ ոք նրան չէր կարողանում զսպել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'որովհետեւ միշտ, գիշեր ու ցերեկ, գերեզմաններում եւ լեռներում, աղաղակում էր եւ ինքն իրեն քարերով ծեծում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Երբ նա Յիսուսին հեռուից տեսաւ, առաջ վազեց ու երկրպագեց նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'բարձրաձայն աղաղակեց եւ ասաց. «Ի՞նչ ես ուզում ինձնից, Յիսո՛ւս, բարձրեալ Աստծո՛ւ Որդի: Երդուեցնում եմ քեզ Աստուծով, ինձ մի՛ տանջիր».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'քանի որ Յիսուս նրան ասում էր. «Պի՛ղծ ոգի, դո՛ւրս ելիր այդ մարդուց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Եւ նրան հարցրեց. «Անունդ ի՞նչ է»: Եւ նա ասաց նրան. «Իմ անունը Լեգէոն է, քանի որ բազում ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Իսկ պիղծ ոգիները սաստիկ աղաչում էին նրան, որ այդ շրջանից դուրս չուղարկի իրենց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Եւ այնտեղ, լերան լանջին, խոզերի մի մեծ երամակ կար, որ արածում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Բոլոր դեւերը աղաչեցին նրան եւ ասացին. «Մեզ խոզերի մէջ ուղարկիր, որ մտնենք նրանց մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Եւ նա հրամայեց նրանց: Երբ պիղծ ոգիները դուրս ելան, մտան խոզերի մէջ, եւ երամակը, թուով մօտ երկու հազար, դարաւանդից դիմեց դէպի ծովը. եւ խեղդուեցին ծովում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Խոզարածները փախան եւ քաղաքում ու ագարակներում պատմեցին. եւ մարդիկ դուրս ելան տեսնելու, թէ ի՛նչ էր կատարուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Եկան Յիսուսի մօտ եւ տեսան դիւահարին, որ նստել էր՝ հագնուած եւ զգաստացած, նրան, որ լեգէոն ունէր. եւ զարհուրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Եւ ովքեր որ տեսել էին, պատմեցին նրանց, թէ ինչ պատահեց այսահարին եւ ինչ՝ խոզերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Եւ սկսեցին աղաչել Յիսուսին, որ հեռանայ իրենց սահմաններից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Եւ երբ նաւակ մտաւ, դիւահարը նրան աղաչում էր, որ նրա հետ լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Բայց Յիսուս նրան թոյլ չտուեց, այլ ասաց. «Գնա՛ քո տունը հարազատներիդ մօտ եւ պատմի՛ր նրանց այն ամէնը, ինչ Տէրը քեզ արեց եւ թէ ինչպէս խղճաց քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Եւ նա գնաց ու սկսեց տարածել Դեկապոլսում, ինչ որ Յիսուս իր համար արել էր: Եւ ամէնքը զարմանում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Եւ երբ Յիսուս նաւակով նորից ծովի միւս կողմն անցաւ, նրա մօտ հաւաքուեց բազում ժողովուրդ: Եւ ինքը ծովեզրին էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Ահա եկաւ ժողովրդապետներից մէկը, որի անունը Յայրոս էր. եւ երբ տեսաւ նրան, նրա ոտքերն ընկաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'սաստիկ աղաչում էր նրան ու ասում, որ իր դուստրը մահամերձ է, եւ որ նա գայ ու նրա վրայ իր ձեռքը դնի, որպէսզի առողջանայ եւ ապրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Եւ Յիսուս գնաց նրա հետ. նրա յետեւից գնում էր նաեւ բազում ժողովուրդ եւ նեղում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Եւ մի կին կար, որ տասներկու տարուց ի վեր արիւնահոսութիւն ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Նա շատ էր տառապել բազմաթիւ բժիշկների ձեռքից եւ իր ամբողջ ունեցուածքը ծախսել էր, բայց որեւէ օգուտ չէր գտել, այլ է՛լ աւելի վատացել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Նա երբ լսեց Յիսուսի մասին, եկաւ ամբոխի մէջ նրա յետեւից եւ ձեռքը դիպցրեց նրա զգեստին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'որովհետեւ մտքում խորհում էր. «Եթէ միայն դիպչեմ նրա զգեստներին, կը բժշկուեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Եւ իսկոյն նրա արեան աղբիւրը չորացաւ, եւ իր մարմնի մէջ զգաց, որ տանջանքներից բժշկուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Եւ Յիսուս իսկոյն ինքն իր մէջ իմանալով իրենից դուրս ելած զօրութիւնը, դարձաւ դէպի ամբոխը եւ ասաց. «Ո՞վ դիպաւ իմ զգեստներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Եւ աշակերտները նրան ասացին. «Տեսնում ես, որ ամբոխը նեղում է քեզ, եւ ասում ես, թէ՝ ո՞վ դիպաւ իմ զգեստներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Եւ նա շուրջն էր նայում՝ տեսնելու, թէ ո՛վ այդ արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Եւ այդ կինը, զարհուրած ու դողալով նրա համար, որ գաղտնի էր արել, - որովհետեւ գիտէր, թէ ինչ կատարուեց իր հետ, - եկաւ ընկաւ նրա առաջ եւ ամէն ինչ ստուգութեամբ ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Եւ Յիսուս նրան ասաց. «Դո՛ւստր, քո հաւատը քեզ փրկեց, գնա՛ խաղաղութեամբ եւ քո տանջանքներից բժշկուած եղիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Մինչ Յիսուս այս բանն էր խօսում, ժողովրդապետի տնից ոմանք եկան եւ ասացին. «Քո դուստրը մեռաւ, էլ ի՞նչ ես նեղութիւն տալիս Վարդապետին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Իսկ Յիսուս, երբ լսեց ասուած խօսքը, ժողովրդապետին ասաց. «Մի՛ վախեցիր, այլ միայն հաւատա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Եւ ոչ ոքի թոյլ չտուեց իր հետ գնալ, այլ միայն՝ Պետրոսին, Յակոբոսին եւ նրա եղբօրը՝ Յովհաննէսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Յիսուս ժողովրդապետի տունը եկաւ եւ տեսաւ մի մեծ ամբոխ, լացուկոծ անողներ եւ աղմուկ-աղաղակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Ապա ներս մտնելով՝ նրանց ասաց. «Ինչո՞ւ էք խռովուած ու լաց էք լինում. մանուկը մեռած չէ, այլ ննջում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Սակայն նրանք ծաղրում էին նրան: Իսկ նա, ամենքին դուրս հանելով, վերցրեց իր հետ մանկան հօրն ու մօրը եւ նրանց, որ իր հետ էին, եւ մտաւ այնտեղ, ուր պառկած էր մանուկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Եւ բռնելով մանկան ձեռքից՝ ասաց նրան՝ Տալի՛թա, կո՛ւմի, որ նշանակում է՝ աղջի՛կ, դո՛ւ, քե՛զ եմ ասում, վե՛ր կաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Եւ աղջիկը իսկոյն վեր կացաւ ու քայլում էր, քանի որ մօտ տասներկու տարեկան էր: Եւ ամէնքը մեծապէս զարմացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Իսկ նա նրանց խստիւ պատուիրեց, որ ոչ ոք այդ բանը չիմանայ. ու ասաց, որ նրան ուտելու բան տան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Եւ այնտեղից ելաւ եկաւ իր գաւառը. եւ իր աշակերտները գնում էին նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Երբ շաբաթ օր եղաւ, սկսեց ժողովարանում ուսուցանել. եւ շատերը, երբ լսում էին նրան, զարմանում էին նրա վարդապետութեան վրայ եւ ասում. «Այս բաները որտեղի՞ց են սրան, կամ ի՞նչ է այս իմաստութիւնը, որ տրուած է սրան, որ սրա ձեռքով այսպիսի զօրաւոր գործեր կատարուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Սա հիւսնի տղան եւ Մարիամի որդին չէ՞ միթէ, Յակոբոսի եւ Յովսէի ու Յուդայի եւ Սիմոնի եղբայրը. եւ սրա քոյրերը այստեղ մեզ մօտ չե՞ն»: Եւ նրանով գայթակղւում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Եւ Յիսուս նրանց ասաց. «Մարգարէն յարգուած անձ է, բայց ոչ իր գաւառում, իր ազգատոհմի եւ իր տան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Եւ չէր կարողանում այնտեղ որեւէ զօրաւոր գործ կատարել, այլ քիչ թուով հիւանդների վրայ ձեռք դնելով՝ նրանց բժշկում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Եւ նա զարմանում էր նրանց անհաւատութեան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Եւ շրջում էր շրջակայ գիւղերում եւ ուսուցանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Նա իր մօտ կանչեց Տասներկուսին եւ սկսեց ուղարկել նրանց երկու-երկու ու պիղծ ոգիների վրայ նրանց իշխանութիւն տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Նրանց պատուիրեց, որ ճանապարհի համար գաւազանից բացի այլ բան չվերցնեն. ո՛չ պարկ, ո՛չ հաց, ո՛չ դրամ գօտիների մէջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'այլ հագնեն հողաթափներ. եւ ասաց. «Աւելորդ պարեգօտ մի՛ վերցրէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Եւ ասում էր նրանց. «Ինչ տուն որ մտնէք, այնտեղ օթեւանեցէ՛ք, մինչեւ որ այնտեղից ելնէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Եւ ուր որ ձեզ չեն ընդունի ու ձեզ չեն լսի, երբ որ այնտեղից ելնէք, ձեր ոտքերի փոշին թա՛փ տուէք՝ իբրեւ նրանց դէմ վկայութիւն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Եւ նրանք ելան ու քարոզում էին, որպէսզի մարդիկ ապաշխարեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Եւ բազում դեւեր էին հանում, բազում հիւանդների օծում էին իւղով ու նրանց բժշկում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Եւ Հերովդէս արքան լսեց այս բաները, որովհետեւ Յիսուսի անունը յայտնի էր դարձել. եւ նա ասաց. «Յովհաննէս Մկրտիչը յարութիւն է առել մեռելներից, եւ դրա համար զօրութիւններ են գործւում նրա միջոցով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Ուրիշներ ասում էին, թէ՝ Եղիան է. իսկ միւսները, թէ՝ մարգարէ է կամ թէ՝ մարգարէների նման մէկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Երբ Հերովդէսը այս լսեց, ասաց. «Յովհաննէսը, որի գլուխը կտրեցի ես, սա նա՛ է. մեռելներից յարութիւն է առել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Արդարեւ, ինքը՝ Հերովդէսն էր մարդ ուղարկել, ձերբակալել էր Յովհաննէսին, կապել նրան ու բանտարկել՝ իր եղբօր՝ Փիլիպպոսի կնոջ՝ Հերովդիայի պատճառով, քանի որ Հերովդէսը նրան իրեն կին էր դարձրել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'եւ քանի որ Յովհաննէսը Հերովդէսին ասում էր. «Քո եղբօր կնոջը քեզ կին առնելը օրինաւոր չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Եւ Հերովդիան ոխ էր պահել նրա դէմ ու ուզում էր նրան սպանել տալ, բայց չէր կարողանում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'որովհետեւ Հերովդէսը վախենում էր Յովհաննէսից, քանի որ նրան գիտէր որպէս արդար եւ սուրբ մարդու, եւ նրան հովանաւորում էր ու նրան անսալով՝ շատ բաներ էր անում եւ քաղցրութեամբ լսում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Սակայն մի յարմար օր եկաւ, երբ Հերովդէսը իր ծննդեան տարեդարձի ընթրիքն էր տալիս իր նախարարներին, Գալիլիայի մեծամեծներին եւ հազարապետներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Եւ երբ Հերովդիայի դուստրը ներս մտաւ եւ սկսեց պարել, դուր եկաւ Հերովդէսին եւ սեղանակիցներին. թագաւորը աղջկան ասաց. «Ուզի՛ր ինձնից, ինչ որ կամենում ես, եւ քեզ կը տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Եւ երդուեց նրան շատ անգամ, թէ՝ դու ինձնից ինչ էլ որ ուզես, կը տամ քեզ, մինչեւ իսկ իմ թագաւորութեան կէսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Աղջիկը դուրս գնալով իր մօրն ասաց՝ ի՞նչ ուզեմ: Եւ սա ասաց՝ Յովհաննէս Մկրտչի գլուխը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Եւ աղջիկը շտապով վերստին մտնելով թագաւորի մօտ՝ ասաց. «Ուզում եմ, որ հիմա ինձ տաս սկուտեղի վրայ Յովհաննէս Մկրտչի գլուխը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Եւ թագաւորը սաստիկ տրտմեց, բայց իր երդումների եւ հրաւիրեալների պատճառով չուզեց նրան մերժել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Եւ թագաւորը իսկոյն դահիճ ուղարկեց ու հրամայեց բերել Յովհաննէսի գլուխը: Եւ սա գնաց գլխատեց նրան բանտում');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'ու նրա գլուխը սկուտեղով բերեց եւ տուեց աղջկան, եւ աղջիկը տարաւ տուեց իր մօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Երբ Յովհաննէսի աշակերտները լսեցին, եկան վերցրին մարմինը եւ դրեցին գերեզմանի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Առաքեալները հաւաքուեցին Յիսուսի մօտ ու նրան պատմեցին այն ամէնը, ինչ որ արել էին եւ ուսուցանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Եւ Յիսուս նրանց ասաց. «Եկէ՛ք դուք առանձին մի ամայի տեղ ու մի քիչ հանգստացէ՛ք». որովհետեւ եկող-գնացողները շատ էին. եւ հաց ուտելու անգամ ժամանակ չունէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Եւ նաւակով գնացին մի ամայի տեղ՝ առանձին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Սակայն մարդիկ տեսան նրանց, որ գնում էին, եւ շատերը ճանաչեցին նրանց ու բոլոր քաղաքներից հետիոտն, խուռներամ այնտեղ վազեցին եւ մօտեցան նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Եւ նա նաւակից դուրս ելնելով՝ մեծ ամբոխ տեսաւ ու գթաց նրանց, որովհետեւ նման էին ոչխարների, որոնք հովիւ չունեն. եւ սկսեց նրանց ուսուցանել շատ բաներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Երբ շատ ժամեր անցան, աշակերտները, մօտենալով, ասացին. «Սա ամայի տեղ է, մինչ օրը դեռ չի վերջացել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'արձակի՛ր այս ժողովրդին, որպէսզի գնան շրջակայքի ագարակներում եւ գիւղերում իրենց համար ուտելիք գնեն, որովհետեւ այստեղ ուտելու բան չունեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Նա պատասխանեց նրանց եւ ասաց. «Դո՛ւք նրանց ուտելիք տուէք»: Ասացին նրան. «Գնանք գնե՞նք երկու հարիւր դահեկանի հաց եւ նրանց տանք ուտելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Ասաց նրանց. «Քանի՞ նկանակ ունէք, գնացէք տեսէ՛ք»: Երբ իմացան, նրան ասացին. «Հինգ նկանակ եւ երկու ձուկ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Եւ նա հրամայեց խումբ-խումբ նստեցնել նրանց դալար խոտի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Եւ դաս-դաս նստեցին, տեղ-տեղ՝ հարիւր, տեղ-տեղ՝ յիսուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Եւ նա վերցնելով հինգ նկանակը եւ երկու ձկները՝ նայեց դէպի երկինք, օրհնեց, մանրեց նկանակները եւ տուեց աշակերտներին, որպէսզի դնեն նրանց առաջ: Եւ երկու ձկներն էլ բաժանեց բոլորին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Կերան եւ յագեցան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'եւ տասներկու սակառ լիքը կտորտանքները վերցրին, ինչպէս նաեւ՝ ձկներից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Եւ նրանք որ կերան, մօտ հինգ հազար հոգի էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Իսկոյն եւեթ Յիսուս շտապեցրեց աշակերտներին, որ նաւակ մտնեն եւ իրենից առաջ գնան հանդիպակաց կողմը՝ դէպի Բեթսայիդա, մինչեւ ինքը ժողովրդին արձակէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Եւ բաժանուելով նրանցից՝ լեռ բարձրացաւ աղօթք անելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Երբ երեկոյ եղաւ, նաւակը ծովի մէջտեղում էր, իսկ ինքը՝ ցամաքի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Եւ տեսաւ նրանց, որ հողմակոծ էին լինում թիավարելիս, որովհետեւ քամին նրանց հակառակ կողմից էր. գիշերուայ ուշ ժամին նա գալիս էր նրանց մօտ՝ ծովի վրայ քայլելով, եւ ուզում էր նրանցից առաջ անցնել գնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Երբ նրանք տեսան, որ քայլում է ծովի վրայ, կարծեցին, թէ մի ուրուական է, եւ աղաղակ բարձրացրին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'որովհետեւ ամէնքը տեսան նրան եւ խռովուեցին: Եւ նա իսկոյն խօսեց նրանց հետ ու ասաց. «Քաջալերուեցէ՛ք, ե՛ս եմ, մի՛ վախեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Եւ նա նաւակ բարձրացաւ նրանց մօտ, եւ քամին դադարեց: Եւ նրանք առաւել եւս ապշել էին իրենց մտքում ու սաստիկ զարմանում էին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'քանի որ մտքները բթացած լինելով՝ չէին հասկացել նաեւ այն, ինչ վերաբերում էր հացի բազմացմանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Երբ դիմացի կողմն անցան, Գեննեսարէթի ցամաքը ելան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Եւ երբ նաւակից դուրս ելան, տեղի մարդիկ իսկոյն եւեթ նրան ճանաչեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Եւ ամբողջ գաւառում այս ու այն կողմ վազելով՝ սկսեցին մահիճներով հիւանդներ բերել այնտեղ, ուր լսում էին, թէ նա գտնւում է: Եւ ուր որ մտնում էր՝ գիւղեր, քաղաքներ թէ ագարակներ, հրապարակներում դնում էին ախտերով տառապողներին եւ աղաչում նրան, որ գոնէ իր զգեստի քղանցքներին դիպչեն: Եւ ովքեր մի անգամ դիպան, բժշկուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Եւ նրա մօտ հաւաքուեցին փարիսեցիներն ու օրէնսգէտներից ոմանք, որոնք եկել էին Երուսաղէմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Նրանք տեսնելով, որ նրա աշակերտներից ոմանք անմաքուր ձեռքերով, այսինքն՝ անլուայ հաց էին ուտում, բամբասեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'որովհետեւ փարիսեցիները եւ բոլոր հրեաները, եթէ ձեռքները մի լաւ չլուանան, հաց չեն ուտում, քանի որ հների աւանդութիւնը պահում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Նաեւ՝ շուկայից տուն մտնելով՝ եթէ նախ չլուացուեն, չեն ուտում: Եւ ուրիշ շատ բաներ էլ կան, որ աւանդաբար պահում են. ինչպէս՝ բաժակների, սափորների, պղնձէ ամանների ու մահիճների լուացումներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Ահա ինչու փարիսեցիները եւ օրէնսգէտները հարց տուեցին նրան. «Ինչո՞ւ քո աշակերտները նախնիների աւանդութեան համաձայն չեն շարժւում, այլ անմաքուր ձեռքերով են հաց ուտում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Նա պատասխանեց եւ ասաց նրանց. «Եսային լաւ մարգարէացաւ ձեր՝ կեղծաւորներիդ մասին՝ ասելով. «Այս ժողովուրդը ինձ շրթներո՛վ է մեծարում, բայց նրանց սրտերը ինձնից հեռու են.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'ի զուր են ինձ պաշտում. ուսուցանում են վարդապետութիւններ, որ մարդկանց պատուիրածներն են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Աստծու պատուիրանը թողած՝ մարդկանց աւանդութիւնն էք պահում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Ապա աւելացրեց. «Աստծու պատուիրանը լաւ էք անարգում, որպէսզի ձե՛ր աւանդութիւնը հաստատէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'որովհետեւ Մովսէսն ասում է. «Պատուի՛ր քո հօրն ու մօրը. եւ ով որ չարախօսի իր հօր կամ մօր մասին, մահուամբ թող պատժուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Իսկ դուք ասում էք. «Եթէ մէկը հօրը կամ մօրն ասի. ՚Ինչ ինձնից պիտի օգտուես, Կորբան է՚, (այսինքն՝ Աստծուն տալու ընծայ),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'դրանով իսկ այլեւս թոյլ չէք տալիս, որ նա իր հօր կամ մօր համար որեւէ բան անի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'եւ այդպէս անարգում էք Աստծու խօսքը նոյն աւանդութեամբ, որ դուք փոխանցում էք միմեանց: Եւ սրա նման ուրիշ շատ բաներ էք անում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Եւ նա ամբողջ ժողովրդին իր մօտ կանչելով՝ ասաց նրանց. «Ամէնքդ ինձ լսեցէ՛ք եւ իմացէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'չկայ որեւէ բան, որ մարդու մէջ դրսից մտնելով կարողանայ նրան պղծել. այլ այն, ինչ ելնում է նրանից, ա՛յն է, որ պղծում է մարդուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Ով ականջներ ունի լսելու, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Եւ երբ ամբոխից բաժանուելով տուն մտաւ, աշակերտները այդ առակի մասին նրան հարցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Եւ նրանց ասաց. «Դո՞ւք էլ այդպէս անմիտ էք, չէ՞ք իմանում, թէ ամէն բան, որ դրսից մարդու մէջ է մտնում, չի կարող նրան պղծել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'որովհետեւ ոչ թէ նրա սիրտն է մտնում, այլ՝ որովայնը եւ դուրս է ելնում ու մաքրում բոլոր կերածները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Եւ ասում էր. «Ինչ որ մարդուց դուրս է գալիս, ա՛յն է, որ պղծում է մարդուն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'որովհետեւ ներսից, մարդկանց սրտից են ելնում չար խորհուրդները՝ շնութիւն, պոռնկութիւն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'գողութիւն, սպանութիւն, ագահութիւն, չարութիւն, նենգութիւն, գիջութիւն, չար նախանձ, հայհոյանք, ամբարտաւանութիւն, անզգամութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Այս բոլոր չարիքները ներսից են ելնում եւ պղծում մարդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Եւ այնտեղից վեր կացաւ եկաւ Տիւրոսի ու Սիդոնի սահմանները. եւ մի տուն մտնելով՝ չէր ուզում, որ որեւէ մէկն իմանայ իր այնտեղ լինելը, սակայն չկարողացաւ թաքնուած մնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Նրա մասին լսեց մի կին, որի դուստրը տառապում էր պիղծ ոգուց. սա եկաւ ընկաւ նրա ոտքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Այս կինը հեթանոս էր, փիւնիկ-ասորի ազգից. աղաչում էր նրան, որ իր աղջկանից դեւը հանի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Եւ Յիսուս նրան ասաց. «Թո՛յլ տուր, որ նախ մանուկները կշտանան, քանի որ լաւ չէ մանուկների հացը առնել եւ շների առաջ գցել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Կինը պատասխանեց եւ ասաց. «Տէ՛ր, շներն էլ մանուկների սեղանի փշրանքներից են կերակրւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Եւ նա ասաց նրան. «Այդ խօսքիդ համար գնա՛, դեւը քո աղջկանից դուրս ելաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Կինը գնաց իր տունը եւ դեւին ելած գտաւ, իսկ աղջկան՝ պառկած մահճի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Եւ դարձեալ դուրս ելնելով Տիւրոսի եւ Սիդոնի սահմաններից, եկաւ Գալիլիայի ծովեզրը, Դեկապոլսի սահմաններից ներս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Նրա առաջ բերեցին մի խուլ ու համր մարդ եւ աղաչեցին, որ իր ձեռքը դնի նրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Եւ Յիսուս նրան ամբոխից մի կողմ տանելով՝ իր մատները դրեց նրա ականջների մէջ եւ այնտեղ թքեց. ապա բռնեց նրա լեզուից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'դէպի երկինք նայեց, հոգոց հանեց եւ ասաց՝ Եփփաթա, որ նշանակում է՝ բացուի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Եւ իսկոյն նրա լսողութիւնը բացուեց, եւ լեզուի կապանքներն ընկան, եւ խօսում էր ուղիղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Եւ նա նրանց պատուիրեց, որ ոչ ոքի չասեն. բայց ինչքան էլ նա պատուիրում էր նրանց, նրանք է՛լ աւելի էին տարածում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Եւ աւելի ու աւելի էին զարմանում եւ ասում. «Սա ամէն ինչ լաւ արեց, որովհետեւ խուլերին լսել է տալիս եւ համրերին՝ խօսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Այդ օրերին ժողովուրդը դարձեալ շատ էր, եւ ուտելու բան չունէին: Յիսուս կանչեց իր աշակերտներին եւ ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '«Սիրտս ցաւում է այս ժողովրդի համար, որովհետեւ արդէն երեք օր է, որ ինձ մօտ են. եւ բան չունեն, որ ուտեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Եթէ նրանց իրենց տներն արձակեմ քաղցած, ճանապարհին ուշագնաց կը լինեն, որովհետեւ նրանցից ոմանք հեռուներից են եկել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Աշակերտները նրան պատասխանեցին եւ ասացին. «Որտեղի՞ց կարող ես նրանց հացով կշտացնել այս ամայի վայրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Եւ նա հարցրեց նրանց. «Քանի՞ նկանակ հաց ունէք»: Եւ նրանք ասացին՝ եօթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Եւ նա հրամայեց ժողովրդին նստել գետնի վրայ. եւ վերցնելով եօթը նկանակները՝ գոհութիւն յայտնեց Աստծուն, կտրեց եւ տուեց աշակերտներին, որ դնեն ժողովրդի առաջ. եւ նրանք հացը ժողովրդի առաջ դրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Եւ քիչ թուով ձկներ էլ ունէին. եւ նա այդ եւս օրհնեց ու հրամայեց նրանց առաջ դնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Կերան եւ կշտացան եւ եօթը զամբիւղ աւելացած կտորտանքներ վերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Եւ նրանք, որ կերան, մօտ չորս հազար հոգի էին. եւ նրանց արձակեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Եւ իսկոյն աշակերտների հետ նաւակ մտնելով՝ եկաւ Դաղմանունայի կողմերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Եկան փարիսեցիները եւ սկսեցին վիճել նրա հետ եւ նրան փորձելով՝ երկնքից նշան էին ուզում նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Եւ նա իր հոգում զայրացաւ եւ ասաց. «Ինչո՞ւ է այս սերունդը նշան ուզում. ճշմարիտ եմ ասում ձեզ, որ այս սերնդին նշան չի տրուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Թողեց նրանց, նորից նաւակ մտաւ եւ գնաց ծովի միւս կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Եւ աշակերտները մոռացան հաց վերցնել. սակայն միայն մէկ նկանակ ունէին իրենց նաւակի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Եւ նա պատուիրեց նրանց ու ասաց. «Զգո՛յշ եղէք փարիսեցիների խմորից եւ հերովդէսականների խմորից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Իսկ նրանք իրենց մէջ խորհում էին եւ ասում՝ հաց չունենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Յիսուս իմացաւ նրանց խորհուրդը եւ նրանց ասաց. «Թերահաւատնե՛ր, ինչո՞ւ էք ձեր սրտերում խորհում, թէ հաց չունէք. դեռ չէ՞ք հասկանում եւ չէ՞ք յիշում. ապշութի՞ւնն է ձեր մտքերը պատել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Աչքեր ունէք եւ չէ՞ք տեսնում, ականջներ ունէք եւ չէ՞ք լսում եւ դեռ չէ՞ք հասկանում ու չէ՞ք յիշում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'երբ հինգ նկանակը բաժանեցի հինգ հազար հոգու, կտորտանքներով լի քանի՞ սակառ վերցրիք»: Եւ նրան պատասխանեցին՝ տասներկու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '«Եւ երբ եօթը նկանակը չորս հազար հոգու բաժանեցի, կտորտանքների քանի՞ զամբիւղ լիքը վերցրիք»: Եւ նրանք պատասխանեցին՝ եօթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Եւ նա նրանց ասաց. «Ապա ուրեմն ինչպէ՞ս չէք հասկանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Եկան Բեթսայիդա. եւ նրա առաջ բերեցին մի կոյրի ու աղաչում էին, որ դիպչի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Եւ նա բռնելով կոյրի ձեռքից՝ գիւղից դուրս հանեց. նրա աչքերը թքով թրջեց եւ ձեռքը նրա վրայ դրեց. եւ հարցնում էր կոյրին, թէ բան տեսնո՞ւմ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Նա բացեց աչքերը եւ ասաց. «Տեսնում եմ մարդկանց, որ շրջում են ինչպէս ծառեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Նա կրկին ձեռքերը դրեց նրա աչքերի վրայ. կոյրը իր աչքերը բացեց եւ տեսնում էր. բժշկուեց եւ ամէն ինչ յստակ տեսնում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Նրան իր տունն արձակեց եւ ասաց. «Գիւղ մի՛ մտիր, այլ գնա՛ քո տունը, իսկ երբ գիւղ մտնես, գիւղում ոչ ոքի չասես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Եւ Յիսուս իր աշակերտների հետ միասին ելաւ գնաց Փիլիպպեան Կեսարիայի գիւղերը. եւ ճանապարհին աշակերտներին հարցնում էր եւ ասում. «Մարդիկ ի՞նչ են ասում իմ մասին՝ ո՞վ եմ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Նրանք պատասխան տուեցին եւ ասացին. «Յովհաննէս Մկրտիչը, եւ ոմանք՝ Եղիան, իսկ ուրիշներ՝ մարգարէներից մէկը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Նրանց ասաց. «Իսկ դուք ի՞նչ էք ասում իմ մասին՝ ո՞վ եմ ես»: Պետրոսը պատասխան տուեց եւ ասաց նրան. «Դու Քրիստոսն ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Եւ նա խստիւ պատուիրեց նրանց, որ իր մասին մարդու բան չասեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Եւ սկսեց ուսուցանել աշակերտներին, թէ մարդու Որդին պէտք է բազում չարչարանքներ կրի, անարգուի երէցներից ու քահանայապետներից եւ օրէնսգէտներից, մեռնի եւ երրորդ օրը յարութիւն առնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Եւ այս խօսքը ասաց բացայայտօրէն. եւ Պետրոսը նրան մի կողմ տանելով՝ սկսեց յանդիմանել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Իսկ նա դարձաւ տեսաւ աշակերտներին, սաստեց Պետրոսին ու ասաց. «Ետե՛ւս գնա, սատանա՛յ, որովհետեւ դու Աստծո՛ւ բաները չես խորհում, այլ՝ մարդկանցը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Եւ նա իր մօտ կանչելով ժողովրդին, աշակերտների հետ միասին, ասաց նրանց. «Եթէ մէկը կամենում է գալ իմ յետեւից, թող ուրանայ իր անձը, թող վերցնի իր խաչը եւ գայ իմ յետեւից,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'որովհետեւ ով կամենում է ազատել իր անձը, այն պիտի կորցնի. իսկ ով կորցնի իր անձը Աւետարանի համար, պիտի ազատի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Ի՞նչ օգուտ է մարդուն, եթէ ամբողջ աշխարհը շահի, բայց իր անձը կորցնի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'որովհետեւ մարդ ի՞նչ ունի տալու իր անձի փոխարէն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Ով որ ամօթ համարի ինձ եւ իմ խօսքերը այս շնացող եւ մեղաւոր ազգի մէջ, մարդու Որդին էլ նրան պիտի ամաչեցնի, երբ գայ փառքովն իր Հօր եւ սուրբ հրեշտակների»: Եւ նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, թէ նրանցից, որ այստեղ են, կան ոմանք, որոնք մահ չպիտի ճաշակեն, մինչեւ որ տեսնեն Աստծու արքայութիւնը՝ զօրութեամբ եկած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Վեց օր յետոյ Յիսուս իր հետ վերցրեց Պետրոսին, Յակոբոսին եւ Յովհաննէսին ու առանձին նրանց հանեց մի բարձր լերան վրայ եւ նրանց առաջ պայծառակերպուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Եւ նրա զգեստները փայլուն, խիստ սպիտակ դարձան, այնպէս որ երկրի վրայ ոչ մի լուացք անող չի կարող այդքան սպիտակեցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Եւ նրանց երեւաց Եղիան՝ Մովսէսի հետ մէկտեղ, ու նրանք խօսում էին Յիսուսի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Պետրոսը Յիսուսին ասաց. «Ռաբբի՛, լաւ է, որ մենք այստեղ լինենք եւ երեք տաղաւարներ շինենք, մէկը՝ քեզ, մէկը՝ Մովսէսի եւ մէկն էլ՝ Եղիայի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Սակայն չգիտէր, թէ ինչ էր խօսում, որովհետեւ զարհուրած էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Եւ մի ամպ նրանց վրայ հովանի եղաւ. ամպից մի ձայն եկաւ, որ ասում էր. «Դա՛ է իմ սիրելի Որդին, դրա՛ն լսեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Եւ յանկարծակի այս ու այն կողմ նայելով՝ այլեւս ոչ մի տեղ ոչ ոքի չտեսան, այլ միայն Յիսուսին՝ իրենց հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Եւ մինչ լեռնից իջնում էին, նա պատուիրեց նրանց, որ իրենց տեսածը մարդու չպատմեն, մինչեւ որ մարդու Որդին մեռելներից յարութիւն առնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Նրանք այս խօսքը իրենց մտքում պահում էին եւ միմեանց հարցնում էին, թէ ի՛նչ է մեռելներից յարութիւն առնելը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Ապա հարցրին նրան ու ասացին. «Այն ի՞նչ է, որ օրէնսգէտներն ասում են, թէ նախ Եղիան պէտք է գայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Նա պատասխանեց նրանց եւ ասաց. «Եղիան նախ պիտի գայ եւ ամէն բան կարգի պիտի դնի. իսկ ինչո՞ւ մարդու Որդու մասին գրուած է, որ շատ չարչարանքներ պիտի կրի ու անարգուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Բայց ես ասում եմ ձեզ, որ Եղիան եկաւ, եւ նրան արեցին, ինչ որ կամեցան, ինչպէս որ գրուած է նրա մասին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Եւ աշակերտների մօտ գալով՝ նրանց շուրջը տեսաւ մեծ բազմութիւն եւ օրէնսգէտներ, որոնք վիճում էին նրանց հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Եւ իսկոյն ամբողջ ժողովուրդը, երբ տեսաւ նրան, զարմացաւ եւ, ընդառաջ վազելով, ողջոյն էր տալիս նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Յիսուս աշակերտներին հարցրեց. «Ինչի՞ մասին էիք վիճում նրանց հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Ժողովրդի միջից մէկը պատասխանեց եւ ասաց. «Վարդապե՛տ, քեզ մօտ բերեցի որդուս, որին մի համր չար ոգի բռնել է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'եւ ուր պատահում է, նրան գետին է զարկում. փրփրում է, ատամներն է կրճտացնում եւ ապա չորանում մնում է: Քո աշակերտներին ասացի, որ հանեն, բայց չկարողացան հանել այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Նա պատասխանեց նրանց եւ ասաց. «Ո՛վ անհաւատ սերունդ, մինչեւ ե՞րբ ձեզ հետ պիտի լինեմ, մինչեւ ե՞րբ ձեզ պիտի հանդուրժեմ. բերէ՛ք նրան ինձ մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Եւ նրան բերեցին իր մօտ: Երբ չար ոգին նրան տեսաւ, իսկոյն ուժգին ցնցեց տղային, որը, գետին ընկնելով, թաւալւում էր ու փրփրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Յիսուս հարցրեց նրա հօրը եւ ասաց. «Ինչքա՞ն ժամանակ է անցել այն օրուանից, ինչ այդ նրան պատահել է»: Եւ նա ասաց. «Մանկութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Շատ անգամ չար ոգին կրակի եւ ջրի մէջ է նետում նրան, որ կործանի. արդ, եթէ մի կերպ կարող ես, օգնի՛ր մեզ, Տէ՛ր, գթալով մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Եւ Յիսուս նրան ասաց. «Ասացիր՝ եթէ կարող ես. ամէն ինչ հնարաւոր է նրա համար, ով հաւատում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Երեխայի հայրը իսկոյն աղաղակեց եւ ասաց. «Հաւատում եմ, օգնի՛ր իմ անհաւատութեանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Երբ Յիսուս տեսաւ, որ ժողովուրդը իրար վրայ է հաւաքւում, սաստեց պիղծ ոգուն եւ ասաց. «Դո՛ւ, հա՛մր եւ խո՛ւլ ոգի, ես հրամայում եմ քեզ, դո՛ւրս ելիր նրանից եւ այլեւս չմտնես դրա մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Եւ չար ոգին ճչաց, ուժգին ցնցեց նրան ու դուրս ելաւ. եւ պատանին մեռելի պէս եղաւ, այն աստիճան, որ շատերը ասացին, թէ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Յիսուս բռնեց նրա ձեռքից, բարձրացրեց նրան, եւ նա ոտքի կանգնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Եւ երբ Յիսուս տուն մտաւ, աշակերտները, առանձին, հարցրին նրան. «Ինչո՞ւ մենք չկարողացանք հանել դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Եւ նա նրանց ասաց. «Այդ տեսակը ուրիշ բանով չի ելնի, եթէ ոչ ծոմապահութեամբ ու աղօթքով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Այնտեղից ելնելով՝ նրանք անցնում էին Գալիլիայի միջով, եւ Յիսուս չէր կամենում, որ որեւէ մէկն իմանայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'քանի որ իր աշակերտներին ուսուցանում էր եւ նրանց ասում. «Մարդու Որդին մատնուելու է մարդկանց ձեռքը, նրանք պիտի սպանեն նրան. եւ երբ նա սպանուի, երրորդ օրը յարութիւն պիտի առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Բայց նրանք չէին հասկանում այդ խօսքը եւ վախենում էին նրան հարցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Եկաւ Կափառնայում եւ, երբ տուն մտաւ, աշակերտներին հարցրեց. «Ճանապարհին իրար հետ ինչի՞ մասին էիք վիճում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Եւ նրանք լուռ էին մնում, որովհետեւ ճանապարհին իրար հետ վիճում էին, թէ ո՛վ է մեծը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Եւ երբ նստեց, կանչեց Տասներկուսին ու նրանց ասաց. «Եթէ մէկն ուզում է առաջին լինել, բոլորից վերջինը եւ բոլորի սպասաւորը պիտի լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Եւ մի մանուկ վերցնելով՝ կանգնեցրեց նրանց մէջ եւ նրան իր գիրկն առնելով՝ նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, '«Ով այսպիսի մանուկներից մէկին ընդունում է իմ անունով, ինձ է ընդունում, եւ ով ինձ է ընդունում, ոչ թէ ինձ է ընդունում, այլ նրան, ով ինձ ուղարկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Յովհաննէսը պատասխանեց եւ ասաց. «Վարդապե՛տ, տեսանք մէկին, որը քո անունով դեւեր էր հանում, բայց մեզ հետ չէր շրջում, եւ արգելեցինք նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Եւ նա ասաց. «Արգելք մի՛ եղէք նրան, որովհետեւ չկայ մէկը, որ իմ անունով զօրաւոր գործեր անի ու կարողանայ ինձ հայհոյել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'քանզի ով մեզ հակառակ չէ, նա մեր կողմն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Եւ ով որ ձեզ մի բաժակ ջուր խմեցնի յանուն այն բանի, որ դուք Քրիստոսինն էք, ճշմարիտ եմ ասում ձեզ, իր վարձը չպիտի կորցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, '«Եւ ով որ ինձ հաւատացող այս փոքրիկներից մէկին գայթակղեցնի, նրա համար աւելի լաւ կը լինէր, եթէ նրա պարանոցից կախուած լինէր էշի մի երկանաքար, եւ ծով գցուէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Եւ եթէ քեզ գայթակղեցնում է քո ձեռքը, կտրիր դէ՛ն գցիր քեզնից, որովհետեւ քեզ համար աւելի լաւ է խեղուած մտնել յաւիտենական կեանքը, քան թէ երկու ձեռք ունենալ ու գնալ գեհեն, անշէջ կրակի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Եւ եթէ քո ոտքն է գայթակղեցնում քեզ, կտրի՛ր, քեզնից դէ՛ն գցիր այն. լաւ է, որ դու կաղ մտնես յաւիտենական կեանքը, քան թէ երկու ոտք ունենաս ու գեհեն ընկնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Եւ եթէ քո աչքն է գայթակղեցնում քեզ, քաշիր հանի՛ր այն. լաւ է, որ դու մէկ աչքով մտնես Աստծու արքայութիւնը, քան թէ երկու աչք ունենաս ու ընկնես գեհեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'ուր նրանց որդը չի մեռնում, եւ կրակը չի հանգչում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'որովհետեւ ամէն ինչ կրակով պիտի աղուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Աղը լաւ բան է. բայց եթէ աղը անհամանայ, ինչո՞վ պիտի համեմուի. արդ, դուք ձեր մէ՛ջ ունեցէք աղը եւ իրար հետ խաղաղութեա՛մբ ապրեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Յիսուս այնտեղից վեր կացաւ եկաւ Հրէաստանի սահմանները, Յորդանանի միւս կողմը. եւ ժողովուրդը դարձեալ գնում խռնւում էր նրա շուրջը, եւ նա, ինչպէս սովոր էր, նորից ուսուցանում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Իսկ փարիսեցիները մօտեցան եւ նրան փորձելով՝ հարց տուին ու ասացին. «Օրինաւո՞ր է, որ մարդ իր կնոջն արձակի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Նա պատասխան տուեց նրանց եւ ասաց. «Մովսէսը ձեզ ի՞նչ պատուիրեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Եւ նրանք ասացին. «Մովսէսը հրաման տուեց արձակելու թուղթ գրել եւ արձակել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Ձեր խստասրտութեան պատճառով գրեց այդ պատուիրանը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'մինչդեռ արարչագործութեան սկզբից Աստուած արու եւ էգ ստեղծեց նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Եւ ասաց. «Դրա համար տղամարդը պիտի թողնի իր հօրն ու մօրը եւ պիտի գնայ իր կնոջ յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Եւ երկուսը մի մարմին պիտի լինեն, եւ այլեւս երկու չեն, այլ՝ մէկ մարմին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Արդ, ինչ որ Աստուած միացրեց, մարդը թող չբաժանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Եւ աշակերտները տան մէջ դարձեալ նոյնը հարցրին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Եւ նրանց ասաց. «Եթէ մի մարդ արձակի իր կնոջը եւ ուրիշին առնի, շնութիւն արած կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Եւ մի կին եթէ թողնի իր ամուսնուն եւ ուրիշ մարդու կին լինի, շնութիւն արած կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Եւ նրան մանուկներ էին բերում, որպէսզի ձեռքը դնի նրանց վրայ: Իսկ աշակերտները յանդիմանում էին նրանց, ովքեր բերում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Երբ Յիսուս այս տեսաւ, բարկանալով սաստեց նրանց եւ ասաց. «Թո՛յլ տուէք այդ մանուկներին գալ ինձ մօտ եւ արգելք մի՛ եղէք նրանց, որովհետեւ Աստծու արքայութիւնը այդպիսիներինն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Ճշմարիտ եմ ասում ձեզ, ով Աստծու արքայութիւնը չընդունի որպէս մանուկ, նրա մէջ չի մտնելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Եւ նա վերցնելով նրանց իր գիրկը՝ նրանց վրայ ձեռքը դրեց եւ օրհնեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Երբ նա այնտեղից ճանապարհ ընկաւ, ահա մեծահարուստ մէկը առաջ վազելով ծնկի իջաւ, հարցրեց նրան ու ասաց. «Բարի՛ Վարդապետ, ի՞նչ պէտք է անեմ, որ յաւիտենական կեանքը ժառանգեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Եւ Յիսուս նրան ասաց. «Ինչո՞ւ ես ինձ բարի կոչում. բարի չէ ոչ ոք, այլ միայն՝ Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Պատուիրանները գիտես. մի՛ շնանար, մի՛ սպանիր, մի՛ գողանար, սուտ մի՛ վկայիրպատուի՛ր քո հօրն ու մօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Նա պատասխանեց եւ ասաց նրան. «Վարդապե՛տ, այդ բոլորը իմ մանկութիւնից ի վեր արել եմ. արդ, ի՞նչ եմ պակաս թողել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Եւ Յիսուս նրան նայելով՝ սիրեց նրան եւ ասաց. «Քեզ մէ՛կ բան է պակասում. եթէ կամենում ես կատարեալ լինել, գնա վաճառի՛ր ինչ որ ունես ու աղքատների՛ն տուր եւ երկնքում գանձեր կ՚ունենաս. եւ վերցրո՛ւ խաչդ եւ արի՛ իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Եւ մարդը այդ խօսքի վրայ խոժոռուած՝ գնաց տրտում, որովհետեւ շատ հարուստ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Եւ Յիսուս այս կողմ, այն կողմ նայելով՝ ասաց իր աշակերտներին. «Ինչքա՜ն դժուարին է Աստծու արքայութիւն մտնել նրանց համար, որ հարստութիւն ունեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Եւ աշակերտները զարմացած էին նրա խօսքերի վրայ. իսկ Յիսուս դարձեալ պատասխանեց նրանց եւ ասաց. «Զաւակնե՛րս, ինչքա՜ն դժուար է Աստծու արքայութիւն մտնել նրանց համար, որ իրենց յոյսը դրել են հարստութեան վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Աւելի հեշտ է, որ պարանը ասեղի ծակից անցնի, քան թէ մի մեծահարուստ Աստծու արքայութիւնը մտնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Եւ աշակերտները առաւել եւս էին զարմանում ու միմեանց ասում. «Ապա ուրեմն ո՞վ կարող է փրկուել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Նայելով նրանց՝ Յիսուս ասաց. «Մարդկանց համար այդ անհնար է, բայց ո՛չ Աստծու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Պետրոսն սկսեց նրան ասել. «Ահաւասիկ մենք թողել ենք ամէն բան եւ եկել ենք քո յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Յիսուս պատասխանեց եւ ասաց. «Ճշմարիտ եմ ասում ձեզ, չկայ մէկը, որ թողած լինի տուն, կամ եղբայրներ, կամ քոյրեր, կամ հայր, կամ մայր, կամ որդիներ, կամ ագարակներ ինձ համար կամ Աւետարանի համար եւ այժմ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'այս ժամանակի մէջ հարիւրապատիկը չստանայ՝ տներ եւ եղբայրներ եւ քոյրեր եւ մայրեր եւ որդիներ եւ ագարակներ՝ հալածանքներ կրելով հանդերձ, եւ այն աշխարհում, որ գալու է՝ յաւիտենական կեանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Սակայն շատեր, որ առաջին են, պիտի լինեն վերջին, իսկ վերջիններ՝ առաջին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Եւ Երուսաղէմ ելնելու ճանապարհի վրայ էին. Յիսուս աշակերտներից աւելի առաջ էր գնում. իսկ նրանք, որ նրա յետեւից էին գնում, զարմացած էին ու վախենում էին: Եւ նա նորից վերցնելով Տասներկուսին՝ առանձին, սկսեց ասել նրանց, թէ ինչ բաներ պիտի պատահեն իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '«Ահա ելնում ենք Երուսաղէմ. եւ մարդու Որդին պիտի մատնուի քահանայապետներին ու օրէնսգէտներին, եւ նրան մահուան պիտի դատապարտեն ու հեթանոսներին պիտի յանձնեն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'նրան պիտի ծաղրեն. նրան պիտի ծեծեն ու նրա վրայ պիտի թքեն. եւ պիտի սպանեն. եւ երրորդ օրը նա յարութիւն պիտի առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Զեբեդէոսի որդիները՝ Յակոբոսը եւ Յովհաննէսը, գնացին նրա մօտ եւ ասացին նրան. «Վարդապե՛տ, ինչ որ քեզնից պիտի խնդրենք, կամենում ենք, որ անես մեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Եւ նա նրանց ասաց. «Ի՞նչ էք կամենում ինձնից, որ անեմ ձեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Եւ նրանք ասացին նրան. «Շնո՛րհ արա մեզ, որ նստենք մէկս՝ քո աջում եւ միւսս՝ ձախում, քո փառքի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Չէք իմանում, թէ ինչ էք խնդրում. կարո՞ղ էք խմել այն բաժակը, որ ես խմելու եմ, կամ մկրտուել այն մկրտութեամբ, որով ես մկրտուելու եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Եւ նրանք ասացին նրան. «Կարող ենք»: Եւ Յիսուս նրանց ասաց. «Այն բաժակը, որ ես խմելու եմ, կը խմէք, եւ այն մկրտութիւնը, որով ես մկրտուելու եմ, նրանով կը մկրտուէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'բայց իմ աջում եւ ձախում նստեցնելը ես չէ, որ պիտի տամ, այլ տրուելու է նրանց, որոնց համար պատրաստուած է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Այդ լսելով՝ տասը առաքեալները սկսեցին բարկանալ Յակոբոսի եւ Յովհաննէսի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Յիսուս նրանց իր մօտ կանչեց եւ ասաց. «Գիտէք, որ հեթանոսների մէջ իշխանաւորներ համարուածները տիրում են նրանց. եւ նրանց մեծամեծներն իշխում են նրանց վրայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'ձեր մէջ այդպէս չպէտք է լինի. այլ ձեզնից ով կամենայ մեծ լինել, թող լինի ձեր սպասաւորը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'եւ ձեզնից ով կամենայ առաջին լինել, բոլորին ծառայ թող լինի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'որովհետեւ մարդու Որդին էլ չեկաւ ծառայութիւն ընդունելու, այլ՝ ծառայելու եւ տալու իր անձը որպէս փրկանք շատերի փոխարէն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Եւ եկան Երիքով: Եւ մինչ նա Երիքովից դուրս էր գալիս իր աշակերտներով եւ բազում ժողովրդով, Տիմէի որդին՝ կոյր Բարտիմէոսը, նստել մուրում էր ճանապարհի եզրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Երբ լսեց, թէ անցնողը Յիսուս Նազովրեցին է, սկսեց աղաղակել եւ ասել. «Դաւթի՛ Որդի, Յիսո՛ւս, ողորմի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Եւ շատերը նրան սաստում էին, որ լռի, իսկ նա առաւել եւս աղաղակում էր. «Դաւթի՛ Որդի, ողորմի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Յիսուս կանգնեց եւ հրամայեց, որ նրան կանչեն: Կոյրին կանչեցին եւ նրան ասացին. «Քաջալերուի՛ր, վե՛ր կաց, կանչում է քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Եւ նա, դէն գցելով իր զգեստները, վեր կացաւ եկաւ Յիսուսի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Յիսուս նրան ասաց. «Ի՞նչ ես ուզում, որ քեզ անեմ»: Կոյրը նրան ասաց. «Վարդապե՛տ, աչքերս թող բացուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Եւ Յիսուս նրան ասաց. «Գնա՛, քո հաւատը քեզ փրկեց»: Եւ իսկոյն նրա աչքերը բացուեցին, եւ ճանապարհին գնում էր նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Երբ մօտեցան Երուսաղէմին, Բեթփագէին եւ Բեթանիային, Ձիթենեաց լերան մօտ, նա ուղարկեց աշակերտներից երկուսին եւ նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, '«Դուք գնացէ՛ք այդ գիւղը, որ ձեր դիմացն է. եւ հէնց որ այնտեղ մտնէք, կը գտնէք մի կապուած աւանակ, որի վրայ ոչ մի մարդ արարած չի նստել. արձակեցէ՛ք այն եւ բերէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Եւ եթէ մէկը ձեզ ասի. «Այդ աւանակը ինչո՞ւ էք արձակում», կ՚ասէք. «Տիրոջը պէտք է». եւ նա իսկոյն դրան այստեղ կ՚ուղարկի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Գնացին եւ գտան աւանակը՝ կապուած դռան մօտ, դրսում, փողոցի մէջ, եւ այն արձակեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Եւ այնտեղ կանգնածներից ոմանք ասացին նրանց. «Ի՞նչ էք անում, ինչո՞ւ էք այդ աւանակն արձակում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Եւ նրանք նրանց ասացին, ինչպէս Յիսուս ասել էր. ու նրանց թոյլ տուին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Աւանակը բերեցին Յիսուսի մօտ. եւ դրա վրայ զգեստներ գցեցին, եւ Յիսուս նստեց դրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Եւ շատեր իրենց զգեստները փռում էին ճանապարհին. եւ ուրիշներ ծառերից ճիւղեր էին կտրում ու գցում ճանապարհի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Եւ նրանք, որ առաջից ու յետեւից էին գնում, աղաղակում էին եւ ասում. «Ովսաննա՜ Բարձրեալին, օրհնեա՜լ լինի նա, որ գալիս է Տիրոջ անունով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'օրհնեա՜լ լինի մեր հօր՝ Դաւթի թագաւորութիւնը, որ գալիս է: Խաղաղութի՜ւն՝ երկնքում եւ փա՜ռք՝ բարձունքներում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Եւ Յիսուս մտաւ Երուսաղէմ, գնաց տաճար ու նայեց իր շուրջը, ամէն ինչի վրայ. եւ որովհետեւ երեկոյի ժամ էր, բարձրացաւ Բեթանիա՝ Տասներկուսի հետ միասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Յաջորդ օրը, մինչ Բեթանիայից դուրս էին գալիս, Յիսուս քաղցած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Եւ հեռուից մի տերեւալից թզենի տեսնելով՝ եկաւ, որ թերեւս նրա վրայ մի բան գտնի. եւ երբ նրան մօտեցաւ, ոչինչ չգտաւ, այլ միայն՝ տերեւ, որովհետեւ տակաւին թզի ժամանակը չէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Յիսուս խօսքը թզենուն ուղղեց եւ ասաց. «Էլ քեզնից ոչ ոք պտուղ չուտի յաւիտեան»: Եւ նրա աշակերտները լսում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Եկան Երուսաղէմ. եւ Յիսուս տաճար մտնելով՝ սկսեց դուրս հանել տաճարում գտնուող վաճառողներին ու գնորդներին եւ լումայափոխների սեղանները ցրեց ու աղաւնեվաճառների աթոռները շուռ տուեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'եւ չէր թողնում, որ որեւէ մէկը տաճարի միջով նոյնիսկ որեւէ բան անցկացնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Եւ ուսուցանում էր նրանց ու ասում. «Գրուած է՝ իմ տունը բոլոր ազգերի համար աղօթքի տուն է կոչուելու, իսկ դուք այն դարձրել էք աւազակների որջեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Քահանայապետներն ու օրէնսգէտները լսեցին այս եւ մի միջոց էին փնտռում, թէ ինչպէս կորստեան մատնեն նրան, բայց վախենում էին նրանից, որովհետեւ ամբողջ ժողովուրդը զարմացած էր նրա ուսուցման վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Երբ երեկոյ եղաւ, քաղաքից դուրս ելան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Յաջորդ օրը, առաւօտեան, մինչ նոյն ճանապարհից էին անցնում, թզենին արմատից չորացած տեսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Պետրոսը յիշեց եւ ասաց նրան. «Ռաբբի՛, ահաւասիկ թզենին, որին անիծեցիր, չորացել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Յիսուս պատասխանեց եւ ասաց նրան. «Եթէ Աստծու հանդէպ հաւատ ունենաք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'ճշմարիտ եմ ասում ձեզ, ով որ այս լերանն ասի՝ ե՛լ եւ ծո՛վն ընկիր, եւ իր սրտում չկասկածի, այլ հաւատայ, թէ ինչ որ ասում է, կը լինի, նա ինչ էլ ասի, կը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Դրա համար ասում եմ ձեզ. ամէն ինչ, որ աղօթք անելով խնդրէք եւ հաւատաք, թէ կը ստանաք, կը տրուի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Եւ երբ աղօթքի կանգնէք, թէ մէկի դէմ մի բան ունէք, ներեցէ՛ք, որպէսզի ձեր Հայրն էլ, որ երկնքում է, ների ձեզ ձեր յանցանքները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Դարձեալ Երուսաղէմ եկան. եւ մինչ նա այնտեղ, տաճարում շրջում էր, նրա մօտ եկան քահանայապետները, օրէնսգէտները եւ ծերերը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'ու ասացին նրան. «Ի՞նչ իշխանութեամբ ես դու այդ անում, եւ ո՞վ տուեց քեզ այդ իշխանութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'Յիսուս պատասխան տուեց եւ ասաց նրանց. «Ես էլ ձե՛զ մի բան հարցնեմ, պատասխանեցէ՛ք ինձ, եւ ես ձեզ կ՚ասեմ, թէ ինչ իշխանութեամբ եմ այս անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Յովհաննէսի մկրտութիւնը երկնքի՞ց էր, թէ՞՝ մարդկանցից. պատասխանեցէ՛ք ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Նրանք իրար միջեւ խորհում էին ու ասում. «Եթէ ասենք՝ երկնքից, մեզ կ՚ասի՝ իսկ ինչո՞ւ նրան չհաւատացիք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'իսկ եթէ ասենք՝ մարդկանցից, ժողովրդից ենք վախենում». որովհետեւ բոլորը գիտէին, թէ Յովհաննէսը մարգարէ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Պատասխան տուեցին եւ Յիսուսին ասացին՝ չգիտենք. եւ Յիսուս նրանց պատասխանեց ու ասաց. «Ես էլ ձե՛զ չեմ ասի, թէ ինչ իշխանութեամբ եմ այս անում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Եւ սկսեց նրանց հետ առակներով խօսել եւ ասել. «Մի մարդ այգի տնկեց եւ նրա շուրջը ցանկապատ քաշեց, հնձանի փոս փորեց եւ աշտարակ շինեց. ու այն յանձնեց մշակներին եւ գնաց ուրիշ երկիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Երբ ժամանակը հասաւ, մշակների մօտ մի ծառայ ուղարկեց, որ այդ մշակներից վերցնի այգու պտղից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Եւ մշակները նրան բռնելով՝ ծեծեցին ու ձեռնունայն արձակեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Դարձեալ նա մի ուրիշ ծառայ ուղարկեց, եւ նրա էլ գլխին հարուածեցին եւ անարգելով արձակեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Եւ վերստին մէկ ուրիշին ուղարկեց. սրան էլ՝ սպանեցին. եւ ուրիշ շատերին ուղարկեց. ոմանց ծեծում էին, ոմանց՝ սպանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Դեռեւս նա մի սիրելի որդի ունէր. վերջում նրան ուղարկեց նրանց մօտ՝ ասելով. «Թերեւս իմ այս որդուց ամաչեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Իսկ մշակները երբ տեսան, որ նա գալիս է, իրար ասացին. «Ժառանգը սա է, եկէք սպանենք սրան, եւ ժառանգութիւնը մերը թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Եւ բռնելով նրան՝ սպանեցին ու հանեցին գցեցին այգուց դուրս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Արդ, այգու տէրը ի՞նչ կ՚անի. կը գայ եւ կը սպանի մշակներին ու այգին ուրիշների ձեռքը կը յանձնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Դուք չէ՞ք կարդացել Գրքի այն խօսքը, թէ՝ «Այն քարը, որ կառուցողները անարգեցին, նա՛ եղաւ անկիւնաքար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Տիրոջ կողմից եղաւ այս, եւ մեր աչքին սքանչելի է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Եւ նրանք միջոց էին փնտռում՝ նրան ձերբակալելու, բայց ժողովրդից վախեցան, որովհետեւ հասկացան, թէ նա առակը իրենց մասին ասաց: Եւ թողեցին նրան ու գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Եւ նրա մօտ ուղարկեցին փարիսեցիներից եւ հերովդէսականներից ոմանց, որպէսզի նրան խօսքով որսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Եւ նրանք եկան ու նենգութեամբ հարց էին տալիս եւ ասում. «Վարդապե՛տ, գիտենք, որ դու ճշմարտասէր ես եւ չես քաշւում ոչ ոքից, որովհետեւ մարդկանց աչառութիւն չես անում, այլ ճշմարտութեամբ Աստծու ճանապարհն ես ուսուցանում. արդ, ասա՛ մեզ, օրինաւո՞ր է հարկ տալ կայսրին, թէ՞ ոչ. տա՞նք, թէ՞ չտանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Յիսուս իմացաւ նրանց կեղծաւորութիւնը եւ ասաց. «Ինչո՞ւ էք ինձ փորձում, կեղծաւորնե՛ր. ինձ մի դահեկա՛ն բերէք, որ տեսնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Եւ նրանք բերեցին: Եւ նրանց ասաց. «Ո՞ւմն է այս պատկերը կամ գիրը»: Եւ նրանք ասացին նրան՝ կայսրինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Յիսուս պատասխան տուեց եւ ասաց նրանց. «Գնացէ՛ք, տուէ՛ք կայսրինը՝ կայսեր եւ Աստծունը՝ Աստծուն»: Եւ զարմացան նրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Նրա մօտ եկան սադուկեցիները, որոնք ասում են, թէ՝ յարութիւն չկայ. հարց էին տալիս եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '«Վարդապե՛տ, Մովսէսը մեզ համար գրել է. «Եթէ մէկի եղբայրը մեռնի եւ կին թողնի, բայց որդի չթողնի, թող նրա եղբայրը առնի նրա կնոջը եւ իր եղբօր համար զաւակ հասցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Արդ, մեզ մօտ եօթը եղբայրներ կային. առաջինը կին առաւ եւ մեռաւ ու զաւակ չթողեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'եւ երկրորդը նոյն կնոջն առաւ ու մեռաւ. եւ նա էլ զաւակ չթողեց: Նոյն ձեւով նաեւ երրորդը առաւ նոյն կնոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Եւ եօթն էլ զաւակ չթողեցին. ամենքից յետոյ մեռաւ նաեւ կինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Արդ, յարութեան ժամանակ, երբ յարութիւն առնեն, նրանցից ո՞ւմ կինը կը լինի. քանի որ եօթն էլ նրան կին առան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Յիսուս պատասխան տուեց եւ ասաց նրանց. «Հէնց դրա համար չէ՞, որ մոլորուած էք. քանի որ չգիտէք Գրքերը եւ ոչ էլ՝ Աստծու զօրութիւնը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'որովհետեւ, երբ մեռելներից յարութիւն առնեն, ո՛չ տղամարդիկ կին կ՚առնեն եւ ո՛չ էլ կանայք մարդու կը գնան, այլ կը լինեն հրեշտակների նման, որ երկնքում են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Իսկ գալով մեռելներին, թէ յարութիւն են առնում, դուք չէ՞ք կարդացել Մովսէսի գրքում, մորենու դրուագում, թէ ինչպէս Աստուած ասաց նրան. «Ե՛ս եմ, - ասում է, - Աբրահամի Աստուածը, Իսահակի Աստուածը եւ Յակոբի Աստուածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Իսկ Աստուած մեռելների Աստուածը չէ, այլ՝ ողջերի. ուստի, դուք խիստ մոլորուած էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Օրէնսգէտներից մէկը, մօտենալով, լսում էր նրանց, մինչ վիճում էին. երբ նա տեսաւ, թէ Յիսուս նրանց պատասխանը լաւ տուեց, հարցրեց նրան եւ ասաց. «Ո՞ր պատուիրանն է առաջինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Եւ Յիսուս ասաց նրան. «Ամենից առաջինն է՝ «Լսի՛ր, Իսրայէ՛լ, մեր Տէր Աստուածը միակ Տէրն է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'եւ դու պիտի սիրես քո Տէր Աստծուն քո ամբողջ սրտով, քո ամբողջ հոգով, քո ամբողջ մտքով եւ քո ամբողջ զօրութեամբ». սա՛ է առաջին պատուիրանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Եւ երկրորդը նման է սրան. «Դու պիտի սիրես քո ընկերոջը քո անձի պէս». չկայ ուրիշ պատուիրան աւելի մեծ, քան սրանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Եւ օրէնսգէտը նրան ասաց. «Լաւ է, Վարդապե՛տ, ճշմարտութեամբ ասացիր, թէ Աստուած մէկ է, եւ բացի նրանից, ուրիշ Աստուած չկայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'եւ նրան ամբողջ սրտով, ամբողջ զօրութեամբ, ամբողջ մտքով սիրելը, ինչպէս եւ ընկերոջն իր անձի պէս սիրելը առաւել է, քան ողջակէզները եւ զոհերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Եւ Յիսուս տեսնելով, թէ նա իմաստութեամբ պատասխան տուեց, նրան ասաց. «Հեռու չես Աստծու արքայութիւնից»: Եւ այլեւս ոչ ոք չէր համարձակւում նրան բան հարցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Մինչ Յիսուս ուսուցանում էր տաճարում, հարց տուեց ժողովրդին ու ասաց. «Ինչպէ՞ս են ասում օրէնսգէտները, թէ Քրիստոս Դաւթի Որդի է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'մինչ Դաւիթն ինքը Սուրբ Հոգով ասում է. «Տէրն իմ Տիրոջն ասաց. նստի՛ր իմ աջում, մինչեւ որ քո թշնամիներին քո ոտքերի համար պատուանդան դնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Արդ, եթէ Դաւիթն ինքն իսկ նրան Տէր է կոչում, ինչպէ՞ս նրա Որդին կը լինի»: Եւ շատ ժողովուրդ նրան լսում էր սիրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Եւ սովորեցնելով՝ նա իր ուսուցման ընթացքում ասում էր. «Զգո՛յշ եղէք այդ օրէնսգէտներից, որ ուզում են աչքի զարնող զգեստներով ման գալ, հրապարակներում յարգանքի ողջոյններ որոնել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'ժողովարաններում՝ առաջին աթոռները եւ ընթրիքների ժամանակ՝ պատուոյ տեղերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Նրանք ուտում են այրիների տները, ցուցադրաբար երկարացնում են աղօթքները, որպէսզի աւելի խիստ դատաստան ընդունեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Յիսուս կանգնած էր գանձանակի դիմաց. դիտում էր, թէ ինչպէս ժողովուրդը պղինձ դրամ է գցում գանձանակի մէջ: Եւ շատ մեծահարուստներ շատ բան գցեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Մի այրի կին եկաւ եւ երկու լումայ գցեց, որ մի գրոշ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Եւ Յիսուս իր մօտ կանչելով իր աշակերտներին՝ նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ այդ չքաւոր այրին աւելի շատ գցեց, քան գանձանակի մէջ միւս բոլոր դրամ գցողները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'քանի որ ամէնքը իրենց աւելորդից գցեցին, իսկ նա, իր չքաւորութիւնից, գցեց ամէն ինչ, որ ունէր՝ իր ամբողջ ապրուստը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Երբ նա տաճարից դուրս էր գալիս, իր աշակերտներից մէկը նրան ասաց. «Վարդապե՛տ, տե՛ս ինչպիսի՜ քարեր են սրանք, եւ ինչպիսի՜ շինուածք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Յիսուս նրան պատասխան տուեց եւ ասաց. «Տեսնո՞ւմ ես այդ բոլոր շինութիւնները. ճշմարիտ եմ ասում ձեզ, որ դրանց քարը քարի վրայ չպիտի թողնուի, որ չքանդուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Եւ մինչ նստած էր նա Ձիթենեաց լերան վրայ, տաճարի դիմաց, Պետրոսն ու Յակոբոսը եւ Յովհաննէսն ու Անդրէասը, առանձին, հարցրին նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '«Ասա՛ մեզ, ե՞րբ պիտի լինի այդ, եւ ի՞նչ կը լինի նշանը, երբ կատարուելու լինի այդ բոլորը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Զգո՛յշ կացէք, ոչ ոք ձեզ չխաբի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'որովհետեւ շատեր պիտի գան իմ անունով եւ պիտի ասեն՝ ե՛ս եմ Քրիստոսը, եւ շատերին պիտի մոլորեցնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Սակայն երբ լսէք պատերազմների ձայներ կամ պատերազմների լուրեր, չխռովուէք, որովհետեւ այդ պէտք է որ լինի, բայց դեռ աշխարհի վախճանը չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Ազգ ազգի դէմ պիտի ելնի եւ թագաւորութիւն՝ թագաւորութեան դէմ, եւ տեղ-տեղ երկրաշարժներ պիտի լինեն, սով եւ համաճարակ ու խռովութիւններ. բայց այդ բոլորը սկիզբն է երկանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Եւ դեռ ձեզ էլ պիտի մատնեն ատեանների, եւ ժողովարանների մէջ պիտի տանջուէք. եւ ինձ համար կուսակալների ու թագաւորների առաջ պիտի կանգնէք՝ ի վկայութիւն նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Բայց նախ պէտք է, որ Աւետարանը քարոզուի բոլոր հեթանոսների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Եւ երբ ձեզ տանեն յանձնելու, առաջուց հոգ մի՛ արէք եւ մի՛ մտածէք, թէ ինչ պիտի խօսէք, այլ, ինչ որ ձեզ տրուի այդ նոյն ժամին, ա՛յն խօսեցէք, որովհետեւ դո՛ւք չէ, որ պիտի խօսէք, այլ՝ Սուրբ Հոգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Եղբայրն իր եղբօրը մահուան պիտի մատնի, եւ հայրը՝ որդուն. եւ որդիները հայրերի դէմ պիտի ելնեն ու պիտի սպանեն նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Եւ իմ անուան համար բոլորից պիտի ատուէք. բայց ով որ մինչեւ վերջ համբերի, նա կը փրկուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, '«Եւ երբ տեսնէք սարսափելի պղծութիւնը՝ տեղ գտած այնտեղ, ուր չպէտք է լինէր (ով կարդում է, թող իմանայ), այն ժամանակ նրանք, որ Հրէաստանում են, լեռները թող փախչեն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'եւ ով տանիքի վրայ է, թող չիջնի եւ տուն չմտնի՝ այնտեղից բան վերցնելու.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'եւ ով արտի մէջ է, թող ետ չդառնայ՝ իր զգեստները վերցնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Բայց վա՜յ յղիներին եւ ստնտուներին այն օրերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Աղօթեցէ՛ք, որ ձմեռ ժամանակ չլինի դա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Այդ օրերը պիտի լինեն օրեր այնպիսի նեղութիւնների, որոնց նմանը չի եղել երբեք արարչագործութեան սկզբից մինչեւ այժմ եւ չի էլ լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Եւ եթէ Աստուած այդ օրերը իր ընտրեալների համար չկարճէր, ոչ մի մարդ չէր ազատուի. բայց նա իր ընտրեալների պատճառով, - որոնց ընտրեց, - կարճեց այդ օրերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Այն ժամանակ եթէ մէկը ձեզ ասի, թէ՝ «Ահա՛ այստեղ է Քրիստոսը կամ այնտեղ», չհաւատաք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'որովհետեւ սուտ քրիստոսներ եւ սուտ մարգարէներ պիտի ելնեն եւ նշաններ ու զարմանալի գործեր պիտի ցոյց տան՝ մոլորեցնելու նպատակով, եթէ հնար լինի, նոյնիսկ ընտրեալներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Բայց դուք զգո՛յշ եղէք. ահա առաջուց ձեզ ամէն ինչ ասացի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, '«Բայց այդ օրերին, այդ նեղութիւնից յետոյ, արեգակը պիտի խաւարի, եւ լուսինն իր լոյսը չպիտի տայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Եւ աստղերը երկնքից վայր պիտի թափուեն, եւ երկնքում զօրութիւնները պիտի շարժուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Եւ այն ժամանակ պիտի տեսնեն մարդու Որդուն՝ եկած ամպերի վրայով՝ զօրութեամբ եւ բազում փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Եւ այն ժամանակ պիտի ուղարկի իր հրեշտակներին ու պիտի հաւաքի իր ընտրեալներին չորս կողմերից, երկրի ծագերից մինչեւ երկնքի ծագերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, '«Բայց դուք այդ թզենո՛ւց սովորեցէք առակը. հէնց որ նրա ոստերը կակղեն, եւ նրա վրայ տերեւ դուրս գայ, իմանում էք, որ ամառը մօտ է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'նոյնպէս եւ դուք. երբ այս բոլորը կատարուած տեսնէք, իմացէ՛ք, որ նա մօտ է, դռների առջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Ճշմարիտ եմ ասում ձեզ, որ չի անցնի այս սերունդը, մինչեւ որ այս բոլորը կատարուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Երկինք ու երկիր կ՚անցնեն, բայց իմ խօսքերը չեն անցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, '«Սակայն այդ օրուայ եւ ժամի մասին ոչ ոք չգիտէ. ո՛չ հրեշտակները երկնքում եւ ո՛չ էլ՝ Որդին, այլ միայն՝ Հայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Զգո՛յշ եղէք, հսկեցէ՛ք ու աղօթեցէ՛ք, քանի որ չգիտէք, թէ ե՛րբ է ժամանակը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'ինչպէս հեռու երկիր գնացած մի մարդ, որ կը թողնի իր տունը եւ իր ծառաներին իշխանութիւն կը տայ եւ իւրաքանչիւրին՝ իր գործը, եւ դռնապանին կը պատուիրի, որ արթուն լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Արդ, արթո՛ւն կացէք, որովհետեւ չգիտէք, թէ տանտէրը ե՛րբ կը գայ՝ երեկոյեա՞ն, թէ՞ կէսգիշերին, աքլորականչի՞ն, թէ՞ առաւօտեան դէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Գուցէ յանկարծակի գալով՝ ձեզ քնի մէջ գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Բայց ինչ որ ձեզ եմ ասում, ամենքին եմ ասում՝ արթո՛ւն կացէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Եւ երկու օր յետոյ զատիկ էր ու Բաղարջակերաց տօնը. քահանայապետները եւ օրէնսգէտները հնար էին որոնում, թէ ինչպէս նրան նենգութեամբ բռնելով սպանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Բայց ասում էին. «Ո՛չ այս տօնին, որպէսզի ժողովրդի մէջ խռովութիւն չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Եւ մինչ նա Բեթանիայում էր, բորոտ Սիմոնի տանը սեղան նստած, եկաւ մի կին, որ հետն ունէր նարդոսի ազնիւ, մեծարժէք իւղի մի շիշ. եւ շիշը կոտրելով՝ իւղը թափեց Յիսուսի գլխին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Աշակերտները զայրացան եւ ասացին. «Այդ իւղը ինչո՞ւ այսպէս պիտի կորչէր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'կարելի էր այդ անուշահոտ իւղը վաճառել աւելի քան երեք հարիւր դահեկանի եւ տալ աղքատներին»: Եւ խիստ զայրանում էին կնոջ վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Եւ Յիսուս նրանց ասաց. «Թո՛յլ տուէք դրան. ինչո՞ւ էք նեղութիւն տալիս, որովհետեւ նա ինձ համար մի բարի գործ արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ամէն ժամ աղքատներին ձեզ հետ ունէք եւ երբ ուզենաք, կարող էք նրանց բարիք անել: Բայց ինձ ամէն ժամ ձեզ հետ չունէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Դա, ինչ որ կարող էր, արեց. առաջուց խնկաւետեց իմ մարմինը ի նշան պատանքուելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Ճշմարիտ եմ ասում ձեզ, ուր էլ քարոզուի այս Աւետարանը ամբողջ աշխարհում, ինչ որ նա արեց, այդ եւս պիտի պատմուի նրա յիշատակի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Եւ Յուդա Իսկարիովտացին՝ Տասներկուսից մէկը, գնաց քահանայապետների մօտ, որ Յիսուսին մատնի նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Երբ նրանք լսեցին, ուրախացան եւ խոստացան նրան դրամ տալ. եւ նա առիթ էր փնտռում, թէ ինչպէս յարմար ժամանակ մատնի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Եւ Բաղարջակերաց տօնի առաջին օրը, երբ զատկի գառն էին մորթում, աշակերտները նրան ասացին. «Ո՞ւր ես ուզում գնանք պատրաստենք, որ զատկական ընթրիքն ուտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Եւ նա աշակերտներից երկուսին ուղարկեց ու նրանց ասաց. «Գնացէ՛ք այն քաղաքը եւ երբ այն քաղաքը մտնէք, կը պատահի ձեզ մի մարդ, որ ուսին ջրի սափոր ունի. գնացէ՛ք նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Եւ նա ո՛ր տունը որ մտնի, տանտիրոջը կ՚ասէք. «Վարդապետն ասում է՝ ո՞ւր է այն իջեւանը, ուր իմ աշակերտների հետ զատկական ընթրիքը պիտի ուտեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Եւ նա ձեզ ցոյց կը տայ զարդարուած մի վերնատուն. այնտե՛ղ պատարաստեցէք մեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Եւ նրա աշակերտները գնացին պատրաստելու. եկան այն քաղաքը եւ գտան՝ ինչպէս որ նա իրենց ասել էր. ու զատկական ընթրիքը պատրաստեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Երբ երեկոյ եղաւ, նա եկաւ Տասներկուսի հետ միասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Եւ երբ սեղան նստեցին ու դեռ ուտում էին, Յիսուս ասաց. «Ճշմարիտ եմ ասում ձեզ, որ ձեզանից մէկը մատնելու է ինձ. նա, որ ինձ հետ իսկ ուտում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Եւ նրանք սկսեցին տրտմել ու ասել մէկը միւսի յետեւից՝ միթէ ե՞ս եմ. եւ միւսը՝ թէ՝ միթէ ե՞ս եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Նա պատասխան տուեց եւ ասաց. «Տասներկուսիցդ մէկը, որ ձեռքը ինձ հետ մտցրեց պնակի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Ճիշտ է, մարդու Որդին կը գնայ այս աշխարհից, ինչպէս որ նրա մասին գրուած է. բայց վա՜յ այն մարդուն, որի ձեռքով մարդու Որդին կը մատնուի. լաւ կը լինէր նրան, եթէ այդ մարդը ծնուած անգամ չլինէր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Եւ մինչ դեռ ուտում էին, Յիսուս հաց վերցնելով՝ օրհնեց եւ կտրեց, տուեց նրանց ու ասաց. «Առէ՛ք, ա՛յս է իմ մարմինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Եւ բաժակը վերցնելով՝ գոհութիւն յայտնեց, տուեց նրանց, եւ բոլորն էլ նրանից խմեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Եւ Յիսուս ասաց նրանց. «Ա՛յս է Նոր Ուխտի իմ արիւնը, որ կը թափուի շատերի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Ճշմարիտ եմ ասում ձեզ, որ այլեւս որթատունկի բերքից չեմ խմելու մինչեւ այն օրը, երբ կը խմեմ նոր գինին Աստծու արքայութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Եւ գոհութիւն մատուցելուց յետոյ ելան Ձիթենեաց լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Եւ Յիսուս նրանց ասաց. «Այս գիշեր ամէնքդ գայթակղուելու էք իմ պատճառով, որովհետեւ գրուած է. «Պիտի հարուածեմ հովուին, եւ ոչխարները պիտի ցրուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Բայց իմ յարութիւնից յետոյ ձեզնից առաջ Գալիլիա պիտի գնամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Պետրոսը պատասխանեց եւ ասաց նրան. «Թէկուզ բոլորն էլ գայթակղուեն, բայց ես չեմ գայթակղուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Եւ Յիսուս նրան ասաց. «Ճշմարիտ եմ ասում քեզ, որ դու այս գիշեր իսկ, դեռ աքաղաղը չկանչած, երեք անգամ պիտի ուրանաս ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Իսկ Պետրոսն առաւել եւս պնդում էր ու ասում. «Թէ քեզ հետ մեռնել իսկ հարկ լինի, քեզ չեմ ուրանայ»: Եւ ամէնքն էլ նոյնն էին ասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Եկան այն տեղը, որը Գեթսեմանի էր կոչւում: Եւ նա աշակերտներին ասաց. «Նստեցէ՛ք այստեղ, մինչեւ ես աղօթեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Եւ նա իր հետ վերցրեց Պետրոսին, Յակոբոսին եւ Յովհաննէսին եւ սկսեց տխրել ու տագնապել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Այն ժամանակ նրանց ասաց. «Տխուր է հոգիս մեռնելու աստիճան. մնացէ՛ք այստեղ եւ արթո՛ւն կացէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Եւ փոքր-ինչ առաջ գնալով՝ երեսի վրայ ընկաւ գետին. եւ աղօթում էր, որ, եթէ կարելի է, այդ ժամը իրենից հեռանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Եւ ասում էր. «Աբբա՛, Հա՛յր, ամէն ինչ քեզ կարելի է. այս բաժակը ինձնից հեռացրո՛ւ, բայց ոչ թէ ինչպէս ե՛ս եմ կամենում, այլ՝ ինչպէս դո՛ւ ես կամենում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Եւ Յիսուս եկաւ ու նրանց քնած գտաւ. եւ Պետրոսին ասաց. «Սիմո՛ն, ննջո՞ւմ ես. չկարողացա՞ր մէկ ժամ արթուն մնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Արթո՛ւն կացէք եւ աղօթեցէ՛ք, որպէսզի փորձութեան մէջ չընկնէք: Հոգին յօժար է, բայց մարմինը՝ տկար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Եւ նորից գնաց, աղօթքի կանգնեց ու նոյն բաներն ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Կրկին անգամ դարձաւ այնտեղ եւ նրանց քնի մէջ գտաւ. որովհետեւ նրանց աչքերը ծանրացել էին, եւ չէին իմանում, թէ ինչ պատասխան տան նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Երրորդ անգամ եկաւ եւ նրանց ասաց. «Քնեցէ՛ք այսուհետեւ եւ հանգստացէ՛ք, քանի որ վախճանը հասել. եկաւ ժամը, եւ ահա մարդու Որդին մատնւում է մեղաւորների ձեռքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Օ՛ն, վե՛ր կացէք գնանք, որովհետեւ ահա մօտեցաւ նա, ով ինձ մատնելու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Եւ մինչ նա դեռ խօսում էր այս բաները, եկաւ Յուդա Իսկարիովտացին՝ Տասներկուսից մէկը, եւ իր հետ՝ սրերով, մահակներով զինուած ամբոխ՝ ուղարկուած քահանայապետների, օրէնսգէտների ու ծերերի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Մատնիչը նրանց նշան էր տուել ասելով՝ ում հետ ես համբուրուեմ, նա՛ է, բռնեցէ՛ք նրան եւ տարէ՛ք զգուշութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Եւ մօտենալով նրան՝ իսկոյն ասաց. «Ռաբբի՛, Ռաբբի՛». եւ համբուրեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Եւ նրանք ձեռք դրեցին նրա վրայ ու բռնեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Ապա նրա շուրջը գտնուողներից մէկը սուրը քաշեց եւ զարկեց քահանայապետի ծառային ու նրա ականջը կտրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Յիսուս դարձաւ եւ ասաց նրանց. «Սրերով եւ մահակներով դուրս էք եկել ինձ բռնելու որպէս աւազակի՞:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Ես միշտ ձեզ մօտ էի եւ ուսուցանում էի տաճարում. եւ ինձ չբռնեցիք. բայց այս եղաւ, որպէսզի մարգարէների Գրուածքները կատարուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Այն ժամանակ աշակերտները բոլորն էլ լքեցին նրան եւ փախան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Եւ մի երիտասարդ գնում էր նրա յետեւից՝ իր մերկ մարմնի վրայ մի սաւան գցած: Երիտասարդները նրան բռնեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'եւ նա թողնելով հագի կտորը՝ մերկ փախաւ նրանցից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Եւ Յիսուսին տարան Կայիափա քահանայապետի մօտ. եւ նրա հետ հաւաքուած էին բոլոր քահանայապետները, օրէնսգէտներն ու ծերերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Իսկ Պետրոսը հեռուից նրա յետեւից գնաց մինչեւ ներս, քահանայապետի գաւիթը: Եւ նստած էր սպասաւորների մօտ ու տաքանում էր կրակի բոցի առջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Իսկ քահանայապետներն ու ամբողջ ատեանը մի որեւէ վկայութիւն էին փնտռում Յիսուսի դէմ, որպէսզի նրան սպանեն, բայց չէին գտնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'քանի որ նրա դէմ շատեր սուտ վկայութիւն էին տալիս, բայց վկայութիւնները իրար նման չէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Ոմանք վեր կենալով՝ սուտ էին վկայում նրա դէմ ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '«Մենք լսեցինք դրանից, երբ ասում էր. «Ես կը քանդեմ այս ձեռակերտ տաճարը եւ երեք օրում կը շինեմ մէկ ուրիշը՝ անձեռակերտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Բայց եւ այնպէս նրանց վկայութիւնը նոյնանման չէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Ապա քահանայապետը կանգնելով մէջտեղում՝ Յիսուսին հարց տուեց ու ասաց. «Ոչինչ չե՞ս պատասխանում. այդ ինչե՜ր են վկայում դրանք քո դէմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Եւ նա միայն լուռ էր մնում ու պատասխան չէր տալիս: Քահանայապետը կրկին անգամ հարցրեց նրան ու ասաց. «Դո՞ւ ես Քրիստոսը՝ օրհնեալ Աստծու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Յիսուս պատասխանեց եւ ասաց նրան. «Դու ասացիր, թէ ես եմ. բայց պիտի տեսնէք մարդու Որդուն՝ ամենազօր Աստծու աջ կողմում նստած եւ երկնքի ամպերի վրայով եկած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Եւ քահանայապետը իսկոյն պատռեց իր պատմուճանը եւ ասաց. «Էլ ի՞նչ պէտք են մեզ վկաներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Ահա ամէնքդ դրա բերանից լսեցիք հայհոյութիւնը. ձեզ ինչպէ՞ս է թւում...»: Եւ ամէնքը դատապարտեցին նրան, թէ մահապարտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Եւ ոմանք սկսեցին թքել նրա երեսին, շորով գլուխը ծածկել, բռունցքով խփել ու ասել. «Մարգարէացի՛ր մեզ, Քրիստո՛սդ, այն ո՞վ է, որ քեզ խփեց»: Եւ սպասաւորները ապտակում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Եւ մինչ Պետրոսը դեռ ներքեւում, գաւթում էր, քահանայապետի մի աղախինը եկաւ եւ տեսաւ նրան տաքանալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Նայեց նրան ու ասաց. «Դու էլ Յիսուս Նազովրեցու հետ էիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Նա ուրացաւ եւ ասաց. «Չեմ ճանաչում նրան եւ չգիտեմ՝ ինչ ես ասում դու»: Եւ երբ նա դրսի գաւիթը ելաւ, աքաղաղը կանչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Աղախինը նորից տեսաւ նրան եւ սկսեց իր շուրջը գտնուողներին ասել. «Սա էլ նրանցից է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Եւ Պետրոսը դարձեալ ուրացաւ: Փոքր-ինչ յետոյ, նորից, նրանք, որ շուրջը կանգնել էին, ասացին Պետրոսին. «Իրօք, դու էլ նրանցից ես, քանի որ գալիլիացի ես, եւ քո խօսուածքն էլ նման է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Եւ նա սկսեց նզովք կարդալ, երդուել եւ ասել. «Չեմ ճանաչում այն մարդուն, որի մասին դուք խօսում էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Եւ հէնց նոյն ժամին աքաղաղը երկրորդ անգամ կանչեց: Եւ Պետրոսը յիշեց այն խօսքը, որ Յիսուս ասել էր իրեն, թէ՝ «Աքաղաղը դեռ երկու անգամ չկանչած՝ դու երեք անգամ ինձ պիտի ուրանաս». եւ սկսեց լալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Եւ իսկոյն, վաղ առաւօտեան, ծերերի եւ օրէնսգէտների հետ միասին, քահանայապետները եւ ամբողջ ատեանը խորհուրդ անելով՝ կապեցին Յիսուսին եւ տարան յանձնեցին Պիղատոսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Պիղատոսը հարցրեց նրան եւ ասաց. «Դո՞ւ ես հրեաների թագաւորը»: Յիսուս պատասխան տուեց նրան եւ ասաց. «Դու ասում ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Եւ քահանայապետները նրան շատ էին ամբաստանում, բայց նա ոչինչ չէր պատասխանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Իսկ Պիղատոսը դարձեալ հարցրեց նրան. «Ոչ մի պատասխան չե՞ս տալիս. տե՛ս, ինչքա՜ն են քեզ ամբաստանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Եւ Յիսուս, այնուհետեւ, էլ ոչինչ չպատասխանեց, այնպէս որ Պիղատոսը շատ զարմացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Սակայն տօնի առիթով Պիղատոսը նրանց համար արձակում էր մի կալանաւոր, ում որ նրանք ուզում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Եւ Բարաբբա անունով մէկը կար՝ բանտարկուած այն խռովարարների հետ, որոնք խռովութեան ժամանակ մի մարդ էին սպանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Ամբոխն սկսեց բարձր ձայնով աղաղակել եւ պահանջել, որ, ինչպէս սովորութիւն էր անել, Բարաբբայի՛ն արձակի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Պիղատոսը պատասխանեց եւ ասաց նրանց. «Ուզո՞ւմ էք, որ հրեաների արքային արձակեմ ձեզ համար».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'քանի որ նա գիտէր, թէ նախանձի՛ց մատնեցին նրան քահանայապետները,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'որոնք եւ ամբոխին համոզեցին, որ Բարաբբայի՛ն արձակի իրենց համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Պիղատոսը դարձեալ խօսք առաւ եւ ասաց նրանց. «Իսկ ի՞նչ էք ուզում, որ անեմ հրեաների արքային»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Եւ նրանք, քահանայապետներից դրդուած, դարձեալ աղաղակեցին. «Խա՛չը հանիր դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Պիղատոսը նրանց ասաց. «Ի՞նչ չար բան է արել նա»: Եւ նրանք առաւել եւս աղաղակում էին ու ասում. «Խա՛չը հանիր դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Իսկ Պիղատոսը, որովհետեւ ուզեց ամբոխին գոհացնել, նրանց համար Բարաբբային արձակեց: Իսկ Յիսուսին ծեծել տալով՝ նրանց ձեռքը յանձնեց, որպէսզի խաչը հանուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Եւ զինուորները նրան ներսի գաւիթը տարան, ուր պալատի բակն էր. մէկտեղ կանչեցին ամբողջ գունդը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'եւ նրան հագցրին կարմիր քղամիդ եւ ծիրանի ու նրա գլխին փշերից պատրաստուած պսակ դրեցին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'եւ սկսեցին նրան ողջոյն տալ ու ասել. «Ողջո՜յն քեզ, հրեաների թագաւո՛րդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Եւ եղէգով հարուածում էին նրա գլխին, թքում էին երեսին ու ծնկի գալով՝ երկրպագում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Եւ նրան ծաղրուծանակի ենթարկելուց յետոյ, քղամիդն ու ծիրանին հանեցին եւ նրան իր զգեստները հագցրին ու դուրս տարան, որ խաչը հանեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Եւ ստիպեցին Սիմոն Կիւրենացուն՝ Ալեքսանդրի եւ Ռուփոսի հօրը, որը ագարակից էր գալիս ու այդ տեղով էր անցնում, որ Յիսուսի խաչափայտը կրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Եւ նրան տարան Գողգոթա, մի տեղ, որ թարգմանւում է կառափնատեղի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Զմուռսով խառնուած գինի տուին նրան, բայց նա չվերցրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Եւ նրան խաչը հանեցին: Եւ նրա հագուստները բաժանեցին՝ դրանց վրայ վիճակ գցելով, թէ ով ի՛նչ պիտի վերցնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Առաւօտեան ժամը ինն էր, երբ նրան խաչեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Եւ կար նրա դատապարտութեան մասին գրութիւն՝ գրուած այսպէս. «Հրեաների թագաւորն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Եւ նրա հետ խաչեցին երկու աւազակներ, մէկը՝ նրա աջում եւ միւսը՝ ձախում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Եւ կատարուեց գրուածը, թէ՝ «Անօրէնների հետ դասուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Եւ ովքեր անցնում էին, հայհոյում էին նրան, շարժում իրենց գլուխները եւ ասում. «Վա՛հ, որ քանդում էիր տաճարը եւ երեք օրում շինում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'ազատի՛ր ինքդ քեզ եւ իջի՛ր այդ խաչից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Նոյնպէս եւ քահանայապետները, իրենք իրենց մէջ, օրէնսգէտների հետ միասին, ծաղր էին անում ու ասում. «Ուրիշներին ազատեց, ինքն իրեն չի կարողանում ազատել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Այդ Քրիստոսը՝ Իսրայէլի այդ թագաւորը, թող այժմ իջնի խաչից, որպէսզի տեսնենք եւ հաւատանք դրան»: Եւ նրա հետ խաչուածներն էլ նախատում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Երբ կէսօր եղաւ, խաւար պատեց ամբողջ երկիրը, մինչեւ ժամը երեքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Եւ ժամը երեքին Յիսուս բարձրաձայն աղաղակեց եւ ասաց. «Էլի՜, Էլի՜, լա՞մա սաբաքթանի», որ թարգմանւում է՝ Աստուա՜ծ իմ, Աստուա՜ծ իմ, ինչո՞ւ թողեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Եւ նրանցից ոմանք, որ նրա շուրջն էին կանգնել, երբ լսեցին այդ, ասացին. «Եղիային է կանչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Եւ մէկը առաջ վազելով՝ սպունգը թաթախեց քացախի մէջ, անցկացրեց եղէգի ծայրին, տուեց նրան, որ խմի, ու ասաց. «Թողէ՛ք տեսնենք, արդեօք Եղիան կը գա՞յ նրան իջեցնելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Եւ Յիսուս բարձր ձայն արձակեց ու հոգին աւանդեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Եւ տաճարի վարագոյրը վերեւից մինչեւ ներքեւ երկուսի պատռուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Եւ այնտեղ կանգնած հարիւրապետը տեսնելով, թէ ինչպէս նա աղաղակեց եւ հոգին աւանդեց, ասաց. «Իրօք այս մարդը Աստծու Որդի էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Կային եւ կանայք, որոնք դիտում էին հեռուից: Նրանց մէջ էին Մարիամ Մագդաղենացին, Կրտսեր Յակոբոսի եւ Յովսէի մայրը՝ Մարիամը, ինչպէս եւ Սաղոմէն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'որոնք, երբ Յիսուս Գալիլիայում էր, նրա յետեւից էին գնում եւ ծառայում նրան. կային նաեւ շատ այլ կանայք, որոնք նրա հետ Երուսաղէմ էին ելել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Եւ երբ երեկոյ եղաւ, - քանի որ ուրբաթ էր, եւ շաբաթամուտն էր սկսւում, -');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'արիմաթիացի Յովսէփը, որ մի պարկեշտ մարդ էր ու հրեաների ժողովի անդամ եւ որ ինքն էլ Աստծու արքայութեանն էր սպասում, համարձակուեց մտնել Պիղատոսի մօտ եւ ուզեց Յիսուսի մարմինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Եւ Պիղատոսը զարմացաւ, որ Յիսուս այդչափ շուտ էր մեռել. եւ իր մօտ կանչելով հարիւրապետին՝ հարցրեց նրան ու ասաց. «Իրօք այդչափ շո՞ւտ մեռաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Երբ այդ ստուգեց հարիւրապետից, մարմինը շնորհեց Յովսէփին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Եւ Յովսէփը կտաւ գնեց ու նրան իջեցնելով՝ պատեց այդ կտաւով ու դրեց մի գերեզմանի մէջ, որ փորուած էր ժայռի մէջ: Եւ մի քար գլորեց գերեզմանի դռան առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Իսկ Մարիամ Մագդաղենացին եւ Յակոբոսի ու Յովսէի մայր Մարիամը տեսան այն տեղը, ուր նա դրուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Եւ երբ շաբաթն անցաւ, Մարիամ Մագդաղենացին, Յակոբոսի մայր Մարիամը եւ Սաղոմէն գնացին խնկի պատրաստութիւն տեսան, որպէսզի գան եւ օծեն նրա մարմինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Եւ կիրակի օրը, առաւօտեան, արեւածագին եկան գերեզման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Եւ ասում էին միմեանց. «Քարը գերեզմանի դռնից մեզ համար ո՞վ պիտի գլորի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Եւ նայեցին ու տեսան, որ գերեզմանից քարը գլորուած էր. եւ այն շատ մեծ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Եւ ներս, գերեզման մտնելով՝ տեսան մի երիտասարդի, որ նստած էր աջ կողմը՝ սպիտակ պատմուճան հագած. եւ զարհուրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Եւ նա ասաց նրանց. «Մի՛ վախեցէք, դուք Յիսուսին էք փնտռում՝ խաչուած Նազովրեցուն. նա յարութիւն առաւ, այստեղ չէ: Ահաւասիկ այն տեղը, ուր նրան դրել էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Բայց գնացէք ասացէ՛ք նրա աշակերտներին եւ Պետրոսին, թէ՝ ահա նա ձեզնից առաջ գնում է Գալիլիա. այնտե՛ղ կը տեսնէք նրան, ինչպէս ձեզ ասել էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Եւ երբ այս լսեցին, ելան ու փախան գերեզմանից, քանի որ սարսափահար էին եղել. եւ ոչ ոքի բան չասացին, որովհետեւ վախենում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Կիրակի առաւօտեան յարութիւն առած լինելով՝ Յիսուս նախ երեւաց Մարիամ Մագդաղենացուն, որից եօթը դեւ էր հանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Եւ սա գնաց ու պատմեց նրանց, որ Յիսուսի հետ էին եւ դեռեւս սգում ու լաց էին լինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Երբ նրանք լսեցին, թէ նա կենդանի է եւ երեւացել է Մարիամին, չհաւատացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Յետոյ Յիսուս այլ կերպարանքով երեւաց նրանց, որոնք հանդ էին գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Սրանք էլ եկան ու պատմեցին ուրիշների. բայց նրանք էլ չհաւատացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Յետոյ, մինչ Տասնմէկը սեղան էին նստել, Յիսուս նրանց երեւաց եւ յանդիմանեց նրանց իրենց անհաւատութեան եւ խստասրտութեան համար, որովհետեւ չէին հաւատացել նրանց, որոնց ինքը երեւացել էր՝ մեռելներից յարութիւն առած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Եւ նրանց ասաց. «Գնացէ՛ք ամբողջ աշխարհով մէկ եւ քարոզեցէ՛ք Աւետարանը բոլոր մարդկանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Ով հաւատայ եւ մկրտուի, պիտի փրկուի, եւ ով չհաւատայ, պիտի դատապարտուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Սրանք են նշանները, որոնք պիտի ուղեկցեն նրանց, որոնք հաւատում են. իմ անունով դեւեր պիտի հանեն, լեզուներ պիտի խօսեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'իրենց ձեռքերին օձեր պիտի բռնեն, եւ եթէ մահացու թոյն խմեն, դա նրանց չպիտի վնասի. հիւանդների վրայ ձեռք պիտի դնեն եւ բժշկեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Եւ ինքը Տէր Յիսուս, նրանց հետ խօսելուց յետոյ, դէպի երկինք վերացաւ եւ նստեց Հօր աջ կողմը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Իսկ նրանք ելան ու քարոզեցին Աւետարանը ամբողջ աշխարհում՝ Տիրոջ գործակցութեամբ. եւ իրենց ուղեկցող բոլոր նշաններով հաստատում էին Խօսքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Քանի որ շատերը ձեռնարկեցին շարադրել մեզանում կատարուած դէպքերի պատմութիւնը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'ինչպէս մեզ աւանդեցին նրանք, որ սկզբից Խօսքի ականատեսներն ու սպասաւորները եղան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'ես էլ, որ սկզբից ստուգութեամբ հետամուտ էի եղել ամէն բանի, կամեցայ կարգով քեզ գրել, ո՛վ գերազանցդ Թէոփիլէ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'որպէսզի ճանաչես ճշմարտութիւնն այն խօսքերի, որոնց աշակերտեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Հրէաստանի Հերովդէս թագաւորի օրով, Աբիայի քահանայական ընտանիքից Զաքարիա անունով մի քահանայ կար, որի կինը Ահարոնի դստրերից էր. նրա անունը Եղիսաբեթ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Եւ երկուսն էլ Աստծու առաջ արդար էին ու անարատ կերպով ընթանում էին Տիրոջ բոլոր պատուիրանների եւ օրէնքների ճանապարհով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Նրանք որդի չունէին, որովհետեւ Եղիսաբեթը ամուլ էր, եւ երկուսն էլ իրենց առաջացած տարիքում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Եւ մինչ Զաքարիան Աստծու առջեւ իր քահանայական պաշտօնն էր կատարում, իր կարգի օրերը հասած լինելով՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'ըստ քահանայութեան օրէնքի նրան վիճակուեց մտնել Տիրոջ տաճարը եւ խնկարկել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Եւ խնկարկութեան ժամին ժողովրդի ամբողջ բազմութիւնը դրսում աղօթքի էր կանգնած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Եւ Տիրոջ հրեշտակը երեւաց նրան՝ խնկերի սեղանի աջ կողմում կանգնած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Երբ Զաքարիան նրան տեսաւ, խռովուեց, եւ վախ ընկաւ նրա մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Տիրոջ հրեշտակը նրան ասաց. «Մի՛ վախեցիր, Զաքարիա՛, որովհետեւ քո աղօթքը լսելի եղաւ. քո կինը՝ Եղիսաբեթը, մի որդի կը ծնի քեզ, եւ նրա անունը Յովհաննէս կը դնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Նա քեզ համար ուրախութիւն եւ ցնծութիւն կը լինի, եւ շատերը կ՚ուրախանան իր ծննդով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'որովհետեւ նա Տիրոջ առաջ մեծ կը լինի, գինի եւ օղի չի խմի եւ մօր որովայնից սկսած Սուրբ Հոգով կը լցուի');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'եւ Իսրայէլի որդիներից շատերին կը դարձնի դէպի իրենց Տէր Աստուածը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Նա Եղիայի հոգով եւ զօրութեամբ պիտի գնայ նրա առաջից, որպէսզի հայրերի սրտերը որդիներին դարձնի ու անհնազանդներին՝ արդարների իմաստութեանը՝ Տիրոջ համար պատրաստ մի ժողովուրդ կազմելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Եւ Զաքարիան ասաց հրեշտակին. «Ես ի՞նչ կերպ կ՚իմանամ այդ, քանի որ ես ծեր եմ, եւ կինս էլ առաջացած տարիքում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Հրեշտակը նրան պատասխանեց եւ ասաց. «Ես Գաբրիէլն եմ, որ կանգնում եմ Աստծու առաջ. ես ուղարկուեցի խօսելու քեզ հետ եւ այդ բանը քեզ աւետելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Եւ ահա՛, դու համր կը լինես եւ չես կարողանայ խօսել մինչեւ այն օրը, երբ այդ կատարուի, քանի որ դու չհաւատացիր իմ խօսքերին, որ կ՚իրականան իրենց ժամանակին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Իսկ ժողովուրդը սպասում էր Զաքարիային. զարմանում էին, որ տաճարում նա ուշանում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Եւ երբ նա դուրս եկաւ, չէր կարողանում խօսել նրանց հետ: Եւ նրանք իմացան, թէ տաճարում տեսիլք էր տեսել. եւ նա նշանացի էր խօսում նրանց հետ ու մնում էր պապանձուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Եւ երբ պաշտամունքի իր օրերը լրացան, գնաց իր տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Այդ օրերից յետոյ նրա կինը՝ Եղիսաբեթը յղիացաւ: Հինգ ամիս նա թաքցնում էր ինքն իրեն եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '«Այս ի՛նչ բան արեց Տէրը ինձ իմ այս օրերին, երբ նայեց ինձ վրայ՝ վերացնելով իմ նախատինքը մարդկանց միջից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Վեցերորդ ամսին Գաբրիէլ հրեշտակը Աստծու կողմից ուղարկուեց Գալիլիայի մի քաղաքը, որի անունը Նազարէթ էր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'մի կոյսի մօտ, որ նշանուած էր Յովսէփ անունով մի մարդու հետ՝ Դաւթի տնից: Եւ այդ կոյսի անունը Մարիամ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Եւ հրեշտակը, գալով նրա մօտ, ասաց. «Ուրախացի՛ր, ո՛վ շնորհընկալ, Տէրը քեզ հետ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Իսկ նա այս խօսքերի վրայ խռովուեց եւ մտքում խորհում էր, թէ ինչ բան էր այս ողջոյնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Եւ հրեշտակը նրան ասաց. «Մի՛ վախեցիր, Մարիա՛մ, որովհետեւ Աստծուց դու շնորհ գտար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Եւ ահա՛ դու կը յղիանաս եւ կը ծնես մի որդի ու նրա անունը Յիսուս կը դնես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Նա մեծ կը լինի եւ Բարձրեալի որդի կը կոչուի: Եւ Տէր Աստուած նրան կը տայ նրա հօր՝ Դաւթի աթոռը, եւ նա յաւիտեան կը թագաւորի Յակոբի տան վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'ու նրա թագաւորութիւնը վախճան չի ունենայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Իսկ Մարիամը հրեշտակին ասաց. «Ինչպէ՞ս այդ կը պատահի ինձ, քանի որ ես տղամարդ չեմ ճանաչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Հրեշտակը պատասխանեց եւ նրան ասաց. «Սուրբ Հոգին կը գայ քո վրայ, եւ Բարձրեալի զօրութիւնը հովանի կը լինի քեզ, որովհետեւ նա, որ քեզնից է ծնուելու, սուրբ է եւ Աստծու որդի կը կոչուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Եւ ահա քո ազգական Եղիսաբեթը. նա եւս յղի է իր ծերութեան մէջ, եւ այս՝ յղիութեան վեցերորդ ամիսն է նրա, որ ամուլ էր կոչուած.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'որովհետեւ Աստծու համար անկարելի բան չկայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Եւ Մարիամն ասաց. «Ահաւասի՛կ ես մնում եմ Տիրոջ աղախինը, թող քո խօսքի համաձայն լինի ինձ»: Եւ հրեշտակը հեռացաւ նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Այդ օրերին Մարիամը վեր կացաւ եւ շտապով գնաց Յուդայի լեռնային շրջանի քաղաքներից մէկը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'մտաւ Զաքարիայի տունը ու Եղիսաբեթին ողջոյն տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Եւ երբ Եղիսաբեթը Մարիամի ողջոյնը լսեց, մանուկը խաղաց նրա որովայնում, եւ Եղիսաբեթը լցուեց Սուրբ Հոգով');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'եւ բարձր ձայնով աղաղակեց ու ասաց. «Օրհնեա՜լ ես դու կանանց մէջ, եւ օրհնեա՜լ է քո որովայնի պտուղը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Որտեղի՞ց ինձ այս ուրախութիւնը, որ իմ Տիրոջ մայրը ինձ մօտ գայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'որովհետեւ ահաւասիկ, երբ քո ողջոյնի ձայնը հասաւ իմ ականջին, մանուկը ցնծալով խաղաց իմ որովայնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Եւ երանի՜ նրան, որ կը հաւատայ, թէ Տիրոջ կողմից իրեն ասուածները կը կատարուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Եւ Մարիամն ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Մարիամը գրեթէ երեք ամիս մնաց Եղիսաբեթի մօտ եւ դարձաւ իր տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Եղիսաբեթի ծննդաբերելու ժամանակը լրացաւ, եւ նա մի որդի ծնեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'եւ նրա շուրջը գտնուողներն ու նրա ազգատոհմը լսեցին, որ Տէրն իր մեծ ողորմութիւնը ցոյց տուեց նրա հանդէպ, եւ ուրախանում էին նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Եւ ութերորդ օրը եկան մանկանը թլփատելու. եւ նրան իր հօր անունով Զաքարիա էին կոչում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Բայց նրա մայրը պատասխանեց եւ ասաց. «Ո՛չ, այլ Յովհաննէս պէտք է կոչուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Նրան ասացին. «Սակայն քո ազգատոհմի մէջ չկայ մէկը, որի անունը Յովհաննէս լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Նշանացի ակնարկեցին նրա հօրը, թէ ի՛նչ կը կամենայ նրան կոչել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Իսկ նա մի տախտակ ուզեց եւ վրան գրեց. «Դրա անունը Յովհաննէս է»: Եւ բոլորը զարմացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Եւ իսկոյն նրա բերանը բացուեց ու նրա լեզուն՝ նոյնպէս. եւ խօսում էր ու օրհնում Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Եւ ահ ընկաւ բոլորի մէջ, որ լսեցին այս, եւ նրանց մէջ, որ բնակւում էին նրանց շուրջը: Եւ Հրէաստանի ամբողջ լեռնակողմում այս բոլոր բաները պատմւում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Եւ բոլոր լսողները պահում էին իրենց սրտում այս ամէնը եւ ասում էին. «Արդեօք ի՞նչ կը լինի այս մանուկը»: Եւ Տիրոջ ձեռքը նրա հետ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Զաքարիան՝ նրա հայրը, Սուրբ Հոգով լցուեց, մարգարէացաւ եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Եւ մանուկը աճում ու զօրանում էր հոգով եւ մնում էր ամայի տեղերում՝ մինչեւ Իսրայէլում նրա երեւալու օրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, '');
