INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Այն օրերին Օգոստոս կայսեր կողմից հրաման ելաւ՝ ամբողջ երկրում մարդահամար անելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Այս առաջին մարդահամարը տեղի ունեցաւ, երբ Կիւրենիոսը կուսակալ էր Ասորիքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Եւ բոլորը գնում էին արձանագրուելու մարդահամարի՝ իւրաքանչիւրն իր քաղաքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Յովսէփն էլ Դաւթի տնից եւ ազգատոհմից լինելով՝ Գալիլիայի Նազարէթ քաղաքից ելաւ գնաց դէպի Հրէաստան՝ Դաւթի քաղաքը, որը Բեթղեհէմ է կոչւում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'մարդահամարի մէջ արձանագրուելու Մարիամի հետ, որ նրա հետ նշանուած էր եւ յղի էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Եւ երբ նրանք այնտեղ հասան, նրա ծննդաբերելու օրերը լրացան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'եւ նա ծնեց իր անդրանիկ որդուն, խանձարուրի մէջ փաթաթեց նրան ու դրեց մսուրի մէջ, որովհետեւ իջեւանում նրանց համար տեղ չկար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Եւ այդ շրջանում բացօթեայ բնակուող հովիւներ կային, որոնք իրենց հօտերի գիշերային պահպանութիւնն էին անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Եւ Տիրոջ հրեշտակը երեւաց նրանց, Տիրոջ փառքը ծագեց նրանց շուրջը, ու նրանք սաստիկ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Եւ հրեշտակը ասաց նրանց. «Մի՛ վախեցէք, որովհետեւ ահա ձեզ մեծ ուրախութիւն եմ աւետում, որը ամբողջ ժողովրդինը կը լինի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'որովհետեւ այսօր Դաւթի քաղաքում ձեզ համար ծնուեց մի Փրկիչ, որ օծեալ Տէրն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Եւ սա՛ ձեզ համար նշան կը լինի. խանձարուրով փաթաթած եւ մսուրի մէջ դրուած մի մանուկ կը գտնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Եւ յանկարծակի այդ հրեշտակի հետ երեւաց երկնային զօրքերի մի բազմութիւն, որ օրհնում էր Աստծուն ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '«Փա՜ռք Աստծուն՝ բարձունքներում, եւ երկրի վրայ խաղաղութի՜ւն եւ հաճութի՜ւն՝ մարդկանց մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Եւ երբ հրեշտակները նրանցից հեռանալով երկինք բարձրացան, հովիւներն ասացին միմեանց. «Եկէ՛ք գնանք մինչեւ Բեթղեհէմ եւ տեսնենք, թէ ի՛նչ բան է այս եղածը, որ Տէրը մեզ ցոյց տուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Եւ նրանք շտապով եկան ու գտան Մարիամին ու Յովսէփին եւ մսուրի մէջ դրուած մանկանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Եւ ճանաչեցին նրան այն խօսքից, որ իրենց ասուել էր մանկան մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Եւ բոլոր լսողները զարմանում էին այն բաների վրայ, որ հովիւները ասացին իրենց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Իսկ Մարիամը այս բոլոր ասուածները պահում էր իր մէջ եւ իր սրտում խորհում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Եւ հովիւները վերադարձան. փառաւորում եւ օրհնում էին Աստծուն այն ամենի համար, որ լսեցին ու տեսան, ինչպէս իրենց պատմուել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Եւ երբ ութ օրերը լրացան, եւ նա թլփատուեց, նրա անունը Յիսուս դրուեց, ինչպէս հրեշտակի կողմից կոչուել էր, երբ դեռ չէր յղացուել մօր որովայնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Երբոր նրանց սրբագործման օրերը լրացան, Մովսէսի Օրէնքի համաձայն՝ նրան Երուսաղէմ տարան՝ Տիրոջը ներկայացնելու համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'ինչպէս գրուած էր Տիրոջ Օրէնքում. «Ամէն արու զաւակ, որ արգանդ է բացում, Տիրոջ համար սուրբ պիտի կոչուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Եւ Տիրոջ Օրէնքում ասուածի համաձայն՝ ընծայ պէտք է տալ մի զոյգ տատրակ կամ աղաւնու երկու ձագ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Արդ, Երուսաղէմում Սիմէոն անունով մի մարդ կար, եւ այդ մարդը արդար ու աստուածավախ էր եւ ակնկալում էր Իսրայէլի մխիթարութիւնը. եւ Սուրբ Հոգին էր նրա մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Եւ Սուրբ Հոգուց հրամայուած էր իրեն մահ չտեսնել, մինչեւ որ տեսնէր Տիրոջ Օծեալին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Նա Հոգով առաջնորդուած՝ եկաւ տաճարը, եւ երբ ծնողները բերին Յիսուս մանկանը՝ նրա վրայ կատարելու ինչ որ օրէնքի սովորութեան համաձայն էր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Սիմէոնը նրան իր գիրկն առաւ, օրհնեց Աստծուն եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Եւ նրա հայրն ու մայրը զարմացած էին այն խօսքերի համար, որ ասում էին նրա մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Սիմէոնը նրանց օրհնեց եւ ասաց նրա մօրը՝ Մարիամին. «Ահա՛ սա նա է, որ պատճառ է դառնալու Իսրայէլի մէջ շատերի անկման ու բարձրացման եւ նշան՝ հակառակութեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Իսկ քո հոգու միջով էլ սուր պիտի անցնի, որպէսզի բազում սրտերի խորհուրդներ յայտնի դառնան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Եւ այնտեղ կար մի մարգարէուհի՝ Աննա անունով՝ Փանուէլի դուստրը, Ասերի ազգատոհմից. սա տարիքով շատ առաջացած էր եւ ամուսնու հետ միայն եօթը տարի էր ապրել՝ սկսած իր կուսութիւնից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Նա մօտ ութսունչորս տարեկան մի այրի էր, որ չէր հեռանում տաճարից, այլ ծոմապահութեամբ եւ աղօթքով գիշեր-ցերեկ ծառայում էր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Սա եւս նոյն ժամին վեր կացաւ եկաւ, գոհութիւն էր մատուցում Տիրոջը եւ խօսում էր մանկան մասին բոլոր նրանց հետ, որոնք Երուսաղէմի փրկութեանն էին սպասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'Եւ երբ ամէն ինչ կատարեցին Տիրոջ Օրէնքի համաձայն, վերադարձան Գալիլիա, իրենց քաղաքը՝ Նազարէթ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Եւ մանուկը աճում ու զօրանում էր՝ լի իմաստութեամբ. եւ Աստծու շնորհները նրա վրայ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'Արդ, նրա ծնողները ամէն տարի, Զատկի տօնին, Երուսաղէմ էին գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Եւ երբ նա տասներկու տարեկան եղաւ, տօնի սովորութեան համաձայն՝ Երուսաղէմ ելան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Եւ երբ տօնական օրերը լրացան, ու նրանք վերադարձան, մանուկ Յիսուսը մնաց Երուսաղէմում, եւ նրա ծնողները այդ չիմացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Կարծում էին, թէ նա իրենց ուղեկիցների հետ է. մի օրուայ չափ ճանապարհ եկան եւ նրան փնտռեցին ազգականների ու ծանօթների մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Ու երբ չգտան, Երուսաղէմ վերադարձան՝ նրան փնտռելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Եւ երեք օր յետոյ նրան գտան տաճարում. վարդապետների հետ նստած՝ նա լսում էր նրանց եւ հարցեր էր տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Եւ բոլորը, որ նրան լսում էին, զարմանում էին նրա իմաստութեան եւ պատասխանների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Երբ ծնողները նրան տեսան, հիացան. իսկ մայրը նրան ասաց. «Որդի՛, այս ի՞նչ արեցիր դու մեզ. ահաւասիկ հայրդ ու ես տագնապած քեզ էինք փնտռում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Եւ նա պատասխանեց նրանց. «Ինչո՞ւ էիք ինձ փնտռում, չգիտէի՞ք, թէ ես Հօրս տանը պէտք է լինեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Բայց նրանք չհասկացան այն խօսքը, որ նա իրենց ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Եւ Յիսուս նրանց հետ իջաւ ու Նազարէթ գնաց. եւ նա հնազանդ էր նրանց: Եւ նրա մայրը այս բոլոր բաները պահում էր իր սրտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Իսկ Յիսուս զարգանում էր իմաստութեամբ, հասակով եւ շնորհով Աստծու ու մարդկանց առջեւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Տիբերիոս կայսեր իշխանութեան տասնհինգերորդ տարում, երբ Պոնտացի Պիղատոսը կուսակալ էր Հրէաստանի, եւ Հերովդէսը՝ չորրորդապետ Գալիլիայի, եւ նրա եղբայր Փիլիպպոսը՝ չորրորդապետ Իտուրացիների ու Տրաքոնացիների աշխարհի, Լիւսանիասը՝ չորրորդապետ Աբիլենէի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'եւ Աննայի ու Կայիափայի քահանայապետութեան օրով, Աստծու խօսքը լսելի եղաւ Զաքարիայի որդի Յովհաննէսին անապատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Եւ նա եկաւ Յորդանանի կողմը ապաշխարութեան մկրտութիւն քարոզելու՝ մեղքերի թողութեան համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'ինչպէս գրուած է Եսայի մարգարէի պատգամների գրքում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Եւ այն ժողովրդին, որ եկել էր իրենից մկրտուելու, ասում էր. «Իժերի՛ ծնունդներ, ո՞վ ձեզ սովորեցրեց փախչել բարկութիւնից, որ գալու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Այսուհետեւ ապաշխարութեան արժանի պտուղներ տուէ՛ք եւ մի՛ սկսէք ասել, թէ Աբրահամին ունենք իբրեւ հայր. այս ասեմ ձեզ, որ Աստուած կարող է այս քարերից անգամ դուրս բերել Աբրահամի որդիներ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Բայց ահաւասիկ կացինը ծառերի արմատի վրայ է. ամէն ծառ, որ բարի պտուղ չի տալիս, կտրւում եւ կրակն է նետւում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Ժողովուրդը նրան հարցնում էր եւ ասում. «Իսկ արդ, ի՞նչ պիտի անենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Նա պատասխանեց նրանց եւ ասաց. «Ով որ երկու զգեստ ունի, մէկը թող տայ նրան, որ չունի, եւ ով որ ուտելիք ունի, նոյն ձեւով թող անի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Մաքսաւորներն էլ եկան մկրտուելու եւ հարցրին նրան. «Վարդապե՛տ, մե՛նք ինչ անենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Նա ասաց նրանց. «Ձեզ հրամայուածներից աւելին մի՛ վերցրէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Զինուորները նոյնպէս հարցնում էին նրան. «Իսկ մե՛նք ինչ անենք»: Նա ասաց նրանց. «Ոչ ոքի մի՛ նեղէք, ոչ ոքի մի՛ զրպարտէք, ձեր ռոճիկը թող ձեզ բաւարար լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Ժողովուրդը սպասման մէջ էր, եւ բոլորն իրենց սրտում Յովհաննէսի մասին հարց էին տալիս, թէ՝ միթէ սա՞ է Քրիստոսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Նա պատասխանեց բոլորին ու ասաց. «Ես ձեզ մկրտում եմ ջրով, բայց գալիս է ինձնից աւելի զօրաւորը, որի կօշիկները հանելու արժանի չեմ ես. նա ձեզ կը մկրտի Սուրբ Հոգով եւ հրով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'նրա քամհարը իր ձեռքում է՝ մաքրելու իր կալը, հաւաքելու ցորենը իր շտեմարանում, իսկ յարդը կ՚այրի անշէջ կրակով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Նա շատ ուրիշ մխիթարիչ խօսքերով բարի լուրն էր աւետում ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Բայց Հերովդէս չորրորդապետը, յանդիմանուած լինելով Յովհաննէսի կողմից, իր եղբօր կնոջ՝ Հերովդիայի պատճառով եւ այն բոլոր չարիքների համար, որ Հերովդէսը գործել էր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'այդ բոլորի վրայ աւելացրեց եւ այն, որ Յովհաննէսին բանտարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Եւ ամբողջ ժողովրդի մկրտուելուց յետոյ, Յիսուս եւս մկրտուեց ու երբ աղօթքի կանգնեց, երկինքը բացուեց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'եւ Սուրբ Հոգին մարմնաւոր տեսքով, որպէս աղաւնի իջաւ նրա վրայ. եւ երկնքից ձայն եկաւ, որ ասում էր. «Դո՛ւ ես իմ սիրելի Որդին, որ ունես իմ ամբողջ բարեհաճութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Եւ ինքը Յիսուս շուրջ երեսուն տարեկան էր, երբ սկսեց իր գործունէութիւնը: Եւ, ինչպէս կարծում էին, որդին էր Յովսէփի, եւ սա՝ Յակոբի, եւ սա՝ Հեղիի, եւ սա՝ Մատաթէի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'եւ սա՝ Ղեւիի, եւ սա՝ Մեղքիի, եւ սա՝ Յաննէի, եւ սա՝ Յովսէփի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'եւ սա՝ Մատթէի, եւ սա՝ Ամոսի, եւ սա՝ Նաւումի, եւ սա՝ Էսղիի, եւ սա՝ Նանգէի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'եւ սա՝ Մաաթի, եւ սա՝ Մատաթէի, եւ սա՝ Սեմէիի, եւ սա՝ Յոսէքէի, եւ սա՝ Յոդայի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'եւ սա՝ Յովնանէի, եւ սա՝ Րէսայի, եւ սա՝ Զորոբաբէլի, եւ սա՝ Սաղաթիէլի, եւ սա՝ Ներիի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'եւ սա՝ Մեղքիի, եւ սա՝ Ադդէի, եւ սա՝ Կոսամի, եւ սա՝ Ելմոդադի, եւ սա՝ Երէի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'եւ սա՝ Յեսուի, եւ սա՝ Եղիազարի, եւ սա՝ Յորամի, եւ սա՝ Մատթէի, եւ սա՝ Ղեւիի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'եւ սա՝ Սիմէոնի, եւ սա՝ Յուդայի, եւ սա՝ Յովսէփի, եւ սա՝ Յովնամի, եւ սա՝ Եղիակիմի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'եւ սա՝ Մելլէի, եւ սա՝ Մեննէի, եւ սա՝ Մատտաթայի, եւ սա՝ Նաթանի, եւ սա՝ Դաւթի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'եւ սա՝ Յեսսէի, եւ սա՝ Օբէդի, եւ սա՝ Բոոսի, եւ սա՝ Սաղմանի, եւ սա՝ Նաասոնի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'եւ սա՝ Ամինադաբի, եւ սա՝ Արամի, եւ սա՝ Ադմէի, եւ սա՝ Առնէի, եւ սա՝ Եսրոնի, եւ սա՝ Փարէսի, եւ սա՝ Յուդայի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'եւ սա՝ Յակոբի, եւ սա՝ Իսահակի, եւ սա, Աբրահամի, եւ սա՝ Թարայի, եւ սա՝ Նաքորի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'եւ սա՝ Սերուգի, եւ սա՝ Ռագաւի, եւ սա՝ Փաղեկի, եւ սա՝ Եբերի, եւ սա՝ Սաղայի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'եւ սա՝ Կայնանի, եւ սա՝ Արփաքսադի, եւ սա՝ Սէմի, եւ սա՝ Նոյի, եւ սա՝ Ղամէքի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'եւ սա՝ Մաթուսաղայի, եւ սա՝ Ենոքի, եւ սա՝ Յարեդի, եւ սա՝ Մաղաղայէլի, եւ սա՝ Կայնանի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'եւ սա՝ Ենոսի, եւ սա՝ Սէթի, եւ սա՝ Ադամի, եւ սա՝ Աստծու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Եւ Յիսուս Սուրբ Հոգով լի վերադարձաւ Յորդանանից. եւ Հոգով անապատ առաջնորդուեց');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'ու քառասուն օր փորձուեց սատանայից: Չկերաւ եւ չխմեց այն օրերին. եւ երբ քառասուն օրերը լրացան, քաղց զգաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Եւ սատանան նրան ասաց. «Եթէ Աստծու Որդի ես, այդ քարին ասա՛, որ հաց լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Յիսուս նրան պատասխանեց եւ ասաց. «Գրուած է. «Միայն հացով չէ, որ կ՚ապրի մարդ, այլ՝ Աստծու ամէն խօսքով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Եւ սատանան տանելով նրան մի բարձր լեռ, մի վայրկեանում նրան ցոյց տուեց աշխարհի բոլոր թագաւորութիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Եւ սատանան նրան ասաց. «Քեզ կը տամ այս ամբողջ իշխանութիւնը եւ սրանց փառքը, որովհետեւ ինձ է տրուած, եւ ում որ կամենամ, կը տամ այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Արդ, եթէ դու իմ առաջ ընկած երկրպագես, բոլորը քոնը կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Յիսուս պատասխանեց նրան եւ ասաց. «Գրուած է. «Քո Տէր Աստծո՛ւն պիտի երկրպագես եւ նրա՛ն միայն պիտի պաշտես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Եւ տարաւ նրան Երուսաղէմ, կանգնեցրեց տաճարի աշտարակի վրայ ու ասաց նրան. «Եթէ Աստծու Որդի ես, քեզ այստեղից ցա՛ծ գցիր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'որովհետեւ գրուած է. «Իր հրեշտակներին պատուիրուած է քո մասին, որ քեզ պահեն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'եւ իրենց ձեռքերի վրայ կը բռնեն քեզ, որ քո ոտքը երբեք քարին չխփես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Յիսուս պատասխանեց նրան եւ ասաց. «Ասուած է. «Քո Տէր Աստծուն պիտի չփորձես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Եւ սատանան կատարած լինելով բոլոր փորձութիւնները՝ նրանից միառժամանակ հեռու մնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Եւ Յիսուս Հոգու զօրութեամբ վերադարձաւ Գալիլիա, ու գաւառի բոլոր կողմերում նրա համբաւը տարածուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Եւ նա ուսուցանում էր նրանց ժողովարաններում՝ փառաւորուելով բոլորից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Եւ եկաւ Նազարէթ, ուր նա սնուել մեծացել էր. եւ ըստ իր սովորութեան՝ շաբաթ օրը ժողովարան մտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Եւ նրան տուին Եսայի մարգարէի գիրքը. եւ նա վեր կացաւ ընթերցելու. եւ երբ գիրքը բացեց, գտաւ այն տեղը, ուր գրուած էր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '«Տիրոջ Հոգին իմ վրայ է, դրա համար իսկ օծեց ինձ, ինձ ուղարկեց աղքատներին աւետարանելու, սրտով բեկեալներին բժշկելու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'գերիներին ազատում քարոզելու եւ կոյրերին՝ տեսողութիւն, կեղեքուածներին ազատ արձակելու, Տիրոջը ընդունելի տարին հռչակելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Եւ փակելով գիրքը՝ տուեց պաշտօնեային ու նստեց. եւ ժողովարանում գտնուողների բոլորի աչքերը նրա վրայ էին սեւեռուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Սկսեց ասել նրանց. «Այսօր այս գրուածքները կատարուեցին, երբ լսում էիք ձեր ականջներով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Եւ բոլորը վկայում էին ու զարմանում նրա բերանից ելած շնորհալի խօսքերի վրայ ու ասում. «Սա Յովսէփի որդին չէ՞»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Եւ նա ասաց նրանց. «Անշուշտ, ինձ այս առածը կ՚ասէք. «Բժի՛շկ, բժշկի՛ր ինքդ քեզ»: Այն ամէնը, ինչ արել ես Կափառնայումում, որչափ որ լսեցինք, արա՛ եւ այստեղ, քո գաւառում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Եւ նա ասաց. «Ճշմարիտ եմ ասում ձեզ, որ մարգարէն ընդունելի չէ իր քաղաքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Արդարեւ, ասում եմ ձեզ, որ Եղիայի օրով Իսրայէլում բազում այրիներ կային, երբ երկինքը փակուեց երեք տարի ու վեց ամիս, եւ ամբողջ երկրի վրայ մեծ սով եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Սակայն նրանցից ոչ մէկի մօտ Եղիան չուղարկուեց, այլ միայն՝ մի այրի կնոջ՝ սիդոնացիների Սարեփթա քաղաքում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Նաեւ՝ Իսրայէլում Եղիսէ մարգարէի օրով բազում բորոտներ կային, եւ սակայն նրանցից ոչ մէկը չմաքրուեց, այլ միայն՝ Նէեման ասորին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Երբ այս լսեցին, ժողովարանում բոլորը լցուեցին բարկութեամբ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'եւ վեր կենալով՝ նրան քաղաքից դուրս հանեցին ու տարան մինչեւ դարաւանդը այն լերան, որի վրայ շինուած էր իրենց քաղաքը, որպէսզի նրան գահավէժ անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Իսկ նա, անցնելով նրանց միջով, գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Եւ իջաւ Գալիլիայի Կափառնայում քաղաքը ու շաբաթ օրերը ուսուցանում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Նրա ուսուցման վրայ զարմանում էին, որովհետեւ նրա խօսքը լի էր հեղինակութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Եւ ժողովարանում մի մարդ կար, որին բռնել էր մի պիղծ դեւի չար ոգին. սա բարձր ձայնով աղաղակեց եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '«Թո՛ղ տուր մեզ, Յիսո՛ւս Նազովրեցի, ի՞նչ ես ուզում մեզնից. մեզ կորստեան մատնելո՞ւ եկար. գիտենք, թէ ով ես, Աստծու Սուրբն ես դու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Յիսուս սաստեց նրան եւ ասաց. «Պապանձուի՛ր եւ դո՛ւրս ելիր դրանից»: Դեւը մէջտեղում գետին զարկեց նրան եւ դուրս ելաւ նրանից ու որեւէ վնաս չտուեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Եւ բոլորին զարմանք պատեց. իրար հետ խօսում էին ու ասում. «Ի՜նչ խօսք է այս, որ իշխանութեամբ եւ զօրութեամբ սաստում է պիղծ ոգիներին, եւ դրանք դուրս են գալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Եւ նրա հռչակը տարածւում էր գաւառի շրջակայքի բոլոր տեղերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Եւ նա ժողովարանից դուրս գալով՝ մտաւ Սիմոնի տունը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Սիմոնի զոքանչը բարձր ջերմութեան մէջ տառապում էր: Նրա համար Յիսուսին աղաչեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Նա կանգնեց նրա մօտ, սաստեց ջերմին, եւ ջերմը թողեց նրան: Հիւանդը անմիջապէս ոտքի ելաւ եւ սպասարկում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Եւ երբ արեւը մայր էր մտնում, բոլոր նրանք, որոնք պէսպէս ցաւերով հիւանդներ ունէին, նրա մօտ էին բերում նրանց. եւ նա նրանցից իւրաքանչիւրի վրայ ձեռք էր դնում ու նրանց բժշկում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Շատերի միջից դեւեր էլ էին ելնում, աղաղակում եւ ասում. «Դո՛ւ ես Աստծու Որդին»: Եւ նա սաստում էր ու թոյլ չէր տալիս նրանց խօսել. որովհետեւ գիտէին, թէ նա Քրիստոսն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Եւ երբ օրը լուսացաւ, նա ելաւ գնաց մի ամայի տեղ, իսկ ժողովուրդը փնտռում էր նրան. եկան մինչեւ նրա մօտ եւ չէին թողնում նրան, որ հեռանայ իրենցից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Եւ նա նրանց ասաց. «Աստծու արքայութիւնը ես ուրիշ քաղաքների էլ պիտի աւետարանեմ, որովհետեւ դրա համար իսկ ուղարկուեցի»: Եւ նա քարոզում էր գալիլիացիների ժողովարաններում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Եւ մինչ ժողովուրդը խռնւում էր նրա շուրջը՝ լսելու Աստծու խօսքը, նա կանգնած էր Գեննեսարէթի ծովակի ափին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Եւ տեսաւ երկու նաւակներ, որ կանգնած էին ծովակի եզերքին. եւ ձկնորսները դրանց միջից դուրս եկած՝ ուռկաններն էին լուանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Նա մտաւ նաւակներից մէկի մէջ, որ Սիմոնինն էր, եւ խնդրեց նրան, որ ցամաքից փոքր-ինչ հեռացնի այն. նստեց ու նաւակի միջից ուսուցանում էր ժողովրդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Եւ երբ դադարեց խօսելուց, ասաց Սիմոնին. «Քշիր տա՛ր դէպի խորերը, եւ ձեր ուռկանները գցեցէ՛ք որսալու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Սիմոնը պատասխանեց եւ նրան ասաց. «Վարդապե՛տ, ամբողջ այս գիշեր չարչարուեցինք եւ ոչինչ չբռնեցինք, բայց քո խօսքի համար ուռկանները կը գցենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Երբ այդ արեցին, մեծ քանակութեամբ ձկներ բռնեցին, այն աստիճան, որ նրանց ուռկանները պատռւում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Նրանք նշան էին անում միւս նաւակի մէջ եղող իրենց որսակիցներին, որ գան իրենց օգնեն: Եւ նրանք եկան, եւ երկու նաւակներն էլ լցուեցին սուզուելու աստիճան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Երբ Սիմոն Պետրոսն այս տեսաւ, Յիսուսի ծնկներին ընկաւ եւ ասաց. «Ինձնից հեռո՛ւ գնա, Տէ՛ր, որովհետեւ ես մեղաւոր մարդ եմ».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'քանի որ վախը պատել էր նրան եւ բոլորին, որ նրա հետ էին, իրենց բռնած ձկների քանակի պատճառով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'նոյնպէս եւ՝ Զեբեդէոսի որդիներին՝ Յակոբոսին եւ Յովհաննէսին, որոնք Սիմոնի որսակիցներն էին. եւ Յիսուս Սիմոնին ասաց. «Մի՛ վախեցիր, այսուհետեւ դու մարդկա՛նց պիտի որսաս կեանքի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Եւ նաւակը ցամաք հանելով՝ թողեցին ամէն ինչ ու նրան հետեւեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Եւ երբ նա հասաւ քաղաքներից մէկը, բորոտութեամբ պատած մի մարդ, Յիսուսին տեսնելով, երեսի վրայ ընկած՝ աղաչեց նրան եւ ասաց. «Տէ՛ր, եթէ կամենաս, կարո՛ղ ես ինձ մաքրել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Նա մեկնեց իր ձեռքը, դիպաւ նրան եւ ասաց. «Կամենում եմ, մաքրուի՛ր»: Եւ իսկոյն բորոտութիւնը գնաց նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Յիսուս պատուիրեց նրան ոչ ոքի չասել, այլ՝ «Գնա՛, - ասաց, - դու քեզ ցո՛յց տուր քահանային եւ ընծայ տուր քո մաքրուելու համար, ինչպէս որ հրամայել էր Մովսէսը՝ ի վկայութիւն նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Եւ նրա համբաւը աւելի ու աւելի էր տարածւում. եւ բազում ժողովուրդ էր հաւաքւում լսելու նրան ու իրենց հիւանդութիւնից բժշկուելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Իսկ նա խոյս էր տալիս դէպի ամայի տեղեր եւ աղօթքի էր կանգնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Մի օր ինքն ուսուցանում էր, իսկ փարիսեցիներն ու օրէնքի վարդապետները, որոնք հաւաքուել էին Գալիլիայի եւ Հրէաստանի բոլոր քաղաքներից ու Երուսաղէմից, նստած էին. եւ Տիրոջ զօրութիւնը նրա հետ էր ու նրա միջոցով բժշկում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Եւ ահա մարդիկ մահիճով մի մարդ բերեցին, որ անդամալոյծ էր, եւ ուզում էին նրան ներս մտցնել ու դնել նրա առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Եւ երբ ամբոխի պատճառով նրան ներս մտցնելու միջոց չգտան, բարձրացան տանիք եւ կտուրի բացուածքից նրան վար կախեցին ու մահիճով հանդերձ իջեցրին մէջտեղ, Յիսուսի առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Տեսնելով նրանց հաւատը՝ Յիսուս ասաց նրան. «Ո՛վ մարդ, թող քո մեղքերը քեզ ներուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Օրէնսգէտներն ու փարիսեցիները սկսեցին խորհել եւ ասացին. «Ո՞վ է սա, որ հայհոյանքներ է ասում. ո՞վ կարող է ներել մեղքերը, եթէ ոչ՝ Աստուած միայն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Յիսուս, գիտենալով նրանց մտածումները, պատասխանեց նրանց եւ ասաց. «Ի՞նչ էք մտմտում ձեր սրտերում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'ո՞րն է աւելի հեշտ, ասել՝ քեզ ներուած լինեն քո մեղքե՞րը, թէ՞ ասել՝ վե՛ր կաց եւ քայլի՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Բայց որպէսզի իմանաք, թէ մարդու Որդին իշխանութիւն ունի երկրի վրայ մեղքերը ներելու (ասաց անդամալոյծին)՝ քե՛զ եմ ասում, վե՛ր կաց, վերցրո՛ւ քո մահիճը եւ գնա՛ քո տունը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Եւ իսկոյն բոլորի առաջ վեր կենալով՝ իր վրայ առաւ այն, ինչի վրայ ինքը պառկել էր, գնաց իր տունը եւ փառաւորում էր Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Բոլորին զարմանք պատեց, եւ փառաւորում էին Աստծուն: Ահով լցուեցին եւ ասում էին. «Այսօր արտասովոր բաներ տեսանք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Դրանից յետոյ, դուրս ելաւ այնտեղից եւ տեսաւ մի մաքսաւորի, որի անունը Ղեւի էր, եւ որը մաքսատանը նստած՝ գործի վրայ էր: Յիսուս նրան ասաց. «Իմ յետեւից արի՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Եւ նա թողնելով ամէն ինչ, վեր կացաւ գնաց նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Եւ Ղեւին իր տան մէջ նրան մեծ ընդունելութիւն տուեց, եւ մեծ թուով մաքսաւորներ եւ ուրիշներ նրանց հետ սեղան էին նստել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Փարիսեցիները եւ օրէնսգէտները տրտնջում էին Յիսուսի դէմ իր աշակերտների մօտ ու ասում. «Ինչո՞ւ էք մաքսաւորների եւ մեղաւորների հետ ուտում եւ խմում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Առողջներին բժիշկներ պէտք չեն, այլ՝ հիւանդներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Ես չեմ եկել արդարներին կանչելու, այլ՝ մեղաւորներին՝ ապաշխարութեան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Եւ նրանցից ոմանք ասացին նրան. «Ինչո՞ւ Յովհաննէսի, ինչպէս եւ փարիսեցիների աշակերտները ծոմ են պահում յաճախ եւ աղօթք անում, իսկ քո աշակերտները ուտում են ու խմում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Եւ նա ասաց նրանց. «Միթէ կարո՞ղ էք հարսանքաւորներին հրամայել, որ ծոմ պահեն, որքան ժամանակ որ փեսան նրանց հետ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Կը գան օրեր, երբ որ փեսան նրանցից կը վերցուի, ապա այդ օրերին ծոմ կը պահեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Եւ նրանց մի առակ էլ ասաց. «Ոչ ոք հնացած ձորձի վրայ նոր զգեստից կտոր չի դնի, ապա թէ ոչ՝ ե՛ւ նորը կը պատռուի, ե՛ւ նոր զգեստից վերցրած կտորը չի յարմարուի հնի հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Եւ ոչ ոք նոր գինին հին տիկերի մէջ չի լցնի, ապա թէ ոչ՝ նոր գինին հին տիկերը կը պայթեցնի. գինին կը թափուի, եւ տիկերը կը փչանան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Այլ՝ նոր գինին նոր տիկերի մէջ պէտք է լցուի, եւ երկուսն էլ կը պահուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Եւ ոչ ոք, երբ հինը խմի, նորը կ՚ուզենայ, որովհետեւ կ՚ասի, թէ՝ հինը աւելի լաւն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Առաջին ամսուայ երկրորդ շաբաթ օրը, երբ նա անցնում էր արտերի միջով, նրա աշակերտները հասկ էին պոկում, շփում իրենց ափի մէջ եւ ուտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Եւ փարիսեցիներից ոմանք ասացին նրանց. «Ինչո՞ւ էք անում այն, ինչ օրինաւոր չէ անել շաբաթ օրով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Յիսուս նրանց պատասխանեց եւ ասաց. «Դուք չէ՞ք կարդացել, թէ ինչ արեց Դաւիթը, երբ քաղց զգաց ինքը եւ նրանք, որ նրա հետ էին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'թէ ինչպէս նա մտաւ Աստծու տունը, կերաւ առաջաւորութեան հացը եւ տուեց նրանց, որ իր հետ էին. մինչդեռ, բացի քահանայապետներից, ոչ ոքի չէր թոյլատրուած ուտել այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Եւ Յիսուս նրանց ասաց. «Մարդու Որդին նաեւ շաբա՛թ օրուայ տէրն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Եւ մի ուրիշ շաբաթ օր նա մտաւ ժողովարան եւ ուսուցանում էր. եւ այնտեղ կար մի մարդ, որի աջ ձեռքը չորացած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Օրէնսգէտներն ու փարիսեցիները հետեւում էին՝ տեսնելու, թէ արդեօք շաբաթ օրը կը բժշկի՞. որպէսզի նրան ամբաստանելու համար բան գտնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Եւ նա գիտէր նրանց մտածումները: Չորացած ձեռքով մարդուն ասաց. «Վե՛ր կաց, մէջտե՛ղ արի»: Նա վեր կացաւ կանգնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Յիսուս նրանց ասաց. «Ես ձեզ մի բան հարցնեմ. շաբաթ օրը ի՞նչ բան է օրինաւոր անել՝ բարի՞ գործ անել, թէ՞՝ չար գործ, մի հոգի՞ փրկել, թէ՞ կորստեան մատնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Եւ իր շուրջը բոլորի վրայ զայրագին նայելով՝ ասաց նրան. «Ձեռքդ երկարի՛ր». եւ նա երկարեց, եւ նրա չորացած ձեռքը առողջացաւ միւսի նման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Նրանք լցուեցին կատաղութեամբ եւ միմեանց հետ խօսում էին, թէ ի՛նչ անեն Յիսուսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Եւ այդ օրերին Յիսուս լեռ բարձրացաւ աղօթելու եւ ամբողջ գիշերն անցկացրեց Աստծուն աղօթելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Եւ երբ լոյսը բացուեց, կանչեց իր աշակերտներին եւ ընտրեց նրանցից տասներկուսին, որոնց եւ առաքեալներ անուանեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Սիմոնին, որին էլ Պետրոս կոչեց, եւ Անդրէասին՝ նրա եղբօրը, Յակոբոսին, Յովհաննէսին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Փիլիպպոսին, Բարթողոմէոսին, Մատթէոսին, Թովմասին, Ալփէոսի որդի Յակոբոսին, Սիմոնին՝ Նախանձայոյզ կոչուածին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Յակոբի որդի Յուդային եւ Իսկարիովտացի Յուդային, որը եւ մատնիչ եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Եւ նրանց հետ միասին իջաւ մի տափարակ տեղ, ուր նրա աշակերտների խումբը եւ ամբողջ Հրէաստանից ու Երուսաղէմից եւ այն կողմերից եւ Տիւրոսի ու Սիդոնի ծովեզրից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'շատ մեծ բազմութիւն եկել էր լսելու նրան եւ բժշկուելու իրենց հիւանդութիւններից: Եւ պիղծ ոգիներից տառապողները բժշկւում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Եւ ամբողջ ժողովուրդն ուզում էր նրան դիպչել, որովհետեւ նրանից մեծ զօրութիւն էր դուրս գալիս եւ բժշկում բոլորին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Եւ Յիսուս աչքերը բարձրացրեց իր աշակերտների վրայ ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, '- Երանի՜ հոգով աղքատներիդ, որովհետեւ Աստծու արքայութիւնը ձերն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, '- Երանի՜ նրանց, որ քաղցած են այժմ, որովհետեւ պիտի յագենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, '- Երանի՜ նրանց, որ այժմ լալիս են, որովհետեւ պիտի ծիծաղեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, '- Երանի՜ է ձեզ, երբ որ մարդիկ ձեզ ատեն եւ երբ որ ձեզ մերժեն եւ նախատեն ու մարդու Որդու պատճառով ձեր մասին չար անուն հանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ուրախացէ՛ք այդ օրը եւ ցնծացէ՛ք, որովհետեւ ձեր վարձը մեծ է երկնքում. նրանց հայրերը նոյն ձեւով էին վարւում մարգարէների հանդէպ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, '- Բայց վա՜յ ձեզ՝ հարուստներիդ, որովհետեւ դուք ձեր մխիթարութիւնը ստացել էք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, '- Վա՜յ ձեզ, որ այժմ յագեցած էք, որովհետեւ քաղցած պիտի մնաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, '- Վա՜յ ձեզ, որ այժմ ծիծաղում էք, որովհետեւ պիտի սգաք ու պիտի լաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, '- Վա՜յ ձեզ, երբ որ բոլոր մարդիկ լաւ խօսեն ձեր մասին, որովհետեւ նրանց հայրերը սուտ մարգարէներին այդպէս էին անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, '«Բայց ասում եմ ձեզ, դո՛ւք, որ լսում էք ինձ. սիրեցէ՛ք ձեր թշնամիներին, ձեզ ատողներին բարութի՛ւն արէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'օրհնեցէ՛ք ձեզ անիծողներին, ձեզ նեղողների համար աղօթեցէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Ով խփում է քո ծնօտին, նրան մի՛ւսն էլ մօտեցրու. եւ ով որ քեզնից քո բաճկոնը բռնի է վերցնում, նրան մի՛ արգելիր, որ վերցնի շապիկդ էլ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Ամէն մարդու, որ քեզնից ուզում է, տո՛ւր, եւ ինչ որ մէկը քեզնից վերցնի, ետ մի՛ պահանջիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Եւ ինչպէս կամենում էք, որ անեն ձեզ մարդիկ, այնպէս արէ՛ք եւ դուք նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Եւ եթէ դուք ձեզ սիրողներին սիրէք, ո՞րն է ձեր արած շնորհը, որովհետեւ մեղաւորներն էլ են սիրում իրենց սիրողներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Եւ եթէ ձեր բարերարներին բարութիւն անէք, ո՞րն է ձեր արած շնորհը, որովհետեւ մեղաւորներն էլ նոյնն են անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Եւ եթէ փոխ էք տալիս նրանց, որոնցից յետ առնելու ակնկալութիւն ունէք, ո՞րն է ձեր արած շնորհը, որովհետեւ մեղաւորներն էլ են փոխ տալիս մեղաւորներին, որպէսզի նոյն չափով յետ առնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Բայց դուք սիրեցէ՛ք ձեր թշնամիներին եւ բարութի՛ւն արէք ձեզ ատողներին ու փո՛խ տուէք նրան, ումից յետ առնելու ակնկալութիւն չունէք: Եւ ձեր վարձը շատ կը լինի, եւ դուք Բարձրեալի որդիները կը լինէք, որովհետեւ նա բարեհաճ է չարերի եւ ապերախտների հանդէպ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Գթասի՛րտ եղէք, ինչպէս որ ձեր Հայրը գթասիրտ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, '«Մի՛ դատէք, որ Աստծուց չդատուէք, մի՛ դատապարտէք, եւ չպիտի դատապարտուէք, ներեցէ՛ք, եւ ներում պիտի գտնէք Աստծուց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'տուէ՛ք, եւ պիտի տրուի ձեզ. ձեր գոգը պիտի լցնեն առա՛տ չափով՝ թաթաղուն, շարժուն, զեղուն. այն չափով, որով չափում էք, նո՛ւյն չափով պիտի չափուի ձեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Նրանց մի առակ էլ ասաց. «Միթէ կարո՞ղ է կոյրը կոյրին առաջնորդել. չէ՞ որ երկուսն էլ փոսը կ՚ընկնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Աշակերտը մեծ չէ, քան իր վարդապետը. ամէն կատարեալ աշակերտ իր վարդապետի պէս կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Ինչո՞ւ քո եղբօր աչքի միջի շիւղը տեսնում ես, իսկ քո աչքի միջի գերանը չես նշմարում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Եւ կամ՝ ինչպէ՞ս կարող ես եղբօրդ ասել՝ եղբա՛յր, թող որ քո աչքից այդ շիւղը հանեմ, իսկ դու քո աչքի միջի գերանը չես տեսնում: Կեղծաւո՛ր, նախ քո աչքից գերանը հանի՛ր եւ ապա լաւ կը տեսնես՝ քո եղբօր աչքից շիւղը հանելու համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, '«Որովհետեւ չկայ բարի ծառ, որ չար պտուղ տայ. եւ դարձեալ՝ չկայ չար ծառ, որ բարի պտուղ տայ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'որովհետեւ իւրաքանչիւր ծառ իր պտղից է ճանաչւում: Փշերից թուզ չեն քաղում եւ ոչ էլ մորենուց՝ խաղող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Բարի մարդը իր սրտի բարի գանձերից բարին է բխեցնում, իսկ չար մարդը՝ չարն է բխեցնում. որովհետեւ սրտի աւելցուկից է, որ խօսում է նրա բերանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, '«Ինչո՞ւ ինձ «Տէ՛ր, Տէ՛ր» էք կոչում, իսկ ինչ ասում եմ՝ չէք անում: Ամէն մարդ, որ ինձ է գալիս եւ լսում է իմ խօսքերն ու կատարում դրանք, ձեզ ցոյց տամ, թէ ում է նման: Նման է տուն շինող այն մարդուն, որ հողը փորեց ու խորացրեց եւ հիմքը դրեց ժայռի վրայ. եւ երբ հեղեղ բարձրացաւ, գետը զարկեց տանը եւ չկարողացաւ շարժել այն, որովհետեւ նրա հիմքը ժայռի վրայ էր հաստատուած: Իսկ ով իմ խօսքերը լսում է եւ չի կատարում, նման է այն մարդուն, որ հողի վրայ առանց հիմքի տուն է շինում. գետը զարկեց, եւ այն իսկոյն փուլ եկաւ, եւ այդ տան կործանումը մեծ եղաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Եւ երբ Յիսուս վերջացրեց իր բոլոր խօսքերը, եւ ժողովուրդը նրան լսեց, Կափառնայում մտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Այնտեղ մի հարիւրապետի ծառայ, որ շատ սիրելի էր նրա համար, ծանր հիւանդացել էր եւ մեռնելու մօտ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Երբ լսեց Յիսուսի մասին, հրեաներից աւագներին ուղարկեց, որ աղաչեն նրան, որպէսզի գայ եւ բժշկի իր ծառային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Եւ նրանք Յիսուսի մօտ գալով՝ թախանձագին աղաչում էին նրան եւ ասում. «Արժանի է նա, որին այս շնորհը պիտի անես,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'որովհետեւ նա սիրում է մեր ազգը եւ ժողովարանը նա՛ շինեց մեզ համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Յիսուս գնաց նրանց հետ. երբ տնից շատ հեռու չէր, հարիւրապետը նրա մօտ բարեկամներ ուղարկեց՝ ասելով. «Տէ՛ր, նեղութիւն մի՛ կրիր, որովհետեւ արժանի չեմ, որ իմ յարկի տակ մտնես.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'դրա համար էլ ինձ արժանի չհամարեցի քեզ մօտ գալու. այլ՝ խօսքով ասա՛, եւ իմ ծառան կը բժշկուի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'որովհետեւ ինքս էլ իշխանութեան ենթակայ մարդ եմ, իմ ձեռքի տակ զինուորներ ունեմ. սրան ասում եմ՝ գնա՛, եւ գնում է, իսկ միւսին, թէ՝ արի՛, եւ գալիս է, եւ իմ ծառային, թէ՝ արա՛ այս բանը, եւ նա անում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Եւ երբ Յիսուս այս լսեց, զարմացաւ. դարձաւ ժողովրդին, որ հետեւում էր իրեն, եւ ասաց. «Ճշմարիտ եմ ասում ձեզ, որ Իսրայէլի մէջ անգամ այսչափ հաւատ չգտայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Պատգամաւորները տուն վերադարձան եւ հիւանդ ծառային գտան բժշկուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Հետեւեալ օրը Յիսուս գնում էր մի քաղաք, որ Նային էր կոչւում. նրա հետ էին գնում նաեւ իր աշակերտները եւ բազում ժողովուրդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Երբ քաղաքի դարպասին մօտեցաւ, ահա դուրս էր բերւում մի մեռել, միակ որդին իր մօր, որ մի այրի կին էր. եւ քաղաքից բազում ժողովուրդ նրա հետ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Երբ Տէրը կնոջը տեսաւ, խղճաց նրան եւ ասաց. «Մի՛ լար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Մօտենալով՝ դագաղին դիպաւ: Դագաղը տանողները կանգ առան: Եւ նա ասաց. «Քե՛զ եմ ասում, ո՛վ պատանի, վե՛ր կաց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Մեռելը վեր կացաւ, նստեց եւ սկսեց խօսել: Եւ Յիսուս նրան մօրը տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Եւ ահը պատեց բոլորին. փառաւորում էին Աստծուն եւ ասում. «Մի մեծ մարգարէ է յայտնուել մեր մէջ», եւ՝ «Աստուած այցելութիւն է տուել իր ժողովրդին բարութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Եւ նրա մասին այս զրոյցը տարածուեց ամբողջ Հրէաստանում եւ երկրի բոլոր կողմերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Եւ Յովհաննէսին այս բոլորի մասին պատմեցին իր աշակերտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Եւ Յովհաննէսն իր աշակերտներից մի երկուսին իր մօտ կանչեց ու նրանց ուղարկեց Տիրոջ մօտ՝ ասելու. «Դո՞ւ ես, որ գալու էիր, թէ՞ ուրիշին սպասենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Եւ այդ մարդիկ գալով նրա մօտ՝ ասացին. «Յովհաննէս Մկրտիչը մեզ ուղարկեց քեզ մօտ եւ ասում է. «Դո՞ւ ես, որ գալու էիր, թէ՞ ուրիշին սպասենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Եւ նոյն ժամին նա շատերին բժշկեց հիւանդութիւններից, ցաւերի հարուածներից, չար ոգիներից եւ բազմաթիւ կոյրերի տեսողութիւն շնորհեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Նա պատասխանեց նրանց եւ ասաց. «Գնացէք պատմեցէ՛ք Յովհաննէսին, ինչ որ դուք տեսաք եւ լսեցիք. որ կոյրերը տեսնում են, կաղերը՝ քայլում, բորոտները մաքրւում են, խուլերը՝ լսում, մեռելները յարութիւն են առնում, աղքատները Բարի լուրն են լսում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'եւ երանի՜ նրան, որ իմ պատճառով չի գայթակղուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Եւ երբ Յովհաննէսի պատգամաւորները գնացին, նա սկսեց ժողովրդին խօսել Յովհաննէսի մասին. «Ի՞նչ տեսնելու համար դուրս եկաք անապատ. քամուց շարժուող մի եղէ՞գ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Հապա ի՞նչ տեսնելու համար դուրս եկաք. փափուկ զգեստներով զարդարուած մի մա՞րդ. ահաւասիկ նրանք, որ փառաւոր զգեստներով են եւ փափուկ կենցաղով են ապրում, արքունիքներում են լինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Հապա ի՞նչ տեսնելու համար դուրս եկաք. մի մարգարէ՞. այո՛, ասում եմ ձեզ, առաւել քան մի մարգարէ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'որովհետեւ Յովհաննէսը նա է, որի մասին գրուած է. «Ահա քո առաջից ուղարկում եմ իմ պատգամաւորին, որպէսզի քո առաջ քո ճանապարհը պատրաստի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Ճշմարիտ եմ ասում ձեզ, կանանցից ծնուածների մէջ չկայ աւելի մեծ մարգարէ, քան Յովհաննէսը. բայց Աստծու արքայութեան մէջ ամենափոքրը աւելի մեծ է, քան թէ նա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Եւ երբ ամբողջ ժողովուրդը լսեց, նոյնպէս եւ մաքսաւորները, ընդունեցին Աստծու արդարութիւնը՝ մկրտուելով Յովհաննէսի մկրտութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Իսկ փարիսեցիները եւ օրինականները իրենց հոգիներում Աստծու խորհուրդն անարգեցին նրանով, որ Յովհաննէսից չմկրտուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '«Արդ, ո՞ւմ նմանեցնեմ այս սերնդի մարդկանց, եւ ո՞ւմ են նման:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Նրանք նման են մանուկների, որոնք նստում են հրապարակներում, ձայն են տալիս միմեանց եւ ասում. «Փող զարկեցինք ձեզ համար, եւ չպարեցիք. ողբ ասացինք, եւ դուք լաց չեղաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Եկաւ Յովհաննէս Մկրտիչը, չէր ուտում եւ չէր խմում. եւ դուք ասացիք՝ նրա մէջ դեւ կայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Եկաւ մարդու Որդին. ուտում է եւ խմում. եւ դուք ասում էք. «Ահա ուտող եւ խմող մի մարդ, մաքսաւորների եւ մեղաւորների բարեկամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Եւ իմաստութիւնը արդարացուեց իր որդիներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Փարիսեցիներից մէկը աղաչում էր նրան, որ իր հետ ճաշ ուտի. եւ նա մտնելով փարիսեցու տունը՝ սեղան նստեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Եւ քաղաքում մի մեղաւոր կին կար. երբ նա իմացաւ, որ փարիսեցու տանը սեղան է նստել, մի շիշ ազնիւ իւղ բերելով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'կանգնեց Յիսուսի յետեւ, նրա ոտքերի մօտ. եւ լաց էր լինում ու սկսեց արտասուքներով թրջել նրա ոտքերը եւ իր գլխի մազերով սրբում էր. համբուրում էր նրա ոտքերը եւ այդ իւղով օծում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Իսկ փարիսեցին, որ նրան հրաւիրել էր, տեսնելով այդ, իր մտքում ասում էր. «Եթէ սա մարգարէ լինէր, ապա կ՚իմանար, թէ ով կամ ինչպիսի մի կին է մօտենում իրեն, որովհետեւ նա մեղաւոր է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Յիսուս պատասխանեց նրան եւ ասաց. «Սիմո՛ն, քեզ ասելու բան ունեմ»: Եւ սա ասաց. «Ասա՛, Վարդապե՛տ»: Եւ Յիսուս ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '«Մի փոխատու երկու պարտապաններ ունէր. մէկը հինգ հարիւր դահեկան պարտք ունէր, իսկ միւսը՝ յիսուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Եւ քանի որ նրանք հատուցելու ոչինչ չունէին, երկուսին էլ պարտքը շնորհեց. հիմա ասա՛, ո՞վ աւելի շատ կը սիրի նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Սիմոնն ասաց. «Ինձ այնպէս է թւում, թէ նա՛՝ ում աւելի շատը շնորհուեց»: Եւ Յիսուս ասաց նրան. «Ուղի՛ղ դատեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Եւ դառնալով կնոջ կողմը՝ Սիմոնին ասաց. «Տեսնո՞ւմ ես այս կնոջը. մտայ քո տունը, ոտքերիս համար ջուր չտուիր, իսկ սա իր արտասուքներով թրջեց իմ ոտքերը եւ իր մազերով սրբեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Դու ինձ մի համբոյր էլ չտուիր, սակայն սա ահա տուն մտնելուցս ի վեր չի դադարում ոտքերս համբուրելուց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Դու իւղով իմ գլուխը չօծեցիր, սա անուշ իւղով ոտքերս օծեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Դրա համար քեզ ասում եմ. իր անհամար մեղքերը կը ներուեն սրան, որովհետեւ ուժգին սիրեց. քանզի ում շատ է ներւում, շատ է սիրում, եւ ում սակաւ՝ սակաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Եւ ասաց այն կնոջը. «Քո մեղքերը քեզ ներուած են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Եւ նրանք, որ նրա հետ սեղան էին նստել, սկսեցին ասել իրենց մտքում. «Ո՞վ է սա, որ մեղքերին թողութիւն է տալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Եւ նա ասաց այդ կնոջը. «Քո հաւա՛տը քեզ փրկեց, գնա՛ խաղաղութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Դրանից յետոյ Յիսուս շրջում էր քաղաքներում եւ գիւղերում, քարոզում էր եւ աւետարանում Աստծու արքայութիւնը: Եւ նրա հետ էին Տասներկուսը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'եւ մի քանի կանայք, որոնք բժշկուել էին չար ոգիներից ու հիւանդութիւններից. Մարիամը, որ կոչւում էր Մագդաղենացի, եւ որից եօթը դեւ էր դուրս եկել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Յովհաննան՝ Հերովդէսի վերակացուի՝ Քուզայի կինը, եւ Շուշանն ու շատ ուրիշներ, որոնք իրենց ունեցուածքից մատակարարում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Երբ շատ ժողովուրդ եւ բազմաթիւ քաղաքներից նրա մօտ եկածներ հաւաքուեցին, առակով նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '«Մի սերմնացան ելաւ սերմեր ցանելու: Եւ երբ նա սերմանում էր, մի մաս սերմ ընկաւ ճանապարհի եզերքը եւ ոտնակոխ եղաւ, եւ երկնքի թռչունները այն կերան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Եւ ուրիշ մի մաս ընկաւ ապառաժի վրայ. երբ բուսաւ, չորացաւ՝ խոնաւութիւն չլինելու պատճառով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Եւ ուրիշ մի մաս ընկաւ փշերի մէջ. եւ փշերը նրա հետ բուսնելով՝ այն խեղդեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Եւ ուրիշ մի մաս ընկաւ լաւ ու պարարտ հողի վրայ եւ, բուսնելով, հարիւրապատիկ պտուղ տուեց»: Երբ այս խօսեց, ասաց. «Ով որ լսելու ականջ ունի, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Աշակերտները նրան հարցնում էին, թէ այդ առակն ի՞նչ է նշանակում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Եւ նա ասաց. «Ձեզ տրուած է գիտենալ Աստծու արքայութեան խորհուրդները, իսկ ուրիշներին՝ առակներով, որպէսզի նայեն, բայց չտեսնեն, լսեն, բայց չիմանան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Իսկ առակը այս է նշանակում. սերմը Աստծու խօսքն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Որոնք որ ճանապարհի եզերքին են, այդ նրանք են, որ լսում են, եւ ապա սատանան գալիս հանում է խօսքը նրանց սրտից, որպէսզի չհաւատան եւ չփրկուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Եւ որոնք որ ապառաժի վրայ են, այդ նրանք են, որ, երբ լսեն, խնդութեամբ են ընդունում խօսքը, բայց արմատ չեն բռնում. սրանք միառժամանակ հաւատում են, իսկ փորձութեան ժամանակ՝ հեռանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Իսկ այն, որ փշերի մէջ ընկաւ, այդ նրանք են, որ, երբ լսում են խօսքը, աշխարհի հոգսերով, հարստութեամբ եւ զուարճութեամբ զբաղուած լինելով՝ խեղդւում ու անպտուղ են լինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Իսկ այն, որ պարարտ հողի վրայ է, նրանք են, որ բարի եւ զուարթագին սրտով լսելով խօսքը՝ ընդունում են այն եւ յարատեւելով պտուղ են տալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '«Ո՛չ ոք ճրագ չի վառի եւ կաթսայի տակ չի թաքցնի կամ մահճի տակ չի դնի, այլ կը դնի աշտանակի վրայ, որպէսզի, ովքեր մտնեն, լոյսը տեսնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Ծածուկ ոչինչ չկայ, որ չյայտնուի, ոչ էլ գաղտնի բան, որ չիմացուի եւ ի յայտ չգայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Այսուհետեւ զգո՛յշ եղէք, թէ ինչպէս էք դուք լսում. որովհետեւ ով որ ունի, նրան կը տրուի, իսկ ով որ չունի, եւ այն, ինչ որ նա կարծում է, թէ ունի, կը վերցուի նրանից»');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Նրա մօտ եկան իր մայրն ու եղբայրները եւ չէին կարողանում նրան մօտենալ բազմութեան պատճառով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Իմաց տուին նրան եւ ասացին. «Քո մայրը եւ քո եղբայրները դրսում կանգնել են եւ ուզում են քեզ տեսնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Եւ նրանց ասաց. «Իմ մայրը եւ եղբայրները սրանք են, որ Աստծու խօսքը լսում են եւ կատարում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Մի օր ինքը նաւակ նստեց իր աշակերտների հետ եւ նրանց ասաց. «Եկէ՛ք ծովակի միւս կողմն անցնենք»: Եւ գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Մինչ նաւարկում էին, նա քուն մտաւ: Եւ ծովակի վրայ քամու մի մրրիկ իջաւ. ծովը ուռչում էր, նաւակը ջրով լցնում. եւ նրանք տագնապի էին մատնուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Մօտեցան արթնացրին նրան եւ ասացին. «Վարդապե՛տ, Վարդապե՛տ, ահա կորչում ենք»: Եւ նա վեր կենալով՝ սաստեց քամուն ու աղմկայոյզ կոհակներին, եւ նրանք հանդարտուեցին, եւ խաղաղութիւն տիրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Եւ նրանց ասաց. «Ո՞ւր է ձեր հաւատը»: Եւ նրանք սարսափած՝ զարմացան եւ ասում էին միմեանց. «Ո՞վ է արդեօք սա, որ հողմերին ու ջրերին անգամ հրաման է տալիս, եւ դրանք հնազանդւում են սրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Ապա նաւարկեցին իջան գերգեսացիների երկիրը, որը Գալիլիայի հանդիպակաց կողմն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Եւ երբ նա ցամաք ելաւ, նրան պատահեց քաղաքից մի մարդ, որի մէջ դեւեր կային. նա երկար ժամանակ հագուստ չէր հագել եւ ոչ էլ տան մէջ էր բնակուել, այլ՝ գերեզմանների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Եւ տեսնելով Յիսուսին՝ աղաղակեց, ընկաւ նրա առաջ եւ բարձր ձայնով ասաց. «Ի՞նչ ես ուզում ինձնից, Յիսո՛ւս, բարձրեալ Աստծու Որդի, աղաչում եմ քեզ, ինձ մի՛ տանջիր».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'որովհետեւ Յիսուս հրաման էր տալիս պիղծ ոգուն, որ դուրս գայ այդ մարդուց, քանի որ շատ անգամ տիրացել էր նրան, եւ նա կապւում էր շղթաներով, պահւում էր երկաթների մէջ, բայց կոտրում էր կապանքները եւ դեւից քշւում էր անբնակ վայրեր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Յիսուս հարցրեց նրան եւ ասաց. «Անունդ ի՞նչ է»: Եւ նա ասաց. «Լեգէոն». որովհետեւ նրա մէջ շատ դեւեր էին մտել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'աղաչում էին նրան, որ հրաման չտայ իրենց, որ անդունդ գնան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Եւ այնտեղ մեծ թուով խոզերի մի երամակ կար, որ արածում էր լերան վրայ: Աղաչեցին նրան, որ հրաման տայ իրենց՝ գնալ մտնել նրանց մէջ: Եւ նա թոյլատրեց նրանց,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'եւ դեւերը դուրս եկան այդ մարդուց ու մտան խոզերի մէջ. եւ երամակը գահաւանդից դիմեց դէպի ծովակ ու խեղդուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Երբ խոզարածները տեսան պատահածները, փախան եւ պատմեցին քաղաքում ու ագարակներում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Եւ երբ մարդիկ դուրս եկան կատարուածները տեսնելու եւ եկան Յիսուսի մօտ ու գտան այն մարդուն, որից դեւերը ելել էին, - որը հագնուած եւ զգաստացած՝ նստած էր Յիսուսի ոտքերի մօտ, - վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Նրանք, որ ականատես էին եղել, պատմեցին նրանց, թէ ինչպէս փրկուեց դիւահարը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Եւ գերգեսացիների երկրի շրջակայքում գտնուող ամբողջ բնակչութիւնը աղաչում էր Յիսուսին՝ հեռու գնալ իրենց սահմաններից, որովհետեւ մեծ վախով տագնապում էին: Եւ նա նաւակ նստելով՝ վերադարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Այն մարդը, որից դեւերը դուրս էին եկել, աղաչում էր նրան, որ ինքը նրա հետ շրջի: Բայց Յիսուս արձակեց նրան եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '«Վերադարձի՛ր քո տունը եւ պատմի՛ր, ինչ որ Աստուած արեց քեզ համար»: Նա գնաց քաղաք եւ տարածում էր այն, ինչ Յիսուս արեց իրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Եւ երբ Յիսուս վերադարձաւ ծովի միւս կողմը, ժողովուրդը նրան լաւ ընդունեց, որովհետեւ ամէնքը նրան սպասում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Եւ ահա եկաւ մի մարդ, որի անունը Յայրոս էր, եւ որը ժողովրդապետ էր: Յիսուսի ոտքերն ընկնելով՝ նա աղաչում էր նրան, որ իր տունը մտնի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'որովհետեւ նա մօտ տասներկու տարեկան մի միամօրիկ դուստր ունէր, որ մահամերձ էր: Եւ երբ Յիսուս գնում էր, ժողովուրդը նրան նեղում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Եւ մի կին, որ տասներկու տարուց ի վեր արիւնահոսութիւն ունէր եւ հնար չէր եղել նրան որեւէ մէկից բժշկուել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'յետեւից մօտեցաւ եւ դիպաւ նրա զգեստի քղանցքին, եւ նոյն ժամին նրա արիւնահոսութիւնը դադարեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Եւ Յիսուս ասաց. «Ո՞վ էր, որ ինձ դիպաւ»: Եւ երբ բոլորը ուրանում էին, Պետրոսը եւ նրա հետ եղողները ասացին. «Վարդապե՛տ, ժողովուրդն է, որ սեղմում ու նեղում է քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Եւ Յիսուս ասաց. «Մէկն ինձ դիպաւ, որովհետեւ զգացի, որ ինձնից զօրութիւն դուրս եկաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Երբ կինը տեսաւ, որ այդ ծածուկ չմնաց նրանից, դողալով եկաւ եւ ընկաւ նրա առաջ ու ամբողջ ժողովրդի առջեւ պատմեց, թէ ինչ բանի համար դիպաւ նրան եւ թէ ինչպէս իսկոյն բժշկուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Եւ նա ասաց. «Քաջալերուի՛ր, դո՛ւստր, քո հաւատը փրկեց քեզ, գնա՛ խաղաղութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Եւ մինչ նա խօսում էր, ժողովրդապետի տնից մէկն եկաւ եւ Յայրոսին ասաց. «Աղջիկդ մեռաւ, յոգնութիւն մի՛ պատճառիր դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Իսկ երբ Յիսուս լսեց, նրան պատասխանեց եւ ասաց. «Մի՛ վախեցիր, միայն հաւատա՛, եւ նա կ՚ապրի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Եւ նրա տունը մտնելով՝ ոչ ոքի չթողեց ներս մտնել, բացի Պետրոսից, Յակոբոսից, Յովհաննէսից եւ երեխայի հօրից ու մօրից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Ամէնքը լալիս եւ ողբում էին նրա վրայ: Եւ նա ասաց. «Լաց մի՛ եղէք, որովհետեւ մեռած չէ, այլ ննջում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Իսկ նրանք ծաղրում էին նրան, որովհետեւ գիտէին, որ մեռած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Եւ ամենքին դուրս հանելով՝ բռնեց նրա ձեռքից, գոչեց եւ ասաց. «Վե՛ր կաց, կանգնի՛ր, ո՛վ մանուկ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Եւ նրա հոգին վերադարձաւ, եւ մանուկը իսկոյն կանգնեց: Եւ Յիսուս հրամայեց, որ նրան ուտելու բան տան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Եւ նրա ծնողները զարմացած մնացին, իսկ նա պատուիրեց, որ ոչ ոքի չասեն, ինչ որ եղել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Եւ նա կանչելով տասներկու առաքեալներին՝ նրանց զօրութիւն եւ իշխանութիւն տուեց բոլոր դեւերի վրայ, նաեւ՝ բժշկելու հիւանդութիւնները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Եւ ուղարկեց նրանց քարոզելու Աստուծոյ արքայութիւնը եւ բժշկելու ախտերով վարակուածներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Եւ ասաց նրանց. «Ճանապարհի համար ոչինչ մի՛ վերցրէք. ո՛չ գաւազան եւ ո՛չ մախաղ, ո՛չ հաց եւ ո՛չ արծաթ դրամ. երկու հագուստ մի՛ ունեցէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'որ տունն էլ մտնէք, այնտե՛ղ գիշերեցէք եւ ապա այնտեղից գնացէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Եւ նրանք, որ ձեզ չեն ընդունի, որպէս վկայութիւն նրանց դէմ՝ ձեր ոտքերի փոշին թօթափեցէ՛ք, երբ այդ քաղաքից դուրս ելնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Եւ նրանք ելան եւ շրջում էին քաղաքներում ու գիւղերում, աւետարանում էին եւ բժշկում ամէն տեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Հերովդէս չորրորդապետը լսեց այս բոլոր գործերը եւ զարմանում էր ոմանց ասածի վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'թէ՝ Յովհաննէսը մեռելներից յարութիւն է առել, իսկ ոմանց ասածի վրայ, թէ՝ Եղիան յայտնուեց, եւ ուրիշների՝ թէ՝ նախկին մարգարէներից մէկը յարութիւն է առել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Հերովդէսն ասաց. «Յովհաննէսին ես գլխատեցի, իսկ սա ո՞վ է, որի մասին այսպիսի բաներ եմ լսում»: Եւ ուզում էր նրան տեսնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Առաքեալները վերադարձան եւ Յիսուսին պատմեցին այն ամէնը, ինչ որ արեցին. եւ նա նրանց հետն առնելով՝ քաշուեց առանձնացաւ ամայի մի տեղ, մօտակայքը մի քաղաքի, որ Բեթսայիդա էր կոչւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Եւ երբ ժողովուրդը իմացաւ, գնաց նրա յետեւից. եւ նա ընդունելով նրանց՝ խօսում էր նրանց հետ Աստծու արքայութեան մասին. եւ որոնք որ բժշկուելու կարիք ունէին, բժշկում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Եւ օրն սկսեց տարաժամել: Տասներկուսը մօտեցան եւ նրան ասացին. «Արձակի՛ր այս ժողովրդին, որպէսզի գնան շրջակայ գիւղերը եւ ագարակները, հանգստանան եւ կերակուր գտնեն, որովհետեւ այստեղ ամայի վայրում ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Նա ասաց նրանց. «Դո՛ւք տուէք նրանց ուտելու բան»: Եւ նրանք ասացին. «Մենք հինգ նկանակից եւ երկու ձկից աւելին չունենք, եթէ չգնանք եւ այս ժողովրդի համար բաւարար ուտելիք չգնենք».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'որովհետեւ շուրջ հինգ հազար մարդ կար: Նա աշակերտներին ասաց. «Նստեցրէ՛ք դրանց խումբ-խումբ, յիսուն-յիսուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Եւ այդպէս արեցին ու ամենքին նստեցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Եւ նա վերցնելով հինգ նկանակը եւ երկու ձուկը՝ նայեց դէպի երկինք, օրհնեց, կտրեց եւ աշակերտներին տուեց, որպէսզի ժողովրդի առաջ դնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Ամէնքը կերան եւ յագեցան. իսկ կտորտանքները վերցրին՝ տասներկու սակառ լիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Եւ երբ նա առանձին աղօթքի էր կանգնել, նրա հետ էին նաեւ իր աշակերտները: Նրանց հարցրեց եւ ասաց. «Ժողովուրդը իմ մասին ի՞նչ է ասում. ո՞վ եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Եւ նրանք պատասխանեցին եւ ասացին. «Յովհաննէս Մկրտիչը. եւ ոմանք, թէ՝ Եղիան, իսկ ուրիշներ, թէ՝ նախնիներից մի մարգարէ յարութիւն է առել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Ասաց նրանց. «Դո՛ւք իմ մասին ի՞նչ էք ասում. ո՞վ եմ»: Պետրոսը պատասխանեց եւ ասաց. «Աստծու Քրիստոսը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Նա սաստեց նրանց եւ պատուիրեց ոչ ոքի չասել այդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Ապա ասաց. «Մարդու Որդին պէտք է շատ չարչարուի եւ անարգուի քահանայապետներից եւ ծերերից ու օրէնսգէտներից. եւ սպանուի ու երրորդ օրը յարութիւն առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Եւ ամենքին ասում էր. «Եթէ մէկը կամենում է իմ յետեւից գալ, թող ուրանայ իր անձը եւ իր խաչը մշտապէս վերցնի եւ գայ իմ յետեւից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'որովհետեւ, ով որ կամենայ իր անձը փրկել, այն պիտի կորցնի, իսկ ով որ իր անձը ինձ համար կորցնի, այն պիտի փրկի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Ի՞նչ օգուտ է մարդուն, եթէ աշխարհը շահի, բայց իր անձը կորցնի ու տուժի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'որովհետեւ, ով որ ինձ եւ իմ խօսքերը ամօթ կը համարի, նրան մարդու Որդին էլ ամօթահար պիտի անի, երբ գայ իր եւ Հօր եւ սուրբ հրեշտակների փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Բայց, արդարեւ, ասում եմ ձեզ, թէ այստեղ գտնուողների մէջ կան ոմանք, որոնք մահ չպիտի ճաշակեն, մինչեւ որ չտեսնեն Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Եւ այս խօսքերից մօտ ութ օր յետոյ, իր հետ վերցնելով Պետրոսին, Յակոբոսին եւ Յովհաննէսին, նա լեռ ելաւ աղօթքի կանգնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Եւ երբ աղօթքի էր կանգնած, նրա երեսի տեսքը այլակերպուեց, նրա զգեստը փոխուեց եւ փայլուն-սպիտակ դարձաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Եւ ահա երկու մարդիկ խօսում էին նրա հետ: Նրանք Մովսէսն ու Եղիան էին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'որոնք փառքով երեւալով՝ խօսում էին նրա վախճանի մասին, որ տեղի պիտի ունենար Երուսաղէմում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Իսկ Պետրոսը եւ նրա հետ գտնուողները քնի ծանրութեան տակ՝ արթնացան ու տեսան նրա փառքը եւ երկու մարդկանց, որոնք նրա մօտ կանգնած էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Եւ երբ դրանք նրանից հեռանում էին, Պետրոսը Յիսուսին ասաց. «Վարդապե՛տ, լաւ է, որ մենք այստեղ ենք. երեք տաղաւար շինենք, մէկը՝ քեզ, մէկը՝ Մովսէսի եւ մէկը՝ Եղիայի համար»: Եւ չէր իմանում, թէ ինչ էր խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Եւ երբ այս ասում էր, մի ամպ եկաւ ու նրանց վրայ հովանի եղաւ. եւ երբ նրանք ամպի տակ ընկան, վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Ամպից մի ձայն եկաւ, որ ասում էր. «Դա՛ է իմ ընտրեալ Որդին, լսեցէ՛ք դրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Եւ մինչ խօսքի ձայնը դեռ գալիս էր, Յիսուս միայնակ գտնուեց. եւ նրանք լսեցին ու այդ օրերին ոչ ոքի չպատմեցին իրենց տեսածներից եւ ոչ մի բան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Յաջորդ օրը, երբ նրանք իջնում էին լեռնից, Յիսուսին ընդառաջ գնաց մի մեծ բազմութիւն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Եւ ահա ժողովրդի միջից մի մարդ աղաղակեց եւ ասաց. «Վարդապե՛տ, աղաչում եմ քեզ, նայի՛ր իմ որդուն, որովհետեւ իմ մէկ հատիկն է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'ահա չար ոգին դէսուդէն է զարնւում նրա մէջ եւ յանկարծ գոչում է. եւ նրան սաստիկ ցնցում է, թաւալեցնում, փրփրեցնում եւ, խորտակելով նրան, հազիւ է հեռանում նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Ես քո աշակերտներին աղաչեցի, որ հանեն չար ոգուն, բայց նրանք չկարողացան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Յիսուս պատասխանեց եւ ասաց. «Ո՛վ անհաւատ եւ մոլորուած սերունդ, մինչեւ ե՞րբ ձեզ հետ պիտի լինեմ եւ ձեզ հանդուրժեմ. բե՛ր այստեղ քո որդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Եւ մինչդեռ նա մօտենում էր, դեւը գետին խփեց նրան ու ցնցեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Յիսուս սաստեց պիղծ ոգուն, բժշկեց մանկանը եւ տուեց նրան նրա հօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Եւ ամէնքը զարմանում էին Աստծու մեծագործութիւնների վրայ: Եւ մինչդեռ բոլորը զարմանում էին այն ամենի վրայ, որ նա կատարում էր, նա իր աշակերտներին ասաց. «Ձեր ականջների մէջ պահեցէ՛ք դուք այս խօսքերը. որ մարդու Որդին մատնուելու է մարդկանց ձեռքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Սակայն նրանք չէին ըմբռնում այս խօսքը, եւ դա ծածկուած էր նրանցից, որ չիմանան. եւ վախենում էին այդ խօսքի մասին հարց տալ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Աշակերտների մէջ մի վէճ առաջ եկաւ, թէ արդեօք իրենցից ո՛վ է մեծ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Երբ Յիսուս իմացաւ նրանց սրտի խորհուրդները, վերցրեց մի մանուկ, կանգնեցրեց նրանց մէջ իր մօտ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'եւ ասաց նրանց. «Ով որ այս մանկանը ընդունի իմ անունով, ինձ է ընդունում. իսկ ով որ ինձ ընդունի, ընդունում է ինձ ուղարկողին. որովհետեւ, ով որ ձեր մէջ փոքրագոյնն է, նա՛ է մեծ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Յովհաննէսը պատասխանեց եւ ասաց. «Վարդապե՛տ, տեսանք մէկին, որ քո անունով դեւեր էր հանում, եւ արգելեցինք նրան, որովհետեւ մեզ հետ չի շրջում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Յիսուս ասաց նրանց. «Մի՛ արգելէք նրան, որովհետեւ, ով որ ձեր թշնամին չէ, ձեր կողմն է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Եւ երբ աշխարհից նրա վերանալու օրերը լրանում էին, հաստատապէս որոշեց գնալ Երուսաղէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Եւ իրենից առաջ պատգամաւորներ ուղարկեց, որոնք, երբ գնացին, մտան սամարացիների մի գիւղ՝ նրա համար պատրաստութիւն տեսնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Բայց սրանք չընդունեցին նրան, որովհետեւ նա ուղեւորւում էր դէպի Երուսաղէմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Երբ նրա աշակերտները՝ Յակոբոսը եւ Յովհաննէսը, այդ տեսան, ասացին. «Տէ՛ր, կամենո՞ւմ ես, որ ասենք, եւ երկնքից կրակ իջնի ու բնաջինջ անի նրանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Նա դարձաւ սաստեց նրանց եւ ասաց. «Չգիտէք ի՛նչ հոգուց էք դուք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'որովհետեւ մարդու Որդին չեկաւ մարդկանց հոգիները կորստեան մատնելու, այլ՝ փրկելու»: Եւ մի ուրիշ գիւղ գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Եւ մինչդեռ նրանք գնում էին, ճանապարհի վրայ մէկը նրան ասաց. «Կը գամ քո յետեւից, ինչ տեղ էլ գնաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Յիսուս նրան ասաց. «Աղուէսները որջեր ունեն, եւ երկնքի թռչունները՝ հանգստանալու տեղ, բայց մարդու Որդին գլուխը դնելու տեղ չունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Մի ուրիշի էլ ասաց. «Արի՛ իմ յետեւից»: Եւ սա ասաց. «Տէ՛ր, հրաման տուր ինձ՝ գնալ նախ թաղել իմ հօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Յիսուս նրան ասաց. «Թող որ մեռածնե՛րը թաղեն իրենց մեռելներին, իսկ դու գնա՛ քարոզիր Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Մէկ ուրիշն էլ ասաց. «Քո յետեւից կը գամ, Տէ՛ր, բայց նախ թո՛յլ տուր ինձ, որ հրաժեշտ տամ իմ տանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Յիսուս նրան ասաց. «Ո՛չ ոք իր ձեռքը մաճի վրայ կը դնի եւ ապա յետ կը նայի, եթէ յարմար է Աստծու արքայութեանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Այնուհետեւ Տէրը նշանակեց ուրիշ եօթանասուներկու հոգի եւս եւ նրանց իրենից առաջ երկու-երկու ուղարկեց այն բոլոր քաղաքներն ու վայրերը, ուր ինքը գնալու էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Եւ նրանց ասաց. «Հունձն առատ է, իսկ մշակները՝ սակաւ: Արդ, խնդրեցէ՛ք հնձի տիրոջը, որ մշակներ ուղարկի իր հնձի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Գնացէ՛ք, ահա ուղարկում եմ ձեզ իբրեւ գառներ գայլերի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Մի՛ վերցրէք ո՛չ քսակ, ո՛չ մախաղ, ո՛չ կօշիկներ եւ ճանապարհին ոչ ոքի ողջոյն մի՛ տուէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Որ տունը մտնէք, նախ ասացէ՛ք. «Խաղաղութի՜ւն այս տանը».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'եթէ այնտեղ կայ խաղաղասէր մարդ, ձեր խաղաղութիւնը նրա վրայ կը հանգչի. ապա թէ ոչ՝ ձե՛զ կը վերադառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Նոյն տանը գիշերեցէ՛ք, կերէ՛ք եւ խմեցէ՛ք նրանց ունեցածից, որովհետեւ մշակը արժանի է իր վարձին. տնից տուն մի՛ տեղափոխուէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Ո՛ր քաղաքը որ մտնէք եւ ձեզ ընդունեն, կերէ՛ք, ինչ որ ձեր առաջ դնեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Եւ բժշկեցէ՛ք դրա մէջ եղած հիւանդներին եւ նրանց ասացէ՛ք. «Մօտեցել է ձեզ Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Իսկ ո՛ր քաղաքը որ մտնէք եւ ձեզ չընդունեն, երբ դուրս գաք նրա հրապարակները, ասացէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '«Ձեր քաղաքից մեր ոտքերին կպած փոշին անգամ թօթափում ենք ձեր վրայ. բայց իմացէ՛ք, որ մօտեցել է Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Ասում եմ ձեզ, որ սոդոմայեցիների համար դատաստանի օրը աւելի տանելի պիտի լինի, քան այն քաղաքի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, '«Վա՜յ քեզ, Քորազին, վա՜յ քեզ, Բեթսայիդա, որովհետեւ եթէ Տիւրոսում եւ Սիդոնում եղած լինէին այն զօրաւոր գործերը, որ կատարուեցին ձեր մէջ, արդարեւ վաղուց իսկ քուրձերի մէջ ու մոխրի վրայ նստած՝ ապաշխարած կը լինէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Բայց Տիւրոսի եւ Սիդոնի համար, դատաստանի ժամանակ, աւելի տանելի կը լինի, քան ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Եւ դու, Կափառնայո՛ւմ, որ մինչեւ երկինք ես բարձրացել, պիտի իջնես մինչեւ դժոխք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Ով որ ձեզ լսում է, ինձ է լսում, եւ ով որ ձեզ է մերժում, ինձ է մերժում, եւ ով որ ինձ է մերժում, ինձ ուղարկողին է մերժում, եւ ով որ ինձ է լսում, լսում է նրան, ով ինձ ուղարկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Եօթանասուներկուսը վերադարձան խնդութեամբ եւ ասացին. «Տէ՛ր, դեւերն էլ են մեզ հնազանդւում քո անունով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Եւ նրանց ասաց. «Տեսնում էի սատանային երկնքից ընկնելիս, ինչպէս փայլակը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Ահա ձեզ իշխանութիւն տուի կոխելու օձերի, կարիճների եւ թշնամու ամբողջ զօրութեան վրայ: Եւ ձեզ բոլորովին չեն վնասելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Բայց մի՛ ուրախացէք այն բանի համար, որ դեւերը ձեզ հնազանդւում են, այլ ուրախացէ՛ք, որ ձեր անունները գրուած են երկնքում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Նոյն ժամին Յիսուս ցնծաց Սուրբ Հոգով եւ ասաց. «Գոհութի՜ւն քեզ, Հա՛յր, Տէ՛ր երկնքի եւ երկրի, որ ծածկեցիր այս բանը իմաստուններից ու գիտուններից եւ յայտնեցիր մանուկներին. այո՛, Հա՛յր, որովհետեւ այսպէս հաճելի եղաւ քեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Ամէն ինչ ինձ տրուեց իմ Հօրից. եւ ոչ ոք չգիտէ, թէ ո՛վ է Որդին, եթէ ոչ՝ Հայրը, եւ թէ՝ ո՛վ է Հայրը, եթէ ոչ՝ Որդին եւ նա, ում կը կամենայ Որդին յայտնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Եւ դառնալով աշակերտներին՝ առանձին ասաց. «Երանի՜ այն աչքերին, որ կը տեսնեն այն, ինչ դուք տեսնում էք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Ասում եմ ձեզ, որ բազում մարգարէներ եւ թագաւորներ կամեցան տեսնել այն, ինչ դուք տեսնում էք, բայց չտեսան, եւ լսել՝ ինչ դուք լսում էք, բայց չլսեցին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Եւ ահա օրինականներից մէկը վեր կացաւ, փորձում էր նրան եւ ասում. «Վարդապե՛տ, ի՞նչ պէտք է անեմ, որ յաւիտենական կեանքը ժառանգեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Եւ նա նրան ասաց. «Օրէնքում ի՞նչ է գրուած, ինչպէ՞ս ես ընթերցում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Սա պատասխանեց եւ ասաց. «Պիտի սիրես քո Տէր Աստծուն քո ամբողջ սրտով եւ քո ամբողջ հոգով եւ քո ամբողջ զօրութեամբ եւ քո ամբողջ մտքով. եւ պիտի սիրես քո ընկերոջը, ինչպէս քո անձը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Եւ Յիսուս նրան ասաց. «Ճիշտ պատասխան տուեցիր, այդ արա՛ եւ կը փրկուես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Եւ նա կամենալով ինքն իրեն արդարացնել, ասաց Յիսուսին. «Իսկ ո՞վ է իմ ընկերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Յիսուս պատասխանեց եւ ասաց. «Մի մարդ Երուսաղէմից Երիքով էր իջնում եւ ընկաւ աւազակների ձեռքը, որոնք նրան մերկացրին, վիրաւորեցին եւ կիսամեռ թողեցին ու գնացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Պատահեց, որ մի քահանայ նոյն ճանապարհով իջնի. նրան տեսաւ եւ թողեց անցաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'նոյնպէս եւ մի ղեւտացի նոյն տեղով անցնելիս, տեսաւ եւ թողեց անցաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Մի սամարացի, որ ճանապարհորդում էր, եկաւ նոյն տեղով նրա մօտ եւ տեսնելով նրան՝ գթաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Եւ մօտենալով՝ կապեց նրա վէրքերը, վրան ձէթ ու գինի ածեց եւ դնելով նրան իր գրաստի վրայ՝ տարաւ մի իջեւան եւ խնամեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Եւ յաջորդ օրը, երբ դուրս էր գալիս այնտեղից, իջեւանատիրոջը երկու դահեկան հանեց տուեց եւ ասաց. «Խնամի՛ր նրան եւ ինչ որ ծախսես դրա վրայ, իմ միւս անգամ գալուն կը հատուցեմ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Արդ, ըստ քեզ, այդ երեքից ո՞րը մերձաւորի պէս վերաբերուեց նրան, ով աւազակների ձեռքն էր ընկել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Եւ սա ասաց. «Նա, ով նրան բարիք արեց»: Յիսուս նրան ասաց. «Գնա՛ եւ դու նո՛յն ձեւով արա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Եւ մինչ նրանք գալիս էին, Յիսուս մտաւ մի գիւղ, եւ Մարթա անունով մի կին նրան ընդունեց իր տան մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Եւ սա մի քոյր ունէր, որի անունը Մարիամ էր, որ եկաւ նստեց Տիրոջ ոտքերի առաջ եւ լսում էր նրա խօսքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Իսկ Մարթան, որ զբաղուած էր տնային շատ գործերով, եկաւ կանգնեց նրա մօտ եւ ասաց. «Տէ՛ր, քեզ փոյթ չէ՞, որ քոյրս ինձ մենակ է թողել ծառայութեան գործի մէջ. արդ, ասա՛ դրան, որ օգնի ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Յիսուս պատասխանեց ու ասաց. «Մարթա՛, Մարթա՛, դու հոգս ես անում եւ շատ բաներով ես զբաղուած,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'բայց այստեղ քիչ բան է պէտք. Մարիամը ընտրել է լաւ մասը, որ նրանից չպիտի վերցուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Եւ եղաւ որ Յիսուս մի տեղ աղօթքի էր կանգնած. եւ երբ վերջացրեց, նրա աշակերտներից մէկն ասաց նրան. «Տէ՛ր, մեզ աղօթել սովորեցրո՛ւ, ինչպէս Յովհաննէսը սովորեցրեց իր աշակերտներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Նա նրանց ասաց. «Երբ աղօթքի կանգնէք, ասացէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Եւ Յիսուս նրանց ասաց. «Ձեզնից ո՞վ է, որ բարեկամ ունենայ, գնայ նրա մօտ կէսգիշերին եւ ասի նրան. բարեկա՛մ, ինձ երեք նկանակ փո՛խ տուր,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'որովհետեւ իմ բարեկամը ճանապարհից եկաւ ինձ մօտ, եւ ես նրա առաջ դնելու ոչինչ չունեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Իսկ նա ներսից պատասխանի եւ ասի. «Ինձ նեղութիւն մի՛ տուր, որովհետեւ դռները փակուած են, եւ երեխաներս ինձ հետ անկողնում են, չեմ կարող վեր կենալ եւ քեզ հաց տալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Ասում եմ ձեզ, եթէ բարեկամութեան համար էլ վեր չկենայ եւ հաց չտայ նրան, նրա թախանձանքի՛ պատճառով վեր կենալով կը տայ նրան, ինչ որ պէտք է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Եւ ես ասում եմ ձեզ. խնդրեցէ՛ք, եւ Աստծուց կը տրուի ձեզ, փնտռեցէ՛ք, եւ կը գտնէք, բախեցէ՛ք, եւ կը բացուի ձեզ համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'որովհետեւ, ով որ խնդրում է, առնում է, ով որ փնտռում է, գտնում է, եւ ով որ բախում է, բացւում է նրա առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Ձեզնից ո՞վ է այն հայրը, որի որդին եթէ ձուկ ուզի, միթէ ձկան փոխարէն օ՞ձ կը տայ նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'եւ կամ ձու ուզի, միթէ կարի՞ճ կը տայ նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Իսկ եթէ դուք, որ չար էք, գիտէք բարի պարգեւներ տալ ձեր որդիներին, որչա՜փ եւս առաւել ձեր երկնաւոր Հայրը բարիքներ կը տայ նրանց, որոնք ուզում են իրենից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Եւ Յիսուս մի համր դեւ էր հանում. եւ երբ դեւը ելաւ, համրը խօսեց. եւ ամբողջ ժողովուրդը զարմացաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Եւ նրանցից ոմանք ասացին. «Դա դեւերին հանում է դեւերի իշխան Բէեղզեբուղի միջոցով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Իսկ ուրիշներ փորձում էին նրան եւ երկնքից նշան էին ուզում նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Իսկ նա իմանալով նրանց մտածումները՝ ասաց նրանց. «Ինքն իր մէջ բաժանուած ամէն թագաւորութիւն աւերւում է, եւ ինքն իր մէջ բաժանուած ամէն տուն՝ կործանւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Արդ, եթէ սատանան էլ ինքն իր մէջ բաժանուեց, նրա թագաւորութիւնը ինչպէ՞ս կարող է կանգուն մնալ. որովհետեւ իմ մասին ասում էք, թէ՝ «Դա դեւերին հանում է դեւերի իշխան Բէեղզեբուղի միջոցով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Եթէ ես դեւերին հանում եմ Բէեղզեբուղի միջոցով, ձեր հետեւորդները ինչո՞վ պիտի հանեն. դրա համար նրա՛նք պիտի լինեն ձեր դատաւորները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Իսկ եթէ Աստծու մատով եմ հանում դեւերին, ապա Աստծու արքայութիւնը հասել է ձեր վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Երբոր զինուած հզօր մի մարդ պահպանում է իր տունը, նրա ինչքը ապահով է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Բայց եթէ նրանից աւելի հզօրը գայ նրա վրայ եւ յաղթի նրան, նրանից կը հանի այն զէնքերը, որոնց վրայ յոյս էր դրել, եւ նրա աւարը կը բաժանի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Ով ինձ հետ չէ, հակառակ է ինձ, եւ ով ինձ հետ չի հաւաքում, ցրում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, '«Երբ պիղծ դեւը ելնում է մարդուց, շրջում է անջրդի տեղերում, հանգիստ է փնտռում. եւ երբ չի գտնում, ասում է՝ «Վերադառնամ իմ տունը, որտեղից ելայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Եւ գալիս է ու գտնում այն՝ մաքրուած եւ կարգի բերուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Այն ժամանակ գնում եւ վերցնում է իրենից աւելի չար եօթը այլ դեւեր եւ մտնում, բնակւում է այնտեղ. եւ այն մարդու վերջին վիճակը լինում է աւելի վատ, քան նախկինը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Եւ մինչդեռ Յիսուս այս բանն էր խօսում, ժողովրդի միջից մի կին ձայն բարձրացրեց եւ ասաց. «Երանի՜ է այն կնոջը, որ յղացաւ եւ դիեցրեց քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Եւ նա ասաց. «Մանաւանդ երանի՜ է նրանց, որ լսում են Աստծու խօսքը եւ կը պահեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Եւ երբ ժողովուրդը նրա շուրջը խռնուեց, սկսեց ասել. «Այս սերունդը չար սերունդ է. նշան է ուզում, եւ նրան երկնքից այլ նշան չի տրուի, բացի Յովնանի նշանից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'որովհետեւ, ինչպէս Յովնանը նշան եղաւ նինուէացիների համար, նոյնպէս մարդու Որդին նշան կը լինի այս սերնդի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Հարաւի դշխոն դատաստանի ժամանակ վեր պիտի կենայ այս սերնդի մարդկանց հետ եւ պիտի դատապարտի նրանց, որովհետեւ նա երկրի ծագերից եկաւ լսելու Սողոմոնի իմաստութիւնը. եւ ահա Սողոմոնից մեծը կայ այստեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Նինուէի մարդիկ դատաստանի ժամանակ վեր պիտի կենան այս սերնդի հետ եւ պիտի դատապարտեն նրան, որովհետեւ Յովնանի քարոզութեան վրայ ապաշխարեցին. եւ ահա Յովնանից մեծը կայ այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, '«Ոչ ոք ճրագ վառելով ծածուկ տեղ չի դնի, այլ կը դնի աշտանակի վրայ, որպէսզի մտնողը լոյս տեսնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Մարմնի ճրագը աչքն է. երբ աչքը առողջ է, ամբողջ մարմինը լուսաւոր կը լինի, իսկ երբ աչքը պղտոր է, մարմինն էլ խաւար կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Արդ, զգո՛յշ եղիր, գուցէ այն լոյսը, որ քո մէջ է, խաւար լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Եթէ քո ամբողջ մարմինը լուսաւոր է, եւ նրա մէջ խաւարի մաս չկայ, ամէն ինչ այնպէս լուսաւոր կը լինի, ինչպէս երբ ճրագը իր շողերով լուսաւորի քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Եւ մինչդեռ նա խօսում էր այս բաները, մի փարիսեցի աղաչում էր նրան, որ իր մօտ ճաշի: Եւ նա մտնելով՝ սեղան նստեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Երբ փարիսեցին տեսաւ, զարմացաւ, որովհետեւ Յիսուս ճաշից առաջ չլուացուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Տէրը նրան ասաց. «Այժմ դուք՝ փարիսեցիներդ, բաժակի եւ պնակի արտաքինն էք մաքրում, իսկ ձեր ներքինը լի է յափշտակութեամբ եւ չարութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Անմիտնե՛ր, չէ՞ որ նա, ով արտաքինը ստեղծեց, նաեւ ներքինը ստեղծեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Բայց տեսէ՛ք, թէ ինչն է իսկապէս արժան. ողորմութի՛ւն տուէք, եւ ահա ձեր ամէն ինչը մաքուր կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Բայց վա՜յ ձեզ՝ փարիսեցիներիդ, որ տասանորդ էք տալիս անանուխի, փեգենայի եւ ամէն տեսակ բանջարեղէնի, բայց զանց էք անում Աստծու արդարութիւնն ու սէրը. այս բաները պէտք էր անել, բայց միւսները զանց չանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Վա՜յ ձեզ՝ փարիսեցիներիդ, որ ժողովարաններում բարձր գահերն էք սիրում եւ հրապարակներում՝ առաջին ողջոյնները ստանալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Վա՜յ ձեզ, որ անյայտ գերեզմանների պէս էք. մարդիկ քայլում են նրանց վրայով եւ չգիտեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Օրէնսգէտներից մէկը պատասխանեց եւ ասաց նրան. «Վարդապե՛տ, այդ բաներն ասելով՝ մեզ էլ ես նախատում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Եւ նա ասաց. «Վա՜յ ձե՛զ եւս, օրէնսգէտնե՛ր, որ մարդկանց դժուարակիր բեռներ էք բարձում, բայց դուք ինքներդ մէկ մատով իսկ բեռներին չէք դիպչում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Վա՜յ ձեզ, որ մարգարէներին շիրիմներ էք շինում, իսկ ձեր հայրերը նրանց սպանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Դրանով իսկ դուք վկայում էք, թէ կամակից էք ձեր հայրերի գործերին, որովհետեւ նրանք կոտորեցին մարգարէներին, իսկ դուք նրանց գերեզմաններ էք շինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Դրա համար Աստծու իմաստութիւնն ասաց. նրանց մէջ մարգարէներ եւ առաքեալներ կ՚ուղարկեմ, եւ նրանցից ոմանց պիտի սպանեն եւ հալածեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'որպէսզի այդ սերնդից պահանջուի արիւնը բոլոր մարգարէների՝ թափուած աշխարհի սկզբից՝');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Աբէլի արիւնից մինչեւ արիւնը Զաքարիայի, որը կորստեան մատնուեց խորանի եւ տաճարի միջեւ. այո՛, ասում եմ ձեզ, պիտի պահանջուի՛ այդ սերնդից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Վա՜յ ձեզ՝ օրէնսգէտների՛դ, որ թաքցնում էք գիտութեան բանալիները. դուք չէք մտնում եւ մտնողներին էլ արգելում էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Եւ երբ այս բոլորը նրանց ասաց ամբողջ ժողովրդի առաջ, ամօթահար եղան. եւ օրէնսգէտներն ու փարիսեցիները սկսեցին խիստ չարանալ եւ բանավէճի բռնուել նրա հետ՝ շատ բաների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Եւ սպասում էին նրա բերանից ինչ-ինչ խօսքեր որսալ, որպէսզի չարախօսեն նրա մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Մինչ Յիսուսի շուրջը բիւրաւոր ժողովուրդ հաւաքուեց՝ իրար կոխոտելու աստիճան, նա սկսեց նախ իր աշակերտներին ասել. «Նախ դուք ձեզ զգո՛յշ պահեցէք փարիսեցիների խմորից, որ կեղծաւորութիւնն է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'որովհետեւ չկայ ծածուկ բան, որ չյայտնուի, եւ գաղտնի բան, որ չիմացուի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'քանի որ, ինչ որ խաւարի մէջ ասէք, լսելի պիտի լինի լոյսի մէջ. եւ ինչ որ շտեմարաններում փսփսաք ականջների մէջ, պիտի քարոզուի տանիքների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Բայց ասում եմ ձեզ՝ իմ սիրելիներին, մի՛ զարհուրէք նրանցից, որ մարմինն են սպանում եւ դրանից յետոյ աւելի բան անել չեն կարող,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'այլ ցոյց կը տամ ձեզ, թէ ումի՛ց պէտք է վախենաք: Վախեցէ՛ք նրանից, ով սպանելուց յետոյ գեհեն նետելու իշխանութիւն ունի: Այո՛, ասում եմ ձեզ, վախեցէ՛ք նրանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Չէ՞ որ հինգ ճնճղուկը երկու դահեկանի է վաճառւում, եւ նրանցից ոչ մէկը Աստծու առաջ մոռացուած չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Նոյնիսկ ձեր գլխի բոլոր մազերը հաշուուած են. մի՛ վախեցէք, որովհետեւ դուք շատ աւելի յարգի էք, քան ճնճղուկները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, '«Ասում եմ ձեզ, ով որ մարդկանց առաջ խոստովանի ինձ, մարդու Որդին էլ նրան կը խոստովանի Աստծու հրեշտակների առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Իսկ ով որ մարդկանց առաջ ինձ կ՚ուրանայ, Աստծու հրեշտակների առաջ պիտի ուրացուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Եւ ով որ մարդու Որդու դէմ բան ասի, նրան պիտի ներուի, բայց ով որ Սուրբ Հոգուն հայհոյի, նրան չպիտի ներուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Իսկ երբ ձեզ տանեն ժողովարանների, կառավարիչների եւ իշխանաւորների առաջ, մի՛ մտահոգուէք, թէ ինչպէս կամ ինչ պատասխան պիտի տաք եւ կամ ինչ պիտի ասէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'որովհետեւ Սուրբ Հոգին նոյն ժամին կը սովորեցնի ձեզ, թէ ինչ պէտք է խօսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Ժողովրդի միջից մէկը նրան ասաց. «Վարդապե՛տ, ասա եղբօրս, որ ժառանգութիւնը ինձ հետ բաժանի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Եւ նա նրան ասաց. «Ո՛վ մարդ, ինձ ո՞վ դատաւոր կամ բաժանարար կարգեց ձեր վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Ապա ժողովրդին ասաց. «Տեսէք, որ զգոյշ լինէք ամէն տեսակ ագահութիւնից, որովհետեւ մարդու կեանքը իր կուտակած հարստութեան մէջ չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Եւ նրանց մի առակ պատմեց ու ասաց. «Մի մեծահարուստի արտերը առատ բերք տուեցին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'եւ նա խորհեց իր մտքում ու ասաց. «Տեսնեմ ինչ կարող եմ անել, քանի որ բերքս կուտակելու տեղ չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Գիտեմ, - ասաց նա, - թէ ինչ պէտք է անեմ. կը քանդեմ իմ շտեմարանները եւ աւելի մեծերը կը շինեմ ու այնտեղ կը հաւաքեմ ցորենը եւ իմ ամբողջ բարիքները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'ու ինքս ինձ կ՚ասեմ՝ ո՛վ մարդ, շատ տարիների համար ամբարուած բազում բարիքներ ունես, հանգի՛ստ արա, կե՛ր, խմի՛ր եւ ուրա՛խ եղիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Աստուած նրան ասաց. «Անմի՛տ, հէնց այս գիշեր հոգիդ քեզնից պահանջելու են, իսկ ինչ որ պատրաստել ես, ո՞ւմն է լինելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Նոյնպէս է նաեւ նա, ով իր անձի համար գանձ կը հաւաքի եւ Աստուծով չի հարստանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Եւ իր աշակերտներին ասաց. «Դրա համար էլ ասում եմ ձեզ. հոգ մի՛ արէք ձեր հոգու համար, թէ ինչ էք ուտելու, ոչ էլ մարմնի համար, թէ ինչ էք հագնելու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'որովհետեւ հոգին առաւել է, քան կերակուրը, եւ մարմինը՝ քան հագուստը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Նայեցէ՛ք ագռաւներին, որոնք ո՛չ սերմանում են եւ ո՛չ հնձում, որոնք ո՛չ շտեմարաններ ունեն եւ ո՛չ էլ ամբարներ, բայց Աստուած կերակրում է նրանց. որքա՜ն եւս առաւել ձեզ, որ շատ աւելի յարգի էք, քան թռչունները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Ձեզնից ո՞վ, հոգս անելով, կը կարողանայ իր հասակի վրայ մէկ կանգուն աւելացնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Արդ, եթէ փոքր բանի մէջ անկարող էք, այլ բաների համար ինչո՞ւ էք հոգս անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Նայեցէ՛ք շուշանին՝ ինչպէս է աճում. ո՛չ աշխատում է եւ ո՛չ հիւսում: Ասում եմ ձեզ՝ Սողոմոնն իսկ իր ամբողջ փառքի մէջ նրանցից մէկի նման չհագնուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Իսկ եթէ խոտը, որ այսօր բաց դաշտի մէջ է, իսկ վաղը հնոց է նետուելու, Աստուած այդպէ՛ս է հագցնում, որչա՜փ եւս առաւել ձեզ պիտի հագցնի, թերահաւատնե՛ր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Եւ դուք մի՛ մտահոգուէք, թէ ի՛նչ էք ուտելու կամ ի՛նչ էք խմելու, եւ մի՛ մտատանջուէք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'որովհետեւ այդ ամէնը աշխարհի հեթանոսներն են, որ փնտռում են: Իսկ ձեր Հայրը գիտէ, որ այդ ամէնը պէտք է ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Այլ դուք հետամո՛ւտ եղէք Աստծու արքայութեանը, եւ այդ ամէնը աւելիով կը տրուի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, '«Մի՛ վախեցիր, փոքրի՛կ հօտ, որովհետեւ ձեր Հայրը հաճեց տալ ձեզ արքայութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Վաճառեցէ՛ք ձեր ինչքերը եւ ողորմութիւն տուէք. եւ ձեզ համար շինեցէ՛ք չհնացող քսակներ եւ անհատնում գանձեր երկնքում, ուր ո՛չ գողն է մօտենում, եւ ո՛չ ցեցը՝ փչացնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'որովհետեւ, ուր որ ձեր գանձն է, այնտեղ եւ ձեր սրտերը կը լինեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, '«Թող ձեր գօտիները մէջքներիդ պնդուած լինեն, եւ ճրագներդ՝ վառուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Եւ դուք նմանուեցէ՛ք այն ծառաներին, որոնք սպասում են իրենց տիրոջը, թէ ե՛րբ կը վերադառնայ հարսանիքից, որպէսզի, երբ գայ եւ բախի դուռը, իսկոյն բաց անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Երանի՜ այն ծառաներին, որոնց արթուն կը գտնի տէրը, երբ գայ: Ճշմարիտ եմ ասում ձեզ, որ նա գօտի կը կապի մէջքին, սեղան կը նստեցնի նրանց եւ կ՚անցնի նրանց սպասարկելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Եւ եթէ տէրը գայ կէսգիշերին եւ կամ աւելի ուշ ու գտնի նրանց այդպէս, երանելի են այդ ծառաները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Բայց այն էլ իմացէ՛ք, որ եթէ տանտէրը գիտենար, թէ ո՛ր ժամին գող կը գայ, թոյլ չէր տայ, որ իր տունը կտրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Դուք էլ պատրա՛ստ եղէք, որովհետեւ այն ժամին, երբ չէք սպասի, կը գայ մարդու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Պետրոսն ասաց. «Տէ՛ր, մե՞զ համար ասացիր այդ առակը, թէ՞ բոլորի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Եւ Տէրն ասաց. «Ո՞վ է այն հաւատարիմ եւ իմաստուն տնտեսը, որին իր տէրը իր ծառաների վրայ վերակացու կարգեց՝ ժամանակի՛ն կերակուր տալու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Երանի՜ է այն ծառային, որին իր տէրը, երբ որ գայ, այդպէս արած կը գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Արդարեւ, ասում եմ ձեզ, որ նրան իր բոլոր ինչքերի վրայ վերակացու կը կարգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Իսկ եթէ այդ ծառան իր սրտում ասի՝ «Իմ տէրը ուշանում է գալ», եւ սկսի ծեծել ծառաներին եւ աղախիններին, ուտել, խմել եւ հարբել,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'այդ ծառայի տէրը կը գայ այն օրը, երբ նա չէր սպասում, եւ այն ժամին, որ չէր իմանում. նրան մէջքից երկու կտոր կ՚անի եւ նրա բաժինը անհաւատների հետ կը դնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Իսկ այն ծառան, որ գիտէ իր տիրոջ կամքը, բայց նրա կամքի համաձայն չի պատրաստի, շատ ծեծ կ՚ուտի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Եւ այն ծառան, որ չգիտէ իր տիրոջ կամքը եւ ծեծի արժանի գործ է կատարում, քիչ ծեծ կ՚ուտի. նրան, ում շատ է տրուած, նրանից շատ էլ կ՚ուզուի, եւ ում շատ է վստահուած, նրանից աւելին կը պահանջեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, '«Երկրի վրայ կրակ գցելու եկայ. եւ ինչքա՜ն եմ կամենում, որ արդէն իսկ բորբոքուած լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Եւ մի մկրտութիւն ունեմ մկրտուելու եւ ինչպէ՜ս եմ շտապում, որ կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Կարծում էք, թէ երկրին խաղաղութի՞ւն տալու եկայ. ո՛չ, ասում եմ ձեզ, այլ՝ բաժանում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'որովհետեւ մէկ տան մէջ այսուհետեւ հինգ հոգի իրարից բաժանուած պիտի լինեն. երեքը՝ երկուսի դէմ, եւ երկուսը՝ երեքի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Հայրը պիտի բաժանուի որդու դէմ, եւ որդին՝ Հօր, մայրը՝ աղջկայ դէմ, եւ աղջիկը՝ մօր, կեսուրը՝ հարսի դէմ, եւ հարսը՝ իր կեսրոջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Ժողովրդին էլ ասաց. «Երբ տեսնէք, որ արեւմուտքից ամպ է ելնում, իսկոյն կ՚ասէք, թէ՝ անձրեւ կը գայ: Այդպէս էլ լինում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Եւ երբ հարաւի քամին փչի, կ՚ասէք, թէ՝ խորշակ կը լինի: Եւ այդպէս էլ լինում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Կեղծաւորնե՛ր, երկնքի եւ երկրի երեւոյթները քննել գիտէք, իսկ այս ներկայ ժամանակը ինչպէ՞ս չէք քննում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Ինչո՞ւ դուք անձնապէս արժանին չէք ընտրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Երբ քո թշնամու հետ գնաս իշխանի մօտ, ճանապարհին հաշիւդ մաքրի՛ր, որ նրանից ազատուես, որովհետեւ գուցէ նա քեզ քարշ տայ դատաւորի մօտ, եւ դատաւորը քեզ բանտապահի ձեռքը յանձնի, եւ բանտապահն էլ՝ բանտ նետի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Ասում եմ քեզ, այնտեղից դուրս չես գայ, մինչեւ որ չվճարես վերջին գրոշը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Այդ նոյն ժամանակ ոմանք եկան եւ պատմեցին նրան այն գալիլիացիների մասին, որոնց արիւնը Պիղատոսը խառնեց իրենց զոհերի արեան հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Նա պատասխանեց նրանց եւ ասաց. «Կարծո՞ւմ էք, թէ այն գալիլիացիները, որոնք այդպիսի պատահարների ենթարկուեցին, աւելի մեղաւոր էին քան բոլոր գալիլիացիները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Ո՛չ, ասում եմ ձեզ, սակայն, եթէ չապաշխարէք, ամէնքդ էլ նոյնպէս պիտի կորչէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Կամ նրանք՝ այն տասնութ մարդիկ, որոնց վրայ Սիլովամում աշտարակը փուլ եկաւ եւ սպանեց նրանց, կարծում էք, թէ աւելի մեղապա՞րտ էին, քան Երուսաղէմում բնակուող բոլոր մարդիկ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Ո՛չ, ասում եմ ձեզ, սակայն եթէ չապաշխարէք, ամէնքդ էլ նոյնպէս պիտի կորչէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Պատմեց եւ այս առակը. «Մի մարդ իր այգում մի թզենի էր տնկել. եւ երբ պտղի ժամանակը հասաւ, նա եկաւ նրա վրայ պտուղ փնտռելու ու չգտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Այգեգործին ասաց. «Ահա երեք տարի է, որ գալիս եմ այդ թզենու վրայ պտուղ փնտռելու եւ չեմ գտնում. արդ, կտրի՛ր այդ. ինչո՞ւ է հողն զբաղեցնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Այգեգործը պատասխանեց եւ ասաց. «Տէ՛ր իմ, նրան այս տարի էլ թո՛ղ, մինչեւ որ նրա շուրջը փորեմ եւ աղբ գցեմ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'գուցէ թէ պտուղ տայ. ապա թէ ոչ՝ մի տարուց յետոյ կը կտրես այդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Եւ մի շաբաթ օր Յիսուս մի ժողովարանում ուսուցանում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Եւ ահա այնտեղ կար մի կին, որին չար դեւը տասնութ տարի բռնած էր պահում. եւ կուչ էր եկած ու ամենեւին վեր նայել չէր կարողանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Եւ Յիսուս նրան տեսնելով՝ կանչեց իր մօտ եւ ասաց. «Ո՛վ կին, բժշկուած ես քո հիւանդութիւնից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Եւ ձեռքը դրեց նրա վրայ, ու նոյն ժամին հիւանդը ուղղուեց եւ Աստծուն փառք էր տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Ժողովրդապետը բարկացաւ, թէ ինչո՛ւ Յիսուս շաբաթ օրով բուժեց. եւ ասաց ժողովրդին. «Վեց օր կայ, երբ արժան է գործել, ա՛յդ օրերին եկէք բուժուեցէք եւ ոչ թէ շաբաթ օրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Տէրը նրան պատասխանեց եւ ասաց. «Կեղծաւորնե՛ր, ձեզնից իւրաքանչիւր ոք շաբաթ օրով իր եզը կամ էշը մսուրից չի՞ արձակում եւ չի՞ տանում ջուր տալու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Իսկ սա Աբրահամի դուստրն էր, որին սատանան ահա տասնութ տարի է, ինչ կապել էր, - արժանի չէ՞ր միթէ շաբաթ օրով արձակել նրան կապանքներից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Եւ երբ այս ասաց, ամաչեցին նրանք, որոնք հակառակում էին նրան. իսկ ամբողջ ժողովուրդը ուրախանում էր այն բոլոր փառաւոր գործերի համար, որ կատարւում էին Յիսուսի կողմից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Եւ ասաց. «Ինչի՞ նման է Աստծու արքայութիւնը, եւ ինչի՞ նմանեցնեմ այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Նման է մանանեխի հատիկին, որ մի մարդ վերցրեց եւ նետեց իր պարտէզը: Սա աճեց եւ ծառ եղաւ, եւ երկնքի թռչունները ապրում էին նրա ճիւղերի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Եւ դարձեալ ասաց. «Ինչի՞ նմանեցնեմ Աստծու արքայութիւնը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'նման է այն խմորին, որ մի կին, վերցնելով, խառնեց երեք գրիւ ալիւրի մէջ, մինչեւ որ ամբողջը խմորուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Եւ Յիսուս շրջում էր քաղաքներով ու գիւղերով եւ ուսուցանում էր: Երբ ճանապարհ էր ընկել դէպի Երուսաղէմ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'մէկը նրան ասաց. «Տէ՛ր, սակաւաթի՞ւ են նրանք, որ փրկուելու են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Եւ նա նրանց ասաց. «Ջանացէ՛ք մտնել նեղ դռնով. ասում եմ ձեզ, որ շատերը կ՚ուզենան մտնել, բայց չեն կարողանայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Այն բանից յետոյ, երբ տանտէրը մտնի եւ դուռը փակի, դուք, դրսում կանգնած, կը սկսէք դուռը բախել եւ ասել. «Տէ՛ր, տէ՛ր, բա՛ց մեզ համար». իսկ նա պատասխանելով կ՚ասի ձեզ. «Չգիտեմ, թէ որտեղից էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Այն ժամանակ կը սկսէք ասել. «Մենք քո առաջ կերանք եւ խմեցինք, եւ դու հրապարակներում ուսուցանեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Եւ տանտէրը կ՚ասի. «Ասում եմ՝ ձեզ չգիտեմ, թէ որտեղից էք. հեռացէ՛ք ինձնից դուք՝ բոլոր անիրաւ մշակներդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Այնտեղ կը լինի լաց եւ ատամների կրճտում, երբ տեսնէք Աբրահամին, Իսահակին, Յակոբին եւ բոլոր մարգարէներին Աստծու արքայութեան մէջ, իսկ ձեզ՝ դուրս հանուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Եւ կը գան մարդիկ արեւելքից եւ արեւմուտքից, հիւսիսից եւ հարաւից ու կը բազմեն Աստծու արքայութեան մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Եւ ահա վերջիններ կան, որ առաջին կը լինեն, եւ առաջիններ՝ որ կը լինեն վերջին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Նոյն օրը մի քանի փարիսեցիներ մօտեցան եւ ասացին նրան. «Վե՛ր կաց, գնա՛ այստեղից, որովհետեւ Հերովդէսն ուզում է քեզ սպանել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Եւ Յիսուս նրանց ասաց. «Գնացէք ասացէ՛ք այն աղուէսին, թէ ահա դեւեր եմ հանում, բուժումներ եմ կատարում այսօր եւ վաղը, իսկ երրորդ օրը գործս կ՚աւարտեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Բայց պէտք է այսօր, վաղը եւ միւս օրը գնալ. որովհետեւ մարգարէն պէտք չէ, որ Երուսաղէմից դուրս կորստեան մատնուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, '«Երուսաղէ՜մ, Երուսաղէ՜մ, որ կոտորում էիր մարգարէներին եւ քարկոծում էիր քեզ մօտ ուղարկուածներին. քանի՜ քանի՜ անգամ կամեցայ հաւաքել քո որդիներին, ինչպէս հաւը իր ձագերին՝ թեւերի տակ, բայց դու չկամեցար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Ահա ձեր տունը ձեզ պիտի թողնուի աւերակ. բայց ասում եմ ձեզ, որ ինձ այլեւս չէք տեսնի, մինչեւ որ չասէք՝ «Օրհնեա՜լ է նա, որ գալիս է Տիրոջ անունով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Երբ մի շաբաթ օր նա մտաւ փարիսեցիների իշխանաւորներից մէկի տունը հաց ուտելու, նրանք դիտում էին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Եւ ահա այնտեղ, նրա առաջ ջրգողով հիւանդ մի մարդ կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Յիսուս պատասխանեց օրէնսգէտներին ու փարիսեցիներին եւ ասաց. «Շաբաթ օրով բժշկելը օրինաւո՞ր է, թէ՞՝ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Նրանք լուռ մնացին: Յիսուս նրան բռնելով՝ բուժեց եւ արձակեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Եւ նրանց ասաց. «Ձեզնից ո՞ւմ եզը կամ էշը ընկնի ջրհորի մէջ, նա իսկոյն այն չի հանի շաբաթ օրով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Եւ այդ մասին նրան պատասխան տալ չկարողացան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Հրաւիրուածներին էլ մի առակ ասաց՝ տեսնելով, թէ ինչպէս նրանք պատուոյ տեղերն էին ընտրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Նրանց ասաց. «Երբ մէկը քեզ հարսանիքի կամ հրաւէրքի կանչի, առաջին տեղը մի՛ նստիր, գուցէ քեզնից աւելի պատուական մէկը նրա կողմից կանչուած լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Եւ քեզ ու նրան կանչողը գայ ու քեզ ասի՝ «Սրան տե՛ղ տուր»: Եւ ապա սկսես ամօթով վերջին տեղը գրաւել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Այլ, երբ հրաւիրուես, գնա բազմի՛ր վերջին տեղը, որպէսզի, երբ քեզ կանչողը գայ եւ քեզ ասի՝ «Բարեկա՛մ, աւելի վե՛ր մօտեցիր», այն ժամանակ քո սեղանակիցների առաջ դու փառաւորուես.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'որովհետեւ նա, ով ինքն իրեն բարձրացնում է, պիտի խոնարհուի, եւ նա, ով ինքն իրեն խոնարհեցնում է, պիտի բարձրանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Իրեն հրաւիրողին էլ ասաց. «Երբ ճաշ կամ ընթրիք ես տալիս, մի՛ կանչիր ո՛չ քո բարեկամներին, ո՛չ քո եղբայրներին, ո՛չ քո ազգականներին եւ ո՛չ էլ քո հարուստ հարեւաններին, որպէսզի նրանք էլ փոխարէնը քեզ չհրաւիրեն, եւ քեզ հատուցում լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Այլ, երբ ընդունելութիւն անես, կանչի՛ր աղքատներին, խեղանդամներին, կաղերին ու կոյրերին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'եւ երանելի կը լինես, որովհետեւ փոխարէնը քեզ հատուցելու ոչինչ չունեն: Եւ դրա փոխարէն քեզ կը հատուցուի արդարների յարութեան օրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Երբ սեղանակիցներից մէկը այս լսեց, ասաց նրան. «Երանի՜ նրան, ով ճաշ կ՚ուտի Աստծու արքայութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Եւ Յիսուս ասաց. «Մի մարդ ընթրիք սարքեց եւ հրաւիրեց շատերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Եւ ընթրիքի ժամին իր ծառային ուղարկեց՝ կանչելու հրաւիրուածներին, թէ՝ «Եկէ՛ք, որովհետեւ ահա ամէն ինչ պատրաստ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Եւ ամէնքը մէկ-մէկ սկսեցին հրաժարուել: Առաջինն ասաց. «Ագարակ գնեցի եւ պէտք է, որ գնամ տեսնեմ. խնդրում եմ քեզ, ինձ հրաժարուա՛ծ համարիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Եւ միւսն ասաց. «Հինգ լուծ եզներ գնեցի. գնում եմ դրանք փորձելու. խնդրում եմ քեզ, ինձ հրաժարուա՛ծ համարիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Իսկ միւսն ասաց. «Կին եմ առել, դրա համար էլ չեմ կարող գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Եւ ծառան եկաւ ու իր տիրոջը պատմեց այս: Այդ ժամանակ, բարկանալով, տանտէրն իր ծառային ասաց. «Իսկոյն դո՛ւրս եկ քաղաքի հրապարակներն ու փողոցները եւ աղքատներին, խեղանդամներին, կաղերին ու կոյրերին բեր մտցրո՛ւ այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Եւ ծառան ասաց. «Տէ՛ր, ինչ հրամայեցիր՝ կատարուեց եւ էլի տեղ կայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Եւ տէրը ծառային ասաց. «Դո՛ւրս եկ ճանապարհներն ու ցանկապատների առաջ եւ մարդկանց այստեղ մտցրո՛ւ, որպէսզի տունս լցուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Ասում եմ ձեզ, որ այդ հրաւիրուածներից ոչ ոք իմ ընթրիքից չի ճաշակի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Եւ նրա հետ շատ ժողովուրդ էր գնում. նա դարձաւ եւ ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '«Եթէ մէկը ինձ մօտ գայ եւ չնախընտրի ինձ իր հօրից ու մօրից, կնոջից ու որդիներից, եղբայրներից ու քոյրերից, նոյնիսկ իր անձից անգամ, չի կարող իմ աշակերտը լինել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'որովհետեւ, ով որ չվերցնի իր խաչը եւ իմ յետեւից չգայ, չի կարող իմ աշակերտը լինել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Ձեզնից ո՞վ, եթէ կամենայ աշտարակ շինել, նախ նստելով չի հաշուի իր ծախսերը, թէ աւարտելու համար բաւական դրամ ունի՞,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'որպէսզի, գուցէ, երբ հիմը դնի եւ չկարողանայ աւարտել, բոլոր նրանք, որ տեսնեն, չսկսեն նրան ծաղրել');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'եւ ասել, թէ՝ «Այս մարդը սկսեց կառուցել եւ չկարողացաւ աւարտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Կամ ո՞ր թագաւորը, եթէ գնայ պատերազմելու մի այլ թագաւորի դէմ, նախ չի նստի եւ խորհի, թէ տասը հազարով կը կարողանա՞յ դիմադրել նրան, որ իր վրայ քսան հազարով է գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Ապա թէ ոչ, մինչ սա դեռ հեռու է, պատգամաւորութիւն ուղարկելով՝ խաղաղութիւն կը խնդրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Արդ, այսպէս էլ՝ ձեզնից ով որ իր ամբողջ ունեցուածքից չհրաժարուի, չի կարող իմ աշակերտը լինել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, '«Աղը լաւ բան է, բայց եթէ աղն էլ անհամանայ, ինչո՞վ այն պիտի համեմուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Ո՛չ հողի համար է պիտանի եւ ո՛չ էլ՝ պարարտանիւթի, այլ՝ դուրս թափելու: Ով որ ականջ ունի լսելու, թող լսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Եւ բոլոր մաքսաւորներն ու մեղաւորները նրա մօտն էին, որպէսզի լսեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Փարիսեցիներն ու օրէնսգէտները տրտնջում էին եւ ասում. «Ինչո՞ւ է սա ընդունում մեղաւորներին եւ ուտում նրանց հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Յիսուս նրանց այս առակն ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '«Ձեզնից ո՞վ է այն մարդը, որ, երբ հարիւր ոչխար ունենայ եւ կորցնի նրանցից մէկը, արօտավայրում չի թողնի իննսունիննին եւ չի գնայ կորածի յետեւից, մինչեւ որ այն գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Եւ երբ այն գտնի, կը դնի այն իր ուսերի վրայ խնդութեամբ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'եւ կը գնայ տուն, կը կանչի բարեկամներին եւ հարեւաններին ու նրանց կ՚ասի. ուրախացէ՛ք ինձ հետ, որովհետեւ գտայ իմ կորած ոչխարը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Ասում եմ ձեզ, որ այսպէս ուրախութիւն կը լինի երկնքում մի մեղաւորի համար, որն ապաշխարում է, քան իննսունինը արդարների համար, որոնց ապաշխարութիւն պէտք չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Կամ՝ ո՞վ է այն կինը, որ, երբ տասը դրամ ունենայ եւ մի դրամ կորցնի, ճրագ չի վառի եւ չի աւլի տունը փութով ու չի փնտռի, մինչեւ որ գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Եւ երբ գտնի, կը կանչի բարեկամներին եւ հարեւաններին ու կ՚ասի. «Ուրախացէ՛ք ինձ հետ, որովհետեւ գտայ իմ կորցրած դրամը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Ասում եմ ձեզ, Աստծու հրեշտակների առաջ այսպէս ուրախութիւն կը լինի մէկ մեղաւորի համար, որն ապաշխարում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Եւ ասաց. «Մի մարդ երկու որդի ունէր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'նրանցից կրտսերը հօրն ասաց. «Հա՛յր, տո՛ւր քո ունեցուածքից ինձ ընկնող բաժինը»: Եւ նա ունեցուածքը բաժանեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Քիչ օրեր յետոյ, կրտսեր որդին, փողի վերածելով ամէն ինչ, գնաց հեռու աշխարհ եւ այնտեղ վատնեց իր ունեցուածքը, որովհետեւ անառակ կեանքով էր ապրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Եւ երբ ամէն ինչ սպառեց, այդ երկրում սաստիկ սով եղաւ, եւ նա սկսեց չքաւոր դառնալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Գնաց դիմեց այդ երկրի քաղաքացիներից մէկին, եւ սա ուղարկեց նրան իր ագարակը՝ խոզեր արածեցնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Եւ նա ցանկանում էր իր որովայնը լցնել եղջերենու պտղով, որ խոզերն էին ուտում, բայց ոչ ոք այդ նրան չէր տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Ապա խելքի եկաւ եւ ասաց. «Քանի՜ վարձու աշխատաւորներ կան իմ հօր տանը, որ առատ հաց ունեն, եւ ես այստեղ սովամահ կորչում եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Վեր կենամ գնամ իմ հօր մօտ եւ նրան ասեմ. հա՛յր, մեղանչեցի երկնքի դէմ ու քո առաջ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'եւ այլեւս արժանի չեմ քո որդին կոչուելու, ինձ վերցրո՛ւ իբրեւ քո աշխատաւորներից մէկը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Եւ վեր կացաւ եկաւ իր հօր մօտ. եւ մինչ դեռ հեռու էր, հայրը տեսաւ նրան եւ գթաց. վեր կացաւ եւ վազեց նրան ընդառաջ, ընկաւ նրա պարանոցով եւ համբուրեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Եւ որդին ասաց նրան. «Հա՛յր, մեղանչեցի երկնքի դէմ եւ քո առաջ, այլեւս արժանի չեմ քո որդին կոչուելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Հայրը իր ծառաներին ասաց. «Անմիջապէս հանեցէ՛ք նրա նախկին պատմուճանը եւ հագցրէ՛ք նրան, մատանին նրա մատը դրէք եւ նրա ոտքերին՝ կօշիկներ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'բերէ՛ք պարարտ եզը, մորթեցէ՛ք, ուտենք եւ ուրախ լինենք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'որովհետեւ իմ այս որդին մեռած էր եւ կենդանացաւ, կորած էր եւ գտնուեց». եւ սկսեցին ուրախանալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Իսկ նրա աւագ որդին ագարակում էր. եւ մինչ գալիս էր եւ տանը մօտեցաւ, լսեց երգերի եւ պարերի ձայնը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'եւ իր մօտ կանչելով ծառաներից մէկին՝ հարցրեց, թէ այդ ի՞նչ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Եւ սա նրան ասաց. «Քո եղբայրը եկել է, եւ քո հայրը մորթեց պարարտ եզը, որովհետեւ ողջ առողջ ընդունեց նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Նա բարկացաւ եւ չէր ուզում ներս մտնել. իսկ հայրը դուրս ելնելով՝ աղաչում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Որդին պատասխանեց եւ ասաց հօրը. «Այս քանի՜ տարի է, որ ծառայում եմ քեզ եւ երբեք քո հրամանները զանց չեմ արել. ինձ երբեք մի ուլ չտուիր, որ բարեկամներիս հետ ուրախութիւն անէի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Երբ եկաւ քո այդ որդին, որը քո ունեցուածքը կերաւ պոռնիկների հետ, պարարտ եզը նրա համար մորթեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Հայրը նրան ասաց. «Որդեա՛կ, դու միշտ ինձ հետ ես, եւ ամէն ինչ, որ իմն է, քոնն է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'բայց պէտք էր ուրախ լինել եւ ցնծալ, որովհետեւ քո այս եղբայրը մեռած էր եւ կենդանացաւ, կորած էր եւ գտնուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Եւ Յիսուս իր աշակերտներին ասաց. «Մի մեծահարուստ մարդ կար, որ մի տնտես ունէր. եւ նրա մասին ամբաստանութիւն եղաւ, որպէս թէ վատնում է իր տիրոջ ունեցուածքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Տէրը կանչեց նրան եւ ասաց. «Այս ի՞նչ եմ լսում քո մասին. տո՛ւր քո տնտեսութեան հաշիւը, որովհետեւ այլեւս տնտես լինել չես կարող»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Տնտեսը իր մտքում ասաց. «Ի՞նչ պէտք է անեմ, քանի որ իմ տէրը տնտեսութիւնս ինձնից վերցնում է. հողի վրայ աշխատել չեմ կարող, մուրալ ամաչում եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Գիտեմ, թէ ինչ պիտի անեմ, որպէսզի, երբ տնտեսութիւնիցս հեռացուեմ, ընդունեն ինձ իրենց տները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Եւ իր տիրոջ պարտապաններից իւրաքանչիւրին մէկ առ մէկ իր մօտ կանչելով՝ առաջինին ասում է՝ «Իմ տիրոջը ինչքա՞ն պարտք ունես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Եւ սա ասում է՝ «Հարիւր տակառիկ ձէթ». եւ տնտեսը նրան ասում է՝ «Ա՛ռ քո մուրհակը եւ նստի՛ր ու անմիջապէս գրի՛ր՝ յիսուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Ապա դարձեալ միւսին ասում է՝ «Դու ինչքա՞ն պարտք ունես». եւ սա ասաց՝ «Հինգ հարիւր պարկ ցորեն»: Տնտեսը նրան ասաց՝ «Ա՛ռ քո մուրհակը եւ նստի՛ր ու գրի՛ր՝ չորս հարիւր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Եւ տէրը գովեց անիրաւ տնտեսին, որովհետեւ հնարամտութեամբ գործեց, քանի որ այս աշխարհի որդիները աւելի հնարամիտ են, քան լոյսի որդիները իրենց սերնդի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, '«Եւ ես ձեզ ասում եմ. անիրաւ մամոնայից ձեզ համար բարեկամներ արէք, որպէսզի, երբ այն պակասի, յաւիտենական յարկերի տակ ընդունեն ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Քիչ բանի մէջ հաւատարիմը շատի մէջ էլ հաւատարիմ է. իսկ քչի մէջ անիրաւը, շատի մէջ էլ անիրաւ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Արդ, եթէ անիրաւ մամոնայի մէջ հաւատարիմ չեղաք, ձեզ ո՞վ կը վստահի ճշմարիտը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Եւ եթէ օտարինը եղող բանի մէջ հաւատարիմ չեղաք, ձերը ո՞վ կը տայ ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Ոչ մի ծառայ երկու տիրոջ ծառայել չի կարող. որովհետեւ, եթէ մէկին ատի, միւսին կը սիրի. կամ եթէ մէկին մեծարի, միւսին էլ կ՚արհամարհի: Չէք կարող ե՛ւ Աստծուն ծառայել, ե՛ւ մամոնային»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Երբ փարիսեցիները լսում էին այս բոլորը, նրան պախարակում էին, քանի որ արծաթասէր էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Եւ նրանց ասաց. «Դուք էք, որ մարդկանց առաջ ձեզ արդար էք ձեւացնում, սակայն Աստուած ձեր սրտերը գիտէ. որովհետեւ այն, որ մարդկանց առաջ բարձր է, Աստծու առաջ զազրելի է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Օրէնքն ու մարգարէները մինչեւ Յովհաննէսն էին. այնուհետեւ աւետարանւում է Աստծու արքայութիւնը, եւ ամէն ոք բռնի է ուզում ձեռք բերել այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Աւելի հեշտ է, որ երկինք ու երկիր անցնեն, քան թէ օրէնքից մէկ նշանախեց ընկնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Ով որ իր կնոջն արձակում է եւ մի ուրիշին առնում, շնանում է. իսկ ով որ արձակուածին է առնում, շնանում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '«Մի մեծահարուստ մարդ կար, որ բեհեզ ու ծիրանի էր հագնում եւ ամէն օր առատապէս ուրախութիւն էր անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Եւ Ղազարոս անունով մի աղքատ մարդ ընկած էր նրա դռան առաջ՝ վէրքերով ծածկուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Եւ ցանկանում էր լցնել իր որովայնը այն փշրանքներով, որոնք թափւում էին մեծահարուստի սեղանից: Եւ դեռ շներն էլ գալիս էին ու լիզում նրա վէրքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Երբ աղքատը մեռաւ, հրեշտակները նրան տարան Աբրահամի գոգը. մեծահարուստն էլ մեռաւ եւ թաղուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Եւ դժոխքում, մինչ սա տանջանքների մէջ էր, բարձրացրեց իր աչքերը, հեռուից տեսաւ Աբրահամին եւ Ղազարոսին էլ՝ նրա գրկում հանգստացած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Եւ նա աղաղակեց ու ասաց. «Հա՛յր Աբրահամ, ողորմի՛ր ինձ եւ ուղարկի՛ր Ղազարոսին, որ իր մատի ծայրը թրջի ջրով եւ զովացնի լեզուս, որովհետեւ այս տապից պապակում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Եւ Աբրահամը նրան ասաց. «Որդեա՛կ, յիշի՛ր, որ դու ստացար քո բարիքները այնտեղ, քո կեանքի ընթացքում, իսկ Ղազարոսն էլ՝ չարչարանքները. այժմ սա այստեղ մխիթարւում է, իսկ դու այդտեղ պապակում ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Եւ այս բոլորից բացի, մեծ վիհ կայ մեր եւ ձեր միջեւ. եթէ ուզենան այստեղից ձեզ մօտ անցնել, չեն կարողանայ. ոչ էլ այդտեղից մէկը կարող է մեզ մօտ անցնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Մեծահարուստն ասաց. «Արդ, աղաչում եմ քեզ, հա՛յր, որ Ղազարոսին ուղարկես իմ հօր տունը, -');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'որտեղ ես հինգ եղբայրներ ունեմ, - որպէսզի նրանց վկայութիւն տայ, որ նրանք էլ չգան տանջանքների այս վայրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Եւ Աբրահամն ասաց. «Նրանք ունեն Մովսէս եւ մարգարէներ, թող նրա՛նց լսեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Եւ նա ասաց. «Ո՛չ, հա՛յր Աբրահամ. բայց եթէ մեռելներից մէկը նրանց մօտ գնայ, նրանք կ՚ապաշխարեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Եւ Աբրահամը նրան ասաց. «Եթէ Մովսէսին եւ մարգարէներին չեն լսում, մեռելներից մէկն էլ եթէ յարութիւն առնի, չպիտի համոզուեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Յիսուս ասաց նաեւ իր աշակերտներին. «Անկարելի է, որ գայթակղութիւն չգայ, բայց վա՜յ նրան, որի ձեռքով կը գայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Նրա համար լաւ կը լինէր, եթէ իր պարանոցից երկանաքար վէմ կախուէր, եւ նա ծովը գցուէր, քան թէ այս փոքրիկներից մէկին գայթակղեցնէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Զգո՛յշ եղէք ձեր անձերի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, '«Եթէ քո եղբայրը մեղանչի, սաստի՛ր նրան. եւ եթէ զղջայ, ների՛ր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Եւ եթէ եօթն անգամ մեղանչի քո դէմ եւ եօթն անգամ դառնայ քեզ եւ ասի՝ զղջում եմ, ների՛ր նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Եւ առաքեալները Տիրոջն ասացին. «Աւելացրո՛ւ մեր հաւատը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Եւ Տէրն ասաց. «Եթէ մանանեխի հատիկի չափ հաւատ ունենաք եւ այս թթենուն ասէ՛ք՝ «Արմատախի՛լ եղիր եւ տնկուի՛ր ծովի մէջ», նա՛ իսկ կը հնազանդուի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, '«Իսկ ձեզնից ո՞վ, որ հողագործ կամ հովիւ ծառայ ունի, երբ սա ագարակից տուն մտնի, նրան կ՚ասի իսկոյն՝ «Անցի՛ր սեղան նստիր».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'այլ նրան չի՞ ասի՝ «Պատրաստի՛ր, ինչ ընթրելու եմ, եւ գօտի կապած՝ ծառայի՛ր ինձ, մինչեւ որ ուտեմ եւ խմեմ, եւ ապա կ՚ուտես եւ կը խմես դու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Միթէ տէրը շնորհապա՞րտ կը լինի այդ ծառային, որ իր բոլոր հրամանները կատարեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Նոյնպէս եւ դուք, երբ կատարէք այն բոլորը, որ ձեզ հրամայուած է, ասացէք, թէ՝ «Անպիտան ծառաներ ենք. ինչ որ պարտաւոր էինք անել, ա՛յն արեցինք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Եւ մինչ նա դէպի Երուսաղէմ էր գնում, անցնում էր Սամարիայի եւ Գալիլիայի միջով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Եւ երբ մի գիւղ էր մտնում, նրան հանդիպեցին տասը բորոտներ, որոնք հեռու կանգնեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'բարձրացրին իրենց ձայնը եւ ասացին. «Յիսո՛ւս վարդապետ, ողորմի՛ր մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Եւ երբ նրանց տեսաւ, ասաց նրանց. «Գնացէ՛ք դուք ձեզ քահանաներին ցոյց տուէք»: Երբ գնում էին, նոյն ժամին մաքրուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Նրանցից մէկը, երբ տեսաւ, թէ բժշկուեց, վերադարձաւ եւ բարձր ձայնով փառաւորում էր Աստծուն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'երեսի վրայ ընկաւ Յիսուսի ոտքերի առաջ եւ շնորհակալութիւն էր յայտնում նրան. եւ ինքը սամարացի էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Յիսուս պատասխանեց եւ ասաց. «Սրանք տասն էլ չմաքրուեցի՞ն. իսկ արդ, իննը ո՞ւր են,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'որ չվերադարձան՝ փառք տալու համար Աստծուն, բացի միայն այս օտարազգի մարդուց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Եւ ասաց նրան. «Վե՛ր կաց գնա, որովհետեւ քո հաւատը քեզ փրկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Երբ փարիսեցիների կողմից հարց տրուեց, թէ ե՞րբ պիտի գայ Աստծու արքայութիւնը, նա պատասխանեց եւ ասաց. «Աստծու արքայութիւնը դրսից տեսանելի կերպով չի գալիս,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'եւ չեն ասի, թէ՝ ահաւասիկ այստեղ է կամ այնտեղ, որովհետեւ ահա Աստծու արքայութիւնը ներսում, ձեր մէջ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Իսկ իր աշակերտներին ասաց. «Կը գան օրեր, երբ դուք կ՚ուզենաք մարդու Որդու օրերից մէկը տեսնել, եւ չէք տեսնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Եւ եթէ ձեզ ասեն, թէ՝ «Ահաւասիկ այստեղ է կամ այնտեղ», մի՛ շտապէք գնալու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'որովհետեւ, ինչպէս որ փայլակը երկնքի ներքեւից փայլատակելով՝ երկնքի երեսը լուսաւորում է, այնպէս էլ կը լինի մարդու Որդին՝ իր օրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Բայց նախ նա պէտք է շատ չարչարուի եւ մերժուի այս սերնդից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Եւ ինչպէս եղաւ Նոյի օրով, այնպէս կը լինի եւ մարդու Որդու օրով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Ուտում էին, խմում, կին էին առնում եւ մարդու էին գնում, մինչեւ այն օրը, երբ Նոյը տապան մտաւ, եւ ջրհեղեղը եկաւ ու բոլորին կորստեան մատնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Նոյնպէս, ինչպէս Ղովտի օրով էլ եղաւ. ուտում էին, խմում, առնում էին ու վաճառում, տնկում էին, շինում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Եւ այն օրը, երբ Ղովտը Սոդոմից դուրս ելաւ, երկնքից կրակ եւ ծծումբ տեղաց ու բոլորին կորստեան մատնեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Նոյն ձեւով է լինելու այն օրն էլ, երբ մարդու Որդին է յայտնուելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Այն օրը, ով որ տանիքում է, եւ իր կարասին՝ տանը, թող չիջնի առնելու այն. եւ ով որ հանդում է, նոյնպէս թող յետ չդառնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Յիշեցէ՛ք Ղովտի կնոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ով որ ուզի իր անձը փրկել, պիտի կորցնի այն, իսկ ով որ կորցնի իր անձը, պիտի փրկի այն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Ասում եմ ձեզ, այն գիշերը, եթէ երկու հոգի լինեն մի մահճի մէջ, մէկը պիտի վերցուի, իսկ միւսը՝ թողնուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Եւ եթէ երկու կին միասին աղալիս լինեն, մէկը պիտի վերցուի, իսկ միւսը՝ թողնուի: Եւ եթէ հանդում երկու հոգի լինեն, մէկը պիտի վերցուի, իսկ միւսը՝ թողնուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Պատասխան տուին եւ ասացին նրան. «Որտե՞ղ, Տէ՛ր»: Եւ նա ասաց նրանց. «Ուր որ մարմինն է, այնտեղ էլ կը հաւաքուեն արծիւները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Մի առակ էլ ասաց նրանց այն մասին, թէ նրանք ամէն ժամ պէտք է աղօթեն ու չձանձրանան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Ասաց. «Մի քաղաքում մի դատաւոր կար. Աստծուց չէր վախենում եւ մարդկանցից չէր ամաչում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Եւ նոյն քաղաքում մի այրի կար, որ գալիս էր նրա մօտ եւ ասում. «Իմ ոսոխի դէմ իմ դատը տես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Եւ դատաւորը երկար ժամանակ չէր ուզում. դրանից յետոյ իր մտքում ասաց. «Թէեւ Աստծուց չեմ վախենում եւ մարդկանցից չեմ ամաչում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'բայց այն բանի համար, որ այրի կինը ինձ յոգնեցնում է, նրա դատը տեսնեմ, որպէսզի անընդհատ չգայ եւ ինձ չանհանգստացնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Եւ Տէրն ասաց. «Լսեցէ՛ք, թէ ինչ էր ասում անիրաւ դատաւորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Իսկ Աստուած արդարութիւն չի՞ անի իր այն ծառաներին, որոնք գիշեր եւ ցերեկ աղաղակում են. եւ նրանց հանդէպ միայն համբերատա՞ր կը լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Այո՛, ասում եմ ձեզ, նրանց իսկոյն արդարութիւն կ՚անի. իսկ երբ մարդու Որդին գայ, արդեօք երկրի վրայ հաւատ կը գտնի՞»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Այս առակն էլ ասաց ոմանց, որոնք իրենք իրենցով պարծենում էին, թէ արդար են, եւ արհամարհում էին ուրիշ շատերին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '«Երկու մարդ տաճար ելան աղօթքի կանգնելու. մէկը՝ փարիսեցի, միւսը՝ մաքսաւոր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Փարիսեցին կանգնած էր մեկուսի եւ, ինքն իրեն, այս աղօթքն էր ասում. «Աստուած իմ, շնորհակալ եմ քեզնից, որ ես նման չեմ ուրիշ մարդկանց, ինչպէս՝ յափշտակողները, անիրաւներն ու շնացողները, եւ կամ ինչպէս այս մաքսաւորը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'այլ շաբաթը երկու անգամ ծոմ եմ պահում եւ տասանորդ եմ տալիս իմ ամբողջ եկամտից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Իսկ մաքսաւորը կանգնած էր մեկուսի եւ չէր իսկ կամենում իր աչքերը երկինք բարձրացնել, այլ ծեծում էր կուրծքը եւ ասում. «Աստուա՛ծ, ների՛ր ինձ՝ մեղաւորիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ասում եմ ձեզ, սա՛ իջաւ իր տունը արդարացած, ոչ թէ միւսը. որովհետեւ, ով որ բարձրացնում է իր անձը, կը խոնարհուի, եւ ով որ խոնարհեցնում է իր անձը, կը բարձրացուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Մանուկներին էլ մօտեցնում էին նրան, որպէսզի նրանց դիպչի. երբ աշակերտները այդ տեսան, սաստեցին բերողներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Իսկ Յիսուս կանչելով մանուկներին իր մօտ՝ ասաց. «Թո՛յլ տուէք այդ մանուկներին, որ ինձ մօտ գան, եւ մի՛ արգելէք նրանց, որովհետեւ այդպիսիներինն է Աստծու արքայութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Ճշմարիտ եմ ասում ձեզ, ով որ Աստծու արքայութիւնը չընդունի ինչպէս մի մանուկ, այնտեղ չի մտնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Մի իշխանաւոր նրան հարցրեց եւ ասաց. «Բարի՛ Վարդապետ, ի՞նչ պիտի անեմ, որ յաւիտենական կեանքը ժառանգեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Յիսուս նրան ասաց. «Ինչո՞ւ ինձ բարի ես կոչում. ոչ ոք բարի չէ, այլ միայն՝ Աստուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Պատուիրանները գիտես՝ մի՛ շնացիր, մի՛ սպանիր, մի՛ գողացիր, սուտ մի՛ վկայիր, մեծարի՛ր քո հօրը եւ մօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Եւ նա ասաց. «Այդ բոլորը պահել եմ իմ մանկութիւնից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Երբ Յիսուս այս լսեց, ասաց նրան. «Դեռ մի բան պակաս է քեզ. ինչ որ ունես, վաճառի՛ր եւ տո՛ւր աղքատներին եւ երկնքում գանձեր կ՚ունենաս, եւ արի՛ իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Երբ նա այս լսեց, տրտմեց, որովհետեւ չափազանց հարուստ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Երբ Յիսուս նրան տեսաւ տրտմած, ասաց. «Ինչքա՜ն դժուարութեամբ Աստծու արքայութիւնը կը մտնեն նրանք, որոնք հարստութիւն ունեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Աւելի հեշտ է, որ պարանը ասեղի ծակից անցնի, քան թէ մի մեծահարուստ Աստծու արքայութիւնը մտնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Եւ նրանք, որ լսեցին, ասացին. «Իսկ ո՞վ կարող է փրկուել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Եւ նա ասաց. «Ինչ որ անհնար է մարդկանց համար, Աստծու համար հնարաւոր է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Եւ Պետրոսն ասաց. «Ահա մենք մեր ամէն ինչը թողեցինք եւ եկանք քո յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Եւ Յիսուս ասաց նրանց. «Ճշմարիտ եմ ասում ձեզ, չկայ մէկը, որ թողած լինի տունը, կամ ծնողներին, կամ եղբայրներին, կամ կնոջը, կամ զաւակներին՝ Աստծու արքայութեան համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'եւ այս ներկայ ժամանակում բազմապատիկ չստանայ ու յաւիտենական կեանքը չժառանգի այն աշխարհում, որ գալու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Եւ Տասներկուսին, առանձին, մի կողմ տանելով՝ նրանց ասաց. «Ահաւասիկ ելնում ենք դէպի Երուսաղէմ, եւ մարգարէների միջոցով մարդու Որդու մասին բոլոր գրուածները պիտի կատարուեն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'որովհետեւ նա պիտի մատնուի հեթանոսներին եւ պիտի ծաղրուի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'նրան պիտի ձաղկեն ու սպանեն, եւ երրորդ օրը յարութիւն պիտի առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Եւ առաքեալները այս բոլորից ոչինչ չիմացան, այլ խօսքը նրանցից ծածկուած էր, եւ ասուածները չէին ըմբռնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Եւ երբ նա մօտենում էր Երիքովին, ճանապարհի վրայ նստել էր մի կոյր մուրացկան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Երբ սա լսեց, որ ժողովուրդը անցնում է, հարցրեց, թէ՝ այդ ի՞նչ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Եւ նրան պատմեցին, թէ անցնում է Յիսուս Նազովրեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Նա աղաղակեց եւ ասաց. «Յիսո՛ւս, Դաւթի՛ Որդի, ողորմի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Եւ առջեւից գնացողները սաստեցին նրան, որ լռի: Իսկ նա առաւել եւս աղաղակում էր. «Դաւթի՛ Որդի, ողորմի՛ր ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Յիսուս տեղում կանգնեց եւ հրամայեց իր մօտ բերել նրան. եւ երբ կոյրը մօտեցաւ, նրան հարցրեց եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '«Ի՞նչ ես կամենում դու, որ ես քեզ համար անեմ»: Եւ սա ասաց. «Որ բացուեն աչքերս, եւ տեսնեմ, Տէ՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Եւ Յիսուս նրան ասաց. «Նայի՛ր. քո հաւատը քեզ փրկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Եւ իսկոյն կոյրը տեսաւ. գնում էր Յիսուսի յետեւից եւ փառք էր տալիս Աստծուն: Եւ ամբողջ ժողովուրդը տեսնելով այս՝ Աստծուն գոհութիւն էր տալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Եւ Յիսուս մտել էր Երիքով ու շրջում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Եւ ահա մի մարդ, Զակքէոս անունով, որ մաքսապետ էր ու մեծահարուստ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'ուզում էր տեսնել, թէ ո՛վ է Յիսուս, բայց բազմութեան պատճառով չէր կարողանում, որովհետեւ կարճահասակ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Եւ առաջ վազելով՝ բարձրացաւ ժանտաթզենու վրայ, որպէսզի տեսնի նրան, որովհետեւ նա հէնց այդտեղով էր անցնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Երբ այդ տեղը եկաւ, Յիսուս վեր նայեց եւ ասաց. «Զակքէո՛ս, շտապիր իջի՛ր այդտեղից, որովհետեւ այսօր պէտք է, որ ես քո տանը գիշերեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Զակքէոսը շտապեց իջաւ եւ նրան ընդունեց ուրախութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Երբ ամէնքը այս տեսան, տրտնջում էին եւ ասում, թէ մեղաւոր մարդու մօտ մտաւ գիշերելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Իսկ Զակքէոսը եկաւ կանգնեց եւ ասաց Տիրոջը. «Տէ՛ր, ահա իմ ինչքերի կէսը կը տամ աղքատներին, եւ եթէ որեւէ մէկին զրկել եմ, քառապատիկ կը հատուցեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Եւ Յիսուս նրան ասաց. «Այսօր այս տան համար փրկութիւն եղաւ, քանի որ սա եւս Աբրահամի որդի է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'որովհետեւ մարդու Որդին եկաւ փնտռելու եւ փրկելու կորածին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Եւ մինչ նրանք լսում էին այս, Յիսուս մի առակ էլ աւելացրեց նրա համար, որ ինքը մօտենում էր Երուսաղէմին, եւ նրանք կարծում էին, թէ Աստծու արքայութիւնը շուտով յայտնուելու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Նա ասաց. «Մի ազնուական մարդ գնաց հեռու աշխարհ՝ իր թագաւորութիւնը ստանալու եւ վերադառնալու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Եւ կանչելով իր ծառաներին՝ նրանց տասը մնաս տուեց եւ ասաց. «Շահարկեցէ՛ք դրանք, մինչեւ որ գամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Բայց նրա համաքաղաքացիները ատում էին նրան. պատգամաւորներ ուղարկեցին նրա յետեւից եւ ասացին. «Մենք չենք կամենում, որ դա մեր վրայ թագաւորի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Եւ ազնուականը վերադարձաւ՝ իր թագաւորութիւնն ստացած, եւ կանչեց այն ծառաներին, որոնց տուել էր դրամը, որպէսզի իմանայ, թէ ով ինչ էր շահել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Եկաւ առաջինը եւ ասաց. «Տէ՛ր, քո մէկ մնասը տասը մնաս բերեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Եւ տէրը նրան ասաց. «Ազնիւ եւ բարի ծառայ, քանի որ այդ փոքր բանի մէջ հաւատարիմ եղար, իշխանութիւն ունեցիր տասը քաղաքների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Եկաւ երկրորդը եւ ասաց. «Քո մէկ մնասը հինգ մնաս բերեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Տէրը նրան ասաց. «Դու էլ՝ հինգ քաղաքների վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Միւսն էլ եկաւ եւ ասաց. «Տէ՛ր, ահա քո մնասը, որ թաշկինակի մէջ ծրարած պահում էի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'վախենում էի քեզնից, որովհետեւ խիստ մարդ ես. վերցնում ես, ինչ որ չես դրել, եւ հնձում ես, ինչ որ չես սերմանել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Եւ տէրը նրան ասաց. «Հէնց քո բերանով քեզ պիտի դատեմ, անհաւատարի՛մ ծառայ. գիտէիր, որ ես մի խիստ մարդ եմ, վերցնում եմ, ինչ որ չեմ դրել եւ հնձում եմ՝ ուր չեմ սերմանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Հապա ինչո՞ւ իմ դրամը լումայափոխներին չտուիր, որպէսզի ես, գալով, տոկոսներով միասին պահանջէի այն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Եւ սպասաւորներին ասաց. «Վերցրէ՛ք դրանից մէկ մնասը եւ տարէ՛ք տուէք նրան, ով տասը մնաս ունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Եւ ծառաները ասացին նրան. «Տէ՛ր, արդէն նա տասը մնաս ունի՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '- Ասում եմ ձեզ, թէ՝ «Ով որ ունի, նրան պիտի տրուի, իսկ նրանից, որ չունի, պիտի վերցուի եւ այն, ինչ որ ունի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Բայց իմ այն թշնամիներին, որոնք չէին կամենում, որ ես թագաւորեմ իրենց վրայ, բերէ՛ք այստեղ եւ սպանեցէ՛ք իմ առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Եւ երբ այս ասաց, առաջ գնաց՝ Երուսաղէմ ելնելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Եւ երբ մօտեցաւ Բեթփագէին եւ Բեթանիային, այն լերան մօտ, որ կոչւում է Ձիթենեաց, ուղարկեց իր աշակերտներից երկուսին');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'եւ ասաց. «Գնացէ՛ք այն գիւղը, որ մեր դիմացն է. երբ այնտեղ մտնէք, կը գտնէք կապուած մի աւանակ, որի վրայ ոչ մի մարդ երբեք չի նստել. արձակեցէ՛ք այն եւ բերէ՛ք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Եւ եթէ մէկը ձեզ հարցնի, թէ ինչու էք արձակում, նրան այսպէս ասացէք. «Իր տիրոջը պէտք է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Երբ գնացին նրանք, որ ուղարկուել էին, գտան այնպէս, ինչպէս ասել էր նրանց. աւանակը կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Եւ մինչ աւանակն արձակում էին, նրա տէրերը ասացին նրանց. «Աւանակն ինչո՞ւ էք արձակում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Եւ աշակերտները ասացին. «Իր տիրոջը պէտք է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Եւ այն բերին Յիսուսի մօտ. զգեստներ գցեցին նրա վրայ եւ Յիսուսին նստեցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Եւ մինչ նա առաջանում էր, մարդիկ իրենց զգեստները փռում էին ճանապարհի վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Եւ երբ նա մօտեցաւ Ձիթենեաց լերան զառիվայրին, աշակերտների ամբողջ բազմութիւնը ուրախութեամբ եւ բարձրաձայն սկսեց օրհնել Աստծուն՝ կատարուած բոլոր զօրութիւնների համար, որ տեսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Եւ ասում էին. «Օրհնեա՜լ է այդ թագաւորը, որ գալիս է Տիրոջ անունով. խաղաղութի՜ւն երկնքում եւ փա՜ռք բարձունքներում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Իսկ փարիսեցիներից ոմանք ամբոխի միջից ասացին նրան. «Վարդապե՛տ, սաստի՛ր քո աշակերտներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Նա պատասխանեց եւ ասաց. «Ասում եմ ձեզ, որ եթէ դրանք լռեն էլ, այդ քարերը կ՚աղաղակեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Եւ երբ մօտեցաւ, տեսնելով քաղաքը՝ լաց եղաւ նրա վրայ եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '«Գոնէ այս օրերին գիտենայի՜ր դու քո խաղաղութիւնը. բայց այժմ ծածկուեց քո տեսողութիւնից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'որովհետեւ օրեր պիտի գան վրադ, երբ թշնամիներդ քո շուրջը պատնէշ պիտի կանգնեն եւ պիտի պաշարեն քեզ, պիտի նեղեն քեզ բոլոր կողմերից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'ու հիմնայատակ պիտի անեն քեզ եւ սպանեն քո մէջ քո որդիներին. եւ քարը քարի վրայ բնաւ չպիտի թողնեն, քանի որ քո այցելութեան ժամանակը չճանաչեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Եւ տաճար մտնելով՝ սկսեց դուրս հանել աղաւնեվաճառներին ու գնողներին եւ լումայափոխների սեղանները ցրեց');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'ու ասաց նրանց. «Գրուած է՝ «Իմ տունը պէտք է աղօթքի տուն լինի», իսկ դուք աւազակների որջերի էք վերածել այդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Եւ նա ամէն օր նրանց ուսուցանում էր տաճարում, իսկ քահանայապետները, օրէնսգէտները եւ ժողովրդի գլխաւորները հնար էին փնտռում նրան կորստեան մատնելու,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'բայց չէին գտնում, թէ ինչ անեն, որովհետեւ ամբողջ ժողովուրդը, նրանով տարուած, լսում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Եւ այն օրերից մէկում, մինչ տաճարում ուսուցանում էր ժողովրդին եւ աւետարանում, վրայ հասան քահանայապետներն ու օրէնսգէտները՝ ծերերով հանդերձ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'եւ ասացին նրան. «Ասա՛ մեզ, ի՞նչ իշխանութեամբ ես դու անում այդ, կամ ո՞վ է, որ քեզ տուեց այդ իշխանութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Յիսուս պատասխան տուեց նրանց եւ ասաց. «Ես էլ ձեզ մի բան հարցնեմ, եւ դուք ինձ ասացէ՛ք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Յովհաննէսի մկրտութիւնը երկնքի՞ց էր, թէ՞՝ մարդկանցից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Եւ նրանք իրենց մտքում խորհեցին եւ ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, '«Եթէ ասենք՝ երկնքից էր, կ՚ասի՝ իսկ ինչո՞ւ չհաւատացիք նրան. եւ եթէ ասենք՝ մարդկանցից, ամբողջ ժողովուրդը մեզ կը քարկոծի, որովհետեւ իրենց մտքում Յովհաննէսի մասին հաստատ համոզում կայ, թէ նա մարգարէ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Եւ պատասխան տուեցին, թէ չգիտեն որտեղից է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Եւ Յիսուս նրանց ասաց. «Ես էլ ձե՛զ չեմ ասի, թէ ինչ իշխանութեամբ եմ անում այս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Եւ սկսեց ժողովրդին ասել այս առակը. «Մի մարդ այգի տնկեց եւ այն յանձնեց մշակներին, իսկ ինքը երկար ժամանակով ճանապարհորդութեան գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Եւ յարմար ժամանակին մշակների մօտ մի ծառայ ուղարկեց, որպէսզի այգու պտղից իր բաժինը տան նրան. իսկ մշակները ծեծեցին նրան ու ձեռնունայն արձակեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Տէրը դարձեալ մէկ ուրիշ ծառայ եւս ուղարկեց. նրանք սրան եւս ծեծեցին, անարգեցին եւ ձեռնունայն ճամբու դրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Ապա ուղարկեց նաեւ մի երրորդի. նրանք սրան էլ վիրաւորեցին եւ այգուց դուրս հանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Այգու տէրն ասաց. «Ի՞նչ անեմ. ուղարկեմ իմ սիրելի որդուն, թերեւս նրանից կը պատկառեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Երբ մշակները նրան տեսան, իրար հետ խորհուրդ արին եւ ասացին. «Սա՛ է ժառանգը, սպանենք սրան, որպէսզի ժառանգութիւնը մերը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Եւ նրան այգուց դուրս հանեցին ու սպանեցին: Արդ, այգու տէրը նրանց ի՞նչ կ՚անի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Չէ՞ որ կը գայ ու կորստեան կը մատնի այդ մշակներին եւ այգին ուրիշներին կը տայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Երբ այս լսեցին, ասացին. «Քա՛ւ լիցի»: Եւ Յիսուս նրանց նայելով՝ ասաց. «Իսկ ի՞նչ է այն, որ գրուած է, թէ՝ «Այն վէմը, որ անարգեցին շինողները, նա՛ է, որ անկիւնաքար եղաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Ով որ այս վէմին բախուի, կը խորտակուի, եւ ում վրայ որ այն ընկնի, կը ճզմի նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Եւ օրէնսգէտներն ու քահանայապետները նոյն պահին ուզում էին նրա վրայ ձեռք դնել, բայց ժողովրդից վախեցան, որովհետեւ հասկացան, թէ այն առակը իրենց մասին ասաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Եւ ապա յարմար առիթի սպասեցին եւ ուղարկեցին խաբեբաներ, որոնք իրենք իրենց, կեղծաւորութեամբ, արդար էին ձեւացնում, որպէսզի նրան խօսքերով բռնեն՝ մատնելու համար պետութեան եւ իշխանութեան կուսակալին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Հարցրին նրան եւ ասացին. «Վարդապե՛տ, գիտենք, որ ճիշտ ես խօսում ու ուսուցանում եւ աչառութիւն չես անում, այլ ճշմարտութեամբ Աստծու ճանապարհն ես սովորեցնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Օրինաւո՞ր է մեզ համար կայսրին հարկ տալ, թէ՝ ոչ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Եւ նկատելով նրանց խորամանկութիւնը՝ ասաց նրանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '«Ցո՛յց տուէք ինձ դահեկանը»: Եւ նրանք ցոյց տուին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Եւ նա ասաց. «Ո՞ւմ պատկերը եւ գիրը ունի դա»: Պատասխանեցին եւ ասացին՝ կայսրինը: Եւ նա նրանց ասաց. «Արդ, գնացէ՛ք տուէք կայսրինը՝ կայսեր, իսկ Աստծունը՝ Աստծուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Եւ չկարողացան նրան խօսքերով բռնել ժողովրդի առաջ ու զարմանալով նրա պատասխանի վրայ՝ լռեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Սադուկեցիներից ոմանք, որոնք հակառակում էին, թէ յարութիւն չկայ, մօտենալով հարցրին նրան եւ ասացին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '«Վարդապե՛տ, Մովսէսը մեզ համար գրել է. «Եթէ մէկի եղբայրը, որը կին ունի, մեռնի, եւ նա անժառանգ լինի, թող նրա եղբայրը առնի այդ կնոջը եւ իր եղբօր համար զաւակ հասցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Արդ, եօթը եղբայրներ կային. առաջինը կին առաւ եւ անժառանգ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Նրան առաւ նաեւ երկրորդը. եւ նա էլ անժառանգ մեռաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Նրան առաւ նաեւ երրորդը. եւ նոյն ձեւով՝ եօթն էլ... Եւ ժառանգներ չթողեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Մեռաւ եւ կինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Արդ, յարութեան ժամանակ նրանցից ո՞ւմ կինը կը լինի, որովհետեւ եօթն էլ նրան կին առան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Այս աշխարհի որդիները կին են առնում եւ մարդու են գնում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'իսկ նրանք, որոնք արժանի կը լինեն այն աշխարհին հասնելու եւ մեռելներից յարութիւն առնելու, ո՛չ կին են առնում եւ ո՛չ էլ մարդու են գնում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'քանի որ այլեւս մեռնել անգամ չեն կարող, որովհետեւ հրեշտակների նման են եւ Աստծու որդիներ, քանի որ յարութեան որդիներ են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Իսկ թէ մեռելները յարութիւն են առնում, Մովսէսն էլ այդ գուշակեց մորենու օրինակի մէջ, ինչպէս որ ասում է Տիրոջ մասին՝ «Աստուած Աբրահամի, Աստուած Իսահակի եւ Աստուած Յակոբի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Իսկ Աստուած մեռելների Աստուածը չէ, այլ՝ ողջերի, որովհետեւ բոլորը նրա համար կենդանի են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Օրէնսգէտներից ոմանք նրան պատասխանեցին եւ ասացին. «Վարդապե՛տ, լա՛ւ ասացիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Եւ այլեւս ոչ ոք չէր համարձակւում նրան որեւէ բան հարցնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Յիսուս նրանց էլ ասաց. «Քրիստոսի համար ինչպէ՞ս են ասում, թէ Դաւթի որդին է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'քանի որ Դաւիթն ինքը Սաղմոսների գրքում ասում է. «Տէրն ասաց իմ Տիրոջը՝ նստի՛ր իմ աջ կողմում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'մինչեւ որ քո թշնամիներին ոտքերիդ պատուանդան դնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Իսկ արդ, եթէ Դաւիթը նրան Տէր է կոչում, Նա ինչպէ՞ս նրա որդին կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Եւ մինչ ամբողջ ժողովուրդը լսում էր, ասաց իր աշակերտներին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '«Զգուշացէ՛ք օրէնսգէտներից, որոնք ուզում են պատմուճաններով շրջել եւ սիրում են ողջոյններ ընդունել հրապարակներում ու առաջին աթոռները գրաւել ժողովարաններում եւ պատուոյ տեղերը նստել ընթրիքների ժամանակ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'որոնք իւրացնում են այրիների տները եւ ձեւականօրէն երկարում են իրենց աղօթքները: Նրանք աւելի խիստ դատավճիռ պիտի ստանան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Եւ Յիսուս նայեց ու տեսաւ մեծահարուստներին, որոնք տաճարի գանձանակի մէջ իրենց նուէրներն էին գցում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Տեսաւ եւ մի աղքատ այրի կնոջ, որ երկու լումայ գցեց այնտեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Եւ ասաց. «Ճշմարիտ եմ ասում ձեզ, որ այդ աղքատ այրին աւելի գցեց, քան բոլորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Նրանք ամէնքը իրենց կուտակածներից գցեցին Աստծուն տրուած նուէրների մէջ, իսկ նա իր կարօտութեան մէջ իր ունեցած ամբողջ ապրուստը գցեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Եւ երբ ոմանք տաճարի մասին ասում էին, թէ գեղեցիկ քարերով եւ աշտարակներով է զարդարուած, նա ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '«Այդ բոլորը, որ տեսնում էք, պիտի գան օրեր, երբ այնտեղ չպիտի թողնուի քար քարի վրայ, որ չքանդուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Հարցրին նրան եւ ասացին. «Վարդապե՛տ, ե՞րբ կը լինի այդ, եւ ի՞նչ կը լինի նշանը, երբ այդ պատահելու լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Եւ նա ասաց. «Զգո՛յշ կացէք, չխաբուէք. որովհետեւ շատերը պիտի գան իմ անունով եւ պիտի ասեն թէ՝ ես եմ Քրիստոսը, եւ թէ՝ ժամանակը մօտեցաւ. նրանց յետեւից չգնաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Եւ երբ լսէք պատերազմների եւ խռովութիւնների մասին, չզարհուրէք. որովհետեւ պէտք է, որ նախ այդ բաները պատահեն. բայց աշխարհի վախճանը շուտով չի լինելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Այն ժամանակ ասաց նրանց. «Ազգ ազգի դէմ պիտի ելնի, եւ թագաւորութիւն՝ թագաւորութեան դէմ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'եւ մեծ երկրաշարժներ ու տարբեր տեղերում սով ու ժանտախտ պիտի լինեն. պիտի լինեն արհաւիրքներ եւ մեծամեծ նշաններ երկնքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Բայց այս բոլորից առաջ ձեր վրայ ձեռք պիտի դնեն եւ պիտի հալածեն, ժողովարանների ու բանտերի պիտի մատնեն ձեզ եւ կուսակալների ու թագաւորների առաջ պիտի տանեն ձեզ իմ անուան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Եւ ձեզ համար այդ պիտի լինի առիթ վկայութեան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Արդ, ձեր մտքում դրէք սա. նախօրօք մի՛ մտահոգուէք պատասխան տալու համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'որովհետեւ ես ձեզ կը տամ բերան եւ իմաստութիւն, որին չեն կարողանայ հակառակել կամ պատասխան տալ ձեր բոլոր հակառակորդները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Դուք պիտի մատնուէք ե՛ւ ծնողներից, ե՛ւ եղբայրներից, ե՛ւ ազգականներից, ե՛ւ բարեկամներից, ու ձեզնից ոմանց պիտի սպանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Եւ պիտի ատուէք բոլորից իմ անուան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Բայց ձեր գլխից մի մազ անգամ չպիտի կորչի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Եւ ձեր համբերութեամբ պիտի շահէք ձեր հոգիները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '«Բայց երբ տեսնէք Երուսաղէմը՝ շրջապատուած զօրքերով, այն ժամանակ իմացէ՛ք, որ նրա աւերումը մօտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Այն ժամանակ նրանք, որ Հրէաստանում են, թող փախչեն լեռները, եւ նրանք, որ Երուսաղէմի մէջ են, թող խոյս տան, իսկ նրանք, որ գաւառներում են, թող քաղաք չմտնեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'որովհետեւ դրանք վրէժխնդրութեան օրեր են, որպէսզի կատարուեն բոլոր գրուածները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Բայց այն օրերին վա՜յ է յղիներին եւ ստնտուներին, որովհետեւ մեծ տագնապ պիտի լինի երկրի վրայ եւ բարկութիւն՝ այս ժողովրդի հանդէպ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Նրանք սրի պիտի քաշուեն, գերի պիտի տարուեն բոլոր հեթանոսներից. եւ Երուսաղէմը ոտքի կոխան պիտի լինի ազգերից, մինչեւ որ լրանան հեթանոսների ժամանակները»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, '«Եւ նշաններ պիտի լինեն արեգակի, լուսնի եւ աստղերի վրայ: Եւ երկրի վրայ պիտի լինի հեթանոսների տագնապ՝ ծովի եւ խռովութեան նման ահեղ ձայնի պատճառով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'աշխարհի վրայ գալիք պատահարների վախից եւ նախազգացումից մարդիկ պիտի մեռնեն, որովհետեւ երկնքի զօրութիւնները պիտի շարժուեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Եւ այն ժամանակ պիտի տեսնեն մարդու Որդուն եկած՝ ամպերի վրայ, զօրութեամբ եւ մեծ փառքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Եւ երբ սկսուի այս բանը լինել, վե՛ր կացէք եւ ձեր գլուխները բարձրացրէ՛ք, որովհետեւ մօտ է ձեր փրկութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Եւ նրանց ասաց մի առակ. «Նայեցէ՛ք թզենուն եւ ամէն մի ծառի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'երբ իրենց բողբոջը ցոյց են տալիս, տեսնում էք այն ու դրանից իմանում էք, որ մօտ է ամառը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Նոյնպէս եւ դուք, երբ տեսնէք այս բոլորը կատարուած, իմացէ՛ք, որ Աստծու արքայութիւնը մօտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Ճշմարիտ եմ ասում ձեզ, որ այս սերունդը չպիտի անցնի, մինչեւ որ այս բոլորը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Երկինքը եւ երկիրը կ՚անցնեն, բայց իմ խօսքերը չեն անցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, '«Զգո՛յշ եղէք ինքներդ ձեզնից. գուցէ ձեր սրտերը ծանրանան զեխութեամբ եւ հարբեցողութեամբ ու աշխարհիկ հոգսերով. եւ յանկարծակի հասնի ձեր վրայ այն օրը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'որովհետեւ այդ օրը որոգայթի նման պիտի հասնի այն ամենքի վրայ, որոնք բնակւում են երկրագնդի ամբողջ երեսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Արթո՛ւն կացէք այսուհետեւ, ամէն ժամ աղօ՛թք արէք, որպէսզի կարողանաք զերծ մնալ այն ամենից, որ լինելու է, եւ արժանի լինէք կանգնելու մարդու Որդու առաջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Եւ ցերեկը ուսուցանում էր տաճարի մէջ, իսկ գիշերները ելնում էր, մնում այն լերան վրայ, որը կոչւում էր Ձիթենեաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Եւ ամբողջ ժողովուրդը առաւօտները վաղ շտապում էր նրա մօտ՝ տաճարում նրան լսելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Մօտեցաւ Բաղարջակերաց տօնը, որը կոչւում էր Պասեք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Իսկ քահանայապետներն ու օրէնսգէտները հնար էին փնտռում, թէ ինչպէս սպանեն նրան, բայց վախենում էին ժողովրդից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Ապա սատանան մտաւ Իսկարիովտացի կոչուած Յուդայի մէջ, որ Տասներկուսի թւում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Սա գնաց բանակցեց քահանայապետների, օրէնսգէտների եւ ժողովրդի իշխանաւորների հետ, որ Յիսուսին նրանց մատնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Նրանք ուրախացան եւ խոստացան նրան արծաթ տալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Եւ նա յանձն առաւ ու պատեհ առիթ էր փնտռում՝ նրան մատնելու նրանց՝ ամբոխից մեկուսի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Եկաւ Բաղարջակերաց օրը, երբ օրէնք էր մորթել Պասեքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Եւ նա ուղարկեց Պետրոսին եւ Յովհաննէսին ու ասաց. «Գնացէ՛ք, պատրաստեցէ՛ք մեզ համար Պասեքի ընթրիքը, որ ուտենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Եւ նրանք ասացին. «Ո՞ւր ես ուզում, որ պատրաստենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Եւ նրանց ասաց. «Ահա՛, երբ քաղաք մտնէք, ձեզ կը հանդիպի մի մարդ՝ ջրի սափորը բարձած. գնացէ՛ք նրա յետեւից այն տունը, ուր նա կը մտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Եւ կ՚ասէք տանտիրոջը. «Վարդապետը քեզ ասում է՝ ո՞ւր է այն հիւրասրահը, որտեղ աշակերտներիս հետ պիտի ուտեմ Պասեքի ընթրիքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Եւ նա ձեզ ցոյց կը տայ զարդարուած մի մեծ վերնատուն, եւ այնտեղ կը պատրաստէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Եւ աշակերտները գնացին գտան, ինչպէս որ իրենց ասել էր. եւ պատրաստեցին Պասեքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Եւ երբ ժամը հասաւ, սեղան նստեց, եւ տասներկու առաքեալներն էլ՝ իր հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Եւ նրանց ասաց. «Յոյժ ցանկացայ այս Պասեքի ընթրիքը ուտել ձեզ հետ, քանի դեռ չեմ չարչարուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Բայց ասում եմ ձեզ, թէ այլեւս չեմ ուտելու սրանից, մինչեւ որ Պասեքը կատարուի Աստծու արքայութեան մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Եւ, բաժակը վերցնելով, գոհութիւն յայտնեց Աստծուն եւ ասաց. «Առէ՛ք այս եւ բաժանեցէ՛ք ձեր մէջ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'ասում եմ ձեզ, թէ այսուհետեւ որթատունկի բերքից չեմ խմելու, մինչեւ որ գայ Աստծու արքայութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Եւ հաց վերցնելով՝ գոհութիւն յայտնեց Աստծուն, կտրեց, տուեց նրանց եւ ասաց. «Այս է իմ մարմինը, որ շատերի համար է տրուած. այս արէ՛ք իմ յիշատակի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Նոյնպէս եւ բաժակը վերցրեց ընթրիքից յետոյ եւ ասաց. «Այս բաժակը նոր Ուխտ է իմ արիւնով՝ ձեզ համար թափուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Բայց ահաւասիկ իմ մատնիչի ձեռքը ինձ հետ այս սեղանի վրայ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Եւ մարդու Որդին աշխարհից կը գնայ ըստ սահմանուածի, բայց վա՜յ այն մարդուն, ում ձեռքով կը մատնուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Եւ նրանք սկսեցին հարցնել իրար մէջ, թէ իրենցից ո՛վ է, որ այդ անելու է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Եւ նրանց մէջ հակաճառութիւն առաջացաւ, թէ իրենցից ո՛վ պիտի մեծ համարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Եւ նա նրանց ասաց. «Ազգերի թագաւորները տիրում են իրենց ժողովուրդների վրայ, եւ նրանք, որ իշխում են նրանց վրայ, բարերարներ են կոչւում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Բայց դուք այդպէս չլինէք, այլ՝ ով որ մեծ է ձեր մէջ, թող լինի ինչպէս կրտսերը, իսկ առաջնորդը՝ ինչպէս սպասաւորը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Ո՞վ է մեծ. սեղան նստո՞ղը, թէ՞ սպասաւորը: Չէ՞ որ՝ սեղան նստողը: Բայց ես ձեր մէջ եմ իբրեւ սպասաւոր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, '«Եւ դուք էք, որ իմ փորձութիւնների մէջ ինձ հետ էիք մնում մինչեւ այժմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Եւ ես խոստանում եմ ձեզ, - ինչպէս եւ իմ Հայրը ինձ խոստացաւ տալու արքայութիւնը, -');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'որ ուտէք եւ խմէք իմ սեղանից իմ արքայութեան մէջ եւ նստէք տասներկու գահերի վրայ՝ դատելու Իսրայէլի տասներկու ցեղերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Եւ Տէրն ասաց. «Սիմո՛ն, Սիմո՛ն, ահա սատանան ուզեց ձեզ ցորենի նման մաղել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Բայց ես աղօթեցի քեզ համար, որպէսզի քո հաւատը չպակասի, եւ դու, երբ վերադառնաս ինձ, հաստատես քո եղբայրներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Եւ Պետրոսն ասաց. «Տէ՛ր, պատրաստ եմ քեզ հետ գնալ ե՛ւ բանտ, ե՛ւ դէպի մահ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Եւ նա նրան ասաց. «Ասում եմ քեզ, Պետրո՛ս, այսօր դեռ աքաղաղը կանչած չպիտի լինի, մինչեւ որ դու երեք անգամ ուրանաս՝ ասելով, թէ ինձ չես ճանաչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Եւ նրանց ասաց. «Երբ ուղարկեցի ձեզ առանց քսակի, մախաղի եւ կօշիկների, մի՞թէ որեւէ բանի կարօտ մնացիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Եւ նրանք ասացին՝ եւ ո՛չ մի բանի: Ապա ասաց. «Իսկ այժմ՝ ով որ քսակ ունի, թող վերցնի այն, նոյնպէս եւ՝ մախաղ. իսկ ով որ չունի, թող վաճառի իր վերարկուն եւ իր համար սուր գնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Բայց ասում եմ ձեզ, այս եւս, որ գրուած է, պէտք է, որ կատարուի իմ վրայ, թէ՝ «Անօրէնների հետ դասուեց». որովհետեւ, ինչ որ ինձ համար է գրուած, կատարուելու վրայ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Եւ նրանք ասացին. «Տէ՛ր, ահաւասիկ այստեղ երկու սուր կայ»: Եւ նրանց ասաց. «Բաւական են»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Եւ Յիսուս ըստ իր սովորութեան ելաւ գնաց Ձիթենեաց լեռը. նրա յետեւից գնացին եւ աշակերտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Երբ տեղ հասաւ, ասաց նրանց. «Աղօթքի՛ կանգնեցէք, որ փորձութեան մէջ չընկնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Եւ ինքը հեռացաւ նրանցից մօտ մի քարընկեց, ծնրադրեց, աղօթում էր եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '«Հա՛յր, եթէ կամենում ես, այս բաժակը ինձնից հեռացրո՛ւ, բայց ոչ թէ իմ կամքը, այլ քո՛նը թող լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Եւ նրան երկնքից երեւաց մի հրեշտակ եւ ուժ էր տալիս նրան. նա տագնապի մէջ էր եւ ամբողջ հոգով էր աղօթում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, '« Եւ նրանից քրտինքը հոսում էր արեան կաթիլների նման՝ շիթ-շիթ գետին թափուելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Եւ վեր կենալով աղօթքից՝ եկաւ աշակերտների մօտ, նրանց քնած գտաւ տրտմութիւնից');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'եւ նրանց ասաց. «Ինչո՞ւ էք քնել. վե՛ր կացէք, աղօթեցէ՛ք, որպէսզի փորձութեան մէջ չընկնէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Եւ մինչ նա դեռ խօսում էր, ահա երեւաց մի ամբոխ. եւ նա, որ Յուդա էր կոչւում, Տասներկուսից մէկը, առաջնորդում էր նրանց. երբ Յուդան մօտեցաւ Յիսուսին, համբուրեց նրան, որովհետեւ այն նշանն էր տուել նրանց, թէ՝ «Ում հետ ես համբուրուեմ, նա՛ է, նրա՛ն բռնեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Յիսուս նրան ասաց. «Յուդա՛, համբուրելո՞վ ես մատնում մարդու Որդուն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Երբ նրա շուրջը գտնուողները տեսան եղածը, նրան ասացին. «Տէ՛ր, սրով նրանց հարուածե՞նք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Եւ աշակերտներից մէկը հարուածեց քահանայապետի ծառային եւ կտրեց դէն գցեց նրա աջ ականջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Յիսուս պատասխանեց եւ ասաց. «Թո՛յլ տուէք, բաւ է եղածը»: Եւ դիպչելով ականջին՝ այն բժշկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Եւ իր վրայ եկած քահանայապետներին, տաճարի իշխանաւորներին եւ ծերերին ասաց. «Ինչպէս աւազակի՞ վրայ էք գալիս սրերով ու մահակներով.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'միշտ ձեզ հետ էի տաճարում, եւ դուք ինձ վրայ ձեռք չերկարեցիք. սակայն ա՛յս է ձեր ժամը եւ խաւարի իշխանութեան զօրութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Եւ բռնելով նրան՝ տարան եւ մտցրին քահանայապետի տունը. իսկ Պետրոսը հեռուից գնում էր նրա յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Երբ գաւթի մէջ կրակ վառեցին եւ նստեցին շուրջը, Պետրոսն էլ նստեց նրանց մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Մի աղախին տեսաւ նրան կրակի լոյսի մօտ նստած, հայեացքը սեւեռեց նրան եւ ասաց. «Սա էլ էր նրանցից, որ նրա հետ էին»');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Իսկ Պետրոսն ուրացաւ ու ասաց. «Ես նրան չեմ ճանաչում, ո՛վ կին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Եւ քիչ յետոյ մէկ ուրիշը տեսաւ նրան եւ ասաց. «Դո՛ւ էլ նրանցից ես»: Պետրոսն ասաց. «Ո՛վ մարդ, ես նրանցից չեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Եւ երբ մի ժամ էլ անցաւ, մէկ ուրիշը վիճում էր եւ ասում. «Ճիշտ որ սա էլ նրա հետ էր, որովհետեւ գալիլիացի է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Պետրոսն ասաց. «Ո՛վ մարդ, չգիտեմ այդ ի՛նչ ես խօսում»: Եւ նոյն պահին, մինչ նա այս ասում էր, աքաղաղը կանչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Տէրը դարձաւ եւ նայեց Պետրոսին. եւ Պետրոսը յիշեց Տիրոջ խօսքը, որ ասել էր իրեն. «Դեռ աքաղաղը չկանչած՝ երեք անգամ պիտի ուրանաս, թէ ինձ չես ճանաչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Եւ Պետրոսը դուրս ելնելով՝ դառնօրէն լաց եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Եւ այն մարդիկ, որ նրան պահպանում էին, ծիծաղում էին նրա վրայ եւ խփում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'ծածկում էին նրա երեսը եւ տանջում, հարցնում էին նրան եւ ասում. «Մարգարէացի՛ր՝ ո՞վ է, որ քեզ խփեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Եւ հայհոյելով՝ ուրիշ շատ բաներ էլ էին ասում նրա երեսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Եւ երբ լոյսը բացուեց, հաւաքուեց ժողովրդի ծերակոյտը՝ քահանայապետներ եւ օրէնսգէտներ, եւ Յիսուսին քաշեցին բերին իրենց ատեանի առաջ եւ ասացին. «Եթէ դու ես Քրիստոսը, ասա՛ մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Նրանց ասաց. «Եթէ ձեզ ասեմ իսկ, չէք հաւատայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Եւ եթէ ես ձեզ հարցնեմ, ինձ պատասխան չէք տայ կամ չէք արձակի ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Բայց սրանից յետոյ մարդու Որդին պիտի նստի Աստծու զօրութեան աջին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Եւ ամէնքը միասին ասացին. «Ուրեմն դու Աստծու Որդի՞ն ես»: Եւ նա նրանց ասաց. «Դուք ասում էք, թէ ես եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Եւ նրանք ասացին. «Էլ ի՞նչ վկայութիւն է պէտք մեզ, որովհետեւ մենք ինքներս լսեցինք նրա բերանից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Եւ նրանց ամբողջ բազմութիւնը, վեր կենալով, նրան տարաւ Պիղատոսի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Եւ սկսեցին ամբաստանել նրան եւ ասել. «Գտանք սրան, որ մոլորեցնում էր մեր ազգը, արգելում էր կայսրին հարկեր տալ եւ ինքն իր մասին ասում էր, թէ՝ Քրիստոսն է, թագաւոր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Իսկ Պիղատոսը հարցրեց նրան եւ ասաց. «Հրեաների թագաւորը դո՞ւ ես»: Նա պատասխանեց նրան եւ ասաց. «Դու ասացիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Պիղատոսը քահանայապետներին եւ ժողովրդին ասաց. «Այս մարդու մէջ ես որեւէ յանցանք չեմ գտնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Իսկ նրանք պնդում էին եւ ասում, թէ ըմբոստութեան է մղում ժողովրդին, քարոզում է ամբողջ Հրէաստանում՝ Գալիլիայից սկսած մինչեւ այստեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Իսկ Պիղատոսը, երբ լսեց Գալիլիայի մասին, հարցրեց, թէ այդ մարդը գալիլիացի՞ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Եւ երբ իմացաւ, թէ Հերովդէսի իշխանութիւնից է, յանձնեց, որ նրան տանեն Հերովդէսի մօտ, որովհետեւ այդ օրերին նա էլ Երուսաղէմում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Եւ երբ Հերովդէսը տեսաւ Յիսուսին, շատ ուրախացաւ, որովհետեւ երկար ժամանակից ի վեր ցանկանում էր նրան տեսնել, քանի որ յաճախ լսում էր նրա մասին եւ ակնկալութիւն ունէր նրա ձեռքով կատարուած որեւէ նշան տեսնել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Հերովդէսը նրան հարցաքննեց շատ խօսքերով, իսկ Յիսուս նրան ոչ մի պատասխան չտուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Քահանայապետներն ու օրէնսգէտները վեր էին կենում եւ նրան բուռն կերպով ամբաստանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Հերոդէսն էլ, իր զօրականներով հանդերձ, արհամարհեց նրան եւ ծիծաղելով նրա վրայ՝ սպիտակ զգեստներ հագցնել տուեց նրան ու վերստին յանձնեց, որ տանեն նրան Պիղատոսի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Եւ Պիղատոսն ու Հերովդէսը այդ օրերին բարեկամներ եղան, որովհետեւ առաջ իրար թշնամիներ էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Պիղատոսը կանչեց քահանայապետներին, իշխանաւորներին եւ ժողովրդին ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, '«Այս մարդուն բերեցիք ներկայացրիք ինձ, որպէս ժողովրդին մոլորեցնողի. եւ ահաւասիկ ձեր առաջ դատաքննութիւն արեցի եւ այս մարդու մէջ չգտայ մէկն այն յանցանքներից, որոնցով դուք ամբաստանում էք նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Եւ ոչ էլ՝ Հերովդէսը, որի մօտ հրամայեցի, որ Յիսուսին տանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Արդ, նա մահուան արժանի ոչինչ չի արել, նրան գանահարել կը տամ եւ կ՚արձակեմ»');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '(որովհետեւ հարկաւոր էր իւրաքանչիւր տօնի առթիւ մի բանտարկեալ արձակել նրանց համար):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Եւ նրանք ամբողջ բազմութեամբ աղաղակում էին եւ ասում. «Նրան վերացրո՛ւ եւ արձակի՛ր մեզ համար Բարաբբային»');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '(որը քաղաքում պատահած մի խռովութեան եւ սպանութեան համար բանտարկուել էր):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Պիղատոսը նորից սկսեց խօսել, որովհետեւ կամենում էր Յիսուսին արձակել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Եւ նրանք կրկին աղաղակում էին ու ասում. «Խա՛չը հանիր նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Եւ նա երրորդ անգամ ասաց նրանց. «Ի՞նչ չար բան է արել սա. նրա վրայ մահուան արժանի որեւէ յանցանք չգտայ. սրան գանահարել կը տամ եւ կ՚արձակեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Իսկ նրանք բարձրաձայն ստիպում էին եւ ուզում, որ նրան խաչը հանի: Եւ նրանց ու քահանայապետների ձայները աւելի ուժեղանում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Եւ Պիղատոսը հաւանութիւն տուեց, որ նրանց պահանջը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Նա արձակեց Բարաբբային, որը խռովութեան եւ սպանութեան համար բանտ էր նետուած, եւ որին էլ հէնց ուզում էին. իսկ Յիսուսին յանձնեց նրանց կամքին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Երբ նրան առան գնացին, բռնեցին Սիմոն Կիւրենացի անունով մէկին, որը հանդից էր գալիս. նրա վրայ դրեցին խաչը, որ այն բերի Յիսուսի յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Եւ նրա յետեւից գնում էր ժողովրդի մի մեծ բազմութիւն եւ կանայք, որոնք կոծում էին ու ողբում նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Յիսուս դարձաւ եւ ասաց նրանց. «Երուսաղէմի՛ դուստրեր, ինձ վրայ լաց մի՛ եղէք, այլ լա՛ց եղէք ձեր եւ ձեր որդիների վրայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'որովհետեւ օրեր պիտի գան, երբ մարդիկ պիտի ասեն՝ «Երանի՜ չբեր կանանց եւ նրանց, որոնք բնաւ չծնեցին եւ չդիեցրին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Այն ժամանակ մարդիկ պիտի սկսեն ասել լեռներին, թէ՝ ընկէ՛ք մեր վրայ, եւ բլուրներին, թէ՝ ծածկեցէ՛ք մեզ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'որովհետեւ, երբ դալա՛ր փայտին այսպէս անեն, չորի՛ն ինչ կը պատահի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Ուրիշ երկու չարագործներ էլ բերեցին՝ նրա հետ սպանելու համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Երբ հասան Գագաթ կոչուած տեղը, այնտեղ նրան խաչը հանեցին. եւ չարագործներին էլ՝ մէկին աջ կողմը, միւսին ձախ կողմը՝ խաչեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Եւ Յիսուս ասաց. «Հա՛յր, ների՛ր դրանց, որովհետեւ չգիտեն, թէ ինչ են անում»: Եւ նրա զգեստները բաժանելու համար վիճակ գցեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Իսկ ժողովուրդը դիտում էր. իշխանաւորները նրանց հետ միասին ծաղրում էին նրան եւ ասում. «Ուրիշներին ազատեց, թող ինքն իրեն էլ ազատի, եթէ դա է Քրիստոսը՝ Աստծու ընտրեալ Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Զինուորներն էլ ծաղրում էին նրան. առաջ էին գալիս, քացախ էին մատուցում նրան եւ ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, '«Եթէ դու ես հրեաների թագաւորը, փրկի՛ր ինքդ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Եւ նրա խաչի վրայ մի գրութիւն կար՝ գրուած յունարէն, լատիներէն եւ եբրայերէն գրերով, թէ՝ սա՛ է հրեաների արքան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Իսկ կախուած չարագործներից մէկը հայհոյում էր նրան եւ ասում. «Դու չե՞ս Քրիստոսը. փրկի՛ր ինքդ քեզ եւ մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Նրա ընկերը նրան սաստելով՝ պատասխան տուեց եւ ասաց. «Աստծուց չե՞ս վախենում, դու, որ նոյն պատիժն ես կրում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Եւ մենք իրաւացիօրէն արժանի հատուցումն ենք ստանում այն գործերի համար, որ կատարեցինք, իսկ սա որեւէ վատ բան չի արել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Եւ ասաց Յիսուսին. «Յիշի՛ր ինձ, Տէ՛ր, երբ գաս քո թագաւորութեամբ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Եւ Յիսուս նրան ասաց. «Ճշմարիտ եմ ասում քեզ, այսօր ինձ հետ դրախտում կը լինես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Եւ համարեա կէսօր էր. եւ խաւար եղաւ ամբողջ երկրի վրայ մինչեւ ժամը երեքը. արեգակը խաւարեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Եւ տաճարի վարագոյրը մէջտեղից պատռուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Եւ Յիսուս բարձրաձայն աղաղակեց եւ ասաց. «Հա՛յր, քո ձեռքն եմ աւանդում իմ հոգին»: Երբ այս ասաց, հոգին աւանդեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Եւ հարիւրապետը, տեսնելով ինչ որ պատահեց, փառաւորեց Աստծուն եւ ասաց. «Իսկապէս այս մարդը արդար էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Եւ ամբողջ ժողովուրդը, որ եկել էր ու դիտում էր այս տեսարանն ու կատարուածը, ծեծում էր կուրծքը եւ վերադառնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Նրա բոլոր ծանօթներն էլ կանգնել էին հեռւում. եւ կանայք, որոնք Գալիլիայից նրա յետեւից էին եկել, տեսնում էին այս բաները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Եւ ահա Յովսէփ անունով մի մարդ կար հրեաների Արիմաթէ քաղաքից: Նա հրեաների խորհրդի անդամ էր, բարեգործ եւ արդար մի մարդ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(սա չէր միաբանել նրանց մտադրութիւններին ու գործերին): Եւ ինքն էլ էր սպասում Աստծու թագաւորութեանը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Սա Պիղատոսի մօտ գալով՝ ուզեց Յիսուսի մարմինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Եւ նրան խաչից իջեցնելով՝ փաթաթեց պատանքով ու դրեց վիմափոր գերեզմանի մէջ, որտեղ բնաւ ոչ ոք չէր դրուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Եւ օրը ուրբաթ էր, ու լուսանում էր շաբաթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Եւ Յովսէփի յետեւից գնում էին կանայք, որոնք Գալիլիայից էին եկել Յիսուսի հետ. նրանք տեսան գերեզմանը, եւ թէ ինչպէս նրա մարմինը այնտեղ դրուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Վերադարձան, խնկեր եւ իւղեր պատրաստեցին ու շաբաթ օրը, օրէնքի համաձայն, հանգիստ արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Բայց կիրակի օրը, առաւօտեան շատ վաղ, կանայք գերեզման եկան՝ բերելով իրենց պատրաստած խնկերը. նրանց հետ եւ ուրիշ կանայք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Եւ քարը գերեզմանից գլորած գտան');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'ու ներս մտնելով՝ Տէր Յիսուսի մարմինը չգտան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Եւ մինչ նրանք զարմացած էին այդ բանի վրայ, ահա լուսաւոր զգեստներով երկու մարդիկ հասան նրանց մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Եւ երբ կանայք զարհուրեցին ու իրենց երեսը գետին խոնարհեցրին, մարդիկ ասացին. «Ինչո՞ւ ողջին մեռելների մէջ էք փնտռում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Այստեղ չէ, այլ՝ յարեաւ: Յիշեցէ՛ք՝ ինչպէս խօսեց նա ձեզ հետ, երբ Գալիլիայում էր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'ասում էր, թէ պէտք է, որ մարդու Որդին մեղաւոր մարդկանց ձեռքը մատնուի, խաչուի եւ երրորդ օրը յարութիւն առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Եւ նրանք յիշեցին նրա խօսքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Եւ վերադարձան ու պատմեցին այս ամէնը Տասնմէկին եւ բոլոր միւսներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Եւ Մարիամ Մագդաղենացին, Յովհաննան, Յակոբի մայր Մարիամը եւ նրանց հետ ուրիշ կանայք էին, որ այս բաները պատմեցին առաքեալներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Բայց նրանց խօսքերը բարբաջանք թուացին աշակերտներին, եւ չէին հաւատում նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Սակայն Պետրոսը վեր կացաւ եւ վազեց դէպի գերեզման, նայեց ու տեսաւ, որ կտաւները միայն կային: Եւ գնաց՝ մտքում զարմացած, թէ ինչ էր եղել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Եւ ահա նոյն օրը աշակերտներից երկուսը գնում էին մի գիւղ, որի անունը Էմմաւուս էր, եւ որը Երուսաղէմից հեռու էր մօտ տասնմէկ կիլոմետր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Եւ նրանք միմեանց հետ խօսում էին կատարուած բոլոր անցուդարձերի մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Եւ մինչ նրանք խօսում էին ու վիճում, ինքը՝ Յիսուս մօտեցաւ ու գնում էր նրանց հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Բայց նրանց աչքերը բռնուած էին, որպէսզի նրան չճանաչեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Եւ նրանց ասաց. «Այդ ի՞նչ բաներ են, որոնց համար քայլելիս վիճում էք միմեանց հետ եւ տրտմած էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Նրանցից մէկը, որի անունը Կղէոպաս էր, ասաց նրան. «Երուսաղէմում միայն դո՛ւ ես, որ չես իմացել, թէ ինչեր կատարուեցին այնտեղ այս օրերին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Եւ նրանց ասաց՝ ի՞նչ: Եւ նրանք ասացին Յիսուս Նազովրեցու մասին, որ եղաւ մարգարէ մարդ, հզօր՝ գործերով եւ խօսքերով, Աստծու եւ ամբողջ ժողովրդի առաջ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'եւ թէ ինչպէս մեր քահանայապետները եւ իշխանաւորները նրան մատնեցին մահուան դատաստանի ու խաչը հանեցին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Մենք ակնկալում էինք, թէ նա է, որ փրկելու է Իսրայէլը. սակայն, այս բոլորով հանդերձ, այս երրորդ օրն է, որ այդ բաները կատարուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Այլ նաեւ մեզ զարմացրին մեր միջից մի քանի կանայք, որոնք վաղ առաւօտեան գերեզման էին գնացել');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'եւ նրա մարմինը չէին գտել. նրանք եկան եւ ասացին, թէ նաեւ մի տեսիլ էլ էին տեսել հրեշտակների, որոնք ասում էին նրա մասին, թէ կենդանի է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Ապա մեզնից ոմանք էլ գերեզման գնացին եւ գտան այնպէս, ինչպէս կանայք ասել էին: Բայց նրան չտեսան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Եւ նա ասաց նրանց. «Ո՛վ անմիտ եւ թուլասիրտ մարդիկ, որ դժուարանում էք հաւատալ այն ամենին, որ ասացին մարգարէները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Չէ՞ որ Քրիստոս պէտք է նոյն այդ չարչարանքները կրէր եւ այնպէս մտնէր իր փառքի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Եւ սկսած Մովսէսից ու բոլոր մարգարէներից՝ մեկնում էր նրանց այն բոլորը, ինչ գրուած է իր մասին բոլոր Գրքերում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Երբ մօտեցան այն գիւղին, ուր գնում էին, Յիսուս պատճառ բռնեց, թէ ինքը գնալու է աւելի հեռու տեղ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Իսկ նրանք շատ ստիպեցին նրան ու ասացին. «Մեզ մօտ գիշերիր, որովհետեւ երեկոյ է, եւ օրը տարաժամել է»: Եւ նա ներս մտաւ՝ նրանց հետ այնտեղ գիշերելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Եւ երբ նա սեղան նստեց նրանց հետ, հաց վերցնելով՝ օրհնեց, կտրեց այն եւ տուեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Եւ նրանց աչքերը բացուեցին ու ճանաչեցին նրան, իսկ ինքը նրանց աչքին աներեւոյթ եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Եւ նրանք ասացին միմեանց. «Մեր սրտերն էլ միթէ չէի՞ն ճմլւում մեր մէջ, մինչ նա ճանապարհին խօսում էր մեզ հետ. եւ ինչպէ՜ս էր մեզ բացատրում Գրքերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Ապա անմիջապէս վեր կացան ու Երուսաղէմ վերադարձան եւ հաւաքուած գտան Տասնմէկին եւ նրանց հետ եղածներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'որոնք ասում էին, թէ՝ «Իսկապէս յարեաւ Տէրը եւ երեւաց Սիմոնին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Իսկ երկուսը պատմեցին այն, ինչ պատահել էր ճանապարհին, եւ թէ ինչպէ՛ս Յիսուս իրեն ճանաչել էր տուել նրանց՝ հաց կտրելու ժամանակ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Մինչ դեռեւս նրանք այս էին խօսում, Յիսուս ինքը եկաւ կանգնեց նրանց մէջ եւ ասաց. «Խաղաղութի՜ւն ձեզ, ես եմ, մի՛ վախեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Իսկ նրանք զարհուրած վախենում եւ կարծում էին, թէ մի ոգի են տեսնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Եւ նրանց ասաց. «Ինչո՞ւ էք խռովուած, եւ ինչո՞ւ ձեր սրտերում կասկածներ են ծագում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'տեսէ՛ք իմ ձեռքերն ու ոտքերը, որովհետեւ նոյն ինքն ես եմ. շօշափեցէ՛ք ինձ եւ տեսէ՛ք, որովհետեւ ոգին մարմին եւ ոսկորներ չունի. ինչպէս տեսնում էք,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'ես ունեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Եւ այս ասելով՝ ցոյց տուեց նրանց իր ձեռքերն ու ոտքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Եւ մինչ դեռեւս ուրախութիւնից չէին հաւատում եւ զարմացած էին, ասաց նրանց. «Այստեղ ուտելու բան ունէ՞ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Եւ նրանք տուին նրան խորոված ձկան մի կտոր եւ մեղրախորիսխ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Եւ նա առաւ կերաւ նրանց առաջ, իսկ մնացածները տուեց նրանց ու ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, '«Սրանք այն խօսքերն են, որ խօսեցի ձեզ հետ, մինչ ձեզ հետ էի, թէ՝ պէտք է կատարուեն այն ամէնը, որ գրուած են իմ մասին Մովսէսի օրէնքում, մարգարէների մէջ եւ սաղմոսներում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Այն ժամանակ բացեց նրանց մտքերը, որ հասկանան Գրքերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'Եւ ասաց նրանց. «Այսպէս պէտք է չարչարուէր Քրիստոս, յարութիւն առնէր մեռելներից երրորդ օրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'եւ քարոզուէր նրա անունով ապաշխարութիւն եւ մեղքերի թողութիւն բոլոր ազգերի մէջ՝ Երուսաղէմից սկսած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Եւ այս բաների վկաներ էք դուք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Եւ ահա ես ուղարկում եմ Ձեզ իմ Հօր խոստումը, իսկ դուք նստեցէ՛ք Երուսաղէմ քաղաքում, մինչեւ որ երկնքից զօրութեամբ զգեստաւորուէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Ապա նրանց տարաւ հանեց մինչեւ Բեթանիա եւ, բարձրացնելով իր ձեռքերը, օրհնեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Եւ մինչ նա օրհնում էր նրանց, բաժանուեց նրանցից եւ դէպի երկինք էր վերանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Իսկ նրանք երկրպագեցին Յիսուսին եւ մեծ ուրախութեամբ վերադաձան Երուսաղէմ: Եւ միշտ տաճարում էին, գովաբանում եւ օրհնաբանում էին Աստծուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Սկզբից էր Բանը, եւ Բանը Աստծու մօտ էր, եւ Բանը Աստուած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Նա սկզբից Աստծու մօտ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Ամէն ինչ նրանով եղաւ. եւ առանց նրան չեղաւ ոչինչ, որ եղել է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Կեանքը նրանով էր: Եւ այդ կեանքը մարդկանց համար լոյս էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Եւ լոյսը խաւարի մէջ լուսաւորում է, եւ խաւարը նրան չնուաճեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Կար մի մարդ՝ Աստծուց ուղարկուած. նրա անունը՝ Յովհաննէս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Սա եկաւ որպէս վկայ, որպէսզի վկայի լոյսի մասին, որ բոլորը նրա միջոցով հաւատան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Ինքը լոյսը չէր, այլ եկել էր, որ վկայի լոյսի մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Այդ լոյսն էր ճշմարիտ լոյսը, որ լուսաւորում է ամէն մարդու, որ գալու է աշխարհ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Նա աշխարհի մէջ էր, եւ աշխարհը նրանով եղաւ, սակայն աշխարհը նրան չճանաչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Իւրայինների մօտ եկաւ, բայց իւրայինները նրան չընդունեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Իսկ ովքեր նրան ընդունեցին, նրանց իշխանութիւն տուեց լինելու Աստծու որդիներ, նրանց, որոնք իր անուանը կը հաւատան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Նրանք ո՛չ արիւնից, ո՛չ մարմնի կամքից եւ ոչ էլ մարդու կամքից, այլ Աստծուց ծնուեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Եւ Բանը մարմին եղաւ ու բնակուեց մեր մէջ, եւ տեսանք նրա փառքը, նման այն փառքի, որ Հայրն է տալիս Միածնին՝ լի շնորհով ու ճշմարտութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Յովհաննէսը վկայում էր նրա մասին, աղաղակում եւ ասում. «Սա՛ է, որի մասին ասացի: Նա, որ իմ յետեւից էր գալու, ինձնից մեծ եղաւ, որովհետեւ ինձնից առաջ կար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Մենք բոլորս նրա լրիւութիւնից ստացանք շնորհ՝ շնորհի փոխարէն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'որովհետեւ օրէնքը Մովսէսի միջոցով տրուեց, իսկ շնորհը եւ ճշմարտութիւնը Յիսուս Քրիստոսի միջոցով եղան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Աստծուն ոչ ոք երբեք չի տեսել, բացի միայն միածին Որդուց, որ Հօր ծոցում է. նա՛ յայտնեց Նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Եւ Յովհաննէսի վկայութիւնը այս է. երբ հրեաները Երուսաղէմից քահանաներ ու ղեւտացիներ ուղարկեցին նրա մօտ, որպէսզի հարցնեն նրան՝ դու ո՞վ ես,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'նա խոստովանեց առանց վարանելու. խոստովանեց, թէ՝ ես Քրիստոսը չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Ու նրան հարցրին՝ իսկ դու ո՞վ ես, Եղիա՞ն ես: Եւ նա ասաց՝ ո՛չ, չեմ: Իսկ դու մարգարէ՞ն ես: Նա պատասխանեց՝ ո՛չ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Իսկ ասա՛ մեզ՝ դու ո՞վ ես, որպէսզի պատասխան տանենք նրանց, որոնք մեզ ուղարկեցին. ի՞նչ ես ասում քո մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Նա ասաց. «Ես անապատում կանչողի ձայնն եմ, հարթեցէ՛ք Տիրոջ ճանապարհը, ինչպէս ասաց Եսայի մարգարէն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Եւ եկողները փարիսեցիների կողմից էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Նրանք հարցրին նրան ու ասացին. «Իսկ դու ինչո՞ւ ես մկրտում, եթէ դու չես Քրիստոսը, ոչ էլ Եղիան եւ ոչ էլ մարգարէն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Յովհաննէսը պատասխան տուեց նրանց ու ասաց. «Ես ձեզ մկրտում եմ ջրով. ձեր մէջ կայ մէկը, որին դուք չէք ճանաչում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'որ գալու է իմ յետեւից, եւ որի կօշիկների կապերը արձակելու արժանի չեմ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Այս բանը պատահեց Բեթաբրիայում, Յորդանանի միւս կողմում, ուր գտնւում էր Յովհաննէսը եւ մկրտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Հետեւեալ օրը նա տեսաւ Յիսուսին, որ գալիս էր դէպի իրեն, ու ասաց. «Ահա՛ Գառն Աստուծոյ, որ վերացնում է աշխարհի մեղքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Սա՛ է նա, որի մասին ես ասում էի՝ իմ յետեւից գալիս է մէկը, որ ինձնից մեծ եղաւ, որովհետեւ ինձնից առաջ կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Եւ ես չէի ճանաչում նրան, բայց որպէսզի յայտնի լինի Իսրայէլին, դրա համար ես եկայ ջրով մկրտելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Յովհաննէսը վկայեց եւ ասաց. «Տեսայ Հոգին, որ իջնում էր երկնքից որպէս աղաւնի եւ հանգչում նրա վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Եւ ես չէի ճանաչում նրան. սակայն նա, ով ինձ ուղարկեց ջրով մկրտելու, նա ինձ ասաց. «Ում վրայ տեսնես, որ Հոգին իջնում եւ մնում է, նա՛ է, որ մկրտում է Սուրբ Հոգով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Եւ ես տեսայ ու վկայեցի, թէ սա՛ է Աստծու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Հետեւեալ օրը դարձեալ այնտեղ կանգնած էր Յովհաննէսը. նաեւ՝ իր աշակերտներից երկուսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Եւ նայելով Յիսուսին, որ անցնում գնում էր, ասաց. «Ահաւասիկ Քրիստոսը՝ Գառն Աստուծոյ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Երկու աշակերտները նրանից լսեցին, ինչ որ խօսեց, եւ գնացին Յիսուսի յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Երբ Յիսուս յետ դարձաւ եւ տեսաւ նրանց, որ գալիս էին իր յետեւից, ասաց նրանց. «Ի՞նչ էք ուզում»: Նրանք ասացին նրան. «Ռաբբի՛ (որ թարգմանւում է՝ վարդապետ), ո՞ւր է քո օթեւանը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Նա նրանց ասաց. «Եկէ՛ք եւ տեսէ՛ք»: Եկան եւ տեսան, թէ որտեղ էր նրա օթեւանը. եւ այն օրը նրա մօտ գիշերեցին, որովհետեւ մօտ ժամը չորսն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Սիմոն Պետրոսի եղբայր Անդրէասը մէկն էր այն երկուսից, որոնք լսեցին Յովհաննէսի ասածը եւ գնացին Յիսուսի յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Սա նախ գտնում է իր եղբայր Սիմոնին ու նրան ասում է. «Գտանք Մեսիային» (որ թարգմանւում է՝ Քրիստոս):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Սա նրան տարաւ Յիսուսի մօտ: Նայելով նրան՝ Յիսուս ասաց. «Դու Յովնանի որդի Սիմոնն ես. դու պիտի կոչուես Կեփաս» (որ թարգմանւում է՝ Պետրոս):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Յաջորդ օրը Յիսուս որոշեց Գալիլիա մեկնել. գտաւ Փիլիպպոսին ու նրան ասաց. «Արի՛ իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Եւ Փիլիպպոսը Բեթսայիդայից էր, Անդրէասի եւ Պետրոսի քաղաքից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Փիլիպպոսը գտնում է Նաթանայէլին ու նրան ասում. «Ում մասին որ Մովսէսը օրէնքի մէջ եւ մարգարէները գրել են, գտանք նրան՝ Յիսուսին՝ Յովսէփի որդուն, Նազարէթ քաղաքից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Նաթանայէլը նրան ասաց. «Իսկ կարելի՞ է, որ Նազարէթից մի որեւիցէ լաւ բան դուրս գայ»: Փիլիպպոսը նրան ասաց. «Արի՛ եւ տե՛ս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Երբ Յիսուս տեսաւ Նաթանայէլին, որ իր մօտ էր գալիս, ասաց նրա մասին. «Ահա՛ իսկական մի իսրայէլացի, որի մէջ նենգութիւն չկայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Նաթանայէլը նրան ասաց. «Որտեղի՞ց ես ինձ ճանաչում»: Յիսուս պատասխանեց եւ ասաց նրան. «Փիլիպպոսը դեռ քեզ չկանչած, երբ թզենու տակ էիր, տեսայ քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Նաթանայէլը պատասխան տուեց նրան ու ասաց. «Ռաբբի՛, դո՛ւ ես Աստծու Որդին, դո՛ւ ես Իսրայէլի թագաւորը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Յիսուս պատասխան տուեց նրան ու ասաց. «Նրա համա՞ր ես հաւատում, որ քեզ ասացի, թէ՝ թզենու տակ տեսայ քեզ. դրանից շատ աւելի մեծ բաներ պիտի տեսնես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Եւ ասաց նրան. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, պիտի տեսնէք երկինքը բացուած եւ Աստծու հրեշտակներին՝ բարձրանալիս եւ իջնելիս մարդու Որդու վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Գալիլիա հասնելու երրորդ օրը Կանա քաղաքում հարսանիք կար: Եւ Յիսուսի մայրը այնտեղ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Հարսանիքի հրաւիրուեցին նաեւ Յիսուս եւ իր աշակերտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Եւ երբ գինին պակասեց, մայրը Յիսուսին ասաց. «Գինի չունեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Եւ Յիսուս նրան ասաց. «Ի՞նչ ես ուզում ինձնից, ո՛վ կին, իմ ժամանակը դեռ չի հասել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Նրա մայրը սպասաւորներին ասաց. «Ինչ որ ձեզ ասի, արէ՛ք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Այնտեղ կային քարէ վեց թակոյկներ՝ հրեաների սովորութեան համաձայն մաքրուելու համար. նրանցից իւրաքանչիւրը շուրջ հարիւր լիտր տարողութիւն ունէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Յիսուս նրանց ասաց. «Լցրէ՛ք այդ թակոյկները ջրով»: Եւ լցրին բերնէբերան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Եւ ասաց նրանց. «Հիմա վերցրէ՛ք եւ տարէ՛ք սեղանապետին»: Եւ նրանք տարան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Եւ երբ սեղանապետը ճաշակեց գինի դարձած ջուրը ու չէր իմանում, թէ որտեղից է (բայց սպասաւորները, որոնք ջուր լցրին, գիտէին),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'խօսեց փեսայի հետ ու ասաց. «Ամէն մարդ նախ ընտիր գինին է մատուցում, եւ երբ հարբած են, այն ժամանակ՝ վատը: Իսկ դու ընտիր գինին մինչեւ հիմա պահել ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Յիսուս այս առաջին նշանն արեց Գալիլիայի Կանա քաղաքում որպէս սկիզբը նշանների եւ յայտնեց իր փառքը, ու նրա աշակերտները հաւատացին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Սրանից յետոյ Յիսուս Կափառնայում իջաւ իր մօր եւ իր եղբայրների հետ. եւ այնտեղ մնաց միայն մի քանի օր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Հրեաների զատիկը մօտ էր, եւ Յիսուս Երուսաղէմ ելաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Եւ տաճարի մէջ գտաւ նրանց, որ վաճառում էին արջառներ, ոչխարներ եւ աղաւնիներ, ինչպէս նաեւ՝ լումայափոխներ, որ նստած էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Եւ չուանից խարազան շինեց ու բոլորին տաճարից դուրս հանեց. նաեւ՝ ոչխարներն ու արջառները. իսկ լումայափոխների պղնձադրամները ցիր ու ցան արեց եւ նրանց սեղանները շուռ տուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Իսկ աղաւնի վաճառողներին ասաց. «Դրանք այստեղից վերցրէ՛ք եւ իմ Հօր Տունը վաճառատան մի՛ վերածէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Նրա աշակերտները յետոյ յիշեցին, որ գրուած է. «Քո Տան նկատմամբ իմ նախանձախնդրութիւնը ինձ պիտի ուտի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Հրեաները նրան ասացին. «Ի՞նչ նշան ցոյց կը տաս մեզ, թէ իրաւունք ունես այդ բանն անելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Պատասխանեց նրանց Յիսուս եւ ասաց. «Քանդեցէ՛ք այդ տաճարը, եւ երեք օրուայ ընթացքում այն կը վերականգնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Հրեաները նրան ասացին. «Քառասունվեց տարում շինուեց այս տաճարը, իսկ դու երե՞ք օրում այն վերականգնում ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Բայց նա իր մարմնի տաճարի մասին էր խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Իսկ երբ մեռելներից յարութիւն առաւ, նրա աշակերտները յիշեցին, թէ այդ է, որ ասել էր. եւ հաւատացին Գրքին ու այն խօսքին, որ Յիսուս ասել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Եւ երբ Յիսուս զատկի տօնին Երուսաղէմում էր գտնւում, շատեր հաւատացին նրան, քանի որ տեսնում էին այն նշանները, որ կատարում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Բայց Յիսուս անձամբ վստահութիւն չունէր նրանց նկատմամբ, որովհետեւ ինքն ամենքին ճանաչում էր');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'եւ կարիք չկար, որ որեւէ մէկը վկայէր մարդու մասին, քանի որ ինքն արդէն գիտէր, թէ ինչ կար մարդու հոգու մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Եւ փարիսեցիների մէջ Նիկոդեմոս անունով մի մարդ կար, որ հրեաների իշխանաւոր էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Սա գիշերով եկաւ նրա մօտ ու նրան ասաց. «Ռաբբի՛, գիտենք, որ Աստծուց ես եկել որպէս վարդապետ, որովհետեւ ոչ ոք չի կարող կատարել այն նշանները, որ դու ես անում, եթէ Աստուած նրա հետ չլինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Յիսուս պատասխանեց եւ ասաց նրան. «Ճշմարիտ, ճշմարիտ եմ ասում քեզ, եթէ մէկը վերստին չծնուի, չի կարող Աստծու արքայութիւնը տեսնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Նիկոդեմոսը նրան ասաց. «Ինչպէ՞ս կարող է ծնուել մի մարդ, որ ծեր է. միթէ կարելի՞ է իր մօր որովայնը կրկին անգամ մտնել ու ծնուել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Յիսուս պատասխան տուեց եւ ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում քեզ, եթէ մէկը ջրից ու Հոգուց չծնուի, չի կարող Աստծու արքայութիւնը մտնել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'որովհետեւ մարմնից ծնուածը մարմին է, իսկ Հոգուց ծնուածը՝ հոգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Դու մի՛ զարմացիր, որ քեզ ասացի՝ պէտք է ձեզ վերստին ծնուել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'որովհետեւ քամին ուր ուզում է՝ փչում է, եւ նրա ձայնը լսում ես, բայց չգիտես որտեղից է գալիս կամ ուր է գնում. այսպէս է եւ ամէն ոք, որ Հոգուց է ծնուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Նիկոդեմոսը հարցրեց նրան. «Այդ ինչպէ՞ս կարող է լինել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Յիսուս պատասխանեց եւ ասաց նրան. «Դո՛ւ ես Իսրայէլի վարդապետ եւ այդ չգիտե՞ս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Ճշմարիտ, ճշմարիտ եմ ասում քեզ, խօսում ենք, ինչ որ գիտենք, եւ վկայում ենք, ինչ որ տեսել ենք, եւ մեր վկայութիւնը չէք ընդունում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Իսկ արդ, եթէ երկրաւոր բաներ ասացի ձեզ, եւ չէք հաւատում, ապա ինչպէ՞ս պիտի հաւատաք, եթէ երկնաւոր բաներ ասեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Արդ, ոչ ոք երկինք չի ելել, եթէ ոչ նա, որ իջաւ երկնքից՝ մարդու Որդին, որ երկնքից էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Եւ ինչպէս որ Մովսէսը անապատում բարձրացրեց օձը, այնպէս էլ մարդու Որդին պէտք է բարձրանայ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'որպէսզի, ով նրան հաւատում է, յաւիտենական կեանքն ընդունի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'քանի որ Աստուած այնքան սիրեց աշխարհը, որ մինչեւ իսկ իր միածին Որդուն տուեց, որպէսզի, ով նրան հաւատում է, չկորչի, այլ ընդունի յաւիտենական կեանքը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'որովհետեւ Աստուած իր Որդուն չուղարկեց աշխարհ, որ դատապարտի աշխարհը, այլ՝ որպէսզի աշխարհը նրանով փրկուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Ով նրան հաւատում է, չպիտի դատապարտուի, եւ ով նրան չի հաւատում, արդէն իսկ դատապարտուած է, քանի որ Աստծու միածին Որդու անուանը չհաւատաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Եւ դատաստանը այսպէ՛ս իսկ է. որ լոյսը եկաւ աշխարհ, սակայն մարդիկ խաւարն աւելի սիրեցին, քան լոյսը, որովհետեւ իրենց գործեր ը չար էին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'որովհետեւ, ով չարիք է գործում, ատում է լոյսը եւ չի գալիս դէպի լոյսը, որպէսզի նրա գործերը իր երեսովը չտան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Իսկ ով կատարում է այն, ինչ ճշմարիտ է, գալիս է դէպի լոյսը, որպէսզի նրա գործերը յայտնի լինեն, թէ Աստուծով կատարուեցին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Այնուհետեւ Յիսուս եւ իր աշակերտները Հրէաստանի երկիրը եկան, եւ նա այնտեղ շրջում էր նրանց հետ ու մկրտում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Յովհաննէսն էլ մկրտում էր Այենոնում, Երուսաղէմի մօտ, որովհետեւ այնտեղ շատ ջրեր կային, եւ մարդիկ գալիս ու մկրտւում էին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'քանի դեռ Յովհաննէսին չէին բանտարկել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Եւ Յովհաննէսի աշակերտների ու մի հրեայի միջեւ մաքրութեան մասին մի հարց ծագեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Նրանք եկան Յովհաննէսի մօտ եւ նրան ասացին. «Ռաբբի՛, նա, որ Յորդանանի միւս կողմում քեզ հետ էր, եւ որի մասին դու վկայեցիր, ահաւասիկ նա մկրտում է, եւ ամէնքը գալիս են նրա մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Յովհաննէսը պատասխանեց եւ ասաց. «Մարդն իրենից որեւէ բան անել չի կարող, եթէ նրան ի վերուստ՝ երկնքից այդ տրուած չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Դուք ինքներդ էք վկայում ինձ, որ ձեզ ասացի. ես Քրիստոսը չեմ, այլ ուղարկուած եմ նրա առաջից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Ով հարս ունի, նա՛ է փեսան. իսկ փեսայի բարեկամը, որ կանգնած լսում է նրան, մեծապէս ուրախանում է փեսայի ձայնի համար. արդ, այս ուրախութիւնը, որ իմն է, կատարեալ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Պէտք է, որ նա մեծանայ, իսկ ես՝ նուազեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, '«Նա, որ ի վերուստ է գալիս, վեր է ամենքից. նա, որ այս երկրից է, երկրաւոր է եւ երկրաւոր բաների մասին է խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Նա, որ երկնքից է գալիս, վկայում է, ինչ որ տեսել ու լսել է, սակայն նրա վկայութիւնը ոչ ոք չի ընդունում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Ով ընդունում է նրա վկայութիւնը, հաստատած կը լինի, որ Աստուած ճշմարիտ է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'քանի որ նա, ում Աստուած ուղարկեց, Աստծու խօսքերն է խօսում. որովհետեւ Աստուած Հոգին տալիս է առանց չափի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Հայրը սիրում է Որդուն եւ ամէն ինչ տուել է նրա ձեռքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Ով հաւատում է Որդուն, ընդունում է յաւիտենական կեանքը, իսկ ով չի հնազանդւում Որդուն, կեանք չի տեսնի, այլ նրա վրայ կը մնայ Աստծու բարկութիւնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Երբ Յիսուս իմացաւ, որ փարիսեցիները լսել են, թէ ինքն աւելի շատ աշակերտներ է դարձնում եւ մկրտում, քան Յովհաննէսը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(թէպէտեւ ոչ թէ Յիսուս ինքն էր մկրտում, այլ՝ նրա աշակերտները),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'թողեց Հրէաստան երկիրը եւ վերստին եկաւ Գալիլիա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Եւ անհրաժեշտ էր, որ նա անցնէր Սամարիայով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Նա գալիս է Սամարիայի մի քաղաքը, որի անունն էր Սիւքար, մօտիկ այն գիւղին, որ Յակոբը տուել էր իր որդուն՝ Յովսէփին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Եւ այնտեղ Յակոբի աղբիւրը կար: Եւ Յիսուս ճանապարհից յոգնած՝ նստեց աղբիւրի մօտ. կէսօր էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Սամարիայից մի կին է գալիս ջուր հանելու. Յիսուս նրան ասում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '«Ինձ խմելու ջուր տուր» (քանի որ նրա աշակերտները գնացել էին քաղաք, որպէսզի ուտելիք գնեն):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Սամարացի կինը նրան ասում է. «Դու, որ հրեայ ես, ինչպէ՞ս ինձնից՝ սամարացի կնոջից, խմելու ջուր ես ուզում» (որովհետեւ հրեաները սամարացիների հետ երբեք շփում չեն ունենում):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Յիսուս նրան պատասխանեց եւ ասաց. «Եթէ դու գիտենայի՜ր Աստծու պարգեւները, եւ թէ ով է, որ քեզ ասում է՝ «Ինձ խմելու ջուր տուր», գուցէ ինքդ արդարեւ նրանից կ՚ուզէիր, եւ նա քեզ կենդանի ջուր կը տար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Կինը նրան ասաց. «Տէ՛ր, սակայն դու դոյլ իսկ չունես, եւ այս ջրհորը խորն է. ուրեմն դու որտեղի՞ց կ՚ունենաս կենդանի ջուր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Միթէ դու աւելի մե՞ծ մէկն ես, քան մեր հայրը՝ Յակոբը, որ այս ջրհորը մեզ տուել է եւ ինքն էլ խմել է սրանից. նաեւ՝ իր որդիներն ու իր հօտերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Յիսուս նրան պատասխանեց եւ ասաց. «Ով որ այս ջրից խմի, նորից կը ծարաւի, բայց ով որ խմի այն ջրից, որ ես եմ տալու նրան, յաւիտեան չպիտի ծարաւի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Իսկ այն ջուրը, որ ես նրան տալու եմ, նրա մէջ կը լինի բխող ջրի աղբիւր յաւիտենական կեանքի համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Կինը ասաց նրան. «Տէ՛ր, տո՛ւր ինձ այդ ջուրը, որպէսզի չծարաւեմ եւ այստեղ չգամ ջուր հանելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Յիսուս նրան ասաց. «Գնա՛, ամուսնուդ կանչի՛ր եւ արի՛ այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Կինը պատասխան տուեց նրան եւ ասաց. «Ամուսին չունեմ»: Յիսուս նրան ասաց. «Լա՛ւ ասացիր, թէ՝ ամուսին չունեմ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'որովհետեւ հինգ մարդ ես փոխել եւ ում հետ, որ այժմ ապրում ես, քո ամուսինը չէ. այդ ճիշտ ասացիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Կինը նրան ասաց. «Տէ՛ր, ինձ թւում է, թէ դու մարգարէ ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Մեր հայրերը այս լերան վրայ երկրպագութիւն արեցին, իսկ դուք ասում էք, թէ միայն Երուսաղէմն է այն տեղը, ուր արժան է երկրպագել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Յիսուս նրան ասաց. «Ո՛վ կին, հաւատա՛ ինձ, որ կը գայ ժամանակը, երբ ո՛չ այս լերան վրայ եւ ո՛չ էլ Երուսաղէմում կ՚երկրպագեն Հօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Դուք երկրպագում էք նրան, ում չգիտէք, իսկ մենք երկրպագում ենք նրան, ում գիտենք, որովհետեւ փրկութիւնը հրեաներից է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Բայց կը գայ ժամանակը, եւ արդէն իսկ եկել է, երբ ճշմարիտ երկրպագուները կ՚երկրպագեն Հօրը հոգով եւ ճշմարտութեամբ, քանի որ Հայրն էլ իրեն այդպիսի երկրպագուներ է ուզում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Հոգի է Աստուած, եւ նրա երկրպագուները պէտք է հոգով եւ ճշմարտութեամբ երկրպագեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Կինը ասաց նրան. «Գիտեմ, որ Մեսիան՝ Քրիստոս կոչուածը, կը գայ. երբ նա գայ, մեզ ամէն ինչ կը պատմի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Յիսուս նրան ասաց. «Այդ ես եմ, որ խօսում եմ քեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Եւ այդ խօսքի վրայ նրա աշակերտները եկան եւ զարմանում էին, որ նա խօսում էր այդ կնոջ հետ, բայց նրանցից ոչ ոք չասաց, թէ՝ ի՞նչ ես ուզում կամ ի՞նչ ես խօսում նրա հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Կինը թողեց իր սափորը եւ քաղաք գնաց ու ասաց մարդկանց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '«Եկէք տեսէ՛ք մի մարդու, որ ինձ ասաց այն բոլորը, ինչ արել եմ. արդեօք նա՞ է Քրիստոսը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Նրանք ելան քաղաքից եւ գալիս էին նրա մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Եւ մինչ նրանք դեռ չէին եկել, աշակերտներն աղաչում էին նրան ու ասում. «Ռաբբի՛, հա՛ց կեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Նա ասաց նրանց. «Ես ունեմ ուտելու կերակուր, որ դուք չգիտէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Աշակերտները իրար մէջ ասում էին՝ արդեօք մէկը դրան ուտելու բա՞ն է բերել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Յիսուս նրանց ասաց. «Իմ կերակուրն այն է, որ կամքը կատարեմ նրա՛, ով ինձ ուղարկել է, եւ կատարեմ նրա գործը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Չէ՞ որ դուք էք ասում, թէ չորս ամիս եւս կայ, որ հունձը գայ. ահա ես ձեզ ասում եմ. բարձրացրէ՛ք ձեր աչքերը եւ տեսէ՛ք արտերը, որ սպիտակել են եւ հասել հնձի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Եւ ով հնձում է, վարձ է ստանում ու յաւիտենական կեանքի համար պտուղ է կուտակում, որպէսզի սերմանողն ու հնձողը հաւասարապէս ցնծան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Հէնց սրանով է ճշմարիտ այն խօսքը, թէ՝ ա՛յլ է սերմանողը եւ ա՛յլ՝ հնձողը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ես ուղարկեցի ձեզ հնձելու այն, որի վրայ աշխատանք չէիք թափել. ուրիշներ աշխատանք թափեցին, իսկ դուք նրանց վաստակի մէջ մտաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Եւ սամարացիների այդ քաղաքից շատեր հաւատացին նրան այն կնոջ խօսքի համար, որ վկայեց, թէ՝ ինձ ասաց այն բոլորը, ինչ ես արել էի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Իսկ երբ սամարացիները նրա մօտ եկան, աղաչում էին, որ իրենց մօտ մնայ. եւ նա այնտեղ մնաց երկու օր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Ուրիշ շատեր էլ նրան հաւատացին՝ իր խօսքի համար.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'եւ կնոջն ասում էին. «Այսուհետեւ քո խօսքերի համար չէ, որ հաւատում ենք, որովհետեւ մենք ինքներս լսեցինք նրանից եւ գիտենք, թէ նա՛ է ճշմարտապէս Փրկիչն աշխարհի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Եւ երկու օր յետոյ նա ելաւ այնտեղից եւ գնաց Գալիլիա.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'քանի որ Յիսուս ինքն իսկ վկայել էր, թէ մարգարէն իր գաւառում պատիւ չունի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Սակայն, երբ նա Գալիլիա եկաւ, գալիլիացիները նրան ընդունեցին, որովհետեւ նրանք եւս տեսել էին այն բոլոր նշանները, որ նա արեց Երուսաղէմում՝ տօնի ժամանակ, քանի որ նրանք էլ էին եկել տօնին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Յիսուս դարձեալ եկաւ Գալիլիայի Կանա քաղաքը, ուր ջուրը գինու էր վերածել: Պալատական մի պաշտօնատար կար, որի որդին հիւանդ էր Կափառնայումում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Երբ նա լսեց, թէ Յիսուս Հրէաստանից Գալիլիա է եկել, եկաւ նրա մօտ եւ աղաչում էր, որ Կափառնայում իջնի ու իր որդուն բժշկի, քանի որ մերձիմահ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Յիսուս նրան ասաց. «Եթէ նշաններ եւ զարմանալի գործեր չտեսնէք, չէք հաւատում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Պաշտօնատարը նրան ասաց. «Տէ՛ր, իջի՛ր, քանի դեռ իմ որդին չի մեռել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Յիսուս նրան ասաց. «Գնա՛, քո որդին կենդանի է»: Եւ մարդը հաւատաց Յիսուսի ասած խօսքին ու գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Եւ մինչդեռ նա իջնում էր, նրա ծառաները ընդառաջ ելան նրան, աւետիս տուեցին եւ ասացին, թէ նրա տղան կենդանի է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Նա հարցրեց նրանց, թէ ո՞ր ժամին ապաքինուեց: Նրան ասացին. «Երէկ, յետմիջօրէի ժամը մէկին ջերմը նրան թողեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Հայրը գիտակցեց, որ այդ ժամին էր, երբ Յիսուս նրան ասաց՝ քո որդին կենդանի է: Եւ հաւատաց ինքը, ու իր ամբողջ ընտանիքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Այս դարձեալ երկրորդ նշանն է, որ արեց Յիսուս՝ Հրէաստանից Գալիլիա գալուց յետոյ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Դրանից յետոյ հրեաների տօնն էր, եւ Յիսուս Երուսաղէմ ելաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Եւ Երուսաղէմում, Ոչխարների աւազանի մօտ մի տեղ կար, որ եբրայերէն անուանւում էր Բեթհեզդա՝ հինգ սրահներով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'որոնց մէջ պառկած էր մի մեծ բազմութիւն հիւանդների, կոյրերի, կաղերի եւ գօսացածների, որոնք սպասում էին ջրերի խառնուելուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Եւ Տիրոջ հրեշտակը ժամանակ առ ժամանակ իջնում էր աւազանը եւ ջրերը խառնում. եւ ով ջրերի խառնուելու ժամանակ առաջինն էր իջնում, բժշկւում էր՝ հիւանդութիւնից նշան անգամ չպահելով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Այնտեղ կար մի մարդ, որ երեսունութ տարուց ի վեր հիւանդ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Երբ Յիսուս տեսաւ, որ նա պառկած ընկած է, եւ իմացաւ, որ դա շատ ժամանակից ի վեր էր, նրան ասաց. «Կամենո՞ւմ ես առողջ լինել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Հիւանդը պատասխանեց նրան. «Տէ՛ր, ոչ ոք չունեմ, որ, երբ ջրերը խառնուեն, ինձ աւազանի մէջ իջեցնի. եւ մինչ ես դանդաղում եմ, մէկ ուրիշն ինձնից աւելի առաջ է իջնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Յիսուս նրան ասաց. «Վե՛ր կաց, վերցրո՛ւ քո մահիճը եւ գնա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Եւ մարդը առողջացաւ, վեր կացաւ, վերցրեց իր մահիճը եւ ման էր գալիս. եւ այն օրը շաբաթ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Հրեաները բժշկուած մարդուն ասացին. «Շաբաթ օր է եւ օրինաւոր չէ, որ վերցնես մահիճդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Նա նրանց ասաց. «Նա, որ ինձ բժշկեց, նա՛ ինձ ասաց՝ վերցրո՛ւ քո մահիճը եւ գնա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Նրան հարցրին ու ասացին. «Ո՞վ է այն մարդը, որ քեզ ասաց՝ վերցրո՛ւ քո մահիճը եւ շրջի՛ր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Իսկ բժշկուածը չէր իմանում, թէ ո՛վ է նա, որովհետեւ Յիսուս այդտեղից ամբոխի պատճառով հեռացել էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Այնուհետեւ Յիսուս նրան գտաւ տաճարում ու ասաց նրան. «Ահաւասիկ առողջացար, այլեւս մի՛ մեղանչիր, որպէսզի մի աւելի չար բան չպատահի քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Մարդը գնաց եւ հրեաներին պատմեց, թէ՝ Յիսուս էր, որ ինձ բժշկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Եւ հրեաները Յիսուսին հալածում էին նրա համար, որ շաբաթ օրով էր անում այդ բաները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Սակայն Յիսուս պատասխանեց նրանց եւ ասաց. «Իմ Հայրը մինչեւ այժմ գործում է, ուրեմն ես եւս գործում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Դրա համար հրեաները առաւել եւս ուզում էին նրան սպանել, որովհետեւ ոչ միայն չէր պահում շաբաթը, այլ նաեւ Աստծուն կոչում էր իր Հայրը եւ իր անձը Աստծուն հաւասար էր դասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Յիսուս ասաց նրանց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, մարդու Որդին ինքն իրենից ոչինչ չի կարող անել, այլ անում է այն, ինչ տեսնում է, թէ Հայրը կատարում է, որովհետեւ ինչ որ Հայրն է անում, նոյնը նրա նման եւ Որդին է գործում,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'քանի որ Հայրը սիրում է Որդուն, եւ այն ամէնը, ինչ ինքն է անում, ցոյց է տալիս նրան. եւ նրան ցոյց կը տայ սրանից շատ աւելի մեծ գործեր, որոնց վրայ դուք կը զարմանաք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'որովհետեւ, ինչպէս որ Հայրը յարութիւն է տալիս մեռելներին եւ կենդանացնում է, նոյնպէս եւ Որդին կենդանացնում է՝ ում կամենայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Սակայն Հայրը ոչ մէկին չի դատում, այլ ամէն դատաստան տուել է իր Որդուն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'որպէսզի ամէնքը պատուեն Որդուն, ինչպէս պատւում են Հօրը: Ով Որդուն չի պատւում, չի պատւում եւ Հօրը՝ նրան առաքողին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ, ով իմ խօսքը լսում է ու հաւատում է նրան, ով ինձ առաքեց, ընդունում է յաւիտենական կեանքը եւ չի դատապարտւում, այլ մահուանից կեանք անցաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ կը գայ ժամանակ, եւ արդէն իսկ եկել է, երբ մեռելները կը լսեն Աստծու Որդու ձայնը, եւ նրանք, որ կը լսեն, կ՚ապրեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'որովհետեւ, ինչպէս Հայրն ինքն իր մէջ կեանք ունի եւ կեանք է տալիս, նոյնպէս եւ Որդուն տուեց ինքն իր մէջ կեանք ունենալ եւ տալ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Եւ նրան իշխանութիւն տուեց դատաստան անելու, քանի որ մարդու Որդի է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'դրա վրայ ինչո՞ւ էք զարմանում, որովհետեւ կը գայ ժամանակ, երբ բոլոր նրանք, որ գերեզմաններում են, կը լսեն նրա ձայնը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'եւ դուրս կը գան. ովքեր բարի գործեր են արել՝ կեանքի յարութեան համար, իսկ ովքեր չար գործեր են արել՝ դատաստանի յարութեան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ես ինքս ինձնից ոչինչ անել չեմ կարող, այլ, ինչպէս լսում եմ Հօրից՝ դատում եմ, եւ իմ դատաստանը արդար է, որովհետեւ ոչ թէ իմ կամքն եմ որոնում, այլ նրա կամքը, ով ինձ առաքեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, '«Եթէ ես եմ վկայում իմ մասին, իմ վկայութիւնը հաւաստի չէ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ուրիշն է, որ վկայում է իմ մասին. եւ դուք գիտէք, որ հաւաստի է այն վկայութիւնը, որ նա վկայեց իմ մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Յովհաննէսի մօտ դուք մարդ ուղարկեցիք, եւ նա վկայեց ճշմարտութիւնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Բայց ես մարդկանցից չէ, որ վկայութիւն եմ առնում, այլ այս ասում եմ, որ դուք փրկուէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Յովհաննէսն էր ճրագը, որ վառուած էր եւ լոյս էր տալիս, եւ դուք կամեցաք միառժամանակ ցնծալ նրա լոյսով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Բայց ես աւելի մեծ վկայութիւն ունեմ, քան Յովհաննէսինը. այն գործերը, որ Հայրն ինձ տուեց, որ կատարեմ, այդ նոյն գործերն իսկ, որ անում եմ, վկայում են իմ մասին, թէ Հայրն է ուղարկել ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Եւ Հայրը, որ ինձ ուղարկեց, նա՛ է վկայել իմ մասին. դուք ո՛չ նրա ձայնն էք երբեւէ լսել եւ ո՛չ էլ նրա երեսն էք տեսել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Եւ ո՛չ էլ նրա խօսքն ունէք ձեր մէջ բնակուած, որովհետեւ, ում նա ուղարկեց, դուք նրան չէք հաւատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Քննեցէ՛ք Գրքերը, քանի որ կարծում էք, թէ նրանցով յաւիտենական կեանք կ՚ունենաք: Բայց այդ Գրքերն իսկ վկայում են իմ մասին, որովհետեւ դուք կարծում էք, թէ յաւիտենական կեանք ունէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Եւ դուք չէք կամենում դէպի ինձ գալ, որպէսզի կեանք ունենաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ես մարդկանցից փառք չեմ առնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Բայց գիտեմ ձեզ, որ Աստծու հանդէպ սէր չունէք ձեր մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ես եկայ իմ Հօր անունով, եւ ինձ չէք ընդունում: Եթէ ուրիշ մէկը գայ իր անունով, նրան կ՚ընդունէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Դուք ինչպէ՞ս կարող էք հաւատալ, քանի որ իրարից էք փառք առնում եւ չէք որոնում այն փառքը, որ միակ Աստծուց է գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Մի՛ կարծէք, որ ես Հօր մօտ ձեզ պիտի ամբաստանեմ. կայ մէկը, որ որպէս ամբաստանող կը կանգնի ձեր դէմ՝ Մովսէ՛սը, որի վրայ դուք յոյս էք դրել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'որովհետեւ, եթէ դուք հաւատայիք Մովսէսին, կը հաւատայիք այդ դէպքում ուրեմն եւ ինձ, քանի որ նա հէնց իմ մասին է գրել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'իսկ եթէ նրա գրածներին չէք հաւատում, իմ խօսքերին ինչպէ՞ս պիտի հաւատաք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Այնուհետեւ Յիսուս Գալիլիայի՝ Տիբերական ծովի հանդիպակաց կողմն անցաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'եւ նրա յետեւից բազում ժողովուրդ էր գնում, որովհետեւ տեսնում էին այն նշանները, որ նա կատարում էր հիւանդների վրայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Յիսուս լեռ բարձրացաւ եւ նստեց այնտեղ իր աշակերտների հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Եւ մօտ էր զատիկը՝ հրեաների տօնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Յիսուս իր աչքերը վեր բարձրացրեց եւ տեսաւ, որ բազում ժողովուրդ է գալիս իր մօտ: Փիլիպպոսին ասաց. «Որտեղի՞ց հաց պիտի գնենք, որ դրանք ուտեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Այս ասում էր՝ նրան փորձելու համար, բայց ինքը գիտէր, թէ ինչ էր անելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Փիլիպպոսը նրան պատասխանեց. «Երկու հարիւր դահեկանի հաց դրանց չի բաւարարի, թէկուզ եւ իւրաքանչիւր ոք մի կտոր վերցնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Նրա աշակերտներից մէկը՝ Անդրէասը, Սիմոն Պետրոսի եղբայրը, ասաց նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '«Այստեղ մի պատանի կայ, որ հինգ գարեհաց ունի եւ երկու ձուկ. բայց այդքանն ի՞նչ է այսչափ մարդկանց համար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Յիսուս ասաց. «Նստեցրէ՛ք մարդկանց»: Այնտեղ առատ խոտ կար: Եւ շուրջ հինգ հազար մարդիկ նստեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Եւ Յիսուս հացն առաւ ու գոհութիւն յայտնեց Աստծուն եւ բաշխեց նստածներին: Նոյն ձեւով եւ ձկներից՝ որչափ որ կամեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Եւ երբ կշտացան, աշակերտներին ասաց. «Հաւաքեցէ՛ք այդ մնացած կտորները, որպէսզի ոչ մի բան չկորչի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Հաւաքեցին եւ լցրին տասներկու սակառ այն հինգ գարեհացի կտորտանքով, որ ավելացել էր ուտողներից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Իսկ մարդիկ, երբ տեսան այն նշանները, որ նա արեց, ասացին. «Սա՛ է ճշմարիտ մարգարէն, որ աշխարհ էր գալու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Երբ Յիսուս իմացաւ, որ գալու են իրեն բռնել տանելու, որպէսզի իրեն թագաւոր անեն, դարձեալ միայնակ դէպի լեռը գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Եւ երբ երեկոյ եղաւ, նրա աշակերտները ծովեզերք իջան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Եւ նաւակ նստելով՝ գալիս էին դէպի ծովի միւս կողմը, դէպի Կափառնայում: Եւ երբ մութն ընկաւ, Յիսուս դեռ իրենց մօտ չէր եկել.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'եւ ծովը հողմի ուժգին փչելուց փոթորկւում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Երբ շուրջ հինգ կամ վեց կիլոմետր թիավարելուց յետոյ տեսան Յիսուսին, որ քայլում էր ծովի վրայով եւ նաւակին մօտեցել էր, սաստիկ վախեցան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Եւ նա ասաց նրանց. «Ես եմ, մի՛ վախեցէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Եւ ուզում էին նրան նաւակի մէջ առնել. եւ նաւակը շուտով հասաւ այն տեղը, ուր գնում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Յաջորդ օրը, ժողովուրդը, որ մնացել էր ծովի այն կողմը, տեսաւ, որ այնտեղ այլ նաւակ չկայ, բացի միայն մէկից, որի մէջ մտել էին Յիսուսի աշակերտները, իսկ Յիսուս իր աշակերտների հետ նաւակ չէր մտել, այլ միայն իր աշակերտներն էին գնաց»լ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Սակայն Տիբերիայից ուրիշ նաւակներ էլ գալիս էին մօտ այն տեղին, ուր հացն էին կերել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Ուրեմն, երբ ժողովուրդը տեսաւ, որ Յիսուս այդտեղ չէ եւ ոչ էլ՝ նրա աշակերտները, նաւակներ նստեցին եւ եկան Կափառնայում՝ Յիսուսին փնտռելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Եւ երբ նրան գտան ծովի միւս կողմում, ասացին նրան. «Ռաբբի՛, ե՞րբ եկար այստեղ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, դուք ինձ փնտռում էք ոչ թէ նրա համար, որ նշաններ տեսաք, այլ որովհետեւ կերաք այն հացից եւ կշտացաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Գնացէք աշխատեցէ՛ք ոչ թէ կորստեան ենթակայ կերակրի համար, այլ այն կերակրի, որը մնում է յաւիտենական կեանքի համար, եւ որը մարդու Որդին կը տայ ձեզ, քանի որ նրան իր կնիքով հաստատել է Հայրը՝ Աստուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Նրան ասացին. «Ի՞նչ անենք, որ Աստծու ուզած գործերը գործենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Աստծու ուզած գործը ա՛յս է. որ հաւատաք նրան, ում նա ուղարկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Նրան ասացին. «Ի՞նչ նշան կ՚անես, որ տեսնենք եւ հաւատանք, ի՞նչ գործ կը գործես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Մեր հայրերը անապատում մանանան կերան, ինչպէս որ գրուած է. «Երկնքից նրանց հաց տուեց ուտելու»»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Յիսուս նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, Մովսէսը չէ, որ ձեզ երկնքից հաց տուեց, այլ իմ Հայրն է, որ տալիս է ձեզ ճշմարիտ հացը երկնքից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'որովհետեւ Աստծուց է այն հացը, որ իջնում է երկնքից եւ կեանք է տալիս աշխարհին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Նրան ասացին. «Տէ՛ր, ամէն ժամ տո՛ւր մեզ այդ հացը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Յիսուս նրանց ասաց. «Ես եմ կենաց հացը. ով դէպի ինձ գայ, քաղց չի զգայ, եւ ով ինձ հաւատայ, երբեք չի ծարաւի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Բայց ես ձեզ ասել եմ, թէ ինձ տեսաք եւ չէք հաւատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Բոլոր նրանք, ում Հայրն ինձ տալիս է, կը գան ինձ մօտ, եւ ով որ ինձ մօտ կը գայ, դուրս չեմ անի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'որովհետեւ ես երկնքից իջայ ոչ թէ իմ կամքը կատարելու համար, այլ՝ կամքը նրա, ով ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Այս է կամքը իմ Հօր, որ ինձ ուղարկեց. բոլոր նրանք, ում Հայրն ինձ տուել է, նրանցից ոչ մէկին չկորցնեմ, այլ վերջին օրը յարութիւն առնել տամ նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Այս է իմ Հօր կամքը. ամէն ոք, ով տեսնի Որդուն եւ հաւատայ նրան, ունենայ յաւիտենական կեանք. եւ ես նրան վերջին օրը յարութիւն առնել տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Հրեաները տրտնջում էին նրանից, որովհետեւ ասել էր՝ ե՛ս եմ երկնքից իջած հացը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Եւ ասում էին. «Սա Յիսուսը չէ՞՝ Յովսէփի որդին, որի հօրն ու մօրը մենք ճանաչում ենք: Իսկ արդ, ինչպէ՞ս է ասում՝ ես երկնքից իջայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Մի՛ քրթմնջէք իրար մէջ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'ոչ ոք չի կարող գալ դէպի ինձ, եթէ նրան չձգի Հայրը, որ ինձ ուղարկեց, եւ ես նրան վերջին օրը յարութիւն առնել կը տամ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Մարգարէների գրքերում գրուած է. «Եւ ամէնքը Աստծուց ուսած կը լինեն»: Ամէն ոք, որ լսում է Հօրից եւ ուսանում է, գալիս է դէպի ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Սակայն ոչ ոք Հօրը չի տեսել, այլ միայն նա, որ Աստծուց է, նա՛ է տեսել Հօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ, ով հաւատում է, ունենում է յաւիտենական կեանքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ես եմ կենաց հացը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Ձեր հայրերը անապատում մանանան կերան, սակայն մեռան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Այս է երկնքից իջած հացը, որպէսզի, ով որ սրանից ուտի, չմեռնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ես եմ կենդանի հացը, որ երկնքից է իջած.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'թէ մէկն այս հացից ուտի, յաւիտենապէս կ՚ապրի. եւ այն հացը, որ ես կը տամ, իմ մարմինն է, որը ես կը տամ, որպէսզի աշխարհը կեանք ունենայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Հրեաները իրար հետ բուռն կերպով վիճում էին եւ ասում. «Սա ինչպէ՞ս կարող է իր մարմինը մեզ տալ՝ ուտելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Յիսուս նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, եթէ չուտէք մարդու Որդու մարմինը եւ չըմպէք նրա արիւնը, ձեր մէջ կեանք չէք ունենայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Ով ուտում է իմ մարմինը եւ ըմպում իմ արիւնը, յաւիտենական կեանք ունի. եւ ես նրան վերջին օրը յարութիւն առնել պիտի տամ,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'քանի որ իմ մարմինը ճշմարիտ կերակուր է, եւ իմ արիւնը՝ ճշմարիտ ըմպելիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Ով ուտում է իմ մարմինը եւ ըմպում իմ արիւնը, կը բնակուի իմ մէջ, եւ ես՝ նրա մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Ինչպէս Հայրը, որ ինձ ուղարկեց, ապրում է, ես էլ ապրում եմ Հօր միջոցով. եւ ով ուտում է ինձ, նա էլ կ՚ապրի իմ միջոցով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Այս է հացը, որ երկնքից է իջած. ոչ այնպէս, ինչպէս մանանան, որը ձեր հայրերը կերան եւ մեռան. ով այս հացն ուտում է, կ՚ապրի յաւիտեան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Նա այս բաներն ասաց Կափառնայումի մէջ ժողովարանում ուսուցանելիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Եւ աշակերտներից շատերը, երբ լսեցին, ասացին. «Խիստ է այդ խօսքը. ո՞վ կարող է այն լսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Յիսուս երբ ինքն իրենից իմացաւ, որ իր աշակերտները դրա համար տրտնջում են, նրանց ասաց. «Այդ ձեզ գայթակղեցնո՞ւմ է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'իսկ արդ, եթէ տեսնէք մարդու Որդուն բարձրանալիս այնտեղ, ուր առաջ էր...»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, '«Հոգին է կենդանարար. մարմինը ոչ մի բան չի կարող անել: Այն խօսքը, որ ես ձեզ ասացի, հոգի է եւ կեանք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Բայց ձեր մէջ կան ոմանք, որ չեն հաւատում»: Քանի որ Յիսուս սկզբից գիտէր, թէ ովքեր են նրանք, որ չեն հաւատում, եւ ով է նա, որ մատնելու է իրեն, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, '«Դրա համար ձեզ ասացի, թէ ոչ ոք չի կարող գալ ինձ մօտ, եթէ այդ իմ Հօրից տրուած չէ նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Դրա վրայ՝ նրա աշակերտներից շատերը յետ քաշուեցին եւ այլեւս նրա հետ չէին շրջում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Յիսուս տասներկու աշակերտներին ասաց. «Միթէ դո՞ւք էլ ուզում էք գնալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Սիմոն Պետրոսը նրան պատասխանեց. «Տէ՛ր, ո՞ւմ մօտ պիտի գնանք: Դու յաւիտենական կեանքի խօսքեր ունես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Եւ մենք հաւատացինք եւ ճանաչեցինք, որ դու ես Քրիստոսը՝ Աստծու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Յիսուս նրանց պատասխանեց. «Չէ՞ որ ես եմ ընտրել ձեզ՝ Տասներկուսիդ. եւ ձեզանից մէկը սատանայ է»: Նա խօսում էր Իսկարիովտացու՝ Սիմոնի որդի Յուդայի մասին, որովհետեւ հէնց նա էր մատնելու նրան. եւ Տասներկուսից մէկն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Դրանից յետոյ Յիսուս շրջում էր Գալիլիայում, քանի որ չէր կամենում Հրէաստանում շրջել, որովհետեւ հրեայ առաջնորդները ուզում էին սպանել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Հրեաների Տաղաւարահարաց տօնը մօտ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Եւ նրա եղբայրներն ասացին նրան. «Այստեղից անցիր գնա՛ Հրէաստան, որպէսզի քո աշակերտներն էլ տեսնեն այն գործերը, որ դու անում ես.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'որովհետեւ չկայ մէկը, որ թաքուն գործի եւ դեռ ուզենայ իրեն համարձակ ներկայացնել. եթէ այդ գործերն անում ես, ուրեմն յայտնի՛ր քեզ աշխարհին».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'քանի որ եղբայրներն իսկ դեռեւս չէին հաւատացել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Յիսուս նրանց ասաց. «Իմ ժամանակը դեռ չի հասել, բայց ձեր ժամանակը միշտ պատրաստ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Աշխարհը չի կարող ձեզ ատել, բայց ինձ ատում է, որովհետեւ ես վկայում եմ աշխարհի մասին, թէ մարդկանց գործերը չար են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Դուք գնացէ՛ք այդ տօնին, ես այդ տօնին չեմ գնում, որովհետեւ իմ ժամանակը դեռ չի լրացել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Երբ այս ասաց, ինքը մնաց այնտեղ, Գալիլիայում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Երբ նրա եղբայրները գնացին, ապա ինքն էլ գնաց տօնին, բայց ոչ յայտնապէս, այլ՝ թաքուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Իսկ հրեաները նրան փնտռում էին այդ տօնի ժամանակ եւ ասում էին՝ ո՞ւր է նա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Եւ ժողովրդի բազմութեան մէջ նրա մասին քրթմնջիւն կար. ոմանք ասում էին՝ լաւն է, ուրիշներ ասում էին՝ չէ, ընդհակառակը, ժողովրդին մոլորեցնում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Եւ հրեայ առաջնորդների վախի պատճառով ոչ ոք նրա մասին համարձակ չէր խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Տօնակատարութեան կէսին Յիսուս տաճար ելաւ եւ ուսուցանում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Հրեաները զարմանում էին ու ասում. «Սա ինչպէ՞ս գիտէ Գրուածքները, քանի որ բնաւ չի սովորել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Յիսուս նրանց պատասխան տուեց ու ասաց. «Իմ ուսուցումն իմը չէ, այլ՝ նրանը, ով ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Եթէ մէկը ուզում է նրա կամքը կատարել, կ՚իմանայ այս ուսուցման մասին, թէ Աստծո՞ւց է արդեօք, թէ՞ ես ինքս ինձնից եմ խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Ով ինքն իրենից է խօսում, իր համար է փառք փնտռում, իսկ ով փնտռում է նրա՛ փառքը, ով իրեն ուղարկել է, նա ճշմարիտ է, եւ նրա մէջ սուտ բան չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Օրէնքը ձեզ Մովսէսը չտուե՞ց, բայց ձեզնից ոչ ոք Օրէնքը չի կատարում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Ինչո՞ւ էք ուզում ինձ սպանել»: Ժողովուրդը պատասխան տուեց ու ասաց. «Քո մէջ դեւ կայ, ո՞վ է ուզում քեզ սպանել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Յիսուս պատասխան տուեց նրանց ու ասաց. «Մի գործ արեցի, եւ ամէնքդ զարմացել էք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Մովսէսը դրա համար ձեզ տուեց թլփատութիւնը (թէեւ այդ ոչ թէ Մովսէսից էր, այլ՝ հայրերից):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Եւ շաբաթ օրով մարդ էք թլփատում: Իսկ արդ, եթէ մարդը շաբաթ օրով թլփատւում է, որպէսզի Մովսէսի Օրէնքը չխախտուի, իմ վրա՞յ էք բարկացած, որ շաբաթ օրով մի ամբողջ մարդ բժշկեցի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Աչքներիդ երեւացածի պէս մի՛ դատէք, այլ ուղի՛ղ դատաստան արէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Երուսաղէմացիներից ոմանք ասում էին. «Սա չէ՞ նա, որին ուզում էին սպանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Իսկ ահաւասիկ բացայայտօրէն խօսում է, եւ դրան բան չեն ասում. գուցէ արդարեւ իշխանաւորներն էլ ճանաչեցին, թէ սա՛ է Քրիստոսը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Բայց մենք սրան գիտենք, թէ որտեղից է. իսկ Քրիստոս երբ որ գայ, ոչ ոք չի գիտենայ, թէ որտեղից է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Յիսուս աղաղակեց տաճարի մէջ, ուսուցանում էր եւ ասում. «Ե՛ւ ինձ գիտէք, ե՛ւ գիտէք որտեղից եմ. ինքս ինձ չեմ եկել, այլ ճշմարիտ է նա, ով ինձ ուղարկեց. նա, որին դուք չգիտէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ես գիտեմ նրան, որովհետեւ նրանից իսկ եմ, եւ նա՛ ուղարկեց ինձ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Ուզում էին նրան բռնել, բայց ոչ ոք նրա վրայ ձեռք չդրեց, որովհետեւ նրա ժամանակը դեռ չէր հասել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Սակայն բազմութեան միջից շատերը հաւատացին նրան եւ ասում էին. «Երբ Քրիստոսը գայ, միթէ աւելի՞ նշաններ պիտի անի, քան սա է անում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Եւ փարիսեցիները նրա մասին ժողովրդի մէջ եղած քրթմնջիւնները լսեցին. եւ քահանայապետներն ու փարիսեցիները սպասաւորներ ուղարկեցին, որպէսզի բռնեն նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Յիսուս ասաց. «Մի փոքր ժամանակ էլ ձեզ հետ եմ եւ ապա գնում եմ նրա մօտ, ով ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ինձ կը փնտռէք եւ չէք գտնի, եւ ուր ես եմ գնում, դուք չէք կարող գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Հրեայ առաջնորդներն իրար ասում էին. «Իսկ դա ո՞ւր պիտի գնայ, որ մենք դրան չգտնենք. միթէ հեթանոսների մէջ ցրուած հրեաների՞ մօտ պիտի գնայ եւ հեթանոսների՞ն պիտի ուսուցանի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Ի՞նչ է այն խօսքը, որ նա ասաց՝ կը փնտռէք ինձ եւ չէք գտնի, եւ ուր ես եմ գնում, դուք չէք կարող գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Մեծ տօնի վերջին օրը Յիսուս կանգնած էր եւ աղաղակում էր՝ ասելով. «Եթէ մէկը ծարաւ է, թող ինձ մօտ գայ եւ խմի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Ով ինձ հաւատում է, - ինչպէս Գիրքն է ասում, - նրա ներսից կենդանի ջրերի գետեր պիտի բխեն»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Նա այս ասում էր Հոգու մասին, որին ընդունելու էին իրեն հաւատացողները. քանի որ Հոգին դեռեւս չկար, որովհետեւ Յիսուս դեռ փառաւորուած չէր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Ժողովրդից ոմանք, երբ լսում էին այս խօսքերը, ասում էին՝ սա՛ է ճշմարիտ մարգարէն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'ուրիշներն ասում էին՝ սա՛ է Քրիստոսը. իսկ դեռ ուրիշներ ասում էին՝ միթէ Քրիստոս Գալիլիայի՞ց է գալու.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'չէ՞ որ Գիրքն ասում է, թէ Քրիստոս գալու է Դաւթի սերնդից եւ Բեթղեհէմ գիւղից, որտեղից Դաւիթն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Եւ ժողովրդի մէջ նրա պատճառով պառակտում եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Եւ նրանցից ոմանք ուզեցին բռնել նրան, բայց ոչ ոք նրա վրայ ձեռք չդրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Իսկ սպասաւորները վերադարձան քահանայապետների եւ փարիսեցիների մօտ. եւ սրանք նրանց ասացին. «Ինչո՞ւ նրան այստեղ չբերեցիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Սպասաւորները պատասխանեցին ու ասացին. «Ոչ մի մարդ երբեք այնպէս չի խօսել, ինչպէս այն մարդը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Փարիսեցիները ասացին. «Միթէ դո՞ւք էլ էք մոլորուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Միթէ իշխանաւորներից կամ փարիսեցիներից որեւէ մէկը հաւատա՞ց նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'բացի այն խաժամուժ ամբոխից, որ օրէնք չգիտէ եւ նզովեալ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Նիկոդեմոսը, որ նախապէս գիշերով եկել էր նրա մօտ եւ նրանցից մէկն էր, նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '«Միթէ մեր օրէնքը դատապարտո՞ւմ է մարդուն, եթէ նախ նրանից լսած եւ կամ իմացած չլինի, թէ ինչ է գործել նա»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Նրան պատասխանեցին ու ասացին. «Միթէ դո՞ւ էլ Գալիլիայից ես. քննի՛ր ու տե՛ս, որ Գալիլիայից մարգարէ դուրս չի գալիս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Ապա ամէն ոք իր տունը գնաց: Իսկ Յիսուս գնաց Ձիթենեաց լեռը: Ապա ամէն ոք իր տունը գնաց: Իսկ Յիսուս գնաց Ձիթենեաց լեռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Առաւօտեան նորից տաճար եկաւ. ամբողջ ժողովուրդը գալիս էր նրա մօտ, եւ ինքն ուսուցանում էր նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Օրէնսգէտներն ու փարիսեցիները բերեցին շնութեան մէջ բռնուած մի կին եւ նրան մէջտեղ կանգնեցնելով՝ ասացին Յիսուսին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, '«Յանցանքի մէջ բռնուած այս կինը յայտնապէս շնացել է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'իսկ Օրէնքում Մովսէսը մեզ պատուիրել է այսպիսիներին քարկոծել. արդ, դու դրա մասին ի՞նչ ես ասում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Նրանք այս ասում էին՝ նրան փորձելու համար, որպէսզի նրան ամբաստանելու պատճառ ունենան: Իսկ Յիսուս, ցած նայելով, մատով գետնի վրայ գրում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Իսկ երբ նրան ստիպեցին հարցնելով, վեր նայեց ու նրանց ասաց. «Ձեր միջից անմե՛ղը նախ թող քար գցի դրա վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Եւ դարձեալ ցած նայելով՝ գետնի վրայ գրում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Եւ այս լսելով՝ մէկ առ մէկ ելնում գնում էին՝ տարիքաւորներից մինչեւ փոքրերը: Եւ Յիսուս միայն մնաց ու կինը՝ կանգնած նրա առաջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Յիսուս նրան ասաց. «Ո՛վ կին, ո՞ւր են. քեզ ոչ ոք չդատապարտե՞ց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Եւ սա ասաց՝ ո՛չ, Տէ՛ր: Եւ Յիսուս ասաց. «Ես էլ քեզ չեմ դատապարտում. գնա՛, այսուհետեւ մի՛ մեղանչիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Յիսուս դարձեալ խօսեց ժողովրդի հետ ու ասաց. «Ես եմ աշխարհի լոյսը. ով իմ յետեւից է գալիս, խաւարի միջով չի քայլի, այլ կ՚ընդունի կենաց լոյսը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Փարիսեցիները նրան ասացին. «Դու քո անձի մասին ես վկայում, եւ քո վկայութիւնը հաւաստի չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Յիսուս պատասխանեց եւ ասաց նրանց. «Թէպէտ ես վկայում եմ իմ անձի մասին, իմ վկայութիւնը ճշմարիտ է, որովհետեւ գիտեմ, թէ որտեղից եկայ եւ ուր եմ գնում: Բայց դուք չգիտէք՝ որտեղից եմ գալիս կամ ուր եմ գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Դուք ըստ մարմնի էք դատում, ես ոչ ոքի չեմ դատում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'թէկուզ եւ մէկին դատեմ էլ, իմ դատաստանը ճշմարիտ է, որովհետեւ մենակ չեմ, այլ՝ ես եմ եւ ինձ հետ է նաեւ իմ Հայրը, որ ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Եւ ձեր օրէնքում իսկ գրուած է, թէ երկու մարդու վկայութիւնը ճշմարիտ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ես նա եմ, որ վկայում եմ իմ մասին, եւ վկայում է իմ մասին Հայրը, որ ինձ ուղարկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Նրան ասացին. «Ո՞ւր է քո Հայրը»: Յիսուս պատասխան տուեց եւ ասաց նրանց. «Ո՛չ ինձ էք ճանաչում եւ ո՛չ էլ իմ Հօրը. եթէ ինձ ճանաչէիք, թերեւս իմ Հօրն էլ կը ճանաչէիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Յիսուս այս խօսքերը խօսեց գանձատանը, երբ ուսուցանում էր տաճարում. սակայն ոչ ոք նրան չբռնեց, որովհետեւ նրա ժամը դեռ չէր հասել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Յիսուս դարձեալ նրանց ասաց. «Ես գնում եմ, եւ դուք ինձ կը փնտռէք եւ ձեր մեղքերի մէջ կը մեռնէք, քանի որ, ուր ես եմ գնում, դուք չէք կարող գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Հրեաները ասացին. «Միթէ անձնասպանութեա՞ն կը դիմի, քանի որ ասում է, թէ՝ ուր ես եմ գնում, դուք չէք կարող գալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Եւ նրանց ասաց. «Դուք այս ներքեւից էք, իսկ ես՝ այն վերեւից. դուք այս աշխարհից էք, ես այս աշխարհից չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Բայց ասացի ձեզ, որ ձեր մեղքերի մէջ կը մեռնէք. արդարեւ, եթէ չհաւատաք, որ ես եմ, կը մեռնէք ձեր մեղքերի մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Նրան ասացին՝ ո՞վ ես դու: Յիսուս նրանց ասաց. «Նա, որ սկզբից եւեթ խօսում էր ձեզ հետ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Շատ բաներ ունեմ ձեր մասին խօսելու եւ դատելու: Բայց նա, ով ինձ ուղարկեց, ճշմարիտ է. եւ ես, ինչ որ լսել եմ նրանից, ա՛յն եմ խօսում աշխարհում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Եւ նրանք չիմացան, թէ Հօր մասին էր ասում իրենց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Յիսուս նրանց ասաց. «Երբ մարդու Որդուն բարձրացնէք, այն ժամանակ պիտի իմանաք, թէ ես եմ. եւ ես ինքս ինձնից ոչինչ չեմ անում, այլ՝ ինչպէս իմ Հայրն ինձ սովորեցրեց, ա՛յն եմ խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Եւ ով ինձ ուղարկեց, ինձ հետ է. ինձ միայնակ չթողեց, որովհետեւ ես միշտ անում եմ, ինչ որ նրան է հաճելի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Երբ այս բաները խօսեց, շատերը հաւատացին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Եւ Յիսուս հաւատացեալ հրեաներին ասաց. «Եթէ դուք իմ ուսուցմանը հաւատարիմ մնաք, իմ ճշմարիտ աշակերտները կը լինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Եւ կը ճանաչէք ճշմարտութիւնը, եւ ճշմարտութիւնը ձեզ կ՚ազատի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Նրան պատասխանեցին ու ասացին. «Աբրահամի որդիներ ենք եւ երբեք ոչ ոքի չենք ծառայել. ինչպէ՞ս ես ասում, թէ՝ ազատ կը լինէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Յիսուս պատասխանեց նրանց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, թէ ամէն ոք, որ մեղք է գործում, մեղքին ծառայ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Եւ ծառան յաւիտեան տան մէջ չի մնում, իսկ որդին յաւիտեան մնում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Իսկ արդ, եթէ Որդին ձեզ ազատի, ճշմարտապէս ազատ կը լինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Գիտեմ, որ Աբրահամի որդիներ էք, բայց ուզում էք ինձ սպանել, որովհետեւ իմ խօսքը տեղ չունի ձեր մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ես խօսում եմ այն, ինչ տեսայ իմ Հօր մօտ, իսկ դուք անում էք, ինչ ձեր հօրից էք լսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Նրան պատասխանեցին ու ասացին. «Մեր հայրը Աբրահամն է»: Յիսուս նրանց ասաց. «Եթէ Աբրահամի որդիներ լինէիք, Աբրահամի գործերը կը գործէիք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Իսկ այժմ ուզում էք սպանել մի մարդու՝ ինձ, որ ձեզ ասացի ճշմարտութիւնը, որը լսել եմ իմ Հօրից. այդպիսի բան Աբրահամը չարեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'դուք ձեր հօր գործերն էք անում»: Նրան ասացին. «Մենք պոռնկութիւնից չենք ծնուել. մեր Հայրը մէկ է՝ Աստուած»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Յիսուս նրանց ասաց. «Եթէ Աստուած ձեր Հայրը լինէր, ինձ իրապէս կը սիրէիք, որովհետեւ ես Աստծուց ելայ ու եկայ. եւ ոչ թէ ինքս ինձ եկայ, այլ նա՛ ուղարկեց ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Ինչո՞ւ դուք իմ խօսածը չէք հասկանում. որովհետեւ իմ խօսքը չէք կարող լսել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Դուք հօր կողմից սատանայի զաւակներ էք, եւ ձեր հօր ցանկութիւններն էք ուզում կատարել, թէեւ նա ի սկզբանէ մարդասպան էր եւ ճշմարտութեան մէջ չմնաց, որովհետեւ նրա մէջ ճշմարտութիւն չկար: Երբ որ նա սուտ խօսի, ինքն իրենից է խօսում, քանի որ նա սուտ է »ւ ստի հայր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Իսկ ես, որ ճշմարտութիւնն եմ ասում, ինձ չէք հաւատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Ձեզնից ո՞վ կը յանդիմանի ինձ մեղքի համար. եթէ ճշմարիտ եմ ասում ձեզ, ինձ ինչո՞ւ չէք հաւատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Ով Աստծուց է, Աստծու խօսքերն է լսում, իսկ դուք չէք լսում նրա համար, որ Աստծուց չէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Հրեաները պատասխանեցին եւ ասացին նրան. «Մենք լաւ չե՞նք ասում, թէ՝ սամարացի ես դու, եւ քո մէջ դեւ կայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Յիսուս պատասխանեց եւ ասաց. «Իմ մէջ դեւ չկայ, այլ պատւում եմ իմ Հօրը, իսկ դուք անարգում էք ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ես իմ փառքը չեմ փնտռում. կայ մէկը, որ այն փնտռում է եւ դատում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթէ մէկը իմ խօսքը պահի, մահ չի տեսնի յաւիտեան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Հրեաները նրան ասացին. «Այժմ իմացանք, որ քո մէջ դեւ կայ: Աբրահամը մեռաւ, նաեւ՝ մարգարէները, իսկ դու ասում ես, թէ՝ ով իմ խօսքը պահի, յաւիտեան մահ չի ճաշակի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Միթէ դու աւելի մե՞ծ ես, քան մեր հայրը՝ Աբրահամը, որ մեռաւ. մեռան եւ մարգարէները. արդ, դու քեզ ո՞ւմ տեղ ես դնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Յիսուս պատասխանեց. «Եթէ ես փառաւորեմ իմ անձը, իմ փառքը ոչինչ է. Հայրն է, որ ինձ փառաւորում է, եւ որի մասին դուք ասում էք, թէ՝ մեր Աստուածն է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'ու չէք ճանաչում նրան: Բայց ես ճանաչում եմ նրան. եւ եթէ ասեմ, թէ նրան չեմ ճանաչում, ձեզ նման ստախօս կը լինեմ. բայց ես ճանաչում եմ նրան եւ նրա խօսքը պահում եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Աբրահամը՝ ձեր հայրը, ցանկացաւ իմ աշխարհ գալու օրը տեսնել. տեսաւ եւ ուրախացաւ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Հրեաները նրան ասացին. «Դեռ յիսուն տարեկան չկաս դու եւ Աբրահամի՞ն ես տեսել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Յիսուս նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, ես ե՛մ, նախքան Աբրահամի լինելը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Նրանք քարեր վերցրին, որ գցեն նրա վրայ, բայց Յիսուս խոյս տուեց եւ տաճարից ելաւ գնաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Եւ մինչ անցնում էր, ի ծնէ կոյր մի մարդու տեսաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'իր աշակերտները հարցրին նրան եւ ասացին. «Ռաբբի՛, մեղքը ո՞ւմն է, որ կոյր է ծնուել, սրա՞նն է, թէ՞ հօրն ու մօրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Յիսուս պատասխանեց. «Ո՛չ դրա մեղքն է եւ ոչ էլ իր հօր ու մօր, այլ՝ որպէսզի դրա վրայ Աստծու գործերը յայտնի լինեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Եւ քանի դեռ ցերեկ է, ես պէտք է կատարեմ գործերը նրա, ով ինձ ուղարկեց. կը գայ գիշերը, երբ ոչ ոք չի կարող գործել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Քանի դեռ աշխարհում եմ, աշխարհի լոյսն եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Երբ այս ասաց, թքեց գետնին եւ թքով կաւ շինեց, եւ կաւը ծեփեց կոյրի աչքերի վրայ ու ասաց նրան.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, '«Գնա՛ լուացուիր Սիլովամի աւազանի մէջ» (որ թարգմանւում է՝ առաքուած): Գնաց լուացուեց, եկաւ եւ տեսնում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Իսկ հարեւանները եւ նրանք, որ նախապէս տեսել էին նրան, որ մուրացիկ էր, ասում էին. «Սա չէ՞ր, որ նստում էր եւ մուրում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Ոմանք ասում էին՝ նա է. ուրիշներ ասում էին՝ ո՛չ, բայց նման է նրան: Իսկ ինքն ասում էր՝ ես եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Նրան ասացին. «Իսկ ինչպէ՞ս բացուեցին քո աչքերը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Նա պատասխանեց. «Մի մարդ, որին ասում են՝ Յիսուսն է, կաւ շինեց եւ ծեփեց իմ աչքերը եւ ինձ ասաց. «Գնա՛ Սիլովամ եւ լուացուի՛ր»: Գնացի, լուացուեցի եւ տեսնում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Նրան ասացին՝ ո՞ւր է նա: Նրանց ասաց՝ չգիտեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Նրան, որ մի ժամանակ կոյր էր, բերին փարիսեցիների մօտ');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, '(օրը շաբաթ էր, երբ Յիսուս կաւ շինեց եւ կոյրի աչքերը բացեց):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Փարիսեցիներն էլ կրկին հարցրին նրան. «Ինչպէ՞ս ես տեսնում»: Եւ նա նրանց ասաց. «Կաւ դրեց աչքերիս վրայ, եւ լուացուեցի ու տեսնում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Փարիսեցիներից ոմանք ասացին. «Այդ մարդը Աստծուց չէ, քանի որ շաբաթ օրը չի պահում»: Ոմանք ասում էին. «Իսկ մեղաւոր մի մարդ ինչպէ՞ս կարող է այսպիսի նշաններ կատարել»: Եւ նրանց մէջ պառակտում կար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Դարձեալ կոյրին ասացին. «Դո՛ւ ինչ ես ասում նրա մասին, քանի որ նա քո աչքերը բացեց»: Եւ նա ասաց՝ մարգարէ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Եւ հրեաները չէին հաւատում, թէ նա կոյր էր, եւ բացուեց, մինչեւ որ կանչեցին աչքերը բացուածի ծնողներին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'հարցրին նրանց ու ասացին. «Սա՞ է ձեր որդին, որի մասին ասում էիք, թէ՝ կոյր ծնուեց. իսկ այժմ ինչպէ՞ս է, որ տեսնում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Նրա ծնողները պատասխանեցին եւ ասացին. «Գիտենք, որ սա մեր որդին է, եւ որ կոյր ծնուեց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'բայց թէ այժմ ինչպէ՛ս է, որ տեսնում է, չգիտենք, կամ թէ՝ ո՛վ բացեց դրա աչքերը, մենք չգիտենք. հէնց իրե՛ն հարցրէք. ինքն արդէն չափահաս է. իր մասին ինքը թող խօսի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Նրա ծնողները այսպէս ասացին, որովհետեւ հրեաներից վախենում էին, քանի որ հրեաները երդուել էին, որ, եթէ մէկը նրան Քրիստոս խոստովանի, հեռացուի ժողովարանից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Դրա համար է, որ նրա ծնողներն ասացին. «Ինքն արդէն չափահաս է, հէնց իրե՛ն հարցրէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Նորից կրկին անգամ կանչեցին այդ մարդուն, որ կոյր էր, եւ նրան ասացին. «Աստծուն փա՛ռք տուր. մենք գիտենք, որ այն մարդը մեղաւոր է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Իսկ նա ասաց. «Թէ մեղաւոր է, ես չգիտեմ, բայց այն գիտեմ, որ կոյր էի եւ հիմա տեսնում եմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Դարձեալ ասացին նրան. «Քեզ ի՞նչ արեց, քո աչքերը ինչպէ՞ս բացեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Նրանց պատասխանեց. «Նոր ձեզ ասացի, եւ չէք լսում, ինչո՞ւ էք ուզում նորից լսել. միթէ դո՞ւք էլ էք կամենում նրան աշակերտել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Նրանք նախատում էին նրան ու ասում. «Դո՛ւ եղիր նրան աշակերտ. մենք Մովսէսի աշակերտներն ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Մենք գիտենք, որ Աստուած Մովսէսի հետ խօսեց. իսկ սրան չգիտենք, թէ որտեղից է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Մարդը պատասխանեց նրանց եւ ասաց. «Զարմանալին էլ այն է, որ դուք չգիտէք, թէ նա որտեղից է, եւ սակայն իմ աչքերը բացեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Գիտենք, որ Աստուած մեղաւորներին չի լսում, բայց եթէ մէկը աստուածապաշտ է եւ նրա կամքը կատարում է, նրան լսում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Աշխարհի սկզբից ոչ ոք չի լսել, թէ մէկը ի ծնէ կոյր ծնուած կոյրի աչքերը բացած լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Եթէ այդ մարդը Աստծուց չլինէր, որեւէ բան անել չէր կարող»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Պատասխանեցին եւ ասացին նրան. «Ամբողջովին մեղքի մէջ ես ծնուած եւ դու մեր գլխին վարդապե՞տ ես դարձել»: Եւ նրան դուրս հանեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Յիսուս լսեց, թէ նրան դուրս են հանել. եւ երբ նրան գտաւ, ասաց. «Դու Աստծու Որդուն հաւատո՞ւմ ես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Նա պատասխան տուեց եւ ասաց. «Տէ՛ր, ո՞վ է, որ նրան հաւատամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Յիսուս նրան ասաց. «Ե՛ւ տեսար նրան, ե՛ւ նա է, ով խօսում է քեզ հետ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Ու նա ասաց. «Հաւատում եմ, Տէ՛ր»: Եւ երկրպագեց նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Եւ Յիսուս ասաց. «Դատաստանի համար եկայ այս աշխարհը, որպէսզի, ովքեր չեն տեսնում, տեսնեն, եւ ովքեր տեսնում են, կուրանան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Փարիսեցիներից ոմանք, որ Յիսուսի հետ էին, այդ լսեցին ու նրան ասացին. «Միթէ մե՞նք էլ կոյր ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Յիսուս նրանց ասաց. «Եթէ կոյր լինէիք, դուք մեղք չէիք ունենայ, բայց հիմա ասում էք, թէ՝ տեսնում ենք. եւ ձեր մեղքը ձեր մէջ հաստատ է մնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '«Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, ով ոչխարների փարախը դռնով չի մտնում, այլ ուրիշ տեղով է բարձրանում, նա գող է եւ աւազակ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'իսկ ով դռնով է մտնում, հովիւ է ոչխարների:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Դռնապանը նրա համար բացում է դուռը, եւ ոչխարները լսում են նրա ձայնը. նա իր ոչխարներին անուններով է կանչում եւ նրանց դուրս է հանում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Եւ երբ իր բոլոր ոչխարներին հանի, նրանց առջեւից է գնում, եւ ոչխարները հետեւում են նրան, որովհետեւ ճանաչում են նրա ձայնը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Օտարի յետեւից չեն գնայ, այլ կը փախչեն նրանից, որովհետեւ չեն ճանաչում օտարների ձայնը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Յիսուս նրանց այս առակն ասաց, իսկ նրանք չէին իմանում, թէ ինչ էր այն, որ նա իրենց ասում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Դարձեալ Յիսուս նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ ես եմ ոչխարների դուռը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Բոլոր նրանք, որ ինձնից առաջ եկան, գողեր էին ու աւազակներ, ուստի ոչխարները նրանց չլսեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ես եմ դուռը. եթէ մէկը իմ միջով մտնի, կը փրկուի. կը մտնի ու կ՚ելնի եւ ճարակելու բան կը գտնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Գողը գալիս է միայն, որպէսզի գողանայ, սպանի եւ կորստեան մատնի. ես եկայ, որպէսզի կեանք ունենան եւ՝ առաւել եւս ունենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ես եմ լաւ հովիւը. լաւ հովիւը իր կեանքն է տալիս ոչխարների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Իսկ վարձկանը, որ հովիւ չէ, եւ ոչխարներն էլ իրենը չեն, երբ տեսնում է, որ գայլը գալիս է, թողնում է ոչխարներին եւ փախչում է: Եւ գայլը յափշտակում է նրանց ու ցրում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'քանի որ վարձկան է, եւ ոչխարների համար հոգ չի անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ես եմ լաւ հովիւը. եւ ճանաչում եմ իմ ոչխարներին ու ճանաչւում նրանցից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Ինչպէս Հայրը ինձ ճանաչում է, ես էլ ճանաչում եմ Հօրը. եւ իմ կեանքը կը տամ իմ ոչխարների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Ես ունեմ նաեւ այլ ոչխարներ, որոնք այս փարախից չեն. նրանց եւս պէտք է այստեղ բերեմ. եւ իմ ձայնը պիտի լսեն. եւ պիտի լինի մի հօտ եւ մի հովիւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Նրա համար է իմ Հայրն ինձ սիրում, որ ես իմ կեանքն եմ տալիս, որպէսզի վերստին այն առնեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Այն ինձնից ոչ ոք չի վերցնի, այլ ես ինքս եմ այն տալիս. իշխանութիւն ունեմ այն տալու եւ իշխանութիւն ունեմ վերստին այն առնելու. այս պատուէրը իմ Հօրից ստացայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Այս խօսքերի պատճառով հրեաների մէջ դարձեալ պառակտում եղաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Եւ նրանցից շատերն ասում էին. «Նրա մէջ դեւ կայ եւ մոլեգնում է. ինչո՞ւ էք նրան լսում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Ոմանք էլ ասում էին. «Սրանք դիւահարի խօսքեր չեն, միթէ դեւը կարո՞ղ է կոյրի աչքերը բանալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Այն ժամանակ Երուսաղէմում տաճարի Նաւակատիքի տօն էր, եւ ձմեռ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Եւ Յիսուս շրջում էր տաճարի մէջ, Սողոմոնի սրահում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Հրեաները նրա շուրջը հաւաքուեցին ու ասացին. «Մինչեւ ե՞րբ մեր հոգին պիտի հանես. եթէ դու ես Քրիստոսը, համարձակ ասա՛ մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Ձեզ ասացի, եւ ինձ չէք հաւատում. այն գործերը, որ ես անում եմ իմ Հօր անունով, դրանք վկայում են իմ մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Բայց դուք չէք հաւատում, որովհետեւ իմ ոչխարներից չէք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'իմ ոչխարներն իմ ձայնը լսում են, եւ ես ճանաչում եմ նրանց. եւ նրանք գալու են իմ յետեւից.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'եւ ես նրանց կը տամ յաւիտենական կեանք. եւ նրանք չեն կորչի յաւիտեան. եւ ոչ ոք նրանց իմ ձեռքից չի յափշտակի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Իմ Հայրը, որ նրանց ինձ տուեց, ամենքից մեծ է. եւ իմ Հօր ձեռքից ոչ ոք չի կարող ոչինչ յափշտակել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ես եւ իմ Հայրը մի ենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Հրեաները քարեր վերցրին, որ նրան քարկոծեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Յիսուս պատասխանեց նրանց. «Բազում բարի գործեր ցոյց տուի ձեզ իմ Հօրից. դրանցից ո՞ր գործի համար էք ինձ քարկոծում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Հրեաները նրան պատասխանեցին. «Քեզ բարի գործի համար չենք քարկոծում, այլ հայհոյութեան համար եւ նրա համար, որ դու մարդ ես, բայց ինքդ քեզ Աստծու տեղ ես դնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Յիսուս նրանց պատասխանեց. «Ձեր օրէնքում չէ՞, որ գրուած է. «Ես ասացի, թէ աստուածներ էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Իսկ եթէ աստուածներ է կոչում նրանց, որոնց ուղղուած էր Աստծու խօսքը (եւ հնարաւոր չէ, որ Գիրքը ջնջուի),');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'ուրեմն՝ ո՛ւմ Հայրը սրբացրեց եւ աշխարհ ուղարկեց, դուք ասում էք, թէ՝ հայհոյում ես, նրա համար, որ ասացի, թէ՝ Աստծու Որդի եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Եթէ իմ Հօր գործերը չեմ անում, ինձ մի՛ հաւատացէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Իսկ եթէ անում եմ, թէ ինձ էլ չէք հաւատում, գործերի՛ն հաւատացէք, որպէսզի իմանաք եւ ճանաչէք, որ Հայրը իմ մէջ է, եւ ես՝ Հօր մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Դարձեալ ուզում էին նրան բռնել, բայց նա նրանց ձեռքից դուրս պրծաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Եւ վերստին գնաց Յորդանանի միւս կողմը, այնտեղ, ուր Յովհաննէսն էր նախապէս գտնւում եւ մկրտում. եւ այնտեղ էր մնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Շատեր նրա մօտ եկան եւ ասում էին. «Յովհաննէսը որեւէ նշան չարեց, բայց այն ամէնը, որ Յովհաննէսն ասել էր նրա մասին, ճշմարիտ էր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Եւ այնտեղ շատերը հաւատացին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Եւ մի հիւանդ կար, Ղազարոս անունով, Բեթանիայից՝ Մարիամի եւ նրա քոյր Մարթայի գիւղից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Սա այն Մարիամն էր, որ իւղով օծեց Տիրոջը եւ իր մազերով սրբեց նրա ոտքերը: Եւ սրա եղբայր Ղազարոսը հիւանդ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Սրա քոյրերը նրա մօտ մարդ ուղարկեցին եւ ասացին. «Տէ՛ր, ահաւասիկ նա, ում դու սիրում էիր, հիւանդացել է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Երբ Յիսուս լսեց, ասաց. «Այդ հիւանդութիւնը մահաբեր չէ, այլ Աստծու փառքի համար է, որպէսզի դրանով Աստծու Որդին փառաւորուի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Յիսուս սիրում էր Մարիամին, նրա քրոջը՝ Մարթային, եւ Ղազարոսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Լսելուց յետոյ, թէ Ղազարոսը հիւանդացել է, նա տակաւին երկու օր մնաց այնտեղ, ուր գտնւում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Ապա դրանից յետոյ իր աշակերտներին ասաց. «Եկէ՛ք վերստին գնանք Հրէաստան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Աշակերտները նրան ասացին. «Ռաբբի՛, հրեաները դեռ նոր էին ուզում քեզ քարկոծել, եւ նորից այնտե՞ղ ես գնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Յիսուս պատասխանեց. «Ցերեկը տասներկու ժամ չունի՞. եթէ մէկը ցերեկն է քայլում, չի սայթաքում, որովհետեւ այս աշխարհի լոյսը տեսնում է,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'իսկ եթէ մէկը գիշերն է քայլում, սայթաքում է, որովհետեւ հետը լոյս չունի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Այս բաներն ասելուց յետոյ նորից ասաց նրանց. «Մեր բարեկամ Ղազարոսը ննջել է, սակայն ես գնում եմ, որ նրան արթնացնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Աշակերտները նրան ասացին. «Տէ՛ր, եթէ ննջել է, ապա կ՚առողջանայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Բայց Յիսուս նրա մահուան մասին էր ասում, մինչդեռ նրանց այնպէս թուաց, թէ նա քնով ննջելու մասին է խօսում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Այն ժամանակ Յիսուս նրանց յայտնապէս ասաց. «Ղազարոսը մեռաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'բայց ես ուրախ եմ ձեզ համար, որ այնտեղ չէի. որպէսզի դուք ինձ հաւատաք: Արդ, եկէ՛ք գնանք նրա մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Թովմասը, որ Երկուորեակ էր կոչւում, աշակերտակիցներին ասաց. «Եկէ՛ք մենք էլ գնանք, որ նրա հետ մեռնենք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Յիսուս եկաւ, նրան գտաւ չորս օրից ի վեր գերեզմանի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Եւ Բեթանիան Երուսաղէմի մօտ էր շուրջ երեք կիլոմետր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Հրեաներից շատերը եկել էին Մարթայի եւ Մարիամի մօտ, որպէսզի նրանց մխիթարեն իրենց եղբօր մահուան համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Երբ Մարթան լսեց, որ Յիսուս գալիս է, նրան ընդառաջ գնաց. իսկ Մարիամը տանը նստած էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Մարթան Յիսուսին ասաց. «Տէ՛ր, եթէ դու այստեղ եղած լինէիր, իմ եղբայրը մեռած չէր լինի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'բայց հիմա էլ գիտեմ, թէ ինչ էլ որ Աստծուց ուզես, Աստուած քեզ կը տայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Յիսուս նրան ասաց. «Քո եղբայրը յարութիւն կ՚առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Մարթան նրան ասաց. «Գիտեմ, որ յարութեան ժամանակ վերջին օրը յարութիւն կ՚առնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Յիսուս նրան ասաց. «Ես իսկ եմ յարութիւն եւ կեանք. ով հաւատում է ինձ, թէպէտ եւ մեռնի, կ՚ապրի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'եւ ով կենդանի է ու ինձ հաւատում է, յաւիտեան չի մեռնի: Հաւատո՞ւմ ես այս բանին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Նա ասաց նրան. «Այո՛, Տէ՛ր, ես հաւատում եմ, որ դո՛ւ ես Քրիստոսը՝ Աստծու Որդին, որ աշխարհ էիր գալու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Եւ այս ասելուց յետոյ, գնաց գաղտնաբար կանչեց իր քրոջը՝ Մարիամին եւ ասաց. «Վարդապետն է եկել եւ քեզ է կանչում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Երբ նա լսեց, իսկոյն վեր կացաւ եւ եկաւ նրա մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Յիսուս դեռ գիւղ չէր հասել, այլ դեռեւս այն տեղում էր, ուր Մարթան նրան ընդառաջ էր ելել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Իսկ այն հրեաները, որ նրա հետ տանն էին եւ նրան մխիթարում էին, երբ տեսան Մարիամին, որ վեր կացաւ իսկոյն ու գնաց, իրենք եւս նրա յետեւից գնացին. կարծում էին, թէ գերեզման է գնում, որ այնտեղ լաց լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Իսկ Մարիամը, երբ եկաւ այնտեղ, ուր Յիսուս կանգնած էր, ու տեսաւ նրան, ընկաւ նրա ոտքերն ու ասաց. «Տէ՛ր, եթէ այստեղ եղած լինէիր, իմ եղբայրը մեռած չէր լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Երբ Յիսուս տեսաւ, որ նա լալիս է, եւ նրա հետ եղող հրեաներն էլ լալիս են, սաստիկ խռովուեց իր հոգում եւ ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '«Ո՞ւր դրիք նրան»: Նրան ասացին. «Տէ՛ր, արի՛ եւ տե՛ս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Եւ Յիսուս արտասուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Հրեաներն ասացին. «Տեսէ՛ք ինչքան էր սիրում նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Նրանցից ոմանք ասում էին. «Սա, որ կոյրի աչքերը բացեց, չէ՞ր կարող նաեւ այնպէս անել, որ սա չմեռնէր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Յիսուս, դարձեալ խռովուելով ինքն իր մէջ, եկաւ գերեզմանը: Սա մի քարայր էր, որի վրայ մի քար էր դրուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Եւ Յիսուս ասաց. «Այդ քարը մի կողմ դրէք»: Մարթան՝ մեռածի քոյրը, նրան ասաց. «Տէ՛ր, հիմա արդէն նեխած կը լինի, քանի որ չորս օրուայ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Յիսուս նրան ասաց. «Քեզ չասացի՞. եթէ հաւատաս, կը տեսնես Աստծու փառքը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Երբ քարը վերցրին, Յիսուս աչքերը վեր բարձրացրեց ու ասաց. «Հա՛յր, գոհութիւն եմ տալիս քեզ, որ ինձ լսեցիր.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'եւ ես գիտէի, որ ամէն ժամ լսում ես ինձ, բայց այս անում եմ շուրջս կանգնած այս ժողովրդի համար, որպէսզի հաւատան, որ դո՛ւ ինձ ուղարկեցիր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Երբ այս ասաց, բարձր ձայնով աղաղակեց եւ ասաց. «Ղազարո՛ս, վե՛ր կաց, դո՛ւրս արի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Եւ մեռելը ելաւ՝ կապուած ոտքերով, ձեռքերը երիզով ամրացուած եւ երեսը վարշամակով պատած: Եւ Յիսուս նրանց ասաց. «Արձակեցէ՛ք դրան եւ թողէ՛ք, որ գնայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Հրեաներից շատերը, որոնք եկել էին Մարիամենց մօտ, երբ տեսան, ինչ որ Յիսուս արեց, հաւատացին նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Իսկ նրանցից ոմանք գնացին փարիսեցիների մօտ եւ պատմեցին նրանց, ինչ որ Յիսուս արեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Քահանայապետներն ու փարիսեցիները ատեան գումարեցին եւ ասացին. «Ի՞նչ անենք, քանի որ այդ մարդը բազում նշաններ է անում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Եթէ նրան այնպէս թողնենք, ամէնքը կը հաւատան նրան, եւ հռոմէացիները կը գան ու կը վերացնեն մեր ազգն ու մեր սրբավայրը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Նրանցից մէկը՝ Կայիափա անունով, որ այդ տարուայ քահանայապետն էր, նրանց ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, '«Դուք ոչինչ չգիտէք, ոչ իսկ խորհել էք, թէ մեզ համար աւելի լաւ է, որ մէկ մարդ մեռնի ժողովրդի համար, քան թէ ամբողջ ազգը կորչի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Այս բանը նա ինքն իրենից չասաց, այլ, քանի որ այդ տարուայ քահանայապետն էր, մարգարէացաւ, որ Յիսուս մեռնելու էր ազգի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'Եւ ոչ միայն ազգի համար, այլ՝ որպէսզի նաեւ Աստծու ցրուած որդիներին ի մի հաւաքի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Ապա այն օրուանից խորհուրդ արեցին, որ նրան սպանեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Եւ Յիսուս այնուհետեւ այլեւս համարձակ չէր շրջում հրեաների մէջ, այլ այնտեղից գնաց մի շրջան, որ մօտ էր անապատին. գնաց մի քաղաք, որի անունն էր Եփրայիմ, եւ իր աշակերտների հետ այդտեղ էր մնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Եւ հրեաների զատիկը մօտ էր. եւ այդ գաւառից շատերը Երուսաղէմ բարձրացան զատկից առաջ, որպէսզի իրենք իրենց մաքրեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Յիսուսին փնտռում էին. եւ մինչ տաճարի մէջ էին, միմեանց ասում էին. «Ինչպէ՞ս է ձեզ թւում, արդեօք այս տօնին չի՞ գայ»: Քահանայապետներն ու փարիսեցիները հրահանգել էին, որ, եթէ մէկն իմանայ, թէ նա որտեղ է, յայտնի, որպէսզի նրան ձ»րբակալ»ն: Յիսուսին փնտռում էին. եւ մինչ տաճարի մէջ էին, միմեանց ասում էին. «Ինչպէ՞ս է ձեզ թւում, արդեօք այս տօնին չի՞ գայ»: Քահանայապետներն ու փարիսեցիները հրահանգել էին, որ, եթէ մէկն իմանայ, թէ նա որտեղ է, յայտնի, որպէսզի նրան ձ»րբակալ»ն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Իսկ Յիսուս զատկից վեց օր առաջ եկաւ Բեթանիա, ուր ապրում էր մեռած Ղազարոսը, որին մեռելներից վեր էր կացրել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Եւ այնտեղ նրան ընթրիք տուին. սպասարկում էր Մարթան, իսկ Ղազարոսը նրա հետ սեղան նստածներից մէկն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Իսկ Մարիամը մի լիտր ազնիւ նարդոսի թանկարժէք իւղ վերցնելով՝ օծեց Յիսուսի ոտքերը. եւ իր մազերով էլ սրբում էր նրա ոտքերը. եւ տունը լցուեց իւղի բուրմունքով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Աշակերտներից մէկը՝ Յուդա Իսկարիովտացին, որ մատնելու էր նրան, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '«Ինչո՞ւ այդ իւղը չվաճառուեց երեք հարիւր արծաթ դահեկանի եւ չտրուեց աղքատներին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Նա այս ասաց ոչ թէ նրա համար, որ աղքատների համար էր հոգում, այլ որովհետեւ գող էր եւ գանձարկղը ինքն էր պահում, եւ ինչ որ այնտեղ դրւում էր, ինքն էր վերցնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Յիսուս ասաց նրան. «Թո՛յլ տուէք նրան, որպէսզի իմ թաղման օրուայ համար պահի այդ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Աղքատներին ամէն ժամ ձեզ հետ ունէք: Ինձ միշտ ձեզ հետ չունէք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Երբ հրեաներից բազում ժողովուրդ իմացաւ, որ նա այնտեղ է, եկաւ. ոչ միայն Յիսուսի պատճառով, այլ՝ որպէսզի տեսնի նաեւ Ղազարոսին, որին մեռելներից վեր էր կացրել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Քահանայապետները խորհուրդ արեցին, որ Ղազարոսին էլ սպանեն,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'քանի որ շատերը հեռանում էին հրեաներից եւ հաւատում էին Յիսուսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Յաջորդ օրը, ժողովրդի բազմութիւնը, որ զատկի տօնին էր եկել, երբ լսեց, թէ Յիսուս Երուսաղէմ է գալիս,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'արմաւենիների ճիւղեր վերցրեց եւ Յիսուսին ընդառաջ ելաւ: Աղաղակում էին ու ասում. «Ովսաննա՜, օրհնեա՜լ լինես դու, որ գալիս ես Տիրոջ անունով, ո՛վ թագաւոր Իսրայէլի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Եւ Յիսուս մի էշ գտնելով, նստեց նրա վրայ, ինչպէս որ գրուած է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '«Մի՛ վախեցիր, ո՛վ դուստրդ Սիոնի, ահա քո թագաւորը գալիս է՝ նստած մի էշի քուռակի վրայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Եւ նրա աշակերտները սկզբում այն չհասկացան, բայց երբ Յիսուս փառաւորուեց, այն ժամանակ յիշեցին, թէ այդ նրա մասին էր գրուած, եւ իրենք այդ էին արել նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Իսկ ժողովուրդը, որ նրա հետ էր, վկայում էր, որ Ղազարոսին հէնց գերեզմանից կանչեց եւ նրան մեռելներից կենդանացրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Եւ դրա համար էլ նրան ընդառաջ ելաւ ժողովուրդը, որովհետեւ լսել էին, որ այդ նշաններն էր արել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Իսկ փարիսեցիները միմեանց ասում էին. «Տեսնում էք, որ ոչ մի օգուտ չէք ստանում. ահաւասիկ ամբողջ աշխարհը նրա յետեւից գնաց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Այնտեղ կային նաեւ որոշ թուով հեթանոսներ՝ նրանց մէջ, որ Երուսաղէմ էին եկել, որպէսզի տօնի ժամանակ երկրպագութիւն անեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Նրանք մօտեցան Փիլիպպոսին, որ Գալիլիայի Բեթսայիդա քաղաքից էր. աղաչում էին նրան ու ասում. «Տէ՛ր, ուզում ենք Յիսուսին տեսնել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Փիլիպպոսը եկաւ եւ Անդրէասին ասաց: Անդրէասը եւ Փիլիպպոսն էլ Յիսուսին ասացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Եւ Յիսուս նրանց պատասխանեց ու ասաց. «Հասաւ ժամը, որ փառաւորուի մարդու Որդին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթէ ցորենի հատիկը հողի մէջ ընկնելով չմեռնի, միայն հատիկն ինքը կը մնայ, իսկ եթէ մեռնի, բազում արդիւնք կը տայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Ով սիրում է իր անձը, կը կորցնի այն, իսկ ով այս աշխարհում իր անձն ատում է, այն կը պահի յաւիտենական կեանքի համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Եթէ մէկն ինձ ծառայի, իմ յետեւից կը գայ. եւ ուր ես եմ, այնտեղ կը լինի եւ իմ ծառան. եթէ մէկը ինձ ծառայի, նրան կը պատուի իմ Հայրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Բայց այժմ հոգիս խռովուած է. եւ ի՞նչ ասեմ. Հա՛յր, փրկի՛ր ինձ այս ժամից: Բայց ես հէնց այս բանի համար եմ եկել այս ժամին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Հա՛յր, փառաւորի՛ր քո անունը»: Երկնքից մի ձայն եկաւ. «Ե՛ւ փառաւորեցի, եւ դարձեա՛լ պիտի փառաւորեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Եւ ժողովուրդը, որ կանգնած էր ու լսում էր, ասում էր, թէ՝ որոտմունք է լինում: Ոմանք էլ ասացին. «Նրա հետ մի հրեշտակ խօսեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Յիսուս պատասխանեց ու ասաց. «Այս ձայնը ինձ համար չէ, որ եկաւ, այլ՝ ձեզ համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Հիմա՛ է այս աշխարհի դատաստանը, հիմա՛ է, որ այս աշխարհի իշխանը դուրս կը նետուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Եւ երբ ես բարձրանամ երկրից, ամենքին դէպի ինձ կը ձգեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Այս ասում էր նշելու համար, թէ ի՛նչ մահով էր մեռնելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Ժողովուրդը նրան պատասխանեց. «Օրէնքից մենք լսել ենք, թէ Քրիստոս յաւիտեան կը մնայ, իսկ դու ինչպէ՞ս ես ասում, թէ մարդու Որդին պէտք է բարձրանայ. ո՞վ է այդ մարդու Որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Յիսուս նրանց ասաց. «Մի փոքր ժամանակ եւս լոյսը ձեզ հետ է. քայլեցէ՛ք, քանի դեռ լոյսն ունէք, որպէսզի խաւարը ձեզ չկլանի, քանի որ, ով քայլում է խաւարի մէջ, չի իմանում, թէ ուր է գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Քանի դեռ լոյսը ձեզ հետ ունէք, հաւատացէ՛ք լոյսին, որպէսզի լոյսի որդիներ լինէք»: Յիսուս այս խօսեց եւ գնաց նրանցից թաքնուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Թէպէտ եւ նա այնքան նշաններ էր արել նրանց առաջ, նրանք չէին հաւատում նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'որպէսզի կատարուէր Եսայի մարգարէի խօսքը, որ ասաց. «Տէ՛ր, ո՞վ հաւատաց մեր տուած լուրին, եւ Տիրոջ բազուկը ո՞ւմ յայտնուեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Չէին կարողանում հաւատալ եւ այն բանի համար, որ Եսային վերստին ասում է.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '«Նրանց աչքերը կուրացրեց եւ նրանց սրտերը կարծրացրեց, որպէսզի աչքերով չտեսնեն ու սրտերով չիմանան եւ դարձի չգան, ու ես նրանց չբժշկեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Եսային այս ասաց, որովհետեւ տեսաւ նրա փառքը եւ խօսեց նրա մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Բայց մինչեւ անգամ հրեայ իշխանաւորներից շատեր հաւատացին նրան, բայց փարիսեցիների պատճառով չէին յայտնում, որպէսզի ժողովարանից դուրս չհանուեն.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'քանի որ մարդկանցից տրուած փառքը աւելի սիրեցին, քան Աստծուց տրուած փառքը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Յիսուս աղաղակում էր ու ասում. «Ով ինձ է հաւատում, ինձ չէ, որ հաւատում է, այլ նրան, ով ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Եւ ով ինձ է տեսնում, տեսնում է նրան, ով ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ես որպէս լոյս եկայ աշխարհ, որպէսզի ամէն ոք, որ ինձ հաւատում է, խաւարում չմնայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Եւ եթէ մէկը լսի իմ խօսքերը եւ չպահի դրանք, ես նրան չեմ դատապարտի, քանի որ չեկայ, որ աշխարհը դատապարտեմ, այլ՝ որպէսզի փրկեմ աշխարհը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Ով անարգում է ինձ եւ իմ խօսքերը չի ընդունում, կայ մէկը, որ նրան դատում է. այն խօսքը, որ ես խօսեցի, դա՛ պիտի դատապարտի նրան վերջին օրը,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'որովհետեւ ես ինքս ինձնից չխօսեցի, այլ Հայրը, որ ինձ ուղարկեց, նա՛ ինձ պատուիրեց, թէ ի՛նչ պիտի ասեմ եւ ի՛նչ պիտի խօսեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Եւ գիտեմ, որ այն պատուիրանը յաւիտենական կեանք է: Արդ, ինչ որ ես եմ խօսում, այնպէս եմ խօսում, ինչպէս Հայրն ինձ ասաց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Զատկի տօնից առաջ Յիսուս իմացաւ, որ հասել է իր ժամը, որպէսզի այս աշխարհից Հօր մօտ փոխադրուի. սիրեց իւրայիններին, որ այս աշխարհում են, իսպառ սիրեց նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Եւ ընթրիքի ժամանակ, երբ սատանան արդէն իսկ Սիմոնի որդի Իսկարիովտացի Յուդայի սրտի մէջ դրել էր, որ մատնի նրան,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Յիսուս իմացաւ, որ Հայրը ամէն բան իր ձեռքն էր յանձնել, եւ որ ինքը Աստծուց էր ելել եւ Աստծու մօտ էր գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Նա վեր կացաւ ընթրիքի սեղանից, մի կողմ դրեց զգեստները եւ մի սրբիչ վերցնելով՝ մէջքին կապեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Եւ ապա ջուր վերցնելով՝ ածեց կոնքի մէջ եւ սկսեց իր աշակերտների ոտքերը լուանալ եւ սրբել մէջքին կապած սրբիչով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Մօտեցաւ Սիմոն Պետրոսին, եւ սա ասաց նրան. «Տէ՛ր, դո՞ւ ես իմ ոտքերը լուանում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Յիսուս պատասխանեց նրան ու ասաց. «Ինչ որ ես անում եմ, դու հիմա չես իմանում, բայց յետոյ կ՚իմանաս»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Պետրոսը նրան ասաց. «Իմ ոտքերը յաւիտեան չես լուանայ»: Յիսուս պատասխանեց. «Եթէ քեզ չլուանամ, ինձ հետ մաս չունես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Սիմոն Պետրոսն ասաց նրան. «Տէ՛ր, ոչ թէ միայն իմ ոտքերը, այլեւ իմ ձեռքերն ու գլուխն էլ լուա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Յիսուս նրան ասաց. «Լուացուածին ուրիշ բան պէտք չէ, բայց միայն ոտքերը լուանալ, քանի որ ամբողջութեամբ մաքուր է. եւ դուք մաքուր էք, բայց ոչ բոլորդ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Քանի որ նա գիտէր նրան, ով իրեն մատնելու էր, դրա համար ասաց. «Բոլորդ չէ, որ մաքուր էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Եւ երբ նրանց ոտքերը լուաց, վերցրեց իր զգեստները եւ դարձեալ սեղան նստեց ու ասաց նրանց. «Գիտէ՞ք, թէ այդ ինչ արեցի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Դուք ինձ Վարդապետ եւ Տէր էք կոչում. եւ լաւ էք անում, քանի որ իսկապէս ե՛մ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'իսկ արդ, եթէ ես՝ Տէրս եւ Վարդապետս, լուացի ձեր ոտքերը, դուք էլ պարտաւոր էք միմեանց ոտքերը լուանալ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'որովհետեւ մի օրինակ տուի ձեզ, որ, ինչպէս ես ձեզ արեցի, դուք էլ նոյն ձեւով անէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, ծառան աւելի մեծ չէ, քան իր տէրը, եւ ոչ էլ ուղարկուածը՝ աւելի մեծ, քան նա, ով նրան ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Եթէ այս բաները գիտէք, առաւել երանելի էք, եթէ դրանք կատարէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ձեր բոլորի համար չէ, որ ասում եմ, որովհետեւ ես գիտեմ նրանց, որոնց ընտրել եմ, այլ որպէսզի կատարուի գրուածը, թէ՝ ով ինձ հետ հաց էր ուտում, իմ դէմ դարձաւ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'հէնց այժմուանից ասում եմ ձեզ, քանի դեռ չի եղել, որպէսզի, երբ որ լինի, հաւատաք, որ ես եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, ով որ ընդունի նրան, ում ես կ՚ուղարկեմ, ինձ է ընդունում, եւ ով ինձ է ընդունում, ընդունում է նրան, ով ինձ ուղարկեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Երբ Յիսուս այս բաներն ասաց, խռովուեց իր հոգում, վկայեց ու ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ ձեզնից մէկն ինձ մատնելու է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Աշակերտներն իրար էին նայում տարակուսելով, թէ ո՛ւմ մասին է ասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Եւ աշակերտներից մէկը, որին Յիսուս սիրում էր, նստել էր նրա մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Սիմոն Պետրոսը սրան ակնարկ արեց՝ հարցնելով, թէ այդ ո՛ւմ մասին է ասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Եւ սա Յիսուսի կրծքովն ընկաւ ու ասաց նրան. «Տէ՛ր, ո՞վ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Յիսուս պատասխանեց եւ ասաց. «Նա է, որի համար ես այս պատառը կը թաթախեմ եւ կը տամ իրեն»: Եւ թաթախելով պատառը՝ տալիս է Իսկարիովտացի Յուդային:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Եւ երբ նա պատառն առաւ, սատանան մտաւ նրա մէջ: Յիսուս նրան ասաց. «Հիմա ինչ որ անելու ես, իսկոյն արա՛»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Եւ սեղանակիցներից ոչ ոք չիմացաւ, թէ նա ինչի՛ համար այդ նրան ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'որովհետեւ ոմանք կարծում էին, թէ, քանի որ Յուդան էր գանձանակը պահում, Յիսուս նրան ասաց. «Գնի՛ր, ինչ որ մեզ տօնի ժամանակ պէտք է» եւ կամ՝ որ մի բան տայ աղքատներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Իսկ նա պատառը վերցնելով՝ իսկոյն դուրս ելաւ: Եւ գիշեր էր...');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Եւ երբ նա դուրս ելաւ, Յիսուս ասաց. «Այժմ մարդու Որդին փառաւորուեց, եւ Աստուած փառաւորուեց նրանով,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'քանի որ, եթէ Աստուած փառաւորուեց նրանով, Աստուած էլ նրան կը փառաւորի իրենով. եւ իսկոյն կը փառաւորի նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Որդեակնե՛րս, մի քիչ ժամանակ դեռ ձեզ հետ եմ. ինձ պիտի փնտռէք, եւ ինչպէս ասացի հրեաներին՝ ուր ես եմ գնում, դուք չէք կարող գալ, - այժմ այդ ձեզ էլ եմ ասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Նոր պատուիրան եմ տալիս ձեզ, որ սիրէք միմեանց. ինչպէս ես ձեզ սիրեցի, դուք էլ միմեա՛նց սիրեցէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Եթէ դուք միմեանց սիրէք, դրանով բոլորը պիտի իմանան, որ դուք իմ աշակերտներն էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Սիմոն Պետրոսը նրան ասաց. «Տէ՛ր, ո՞ւր ես գնում»: Յիսուս պատասխանեց. «Ուր ես եմ գնում, դու այժմ իմ յետեւից չես կարող գալ, բայց յետոյ կը գաս իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Պետրոսը նրան ասաց. «Տէ՛ր, ինչո՞ւ այժմ չեմ կարող քո յետեւից գալ. այժմուանից իսկ իմ կեանքը քեզ համար կը տամ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Յիսուս պատասխանեց. «Ինձ համար կեա՞նքդ կը տաս. ճշմարիտ, ճշմարիտ եմ ասում քեզ, աքաղաղը դեռ կանչած չի լինի, երբ դու երեք անգամ ինձ ուրացած կը լինես»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Ապա Յիսուս ասաց իր աշակերտներին. «Թող ձեր սրտերը չխռովուեն. հաւատացէ՛ք Աստծուն, հաւատացէ՛ք եւ ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Իմ Հօր տան մէջ բազում օթեւաններ կան. թէ չէ ես ձեզ կ՚ասէի, թէ գնում եմ ձեզ համար էլ տեղ պատրաստելու.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'եւ եթէ գնամ եւ ձեզ համար էլ տեղ պատրաստեմ, դարձեալ կը գամ եւ ձեզ կը վերցնեմ ինձ մօտ, որպէսզի, ուր ես լինեմ, դուք եւս այնտեղ լինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Եւ թէ ուր եմ գնում, այդ գիտէք, գիտէք եւ ճանապարհը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Թովմասը նրան ասաց. «Տէ՛ր, չգիտենք՝ ուր ես գնում, ուրեմն ինչպէ՞ս կարող ենք գիտենալ ճանապարհը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Յիսուս նրանց ասաց. «Ես եմ Ճանապարհը եւ Ճշմարտութիւնը եւ Կեանքը: Ոչ ոք չի գայ Հօր մօտ, եթէ ոչ՝ ինձանով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Եթէ ինձ ճանաչէիք, ապա կը ճանաչէիք եւ իմ Հօրը. այսուհետեւ կը ճանաչէք նրան. եւ տեսել էք նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Փիլիպպոսն ասաց նրան. «Տէ՛ր, Հօրը մեզ ցո՛յց տուր, եւ այդ բաւական է մեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Յիսուս նրան ասաց. «Այսքան ժամանակ ձեզ հետ եմ, Փիլիպպո՛ս, եւ ինձ չճանաչեցի՞ր. ով ինձ տեսաւ, տեսաւ Հօրը. իսկ դու ինչպէ՞ս ես ասում, թէ՝ Հօրը մեզ ցո՛յց տուր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Չե՞ս հաւատում, որ ես Հօր մէջ եմ, եւ Հայրը՝ իմ մէջ: Այն խօսքերը, որ ես ասում եմ ձեզ, ինքս ինձնից չեմ խօսում, այլ Հայրը, որ բնակւում է իմ մէջ, նա՛ է անում գործերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Հաւատացէ՛ք ինձ, որ ես Հօր մէջ եմ, եւ Հայրը՝ իմ մէջ. եթէ ոչ՝ գոնէ գործերի՛ համար հաւատացէք ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, թէ ով հաւատում է ինձ, ինքն էլ կ՚անի այն գործերը, որ ես եմ անում. եւ դրանցից աւելի մեծերը կ՚անի, որովհետեւ ես գնում եմ Հօր մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Եւ ինչ որ ուզէք իմ անունով, այն կ՚անեմ, որպէսզի Հայրը փառաւորուի Որդու միջոցով»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, '«Եթէ ինձ սիրում էք, կը պահէք իմ պատուիրանները.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'եւ ես պիտի աղաչեմ Հօրը, եւ նա մի այլ Մխիթարիչ պիտի տայ ձեզ, որպէսզի յաւիտեան ձեզ հետ բնակուի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Ճշմարտութեան Հոգին, որին այս աշխարհը չի կարող ընդունել, որովհետեւ նրան չի տեսնում եւ նրան չի ճանաչում, բայց դուք ճանաչում էք նրան, որովհետեւ ձեզ մօտ պիտի բնակուի եւ ձեր մէջ պիտի լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Ձեզ որբ չեմ թողնի, կը գամ ձեզ մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Մի փոքր ժամանակ եւս, եւ այս աշխարհը ինձ չի տեսնի, բայց դուք ինձ կը տեսնէք, որովհետեւ ես կենդանի եմ, եւ դուք կենդանի էք լինելու:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Այն օրը դուք պիտի իմանաք, որ ես իմ Հօր մէջ եմ, եւ դուք՝ իմ մէջ. ու ես՝ ձեր մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Ով իմ պատուիրաններն ընդունում եւ դրանք պահում է, նա՛ է, որ ինձ սիրում է. եւ ով ինձ սիրում է, պիտի սիրուի իմ Հօրից. ես էլ նրան պիտի սիրեմ եւ ինձ պիտի յայտնեմ նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Յուդան (ոչ Իսկարիովտացին) ասաց նրան. «Տէ՛ր, ինչպէ՞ս եղաւ, որ քեզ պիտի յայտնես մեզ եւ ոչ թէ աշխարհին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Յիսուս պատասխանեց եւ ասաց նրան. «Եթէ մէկը սիրում է ինձ, իմ խօսքը կը պահի, եւ իմ Հայրը նրան կը սիրի. եւ մենք նրա մօտ կը գանք ու նրա մօտ կ՚օթեւանենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Եւ ով ինձ չի սիրում, իմ խօսքերը չի պահում. եւ իմ խօսքը, որ լսում էք, իմը չէ, այլ՝ Հօրը, որ ինձ ուղարկեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Այս բաները ասացի ձեզ, մինչ ձեզ հետ եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Իսկ Մխիթարիչը՝ Սուրբ Հոգին, որին Հայրը կ՚ուղարկի իմ անունով, նա ձեզ ամէն բան կ՚ուսուցանի եւ ձեզ կը յիշեցնի այն ամէնը, ինչ ես ասացի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, '«Խաղաղութիւն եմ թողնում ձեզ, իմ խաղաղութիւնն եմ տալիս ձեզ. ձեզ չեմ տալիս այնպէս, ինչպէս այս աշխարհն է տալիս. ձեր սրտերը թող չխռովուեն, եւ չվախենաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Լսեցիք, որ ձեզ ասացի, թէ՝ գնում եմ եւ կը գամ ձեզ մօտ. եթէ ինձ սիրէիք, ապա դուք ուրախ պիտի լինէիք, որ ես Հօր մօտ եմ գնում, որովհետեւ իմ Հայրը մեծ է, քան ես:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Եւ հիմա ասացի ձեզ, երբ դեռ չի եղել, որպէսզի, երբ լինի, հաւատաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Այլեւս երկար չեմ խօսի ձեզ հետ. գալիս է աշխարհի իշխանը եւ իմ վրայ ոչ մի իշխանութիւն չունի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Իսկ որպէսզի աշխարհը գիտենայ, որ ես սիրում եմ Հօրը, այնպէս եմ անում, ինչպէս որ Հայրը պատուիրեց ինձ. դե՛հ, վե՛ր կացէք գնանք այստեղից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, '');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '«Ես եմ ճշմարիտ որթատունկը, եւ իմ Հայրը մշակն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Ամէն ճիւղ, որ իմ վրայ է եւ պտուղ չի տալիս, նա կտրում է այն. եւ այն ամէնը, որ պտուղ է տալիս, էտում է, որպէսզի առաւել եւս պտղաբեր լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Դուք արդէն իսկ մաքուր էք այն խօսքի համար, որ ձեզ ասացի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Մնացէ՛ք իմ մէջ, եւ ես՝ ձեր մէջ. ինչպէս ճիւղը, որ ինքն իրեն չի կարող պտուղ տալ, եթէ որթատունկի վրայ հաստատուած չլինի, նոյնպէս եւ դուք՝ եթէ իմ վրայ հաստատուած չլինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ես եմ որթատունկը, իսկ դուք՝ ճիւղերը: Ով բնակւում է իմ մէջ, եւ ես՝ նրա մէջ, նա շատ պտուղ է տալիս, որովհետեւ առանց ինձ ոչինչ անել չէք կարող:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Եթէ մէկը իմ վրայ հաստատուած չէ, նա ճիւղի նման դուրս կը նետուի եւ կը չորանայ, եւ այն կը հաւաքեն ու կրակը կը նետեն, եւ կ՚այրուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Եթէ իմ մէջ մնաք, եւ իմ խօսքերն էլ մնան ձեր մէջ, ինչ որ ուզենաք, խնդրեցէ՛ք Աստծուց, եւ ձեզ կը տրուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Իմ Հայրը փառաւորուած կը լինի նրանով, որ դուք շատ պտուղ տաք եւ իմ աշակերտները լինէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Ինչպէս իմ Հայրն ինձ սիրեց, ես էլ ձեզ սիրեցի. իմ սիրոյ մէջ հաստատո՛ւն մնացէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Եթէ իմ պատուիրանները պահէք, կը մնաք իմ սիրոյ մէջ, ինչպէս ես իմ Հօր պատուիրանները պահեցի եւ մնում եմ նրա սիրոյ մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Այս բաները ձեզ ասացի, որպէսզի իմ ուրախութիւնը ձեր մէջ լինի, եւ ձեր ուրախութիւնը լիակատար լինի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Այս է իմ պատուէրը. որ սիրէք միմեանց, ինչպէս որ ես սիրեցի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Աւելի մեծ սէր ոչ ոք չունի, քան այն, որ մէկն իր կեանքը տայ իր բարեկամների համար:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Դուք իմ բարեկամներն էք, եթէ անէք այն, ինչ ես ձեզ պատուիրում եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Այլեւս ձեզ ծառաներ չեմ կոչում, որովհետեւ ծառան չգիտէ, թէ տէրն ինչ է անում. այլ ձեզ բարեկամներ կոչեցի, որովհետեւ այն բոլորը, ինչ իմ Հօրից լսեցի, յայտնեցի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ոչ թէ դուք ինձ ընտրեցիք, այլ ես ձեզ ընտրեցի եւ ձեզ կարգեցի, որ դուք գնաք եւ պտղաբեր լինէք, եւ ձեր պտուղը մնայ, եւ ինչ էլ որ իմ անունով Հօրիցս խնդրէք, ձեզ տայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Այս եմ ձեզ պատուիրում. որ սիրէք միմեանց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '«Եթէ աշխարհը ձեզ ատում է, իմացէ՛ք, որ նախ ինձ է ատել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Եթէ այս աշխարհից լինէիք, աշխարհն արդէն, որպէս իրենը, ձեզ սիրած կը լինէր. բայց որովհետեւ այս աշխարհից չէք, այլ ես ձեզ ընտրեցի աշխարհից, դրա համար աշխարհը ձեզ ատում է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Յիշեցէ՛ք այն խօսքը, որ ես ձեզ ասացի, թէ՝ ծառան մեծ չէ, քան իր տէրը. եթէ ինձ հալածեցին, ապա ձեզ էլ կը հալածեն. եթէ իմ խօսքը պահեցին, ապա ձերն էլ կը պահեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Բայց նոյն բաները ձեզ պիտի անեն իմ անուան համար, որովհետեւ չեն ճանաչում նրան, ով ինձ ուղարկել է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Եթէ ես եկած եւ նրանց հետ խօսած չլինէի, նրանք որեւէ մեղք ունեցած չէին լինի. բայց հիմա իրենց մեղքի համար ոչ մի արդարացում չկայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Ով ինձ է ատում, ատում է եւ իմ Հօրը.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'եթէ ես նրանց մէջ արած չլինէի այն գործերը, որ ուրիշ ոչ ոք չարեց, նրանք որեւէ մեղք չէին ունենայ. բայց այժմ տեսան գործերը եւ ատեցին թէ՛ ինձ, թէ՛ իմ Հօրը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Եւ այդ նրա համար, որ կատարուի նրանց օրէնքում գրուած այն խօսքը, թէ՝ առանց պատճառի ինձ ատեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Բայց երբ գայ Մխիթարիչը, որին ես ձեզ կ՚ուղարկեմ Հօրից, Ճշմարտութեան Հոգին, որ ելնում է Հօրից, նա՛ կը վկայի իմ մասին.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'կը վկայէք եւ դուք, որովհետեւ սկզբից ինձ հետ էք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '«Այս բաները ասացի ձեզ, որպէսզի գայթակղութիւնից յետ մնաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Իրենց ժողովարաններից դուրս պիտի հանեն ձեզ. մինչեւ իսկ ժամանակը կը գայ, երբ, ով ձեզ սպանի, պիտի համարի, թէ Աստծուն պաշտամունք է մատուցում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Եւ այդ բանը պիտի անեն ձեզ էլ, որովհետեւ չճանաչեցին ո՛չ Հօրը եւ ո՛չ էլ ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Սակայն այս բաները ձեզ ասացի, որպէսզի երբ ժամանակը գայ, յիշէք, որ ես ձեզ ասել եմ: Այս բաները սկզբից ձեզ չասացի, քանի որ ձեզ հետ էի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, '«Բայց այժմ ես գնում եմ ինձ ուղարկողի մօտ, եւ ձեզնից ոչ ոք ինձ չի հարցնում, թէ՝ ո՞ւր ես գնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Բայց որովհետեւ ձեզ այս բաներն ասացի, տրտմութիւնը լցրեց ձեր սրտերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Բայց ես ճշմարիտն եմ ասում ձեզ. լաւ է ձեզ համար, որ ես գնամ. որովհետեւ, եթէ ես չգնամ, Մխիթարիչը ձեզ մօտ չի գայ. իսկ եթէ գնամ, նրան կ՚ուղարկեմ ձեզ մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Եւ նա գալով՝ պիտի ապացուցի աշխարհին, որ նա սխալ է մեղքի եւ արդարութեան հարցում եւ դատաստանի հարցում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Մեղքի հարցում՝ որովհետեւ ինձ չեն հաւատում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'արդարութեան հարցում՝ որովհետեւ իմ Հօր մօտ եմ գնում, եւ այլեւս ինձ չէք տեսնի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'դատաստանի հարցում՝ որովհետեւ այս աշխարհի իշխանը դատապարտուած է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Դեռ շատ բաներ ունեմ ձեզ ասելու, բայց այժմ չէք կարող տանել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Երբ որ գայ նա՝ Ճշմարտութեան Հոգին, ամենայն ճշմարտութեամբ կ՚առաջնորդի ձեզ. որովհետեւ ոչ թէ ինքն իրենից կը խօսի, այլ ինչ լսի, այն կը խօսի. եւ գալիք բաների մասին կը պատմի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Նա ինձ պիտի փառաւորի, որովհետեւ ինչ որ առնում է ինձանից, կը յայտնի ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Ամէն ինչ որ Հայրն ունի, իմն է. դրա համար ձեզ ասացի, թէ ինչ որ առնում է ինձանից, կը յայտնի ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '«Մի փոքր ժամանակ, եւ այլեւս ինձ չէք տեսնի. եւ ապա մի քիչ եւս՝ եւ ինձ նորից կը տեսնէք. եւ ես գնում եմ Հօր մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Աշակերտներից ոմանք միմեանց ասում էին. «Ի՞նչ է այս, որ մեզ ասում է, թէ՝ մի քիչ եւս, եւ ինձ չէք տեսնի. եւ դարձեալ, թէ՝ մի քիչ եւս, եւ ինձ կը տեսնէք եւ թէ՝ ես գնում եմ իմ Հօր մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Եւ ասում էին. «Ի՞նչ է այն «մի քիչ եւս» -ը. չենք հասկանում, թէ ինչ է խօսում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Յիսուս իմացաւ, որ ուզում են իրեն հարց տալ, եւ նրանց ասաց. «Դրա՞ համար էիք միմեանց հարցնում, որ ասացի, թէ՝ մի փոքր ժամանակ, եւ ինձ չէք տեսնի. եւ դարձեալ՝ մի քիչ եւս, եւ կը տեսնէք ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ դուք պիտի լաք եւ պիտի ողբաք, իսկ աշխարհը ուրախ պիտի լինի. դուք պիտի տրտմէք, բայց ձեր տրտմութիւնը ուրախութեան պիտի փոխուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Երբ կինը ծննդաբերում է, նրա համար տրտմութիւն է, որովհետեւ նրա ժամը հասած է. բայց երբ մանկանը ծնի, այլեւս չի յիշում նեղութիւնը՝ ուրախութեան պատճառով, որ աշխարհում մի մարդ ծնուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Դուք էլ այժմ տրտմութիւն ունէք, բայց ես դարձեալ ձեզ պիտի տեսնեմ, ու ձեր սրտերը ուրախ պիտի լինեն. եւ ձեր ուրախութիւնը ոչ ոք ձեզնից չպիտի խլի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Եւ այն օրը ինձ ոչինչ չպիտի հարցնէք: Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ, ինչ իմ անունով իմ Հօրից ուզէք, պիտի տայ ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Մինչեւ հիմա իմ անունով ոչինչ չխնդրեցիք. խնդրեցէ՛ք եւ պիտի ստանաք, որպէսզի ձեր ուրախութիւնը լիակատար լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, '«Այս բաները առակներով ասացի ձեզ. պիտի գայ ժամանակ, երբ այլեւս առակներով չպիտի խօսեմ ձեզ հետ, այլ յայտնապէս Հօր մասին պիտի պատմեմ ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Այն օրը իմ անունով պիտի խնդրէք. եւ ձեզ չեմ ասում, թէ՝ ե՛ս պիտի աղաչեմ Հօրը ձեզ համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'քանի որ Հայրը ինքն իսկ սիրում է ձեզ. որովհետեւ դուք սիրեցիք ինձ եւ հաւատացիք, որ ես Աստծուց ելայ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ելայ Հօրից եւ եկայ աշխարհ. դարձեալ թողնում եմ աշխարհը եւ գնում Հօր մօտ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Աշակերտները նրան ասացին. «Ահա հիմա բացայայտ ես խօսում եւ ոչ մի առակ չես ասում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Հիմա գիտենք, որ ամէն ինչ գիտես, եւ պէտք չկայ, որ մէկը քեզ բան հարցնի. դրա համար հաւատում ենք, որ Աստծուց ելար»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Յիսուս պատասխանեց նրանց եւ ասաց. «Այժմ հաւատո՞ւմ էք.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'ահա պիտի գայ ժամանակ եւ արդէն իսկ եկել է, երբ պիտի ցրուէք իւրաքանչիւրդ իր տեղը, եւ ինձ միայնակ պիտի թողնէք. սակայն ես միայնակ չեմ, որովհետեւ Հայրն ինձ հետ է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Այս բաները ասացի ձեզ, որպէսզի ինձնով խաղաղութիւն ունենաք: Այստեղ, աշխարհում նեղութիւն պիտի ունենաք, սակայն քաջալերուեցէ՛ք, որովհետեւ ես յաղթեցի աշխարհին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Յիսուս երբ այս բաները խօսեց, աչքերը երկինք բարձրացրեց եւ ասաց. «Հա՛յր, հասել է ժամը, փառաւորի՛ր քո Որդուն, որպէսզի քո Որդին էլ քեզ փառաւորի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'ինչպէս որ նրան իշխանութիւն տուեցիր բոլոր մարդկանց վրայ, որպէսզի յաւիտենական կեանք տայ այն ամենքին, որ նրան տուեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Յաւիտենական կեանքը այս է. որ ճանաչեն քեզ միակ ճշմարիտ Աստուած, նաեւ Յիսուս Քրիստոսին, որ դու ուղարկեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ես քեզ փառաւորեցի երկրի վրայ. լրացրի այն գործը, որն ինձ տուիր, որ անեմ.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'եւ դու այժմ փառաւորի՛ր ինձ, Հա՛յր, քեզ մօտ եղող այն փառքով, որ ունէի քեզ մօտ՝ նախքան աշխարհի լինելը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Քո անունը յայտնեցի այն մարդկանց, որոնց ինձ տուեցիր աշխարհից. նրանք քոնն էին, եւ ինձ տուեցիր նրանց, ու նրանք քո խօսքը պահեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Հիմա իմացան, որ այն ամէնը, ինչ ինձ տուիր, ես նրանց տուեցի.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'եւ նրանք ընդունեցին ու ճշմարտութեամբ ճանաչեցին, որ ես քո մօտից ելայ. եւ նրանք հաւատացին, որ դո՛ւ ուղարկեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Արդ, ես նրանց համար եմ աղաչում. ես չեմ աղաչում աշխարհի համար, այլ՝ նրանց համար, որոնց դու ինձ տուեցիր, որովհետեւ նրանք քոնն են:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Եւ ինչ որ իմն է, բոլորը քոնն է, եւ ինչ որ քոնն է, այն իմն է, ու ես նրանց մէջ փառաւորուած եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Եւ ես այլեւս աշխարհի մէջ չեմ, իսկ նրանք աշխարհի մէջ են. եւ ես դէպի քեզ եմ գալիս: Սո՛ւրբ Հայր, պահի՛ր նրանց քո անունով, որով ինձ տուեցիր, որպէսզի լինեն մի, ինչպէս մենք էլ մի ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Մինչ աշխարհում նրանց հետ էի, ես պահում էի նրանց քո անունով, որով ինձ տուեցիր. եւ ես պահեցի. ու նրանցից ոչ ոք չկորաւ, բացի կորստեան դատապարտուած մարդուց, որպէսզի գրուածը կատարուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Բայց հիմա քեզ մօտ եմ գալիս եւ այս բաները խօսում եմ աշխարհում, որպէսզի նրանք իրենց մէջ իմ լիակատար ուրախութիւնն ունենան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ես նրանց տուի քո խօսքը, եւ աշխարհը նրանց ատեց, որովհետեւ նրանք աշխարհից չեն, ինչպէս ես էլ աշխարհից չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Այս աղաչում եմ ոչ թէ նրա համար, որ նրանց վերացնես աշխարհից, այլ որպէսզի նրանց պահես չարից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Նրանք այս աշխարհից չեն, ինչպէս ես էլ աշխարհից չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Սրբացրո՛ւ նրանց քո ճշմարտութեամբ, որովհետեւ քո խօսքը ճշմարտութիւն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Ինչպէս դու ինձ ուղարկեցիր աշխարհ, ես էլ նրանց ուղարկեցի աշխարհ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Եւ ես ինձ սրբացնում եմ նրանց համար, որպէսզի նրանք էլ սրբացուեն ճշմարտութեամբ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Սակայն միայն նրանց համար չէ, որ աղաչում եմ, այլեւ նրանց խօսքի միջոցով բոլոր ինձ հաւատացողների համար,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'որպէսզի ամէնքը մի լինեն. ինչպէս դու, Հա՛յր, իմ մէջ, եւ ես՝ քո մէջ, որպէսզի նրանք էլ մեր մէջ լինեն, եւ որպէսզի աշխարհն էլ հաւատայ, թէ դո՛ւ ուղարկեցիր ինձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Եւ ես տուեցի նրանց այն փառքը, որ դու ինձ տուեցիր, որպէսզի մի լինեն, ինչպէս եւ մենք մի ենք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ես՝ նրանց մէջ, եւ դու՝ իմ մէջ, որպէսզի կատարեալ լինեն միութեան մէջ: Եւ աշխարհը գիտենայ, որ դո՛ւ ուղարկեցիր ինձ. եւ ես սիրեցի նրանց, ինչպէս դու ինձ սիրեցիր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Հա՛յր, ում որ ինձ տուիր, կամենում եմ, որ, ուր ես եմ, նրանք էլ ինձ հետ լինեն, որպէսզի տեսնեն իմ փառքը, որ դու ինձ տուեցիր, քանի որ ինձ սիրեցիր՝ նախքան աշխարհի լինելը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Արդա՛ր Հայր, թէեւ աշխարհը քեզ չճանաչեց, բայց ես քեզ ճանաչեցի, եւ իմացան նրանք, որ դու ես ինձ ուղարկել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Եւ ճանաչեցրի նրանց քո անունը ու պիտի ճանաչեցնեմ, որպէսզի այն սէրը, որով ինձ սիրեցիր, նրանց մէջ լինի, եւ ես՝ նրանց մէջ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Երբ Յիսուս այսպէս խօսեց, աշակերտներով հանդերձ ելաւ գնաց Կեդրոնի ձորի միւս կողմը. այնտեղ մի պարտէզ կար, ուր մտան ինքը եւ իր աշակերտները:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Յուդան էլ, որ նրան մատնելու էր, գիտէր այն տեղը, որովհետեւ Յիսուս ու իր աշակերտները շատ անգամ այնտեղ հաւաքուել էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Եւ Յուդան իր հետ վերցնելով գունդը եւ պահակներ՝ ուղարկուած քահանայապետներից ու փարիսեցիներից, այնտեղ եկաւ ջահերով, լապտերներով ու զէնքերով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Իսկ Յիսուս իր վրայ եկող այս ամէնը տեսնելով՝ դուրս ելաւ ու նրանց ասաց. «Ո՞ւմ էք փնտռում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Նրան պատասխանեցին՝ Յիսուս Նազովրեցուն: Յիսուս նրանց ասաց՝ ես եմ: Նրանց հետ էր եւ Յուդան, որ մատնում էր նրան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Երբ Յիսուս ասաց՝ ես եմ, յետ-յետ գնացին եւ գետին ընկան:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Դարձեալ նրանց հարցրեց՝ ո՞ւմ էք փնտռում: Նրանք ասացին՝ Յիսուս Նազովրեցուն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Յիսուս նրանց պատասխանեց. «Ձեզ ասացի, թէ՝ ես եմ. արդ, եթէ ինձ էք փնտռում, նրանց թո՛յլ տուէք գնալ».');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'որպէսզի կատարուի խօսքը, որ ասել էր, թէ՝ նրանց, որոնց ինձ տուեցիր, նրանցից եւ ոչ մէկին չկորցրի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Իսկ Սիմոն Պետրոսը, որովհետեւ սուր ունէր, քաշեց այն եւ զարկեց քահանայապետի ծառային ու նրա աջ ականջը կտրեց: Եւ այն ծառայի անունը Մաղքոս էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Յիսուս Պետրոսին ասաց. «Այդ սուրդ նորից իր պատեանի մէջ դիր. այն բաժակը, որ Հայրն է ինձ տուել, չպիտի՞ խմեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Իսկ գունդը, հազարապետը եւ հրեաների պահակները բռնեցին Յիսուսին եւ կապեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Եւ նախ նրան տարան Աննայի մօտ, որը Կայիափայի՝ այդ տարուայ քահանայապետի աներն էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Սա այն Կայիափան էր, որ հրեաներին խրատ տուեց, թէ աւելի լաւ է, որ ժողովրդի համար մէկ մարդ մեռնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Եւ Յիսուսի յետեւից գնում էին Սիմոն Պետրոսը եւ միւս աշակերտը: Եւ քանի որ այդ աշակերտը քահանայապետին ծանօթ էր, Յիսուսի հետ մտաւ քահանայապետի տան գաւիթը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Իսկ Պետրոսը կանգնել էր դռան մօտ, դուրսը: Միւս աշակերտը, որ ծանօթ էր քահանայապետին, դուրս ելաւ, դռնապանին ասաց եւ Պետրոսին ներս մտցրեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Այն աղջիկը, որ դռնապանն էր, Պետրոսին ասաց. «Մի՞թէ դու էլ այդ մարդու աշակերտներից ես»: Եւ նա ասաց՝ ո՛չ, չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Այնտեղ կային ծառաներ եւ պահակներ, որոնք խարոյկ էին արել եւ տաքանում էին, քանի որ ցուրտ էր: Պետրոսն էլ նրանց հետ կանգնել էր ու տաքանում էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Իսկ քահանայապետը հարց տուեց Յիսուսին նրա աշակերտների եւ վարդապետութեան մասին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Յիսուս նրան պատասխանեց. «Ես բացայայտ ասացի բոլորին. ես միշտ ուսուցանել եմ ժողովարանում եւ տաճարի մէջ, ուր հաւաքւում էին բոլոր հրեաները. եւ ծածուկ ոչինչ չեմ խօսել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Ինձ ինչո՞ւ ես հարցուփորձ անում. հարցուփորձ արա նրանց, ովքեր լսել են, թէ ես նրանց հետ ինչ եմ խօսել. ահա՛, նրանք գիտեն, թէ ինչ եմ ասել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Երբ նա այս ասաց, այնտեղ կանգնած պահակներից մէկը մի ապտակ տուեց Յիսուսին ու ասաց. «Այդպէ՞ս ես պատասխան տալիս քահանայապետին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Եւ Յիսուս նրան ասաց. «Եթէ վատ խօսեցի, վկայի՛ր վատի մասին, իսկ եթէ լաւ՝ ինձ ինչո՞ւ ես խփում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Եւ Աննան նրան կապած ուղարկեց Կայիափա քահանայապետի մօտ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Եւ Սիմոն Պետրոսը այնտեղ կանգնած էր ու տաքանում էր. նրան ասացին. «Մի՞թէ դու էլ նրա աշակերտներից ես»: Նա ուրացաւ եւ ասաց՝ ո՛չ, չեմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Եւ քահանայապետի ծառաներից մէկը՝ նրա՛ ազգականը, որի ականջը Պետրոսը կտրել էր, ասաց. «Չէ՞ որ ես ինքս տեսայ քեզ նրա հետ պարտէզում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Պետրոսը դարձեալ ուրացաւ. եւ իսկոյն մի աքաղաղ կանչեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Կայիափայի տնից Յիսուսին տարան կուսակալի ապարանքը: Այգաբաց էր: Բայց նրանք ապարանք չմտան, որպէսզի չպղծուեն եւ որպէսզի զատկական ընթրիքը կարողանան ուտել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Ուստի Պիղատոսն ինքը դուրս ելաւ նրանց մօտ եւ ասաց. «Այս մարդու մասին ի՞նչ ամբաստանութիւն էք ներկայացնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Նրան պատասխանեցին եւ ասացին. «Եթէ այս մարդը չարագործ չլինէր, ապա նրան քո ձեռքը չէինք մատնի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Պիղատոսը նրանց ասաց. «Դուք վերցրէ՛ք նրան եւ ձեր օրէնքի համաձայն նրան դատեցէ՛ք»: Հրեաները նրան ասացին. «Մեզ համար որեւէ մէկին սպանել օրինաւոր չէ»');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, '(որպէսզի կատարուի Յիսուսի այն խօսքը, որ նա ասաց՝ նշելով, թէ ինչ մահով էր ինքը մեռնելու):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Պիղատոսը դարձեալ ապարանք մտաւ, կանչեց Յիսուսին եւ ասաց նրան. «Դո՞ւ ես հրեաների թագաւորը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Յիսուս պատասխանեց. «Դու քեզնի՞ց ես այդ ասում, թէ ուրիշներ իմ մասին քեզ ասացին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Պիղատոսը պատասխանեց. «Միթէ ես էլ հրեա՞յ եմ. քո ազգը եւ քահանայապետները մատնեցին քեզ իմ ձեռքը. դու ի՞նչ ես արել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Յիսուս պատասխանեց. «Իմ թագաւորութիւնը այս աշխարհից չէ. եթէ իմ թագաւորութիւնը այս աշխարհից լինէր, իմ հետեւորդները կը մարտնչէին արդէն, որպէսզի հրեաների ձեռքը չմատնուեմ. բայց, արդ, իմ թագաւորութիւնը այստեղից չէ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Պիղատոսը նրան ասաց. «Թէ որ այդպէս է, ուրեմն դու թագաւո՞ր ես»: Յիսուս նրան պատասխանեց. «Դու ես ասում, որ թագաւոր եմ, բայց ես դրա համար իսկ ծնուել եմ եւ դրա համար իսկ եկել եմ աշխարհ, որպէսզի ճշմարտութեան համար վկայեմ: Ամէն մարդ, որ ճշմարտութիւնից է« իմ ձայնը լսում է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Պիղատոսը նրան ասաց. «Ի՞նչ է ճշմարտութիւնը»: Երբ այս ասաց, դարձեալ դուրս ելաւ, հրեաների մօտ, ու ասաց նրանց. «Ես նրա մէջ ոչ մի յանցանք չեմ գտնում:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Բայց դուք սովորութիւն ունէք, որ զատկին ձեզ համար մի բանտարկեալ արձակեմ. արդ, ուզո՞ւմ էք, որ ձեզ համար արձակեմ հրեաների թագաւորին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Բոլորը աղաղակեցին եւ ասացին՝ ո՛չ դրան, այլ՝ Բարաբբային: Եւ այն Բարաբբան աւազակ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Այն ժամանակ Պիղատոսը հրամայեց Յիսուսին վերցնել եւ նրան գանակոծել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Իսկ զինուորները փշէ պսակ շինելով՝ դրեցին նրա գլխին ու նրան ծիրանի զգեստ հագցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Եւ գալիս էին նրա մօտ ու ասում՝ ողջո՛յն, հրեաների՛ արքայ: Եւ նրան ապտակում էին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Պիղատոսը դարձեալ դուրս ելաւ ու ասաց նրանց. «Ահա նրան դուրս, ձեզ մօտ եմ բերում, որպէսզի իմանաք, թէ ես նրա մէջ որեւէ յանցանք չեմ գտնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Յիսուս դուրս ելաւ. եւ փշէ պսակ ունէր եւ ծիրանի զգեստ: Եւ նրանց ասաց. «Ահա ձեր մարդը՝ ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Երբ քահանայապետներն ու պահակները նրան տեսան, աղաղակ բարձրացրին եւ ասացին. «Խա՛չը հանիր, խա՛չը հանիր դրան»: Պիղատոսը նրանց ասաց. «Դո՛ւք առէք նրան ձեր մէջ եւ ինքնե՛րդ խաչը հանեցէք, քանի որ ես դրա մէջ որեւէ յանցանք չեմ գտնում»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Հրեաները նրան պատասխանեցին. «Մենք օրէնք ունենք, եւ ըստ մեր օրէնքի պէտք է նա մեռնի, որովհետեւ իրեն Աստծու Որդի դարձրեց»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Երբ Պիղատոսը այս խօսքերը լսեց, աւելի եւս վախեցաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Դարձեալ, մի անգամ եւս մտաւ ապարանքը եւ Յիսուսին ասաց՝ որտեղի՞ց ես դու: Եւ Յիսուս նրան պատասխան չտուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Պիղատոսը նրան ասաց. «Ինձ հետ չե՞ս խօսում, չգիտե՞ս, որ իշխանութիւն ունեմ քեզ խաչը հանելու. եւ իշխանութիւն ունեմ քեզ ազատ արձակելու»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Յիսուս պատասխանեց. «Դու իմ վրայ ոչ մի իշխանութիւն էլ չէիր ունենայ, եթէ քեզ ի վերուստ տրուած չլինէր. դրա համար էլ, ով ինձ քո ձեռքը մատնեց, նրա մեղքը աւելի մեծ է»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Սրանից յետոյ Պիղատոսը ուզում էր նրան ազատ արձակել: Իսկ հրեաները աղաղակում էին ու ասում.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, '«Եթէ դրան արձակես, կայսրին բարեկամ չես: Ամենայն ոք, որ ինքն իրեն թագաւոր է կոչում, հակառակ է կայսեր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Իսկ երբ Պիղատոսը այս խօսքերը լսեց, Յիսուսին դուրս բերեց, նստեց բեմի վրայ, այն տեղը, որ Քարայատակ էր կոչւում, իսկ եբրայերէն՝ Կապպաթա:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Զատկի նախօրէն էր, եւ կէսօրուայ մօտ էր: Եւ նա հրեաներին ասաց. «Ահա ձեր թագաւորը՝ ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Իսկ նրանք աղաղակում էին. «Վերացրո՛ւ մեր միջից, վերացրո՛ւ մեր միջից եւ խա՛չը հանիր նրան»: Պիղատոսը նրանց ասաց. «Ես ձեր թագաւորին խա՞չը հանեմ»: Քահանայապետները պատասխանեցին. «Չունենք մենք այլ թագաւոր, բացի կայսրից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Այն ժամանակ Յիսուսին յանձնեց նրանց ձեռքը, որպէսզի խաչը հանուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Եւ նրանք առան Յիսուսին եւ տարան: Եւ խաչափայտը նա ինքն էր վերցրել եւ բարձրացնում էր այն տեղը, որի անունն էր Գագաթ, իսկ եբրայերէն կոչւում էր Գողգոթա,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'որտեղ եւ խաչը հանեցին նրան ու նրա հետ երկու ուրիշների՝ այս եւ այն կողմից, իսկ մէջտեղում՝ Յիսուսին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Պիղատոսը մի տախտակ էլ գրեց եւ դրեց խաչի վրայ. եւ գրուած էր. «Յիսուս Նազովրեցի՝ հրեաների թագաւոր»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Այդ տախտակը հրեաներից շատերը կարդացին, որովհետեւ այն տեղը, ուր Յիսուս խաչուեց, քաղաքին մօտ էր (եւ գրուած էր եբրայերէն, լատիներէն եւ յունարէն):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Հրեաների քահանայապետները Պիղատոսին ասացին. «Մի՛ գրիր՝ հրեաների թագաւոր, այլ՝ ինչ նա ասաց՝ թագաւոր եմ հրեաների»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Պիղատոսը պատասխանեց. «Ինչ գրեցի, գրեցի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Իսկ զինուորները, երբ Յիսուսին խաչը հանեցին, վերցրին նրա զգեստները եւ չորս մաս արեցին. իւրաքանչիւր զինուորի՝ մէկ մաս: Իսկ քանի որ պատմուճանը առանց կարի էր, վերեւից ներքեւ ամբողջովին հիւսած շուրջանակի,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'ուստի միմեանց ասացին. «Այդ չպատռտենք, այլ դրա վրայ վիճակ գցենք, ում որ ելնի», որպէսզի կատարուի գրուածը, որ ասում է. «Իմ զգեստները բաժանեցին իրար մէջ եւ իմ պատմուճանի վրայ վիճակ գցեցին»: Զինուորներն այս բանն արեցին: ուստի միմեանց ասացին. «Այդ չպատռտենք, այլ դրա վրայ վիճակ գցենք, ում որ ելնի», որպէսզի կատարուի գրուածը, որ ասում է. «Իմ զգեստները բաժանեցին իրար մէջ եւ իմ պատմուճանի վրայ վիճակ գցեցին»: Զինուորներն այս բանն արեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Իսկ Յիսուսի խաչի մօտ կանգնած էին նրա մայրը եւ նրա մօրաքոյրը՝ Կղէոպասի կին Մարիամը եւ Մարիամ Մագդաղենացին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Երբ Յիսուս տեսաւ մօրը եւ այն աշակերտին, որ մօտ էր կանգնած, որին նա սիրում էր, մօրն ասաց. «Ո՛վ կին, ահա՛ քո որդին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Ապա աշակերտին ասաց. «Ահա՛ քո մայրը»: Եւ այդ պահից աշակերտը նրան իր մօտ առաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Այնուհետեւ Յիսուս, գիտենալով, թէ ահա ամէն ինչ կատարուած է, որպէսզի կատարուի գրուածը, ասաց՝ ծարաւ եմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Եւ այնտեղ քացախով լի մի աման կար. զինուորները լեղախառն քացախով մի սպունգ թրջեցին եւ այն դրին եղէգի ծայրին ու մօտեցրին նրա բերանին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Երբ Յիսուս լեղախառն քացախը բերանն առաւ, ասաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, '«Ամէն ինչ կատարուած է»: Եւ գլուխը կախելով՝ հոգին աւանդեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Իսկ քանի որ ուրբաթ էր, որպէսզի մարմինները չմնան խաչի վրայ մինչեւ շաբաթ օրը, - որովհետեւ այն շաբաթը տօնական մեծ օր էր, - հրեայ առաջնորդները Պիղատոսին աղաչեցին, որ կոտրեն նրանց սրունքները եւ վերցնեն նրանց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Զինուորները եկան եւ առաջինի սրունքները կոտրեցին, նոյնպէս եւ միւսինը, որ նրա հետ խաչ էր հանուել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Բայց երբ եկան Յիսուսի մօտ եւ տեսան, որ նա արդէն մեռած էր, նրա սրունքները չկոտրեցին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'այլ զինուորներից մէկը տէգով խոցեց նրա կողը, եւ իսկոյն արիւն եւ ջուր ելաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Եւ ով այս բանը տեսաւ, վկայեց. եւ նրա վկայութիւնը ճշմարիտ է, եւ նա գիտէ, որ ճշմարիտ է ասում, որպէսզի դուք էլ հաւատաք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Այս պատահեց, որպէսզի կատարուի գրուածը, թէ՝ նրա ոսկորը չպիտի փշրուի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Եւ դարձեալ միւս գրուածն ասում է. «Պիտի նայեն նրան, ում խոցեցին»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Այնուհետեւ Յովսէփը, որ արիմաթիացի էր եւ Յիսուսի թաքուն աշակերտն էր հրեաների վախի պատճառով, Պիղատոսին աղաչեց, որ Յիսուսի մարմինը վերցնի: Եւ Պիղատոսը հրաման տուեց. ուստի Յովսէփն ու Նիկոդեմոսը եկան եւ նրան վերցրին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Նիկոդեմոսը, որ առաջին անգամ գիշերով Յիսուսի մօտ էր եկել, բերեց մօտ հարիւր լիտր զմուռս՝ հալուէի հետ խառնուած:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Վերցրին Յիսուսի մարմինը եւ պատեցին կտաւներով՝ խնկերով հանդերձ, ինչպէս որ հրեաների սովորութիւնն էր՝ պատել: Եւ այն տեղում, ուր նա խաչուեց, պարտէզ կար. եւ այդ պարտէզում՝ մի նոր գերեզման, որի մէջ երբեք որեւէ մէկը չէր դրուած: Եւ քանի որ գերեզմանը մօտ էր, հրեաների ուրբաթի պատճառով, այնտե՛ղ դրեցին Յիսուսի մարմինը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Եւ կիրակի օրը Մարիամ Մագդաղենացին առաւօտեան արշալոյսին գերեզման է գալիս եւ տեսնում է, որ քարը գերեզմանի դռնից վերցուած է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Ապա վազում է եւ գալիս Սիմոն Պետրոսի եւ այն միւս աշակերտի մօտ, որին Յիսուս սիրում էր, ու նրանց ասում է. «Տիրոջը վերցրել են գերեզմանից, եւ չգիտենք, թէ ո՛ւր են դրել նրան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Պետրոսը եւ միւս աշակերտը ելան եւ գերեզման էին գալիս:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Երկուսով միասին վազում էին, բայց միւս աշակերտը առաջ անցաւ Պետրոսից եւ աւելի շուտ վազեց ու առաջինը գերեզման եկաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Եւ կռանալով՝ տեսաւ, որ կտաւները այնտեղ էին, բայց ներս չմտաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Եկաւ նաեւ Սիմոն Պետրոսը, որ նրա յետեւից էր գալիս. մտաւ գերեզմանը եւ տեսաւ, որ կտաւները այնտեղ էին,');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'եւ վարշամակը, որ նրա գլխին էր, միւս կտաւների հետ չէր, այլ առանձին ծալուած՝ մի կողմ էր:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Այն ժամանակ մտաւ եւ միւս աշակերտը, որ աւելի առաջ էր եկել գերեզման. տեսաւ ու հաւատաց.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'քանի որ դեռ չէին հասկացել գրուածքը, թէ՝ մեռելներից պէտք է յարութիւն առնի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Աշակերտները, վերադառնալով, գնացին իրենց տեղերը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Բայց Մարիամը կանգնած էր գերեզմանի դուրսը ու լաց էր լինում. եւ մինչ դեռ լաց էր լինում, կռացաւ դէպի գերեզմանը');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'եւ տեսաւ երկու հրեշտակներ՝ սպիտակների մէջ, որոնք նստել էին՝ մէկը՝ սնարին, եւ միւսը՝ ոտքերի մօտ, այնտեղ, ուր Յիսուսի մարմինն էր եղել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Եւ նրան ասացին. «Ո՛վ կին, ինչո՞ւ ես լալիս»: Նա նրանց ասաց. «Որովհետեւ իմ Տիրոջը գերեզմանից վերցրել են, եւ չգիտեմ՝ նրան ուր են դրել»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Երբ այս ասաց, դէպի յետեւի կողմը դարձաւ եւ տեսաւ Յիսուսին, որ կանգնած էր. բայց չէր իմանում, թէ Յիսուսն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Յիսուս նրան ասաց. «Ո՛վ կին, ինչո՞ւ ես լալիս, ո՞ւմ ես փնտռում»: Նրան այնպէս թուաց, թէ պարտիզպանն է. եւ ասաց նրան. «Տէ՛ր, եթէ դու ես նրան վերցրել, ասա՛ ինձ՝ ուր ես դրել նրան, որպէսզի ես նրան վերցնեմ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Յիսուս նրան ասաց՝ Մարիա՛մ: Եւ նա դարձաւ ու եբրայերէն նրան ասաց՝ Ռաբբունի՛ (որ թարգմանւում է՝ վարդապետ):');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Յիսուս նրան ասաց. «Ինձ մի՛ մօտեցիր, քանի որ դեռ Հօրս մօտ չեմ բարձրացել. ուրեմն գնա՛ դու իմ եղբայրների մօտ ու նրանց ասա՛, որ ես բարձրանում եմ դէպի իմ Հայրը եւ ձեր Հայրը, դէպի իմ Աստուածը եւ ձեր Աստուածը»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Մարիամ Մագդաղենացին եկաւ ու աշակերտներին պատմեց, թէ ինքը Տիրոջը տեսել է, եւ նա իրեն այս բաներն է ասել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Նոյն կիրակի օրուայ երեկոյեան աշակերտները հաւաքուած էին մի տան մէջ, որի դռները փակուած էին հրեաների վախի պատճառով: Յիսուս եկաւ, կանգնեց նրանց մէջտեղն ու նրանց ասաց. «Խաղաղութի՜ւն ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Այս ասելով՝ նրանց ցոյց տուեց իր ձեռքերը եւ կողը. եւ աշակերտներն ուրախացան, երբ տեսան Տիրոջը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Նա դարձեալ նրանց ասաց. «Խաղաղութի՜ւն ձեզ. ինչպէս իմ Հայրն ինձ ուղարկեց, ես էլ ուղարկում եմ ձեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Երբ այս ասաց, նրանց վրայ փչեց եւ ասաց. «Առէ՛ք Սուրբ Հոգին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Եթէ մէկի մեղքերը ներէք, նրանց ներուած կը լինի. եթէ մէկի մեղքերը չներէք, ներուած չի լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Իսկ Թովմասը՝ Տասներկուսից մէկը՝ Երկուորեակ կոչուածը, նրանց հետ չէր, երբ Յիսուս եկաւ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Միւս աշակերտները նրան ասացին, թէ՝ Տիրոջը տեսանք: Եւ նա նրանց ասաց. «Եթէ չտեսնեմ նրա ձեռքերի վրայ մեխերի նշանը եւ իմ մատները մեխերի տեղերը չդնեմ ու իմ ձեռքը նրա կողի մէջ չխրեմ, չեմ հաւատայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Ութ օր յետոյ աշակերտները դարձեալ ներսում էին. եւ Թովմասը՝ նրանց հետ: Յիսուս եկաւ փակ դռներով, կանգնեց մէջտեղ ու ասաց՝ խաղաղութի՜ւն ձեզ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Ապա Թովմասին ասաց. «Բե՛ր քո մատները եւ դի՛ր այստեղ ու տե՛ս իմ ձեռքերը. եւ բե՛ր քո ձեռքը ու մտցրո՛ւ իմ կողի մէջ. անհաւատ մի՛ եղիր, այլ՝ հաւատացեալ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Թովմասը պատասխան տուեց ու նրան ասաց՝ Տէ՛ր իմ եւ Աստուա՛ծ իմ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Յիսուս նրան ասաց. «Որովհետեւ դու ինձ տեսար, հաւատացիր. երանի՜ նրանց, որոնք չեն տեսել եւ սակայն կը հաւատան»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Իր աշակերտների առաջ Յիսուս բազում այլ նշաններ էլ արեց, որոնք այս գրքում գրուած չեն:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Այլ այսքանը գրուեց, որ դուք հաւատաք, թէ Յիսուս Քրիստոսն է՝ Աստծու Որդին. նաեւ՝ որպէսզի հաւատաք ու նրա անունով յաւիտենական կեանքն ընդունէք:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Սրանից յետոյ Յիսուս դարձեալ իրեն յայտնեց իր աշակերտներին Տիբերիայի ծովեզերքի մօտ. եւ յայտնեց այսպէս.');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'միասին էին Սիմոն Պետրոսը, Թովմասը՝ Երկուորեակ կոչուածը, Նաթանայէլը, որ Գալիլիայի Կանա քաղաքից էր, Զեբեդէոսի որդիները եւ աշակերտներից ուրիշ երկու հոգի:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Սիմոն Պետրոսը նրանց ասաց. «Գնում եմ ձուկ որսալու»: Նրան ասացին. «Մենք էլ ենք գալիս քեզ հետ»: Գնացին եւ նաւակը մտան. եւ այդ գիշեր ոչինչ չբռնեցին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Երբ առաւօտ եղաւ, Յիսուս կանգնած էր ծովի եզերքին. բայց աշակերտները չիմացան, որ Յիսուսն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Յիսուս նրանց ասաց. «Տղանե՛ր, ուտելու բան չունէ՞ք»: Նրան պատասխանեցին՝ ո՛չ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Նրանց ասաց. «Ուռկանը գցեցէ՛ք նաւակի աջ կողմը եւ կը գտնէք»: Գցեցին. եւ ձկների բազմութիւնից չէին կարողանում այն դուրս քաշել:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Այն աշակերտը, որին Յիսուս սիրում էր, Պետրոսին ասաց՝ Տէրն է: Երբ Սիմոն Պետրոսը լսեց, թէ Տէրն է, հագուստը վրան գցեց, քանի որ մերկ էր, եւ իրեն նետեց ծովի մէջ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Միւս աշակերտներն էլ նաւակով եկան. եւ քանի որ ցամաքից հեռու չէին, այլ երկու հարիւր կանգունի չափ միայն, քաշում էին ուռկանը ձկներով հանդերձ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Երբ ցամաք ելան, տեսան վառուած ածուխի մի կրակատեղ՝ մի ձուկ նրա վրայ եւ հաց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Յիսուս նրանց ասաց. «Բերէ՛ք այն ձկներից, որ դուք հիմա որսացիք»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Սիմոն Պետրոսը նաւակ մտաւ եւ ցամաք քաշեց ուռկանը, որ լիքն էր հարիւր յիսուներեք մեծ-մեծ ձկներով:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Թէեւ այնչափ բան կար, բայց ուռկանը չպատռուեց:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Յիսուս նրանց ասաց՝ եկէք ճաշեցէ՛ք: Եւ աշակերտներից ոչ ոք չէր համարձակւում հարցնել, թէ՝ դու ո՞վ ես, որովհետեւ գիտէին, որ Տէրն է:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Եկաւ Յիսուս, առաւ հացը եւ տուեց նրանց. նոյնպէս եւ ձուկը:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Այս երրորդ անգամն էր, որ Յիսուս երեւաց իր աշակերտներին՝ մեռելներից յարութիւն առնելուց յետոյ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Եւ երբ ճաշեցին, Յիսուս Սիմոն Պետրոսին ասաց. «Սիմո՛ն, որդի՛ Յովնանի, սիրո՞ւմ ես ինձ աւելի, քան դրանք»: Սա ասաց նրան. «Այո՛, Տէ՛ր, եւ դու գիտես, որ սիրում եմ քեզ»: Նրան ասաց՝ արածացրո՛ւ իմ գառներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Դարձեալ ասաց նրան. «Սիմո՛ն, որդի՛ Յովնանի, սիրո՞ւմ ես ինձ»: Նա ասաց նրան. «Այո՛, Տէ՛ր, եւ դու գիտես, որ սիրում եմ քեզ»: Նրան ասաց՝ արածացրո՛ւ իմ ոչխարներին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Երրորդ անգամ նրան ասաց. «Սիմո՛ն, որդի՛ Յովնանի, սիրո՞ւմ ես ինձ»: Պետրոսը տխրեց, որ երրորդ անգամ իրեն ասաց, թէ՝ սիրո՞ւմ ես ինձ: Ու նրան պատասխանեց. «Տէ՛ր, դու ամէն ինչ գիտես. դու ինքդ ճանաչում ես բոլորին եւ գիտես, թէ սիրում »մ ք»զ»: Յիսուս նրան ասաց. «Արածացրո՛ւ իմ ոչխարն»րին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Ճշմարիտ, ճշմարիտ եմ ասում քեզ, որ մինչ դու երիտասարդ էիր, ինքդ էիր գօտիդ կապում եւ գնում էիր՝ ուր եւ կամենում էիր. սակայն երբ ծերանաս, ձեռքերդ վեր կը բարձրացնես, եւ ուրիշները քեզ գօտի կը կապեն ու կը տանեն՝ ուր չես կամ»նայ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Այս ասաց, նշելով, թէ ինչ մահով նա պիտի փառաւորի Աստծուն: Եւ երբ այս ասաց, աւելացրեց՝ արի՛ իմ յետեւից:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Պետրոսը դարձաւ եւ տեսաւ, որ այն աշակերտը, ում Յիսուս սիրում էր, գալիս է յետեւից. նա, որ ընկել էր նրա կրծքովն ու ասել. «Տէ՛ր, ո՞վ է, որ մատնելու է քեզ»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Պետրոսը, նրան տեսնելով, ասաց Յիսուսին. «Տէ՛ր, իսկ սա ի՞նչ կը լինի»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Յիսուս նրան ասաց. «Եթէ ես կամենում եմ, որ դա ապրի, մինչեւ որ ես գամ, այդ քեզ ի՞նչ հոգ, դու արի՛ իմ յետեւից»:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Եւ այս խօսքը տարածուեց եղբայրների մէջ. եւ կարծեցին, թէ այն աշակերտը չպիտի մեռնի: Բայց Յիսուս նրան չասաց, թէ չպիտի մեռնի, այլ թէ՝ ես կամենում եմ, որ դա ապրի, մինչեւ որ ես գամ:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Այս աշակերտն է, որ վկայում է այս բաների մասին, որ եւ գրեց իսկ դրանք. եւ գիտենք, որ նրա վկայութիւնը ճշմարիտ է: Բայց ուրիշ շատ բաներ էլ կան, որ Յիսուս արեց, որոնք, եթէ մէկը մէկ առ մէկ գրած լինէր, կարծում եմ, թէ աշխարհն իսկ բաւական չէր լինի պարփակելու այդ գրքերը, եթէ դրանք գրուած լինէին:');
INSERT INTO `ArmEastern_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, '');
